pub fn parseCommand(arg: ?[]const u8) !Command {
    const value = arg orelse return .help;
    if (std.mem.eql(u8, value, "version")) return .version;
    if (std.mem.eql(u8, value, "init")) return .init;
    if (std.mem.eql(u8, value, "stats")) return .stats;
    if (std.mem.eql(u8, value, "store-info")) return .store_info;
    if (std.mem.eql(u8, value, "rebuild-text")) return .rebuild_text;
    if (std.mem.eql(u8, value, "backup")) return .backup;
    if (std.mem.eql(u8, value, "restore")) return .restore;
    if (std.mem.eql(u8, value, "migrate-store-v2")) return .migrate_store_v2;
