    if (std.mem.eql(u8, value, "schema-apply")) return .schema_apply;
    if (std.mem.eql(u8, value, "schema-validate")) return .schema_validate;
    if (std.mem.eql(u8, value, "schema-migrate")) return .schema_migrate;
    if (std.mem.eql(u8, value, "import-metaknow-replay")) return .import_metaknow_replay;
    if (std.mem.eql(u8, value, "import-jsonl")) return .import_jsonl;
    if (std.mem.eql(u8, value, "export-jsonl")) return .export_jsonl;
    if (std.mem.eql(u8, value, "apply")) return .apply;
    if (std.mem.eql(u8, value, "import-markdown")) return .import_markdown;
    if (std.mem.eql(u8, value, "export-markdown")) return .export_markdown;
    if (std.mem.eql(u8, value, "import-md-ast")) return .import_md_ast;
    if (std.mem.eql(u8, value, "import-md-doc")) return .import_md_doc;
    if (std.mem.eql(u8, value, "render-md-doc")) return .render_md_doc;
    if (std.mem.eql(u8, value, "gc-md-orphans")) return .gc_md_orphans;
    if (std.mem.eql(u8, value, "get")) return .get;
    if (std.mem.eql(u8, value, "inspect")) return .get;
