    if (std.mem.eql(u8, value, "append-node-version")) return .append_node_version;
    if (std.mem.eql(u8, value, "set-property")) return .set_property;
    if (std.mem.eql(u8, value, "set-uint-property")) return .set_uint_property;
    if (std.mem.eql(u8, value, "set-node-property")) return .set_node_property;
    if (std.mem.eql(u8, value, "set-edge-property")) return .set_edge_property;
    if (std.mem.eql(u8, value, "node-versions")) return .node_versions;
    if (std.mem.eql(u8, value, "node-latest")) return .node_latest;
    if (std.mem.eql(u8, value, "govern-node")) return .govern_node;
