    if (std.mem.eql(u8, value, "segment-query")) return .segment_query;
    if (std.mem.eql(u8, value, "segment-query-explain")) return .segment_query_explain;
    if (std.mem.eql(u8, value, "export-segment-bundle")) return .export_segment_bundle;
    if (std.mem.eql(u8, value, "gc-segment-bundle")) return .gc_segment_bundle;
    if (std.mem.eql(u8, value, "bench")) return .bench;
    if (std.mem.eql(u8, value, "bench-md-doc-edit")) return .bench_md_doc_edit;
    if (std.mem.eql(u8, value, "maintain")) return .maintain;
    if (std.mem.eql(u8, value, "compact-edges")) return .compact_edges;
    if (std.mem.eql(u8, value, "compact-edge-segments")) return .compact_edge_segments;
    if (std.mem.eql(u8, value, "maintain-edge-segments")) return .maintain_edge_segments;
