        .migrate_store_v2 => {
            const parsed = try parseMigrateStoreV2Args(args);
            // Resolve aliases before acquiring either lock.  If target is a
            // symlink/dotted spelling of source, taking source and then target
            // would recursively acquire the same lock and wait until timeout
            // instead of rejecting the destructive overlap immediately.
            try validateMigrateStoreV2PathRelationships(allocator, io, parsed);
            const canonical_target_lock_path = try canonicalProspectivePath(allocator, io, parsed.target_path);
            defer allocator.free(canonical_target_lock_path);
            const source_lock = try CliStoreLock.acquire(allocator, io, parsed.source_path);
            defer source_lock.deinit();
            // Close the preflight-to-lock race as far as path-based APIs can:
            // re-resolve after source exclusion, while acquiring the target
            // lock at the already canonical prospective location. If the raw
            // target spelling is swapped to source after this check, the
            // inner migrateStoreV2 validation rejects it before any write;
            // it cannot redirect this second lock back inside source.
            try validateMigrateStoreV2PathRelationships(allocator, io, parsed);
            const target_lock = try CliStoreLock.acquireAdjacent(
                allocator,
                io,
                canonical_target_lock_path,
                store_migration_publish_lock_suffix,
            );
            defer target_lock.deinit();
            const start_ns = monotonicNs(io);
            const result = try migrateStoreV2(allocator, io, parsed);
            const elapsed_ns = elapsedNs(io, start_ns);
            try writer.print(
                "migrate_store_v2 source={s} target={s} dry_run={} verified={} nodes_scanned={} nodes_written={} edges_scanned={} edges_written={} tombstone_nodes_skipped={} legacy_props_extracted={} legacy_text_repaired={} empty_text_physical_placeholders={} node_properties_written={} edge_properties_written={} task_statuses_written={} legacy_closed_tasks_converted={} backup={s} text_warmed={} marker_cleanup_pending={} elapsed_ns={}\n",
                .{
                    parsed.source_path,
                    parsed.target_path,
                    @intFromBool(parsed.dry_run),
                    @intFromBool(result.verified),
                    result.nodes_scanned,
                    result.nodes_written,
                    result.edges_scanned,
                    result.edges_written,
                    result.tombstone_nodes_skipped,
                    result.legacy_props_extracted,
                    result.legacy_text_repaired,
                    result.empty_text_physical_placeholders,
                    result.node_properties_written,
                    result.edge_properties_written,
                    result.task_statuses_written,
                    result.legacy_closed_tasks_converted,
                    parsed.backup_path orelse "",
                    @intFromBool(result.text_warmed),
                    @intFromBool(result.marker_cleanup_pending),
                    elapsed_ns,
                },
            );
        },
