        },
        .ensure_node => {
            // 原子 find-or-create(Linus:客户端两次 CLI 模拟事务必有竞态窗口——lookup 与 create
            // 各持一次锁,间隙里另一进程可插入同名节点 → 重复 project 节点、记忆永久分裂)。
            // 本命令把 find + create 收进**同一把 CliStoreLock**;find 走 lookupNodesByTextLimited
            // (server-side 原始 text 精确索引,无 TSV 转义失配问题)。
            const parsed = try parseDbArgs(allocator, io, args, 2, 2, std.math.maxInt(usize), true);
            const add_args = try parseAddNodeArgs(parsed.rest);
            // 幂等脚枪封死:lookup 按 add_args.text,create 存 nodeVisibleTextFromGovernanceArgs
            // 产物——若 --name/--summary/--retrieval-hints 使两者不等,幂等即碎(每次 created=1)。
            // ensure-node 只做"kind+text 定身份"的 find-or-create,拒收会改可见文本的参数。
            if (add_args.name != null or add_args.summary != null or add_args.retrieval_hints != null) return error.Unsupported;
            const governance_args = ParsedNodeTextGovernanceArgs{
                .kind_label = add_args.kind_label,
                .text = add_args.text,
                .schema_type = add_args.schema_type,
                .recorded_ns = persistentNowNs(io),
            };
            try validateNodeWriteGranularity(governance_args);
            const node_text = try nodeVisibleTextFromGovernanceArgs(allocator, governance_args);
            defer if (node_text.ptr != add_args.text.ptr) allocator.free(node_text);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            var effective_schema = try loadEffectiveSchemaRegistry(allocator, io, store, add_args.schema_path);
            defer effective_schema.deinit();
            const kind = try parseNodeKindWithSchemaPolicy(add_args.kind_label, effective_schema.registry, effective_schema.enforce_application_schema);
            const candidate_limit = currentGenerationLookupCandidateLimit(1);
            var matches = store.lookupNodesByTextLimited(allocator, kind, add_args.text, candidate_limit) catch |err| switch (err) {
                error.FileNotFound, error.InvalidRecord => retry: {
                    try store.repairPersistentIndexesFromLog();
                    break :retry try store.lookupNodesByTextLimited(allocator, kind, add_args.text, candidate_limit);
                },
                else => |e| return e,
            };
            defer {
                for (matches.items) |*node| node.deinit(allocator);
                matches.deinit(allocator);
            }
            for (matches.items) |*node| {
                if (!try nodeIsCurrentGeneration(store, node.id)) continue;
                if (node.kind == .task) try ensureTaskStatusProperty(allocator, store, node.id);
                try writer.print("node {} created=0\n", .{node.id.toInt()});
                return;
            }
            const id = try store.addNode(kind, node_text);
            try applyNodeGovernanceProperties(allocator, store, id, governance_args, null);
            if (kind == .task) try ensureTaskStatusProperty(allocator, store, id);
            try writer.print("node {} created=1\n", .{id.toInt()});
        },
        .schema_scope => {
            // 项目级本体:声明 <schema_type> 只在 --project 列出的 project 下可用(严格精确无继承)。
            // find-or-create 政策节点(concept + schema_type=schema_scope + name=<schema_type>),
            // 写 scope_projects(project node-id JSON 数组)+ enforce。--project 接受 name 或 id。
            const parsed = try parseDbArgs(allocator, io, args, 2, 1, std.math.maxInt(usize), true);
            if (parsed.rest.len < 1) return error.InvalidRecord;
            const scope_type = parsed.rest[0];
            // 政策节点自身/project 自身不该被当内容治理:拒绝给保留类型声明 scope。
            if (std.mem.eql(u8, scope_type, "schema_scope") or std.mem.eql(u8, scope_type, "project")) return error.InvalidRecord;

            var project_specs = std.ArrayList([]const u8).empty;
            defer project_specs.deinit(allocator);
            var enforce_value: []const u8 = "report";
            var if_absent = false; // --if-absent:仅当政策不存在时创建,不覆盖已有 scope(auto-scope 用)
            var ai: usize = 1;
            while (ai < parsed.rest.len) : (ai += 1) {
                const a = parsed.rest[ai];
                if (std.mem.eql(u8, a, "--project")) {
                    ai += 1;
                    if (ai >= parsed.rest.len) return error.InvalidRecord;
                    // 逗号分隔多个 name|id
                    var it = std.mem.splitScalar(u8, parsed.rest[ai], ',');
                    while (it.next()) |spec| {
                        const s = std.mem.trim(u8, spec, " \t");
                        if (s.len > 0) try project_specs.append(allocator, s);
                    }
                } else if (std.mem.eql(u8, a, "--enforce")) {
                    ai += 1;
                    if (ai >= parsed.rest.len) return error.InvalidRecord;
                    const ev = parsed.rest[ai];
                    if (!std.mem.eql(u8, ev, "block") and !std.mem.eql(u8, ev, "report")) return error.InvalidRecord;
                    enforce_value = ev;
                } else if (std.mem.eql(u8, a, "--if-absent")) {
                    if_absent = true;
                } else return error.InvalidRecord;
            }
            if (project_specs.items.len == 0) return error.InvalidRecord;

            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();

            // --if-absent:政策已存在则直接返回,不覆盖已有 scope/enforce(auto-scope"引入即隔离"用:
            // 首次引入建 scope,后续不重置——防 auto-scope 把手动扩展过的 scope 冲掉)。
            if (if_absent) {
                const existing_text = try std.fmt.allocPrint(allocator, "schema_scope:{s}", .{scope_type});
                defer allocator.free(existing_text);
                var ex = try store.lookupNodesByTextLimited(allocator, .concept, existing_text, currentGenerationLookupCandidateLimit(1));
                defer {
                    for (ex.items) |*n| n.deinit(allocator);
                    ex.deinit(allocator);
                }
                for (ex.items) |*n| {
                    if (!try nodeIsCurrentGeneration(store, n.id)) continue;
                    try writer.print("schema_scope node={} created=0 type={s} unchanged=1\n", .{ n.id.toInt(), scope_type });
                    return;
                }
            }

            // 解析每个 --project spec(name 或 id)→ project node-id。
            var project_ids = std.ArrayList(u64).empty;
            defer project_ids.deinit(allocator);
            for (project_specs.items) |spec| {
                const pid = try resolveProjectSpec(allocator, store, spec);
                // 去重
                var dup = false;
                for (project_ids.items) |x| {
                    if (x == pid) {
                        dup = true;
                        break;
                    }
                }
                if (!dup) try project_ids.append(allocator, pid);
            }

            // 构造 scope_projects JSON 数组。
            var json_buf = std.ArrayList(u8).empty;
            defer json_buf.deinit(allocator);
            try json_buf.append(allocator, '[');
            for (project_ids.items, 0..) |pid, idx| {
                if (idx > 0) try json_buf.append(allocator, ',');
                var num_buf: [20]u8 = undefined;
                const num_str = std.fmt.bufPrint(&num_buf, "{d}", .{pid}) catch unreachable;
                try json_buf.appendSlice(allocator, num_str);
            }
            try json_buf.append(allocator, ']');

            // find-or-create 政策节点:身份 = concept + text="schema_scope:<schema_type>"。
            const policy_text = try std.fmt.allocPrint(allocator, "schema_scope:{s}", .{scope_type});
            defer allocator.free(policy_text);
            const candidate_limit = currentGenerationLookupCandidateLimit(1);
            var matches = try store.lookupNodesByTextLimited(allocator, .concept, policy_text, candidate_limit);
            defer {
                for (matches.items) |*n| n.deinit(allocator);
                matches.deinit(allocator);
            }
            var policy_id: ?core.NodeId = null;
            for (matches.items) |*n| {
                if (!try nodeIsCurrentGeneration(store, n.id)) continue;
                policy_id = n.id;
                break;
            }
            var created: u8 = 0;
            const owner_id = if (policy_id) |pid| pid else blk: {
                const nid = try store.addNode(.concept, policy_text);
                created = 1;
                break :blk nid;
            };
            const owner: storage.PropertyOwner = .{ .node = owner_id };
            try store.setStringProperty(allocator, owner, "schema_type", "schema_scope");
            try store.setStringProperty(allocator, owner, "name", scope_type);
            try store.setStringProperty(allocator, owner, "scope_projects", json_buf.items);
            try store.setStringProperty(allocator, owner, "enforce", enforce_value);
            try writer.print("schema_scope node={} created={} type={s} projects={s} enforce={s}\n", .{ owner_id.toInt(), created, scope_type, json_buf.items, enforce_value });

            // PM review:声明时立即回显当前违规者(不要求另跑全店 governance)。
            var dangling: u64 = 0;
            var allowed = try schemaScopeAllowedSet(allocator, store, project_ids.items, &dangling);
            defer allowed.deinit();
            var violations: u64 = 0;
            var vit = try store.nodeRecordsIterator(null);
            defer vit.deinit();
            while (try vit.next(allocator)) |stored_node| {
                var node = stored_node;
                defer node.deinit(allocator);
                if (isDeletedNodeTombstone(node)) continue;
                if (node.kind == .project) continue;
                const st = try store.getNodeStringProperty(allocator, node.id, "schema_type");
                defer if (st) |s| allocator.free(s);
                if (st == null or !std.mem.eql(u8, st.?, scope_type)) continue;
                if (allowed.contains(node.id.toInt())) continue;
                violations += 1;
                if (violations <= 20) {
                    try writer.print("  violation node={} not in scope\n", .{node.id.toInt()});
                }
            }
            try writer.print("schema_scope_violations={} dangling_projects={}\n", .{ violations, dangling });
        },
        .ensure_anchor => {
            // project 三锚(乙方案):task(任务 DAG 执行面,唯一)/ docs(可渲染 markdown 文档面)/
            // memory(记忆面,本体随理解演进)。find-or-create 收进同一把 CliStoreLock —— 唯一性
            // 由程序原语保证,不靠图校验器,也不靠 LLM 自觉(与 ensure-node project 同款纪律)。
            // 崩溃窗口(Linus C,已知非全原子):addNode→setProperty→addEdge 三步,首步后崩
            // = 无边孤儿 concept(下次 find 扫不到会再建)。窗口极窄;孤儿由 governance 的
            // isolated_nodes 兜出,gc 清理。别把本命令当全原子事务。
            const parsed = try parseDbArgs(allocator, io, args, 2, 2, 2, true);
            const project_id = try parseNodeIdArg(parsed.rest[0]);
            const anchor = parseAnchorType(parsed.rest[1]) orelse return error.InvalidArgument;
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            var proj = (try store.readNodeById(allocator, project_id)) orelse return core.Error.NotFound;
            defer proj.deinit(allocator);
            if (proj.kind != .project) return core.Error.InvalidId;

            // find:project 的 contain 孩子里按 schema_type 认锚(segment-aware)。
            var children = try collectContainChildIds(allocator, store, project_id);
            defer children.deinit(allocator);
            for (children.items) |cid| {
                const st = try store.getNodeStringProperty(allocator, core.NodeId.fromInt(cid), "schema_type");
                defer if (st) |s| allocator.free(s);
                if (st != null and std.mem.eql(u8, st.?, anchor.schemaType())) {
                    if (anchor.nodeKind() == .task) try ensureTaskStatusProperty(allocator, store, core.NodeId.fromInt(cid));
                    try writer.print("node {} created=0\n", .{cid});
                    return;
                }
            }
            const id = try store.addNode(anchor.nodeKind(), anchor.defaultText());
            try store.setNodeStringProperty(allocator, id, "schema_type", anchor.schemaType());
            if (anchor.nodeKind() == .task) try ensureTaskStatusProperty(allocator, store, id);
            _ = try dag.addEdgeCheckedWithPersistentStore(allocator, store, project_id, .contain, id, .{});
            try writer.print("node {} created=1\n", .{id.toInt()});
        },
        .add_node => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 2, std.math.maxInt(usize), true);
            const add_args = try parseAddNodeArgs(parsed.rest);
            const governance_args = ParsedNodeTextGovernanceArgs{
                .kind_label = add_args.kind_label,
                .text = add_args.text,
                .schema_type = add_args.schema_type,
                .name = add_args.name,
                .summary = add_args.summary,
                .retrieval_hints = add_args.retrieval_hints,
                .recorded_ns = persistentNowNs(io),
            };
            try validateNodeWriteGranularity(governance_args);
            const node_text = try nodeVisibleTextFromGovernanceArgs(allocator, governance_args);
            defer if (node_text.ptr != add_args.text.ptr) allocator.free(node_text);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            var effective_schema = try loadEffectiveSchemaRegistry(allocator, io, store, add_args.schema_path);
            defer effective_schema.deinit();
            const kind = try parseNodeKindWithSchemaPolicy(add_args.kind_label, effective_schema.registry, effective_schema.enforce_application_schema);
            const id = try store.addNode(kind, node_text);
            try applyNodeGovernanceProperties(allocator, store, id, governance_args, null);
            if (kind == .task) try ensureTaskStatusProperty(allocator, store, id);
            try writer.print("node {}\n", .{id.toInt()});
        },
        .update_node => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 3, std.math.maxInt(usize), true);
            const update_args = try parseUpdateNodeArgs(parsed.rest);
            const node_id = try parseNodeIdArg(update_args.node_id);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            var effective_schema = try loadEffectiveSchemaRegistry(allocator, io, store, update_args.schema_path);
            defer effective_schema.deinit();
            const requested_kind = try parseNodeKindWithSchemaPolicy(update_args.kind_label, effective_schema.registry, effective_schema.enforce_application_schema);
            var existing_node = (try store.readNodeById(allocator, node_id)) orelse return core.Error.NotFound;
            defer existing_node.deinit(allocator);
            const legacy_task_close = existing_node.kind == .task and (requested_kind == .verification or requested_kind == .fix);
            if (existing_node.kind == .task and requested_kind != .task and !legacy_task_close) return error.InvalidTaskTransition;
            const kind: core.NodeKind = if (legacy_task_close) .task else requested_kind;
            const existing_schema_type = if (legacy_task_close) try store.getNodeStringProperty(allocator, node_id, "schema_type") else null;
            defer if (existing_schema_type) |value| allocator.free(value);
            const effective_schema_type: ?[]const u8 = if (legacy_task_close and update_args.schema_type != null and
                (std.mem.eql(u8, update_args.schema_type.?, "verification") or std.mem.eql(u8, update_args.schema_type.?, "fix")))
                existing_schema_type orelse "task"
            else
                update_args.schema_type;
            const recorded_ns = persistentNowNs(io);
            const recorded_ns_u64 = try u128ToU64(recorded_ns);
            if (legacy_task_close) {
                _ = try validateTaskCloseTransition(
                    allocator,
                    store,
                    existing_node,
                    .completed,
                    null,
                    false,
                    recorded_ns_u64,
                );
            } else if (kind == .task) {
                // A non-task may carry an unrelated application `status`, or
                // stale task audit fields.  Validate the prospective task
                // lifecycle before the copy-on-write rewrite: discovering the
                // conflict after updateNode commits would leave a failed
                // command with a partially converted node.
                try validateTaskLifecycleFieldsForRewrite(allocator, store, node_id, recorded_ns_u64);
            }
            const lifecycle = try taskLifecycleMetadataForUpdate(allocator, store, existing_node, requested_kind, recorded_ns);
            const task_event_metadata = try taskEventMetadataForUpdate(allocator, store, existing_node, kind, update_args.schema_type, recorded_ns);
            defer if (task_event_metadata) |metadata| metadata.deinit(allocator);
            const governance_args = ParsedNodeTextGovernanceArgs{
                .kind_label = update_args.kind_label,
                .text = update_args.text,
                .schema_type = effective_schema_type,
                .name = update_args.name,
                .summary = update_args.summary,
                .retrieval_hints = update_args.retrieval_hints,
                .recorded_ns = recorded_ns,
                .task_created_ns = lifecycle.task_created_ns,
                // The legacy task-close bridge must publish completion time,
                // terminal status and lease expiry in one delta frame below.
                // Writing the timestamp as part of governance first creates
                // a crash window containing an open task with terminal audit
                // metadata, which import/export correctly reject.
                .task_completed_ns = if (legacy_task_close) null else lifecycle.task_completed_ns,
                .task_event_metadata = task_event_metadata,
            };
            try validateNodeWriteGranularity(governance_args);
            const node_text = try nodeVisibleTextFromGovernanceArgs(allocator, governance_args);
            defer if (node_text.ptr != update_args.text.ptr) allocator.free(node_text);
            const store_bytes_before = try storeDirBytes(allocator, io, parsed.db_path);
            if (existing_node.kind == .task or kind == .task) {
                var deferred_based_on = try readMetaknowDeferredBasedOnSidecarForwardPairs(allocator, io, parsed.db_path);
                defer deferred_based_on.deinit(allocator);
                const result = try store.updateNode(node_id, kind, node_text);
                try applyNodeGovernanceProperties(allocator, store, node_id, governance_args, null);
                if (legacy_task_close) {
                    // Backward-compatible bridge for old clients.  The target
                    // kind is interpreted as a lifecycle transition; the
                    // node itself remains a task.  New clients use task-close.
                    _ = try store.upsertPropertiesBatch(allocator, &.{
                        .{ .owner = .{ .node = node_id }, .key = "task_completed_ns", .value = .{ .uint = try u128ToU64(lifecycle.task_completed_ns orelse return error.InvalidTaskTransition) } },
                        .{ .owner = .{ .node = node_id }, .key = task.status_property, .value = .{ .string = @tagName(task.Status.completed) } },
                        .{ .owner = .{ .node = node_id }, .key = task.claim_expires_ns_property, .value = .{ .uint = 0 } },
                    });
                } else if (kind == .task) {
                    try ensureTaskStatusProperty(allocator, store, node_id);
                }
                try restoreMetaknowDeferredBasedOnSidecar(allocator, store, &deferred_based_on);
                try writer.print(
                    "updated node={} rewrite_mode=copy_on_write_full_store store_bytes_before={} nodes_rewritten={} edges_rewritten={} edges_removed={} text_rewarmed=0 text_index_current=0\n",
                    .{ node_id.toInt(), store_bytes_before, result.nodes_rewritten, result.edges_rewritten, result.edges_removed },
                );
            } else {
                const new_node_id = try store.addNode(kind, node_text);
                try applyNodeGovernanceProperties(allocator, store, new_node_id, governance_args, null);
                const edge_id = try dag.addEdgeCheckedWithPersistentStore(allocator, store, node_id, .deprecated_by, new_node_id, .{});
                try writer.print(
                    "updated node={} new={} edge={} rel=deprecated_by update_mode=append_only_version store_bytes_before={} text_rewarmed=0 text_index_current=0\n",
                    .{ node_id.toInt(), new_node_id.toInt(), edge_id.toInt(), store_bytes_before },
                );
            }
        },
        .append_node_version => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 3, std.math.maxInt(usize), true);
            const update_args = try parseUpdateNodeArgs(parsed.rest);
            const old_node_id = try parseNodeIdArg(update_args.node_id);
            const governance_args = ParsedNodeTextGovernanceArgs{
                .kind_label = update_args.kind_label,
                .text = update_args.text,
                .schema_type = update_args.schema_type,
                .name = update_args.name,
                .summary = update_args.summary,
                .retrieval_hints = update_args.retrieval_hints,
                .recorded_ns = persistentNowNs(io),
            };
            try validateNodeWriteGranularity(governance_args);
            const node_text = try nodeVisibleTextFromGovernanceArgs(allocator, governance_args);
            defer if (node_text.ptr != update_args.text.ptr) allocator.free(node_text);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            var effective_schema = try loadEffectiveSchemaRegistry(allocator, io, store, update_args.schema_path);
            defer effective_schema.deinit();
            const kind = try parseNodeKindWithSchemaPolicy(update_args.kind_label, effective_schema.registry, effective_schema.enforce_application_schema);
            var existing_node = (try store.readNodeById(allocator, old_node_id)) orelse return core.Error.NotFound;
            existing_node.deinit(allocator);
            const store_bytes_before = try storeDirBytes(allocator, io, parsed.db_path);
            const new_node_id = try store.addNode(kind, node_text);
            try applyNodeGovernanceProperties(allocator, store, new_node_id, governance_args, null);
            if (kind == .task) try ensureTaskStatusProperty(allocator, store, new_node_id);
            const edge_id = try dag.addEdgeCheckedWithPersistentStore(allocator, store, old_node_id, .deprecated_by, new_node_id, .{});
            try writer.print(
                "appended node_version old={} new={} edge={} rel=deprecated_by append_only=1 store_bytes_before={} text_rewarmed=0 text_index_current=0\n",
                .{ old_node_id.toInt(), new_node_id.toInt(), edge_id.toInt(), store_bytes_before },
            );
        },
        .set_property => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 4, 6, true);
            const schema_arg = try parseOptionalTrailingSchemaArg(parsed.rest, 4, 4);
            const set_args = try parseSetPropertyArgs(schema_arg.positionals);
            try validateParsedStringProperty(set_args.owner, set_args.key, set_args.value);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            var effective_schema = try loadEffectiveSchemaRegistry(allocator, io, store, schema_arg.schema_path);
            defer effective_schema.deinit();
            try validateSchemaStringPropertyWrite(allocator, store, effective_schema.registry, set_args.owner, set_args.key, set_args.value, effective_schema.enforce_application_schema);
            try store.setStringProperty(allocator, set_args.owner, set_args.key, set_args.value);
            const owner_id = switch (set_args.owner) {
                .node => |node_id| node_id.toInt(),
                .edge => |edge_id| edge_id.toInt(),
            };
            try writer.print("property owner={s} id={} key={s} bytes={}\n", .{ set_args.owner_label, owner_id, set_args.key, set_args.value.len });
        },
