        .govern_node => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 1, std.math.maxInt(usize), true);
            const govern_args = try parseGovernNodeArgs(parsed.rest);
            const node_id = try parseNodeIdArg(govern_args.node_id);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            var existing_node = (try store.readNodeById(allocator, node_id)) orelse return core.Error.NotFound;
            defer existing_node.deinit(allocator);
            const kind_label = try nodeKindNameAlloc(allocator, existing_node.kind);
            defer allocator.free(kind_label);
            const governance_args = ParsedNodeTextGovernanceArgs{
                .kind_label = kind_label,
                .text = existing_node.text,
                .schema_type = govern_args.schema_type,
                .recorded_ns = persistentNowNs(io),
            };
            try validateNodeWriteGranularity(governance_args);
            // govern-node 从不改节点 kind/text —— nodeVisibleTextFromGovernanceArgs 恒返原文本
            // (仅校验 task_event token,govern-node 不传),故旧版 updateNode 是"用同 kind+同 text
            // 重写整店"= 纯浪费的 copy_on_write_full_store。真正的治理落在 applyNodeGovernanceProperties:
            // setStringProperty(property sidecar 增量) + linkNodeToProjectParent(contain 边 delta append)。
            // 二者都自持久化、不依赖 updateNode。故永远走增量挂接,不再全店重写(benefit 所有调用方)。
            // 保留 nodeVisibleTextFromGovernanceArgs 的校验副作用(task_event token)但丢弃其返回值。
            _ = try nodeVisibleTextFromGovernanceArgs(allocator, governance_args);
            try applyNodeGovernanceProperties(allocator, store, node_id, governance_args, govern_args.parent_id);
            try writer.print(
                "governed node={} parent={s} rewrite_mode=incremental_append\n",
                .{ node_id.toInt(), govern_args.parent_id orelse "*" },
            );
        },
        .delete_node => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 1, 1, true);
            const node_id = try parseNodeIdArg(parsed.rest[0]);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            // segment-aware(Linus BLOCKER 修):delta segment 上的 contain 子边也必须挡删除。
            var contain_children = try collectContainChildIds(allocator, store, node_id);
            defer contain_children.deinit(allocator);
            if (contain_children.items.len > 0) {
                try writer.print("delete-node rejected node={} reason=has_contain_children\n", .{node_id.toInt()});
                return;
            }
            const store_bytes_before = try storeDirBytes(allocator, io, parsed.db_path);
            var deferred_based_on = try readMetaknowDeferredBasedOnSidecarForwardPairs(allocator, io, parsed.db_path);
            defer deferred_based_on.deinit(allocator);
            if (deferred_based_on.present) pruneMetaknowDeferredBasedOnPairsForNode(&deferred_based_on, node_id);
            const result = try store.deleteNode(node_id);
            try restoreMetaknowDeferredBasedOnSidecar(allocator, store, &deferred_based_on);
            try writer.print(
                "deleted node={} tombstone=1 rewrite_mode=copy_on_write_full_store store_bytes_before={} nodes_rewritten={} edges_rewritten={} edges_removed={} text_rewarmed=0 text_index_current=0\n",
                .{ node_id.toInt(), store_bytes_before, result.nodes_rewritten, result.edges_rewritten, result.edges_removed },
            );
        },
