        .agent_write => {
            const db_parsed = try parseDbArgs(allocator, io, args, 2, 1, std.math.maxInt(usize), true);
            if (agentWriteArgsUseJson(db_parsed.rest)) {
                const parsed = try parseAgentWriteJsonArgs(db_parsed.rest, db_parsed.db_path);
                const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
                defer cli_lock.deinit();
                var store = try storage.Store.open(allocator, io, parsed.db_path);
                defer store.deinit();
                var effective_schema = try loadEffectiveSchemaRegistry(allocator, io, store, parsed.schema_path);
                defer effective_schema.deinit();
                const result = try agentWriteJsonBatch(allocator, io, store, parsed, effective_schema.registry, effective_schema.enforce_application_schema);
                defer result.deinit(allocator);
                try writer.print(
                    "agent_write_json items={} fact_created={} projection_nodes_imported={} projection_edge_created={} content_node_properties={} projection_links={} fact_properties={} projection_properties={} agent_inbox_created={}\n",
                    .{
                        result.items,
                        result.fact_created,
                        result.projection_nodes_imported,
                        result.projection_edge_created,
                        result.content_node_properties,
                        result.projection_links,
                        result.fact_properties,
                        result.projection_properties,
                        result.agent_inbox_created,
                    },
                );
                return;
            }
            const parsed = try parseAgentWriteArgs(db_parsed.rest, db_parsed.db_path);
            const src = try parseNodeIdArg(parsed.src_node_id);
            const dst = try parseNodeIdArg(parsed.dst_node_id);
            const render_rel = try parseRelKindWithLoadedSchema(parsed.render_rel_label, null);
            if (!agentWriteRenderRelSupported(render_rel)) return error.InvalidRelKind;
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            var effective_schema = try loadEffectiveSchemaRegistry(allocator, io, store, parsed.schema_path);
            defer effective_schema.deinit();
            const fact_rel = try parseRelKindWithSchemaPolicy(parsed.rel_label, effective_schema.registry, effective_schema.enforce_application_schema);
            if (effective_schema.enforce_application_schema) try validateSchemaEdgeEndpoints(store, effective_schema.registry, src, fact_rel, dst);
            const result = try agentWriteFactAndProjection(allocator, io, store, parsed, src, fact_rel, dst, render_rel);
            try writer.print(
                "agent_write src={} rel={} dst={} fact_edge={} fact_created={} projection_root={} projection_content={} projection_edge={} projection_nodes_imported={} projection_edge_created={} content_node_properties={} projection_links={} agent_inbox_created={}\n",
                .{
                    src.toInt(),
                    @intFromEnum(fact_rel),
                    dst.toInt(),
                    result.fact_edge_id.toInt(),
                    @intFromBool(result.fact_created),
                    result.projection_root_id.toInt(),
                    result.projection_content_id.toInt(),
                    result.projection_edge_id.toInt(),
                    result.projection_nodes_imported,
                    @intFromBool(result.projection_edge_created),
                    result.content_node_properties,
                    result.projection_links,
                    @intFromBool(result.agent_inbox_created),
                },
            );
        },
        .add_edge => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 3, 5, true);
            const schema_arg = try parseTrailingSchemaArg(parsed.rest, 3);
            const src = try parseNodeIdArg(schema_arg.positionals[0]);
            const dst = try parseNodeIdArg(schema_arg.positionals[2]);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            var effective_schema = try loadEffectiveSchemaRegistry(allocator, io, store, schema_arg.schema_path);
            defer effective_schema.deinit();
            const rel = try parseRelKindWithSchemaPolicy(schema_arg.positionals[1], effective_schema.registry, effective_schema.enforce_application_schema);
            if (effective_schema.enforce_application_schema) try validateSchemaEdgeEndpoints(store, effective_schema.registry, src, rel, dst);
            // 树目录约束盖 contain(治理归属)**和 contains(任务/文档组合)**(Linus B):
            // project 挂进任务分解树 = frontier 隐形(kind≠task 被跳)而 membership 却把它
            // 整棵卷进来——两个读面语义矛盾。project 只能被 project 收养,不分边种。
            if (rel == .contain or rel == .contains) try validateContainProjectTree(allocator, store, src, dst);
            if (try store.lookupFactEdgeByNodeExternalKeys(allocator, src, rel, dst)) |existing_id| {
                try writer.print("edge {}\n", .{existing_id.toInt()});
                return;
            }
            const id = try dag.addEdgeCheckedWithPersistentStore(allocator, store, src, rel, dst, .{});
            store.refreshFactEdgeExternalKeyIndexAfterAppend(.{ .id = id, .src = src, .rel = rel, .dst = dst }) catch {};
            try writer.print("edge {}\n", .{id.toInt()});
        },
        .delete_edge => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 1, 1, true);
            const edge_id = core.EdgeId.fromInt(std.fmt.parseInt(u64, parsed.rest[0], 10) catch return error.InvalidEdgeId);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            try store.deleteEdge(edge_id);
            try writer.print("deleted edge {}\n", .{edge_id.toInt()});
        },
        .reparent_contain => {
            // merge 原语(遗留⑤):存量重复 project 节点合并——把 from 的全部 contain 子边迁到 to。
            // 全增量:appendEdge(delta)+ deleteEdgesBatch(edge tombstone),不全店重写。
            // 去重:to 已含该 child 则只删旧边不加新边(segment-aware 读,delta 边可见)。
            // 不自动删 from(空壳交调用方 delete-node;它有 contain 子边保护,迁完自然可删)。
            const parsed = try parseDbArgs(allocator, io, args, 2, 2, 2, true);
            const from_id = try parseNodeIdArg(parsed.rest[0]);
            const to_id = try parseNodeIdArg(parsed.rest[1]);
            if (from_id.toInt() == to_id.toInt()) return error.InvalidId;
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            var node_view = try store.openNodeByIdIndexView();
            defer node_view.deinit();
            if (!try node_view.nodeExists(from_id) or !try node_view.nodeExists(to_id)) return core.Error.NotFound;

            // 环检查(Linus 严重3):to 在 from 的 contain 子树内 → 迁移会造 contain 环
            // (from→to 子边迁成 to→to 自环)。腐坏库正是本工具的目标场景,必须拒绝。
            {
                var cyc_trunc = false;
                var from_subtree = try collectProjectDescendantNodeIds(allocator, store, from_id, null, list_recent_project_scan_cap, &cyc_trunc, .contain_only);
                defer from_subtree.deinit(allocator);
                if (cyc_trunc) { // 子树超 cap 无法证明无环,拒绝而非赌(与环拒绝同通道,可读 reason)
                    try writer.print("reparent-contain rejected from={} to={} reason=subtree_exceeds_scan_cap cap={}\n", .{ from_id.toInt(), to_id.toInt(), list_recent_project_scan_cap });
                    return;
                }
                for (from_subtree.items) |n| {
                    if (n.toInt() == to_id.toInt()) {
                        try writer.print("reparent-contain rejected from={} to={} reason=would_create_contain_cycle\n", .{ from_id.toInt(), to_id.toInt() });
                        return;
                    }
                }
            }

            var to_children = try collectContainChildIds(allocator, store, to_id);
            defer to_children.deinit(allocator);
            var to_set = std.AutoHashMap(u64, void).init(allocator);
            defer to_set.deinit();
            for (to_children.items) |c| try to_set.put(c, {});

            var from_records = try store.readVisibleEdgeIndexRecordsByNodeForOrderedTraversal(allocator, from_id);
            defer from_records.deinit(allocator);
            var old_edge_ids = std.ArrayList(core.EdgeId).empty;
            defer old_edge_ids.deinit(allocator);
            var moved: usize = 0;
            var deduped: usize = 0;
            // 树目录约束预检(**先检后迁**,不留半迁移态):任一 child 是 project 而 to 不是
            // project → 整体拒绝(迁移会造非法收养)。注意(Linus D):对将被 dedup 的孩子也
            // 校验——若 to **已经**非法持有某 project 孩子(存量腐坏),本次迁移同样被拒。
            // 有意为之:拒绝比默默扩大坏账好;reason 已打印,操作者先修 to 再迁。
            for (from_records.items) |r| {
                if (r.rel != @intFromEnum(core.RelKind.contain)) continue;
                validateContainProjectTree(allocator, store, to_id, core.NodeId.fromInt(r.dst)) catch |e| switch (e) {
                    error.ProjectTreeViolation => {
                        try writer.print("reparent-contain rejected from={} to={} reason=project_child_requires_project_parent child={}\n", .{ from_id.toInt(), to_id.toInt(), r.dst });
                        return error.ProjectTreeViolation;
                    },
                    else => |other| return other,
                };
            }
            for (from_records.items) |r| {
                if (r.rel != @intFromEnum(core.RelKind.contain)) continue;
                try old_edge_ids.append(allocator, core.EdgeId.fromInt(r.edge_id));
                if (to_set.contains(r.dst)) {
                    deduped += 1; // to 已含,双亲去重:只删旧边
                    continue;
                }
                const id = try store.nextEdgeId();
                try store.appendEdge(.{ .id = id, .src = to_id, .rel = .contain, .dst = core.NodeId.fromInt(r.dst) });
                try to_set.put(r.dst, {}); // from 侧同 dst 重复边(历史 bug 产物)也只迁一条
                moved += 1;
            }
            try store.deleteEdgesBatch(old_edge_ids.items);
            try writer.print("reparented from={} to={} moved={} deduped={} old_edges_removed={}\n", .{ from_id.toInt(), to_id.toInt(), moved, deduped, old_edge_ids.items.len });
        },
        .delete_edges => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 1, std.math.maxInt(usize), true);
            var edge_ids = std.ArrayList(core.EdgeId).empty;
            defer edge_ids.deinit(allocator);
            try edge_ids.ensureTotalCapacityPrecise(allocator, parsed.rest.len);
            for (parsed.rest) |arg| {
                edge_ids.appendAssumeCapacity(core.EdgeId.fromInt(std.fmt.parseInt(u64, arg, 10) catch return error.InvalidEdgeId));
            }
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            try store.deleteEdgesBatch(edge_ids.items);
            try writer.print("deleted edges={}\n", .{edge_ids.items.len});
        },
        .list_rels => {
            const parsed = try parseOptionalSchemaOnlyArgs(args, 2);
            var registry = try loadSchemaRegistryFromSchemaArg(allocator, io, parsed);
            defer registry.deinit();
            try renderRelListWithSchema(writer, registry);
        },
        .find => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 2, 5, true);
            const find_args = try parseFindArgs(parsed.rest);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            var effective_schema = try loadEffectiveSchemaRegistry(allocator, io, store, find_args.schema_path);
            defer effective_schema.deinit();
            const kind = try parseNodeKindWithSchemaPolicy(find_args.kind_label, effective_schema.registry, effective_schema.enforce_application_schema);
            const candidate_limit = if (find_args.include_history) @as(usize, 1) else currentGenerationLookupCandidateLimit(1);
            var matches = store.lookupNodesByTextLimited(allocator, kind, find_args.text, candidate_limit) catch |err| switch (err) {
                error.FileNotFound, error.InvalidRecord => retry: {
                    try store.repairPersistentIndexesFromLog();
                    break :retry try store.lookupNodesByTextLimited(allocator, kind, find_args.text, candidate_limit);
                },
                else => |e| return e,
            };
            defer {
                for (matches.items) |*node| node.deinit(allocator);
                matches.deinit(allocator);
            }
            var found_node: ?*storage.StoredNode = null;
            for (matches.items) |*node| {
                if (!find_args.include_history and !try nodeIsCurrentGeneration(store, node.id)) continue;
                found_node = node;
                break;
            }
            if (found_node) |node| {
                try writer.print("{}\t", .{node.id.toInt()});
                try writeNodeKindNameWithSchema(writer, effective_schema.registry, node.kind);
                try writer.writeAll("\t");
                try writeEscapedText(writer, node.text);
                try writer.writeAll("\n");
            } else {
                try writer.writeAll("not found\n");
            }
        },
        .search => {
            const parsed = try parseSearchArgs(allocator, io, args);
            defer parsed.deinit(allocator);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            // 成员过滤 **server-side 下推**(截断前生效,text.zig member_filter):
            // --project = contain 子树 BFS 成员集;--schema-type = property 成员集;都给取交集。
            // 旧后置过滤 + 4096 候选窗口放大是创可贴(project 外高分命中把子树内匹配挤出窗口
            // → 静默漏召回),已删。
            var filter_diag = MemberFilterDiag{};
            var member_set = try buildSearchMemberSet(allocator, store, parsed.project, parsed.schema_type, &filter_diag);
            defer if (member_set) |*m| m.deinit();
            const search_options = text_search.TextSearchOptions{
                .kind_filter = parsed.kind_filter,
                .member_filter = if (member_set) |*m| m else null,
                .limit = searchCandidateLimit(parsed.profile, parsed.kind_filter, parsed.limit, parsed.include_history),
                .max_postings_scanned = parsed.max_postings_scanned,
                .deadline = core.QueryDeadline.fromIo(io, parsed.timeout_ms),
            };
            const output = if (parsed.format == .json)
                renderSearchJsonOutput(allocator, store, parsed.query, search_options, parsed.profile, parsed.limit, parsed.include_history, parsed.include_text, parsed.timeout_ms, filter_diag) catch |err| switch (err) {
                    error.FileNotFound, error.InvalidRecord => retry: {
                        try store.repairPersistentIndexesFromLog();
                        break :retry try renderSearchJsonOutput(allocator, store, parsed.query, search_options, parsed.profile, parsed.limit, parsed.include_history, parsed.include_text, parsed.timeout_ms, filter_diag);
                    },
                    else => |e| return e,
                }
            else
                renderSearchOutput(allocator, store, parsed.query, search_options, parsed.profile, parsed.limit, parsed.include_history, filter_diag) catch |err| switch (err) {
                    error.FileNotFound, error.InvalidRecord => retry: {
                        try store.repairPersistentIndexesFromLog();
                        break :retry try renderSearchOutput(allocator, store, parsed.query, search_options, parsed.profile, parsed.limit, parsed.include_history, filter_diag);
                    },
                    else => |e| return e,
                };
            defer allocator.free(output);
            try writer.writeAll(output);
        },
