            var effective_schema = try loadEffectiveSchemaRegistry(allocator, io, store, schema_arg.schema_path);
            defer effective_schema.deinit();
            const rel_filter = if (schema_arg.positionals.len > 2)
                try parseRelKindWithSchemaPolicy(schema_arg.positionals[2], effective_schema.registry, effective_schema.enforce_application_schema)
            else
                null;
            var edge_retention_registry = storage.EdgeSegmentRetentionRegistry.init(allocator);
            defer edge_retention_registry.deinit();
            var result = query.pathWithPersistentStoreRetained(allocator, store, &edge_retention_registry, from, to, rel_filter, .{}) catch |err| switch (err) {
                error.FileNotFound, error.InvalidRecord => retry: {
                    try store.repairPersistentIndexesFromLog();
                    break :retry try query.pathWithPersistentStoreRetained(allocator, store, &edge_retention_registry, from, to, rel_filter, .{});
                },
                else => |e| return e,
            };
            defer result.deinit(allocator);
            if (result.nodes.items.len == 0) {
                if (result.stats.budget_exceeded) return core.Error.BudgetExceeded;
                try writer.writeAll("not found\n");
                return;
            }
            for (result.nodes.items, 0..) |node_id, i| {
                if (i > 0) try writer.writeAll(" -> ");
                try writer.print("{}", .{node_id.toInt()});
            }
            try writer.writeAll("\n");
        },
        .task_ready => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 1, 1, true);
