        .task_frontier => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 1, 6, true);
            const frontier_arg = try parseTaskFrontierArgs(parsed.rest);
            if (frontier_arg.mine) |identity| _ = try validateAgentIdentity(identity);
            const root_id = try parseNodeIdArg(frontier_arg.root_id);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
