        },
        .task_claim => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 3, 6, true);
            const claim_args = try parseTaskClaimArgs(parsed.rest);
            const node_id = try parseNodeIdArg(claim_args.task_id);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            // 身份由宿主程序经 --by 注入(per-agent-loop 唯一 id),不指望模型手填。
            const agent_name = try validateAgentIdentity(claim_args.by orelse return error.MissingArgument);
            var node = (try store.readNodeById(allocator, node_id)) orelse return core.Error.NotFound;
            defer node.deinit(allocator);
            if (node.kind != .task) return core.Error.InvalidId;

            const now_ns = try u128ToU64(persistentNowNs(io));
            var lifecycle_snapshot = try task.StatusSnapshot.initForNodeIds(allocator, store, &.{node_id});
            defer lifecycle_snapshot.deinit();
            const lifecycle = try lifecycle_snapshot.statusForStoredNode(node, now_ns);
            if (lifecycle.isTerminal()) return error.InvalidTaskTransition;
            if (try taskHasNonCompletedChildren(allocator, store, node_id, now_ns)) return error.TaskHasOpenChildren;
            if ((try task.readyStateWithPersistentStoreSnapshotAt(allocator, store, node_id, now_ns, &lifecycle_snapshot)) != .ready) return error.TaskNotReady;
            const lifecycle_fields = lifecycle_snapshot.fields(node_id);
            const holder = lifecycle_fields.claimed_by;
            const held_expires = lifecycle_fields.claim_expires_ns orelse 0;
            const held_by_other = holder != null and holder.?.len > 0 and
                held_expires > now_ns and !std.mem.eql(u8, holder.?, agent_name);
            if (held_by_other and !claim_args.steal) {
                try writer.print("task_claim_held\t{}\tby=", .{node_id.toInt()});
                try writeEscapedText(writer, holder.?);
                try writer.print("\texpires_ns={}\n", .{held_expires});
                return error.ClaimHeld;
            }

            const ttl_ns = std.math.mul(u64, claim_args.ttl_s, std.time.ns_per_s) catch return error.InvalidLimit;
            const expires_ns = std.math.add(u64, now_ns, ttl_ns) catch return error.InvalidLimit;
            _ = try store.upsertPropertiesBatch(allocator, &.{
                .{ .owner = .{ .node = node_id }, .key = task.claimed_by_property, .value = .{ .string = agent_name } },
                .{ .owner = .{ .node = node_id }, .key = task.claim_expires_ns_property, .value = .{ .uint = expires_ns } },
                .{ .owner = .{ .node = node_id }, .key = task.status_property, .value = .{ .string = @tagName(if (expires_ns > now_ns) task.Status.claimed else task.Status.open) } },
            });
            try writer.print("task_claimed\t{}\tby=", .{node_id.toInt()});
            try writeEscapedText(writer, agent_name);
            try writer.print("\texpires_ns={}\n", .{expires_ns});
        },
        .task_release => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 1, 4, true);
            const release_args = try parseTaskReleaseArgs(parsed.rest);
            const release_by = if (release_args.by) |identity| try validateAgentIdentity(identity) else null;
            const node_id = try parseNodeIdArg(release_args.task_id);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            var node = (try store.readNodeById(allocator, node_id)) orelse return core.Error.NotFound;
            defer node.deinit(allocator);
            if (node.kind != .task) return core.Error.InvalidId;
            const now_ns = try u128ToU64(persistentNowNs(io));
            var lifecycle_snapshot = try task.StatusSnapshot.initForNodeIds(allocator, store, &.{node_id});
            defer lifecycle_snapshot.deinit();
            const lifecycle = try lifecycle_snapshot.statusForStoredNode(node, now_ns);
            // 终态 task 允许清理残留租约，但绝不能被 release 重开。
            // 身份对称性(Linus #2):抢租约要 --steal,放租约同样不能随手放——
            // 他人未过期租约必须 --by 匹配 holder,否则 --force 显式越权。
            const lifecycle_fields = lifecycle_snapshot.fields(node_id);
            const holder = lifecycle_fields.claimed_by;
            const held_expires = lifecycle_fields.claim_expires_ns orelse 0;
            const lease_live = holder != null and holder.?.len > 0 and held_expires > now_ns;
            if (lease_live and !release_args.force) {
                const by_matches = if (release_by) |by| std.mem.eql(u8, by, holder.?) else false;
                if (!by_matches) {
                    try writer.print("task_release_held\t{}\tby=", .{node_id.toInt()});
                    try writeEscapedText(writer, holder.?);
                    try writer.print("\texpires_ns={}\n", .{held_expires});
                    return error.ClaimHeld;
                }
            }
            // 释放 = 租约立即过期(claimed_by 留痕但 inactive;空串属性值存储层不收)。
            var property_publish_count: usize = 0;
            if (lifecycle.isTerminal()) {
                if (held_expires != 0) {
                    const result = try store.upsertPropertiesBatch(allocator, &.{.{
                        .owner = .{ .node = node_id },
                        .key = task.claim_expires_ns_property,
                        .value = .{ .uint = 0 },
                    }});
                    property_publish_count = result.payload_publish_count;
                }
            } else {
                const status_is_open = if (lifecycle_fields.stored_status_raw) |value| std.mem.eql(u8, value, @tagName(task.Status.open)) else false;
                if (held_expires != 0 and !status_is_open) {
                    const result = try store.upsertPropertiesBatch(allocator, &.{
                        .{ .owner = .{ .node = node_id }, .key = task.claim_expires_ns_property, .value = .{ .uint = 0 } },
                        .{ .owner = .{ .node = node_id }, .key = task.status_property, .value = .{ .string = @tagName(task.Status.open) } },
                    });
                    property_publish_count = result.payload_publish_count;
                } else if (held_expires != 0) {
                    const result = try store.upsertPropertiesBatch(allocator, &.{.{
                        .owner = .{ .node = node_id },
                        .key = task.claim_expires_ns_property,
                        .value = .{ .uint = 0 },
                    }});
                    property_publish_count = result.payload_publish_count;
                } else if (!status_is_open) {
                    const result = try store.upsertPropertiesBatch(allocator, &.{.{
                        .owner = .{ .node = node_id },
                        .key = task.status_property,
                        .value = .{ .string = @tagName(task.Status.open) },
                    }});
                    property_publish_count = result.payload_publish_count;
                }
            }
            try writer.print("task_released\t{}\tproperty_publishes={}\n", .{ node_id.toInt(), property_publish_count });
        },
        .task_close => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 2, 8, true);
            const close_args = try parseTaskCloseArgs(parsed.rest);
            const node_id = try parseNodeIdArg(close_args.task_id);
            const evidence_id = if (close_args.evidence_id) |raw| try parseNodeIdArg(raw) else null;
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            var node = (try store.readNodeById(allocator, node_id)) orelse return core.Error.NotFound;
            defer node.deinit(allocator);
            if (node.kind != .task) return core.Error.InvalidId;

            const recorded_ns = persistentNowNs(io);
            const now_ns = try u128ToU64(recorded_ns);
            const lifecycle = try validateTaskCloseTransition(
                allocator,
                store,
                node,
                close_args.status,
                close_args.by,
                close_args.force,
                now_ns,
            );
            // Inline text belongs to this lifecycle transition. A same-status
            // terminal retry is a no-op and must not manufacture a second
            // verification from changed retry prose. Explicit --evidence IDs
            // retain their existing post-close supplemental-evidence behavior.
            const effective_evidence_id = evidence_id orelse if (!lifecycle.isTerminal())
                if (close_args.evidence_text) |text|
                    try ensureTaskEvidenceTextNode(allocator, store, text, recorded_ns)
                else
                    null
            else
                null;
            if (effective_evidence_id) |id| try ensureTaskEvidenceEdge(allocator, store, node_id, id);

            var property_publish_count: usize = 0;
            if (!lifecycle.isTerminal()) {
                // Evidence is idempotent and precedes the single lifecycle COW
                // publication. Timestamp, terminal status and lease expiry
                // therefore cannot be observed as three partial property
                // payload generations after a successful publish.
                const result = try store.upsertPropertiesBatch(allocator, &.{
                    .{ .owner = .{ .node = node_id }, .key = "task_completed_ns", .value = .{ .uint = now_ns } },
                    .{ .owner = .{ .node = node_id }, .key = task.status_property, .value = .{ .string = @tagName(close_args.status) } },
                    .{ .owner = .{ .node = node_id }, .key = task.claim_expires_ns_property, .value = .{ .uint = 0 } },
                });
                property_publish_count = result.payload_publish_count;
            } else if (((try store.getUintProperty(allocator, .{ .node = node_id }, task.claim_expires_ns_property)) orelse 0) != 0) {
                const result = try store.upsertPropertiesBatch(allocator, &.{.{
                    .owner = .{ .node = node_id },
                    .key = task.claim_expires_ns_property,
                    .value = .{ .uint = 0 },
                }});
                property_publish_count = result.payload_publish_count;
            }
            try writer.print("task_closed\t{}\tstatus={s}\tidempotent={}\tproperty_publishes={}\n", .{ node_id.toInt(), @tagName(close_args.status), @intFromBool(lifecycle.isTerminal()), property_publish_count });
        },
        .task_ancestry => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 1, 5, true);
            const ancestry_arg = try parseTaskAncestryArgs(parsed.rest);
            const task_id = try parseNodeIdArg(ancestry_arg.task_id);
