        .task_metrics => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 1, 3, true);
            const metrics_arg = try parseTaskMetricsArgs(parsed.rest);
            const root_id = try parseNodeIdArg(metrics_arg.root_id);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            const output = renderTaskMetricsOutput(allocator, io, store, root_id, metrics_arg.limit) catch |err| switch (err) {
                error.FileNotFound, error.InvalidRecord => retry: {
                    try store.repairPersistentIndexesFromLog();
