        },
        .task_event => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 2, std.math.maxInt(usize), true);
            const event_arg = try parseTaskEventArgs(parsed.rest);
            const root_id = try parseNodeIdArg(event_arg.root_id);
            const task_id = if (event_arg.task_id) |id| try parseNodeIdArg(id) else null;
            const relation = if (event_arg.relation_label) |label| try parseRelKindWithLoadedSchema(label, null) else null;
            if (taskEventRequiresRelation(event_arg.event_type) and relation == null) return error.MissingArgument;
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            try validateTaskEventTargets(allocator, store, root_id, task_id);
            const event_ns = persistentNowNs(io);
            const event_text = try taskEventNodeText(allocator, .{
                .event_type = event_arg.event_type,

                .root_id = root_id,
                .task_id = task_id,
                .relation = relation,
                .event_ns = event_ns,
                .note = event_arg.note,
            });
            defer allocator.free(event_text);
            try validateNodeTextGranularity(event_text);
            const event_kind: core.NodeKind = if (event_arg.event_type == .write_error) .error_event else .command;
            const event_id = try store.addNode(event_kind, event_text);
            const event_type_text = try taskEventTypeNameAlloc(allocator, event_arg.event_type);
            defer allocator.free(event_type_text);
            const relation_text = if (relation) |rel| try relKindNameAlloc(allocator, rel) else null;
            defer if (relation_text) |value| allocator.free(value);
            try applyNodeGovernanceProperties(allocator, store, event_id, .{
                .kind_label = if (event_arg.event_type == .write_error) "error_event" else "command",
                .text = event_text,
                .schema_type = "task_event",
                .task_event_metadata = .{
                    .event_type = event_type_text,
                    .event_ns = event_ns,
                    .root_id = root_id.toInt(),
                    .task_id = if (task_id) |id| id.toInt() else null,
                    .dependency_relation = relation_text,
                },
            }, null);
            _ = try dag.addEdgeCheckedWithPersistentStore(allocator, store, event_id, .task_event, root_id, .{});
            if (task_id) |id| {
                if (id.toInt() != root_id.toInt()) {
                    _ = try dag.addEdgeCheckedWithPersistentStore(allocator, store, event_id, .task_event, id, .{});
                }
            }
            try writer.print("task_event node={} type=", .{event_id.toInt()});
            try writeTaskEventTypeName(writer, event_arg.event_type);
            try writer.writeAll("\n");
        },
        .query, .query_explain => {
            const parsed = try parseQueryArgs(allocator, io, args);
            defer parsed.deinit(allocator);
            const ast_query = try ql.parser.parse(allocator, parsed.query);
            defer ql.ast.freeQuery(allocator, ast_query);

            // Catalog selection is part of opening the store, not a caller
            // obligation.  A migrated/self-describing store must be directly
            // queryable without reconstructing its schema in a side file.
            // Keep the lock across catalog selection and execution so a
            // concurrent schema publication cannot change type resolution
            // between planning and reading rows.
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();

            var loaded_schema: ?schema.Registry = if (parsed.schema_path) |path| try loadSchemaRegistryFile(allocator, io, path) else null;
            defer if (loaded_schema) |*registry| registry.deinit();
            var embedded_catalog: ?catalog_mod.Catalog = if (loaded_schema == null) try store.readCatalog() else null;
            defer if (embedded_catalog) |*cat| cat.deinit();
            const query_registry: ?schema.Registry = if (loaded_schema) |registry|
                registry
            else if (embedded_catalog) |cat|
                if (queryCatalogCoversSchemaReferences(cat.registry, ast_query)) cat.registry else null
            else
                null;

            var type_env = if (query_registry) |registry|
                try ql.typecheck.checkWithSchema(allocator, ast_query, registry)
            else
                try ql.typecheck.check(allocator, ast_query);
            defer type_env.deinit(allocator);
            var logical = if (query_registry) |registry|
                try ql.planner.planWithSchema(allocator, ast_query, registry)
            else
                try ql.planner.plan(allocator, ast_query);
            defer logical.deinit(allocator);
            var physical = try ql.optimizer.optimize(allocator, logical);
            defer physical.deinit(allocator);

            const budget = core.QueryBudget{
                .max_text_postings_scanned = parsed.max_postings_scanned,
                .timeout_ms = parsed.timeout_ms,
            };
            var edge_retention_registry = storage.EdgeSegmentRetentionRegistry.init(allocator);
            defer edge_retention_registry.deinit();
            const output = renderPersistentQueryOutputRetained(allocator, io, store, &edge_retention_registry, physical, cmd == .query_explain, budget) catch |err| switch (err) {
                error.FileNotFound, error.InvalidRecord => retry: {
                    try store.repairPersistentIndexesFromLog();
                    break :retry try renderPersistentQueryOutputRetained(allocator, io, store, &edge_retention_registry, physical, cmd == .query_explain, budget);
                },
                else => |e| return e,
            };
            defer allocator.free(output);
            try writer.writeAll(output);
        },
        .governance => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 0, 4, true);
            const schema_arg = try parseSchemaOnlyRestArgs(parsed.rest);
            var loaded_schema: ?schema.Registry = if (schema_arg.schema_path != null or schema_arg.profiles != null)
                try loadSchemaRegistryFromSchemaArg(allocator, io, schema_arg)
            else
                null;
            defer if (loaded_schema) |*registry| registry.deinit();
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            var embedded_catalog: ?catalog_mod.Catalog = if (loaded_schema == null) try store.readCatalog() else null;
            defer if (embedded_catalog) |*cat| cat.deinit();
            const governance_registry: ?schema.Registry = if (loaded_schema) |registry|
                registry
            else if (embedded_catalog) |cat|
                if (catalogHasApplicationSchema(cat)) cat.registry else null
            else
                null;
            try renderGovernanceReport(allocator, io, parsed.db_path, store, governance_registry, writer);
        },
        .segment_query, .segment_query_explain => {
