        },
        .bench => {
            const parsed = try parseBenchArgs(args);
            if (try existingTinyKgStorePath(allocator, io, parsed.db_path)) return error.AlreadyExists;
            const output = try renderBenchOutput(
                allocator,
                io,
                parsed.db_path,
                parsed.nodes,
                parsed.edges,
                parsed.chunk_size,
                parsed.workload,
                parsed.corpus_file_path,
                parsed.corpus_dir_path,
                parsed.edge_id_pattern,
                parsed.edge_delta_stats,
                parsed.edge_tombstone_probe,
                parsed.storage_only,
                parsed.agent_mixed,
                parsed.edge_compact_batch_entries,
                parsed.edge_compact_threshold_entries,
                parsed.maintenance_every_ops,
                parsed.maintenance_max_segments,
                parsed.maintenance_max_edges,
                parsed.maintenance_gc,
                parsed.maintenance_node_text_every_ops,
                parsed.maintenance_node_text_max_records,
                parsed.maintenance_node_text_runs_every_ops,
                parsed.maintenance_node_text_runs_max_records,
                parsed.no_regression_gates,
            );
            defer allocator.free(output);
            try writer.writeAll(output);
        },
        .bench_md_doc_edit => {
            const parsed = try parseMarkdownDocEditBenchArgs(args);
            const output = try renderMarkdownDocEditBenchOutput(allocator, io, parsed);
            defer allocator.free(output);
            try writer.writeAll(output);
        },
        .maintain => {
            const parsed = try parseLifecycleMaintenanceArgs(allocator, io, args);
            const maintenance_start_ns = monotonicNs(io);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            var summary = LifecycleMaintenanceSummary{};
            var clean_cycle_streak: usize = 0;
            var cycle_index: usize = 0;
            while (cycle_index < parsed.max_cycles) : (cycle_index += 1) {
                const cycle = try runLifecycleMaintenanceCycle(store, parsed, &summary, io);
                try summary.recordCycle(cycle.made_progress);
                if (cycle.made_progress) {
                    clean_cycle_streak = 0;
                } else {
                    clean_cycle_streak = std.math.add(usize, clean_cycle_streak, 1) catch return error.RecordTooLarge;
                }
                if (parsed.max_cycles == 1 and cycle.stopped_clean) {
                    summary.stopped_clean = true;
                }
                if (parsed.stop_after_clean_cycles != 0 and clean_cycle_streak >= parsed.stop_after_clean_cycles) {
                    summary.stopped_clean = true;
                    break;
                }
                if (cycle_index < parsed.max_cycles - 1 and parsed.poll_ms != 0) {
                    try sleepMillis(io, parsed.poll_ms);
                }
            }
            const maintenance_elapsed_ns = elapsedNs(io, maintenance_start_ns);
            try writer.print(
                "maintenance cycles={} passes={} stopped_clean={} clean_cycles={} edge_l0_compactions={} edge_l0_compacted_edges={} edge_l0_compacted_segments={} edge_gc_passes={} edge_gc_deleted_segments={} edge_gc_deleted_manifests={} node_text_delta_compactions={} node_text_delta_records_compacted={} node_text_run_compactions={} node_text_run_compacted_records={} node_text_run_gc_deleted_runs={} node_texts_compressions={} node_texts_compress_ns={} node_texts_bytes_before_last={} node_texts_bytes_after_last={} node_texts_logical_bytes_last={} node_text_gc_passes={} node_text_gc_deleted_runs={} node_text_gc_deleted_manifests={} property_payload_compactions={} property_payload_delta_bytes_compacted={} property_payload_delta_frames_compacted={} last_property_payload_live_entries={} property_payload_cleanup_pending={}",
                .{
                    summary.cycles,
                    summary.passes,
                    summary.stopped_clean,
                    summary.clean_cycles,
                    summary.edge_l0_compactions,
                    summary.edge_l0_compacted_edges,
                    summary.edge_l0_compacted_segments,
                    summary.edge_gc_passes,
                    summary.edge_gc_deleted_segments,
                    summary.edge_gc_deleted_manifests,
                    summary.node_text_delta_compactions,
                    summary.node_text_delta_records_compacted,
                    summary.node_text_run_compactions,
                    summary.node_text_run_compacted_records,
                    summary.node_text_run_gc_deleted_runs,
                    summary.node_texts_compressions,
                    summary.node_texts_compress_ns,
                    summary.node_texts_bytes_before_last,
                    summary.node_texts_bytes_after_last,
                    summary.node_texts_logical_bytes_last,
                    summary.node_text_gc_passes,
                    summary.node_text_gc_deleted_runs,
                    summary.node_text_gc_deleted_manifests,
                    summary.property_payload_compactions,
                    summary.property_payload_delta_bytes_compacted,
                    summary.property_payload_delta_frames_compacted,
                    summary.last_property_payload_live_entries,
                    @intFromBool(summary.property_payload_cleanup_pending),
                },
            );
            try writer.print(
                " last_edge_l0_entries_before={} last_edge_l0_entries_after={} last_node_text_delta_records_before={} last_node_text_delta_records_after={} last_node_text_run_entries_before={} last_node_text_run_entries_after={} last_node_text_run_records_before={} last_node_text_run_records_after={} elapsed_ns={}\n",
                .{
                    summary.last_edge_l0_entries_before,
                    summary.last_edge_l0_entries_after,
                    summary.last_node_text_delta_records_before,
                    summary.last_node_text_delta_records_after,
                    summary.last_node_text_run_entries_before,
                    summary.last_node_text_run_entries_after,
                    summary.last_node_text_run_records_before,
                    summary.last_node_text_run_records_after,
                    maintenance_elapsed_ns,
                },
            );
        },
        .compact_edges => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 1, 1, true);
            if (try pathExists(io, parsed.rest[0])) return error.AlreadyExists;

            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            const edges = store.publishEdgeAdjacencySegment(parsed.rest[0]) catch |err| switch (err) {
                error.FileNotFound, error.InvalidRecord => retry: {
                    try store.repairPersistentIndexesFromLog();
                    break :retry try store.publishEdgeAdjacencySegment(parsed.rest[0]);
                },
                else => |e| return e,
            };
            try writer.print("edge_segment edges={} dir={s}\n", .{ edges, parsed.rest[0] });
        },
        .compact_edge_segments => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 1, 1, true);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            const edges = try store.compactPublishedEdgeSegments(parsed.rest[0]);
            try writer.print("edge_segment_compacted edges={} dir={s}\n", .{ edges, parsed.rest[0] });
        },
        .maintain_edge_segments => {
            const parsed = try parseEdgeSegmentMaintenanceArgs(allocator, io, args);
            const maintenance_start_ns = monotonicNs(io);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.openWithOptions(allocator, io, parsed.db_path, .{
                .auto_gc_edge_segments = parsed.gc,
            });
            defer store.deinit();
            const result = try store.compactEdgeSegmentsBudgetedWithProcessLeases(.{
                .max_segments = parsed.max_segments,
                .max_edges = parsed.max_edges,
            });
            const maintenance_elapsed_ns = elapsedNs(io, maintenance_start_ns);
            try writer.print(
                "edge_segments_maintenance compacted={} compacted_edges={} compacted_segments={} gc_deleted_segments={} gc_deleted_manifests={} entries_before={} entries_after={} elapsed_ns={}\n",
                .{
                    result.compacted,
                    result.compacted_edges,
                    result.compacted_segments,
                    result.gc_deleted_segments,
                    result.gc_deleted_manifests,
                    result.manifest_entries_before,
                    result.manifest_entries_after,
                    maintenance_elapsed_ns,
                },
            );
        },
        .gc_edge_segments => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 0, 0, true);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            const result = try store.gcUnreferencedEdgeSegmentsWithProcessLeases();
            try writer.print("edge_segments_gc deleted_segments={} deleted_manifests={}\n", .{ result.deleted_segments, result.deleted_manifests });
        },
        .gc_node_text_runs => {
            const parsed = try parseDbArgs(allocator, io, args, 2, 0, 0, true);
            const cli_lock = try CliStoreLock.acquire(allocator, io, parsed.db_path);
            defer cli_lock.deinit();
            var store = try storage.Store.open(allocator, io, parsed.db_path);
            defer store.deinit();
            const result = try store.gcUnreferencedNodeTextRunsWithProcessLeases();
            try writer.print("node_text_runs_gc deleted_runs={} deleted_manifests={}\n", .{ result.deleted_runs, result.deleted_manifests });
        },
    }
}

fn taskReadyForOpenTask(allocator: std.mem.Allocator, store: storage.Store, task_id: core.NodeId) !task.ReadyState {
    const now_ns = try u128ToU64(persistentNowNs(store.io));
    const lifecycle = try task.statusWithPersistentStoreAt(allocator, store, task_id, now_ns);
    if (lifecycle.isTerminal()) return error.InvalidTaskTransition;
    return try task.readyStateWithPersistentStoreAt(allocator, store, task_id, now_ns);
}

