    id: []const u8,
    format: CliOutputFormat = .text,
    meta: bool = false,
    include_text: bool = false,
};

const CliOutputFormat = enum { text, json };

const ParsedFreeTextDbArgs = struct {
    db_path: []const u8,
    rest: []const []const u8,
    owned_db_path: ?[]u8 = null,

    fn deinit(self: ParsedFreeTextDbArgs, allocator: std.mem.Allocator) void {
