        .max_edges = max_edges,
        .gc = gc,
    };
}

fn parseMetaknowReplayImportArgs(args: []const []const u8) !ParsedMetaknowReplayImportArgs {
    if (args.len < 4) return error.MissingArgument;
    var parsed = ParsedMetaknowReplayImportArgs{
        .db_path = args[2],
        .corpus_dir_path = args[3],
    };

    var pos: usize = 4;
    while (pos < args.len) {
        const option = args[pos];
        if (std.mem.eql(u8, option, "--chunk")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            parsed.chunk_size = try parseBenchCount(args[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, option, "--warm-text")) {
            parsed.warm_text = true;
            pos += 1;
        } else if (std.mem.startsWith(u8, option, "--")) {
            return error.UnknownOption;
        } else {
            return error.TooManyArguments;
        }
    }
    return parsed;
}

fn parseJsonlImportArgs(args: []const []const u8) !ParsedJsonlImportArgs {
    if (args.len < 4) return error.MissingArgument;
    var parsed = ParsedJsonlImportArgs{
        .db_path = args[2],
        .dir_path = args[3],
    };
    var pos: usize = 4;
    while (pos < args.len) {
        const option = args[pos];
        if (std.mem.eql(u8, option, "--warm-text")) {
            parsed.warm_text = true;
            pos += 1;
        } else if (std.mem.startsWith(u8, option, "--")) {
            return error.UnknownOption;
        } else {
            return error.TooManyArguments;
        }
    }
    return parsed;
}

fn parseMigrateStoreV2Args(args: []const []const u8) !ParsedMigrateStoreV2Args {
    if (args.len < 4) return error.MissingArgument;
    var parsed = ParsedMigrateStoreV2Args{
        .source_path = args[2],
        .target_path = args[3],
    };
    var pos: usize = 4;
    while (pos < args.len) {
        const option = args[pos];
        if (std.mem.eql(u8, option, "--backup")) {
            if (parsed.backup_path != null) return error.TooManyArguments;
            if (pos + 1 >= args.len) return error.MissingArgument;
            parsed.backup_path = args[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--profile")) {
            if (parsed.profiles_explicit) return error.TooManyArguments;
            if (pos + 1 >= args.len) return error.MissingArgument;
            parsed.profiles = args[pos + 1];
            parsed.profiles_explicit = true;
            pos += 2;
        } else if (std.mem.eql(u8, option, "--warm-text")) {
            parsed.warm_text = true;
            pos += 1;
        } else if (std.mem.eql(u8, option, "--verify")) {
            parsed.verify = true;
            pos += 1;
        } else if (std.mem.eql(u8, option, "--no-verify")) {
            parsed.verify = false;
            pos += 1;
        } else if (std.mem.eql(u8, option, "--dry-run")) {
            parsed.dry_run = true;
            pos += 1;
        } else if (std.mem.eql(u8, option, "--strict")) {
            parsed.strict = true;
            pos += 1;
        } else if (std.mem.eql(u8, option, "--task-status-v1")) {
            parsed.task_status_v1 = true;
            pos += 1;
        } else if (std.mem.startsWith(u8, option, "--")) {
            return error.UnknownOption;
        } else {
            return error.TooManyArguments;
        }
    }
    if (parsed.profiles.len == 0) return error.InvalidRecord;
    return parsed;
}

fn parseMarkdownDocEditBenchArgs(args: []const []const u8) !ParsedMarkdownDocEditBenchArgs {
    if (args.len < 4) return error.MissingArgument;
    const paragraphs = try parseBenchCount(args[3]);
    var parsed = ParsedMarkdownDocEditBenchArgs{
        .db_path = args[2],
        .paragraphs = paragraphs,
        .edit_index = paragraphs / 2,
    };
    var pos: usize = 4;
    while (pos < args.len) {
        const option = args[pos];
        if (std.mem.eql(u8, option, "--edit-index")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            parsed.edit_index = std.fmt.parseInt(usize, args[pos + 1], 10) catch return error.InvalidLimit;
            pos += 2;
        } else if (std.mem.eql(u8, option, "--repeat-local-edits")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            parsed.repeat_local_edits = try parseBenchCount(args[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, option, "--repeat-update-edits")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            parsed.repeat_update_edits = try parseBenchCount(args[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, option, "--agent-mixed-writes")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            parsed.agent_mixed_writes = try parseBenchCount(args[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, option, "--max-edit-changed-records")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            parsed.max_edit_changed_records = std.fmt.parseInt(usize, args[pos + 1], 10) catch return error.InvalidLimit;
            pos += 2;
        } else if (std.mem.eql(u8, option, "--max-edit-elapsed-ns")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            parsed.max_edit_elapsed_ns = std.fmt.parseInt(u128, args[pos + 1], 10) catch return error.InvalidLimit;
            pos += 2;
        } else if (std.mem.eql(u8, option, "--max-edit-ns-per-paragraph")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            parsed.max_edit_ns_per_paragraph = std.fmt.parseInt(u128, args[pos + 1], 10) catch return error.InvalidLimit;
            pos += 2;
        } else if (std.mem.eql(u8, option, "--max-edit-to-initial-bps")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            parsed.max_edit_to_initial_bps = std.fmt.parseInt(u128, args[pos + 1], 10) catch return error.InvalidLimit;
            pos += 2;
        } else if (std.mem.eql(u8, option, "--max-repeat-edit-elapsed-ns")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            parsed.max_repeat_edit_elapsed_ns = std.fmt.parseInt(u128, args[pos + 1], 10) catch return error.InvalidLimit;
            pos += 2;
        } else if (std.mem.eql(u8, option, "--max-repeat-update-edit-elapsed-ns")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            parsed.max_repeat_update_edit_elapsed_ns = std.fmt.parseInt(u128, args[pos + 1], 10) catch return error.InvalidLimit;
            pos += 2;
        } else if (std.mem.eql(u8, option, "--max-render-local-subtree-elapsed-ns")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            parsed.max_render_local_subtree_elapsed_ns = std.fmt.parseInt(u128, args[pos + 1], 10) catch return error.InvalidLimit;
            pos += 2;
        } else if (std.mem.startsWith(u8, option, "--")) {
            return error.UnknownOption;
        } else {
            return error.TooManyArguments;
        }
    }
    if (parsed.edit_index >= parsed.paragraphs) return error.InvalidLimit;

    return parsed;
}

fn parseBenchArgs(args: []const []const u8) !ParsedBenchArgs {
    if (args.len < 5) return error.MissingArgument;
    const nodes = try parseBenchCount(args[3]);
    const edges = try parseBenchCount(args[4]);
    var chunk_size: usize = default_bench_chunk_size;
    var workload: BenchWorkload = .synthetic_ring;
    var corpus_file_path: ?[]const u8 = null;
    var corpus_dir_path: ?[]const u8 = null;
    var edge_id_pattern: BenchEdgeIdPattern = .sequential;
    var edge_delta_stats = false;
    var edge_tombstone_probe = false;
    var storage_only = false;
    var agent_mixed = false;
    var edge_compact_batch_entries: u32 = 0;
    var edge_compact_threshold_entries: u32 = default_bench_edge_compact_threshold_entries;
    var maintenance_every_ops: usize = 0;
    var maintenance_max_segments: usize = 0;
    var maintenance_max_edges: u64 = 0;
    var maintenance_gc = false;
    var maintenance_node_text_every_ops: usize = 0;
    var maintenance_node_text_max_records: u64 = 0;
    var maintenance_node_text_runs_every_ops: usize = 0;
    var maintenance_node_text_runs_max_records: u64 = 0;
    var no_regression_gates = BenchNoRegressionGateLimits{};
    var pos: usize = 5;
    while (pos < args.len) {
        const option = args[pos];
        if (std.mem.eql(u8, option, "--chunk")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            chunk_size = try parseBenchCount(args[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, option, "--workload")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            workload = try parseBenchWorkload(args[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, option, "--corpus-file")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            corpus_file_path = args[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--corpus-dir")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            corpus_dir_path = args[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--edge-id-pattern")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            edge_id_pattern = try parseBenchEdgeIdPattern(args[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, option, "--edge-delta-stats")) {
            edge_delta_stats = true;
            pos += 1;
        } else if (std.mem.eql(u8, option, "--edge-tombstone-probe")) {
            edge_tombstone_probe = true;
            pos += 1;
        } else if (std.mem.eql(u8, option, "--edge-compact-batch")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            edge_compact_batch_entries = std.fmt.parseInt(u32, args[pos + 1], 10) catch return error.InvalidLimit;
            pos += 2;
        } else if (std.mem.eql(u8, option, "--edge-compact-threshold")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            edge_compact_threshold_entries = std.fmt.parseInt(u32, args[pos + 1], 10) catch return error.InvalidLimit;
            pos += 2;
        } else if (std.mem.eql(u8, option, "--maintenance-every")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            maintenance_every_ops = try parseBenchCount(args[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, option, "--maintenance-max-segments")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            maintenance_max_segments = try parseBenchCount(args[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, option, "--maintenance-max-edges")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            maintenance_max_edges = std.fmt.parseInt(u64, args[pos + 1], 10) catch return error.InvalidLimit;
            if (maintenance_max_edges == 0) return error.InvalidLimit;
            pos += 2;
        } else if (std.mem.eql(u8, option, "--maintenance-gc")) {
            maintenance_gc = true;
            pos += 1;
        } else if (std.mem.eql(u8, option, "--maintenance-node-text-every")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            maintenance_node_text_every_ops = try parseBenchCount(args[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, option, "--maintenance-node-text-max-records")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            maintenance_node_text_max_records = std.fmt.parseInt(u64, args[pos + 1], 10) catch return error.InvalidLimit;
            if (maintenance_node_text_max_records == 0) return error.InvalidLimit;
            pos += 2;
        } else if (std.mem.eql(u8, option, "--maintenance-node-text-runs-every")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            maintenance_node_text_runs_every_ops = try parseBenchCount(args[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, option, "--maintenance-node-text-runs-max-records")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            maintenance_node_text_runs_max_records = std.fmt.parseInt(u64, args[pos + 1], 10) catch return error.InvalidLimit;
            if (maintenance_node_text_runs_max_records == 0) return error.InvalidLimit;
            pos += 2;
        } else if (std.mem.eql(u8, option, "--max-search-ns")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            no_regression_gates.max_search_ns = try parseBenchGateU128(args[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, option, "--max-neighbors-ns")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            no_regression_gates.max_neighbors_ns = try parseBenchGateU128(args[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, option, "--max-tinyql-expand-p95-ns")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            no_regression_gates.max_tinyql_expand_p95_ns = try parseBenchGateU128(args[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, option, "--max-tinyql-context-render-p95-ns")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            no_regression_gates.max_tinyql_context_render_p95_ns = try parseBenchGateU128(args[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, option, "--max-path-ns")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            no_regression_gates.max_path_ns = try parseBenchGateU128(args[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, option, "--max-store-overhead-bps")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            no_regression_gates.max_store_overhead_bps = try parseBenchGateU128(args[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, option, "--storage-only")) {
            storage_only = true;
            pos += 1;
        } else if (std.mem.eql(u8, option, "--agent-mixed")) {
            agent_mixed = true;
            pos += 1;
        } else {
            return error.UnknownOption;
        }
    }
    if (agent_mixed and storage_only) return core.Error.Unsupported;
    if (edge_tombstone_probe and !storage_only) return core.Error.Unsupported;
    if (maintenance_every_ops != 0 and !agent_mixed) return core.Error.Unsupported;
    if ((maintenance_max_segments != 0 or maintenance_max_edges != 0) and maintenance_every_ops == 0) return core.Error.Unsupported;
    if (maintenance_gc and maintenance_every_ops == 0) return core.Error.Unsupported;
    if (maintenance_node_text_every_ops != 0 and !agent_mixed) return core.Error.Unsupported;
    if (maintenance_node_text_max_records != 0 and maintenance_node_text_every_ops == 0) return core.Error.Unsupported;
    if (maintenance_node_text_runs_every_ops != 0 and !agent_mixed) return core.Error.Unsupported;
    if (maintenance_node_text_runs_max_records != 0 and maintenance_node_text_runs_every_ops == 0) return core.Error.Unsupported;
    if (no_regression_gates.enabled() and (storage_only or agent_mixed)) return core.Error.Unsupported;
    if (benchWorkloadUsesMetaknowReplay(workload) and corpus_dir_path == null) return error.MissingArgument;
    if (!benchWorkloadUsesMetaknowReplay(workload) and corpus_dir_path != null) return core.Error.Unsupported;
    if (benchWorkloadUsesMetaknowReplay(workload) and agent_mixed) return core.Error.Unsupported;
    if (benchWorkloadUsesMetaknowReplay(workload) and edge_tombstone_probe) return core.Error.Unsupported;
    return .{
        .db_path = args[2],
        .nodes = nodes,
        .edges = edges,
        .chunk_size = chunk_size,
        .workload = workload,
        .corpus_file_path = corpus_file_path,
        .corpus_dir_path = corpus_dir_path,
        .edge_id_pattern = edge_id_pattern,
        .edge_delta_stats = edge_delta_stats,
        .edge_tombstone_probe = edge_tombstone_probe,
        .storage_only = storage_only,
        .agent_mixed = agent_mixed,
        .edge_compact_batch_entries = edge_compact_batch_entries,
        .edge_compact_threshold_entries = edge_compact_threshold_entries,
        .maintenance_every_ops = maintenance_every_ops,
        .maintenance_max_segments = maintenance_max_segments,
        .maintenance_max_edges = maintenance_max_edges,
        .maintenance_gc = maintenance_gc,
        .maintenance_node_text_every_ops = maintenance_node_text_every_ops,
        .maintenance_node_text_max_records = maintenance_node_text_max_records,
        .maintenance_node_text_runs_every_ops = maintenance_node_text_runs_every_ops,
        .maintenance_node_text_runs_max_records = maintenance_node_text_runs_max_records,
        .no_regression_gates = no_regression_gates,
    };
}

fn parseBenchGateU128(value: []const u8) !u128 {
    const parsed = std.fmt.parseInt(u128, value, 10) catch return error.InvalidLimit;
    if (parsed == 0) return error.InvalidLimit;
    return parsed;
}

fn parseBenchWorkload(value: []const u8) !BenchWorkload {
    if (std.mem.eql(u8, value, "synthetic-ring")) return .synthetic_ring;
    if (std.mem.eql(u8, value, "realistic-agent-text")) return .realistic_agent_text;
    if (std.mem.eql(u8, value, "realistic-agent-diverse-text")) return .realistic_agent_diverse_text;
    if (std.mem.eql(u8, value, "metaknow-replay")) return .metaknow_replay;
    if (std.mem.eql(u8, value, "metaknow-replay-shaped")) return .metaknow_replay_shaped;
    return error.InvalidLimit;
}

fn benchWorkloadUsesMetaknowReplay(workload: BenchWorkload) bool {
    return switch (workload) {
        .metaknow_replay, .metaknow_replay_shaped => true,
        else => false,
    };
}

fn parseBenchEdgeIdPattern(value: []const u8) !BenchEdgeIdPattern {
    if (std.mem.eql(u8, value, "sequential")) return .sequential;
    if (std.mem.eql(u8, value, "gap-heavy")) return .gap_heavy;
    return error.InvalidLimit;
}

fn parseTextBudgetProfile(value: []const u8) !TextBudgetProfile {
    if (std.mem.eql(u8, value, "interactive")) return .interactive;
    if (std.mem.eql(u8, value, "agent-memory")) return .agent_memory;
    return error.InvalidLimit;
}

fn applyTextBudgetProfile(profile: TextBudgetProfile, max_postings_scanned: *usize, timeout_ms: *u64, max_postings_explicit: bool, timeout_explicit: bool) void {
    switch (profile) {
        .interactive => {},
        .agent_memory => {
            if (!max_postings_explicit) max_postings_scanned.* = agent_memory_text_postings_scanned;
            if (!timeout_explicit) timeout_ms.* = agent_memory_text_timeout_ms;
        },
    }
}

fn parseGetArgs(args: []const []const u8) !ParsedGetArgs {
    if (args.len == 0) return error.MissingArgument;
    var parsed = ParsedGetArgs{ .id = args[0] };
    var pos: usize = 1;
    while (pos < args.len) {
        const option = args[pos];
        if (std.mem.eql(u8, option, "--format")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            parsed.format = try parseCliOutputFormat(args[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, option, "--meta")) {
            parsed.meta = true;
            pos += 1;
        } else if (std.mem.eql(u8, option, "--include-text")) {
            parsed.include_text = true;
            pos += 1;
        } else if (std.mem.startsWith(u8, option, "--")) {
            return error.UnknownOption;
        } else {
            return error.TooManyArguments;
        }
    }
    if (parsed.include_text and parsed.format != .json) return error.Unsupported;
    if (parsed.meta and parsed.format != .json) return error.Unsupported;
    return parsed;
}

fn parseCliOutputFormat(value: []const u8) !CliOutputFormat {
    if (std.mem.eql(u8, value, "text")) return .text;
    if (std.mem.eql(u8, value, "json")) return .json;
    return error.InvalidFormat;
}

fn parseImportMarkdownDocumentArgs(allocator: std.mem.Allocator, io: std.Io, args: []const []const u8) !ParsedImportMarkdownDocumentArgs {
    _ = allocator;
    _ = io;
    if (args.len < 4) return error.MissingArgument;
    var file_path: ?[]const u8 = null;
    var durability: storage.DurabilityMode = .safe;
    var source_label: ?[]const u8 = null;
    var pos: usize = 3;
    while (pos < args.len) {
        const arg = args[pos];
        if (std.mem.eql(u8, arg, "--source-label")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            source_label = args[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--durability")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            durability = try parseDurabilityModeArg(args[pos + 1]);
            pos += 2;
        } else if (std.mem.startsWith(u8, arg, "--")) {
            return error.UnknownOption;
        } else {
            if (file_path != null) return error.TooManyArguments;
            file_path = arg;
            pos += 1;
        }
    }
    return .{
        .db_path = args[2],
        .file_path = file_path orelse return error.MissingArgument,
        .durability = durability,
        .source_label = source_label,
    };
}

fn parseImportMarkdownAstArgs(args: []const []const u8) !ParsedImportMarkdownAstArgs {
    if (args.len < 4) return error.MissingArgument;
    var ast_path: ?[]const u8 = null;
    var source_id: ?[]const u8 = null;
    var format: []const u8 = "mdast";
    var durability: storage.DurabilityMode = .safe;
    var pos: usize = 3;
    while (pos < args.len) {
        const arg = args[pos];
        if (std.mem.eql(u8, arg, "--source") or std.mem.eql(u8, arg, "--source-id")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            source_id = args[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--format")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            format = args[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--durability")) {
            if (pos + 1 >= args.len) return error.MissingArgument;
            durability = try parseDurabilityModeArg(args[pos + 1]);
            pos += 2;
        } else if (std.mem.startsWith(u8, arg, "--")) {
            return error.UnknownOption;
        } else {
            if (ast_path != null) return error.TooManyArguments;
            ast_path = arg;
            pos += 1;
        }
    }
    if (!std.mem.eql(u8, format, "mdast")) return error.InvalidRecord;
    const path = ast_path orelse return error.MissingArgument;
    return .{
        .db_path = args[2],
        .ast_path = path,
        .format = format,
        .source_id = source_id orelse if (std.mem.eql(u8, path, "-")) "stdin" else path,
        .durability = durability,
    };
}

fn parseDurabilityModeArg(value: []const u8) !storage.DurabilityMode {
    if (std.mem.eql(u8, value, "safe")) return .safe;
    if (std.mem.eql(u8, value, "fast")) return .fast;
    return error.InvalidRecord;
}

fn parseRenderMarkdownDocumentArgs(rest: []const []const u8) !ParsedRenderMarkdownDocumentArgs {
    if (rest.len == 0) return error.MissingArgument;
    const document_id = try parseNodeIdArg(rest[0]);
    var render_root_id = document_id;
    var format: CliOutputFormat = .text;
    var meta = false;
    var preview_lines: usize = 20;
    var preview_lines_explicit = false;
    var page_size_bytes: ?usize = null;
    var cursor: usize = 0;
    var cursor_explicit = false;
    var pos: usize = 1;
    while (pos < rest.len) {
        const arg = rest[pos];
        if (std.mem.eql(u8, arg, "--section") or std.mem.eql(u8, arg, "--subtree")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (render_root_id.toInt() != document_id.toInt()) return error.TooManyArguments;
            render_root_id = try parseNodeIdArg(rest[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--format")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            format = try parseCliOutputFormat(rest[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--meta")) {
            meta = true;
            pos += 1;
        } else if (std.mem.eql(u8, arg, "--preview-lines")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (preview_lines_explicit) return error.TooManyArguments;
            preview_lines = std.fmt.parseInt(usize, rest[pos + 1], 10) catch return error.InvalidLimit;
            if (preview_lines > 200) return error.InvalidLimit;
            preview_lines_explicit = true;
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--page-size-bytes") or std.mem.eql(u8, arg, "--page-bytes")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (page_size_bytes != null) return error.TooManyArguments;
            const parsed_page_size = std.fmt.parseInt(usize, rest[pos + 1], 10) catch return error.InvalidLimit;
            if (parsed_page_size == 0 or parsed_page_size > 2_000_000) return error.InvalidLimit;
            page_size_bytes = parsed_page_size;
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--cursor")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (cursor_explicit) return error.TooManyArguments;
            cursor = std.fmt.parseInt(usize, rest[pos + 1], 10) catch return error.InvalidLimit;
            cursor_explicit = true;
            pos += 2;
        } else if (std.mem.startsWith(u8, arg, "--")) {
            return error.UnknownOption;
        } else {
            return error.TooManyArguments;
        }
    }
    if (meta and format != .json) return error.Unsupported;
    if (format != .json and preview_lines_explicit) return error.Unsupported;
    if (format != .json and (page_size_bytes != null or cursor_explicit)) return error.Unsupported;
    if (cursor_explicit and page_size_bytes == null) return error.Unsupported;
    return .{
        .document_id = document_id,
        .render_root_id = render_root_id,
        .format = format,
        .meta = meta,
        .preview_lines = preview_lines,
        .page_size_bytes = page_size_bytes,
        .cursor = cursor,
    };
}

fn parseMarkdownOrphanGcArgs(args: []const []const u8) !ParsedMarkdownOrphanGcArgs {
    if (args.len < 3) return error.MissingArgument;
    var parsed = ParsedMarkdownOrphanGcArgs{ .db_path = args[2] };
    var pos: usize = 3;
    while (pos < args.len) {
        const option = args[pos];
        if (std.mem.eql(u8, option, "--apply")) {
            parsed.apply = true;
            pos += 1;
        } else if (std.mem.startsWith(u8, option, "--")) {
            return error.UnknownOption;
        } else {
            return error.TooManyArguments;
        }
    }
    return parsed;
}

fn parseAgentWriteArgs(rest: []const []const u8, db_path: []const u8) !ParsedAgentWriteArgs {
    var src_node_id: ?[]const u8 = null;
    var rel_label: ?[]const u8 = null;
    var dst_node_id: ?[]const u8 = null;
    var document_node_id: ?[]const u8 = null;
    var section_node_id: ?[]const u8 = null;
    var agent_inbox = false;
    var text: ?[]const u8 = null;
    var name: ?[]const u8 = null;
    var summary: ?[]const u8 = null;
    var retrieval_hints: ?[]const u8 = null;
    var render_rel_label: []const u8 = "md:paragraph";
    var schema_path: ?[]const u8 = null;

    var pos: usize = 0;
    while (pos < rest.len) {
        const option = rest[pos];
        if (std.mem.eql(u8, option, "--src")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            src_node_id = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--rel")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            rel_label = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--dst")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            dst_node_id = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--document")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            document_node_id = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--section")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            section_node_id = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--agent-inbox")) {
            agent_inbox = true;
            pos += 1;
        } else if (std.mem.eql(u8, option, "--text")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            text = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--name")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            name = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--summary")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            summary = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--retrieval-hints") or std.mem.eql(u8, option, "--retrieval-hint")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            retrieval_hints = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--render-rel")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            render_rel_label = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--schema")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            schema_path = rest[pos + 1];
            pos += 2;
        } else if (std.mem.startsWith(u8, option, "--")) {
            return error.UnknownOption;
        } else {
            return error.TooManyArguments;
        }
    }

    const attach_target_count: usize =
        @intFromBool(document_node_id != null) +
        @intFromBool(section_node_id != null) +
        @intFromBool(agent_inbox);
    if (attach_target_count > 1) return error.MissingArgument;
    if (text) |value| try validateNodeTextGranularity(value);
    try validateNodeLlmMetadataGranularity(name, summary, retrieval_hints);
    return .{
        .db_path = db_path,
        .src_node_id = src_node_id orelse return error.MissingArgument,
        .rel_label = rel_label orelse return error.MissingArgument,
        .dst_node_id = dst_node_id orelse return error.MissingArgument,
        .document_node_id = document_node_id,
        .section_node_id = section_node_id,
        .agent_inbox = agent_inbox or attach_target_count == 0,
        .text = text orelse return error.MissingArgument,
        .name = name,
        .summary = summary,
        .retrieval_hints = retrieval_hints,
        .render_rel_label = render_rel_label,
        .schema_path = schema_path,
    };
}

fn agentWriteArgsUseJson(rest: []const []const u8) bool {
    return rest.len >= 2 and std.mem.eql(u8, rest[0], "--json");
}

fn parseAgentWriteJsonArgs(rest: []const []const u8, db_path: []const u8) !ParsedAgentWriteJsonArgs {
    var json_path: ?[]const u8 = null;
    var schema_path: ?[]const u8 = null;
    var pos: usize = 0;
    while (pos < rest.len) {
        const option = rest[pos];
        if (std.mem.eql(u8, option, "--json")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            json_path = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--schema")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            schema_path = rest[pos + 1];
            pos += 2;
        } else if (std.mem.startsWith(u8, option, "--")) {
            return error.UnknownOption;
        } else {
            return error.TooManyArguments;
        }
    }
    return .{
        .db_path = db_path,
        .json_path = json_path orelse return error.MissingArgument,
        .schema_path = schema_path,
    };
}

fn parseBenchCount(value: []const u8) !usize {
    const parsed = std.fmt.parseInt(usize, value, 10) catch return error.InvalidLimit;
    if (parsed == 0) return error.InvalidLimit;
    return parsed;
}

fn parseSearchArgs(allocator: std.mem.Allocator, io: std.Io, args: []const []const u8) !ParsedSearchArgs {
    const parsed = try parseFreeTextDbArgs(allocator, io, args, 2, 1);
    errdefer parsed.deinit(allocator);

    var kind_filter: ?core.NodeKind = null;
    var project: ?[]const u8 = null;
    var schema_type: ?[]const u8 = null;
    var limit: usize = 20;
    var max_postings_scanned: usize = (core.QueryBudget{}).max_text_postings_scanned;
    var timeout_ms: u64 = (core.QueryBudget{}).timeout_ms;
    var profile: TextBudgetProfile = .interactive;
    var include_history = false;
    var include_text = false;
    var format: CliOutputFormat = .text;
    var meta = false;
    var max_postings_explicit = false;
    var timeout_explicit = false;
    var query_end = parsed.rest.len;
    while (query_end > 0) {
        if (std.mem.eql(u8, parsed.rest[query_end - 1], "--include-history")) {
            include_history = true;
            query_end -= 1;
            continue;
        }
        if (std.mem.eql(u8, parsed.rest[query_end - 1], "--include-text")) {
            include_text = true;
            query_end -= 1;
            continue;
        }
        if (std.mem.eql(u8, parsed.rest[query_end - 1], "--meta")) {
            meta = true;
            query_end -= 1;
            continue;
        }
        if (query_end < 2) break;
        const option = parsed.rest[query_end - 2];
        const value = parsed.rest[query_end - 1];
        if (std.mem.eql(u8, option, "--kind")) {
            kind_filter = parseCliNodeKind(value) orelse return error.InvalidNodeKind;
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--project")) {
            project = value;
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--schema-type")) {
            schema_type = value;
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--limit")) {
            limit = std.fmt.parseInt(usize, value, 10) catch return error.InvalidLimit;
            if (limit > (core.QueryBudget{}).max_results) return error.InvalidLimit;
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--max-postings")) {
            max_postings_scanned = std.fmt.parseInt(usize, value, 10) catch return error.InvalidLimit;
            if (max_postings_scanned > max_cli_text_postings_scanned) return error.InvalidLimit;
            max_postings_explicit = true;
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--timeout-ms")) {
            timeout_ms = std.fmt.parseInt(u64, value, 10) catch return error.InvalidLimit;
            if (timeout_ms == 0 or timeout_ms > max_cli_text_timeout_ms) return error.InvalidLimit;
            timeout_explicit = true;
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--profile")) {
            profile = try parseTextBudgetProfile(value);
            applyTextBudgetProfile(profile, &max_postings_scanned, &timeout_ms, max_postings_explicit, timeout_explicit);
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--format")) {
            format = try parseCliOutputFormat(value);
            query_end -= 2;
        } else if (std.mem.startsWith(u8, option, "--")) {
            return error.UnknownOption;
        } else {
            break;
        }
    }
    if (query_end == 0) return error.MissingArgument;
    if (meta and format != .json) return error.Unsupported;
    return .{
        .db_path = parsed.db_path,
        .query = try joinArgs(allocator, parsed.rest[0..query_end]),
        .owned_db_path = parsed.owned_db_path,
        .profile = profile,
        .kind_filter = kind_filter,
        .project = project,
        .schema_type = schema_type,
        .limit = limit,
        .include_history = include_history,
        .include_text = include_text,
        .format = format,
        .meta = meta,
        .max_postings_scanned = max_postings_scanned,
        .timeout_ms = timeout_ms,
    };
}

fn parseContextArgs(allocator: std.mem.Allocator, io: std.Io, args: []const []const u8) !ParsedContextArgs {
    const parsed = try parseFreeTextDbArgs(allocator, io, args, 2, 1);
    errdefer parsed.deinit(allocator);

    var task_id: ?core.NodeId = null;
    var root_node_id: ?core.NodeId = null;
    var profile: TextBudgetProfile = .agent_memory;
    var limit: usize = 5;
    var include_history = false;
    var format: CliOutputFormat = .json;
    var meta = false;
    var max_postings_scanned: usize = 20_000;
    var timeout_ms: u64 = 250;
    var neighbor_depth: usize = 1;
    var max_nodes: usize = 12;
    var max_edges: usize = 24;
    var max_chars: usize = 200_000;
    var markdown_preview_lines: usize = 8;
    var query_end = parsed.rest.len;
    while (query_end > 0) {
        if (std.mem.eql(u8, parsed.rest[query_end - 1], "--include-history")) {
            include_history = true;
            query_end -= 1;
            continue;
        }
        if (std.mem.eql(u8, parsed.rest[query_end - 1], "--meta")) {
            meta = true;
            query_end -= 1;
            continue;
        }
        if (query_end < 2) break;
        const option = parsed.rest[query_end - 2];
        const value = parsed.rest[query_end - 1];
        if (std.mem.eql(u8, option, "--task")) {
            task_id = try parseNodeIdArg(value);
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--node")) {
            root_node_id = try parseNodeIdArg(value);
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--limit")) {
            limit = std.fmt.parseInt(usize, value, 10) catch return error.InvalidLimit;
            if (limit == 0 or limit > (core.QueryBudget{}).max_results) return error.InvalidLimit;
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--profile")) {
            profile = try parseTextBudgetProfile(value);
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--max-postings")) {
            max_postings_scanned = std.fmt.parseInt(usize, value, 10) catch return error.InvalidLimit;
            if (max_postings_scanned == 0 or max_postings_scanned > max_cli_text_postings_scanned) return error.InvalidLimit;
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--timeout-ms")) {
            timeout_ms = std.fmt.parseInt(u64, value, 10) catch return error.InvalidLimit;
            if (timeout_ms == 0 or timeout_ms > max_cli_text_timeout_ms) return error.InvalidLimit;
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--format")) {
            format = try parseCliOutputFormat(value);
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--neighbor-depth")) {
            neighbor_depth = std.fmt.parseInt(usize, value, 10) catch return error.InvalidLimit;
            if (neighbor_depth == 0 or neighbor_depth > 8) return error.InvalidLimit;
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--max-nodes")) {
            max_nodes = std.fmt.parseInt(usize, value, 10) catch return error.InvalidLimit;
            if (max_nodes == 0 or max_nodes > (core.QueryBudget{}).max_visited_nodes) return error.InvalidLimit;
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--max-edges")) {
            max_edges = std.fmt.parseInt(usize, value, 10) catch return error.InvalidLimit;
            if (max_edges == 0 or max_edges > (core.QueryBudget{}).max_visited_edges) return error.InvalidLimit;
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--max-chars")) {
            max_chars = std.fmt.parseInt(usize, value, 10) catch return error.InvalidLimit;
            if (max_chars == 0) return error.InvalidLimit;
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--markdown-preview-lines")) {
            markdown_preview_lines = std.fmt.parseInt(usize, value, 10) catch return error.InvalidLimit;
            if (markdown_preview_lines > 200) return error.InvalidLimit;
            query_end -= 2;
        } else if (std.mem.startsWith(u8, option, "--")) {
            return error.UnknownOption;
        } else {
            break;
        }
    }
    if (query_end == 0) return error.MissingArgument;
    if (format != .json) return error.Unsupported;
    return .{
        .db_path = parsed.db_path,
        .query = try joinArgs(allocator, parsed.rest[0..query_end]),
        .owned_db_path = parsed.owned_db_path,
        .task_id = task_id,
        .root_node_id = root_node_id,
        .profile = profile,
        .limit = limit,
        .include_history = include_history,
        .format = format,
        .meta = meta,
        .max_postings_scanned = max_postings_scanned,
        .timeout_ms = timeout_ms,
        .neighbor_depth = neighbor_depth,
        .max_nodes = max_nodes,
        .max_edges = max_edges,
        .max_chars = max_chars,
        .markdown_preview_lines = markdown_preview_lines,
    };
}

fn parseQueryArgs(allocator: std.mem.Allocator, io: std.Io, args: []const []const u8) !ParsedQueryArgs {
    const parsed = try parseFreeTextDbArgs(allocator, io, args, 2, 1);
    errdefer parsed.deinit(allocator);

    var schema_path: ?[]const u8 = null;
    var max_postings_scanned: usize = (core.QueryBudget{}).max_text_postings_scanned;
    var timeout_ms: u64 = (core.QueryBudget{}).timeout_ms;
    var max_postings_explicit = false;
    var timeout_explicit = false;
    var query_end = parsed.rest.len;
    while (query_end >= 2) {
        const option = parsed.rest[query_end - 2];
        const value = parsed.rest[query_end - 1];
        if (std.mem.eql(u8, option, "--schema")) {
            schema_path = value;
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--max-postings")) {
            max_postings_scanned = std.fmt.parseInt(usize, value, 10) catch return error.InvalidLimit;
            if (max_postings_scanned > max_cli_text_postings_scanned) return error.InvalidLimit;
            max_postings_explicit = true;
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--timeout-ms")) {
            timeout_ms = std.fmt.parseInt(u64, value, 10) catch return error.InvalidLimit;
            if (timeout_ms == 0 or timeout_ms > max_cli_text_timeout_ms) return error.InvalidLimit;
            timeout_explicit = true;
            query_end -= 2;
        } else if (std.mem.eql(u8, option, "--profile")) {
            applyTextBudgetProfile(try parseTextBudgetProfile(value), &max_postings_scanned, &timeout_ms, max_postings_explicit, timeout_explicit);
            query_end -= 2;
        } else if (std.mem.startsWith(u8, option, "--")) {
            return error.UnknownOption;
        } else {
            break;
        }
    }
    if (query_end == 0) return error.MissingArgument;
    return .{
        .db_path = parsed.db_path,
        .query = try joinArgs(allocator, parsed.rest[0..query_end]),
        .owned_db_path = parsed.owned_db_path,
        .schema_path = schema_path,
        .max_postings_scanned = max_postings_scanned,
        .timeout_ms = timeout_ms,
    };
}

fn parseTrailingSchemaArg(rest: []const []const u8, positional_count: usize) !ParsedSchemaArg {
    if (rest.len == positional_count) return .{ .positionals = rest };
    if (rest.len == positional_count + 2 and std.mem.eql(u8, rest[positional_count], "--schema")) {
        return .{ .positionals = rest[0..positional_count], .schema_path = rest[positional_count + 1] };
    }
    if (rest.len > positional_count and std.mem.startsWith(u8, rest[positional_count], "--")) return error.UnknownOption;
    return error.TooManyArguments;
}

fn parseAddNodeArgs(rest: []const []const u8) !ParsedAddNodeArgs {
    if (rest.len < 2) return error.MissingArgument;
    var parsed = ParsedAddNodeArgs{
        .kind_label = rest[0],
        .text = rest[1],
    };
    var pos: usize = 2;
    while (pos < rest.len) {
        const option = rest[pos];
        if (std.mem.eql(u8, option, "--schema")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            parsed.schema_path = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--schema-type")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            parsed.schema_type = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--name")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            parsed.name = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--summary")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            parsed.summary = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--retrieval-hints") or std.mem.eql(u8, option, "--retrieval-hint")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            parsed.retrieval_hints = rest[pos + 1];
            pos += 2;
        } else if (std.mem.startsWith(u8, option, "--")) {
            return error.UnknownOption;
        } else {
            return error.TooManyArguments;
        }
    }
    return parsed;
}

fn parseUpdateNodeArgs(rest: []const []const u8) !ParsedUpdateNodeArgs {
    if (rest.len < 3) return error.MissingArgument;
    var parsed = ParsedUpdateNodeArgs{
        .node_id = rest[0],
        .kind_label = rest[1],
        .text = rest[2],
    };
    var pos: usize = 3;
    while (pos < rest.len) {
        const option = rest[pos];
        if (std.mem.eql(u8, option, "--schema")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            parsed.schema_path = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--schema-type")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            parsed.schema_type = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--name")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            parsed.name = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--summary")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            parsed.summary = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--retrieval-hints") or std.mem.eql(u8, option, "--retrieval-hint")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            parsed.retrieval_hints = rest[pos + 1];
            pos += 2;
        } else if (std.mem.startsWith(u8, option, "--")) {
            return error.UnknownOption;
        } else {
            return error.TooManyArguments;
        }
    }
    return parsed;
}

fn parseSetNodePropertyArgs(rest: []const []const u8) !ParsedSetNodePropertyArgs {
    if (rest.len != 3) return if (rest.len < 3) error.MissingArgument else error.TooManyArguments;
    const key = try normalizeNodeStringPropertyKey(rest[1]);
    return .{
        .node_id = rest[0],
        .key = key,
        .value = rest[2],
    };
}

fn parseSetEdgePropertyArgs(rest: []const []const u8) !ParsedSetEdgePropertyArgs {
    if (rest.len != 3) return if (rest.len < 3) error.MissingArgument else error.TooManyArguments;
    const key = try normalizeEdgeStringPropertyKey(rest[1]);
    return .{
        .edge_id = rest[0],
        .key = key,
        .value = rest[2],
    };
}

fn parseSetPropertyArgs(rest: []const []const u8) !ParsedSetPropertyArgs {
    if (rest.len != 4) return if (rest.len < 4) error.MissingArgument else error.TooManyArguments;
    if (std.mem.eql(u8, rest[0], "node")) {
        const node_id = try parseNodeIdArg(rest[1]);
        return .{
            .owner = .{ .node = node_id },
            .owner_label = "node",
            .key = try normalizeNodeStringPropertyKey(rest[2]),
            .value = rest[3],
        };
    }
    if (std.mem.eql(u8, rest[0], "edge")) {
        const edge_id = core.EdgeId.fromInt(std.fmt.parseInt(u64, rest[1], 10) catch return error.InvalidEdgeId);
        return .{
            .owner = .{ .edge = edge_id },
            .owner_label = "edge",
            .key = try normalizeEdgeStringPropertyKey(rest[2]),
            .value = rest[3],
        };
    }
    return error.InvalidRecord;
}

fn parseSetUintPropertyArgs(rest: []const []const u8) !ParsedSetUintPropertyArgs {
    if (rest.len != 4) return if (rest.len < 4) error.MissingArgument else error.TooManyArguments;
    const value = std.fmt.parseInt(u64, rest[3], 10) catch return error.InvalidRecord;
    if (std.mem.eql(u8, rest[0], "node")) {
        const node_id = try parseNodeIdArg(rest[1]);
        return .{
            .owner = .{ .node = node_id },
            .owner_label = "node",
            .key = try normalizeNodeUintPropertyKey(rest[2]),
            .value = value,
        };
    }
    if (std.mem.eql(u8, rest[0], "edge")) {
        const edge_id = core.EdgeId.fromInt(std.fmt.parseInt(u64, rest[1], 10) catch return error.InvalidEdgeId);
        return .{
            .owner = .{ .edge = edge_id },
            .owner_label = "edge",
            .key = try normalizeEdgeUintPropertyKey(rest[2]),
            .value = value,
        };
    }
    return error.InvalidRecord;
}

fn normalizeNodeStringPropertyKey(key: []const u8) ![]const u8 {
    const normalized = if (std.mem.eql(u8, key, "retrieval-hints"))
        "retrieval_hints"
    else
        key;
    if (!std.mem.eql(u8, normalized, "name") and
        !std.mem.eql(u8, normalized, "summary") and
        !std.mem.eql(u8, normalized, "retrieval_hints") and
        !std.mem.eql(u8, normalized, "schema_type") and
        !std.mem.eql(u8, normalized, "external_key") and
        !std.mem.eql(u8, normalized, "content_hash") and
        !std.mem.eql(u8, normalized, "source_label") and
        !std.mem.eql(u8, normalized, "task_event_type") and
        !std.mem.eql(u8, normalized, "dependency_relation"))
    {
        return error.InvalidRecord;
    }
    return normalized;
}

fn normalizeNodeUintPropertyKey(key: []const u8) ![]const u8 {
    const normalized = if (std.mem.eql(u8, key, "created-at"))
        "created_at"
    else if (std.mem.eql(u8, key, "updated-at"))
        "updated_at"
    else if (std.mem.eql(u8, key, "byte-start"))
        "byte_start"
    else if (std.mem.eql(u8, key, "byte-end"))
        "byte_end"
    else if (std.mem.eql(u8, key, "line-start"))
        "line_start"
    else if (std.mem.eql(u8, key, "line-end"))
        "line_end"
    else
        key;
    // Task lifecycle timestamps are state-machine output, not generic CLI
    // properties.  Import/migration code uses the storage API directly; the
    // public setter must not manufacture an open task with a completion time
    // (or rewrite its creation history) behind task-close.
    if (!std.mem.eql(u8, normalized, "task_event_ns") and
        !std.mem.eql(u8, normalized, "task_root_id") and
        !std.mem.eql(u8, normalized, "task_id") and
        !std.mem.eql(u8, normalized, "generation") and
        !std.mem.eql(u8, normalized, "created_at") and
        !std.mem.eql(u8, normalized, "updated_at") and
        !std.mem.eql(u8, normalized, "byte_start") and
        !std.mem.eql(u8, normalized, "byte_end") and
        !std.mem.eql(u8, normalized, "line_start") and
        !std.mem.eql(u8, normalized, "line_end"))
    {
        return error.InvalidRecord;
    }
    return normalized;
}

fn normalizeEdgeStringPropertyKey(key: []const u8) ![]const u8 {
    const normalized = if (std.mem.eql(u8, key, "markdown-attr"))
        "markdown_attr"
    else if (std.mem.eql(u8, key, "render-flags"))
        "render_flags"
    else if (std.mem.eql(u8, key, "source-span"))
        "source_span"
    else if (std.mem.eql(u8, key, "created-by"))
        "created_by"
    else
        key;
    if (!std.mem.eql(u8, normalized, "markdown_attr") and
        !std.mem.eql(u8, normalized, "render_flags") and
        !std.mem.eql(u8, normalized, "source_span") and
        !std.mem.eql(u8, normalized, "confidence") and
        !std.mem.eql(u8, normalized, "created_by") and
        // state = 分类两态位(tentative|confirmed):写入容忍模糊,闭合/纠正时结晶。
        // 值域校验在 setEdgeState 侧收口(此处只放行 key)。
        !std.mem.eql(u8, normalized, "state"))
    {
        return error.InvalidRecord;
    }
    return normalized;
}

fn normalizeEdgeUintPropertyKey(key: []const u8) ![]const u8 {
    const normalized = if (std.mem.eql(u8, key, "order-key"))
        "order_key"
    else if (std.mem.eql(u8, key, "tombstone-generation"))
        "tombstone_generation"
    else
        key;
    if (!std.mem.eql(u8, normalized, "order_key") and
        !std.mem.eql(u8, normalized, "generation") and
        !std.mem.eql(u8, normalized, "tombstone_generation"))
    {
        return error.InvalidRecord;
    }
    return normalized;
}

fn parseGovernNodeArgs(rest: []const []const u8) !ParsedGovernNodeArgs {
    if (rest.len < 3) return error.MissingArgument;
    var node_id: ?[]const u8 = rest[0];
    var parent_id: ?[]const u8 = null;
    var schema_type: ?[]const u8 = null;
    var pos: usize = 1;
    while (pos < rest.len) {
        const option = rest[pos];
        if (std.mem.eql(u8, option, "--parent")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            parent_id = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, option, "--schema-type")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            schema_type = rest[pos + 1];
            pos += 2;
        } else if (std.mem.startsWith(u8, option, "--")) {
            return error.UnknownOption;
        } else {
            if (node_id != null) return error.TooManyArguments;
            node_id = option;
            pos += 1;
        }
    }
    return .{
        .node_id = node_id orelse return error.MissingArgument,
        .parent_id = parent_id,
        .schema_type = schema_type,
    };
}

fn nodeVisibleTextFromGovernanceArgs(allocator: std.mem.Allocator, parsed: ParsedNodeTextGovernanceArgs) ![]const u8 {
    _ = allocator;
    if (parsed.task_event_metadata) |metadata| {
        try validateGovernanceMetadataToken("task_event");
        try validateGovernanceMetadataToken(metadata.event_type);
        if (metadata.dependency_relation) |relation| try validateGovernanceMetadataToken(relation);
    }
    return parsed.text;
}

fn applyNodeGovernanceProperties(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_id: core.NodeId,
    parsed: ParsedNodeTextGovernanceArgs,
    parent_id: ?[]const u8,
) !void {
    const owner: storage.PropertyOwner = .{ .node = node_id };
    const schema_type = if (parsed.task_event_metadata != null) "task_event" else parsed.schema_type orelse parsed.kind_label;
    const parent_node_id = if (parent_id) |pid| try parseNodeIdArg(pid) else null;
    var writes: [12]storage.PropertyPayloadWrite = undefined;
    var write_count: usize = 0;
    if (parsed.name) |name| {
        writes[write_count] = .{ .owner = owner, .key = "name", .value = .{ .string = name } };
        write_count += 1;
    }
    if (parsed.summary) |summary| {
        writes[write_count] = .{ .owner = owner, .key = "summary", .value = .{ .string = summary } };
        write_count += 1;
    }
    if (parsed.retrieval_hints) |retrieval_hints| {
        writes[write_count] = .{ .owner = owner, .key = "retrieval_hints", .value = .{ .string = retrieval_hints } };
        write_count += 1;
    }
    if (parent_node_id != null or parsed.schema_type != null or parsed.task_event_metadata != null) {
        writes[write_count] = .{ .owner = owner, .key = "schema_type", .value = .{ .string = schema_type } };
        write_count += 1;
    }
    if (parsed.task_event_metadata) |metadata| {
        writes[write_count] = .{ .owner = owner, .key = "task_event_type", .value = .{ .string = metadata.event_type } };
        write_count += 1;
        writes[write_count] = .{ .owner = owner, .key = "task_event_ns", .value = .{ .uint = try u128ToU64(metadata.event_ns) } };
        write_count += 1;
        writes[write_count] = .{ .owner = owner, .key = "task_root_id", .value = .{ .uint = metadata.root_id } };
        write_count += 1;
        if (metadata.task_id) |task_id| {
            writes[write_count] = .{ .owner = owner, .key = "task_id", .value = .{ .uint = task_id } };
            write_count += 1;
        }
        if (metadata.dependency_relation) |relation| {
            writes[write_count] = .{ .owner = owner, .key = "dependency_relation", .value = .{ .string = relation } };
            write_count += 1;
        }
    }
    if (parsed.recorded_ns) |recorded_ns| {
        if (nodeGovernanceNeedsTaskMetricTimestamp(parsed.kind_label, schema_type)) {
            const created_ns = parsed.task_created_ns orelse if (nodeGovernanceIsOpenTask(parsed.kind_label, schema_type)) recorded_ns else null;
            writes[write_count] = .{ .owner = owner, .key = "task_recorded_ns", .value = .{ .uint = try u128ToU64(recorded_ns) } };
            write_count += 1;
            if (created_ns) |created| {
                writes[write_count] = .{ .owner = owner, .key = "task_created_ns", .value = .{ .uint = try u128ToU64(created) } };
                write_count += 1;
            }
            if (parsed.task_completed_ns) |completed| {
                writes[write_count] = .{ .owner = owner, .key = "task_completed_ns", .value = .{ .uint = try u128ToU64(completed) } };
                write_count += 1;
            }
        }
    }
    if (write_count != 0) _ = try store.upsertPropertiesBatch(allocator, writes[0..write_count]);
    if (parent_node_id) |parent| try linkNodeToProjectParent(allocator, store, node_id, parent);
}

fn u128ToU64(value: u128) !u64 {
    return std.math.cast(u64, value) orelse error.RecordTooLarge;
}

fn writeGovernanceJsonStringField(writer: *QueryOutputWriter, field: []const u8, value: []const u8, first_field: *bool) !void {
    try writeGovernanceJsonFieldPrefix(writer, field, first_field);
    try writeJsonString(writer, value);
}

fn writeGovernanceJsonNumberField(writer: *QueryOutputWriter, field: []const u8, value: anytype, first_field: *bool) !void {
    try writeGovernanceJsonFieldPrefix(writer, field, first_field);
    try writer.print("{}", .{value});
}

fn writeGovernanceJsonFieldPrefix(writer: *QueryOutputWriter, field: []const u8, first_field: *bool) !void {
    if (first_field.*) {
        first_field.* = false;
    } else {
        try writer.writeAll(",");
    }
    try writeJsonString(writer, field);
    try writer.writeAll(":");
}

fn nodeGovernanceNeedsTaskMetricTimestamp(kind_label: []const u8, schema_type: []const u8) bool {
    return std.mem.eql(u8, kind_label, "task") or
        std.mem.eql(u8, kind_label, "verification") or
        std.mem.eql(u8, kind_label, "fix") or
        std.mem.eql(u8, schema_type, "task") or
        std.mem.eql(u8, schema_type, "verification") or
        std.mem.eql(u8, schema_type, "fix");
}

fn nodeGovernanceIsOpenTask(kind_label: []const u8, schema_type: []const u8) bool {
    return std.mem.eql(u8, kind_label, "task") or std.mem.eql(u8, schema_type, "task");
}

const TaskLifecycleMetadata = struct {
    task_created_ns: ?u128 = null,
    task_completed_ns: ?u128 = null,
};

const TaskEventMetadata = struct {
    event_type: []const u8,
    event_ns: u128,
    root_id: u64,
    task_id: ?u64 = null,
    dependency_relation: ?[]const u8 = null,

    fn deinit(self: TaskEventMetadata, allocator: std.mem.Allocator) void {
        allocator.free(self.event_type);
        if (self.dependency_relation) |relation| allocator.free(relation);
    }
};

const TaskEventNodeTextArgs = struct {
    event_type: TaskEventType,
    root_id: core.NodeId,
    task_id: ?core.NodeId = null,
    relation: ?core.RelKind = null,
    event_ns: u128,
    note: ?[]const u8 = null,
};

fn taskEventNodeText(allocator: std.mem.Allocator, args: TaskEventNodeTextArgs) ![]const u8 {
    const event_type = try taskEventTypeNameAlloc(allocator, args.event_type);
    defer allocator.free(event_type);
    _ = args.relation;
    _ = args.root_id;
    _ = args.task_id;
    _ = args.event_ns;

    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);
    try out.print("task_event {s}", .{event_type});
    if (args.note) |note| try out.print(" note={s}", .{note});
    return out.buffer.toOwnedSlice(allocator);
}

fn writeTaskEventTypeName(writer: anytype, event_type: TaskEventType) !void {
    try writer.writeAll(switch (event_type) {
        .write_attempt => "write_attempt",
        .write_error => "write_error",
        .dependency_edge_created => "dependency_edge_created",
        .dependency_edge_deleted => "dependency_edge_deleted",
        .prompt_adherence_ok => "prompt_adherence_ok",
        .prompt_adherence_miss => "prompt_adherence_miss",
    });
}

fn taskEventTypeNameAlloc(allocator: std.mem.Allocator, event_type: TaskEventType) ![]const u8 {
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);
    try writeTaskEventTypeName(&out, event_type);
    return out.buffer.toOwnedSlice(allocator);
}

fn validateTaskEventTargets(
    allocator: std.mem.Allocator,
    store: storage.Store,
    root_id: core.NodeId,
    task_id: ?core.NodeId,
) !void {
    var node_id_view = try store.openNodeByIdIndexView();
    defer node_id_view.deinit();
    if (!try node_id_view.nodeExists(root_id)) return core.Error.NotFound;
    if (task_id) |id| {
        var node = (try store.readNodeById(allocator, id)) orelse return core.Error.NotFound;
        defer node.deinit(allocator);
        if (!nodeKindCanAnchorTaskEvent(node.kind)) return core.Error.InvalidId;
    }
}

fn nodeKindCanAnchorTaskEvent(kind: core.NodeKind) bool {
    return switch (kind) {
        .task, .verification, .fix => true,
        else => false,
    };
}

fn taskLifecycleMetadataForUpdate(
    allocator: std.mem.Allocator,
    store: storage.Store,
    existing_node: storage.StoredNode,
    target_kind: core.NodeKind,
    completed_ns: u128,
) !TaskLifecycleMetadata {
    const existing_created_ns = taskMetricEpochNs(optionalU64ToU128(try store.getUintProperty(allocator, .{ .node = existing_node.id }, "task_created_ns"))) orelse
        taskMetricEpochNs(optionalU64ToU128(try store.getUintProperty(allocator, .{ .node = existing_node.id }, "task_recorded_ns"))) orelse
        completed_ns;
    const existing_completed_ns = taskMetricEpochNs(optionalU64ToU128(try store.getUintProperty(allocator, .{ .node = existing_node.id }, "task_completed_ns")));
    return switch (target_kind) {
        .task => .{ .task_created_ns = existing_created_ns },
        .verification, .fix => .{
            .task_created_ns = existing_created_ns,
            .task_completed_ns = existing_completed_ns orelse if (existing_node.kind == .task) completed_ns else null,
        },
        else => .{},
    };
}

fn taskEventMetadataForUpdate(
    allocator: std.mem.Allocator,
    store: storage.Store,
    existing_node: storage.StoredNode,
    target_kind: core.NodeKind,
    explicit_schema_type: ?[]const u8,
    fallback_event_ns: u128,
) !?TaskEventMetadata {
    if (!taskEventMetadataShouldBePreserved(target_kind, explicit_schema_type)) return null;
    return try taskEventMetadataFromProperties(allocator, store, existing_node.id, fallback_event_ns);
}

fn taskEventMetadataShouldBePreserved(target_kind: core.NodeKind, explicit_schema_type: ?[]const u8) bool {
    if (explicit_schema_type) |schema_type| return std.mem.eql(u8, schema_type, "task_event");
    return switch (target_kind) {
        .command, .error_event, .observation => true,
        else => false,
    };
}

fn taskEventMetadataFromProperties(allocator: std.mem.Allocator, store: storage.Store, node_id: core.NodeId, fallback_event_ns: u128) !?TaskEventMetadata {
    const schema_type = try store.getNodeStringProperty(allocator, node_id, "schema_type");
    defer if (schema_type) |value| allocator.free(value);
    const concrete_schema_type = schema_type orelse return null;
    if (!std.mem.eql(u8, concrete_schema_type, "task_event")) return null;

    const event_type = try store.getNodeStringProperty(allocator, node_id, "task_event_type");
    defer if (event_type) |value| allocator.free(value);
    const concrete_event_type = event_type orelse return null;
    const event_ns = taskMetricEpochNs(optionalU64ToU128(try store.getUintProperty(allocator, .{ .node = node_id }, "task_event_ns"))) orelse fallback_event_ns;
    const root_id = try store.getUintProperty(allocator, .{ .node = node_id }, "task_root_id") orelse return null;
    const task_id = try store.getUintProperty(allocator, .{ .node = node_id }, "task_id");

    var metadata = TaskEventMetadata{
        .event_type = try allocator.dupe(u8, concrete_event_type),
        .event_ns = event_ns,
        .root_id = root_id,
        .task_id = task_id,
    };
    errdefer metadata.deinit(allocator);
    metadata.dependency_relation = try store.getNodeStringProperty(allocator, node_id, "dependency_relation");
    return metadata;
}

fn exerciseTaskEventMetadataAllocationFailure(allocator: std.mem.Allocator, store: storage.Store) !void {
    const metadata = (try taskEventMetadataFromProperties(allocator, store, .fromInt(1), 7)) orelse return error.TestExpectedEqual;
    defer metadata.deinit(allocator);
    try std.testing.expectEqualStrings("write_error", metadata.event_type);
    try std.testing.expectEqual(@as(u64, 2), metadata.root_id);
    try std.testing.expectEqual(@as(?u64, 3), metadata.task_id);
    try std.testing.expectEqualStrings("depends_on", metadata.dependency_relation.?);
}

fn validateGovernanceMetadataToken(value: []const u8) !void {
    if (value.len == 0 or value.len > 128) return error.InvalidRecord;
    for (value) |byte| {
        const ok = std.ascii.isAlphanumeric(byte) or byte == '_' or byte == '-' or byte == '.' or byte == ':' or byte == '/';
        if (!ok) return error.InvalidRecord;
    }
}

fn parseOptionalTrailingSchemaArg(rest: []const []const u8, min_positionals: usize, max_positionals: usize) !ParsedSchemaArg {
    if (max_positionals < min_positionals) return error.InvalidPlan;
    const has_schema = rest.len >= 2 and std.mem.eql(u8, rest[rest.len - 2], "--schema");
    const positionals = if (has_schema) rest[0 .. rest.len - 2] else rest;
    if (positionals.len < min_positionals) return error.MissingArgument;
    if (positionals.len > max_positionals) {
        if (positionals.len > min_positionals and std.mem.startsWith(u8, positionals[min_positionals], "--")) return error.UnknownOption;
        return error.TooManyArguments;
    }
    return .{
        .positionals = positionals,
        .schema_path = if (has_schema) rest[rest.len - 1] else null,
    };
}

fn parseSchemaOnlyRestArgs(rest: []const []const u8) !ParsedSchemaArg {
    var parsed = ParsedSchemaArg{ .positionals = &.{} };
    var pos: usize = 0;
    while (pos < rest.len) {
        if (std.mem.eql(u8, rest[pos], "--schema")) {
            if (parsed.schema_path != null) return error.TooManyArguments;
            if (pos + 1 >= rest.len) return error.MissingArgument;
            parsed.schema_path = rest[pos + 1];
            pos += 2;
            continue;
        }
        if (std.mem.eql(u8, rest[pos], "--profile")) {
            if (parsed.profiles != null) return error.TooManyArguments;
            if (pos + 1 >= rest.len) return error.MissingArgument;
            parsed.profiles = rest[pos + 1];
            pos += 2;
            continue;
        }
        if (std.mem.startsWith(u8, rest[pos], "--")) return error.UnknownOption;
        return error.TooManyArguments;
    }
    return parsed;
}

fn parseFindArgs(rest: []const []const u8) !ParsedFindArgs {
    var positionals: [2][]const u8 = undefined;
    var positional_count: usize = 0;
    var schema_path: ?[]const u8 = null;
    var include_history = false;
    var pos: usize = 0;
    while (pos < rest.len) {
        const arg = rest[pos];
        if (std.mem.eql(u8, arg, "--schema")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (schema_path != null) return error.TooManyArguments;
            schema_path = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--include-history")) {
            include_history = true;
            pos += 1;
        } else if (std.mem.startsWith(u8, arg, "--")) {
            return error.UnknownOption;
        } else {
            if (positional_count >= positionals.len) return error.TooManyArguments;
            positionals[positional_count] = arg;
            positional_count += 1;
            pos += 1;
        }
    }
    if (positional_count < 2) return error.MissingArgument;
    return .{
        .kind_label = positionals[0],
        .text = positionals[1],
        .schema_path = schema_path,
        .include_history = include_history,
    };
}

fn parseNeighborsArgs(rest: []const []const u8) !ParsedNeighborsArgs {
    var positionals: [2][]const u8 = undefined;
    var positional_count: usize = 0;
    var schema_path: ?[]const u8 = null;
    var limit: ?usize = null;
    var offset: usize = 0;
    var offset_explicit = false;
    var include_history = false;
    var format: CliOutputFormat = .text;
    var meta = false;
    var depth: usize = 1;
    var max_nodes: ?usize = null;
    var max_edges: ?usize = null;
    var max_chars: ?usize = null;

    var pos: usize = 0;
    while (pos < rest.len) {
        const arg = rest[pos];
        if (std.mem.eql(u8, arg, "--schema")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (schema_path != null) return error.TooManyArguments;
            schema_path = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--limit")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (limit != null) return error.TooManyArguments;
            const parsed_limit = std.fmt.parseInt(usize, rest[pos + 1], 10) catch return error.InvalidLimit;
            if (parsed_limit == 0 or parsed_limit > (core.QueryBudget{}).max_results) return error.InvalidLimit;
            limit = parsed_limit;
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--offset")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (offset_explicit) return error.TooManyArguments;
            offset = std.fmt.parseInt(usize, rest[pos + 1], 10) catch return error.InvalidLimit;
            if (offset > (core.QueryBudget{}).max_visited_edges) return error.InvalidLimit;
            offset_explicit = true;
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--include-history")) {
            include_history = true;
            pos += 1;
        } else if (std.mem.eql(u8, arg, "--format")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            format = try parseCliOutputFormat(rest[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--meta")) {
            meta = true;
            pos += 1;
        } else if (std.mem.eql(u8, arg, "--depth")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            const parsed_depth = std.fmt.parseInt(usize, rest[pos + 1], 10) catch return error.InvalidLimit;
            if (parsed_depth == 0 or parsed_depth > 8) return error.InvalidLimit;
            depth = parsed_depth;
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--max-nodes")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (max_nodes != null) return error.TooManyArguments;
            const parsed_max_nodes = std.fmt.parseInt(usize, rest[pos + 1], 10) catch return error.InvalidLimit;
            if (parsed_max_nodes == 0 or parsed_max_nodes > (core.QueryBudget{}).max_visited_nodes) return error.InvalidLimit;
            max_nodes = parsed_max_nodes;
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--max-edges")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (max_edges != null) return error.TooManyArguments;
            const parsed_max_edges = std.fmt.parseInt(usize, rest[pos + 1], 10) catch return error.InvalidLimit;
            if (parsed_max_edges == 0 or parsed_max_edges > (core.QueryBudget{}).max_visited_edges) return error.InvalidLimit;
            max_edges = parsed_max_edges;
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--max-chars")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (max_chars != null) return error.TooManyArguments;
            const parsed_max_chars = std.fmt.parseInt(usize, rest[pos + 1], 10) catch return error.InvalidLimit;
            if (parsed_max_chars == 0) return error.InvalidLimit;
            max_chars = parsed_max_chars;
            pos += 2;
        } else if (std.mem.startsWith(u8, arg, "--")) {
            return error.UnknownOption;
        } else {
            if (positional_count >= positionals.len) return error.TooManyArguments;
            positionals[positional_count] = arg;
            positional_count += 1;
            pos += 1;
        }
    }

    if (positional_count == 0) return error.MissingArgument;
    if (offset_explicit and limit == null) return error.MissingArgument;
    if (limit) |page_limit| {
        if (offset > (core.QueryBudget{}).max_visited_edges - page_limit) return error.InvalidLimit;
    }
    if (meta and format != .json) return error.Unsupported;
    if (format != .json and (depth != 1 or max_nodes != null or max_edges != null or max_chars != null)) return error.Unsupported;
    return .{
        .node_id = positionals[0],
        .rel_label = if (positional_count > 1) positionals[1] else null,
        .schema_path = schema_path,
        .limit = limit,
        .offset = offset,
        .include_history = include_history,
        .format = format,
        .meta = meta,
        .depth = depth,
        .max_nodes = max_nodes,
        .max_edges = max_edges,
        .max_chars = max_chars,
    };
}

fn parseIncomingArgs(rest: []const []const u8) !ParsedIncomingArgs {
    var positionals: [2][]const u8 = undefined;
    var positional_count: usize = 0;
    var schema_path: ?[]const u8 = null;
    var include_history = false;
    var pos: usize = 0;
    while (pos < rest.len) {
        const arg = rest[pos];
        if (std.mem.eql(u8, arg, "--schema")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (schema_path != null) return error.TooManyArguments;
            schema_path = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--include-history")) {
            include_history = true;
            pos += 1;
        } else if (std.mem.startsWith(u8, arg, "--")) {
            return error.UnknownOption;
        } else {
            if (positional_count >= positionals.len) return error.TooManyArguments;
            positionals[positional_count] = arg;
            positional_count += 1;
            pos += 1;
        }
    }
    if (positional_count == 0) return error.MissingArgument;
    return .{
        .node_id = positionals[0],
        .rel_label = if (positional_count > 1) positionals[1] else null,
        .schema_path = schema_path,
        .include_history = include_history,
    };
}

fn parseTaskPacketArgs(rest: []const []const u8) !ParsedTaskPacketArgs {
    var task_id: ?[]const u8 = null;
    var limit: usize = 8;
    var format: CliOutputFormat = .text;
    var meta = false;
    var max_nodes: ?usize = null;
    var max_edges: ?usize = null;
    var max_chars: ?usize = null;

    var pos: usize = 0;
    while (pos < rest.len) {
        const arg = rest[pos];
        if (std.mem.eql(u8, arg, "--limit")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            const parsed_limit = std.fmt.parseInt(usize, rest[pos + 1], 10) catch return error.InvalidLimit;
            if (parsed_limit == 0 or parsed_limit > (core.QueryBudget{}).max_results) return error.InvalidLimit;
            limit = parsed_limit;
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--format")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            format = try parseCliOutputFormat(rest[pos + 1]);
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--meta")) {
            meta = true;
            pos += 1;
        } else if (std.mem.eql(u8, arg, "--max-nodes")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (max_nodes != null) return error.TooManyArguments;
            const parsed_max_nodes = std.fmt.parseInt(usize, rest[pos + 1], 10) catch return error.InvalidLimit;
            if (parsed_max_nodes == 0 or parsed_max_nodes > (core.QueryBudget{}).max_visited_nodes) return error.InvalidLimit;
            max_nodes = parsed_max_nodes;
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--max-edges")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (max_edges != null) return error.TooManyArguments;
            const parsed_max_edges = std.fmt.parseInt(usize, rest[pos + 1], 10) catch return error.InvalidLimit;
            if (parsed_max_edges == 0 or parsed_max_edges > (core.QueryBudget{}).max_visited_edges) return error.InvalidLimit;
            max_edges = parsed_max_edges;
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--max-chars")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (max_chars != null) return error.TooManyArguments;
            const parsed_max_chars = std.fmt.parseInt(usize, rest[pos + 1], 10) catch return error.InvalidLimit;
            if (parsed_max_chars == 0) return error.InvalidLimit;
            max_chars = parsed_max_chars;
            pos += 2;
        } else if (std.mem.startsWith(u8, arg, "--")) {
            return error.UnknownOption;
        } else {
            if (task_id != null) return error.TooManyArguments;
            task_id = arg;
            pos += 1;
        }
    }

    if (meta and format != .json) return error.Unsupported;
    if (format != .json and (max_nodes != null or max_edges != null or max_chars != null)) return error.Unsupported;
    return .{
        .task_id = task_id orelse return error.MissingArgument,
        .limit = limit,
        .format = format,
        .meta = meta,
        .max_nodes = max_nodes,
        .max_edges = max_edges,
        .max_chars = max_chars,
    };
}

fn parseTaskFrontierArgs(rest: []const []const u8) !ParsedTaskFrontierArgs {
    var root_id: ?[]const u8 = null;
    var limit: usize = 8;
    var mine: ?[]const u8 = null;
    var unclaimed = false;

    var pos: usize = 0;
    while (pos < rest.len) {
        const arg = rest[pos];
        if (std.mem.eql(u8, arg, "--limit")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            const parsed_limit = std.fmt.parseInt(usize, rest[pos + 1], 10) catch return error.InvalidLimit;
            if (parsed_limit == 0 or parsed_limit > (core.QueryBudget{}).max_results) return error.InvalidLimit;
            limit = parsed_limit;
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--mine")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            mine = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--unclaimed")) {
            unclaimed = true;
            pos += 1;
        } else if (std.mem.startsWith(u8, arg, "--")) {
            return error.UnknownOption;
        } else {
            if (root_id != null) return error.TooManyArguments;
            root_id = arg;
            pos += 1;
        }
    }
    if (mine != null and unclaimed) return error.TooManyArguments;

    return .{
        .root_id = root_id orelse return error.MissingArgument,
        .limit = limit,
        .mine = mine,
        .unclaimed = unclaimed,
    };
}

/// agent 身份校验。身份**必须由宿主程序注入**(如 metacodes 为每个 agent loop
/// 生成的全局唯一 session id,经 --by 显式传参):env 是进程级的,单进程多 agent
/// loop 会串;让 LLM 自己发明/记住 id 更是伪命题(编造、跨轮遗忘、互相撞)。
fn validateAgentIdentity(agent_name: []const u8) ![]const u8 {
    // 参数校验错误就报参数错误(Linus #3):InvalidRecord 是存储层"记录坏了",
    // 拿来报"身份太长"会诱导调用方去跑 repair。
    if (agent_name.len == 0 or agent_name.len > task.max_claim_holder_len) return error.InvalidArgument;
    return agent_name;
}

fn ensureTaskStatusProperty(
    allocator: std.mem.Allocator,
    store: storage.Store,
    task_id: core.NodeId,
) !void {
    const existing = try store.getNodeStringProperty(allocator, task_id, task.status_property);
    defer if (existing) |value| allocator.free(value);
    // Pre-status tasks may already carry a live legacy lease. Materializing
    // `open` unconditionally would create the contradictory state
    // `status=open + future claim_expires_ns`, poisoning all strict readers.
    // Evaluate the complete lifecycle first, including when status already
    // exists: merely parsing the enum would accept malformed terminal audit
    // fields or contradictory leases.
    const effective = try task.statusWithPersistentStore(allocator, store, task_id);
    if (existing != null) return;
    try store.setNodeStringProperty(allocator, task_id, task.status_property, @tagName(effective));
}

fn validateTaskLifecycleFieldsForRewrite(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_id: core.NodeId,
    now_ns: u64,
) !void {
    var snapshot = try task.StatusSnapshot.initForNodeIds(allocator, store, &.{node_id});
    defer snapshot.deinit();
    _ = try task.effectiveStatusForLifecycleFields(snapshot.fields(node_id), now_ns, .strict);
}

fn forEachVisibleEdgeRecordByNode(
    allocator: std.mem.Allocator,
    store: storage.Store,
    order: storage.EdgeIndexOrder,
    node_id: core.NodeId,
    rel_filter: ?core.RelKind,
    context: anytype,
    comptime callback: fn (@TypeOf(context), storage.EdgeIndexRecord) anyerror!bool,
) !bool {
    const Adapter = struct {
        inner: @TypeOf(context),

        fn visit(self: *@This(), edge: query_index.EdgeRef) !bool {
            return callback(self.inner, .{
                .src = edge.src.toInt(),
                .dst = edge.dst.toInt(),
                .edge_id = edge.edge_id.toInt(),
                .rel = @intFromEnum(edge.rel),
            });
        }
    };
    var adapter = Adapter{ .inner = context };
    const cursor = query.EdgeCursor{ .persistent_store = .{
        .allocator = allocator,
        .store = store,
    } };
    return switch (order) {
        .src => cursor.forEachOutgoingRelation(node_id, rel_filter, &adapter, Adapter.visit),
        .dst => cursor.forEachIncomingRelation(node_id, rel_filter, &adapter, Adapter.visit),
        .id => core.Error.Unsupported,
    };
}

const VisibleEdgeRecordCollection = struct {
    records: std.ArrayList(storage.EdgeIndexRecord),
    truncated: bool,
};

fn collectVisibleEdgeRecordsByNodeLimited(
    allocator: std.mem.Allocator,
    store: storage.Store,
    order: storage.EdgeIndexOrder,
    node_id: core.NodeId,
    rel_filter: ?core.RelKind,
    max_records: usize,
) !VisibleEdgeRecordCollection {
    const CollectContext = struct {
        allocator: std.mem.Allocator,
        records: *std.ArrayList(storage.EdgeIndexRecord),
        max_records: usize,

        fn visit(self: *@This(), record: storage.EdgeIndexRecord) !bool {
            if (self.records.items.len >= self.max_records) return true;
            try self.records.append(self.allocator, record);
            return false;
        }
    };
    var records = std.ArrayList(storage.EdgeIndexRecord).empty;
    errdefer records.deinit(allocator);
    var context = CollectContext{
        .allocator = allocator,
        .records = &records,
        .max_records = max_records,
    };
    const truncated = try forEachVisibleEdgeRecordByNode(allocator, store, order, node_id, rel_filter, &context, CollectContext.visit);
    return .{ .records = records, .truncated = truncated };
}

/// Deliberately returns a prefix when the adjacency exceeds `max_records`.
/// Callers must expose their own truncation semantics; correctness checks use
/// the complete variant below instead.
fn readVisibleEdgeRecordsByNodeLimited(
    allocator: std.mem.Allocator,
    store: storage.Store,
    order: storage.EdgeIndexOrder,
    node_id: core.NodeId,
    rel_filter: ?core.RelKind,
    max_records: usize,
) !std.ArrayList(storage.EdgeIndexRecord) {
    const collected = try collectVisibleEdgeRecordsByNodeLimited(allocator, store, order, node_id, rel_filter, max_records);
    return collected.records;
}

/// A bounded complete read: refuse to turn edge pressure into an incomplete
/// answer when callers use the result for lifecycle or graph invariants.
fn readVisibleEdgeRecordsByNodeCompleteLimited(
    allocator: std.mem.Allocator,
    store: storage.Store,
    order: storage.EdgeIndexOrder,
    node_id: core.NodeId,
    rel_filter: ?core.RelKind,
    max_records: usize,
) !std.ArrayList(storage.EdgeIndexRecord) {
    var collected = try collectVisibleEdgeRecordsByNodeLimited(allocator, store, order, node_id, rel_filter, max_records);
    if (collected.truncated) {
        collected.records.deinit(allocator);
        return core.Error.BudgetExceeded;
    }
    return collected.records;
}

fn readVisibleEdgeRecordsByNode(
    allocator: std.mem.Allocator,
    store: storage.Store,
    order: storage.EdgeIndexOrder,
    node_id: core.NodeId,
    rel_filter: ?core.RelKind,
) !std.ArrayList(storage.EdgeIndexRecord) {
    return try readVisibleEdgeRecordsByNodeCompleteLimited(
        allocator,
        store,
        order,
        node_id,
        rel_filter,
        (core.QueryBudget{}).max_visited_edges,
    );
}

fn taskEdgeLookaheadLimit(limit: usize) usize {
    const cursor_budget = (core.QueryBudget{}).max_visited_edges;
    if (cursor_budget == 0) return 0;
    // Reserve one cursor visit for the caller's truncation lookahead.  Asking
    // for the full cursor budget would fail before that extra edge reached the
    // callback, turning an intentionally bounded metric into BudgetExceeded.
    return @min(cursor_budget - 1, limit +| 1);
}

fn taskHasNonCompletedChildren(
    allocator: std.mem.Allocator,
    store: storage.Store,
    task_id: core.NodeId,
    now_ns: u64,
) !bool {
    var records = try readVisibleEdgeRecordsByNode(allocator, store, .src, task_id, .contains);
    defer records.deinit(allocator);
    var child_ids = std.ArrayList(core.NodeId).empty;
    defer child_ids.deinit(allocator);
    for (records.items) |record| {
        try child_ids.append(allocator, .fromInt(record.dst));
    }
    if (child_ids.items.len == 0) return false;
    var status_snapshot = try task.StatusSnapshot.initForNodeIds(allocator, store, child_ids.items);
    defer status_snapshot.deinit();
    var node_view = try store.openNodeRecordView();
    defer node_view.deinit();
    for (child_ids.items) |child_id| {
        var child = (try node_view.readNodeById(allocator, child_id)) orelse return error.InvalidRecord;
        defer child.deinit(allocator);
        if (child.kind == .task) {
            if ((try status_snapshot.statusForStoredNode(child, now_ns)) != .completed) return true;
        } else if (status_snapshot.isLegacyClosedTaskNode(child)) {
            continue;
        }
    }
    return false;
}

/// Validate a terminal transition without mutating the store. `force` is
/// intentionally limited to lease ownership: it never bypasses dependency or
/// child-completion invariants. Terminal same-status retries skip lease checks
/// so a crash after the status commit marker remains safely idempotent.
fn validateTaskCloseTransition(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node: storage.StoredNode,
    requested_status: task.Status,
    by: ?[]const u8,
    force: bool,
    now_ns: u64,
) !task.Status {
    if (node.kind != .task or !requested_status.isTerminal()) return error.InvalidTaskTransition;
    const validated_by = if (by) |identity| try validateAgentIdentity(identity) else null;
    var lifecycle_snapshot = try task.StatusSnapshot.initForNodeIds(allocator, store, &.{node.id});
    defer lifecycle_snapshot.deinit();
    const lifecycle = try lifecycle_snapshot.statusForStoredNode(node, now_ns);
    if (lifecycle.isTerminal()) {
        if (lifecycle != requested_status) return error.InvalidTaskTransition;
        return lifecycle;
    }

    const lifecycle_fields = lifecycle_snapshot.fields(node.id);
    const holder = lifecycle_fields.claimed_by;
    const held_expires = lifecycle_fields.claim_expires_ns orelse 0;
    const lease_live = holder != null and holder.?.len != 0 and held_expires > now_ns;
    if (lease_live and !force) {
        const by_matches = if (validated_by) |identity| std.mem.eql(u8, identity, holder.?) else false;
        if (!by_matches) return error.ClaimHeld;
    }

    if (requested_status == .completed) {
        if (try taskHasNonCompletedChildren(allocator, store, node.id, now_ns)) return error.TaskHasOpenChildren;
        if ((try task.readyStateWithPersistentStoreSnapshotAt(allocator, store, node.id, now_ns, &lifecycle_snapshot)) != .ready) return error.TaskNotReady;
    }
    return lifecycle;
}

fn taskEvidenceKindAllowed(kind: core.NodeKind) bool {
    return switch (kind) {
        .verification, .evidence, .error_event, .fix, .observation => true,
        else => false,
    };
}

fn ensureTaskEvidenceEdge(
    allocator: std.mem.Allocator,
    store: storage.Store,
    task_id: core.NodeId,
    evidence_id: core.NodeId,
) !void {
    var evidence = (try store.readNodeById(allocator, evidence_id)) orelse return core.Error.NotFound;
    defer evidence.deinit(allocator);
    if (!taskEvidenceKindAllowed(evidence.kind)) return core.Error.InvalidId;

    var records = try readVisibleEdgeRecordsByNode(allocator, store, .src, task_id, .verified_by);
    defer records.deinit(allocator);
    for (records.items) |record| {
        if (record.dst == evidence_id.toInt()) return;
    }
    _ = try dag.addEdgeCheckedWithPersistentStore(allocator, store, task_id, .verified_by, evidence_id, .{});
}

/// Find-or-create verification evidence after task-close authorization has
/// succeeded and while the same CLI store lock is still held. This closes the
/// client-side race where an invalid lease holder could create an orphan
/// verification before task-close rejected the transition. The evidence node
/// and edge intentionally precede the terminal property batch: both writes are
/// idempotent, so a crash can be retried without duplicating evidence.
fn ensureTaskEvidenceTextNode(
    allocator: std.mem.Allocator,
    store: storage.Store,
    text: []const u8,
    recorded_ns: u128,
) !core.NodeId {
    const governance_args = ParsedNodeTextGovernanceArgs{
        .kind_label = "verification",
        .text = text,
        .schema_type = "verification",
        .recorded_ns = recorded_ns,
    };
    try validateNodeWriteGranularity(governance_args);
    const candidate_limit = currentGenerationLookupCandidateLimit(1);
    var matches = store.lookupNodesByTextLimited(allocator, .verification, text, candidate_limit) catch |err| switch (err) {
        error.FileNotFound, error.InvalidRecord => retry: {
            try store.repairPersistentIndexesFromLog();
            break :retry try store.lookupNodesByTextLimited(allocator, .verification, text, candidate_limit);
        },
        else => |e| return e,
    };
    defer {
        for (matches.items) |*node| node.deinit(allocator);
        matches.deinit(allocator);
    }
    for (matches.items) |*node| {
        if (try nodeIsCurrentGeneration(store, node.id)) return node.id;
    }
    const id = try store.addNode(.verification, text);
    try applyNodeGovernanceProperties(allocator, store, id, governance_args, null);
    return id;
}

const ParsedTaskClaimArgs = struct {
    task_id: []const u8,
    by: ?[]const u8,
    ttl_s: u64,
    steal: bool,
};

const ParsedTaskReleaseArgs = struct {
    task_id: []const u8,
    by: ?[]const u8,
    force: bool,
};

const ParsedTaskCloseArgs = struct {
    task_id: []const u8,
    status: task.Status,
    by: ?[]const u8,
    evidence_id: ?[]const u8,
    evidence_text: ?[]const u8,
    force: bool,
};

fn parseTaskCloseArgs(rest: []const []const u8) !ParsedTaskCloseArgs {
    var task_id: ?[]const u8 = null;
    var close_status: ?task.Status = null;
    var by: ?[]const u8 = null;
    var evidence_id: ?[]const u8 = null;
    var evidence_text: ?[]const u8 = null;
    var force = false;
    var force_explicit = false;

    var pos: usize = 0;
    while (pos < rest.len) {
        const arg = rest[pos];
        if (std.mem.eql(u8, arg, "--by")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (by != null) return error.TooManyArguments;
            by = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--evidence")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (evidence_id != null or evidence_text != null) return error.TooManyArguments;
            evidence_id = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--evidence-text")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (evidence_id != null or evidence_text != null) return error.TooManyArguments;
            evidence_text = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--force")) {
            if (force_explicit) return error.TooManyArguments;
            force = true;
            force_explicit = true;
            pos += 1;
        } else if (std.mem.startsWith(u8, arg, "--")) {
            return error.UnknownOption;
        } else if (task_id == null) {
            task_id = arg;
            pos += 1;
        } else if (close_status == null) {
            const parsed = task.Status.parse(arg) orelse return error.InvalidStatus;
            if (parsed != .completed and parsed != .failed) return error.InvalidStatus;
            close_status = parsed;
            pos += 1;
        } else {
            return error.TooManyArguments;
        }
    }

    return .{
        .task_id = task_id orelse return error.MissingArgument,
        .status = close_status orelse return error.MissingArgument,
        .by = by,
        .evidence_id = evidence_id,
        .evidence_text = evidence_text,
        .force = force,
    };
}

