fn parseTaskClaimArgs(rest: []const []const u8) !ParsedTaskClaimArgs {
    var task_id: ?[]const u8 = null;
    var agent_arg: ?[]const u8 = null;
    var ttl_s: u64 = task_claim_default_ttl_s;
    var ttl_explicit = false;
    var steal = false;
    var steal_explicit = false;

    var pos: usize = 0;
    while (pos < rest.len) {
        const arg = rest[pos];
        if (std.mem.eql(u8, arg, "--by")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (agent_arg != null) return error.TooManyArguments;
            agent_arg = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--ttl-s")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (ttl_explicit) return error.TooManyArguments;
            ttl_s = std.fmt.parseInt(u64, rest[pos + 1], 10) catch return error.InvalidLimit;
            if (ttl_s == 0) return error.InvalidLimit;
            ttl_explicit = true;
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--steal")) {
            if (steal_explicit) return error.TooManyArguments;
            steal = true;
            steal_explicit = true;
            pos += 1;
        } else if (std.mem.startsWith(u8, arg, "--")) {
            return error.UnknownOption;
        } else {
            if (task_id != null) return error.TooManyArguments;
            task_id = arg;
            pos += 1;
        }
    }

    return .{
        .task_id = task_id orelse return error.MissingArgument,
        .by = agent_arg,
        .ttl_s = ttl_s,
        .steal = steal,
    };
}

fn parseTaskAncestryArgs(rest: []const []const u8) !ParsedTaskAncestryArgs {
    var task_id: ?[]const u8 = null;
    var depth: usize = 3;
    var limit: usize = 16;

    var pos: usize = 0;
    while (pos < rest.len) {
        const arg = rest[pos];
        if (std.mem.eql(u8, arg, "--depth")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            const parsed_depth = std.fmt.parseInt(usize, rest[pos + 1], 10) catch return error.InvalidLimit;
            if (parsed_depth == 0 or parsed_depth > 8) return error.InvalidLimit;
            depth = parsed_depth;
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--limit")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            const parsed_limit = std.fmt.parseInt(usize, rest[pos + 1], 10) catch return error.InvalidLimit;
            if (parsed_limit == 0 or parsed_limit > (core.QueryBudget{}).max_results) return error.InvalidLimit;
            limit = parsed_limit;
            pos += 2;
        } else if (std.mem.startsWith(u8, arg, "--")) {
            return error.UnknownOption;
        } else {
            if (task_id != null) return error.TooManyArguments;
            task_id = arg;
            pos += 1;
        }
    }

    return .{
        .task_id = task_id orelse return error.MissingArgument,
        .depth = depth,
        .limit = limit,
    };
}

