fn parseTaskEventArgs(rest: []const []const u8) !ParsedTaskEventArgs {
    var root_id: ?[]const u8 = null;
    var event_type: ?TaskEventType = null;
    var task_id: ?[]const u8 = null;
    var relation_label: ?[]const u8 = null;
    var note: ?[]const u8 = null;

    var pos: usize = 0;
    while (pos < rest.len) {
        const arg = rest[pos];
        if (std.mem.eql(u8, arg, "--task")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (task_id != null) return error.TooManyArguments;
            task_id = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--relation") or std.mem.eql(u8, arg, "--rel")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (relation_label != null) return error.TooManyArguments;
            relation_label = rest[pos + 1];
            pos += 2;
        } else if (std.mem.eql(u8, arg, "--note")) {
            if (pos + 1 >= rest.len) return error.MissingArgument;
            if (note != null) return error.TooManyArguments;
            note = rest[pos + 1];
            pos += 2;
        } else if (std.mem.startsWith(u8, arg, "--")) {
            return error.UnknownOption;
        } else {
            if (root_id == null) {
                root_id = arg;
            } else if (event_type == null) {
                event_type = parseTaskEventType(arg) orelse return error.InvalidRecord;
            } else {
                return error.TooManyArguments;
            }
            pos += 1;
        }
    }

    const parsed_event_type = event_type orelse return error.MissingArgument;
    if (taskEventRequiresRelation(parsed_event_type) and relation_label == null) return error.MissingArgument;
    return .{
        .root_id = root_id orelse return error.MissingArgument,
        .event_type = parsed_event_type,
        .task_id = task_id,
        .relation_label = relation_label,
        .note = note,
    };
}

fn parseTaskEventType(value: []const u8) ?TaskEventType {
    if (std.mem.eql(u8, value, "write_attempt")) return .write_attempt;
    if (std.mem.eql(u8, value, "write_error")) return .write_error;
    if (std.mem.eql(u8, value, "dependency_edge_created")) return .dependency_edge_created;
    if (std.mem.eql(u8, value, "dependency_edge_deleted")) return .dependency_edge_deleted;
    if (std.mem.eql(u8, value, "prompt_adherence_ok")) return .prompt_adherence_ok;
    if (std.mem.eql(u8, value, "prompt_adherence_miss")) return .prompt_adherence_miss;
    return null;
}

fn taskEventRequiresRelation(event_type: TaskEventType) bool {
    return switch (event_type) {
        .dependency_edge_created, .dependency_edge_deleted => true,
        .write_attempt, .write_error, .prompt_adherence_ok, .prompt_adherence_miss => false,
    };
}

fn parseOptionalSchemaOnlyArgs(args: []const []const u8, start: usize) !ParsedSchemaArg {
    var parsed = ParsedSchemaArg{ .positionals = &.{} };
    var pos = start;
    while (pos < args.len) {
        if (std.mem.eql(u8, args[pos], "--schema")) {
            if (parsed.schema_path != null) return error.TooManyArguments;
            if (pos + 1 >= args.len) return error.MissingArgument;
            parsed.schema_path = args[pos + 1];
            pos += 2;
            continue;
        }
        if (std.mem.eql(u8, args[pos], "--profile")) {
            if (parsed.profiles != null) return error.TooManyArguments;
            if (pos + 1 >= args.len) return error.MissingArgument;
            parsed.profiles = args[pos + 1];
            pos += 2;
            continue;
        }
        if (std.mem.startsWith(u8, args[pos], "--")) return error.UnknownOption;
        return error.TooManyArguments;
    }
    return parsed;
}

fn loadSchemaRegistryFromSchemaArg(allocator: std.mem.Allocator, io: std.Io, parsed: ParsedSchemaArg) !schema.Registry {
    var registry = if (parsed.schema_path) |path| try loadSchemaRegistryFile(allocator, io, path) else blk: {
        var base = schema.Registry.init(allocator);
        errdefer base.deinit();
        try base.addKernelTypes();
        break :blk base;
    };
    errdefer registry.deinit();
    if (parsed.profiles) |profiles| try addBuiltinProfilesFromCsv(&registry, profiles);
    return registry;
}

fn schemaArgLabelAlloc(allocator: std.mem.Allocator, parsed: ParsedSchemaArg) ![]u8 {
    if (parsed.schema_path) |path| {
        if (parsed.profiles) |profiles| return try std.fmt.allocPrint(allocator, "{s}+profiles:{s}", .{ path, profiles });
        return try allocator.dupe(u8, path);
    }
    if (parsed.profiles) |profiles| return try std.fmt.allocPrint(allocator, "kernel+profiles:{s}", .{profiles});
    return try allocator.dupe(u8, "kernel");
}

const EffectiveSchemaRegistry = struct {
    registry: schema.Registry,
    enforce_application_schema: bool,

    fn deinit(self: *EffectiveSchemaRegistry) void {
        self.registry.deinit();
        self.* = undefined;
    }
};

fn loadEffectiveSchemaRegistry(
    allocator: std.mem.Allocator,
    io: std.Io,
    store: storage.Store,
    schema_path: ?[]const u8,
) !EffectiveSchemaRegistry {
    if (schema_path) |path| {
        return .{
            .registry = try loadSchemaRegistryFile(allocator, io, path),
            .enforce_application_schema = true,
        };
    }
    if (try store.readCatalog()) |catalog_value| {
        var source_catalog = catalog_value;
        defer source_catalog.deinit();
        const enforce_application_schema = catalogHasApplicationSchema(source_catalog);
        const registry = source_catalog.registry;
        // Transfer registry ownership out of the decoded catalog while still
        // letting its profile/retired metadata follow the normal deinit path.
        source_catalog.registry = schema.Registry.init(allocator);
        return .{
            .registry = registry,
            .enforce_application_schema = enforce_application_schema,
        };
    }
    var registry = schema.Registry.init(allocator);
    errdefer registry.deinit();
    try registry.addKernelTypes();
    return .{
        .registry = registry,
        .enforce_application_schema = false,
    };
}

fn parseNodeKindWithSchemaPolicy(label: []const u8, registry: schema.Registry, enforce_application_schema: bool) !core.NodeKind {
    if (registry.findNodeType(label)) |id| return @enumFromInt(id);
    const kind = parseCliNodeKind(label) orelse return error.UnknownNodeKind;
    if (enforce_application_schema and !registry.hasNodeTypeId(@intFromEnum(kind))) return error.UnknownNodeKind;
    return kind;
}

fn parseRelKindWithLoadedSchema(label: []const u8, registry: ?schema.Registry) !core.RelKind {
    if (registry) |loaded| {
        const id = loaded.findRelationType(label) orelse if (parseCliRelKind(label)) |rel| @intFromEnum(rel) else return error.UnknownRelationKind;
        return @enumFromInt(id);
    }
    return parseCliRelKind(label) orelse return error.InvalidRelKind;
}

fn parseRelKindWithSchemaPolicy(label: []const u8, registry: schema.Registry, enforce_application_schema: bool) !core.RelKind {
    if (registry.findRelationType(label)) |id| return @enumFromInt(id);
    const rel = parseCliRelKind(label) orelse return error.UnknownRelationKind;
    if (enforce_application_schema and !registry.hasRelationTypeId(@intFromEnum(rel))) return error.UnknownRelationKind;
    return rel;
}

fn parseCliNodeKind(label: []const u8) ?core.NodeKind {
    if (core.parseNodeKind(label)) |kind| return kind;
    if (std.ascii.eqlIgnoreCase(label, "note")) return .observation;
    if (std.mem.startsWith(u8, label, "type#")) {
        const id = std.fmt.parseInt(u16, label["type#".len..], 10) catch return null;
        return @enumFromInt(id);
    }
    return null;
}

fn parseCliRelKind(label: []const u8) ?core.RelKind {
    if (core.parseRelKind(label)) |rel| return rel;
    if (schema.markdownProjectionRelationIdByName(label)) |id| return @enumFromInt(id);
    if (std.ascii.eqlIgnoreCase(label, "supports")) return .evidences;
    if (std.mem.startsWith(u8, label, "rel#")) {
        const id = std.fmt.parseInt(u16, label["rel#".len..], 10) catch return null;
        return @enumFromInt(id);
    }
    return null;
}

fn parseDbArgs(
    allocator: std.mem.Allocator,
    io: std.Io,
    args: []const []const u8,
    start: usize,
    min_rest: usize,
    max_rest: usize,
    require_existing_db: bool,
) !ParsedDbArgs {
    if (args.len < start) return error.MissingArgument;
    if (max_rest < min_rest) return error.InvalidPlan;

    const remaining_default = args[start..];
    const default_valid = remaining_default.len >= min_rest and remaining_default.len <= max_rest;
    if (args.len == start) {
        if (default_valid) return .{ .db_path = defaultDbPath(), .rest = remaining_default };
        return error.MissingArgument;
    }

    const candidate = args[start];
    const remaining_if_db = if (args.len > start + 1) args[start + 1 ..] else &.{};
    const db_valid = remaining_if_db.len >= min_rest and remaining_if_db.len <= max_rest;

    if (default_valid and db_valid) {
        if (try existingTinyKgStorePath(allocator, io, candidate)) {
            return .{ .db_path = candidate, .rest = remaining_if_db };
        }
        if (require_existing_db and looksLikeExplicitDbPath(candidate)) return error.FileNotFound;
        return .{ .db_path = defaultDbPath(), .rest = remaining_default };
    }
    if (default_valid) return .{ .db_path = defaultDbPath(), .rest = remaining_default };
    if (db_valid) {
        if (require_existing_db and !try existingTinyKgStorePath(allocator, io, candidate)) {
            if (remaining_default.len < min_rest) return error.MissingArgument;
            if (looksLikeExplicitDbPath(candidate)) return error.FileNotFound;
            return error.TooManyArguments;
        }
        return .{ .db_path = candidate, .rest = remaining_if_db };
    }
    if (remaining_default.len < min_rest) return error.MissingArgument;
    return error.TooManyArguments;
}

fn looksLikeExplicitDbPath(value: []const u8) bool {
    if (std.mem.eql(u8, value, default_db_path)) return true;
    return std.mem.indexOfScalar(u8, value, '/') != null or std.mem.indexOfScalar(u8, value, '\\') != null;
}

fn pathExists(io: std.Io, path: []const u8) !bool {
    var dir = std.Io.Dir.cwd().openDir(io, path, .{}) catch |err| switch (err) {
        error.FileNotFound => return false,
        else => |e| return e,
    };
    dir.close(io);
    return true;
}

fn anyPathExists(io: std.Io, path: []const u8) !bool {
    var dir = std.Io.Dir.cwd().openDir(io, path, .{}) catch |dir_err| switch (dir_err) {
        error.FileNotFound, error.NotDir => {
            var file = std.Io.Dir.cwd().openFile(io, path, .{}) catch |file_err| switch (file_err) {
                error.FileNotFound, error.NotDir => return false,
                error.IsDir => return true,
                else => |e| return e,
            };
            defer file.close(io);
            return true;
        },
        else => |e| return e,
    };
    dir.close(io);
    return true;
}

fn parseFreeTextDbArgs(allocator: std.mem.Allocator, io: std.Io, args: []const []const u8, start: usize, min_rest: usize) !ParsedFreeTextDbArgs {
    if (args.len <= start) return error.MissingArgument;

    const candidate = args[start];
    const remaining_if_db = if (args.len > start + 1) args[start + 1 ..] else &.{};
    if (try existingTinyKgStorePath(allocator, io, candidate)) {
        if (remaining_if_db.len < min_rest) return error.MissingArgument;
        const owned = try allocator.dupe(u8, candidate);
        return .{ .db_path = owned, .rest = remaining_if_db, .owned_db_path = owned };
    }
    if (looksLikeExplicitDbPath(candidate)) return error.FileNotFound;

    const remaining_default = args[start..];
    if (remaining_default.len < min_rest) return error.MissingArgument;
    return .{ .db_path = defaultDbPath(), .rest = remaining_default };
}

fn existingTinyKgStorePath(allocator: std.mem.Allocator, io: std.Io, db_path: []const u8) !bool {
    const path = try std.fs.path.join(allocator, &.{ db_path, "events.bin" });
    defer allocator.free(path);
    return fileExists(io, path);
}

fn fileExists(io: std.Io, path: []const u8) !bool {
    var file = std.Io.Dir.cwd().openFile(io, path, .{}) catch |err| switch (err) {
        error.FileNotFound => return false,
        error.NotDir => return false,
        error.IsDir => return false,
        // Free-text commands probe their first token to distinguish an
        // optional database path from query text.  TinyQL labels contain ':';
        // that is valid query syntax but an invalid Windows filename.
        error.BadPathName, error.NameTooLong => return false,
        else => |e| return e,
    };
    defer file.close(io);
    return (try file.stat(io)).kind == .file;
}

fn storeFileSize(allocator: std.mem.Allocator, io: std.Io, db_path: []const u8, file_name: []const u8) !?u64 {
    const path = try std.fs.path.join(allocator, &.{ db_path, file_name });
    defer allocator.free(path);
    const stat = std.Io.Dir.cwd().statFile(io, path, .{}) catch |err| switch (err) {
        error.FileNotFound, error.NotDir => return null,
        else => |e| return e,
    };
    if (stat.kind != .file) return null;
    return stat.size;
}

fn persistentTextCatalogFilesPresent(allocator: std.mem.Allocator, io: std.Io, db_path: []const u8) !bool {
    const text_docs_exists = (try storeFileSize(allocator, io, db_path, "text_docs.idx")) != null;
    const text_terms_exists = (try storeFileSize(allocator, io, db_path, "text_terms.idx")) != null;
    const text_postings_exists = (try storeFileSize(allocator, io, db_path, "text_postings.dat")) != null;
    return text_docs_exists and text_terms_exists and text_postings_exists;
}

fn persistentTextCatalogWarm(
    allocator: std.mem.Allocator,
    io: std.Io,
    store: storage.Store,
    db_path: []const u8,
) !bool {
    if (!try persistentTextCatalogFilesPresent(allocator, io, db_path)) return false;
    return !try text_search.persistentTextCatalogQuickStale(allocator, store);
}

fn printOptionalBytes(writer: anytype, comptime key: []const u8, value: ?u64) !void {
    try writer.print("{s}={}\n", .{ key, value orelse 0 });
}

const schema_file_max_bytes: u64 = 1024 * 1024;
// Match the accepted realistic-agent-text 4KiB-8KiB long-tail shape. The
// benchmark's rendered record includes a small metadata envelope, so the
// governance cap is 8KiB plus 512 codepoints rather than a hard 8192.
const node_text_char_limit: usize = 8 * 1024 + 512;
const node_llm_metadata_field_char_limit: usize = 6000;
const node_llm_metadata_total_char_limit: usize = 12000;

const SchemaFileJson = struct {
    schema_version: ?u8 = null,
    profiles: ?[]const []const u8 = null,
    node_types: ?[]SchemaTypeJson = null,
    relation_types: ?[]SchemaTypeJson = null,
};

const SchemaTypeJson = struct {
    name: []const u8,
    id: u16,
    parents: ?[]const []const u8 = null,
    class: ?[]const u8 = null,
    relation_class: ?[]const u8 = null,
    src_types: ?[]const []const u8 = null,
    dst_types: ?[]const []const u8 = null,
    properties: ?std.json.Value = null,
    composition: ?SchemaCompositionJson = null,
};

const SchemaCompositionJson = struct {
    enabled: ?bool = null,
    owner: ?bool = null,
    cardinality: ?[]const u8 = null,
    ordered_by: ?[]const u8 = null,
};

fn loadSchemaRegistryFile(allocator: std.mem.Allocator, io: std.Io, path: []const u8) !schema.Registry {
    const stat = try std.Io.Dir.cwd().statFile(io, path, .{});
    if (stat.kind != .file or stat.size == 0 or stat.size > schema_file_max_bytes) return error.InvalidRecord;
    const size: usize = @intCast(stat.size);
    const bytes = try allocator.alloc(u8, size);
    defer allocator.free(bytes);

    var file = try std.Io.Dir.cwd().openFile(io, path, .{});
    defer file.close(io);
    const read = try file.readPositionalAll(io, bytes, 0);
    if (read != bytes.len) return error.InvalidRecord;

    var parsed = try std.json.parseFromSlice(SchemaFileJson, allocator, bytes, .{
        .ignore_unknown_fields = true,
        .allocate = .alloc_always,
    });
    defer parsed.deinit();

    var registry = schema.Registry.init(allocator);
    errdefer registry.deinit();
    try registry.addKernelTypes();
    const schema_version = parsed.value.schema_version orelse 1;
    if (schema_version != 1 and schema_version != 2 and schema_version != 3) return error.InvalidRecord;
    if (parsed.value.profiles) |profiles| {
        for (profiles) |profile_label| try addBuiltinProfileFromLabelForSchemaVersion(&registry, profile_label, schema_version);
    }

    if (parsed.value.node_types) |types| {
        for (types) |type_def| {
            var parents = std.ArrayList(u16).empty;
            defer parents.deinit(allocator);
            if (type_def.parents) |parent_names| {
                try parents.ensureTotalCapacity(allocator, parent_names.len);
                for (parent_names) |parent_name| {
                    const parent_id = registry.findNodeType(parent_name) orelse return error.UnknownNodeKind;
                    parents.appendAssumeCapacity(parent_id);
                }
            }
            if (registry.findNodeType(type_def.name)) |existing_id| {
                if (existing_id != type_def.id) return error.DuplicateTypeName;
                if (parents.items.len != 0) return error.DuplicateTypeName;
                try applySchemaNodePropertiesFromJson(&registry, existing_id, type_def.properties);
                continue;
            }
            try registry.addNodeType(type_def.name, type_def.id, parents.items);
            try applySchemaNodePropertiesFromJson(&registry, type_def.id, type_def.properties);
        }
    }
    if (parsed.value.relation_types) |types| {
        for (types) |type_def| {
            var parents = std.ArrayList(u16).empty;
            defer parents.deinit(allocator);
            if (type_def.parents) |parent_names| {
                try parents.ensureTotalCapacity(allocator, parent_names.len);
                for (parent_names) |parent_name| {
                    const parent_id = registry.findRelationType(parent_name) orelse return error.UnknownRelationKind;
                    parents.appendAssumeCapacity(parent_id);
                }
            }
            const endpoint_rule = try schemaEndpointRuleFromJson(registry, type_def);
            const relation_class = try schemaRelationClassFromJson(type_def);
            if (registry.findRelationType(type_def.name)) |existing_id| {
                if (existing_id != type_def.id) return error.DuplicateTypeName;
                if (parents.items.len != 0) return error.DuplicateTypeName;
                try registry.setRelationEndpointRule(existing_id, endpoint_rule);
                if (schemaRelationClassLabelFromJson(type_def) != null) try registry.setRelationClass(existing_id, relation_class);
                try applySchemaRelationPropertiesFromJson(&registry, existing_id, type_def.properties);
                try applySchemaRelationCompositionFromJson(&registry, existing_id, type_def.composition);
                continue;
            }
            try registry.addRelationTypeWithMetadata(type_def.name, type_def.id, parents.items, endpoint_rule, relation_class);
            try applySchemaRelationPropertiesFromJson(&registry, type_def.id, type_def.properties);
            try applySchemaRelationCompositionFromJson(&registry, type_def.id, type_def.composition);
        }
    }
    return registry;
}

fn addBuiltinProfilesFromCsv(registry: *schema.Registry, raw_profiles: []const u8) !void {
    return try addBuiltinProfilesFromCsvForSchemaVersion(registry, raw_profiles, 3);
}

fn addBuiltinProfilesFromCsvForSchemaVersion(registry: *schema.Registry, raw_profiles: []const u8, schema_version: u32) !void {
    var it = std.mem.splitScalar(u8, raw_profiles, ',');
    var count: usize = 0;
    while (it.next()) |raw_profile| {
        const profile = std.mem.trim(u8, raw_profile, " \t\r\n");
        if (profile.len == 0) continue;
        try addBuiltinProfileFromLabelForSchemaVersion(registry, profile, schema_version);
        count += 1;
    }
    if (count == 0) return error.InvalidRecord;
}

fn addBuiltinProfileFromLabel(registry: *schema.Registry, raw_profile: []const u8) !void {
    return try addBuiltinProfileFromLabelForSchemaVersion(registry, raw_profile, 3);
}

fn addBuiltinProfileFromLabelForSchemaVersion(registry: *schema.Registry, raw_profile: []const u8, schema_version: u32) !void {
    const profile = schema.BuiltinProfile.fromLabel(raw_profile) orelse return error.InvalidRecord;
    try registry.addBuiltinProfileForSchemaVersion(profile, schema_version);
}

fn applySchemaNodePropertiesFromJson(registry: *schema.Registry, type_id: u16, properties: ?std.json.Value) !void {
    const value = properties orelse return;
    if (value != .object) return error.InvalidRecord;
    var it = value.object.iterator();
    while (it.next()) |entry| {
        const property = try schemaPropertyMetaFromJson(registry.allocator, entry.key_ptr.*, entry.value_ptr.*);
        defer if (property.enum_values.len != 0) registry.allocator.free(property.enum_values);
        try registry.setNodeProperty(type_id, property);
    }
}

fn applySchemaRelationPropertiesFromJson(registry: *schema.Registry, type_id: u16, properties: ?std.json.Value) !void {
    const value = properties orelse return;
    if (value != .object) return error.InvalidRecord;
    var it = value.object.iterator();
    while (it.next()) |entry| {
        const property = try schemaPropertyMetaFromJson(registry.allocator, entry.key_ptr.*, entry.value_ptr.*);
        defer if (property.enum_values.len != 0) registry.allocator.free(property.enum_values);
        try registry.setRelationProperty(type_id, property);
    }
}

fn schemaPropertyMetaFromJson(allocator: std.mem.Allocator, name: []const u8, value: std.json.Value) !schema.PropertyMeta {
    if (value != .object) return error.InvalidRecord;
    const value_type = if (value.object.get("type")) |type_value| try schemaPropertyTypeFromJson(type_value) else .string;
    const enum_values = if (value.object.get("values")) |values_value|
        try schemaPropertyEnumValuesFromJson(allocator, values_value)
    else
        &.{};
    errdefer if (enum_values.len != 0) allocator.free(enum_values);
    if (value_type == .@"enum" and enum_values.len == 0) return error.InvalidRecord;
    if (value_type != .@"enum" and enum_values.len != 0) return error.InvalidRecord;
    return .{
        .name = name,
        .value_type = value_type,
        .enum_values = enum_values,
        .required = if (value.object.get("required")) |field| try schemaBoolFromJson(field) else false,
        .nullable = if (value.object.get("nullable")) |field| try schemaBoolFromJson(field) else true,
        .agent_fillable = if (value.object.get("agent_fillable")) |field| try schemaBoolFromJson(field) else false,
        .human_fillable = if (value.object.get("human_fillable")) |field| try schemaBoolFromJson(field) else false,
        .indexed = if (value.object.get("indexed")) |field| try schemaBoolFromJson(field) else false,
        .searchable = if (value.object.get("searchable")) |field| try schemaBoolFromJson(field) else false,
        .returned_by_default = if (value.object.get("returned_by_default")) |field| try schemaBoolFromJson(field) else false,
    };
}

fn schemaPropertyEnumValuesFromJson(allocator: std.mem.Allocator, value: std.json.Value) ![]const []const u8 {
    if (value != .array or value.array.items.len == 0 or value.array.items.len > schema.max_enum_values) return error.InvalidRecord;
    // The parsed JSON owns the strings for the duration of registry
    // construction; Registry.set*Property deep-copies the domain.
    const string_values = try allocator.alloc([]const u8, value.array.items.len);
    errdefer allocator.free(string_values);
    for (value.array.items, 0..) |item, index| {
        if (item != .string or item.string.len == 0 or item.string.len > schema.max_enum_value_bytes) return error.InvalidRecord;
        for (string_values[0..index]) |previous| {
            if (std.mem.eql(u8, previous, item.string)) return error.InvalidRecord;
        }
        string_values[index] = item.string;
    }
    return string_values;
}

fn schemaPropertyTypeFromJson(value: std.json.Value) !schema.PropertyType {
    if (value != .string) return error.InvalidRecord;
    return schema.PropertyType.fromLabel(value.string) orelse return error.InvalidRecord;
}

fn schemaBoolFromJson(value: std.json.Value) !bool {
    if (value != .bool) return error.InvalidRecord;
    return value.bool;
}

fn applySchemaRelationCompositionFromJson(registry: *schema.Registry, type_id: u16, composition: ?SchemaCompositionJson) !void {
    const raw = composition orelse return;
    try registry.setRelationComposition(type_id, .{
        .enabled = raw.enabled orelse true,
        .owner = raw.owner orelse false,
        .cardinality = if (raw.cardinality) |label| schema.CompositionCardinality.fromLabel(label) orelse return error.InvalidRecord else .many,
        .ordered_by = raw.ordered_by,
    });
}

fn schemaEndpointRuleFromJson(registry: schema.Registry, type_def: SchemaTypeJson) !schema.RelationEndpointRule {
    return .{
        .src = if (type_def.src_types) |labels| try schemaNodeTypeSetFromLabels(registry, labels) else null,
        .dst = if (type_def.dst_types) |labels| try schemaNodeTypeSetFromLabels(registry, labels) else null,
    };
}

fn schemaRelationClassLabelFromJson(type_def: SchemaTypeJson) ?[]const u8 {
    return type_def.relation_class orelse type_def.class;
}

fn schemaRelationClassFromJson(type_def: SchemaTypeJson) !schema.RelationClass {
    if (schemaRelationClassLabelFromJson(type_def)) |label| {
        return schema.RelationClass.fromLabel(label) orelse return error.InvalidRecord;
    }
    return schemaRelationClassNamespace(type_def.name) orelse .domain;
}

fn schemaRelationClassNamespace(name: []const u8) ?schema.RelationClass {
    if (std.mem.startsWith(u8, name, "md:")) return .md;
    if (std.mem.startsWith(u8, name, "markdown:")) return .md;
    if (std.mem.startsWith(u8, name, "prov:")) return .prov;
    if (std.mem.startsWith(u8, name, "provenance:")) return .prov;
    if (std.mem.startsWith(u8, name, "task:")) return .task;
    if (std.mem.startsWith(u8, name, "sys:")) return .sys;
    if (std.mem.startsWith(u8, name, "system:")) return .sys;
    if (std.mem.startsWith(u8, name, "domain:")) return .domain;
    return null;
}

fn schemaNodeTypeSetFromLabels(registry: schema.Registry, labels: []const []const u8) !schema.NodeTypeSet {
    if (labels.len == 0) return error.InvalidRecord;
    var out = schema.NodeTypeSet.empty();
    for (labels) |label| {
        const id = registry.findNodeType(label) orelse return error.UnknownNodeKind;
        out.merge(try registry.nodeDescendants(id));
    }
    return out;
}

fn validateNodeTextGranularity(text: []const u8) !void {
    const chars = std.unicode.utf8CountCodepoints(text) catch return error.InvalidRecord;
    if (chars > node_text_char_limit) return error.NodeTextTooLarge;
}

fn validateNodeLlmMetadataGranularity(name: ?[]const u8, summary: ?[]const u8, retrieval_hints: ?[]const u8) !void {
    var total_chars: usize = 0;
    if (name) |value| {
        const chars = std.unicode.utf8CountCodepoints(value) catch return error.InvalidRecord;
        if (chars > node_llm_metadata_field_char_limit) return error.NodePropertyTooLarge;
        total_chars = std.math.add(usize, total_chars, chars) catch return error.NodePropertyTooLarge;
    }
    if (summary) |value| {
        const chars = std.unicode.utf8CountCodepoints(value) catch return error.InvalidRecord;
        if (chars > node_llm_metadata_field_char_limit) return error.NodePropertyTooLarge;
        total_chars = std.math.add(usize, total_chars, chars) catch return error.NodePropertyTooLarge;
    }
    if (retrieval_hints) |value| {
        const chars = std.unicode.utf8CountCodepoints(value) catch return error.InvalidRecord;
        if (chars > node_llm_metadata_field_char_limit) return error.NodePropertyTooLarge;
        total_chars = std.math.add(usize, total_chars, chars) catch return error.NodePropertyTooLarge;
    }
    if (total_chars > node_llm_metadata_total_char_limit) return error.NodePropertyTooLarge;
}

fn validateEdgeStringProperty(value: []const u8) !void {
    const chars = std.unicode.utf8CountCodepoints(value) catch return error.InvalidRecord;
    if (chars == 0 or chars > node_llm_metadata_field_char_limit) return error.NodePropertyTooLarge;
}

fn validateParsedStringProperty(owner: storage.PropertyOwner, key: []const u8, value: []const u8) !void {
    switch (owner) {
        .node => {
            if (std.mem.eql(u8, key, "summary")) {
                try validateNodeLlmMetadataGranularity(null, value, null);
            } else if (std.mem.eql(u8, key, "retrieval_hints")) {
                try validateNodeLlmMetadataGranularity(null, null, value);
            } else if (std.mem.eql(u8, key, "name")) {
                try validateNodeLlmMetadataGranularity(value, null, null);
            } else {
                return error.InvalidRecord;
            }
        },
        .edge => {
            // state 是**两态位**,不是连续置信度——严格只收 tentative|confirmed。
            // (设计铁律:禁止 0.67 之类编造的浮点置信度;一个 bit + 可溯源留痕更诚实。)
            if (std.mem.eql(u8, key, "state")) {
                if (!std.mem.eql(u8, value, "tentative") and !std.mem.eql(u8, value, "confirmed")) {
                    return error.InvalidRecord;
                }
            } else {
                try validateEdgeStringProperty(value);
            }
        },
    }
}

fn validateSchemaStringPropertyWrite(
    allocator: std.mem.Allocator,
    store: storage.Store,
    registry: schema.Registry,
    owner: storage.PropertyOwner,
    key: []const u8,
    value: []const u8,
    require_declared: bool,
) !void {
    const maybe_property = switch (owner) {
        .node => |node_id| blk: {
            var node = (try store.readNodeById(allocator, node_id)) orelse return core.Error.NotFound;
            defer node.deinit(allocator);
            break :blk registry.nodePropertyByTypeId(@intFromEnum(node.kind), key);
        },
        .edge => |edge_id| blk: {
            const edge = try store.readEdgeById(edge_id);
            break :blk registry.relationPropertyByTypeId(@intFromEnum(edge.rel), key);
        },
    };
    const property = maybe_property orelse {
        if (require_declared) return error.UnknownProperty;
        return;
    };
    switch (property.value_type) {
        .string, .json => {},
        .@"enum" => if (!property.enumAllows(value)) return error.InvalidRecord,
        else => return error.InvalidRecord,
    }
}

fn validateSchemaUintPropertyWrite(
    allocator: std.mem.Allocator,
    store: storage.Store,
    registry: schema.Registry,
    owner: storage.PropertyOwner,
    key: []const u8,
    require_declared: bool,
) !void {
    const maybe_property = switch (owner) {
        .node => |node_id| blk: {
            var node = (try store.readNodeById(allocator, node_id)) orelse return core.Error.NotFound;
            defer node.deinit(allocator);
            break :blk registry.nodePropertyByTypeId(@intFromEnum(node.kind), key);
        },
        .edge => |edge_id| blk: {
            const edge = try store.readEdgeById(edge_id);
            break :blk registry.relationPropertyByTypeId(@intFromEnum(edge.rel), key);
        },
    };
    const property = maybe_property orelse {
        if (require_declared) return error.UnknownProperty;
        return;
    };
    if (property.value_type != .uint) return error.InvalidRecord;
}

fn validateNodeWriteGranularity(parsed: ParsedNodeTextGovernanceArgs) !void {
    try validateNodeTextGranularity(parsed.text);
    try validateNodeLlmMetadataGranularity(parsed.name, parsed.summary, parsed.retrieval_hints);
}

fn loadBenchCorpusFile(allocator: std.mem.Allocator, io: std.Io, path: []const u8) !BenchCorpus {
    return loadBenchLineFile(allocator, io, path, bench_corpus_file_max_bytes);
}

fn loadBenchLineFile(allocator: std.mem.Allocator, io: std.Io, path: []const u8, max_bytes: u64) !BenchCorpus {
    const stat = try std.Io.Dir.cwd().statFile(io, path, .{});
    if (stat.kind != .file or stat.size == 0 or stat.size > max_bytes) return error.InvalidRecord;

    const size: usize = @intCast(stat.size);
    const bytes = try allocator.alloc(u8, size);
    errdefer allocator.free(bytes);

    var file = try std.Io.Dir.cwd().openFile(io, path, .{});
    defer file.close(io);
    const read = try file.readPositionalAll(io, bytes, 0);
    if (read != bytes.len) return error.InvalidRecord;

    var records = std.ArrayList([]const u8).empty;
    errdefer records.deinit(allocator);
    var lines = std.mem.splitScalar(u8, bytes, '\n');
    while (lines.next()) |line| {
        const trimmed = std.mem.trim(u8, line, " \t\r");
        if (trimmed.len == 0) continue;
        try records.append(allocator, trimmed);
    }
    if (records.items.len == 0) return error.InvalidRecord;

    return .{
        .bytes = bytes,
        .records = try records.toOwnedSlice(allocator),
    };
}

fn loadJsonlLineFile(allocator: std.mem.Allocator, io: std.Io, path: []const u8, max_bytes: u64) !BenchCorpus {
    const stat = try std.Io.Dir.cwd().statFile(io, path, .{});
    if (stat.kind != .file or stat.size > max_bytes) return error.InvalidRecord;
    if (stat.size == 0) return .{};

    const size: usize = @intCast(stat.size);
    const bytes = try allocator.alloc(u8, size);
    errdefer allocator.free(bytes);

    var file = try std.Io.Dir.cwd().openFile(io, path, .{});
    defer file.close(io);
    const read = try file.readPositionalAll(io, bytes, 0);
    if (read != bytes.len) return error.InvalidRecord;

    var records = std.ArrayList([]const u8).empty;
    errdefer records.deinit(allocator);
    var lines = std.mem.splitScalar(u8, bytes, '\n');
    while (lines.next()) |line| {
        const trimmed = std.mem.trim(u8, line, " \t\r");
        if (trimmed.len == 0) continue;
        try records.append(allocator, trimmed);
    }

    return .{
        .bytes = bytes,
        .records = try records.toOwnedSlice(allocator),
    };
}

fn loadBenchMetaknowReplay(allocator: std.mem.Allocator, io: std.Io, dir_path: []const u8) !BenchMetaknowReplay {
    const nodes_path = try std.fs.path.join(allocator, &.{ dir_path, "nodes.jsonl" });
    defer allocator.free(nodes_path);
    const edges_path = try std.fs.path.join(allocator, &.{ dir_path, "edges.jsonl" });
    defer allocator.free(edges_path);
    const manifest_path = try std.fs.path.join(allocator, &.{ dir_path, "manifest.json" });
    defer allocator.free(manifest_path);
    const deferred_based_on_path = try std.fs.path.join(allocator, &.{ dir_path, "deferred_based_on.jsonl" });
    defer allocator.free(deferred_based_on_path);

    const node_lines = try loadBenchLineFile(allocator, io, nodes_path, bench_metaknow_jsonl_max_bytes);
    defer node_lines.deinit(allocator);
    const edge_lines = try loadBenchLineFile(allocator, io, edges_path, bench_metaknow_jsonl_max_bytes);
    defer edge_lines.deinit(allocator);
    const input_shape = try detectBenchMetaknowReplayInputShape(allocator, node_lines.records, edge_lines.records);
    const manifest = if (try fileExists(io, manifest_path))
        try loadBenchMetaknowManifest(allocator, io, manifest_path)
    else switch (input_shape) {
        .native_jsonl => BenchMetaknowReplayManifestStats{},
        .metaknow_export => return error.FileNotFound,
    };

    var nodes = std.ArrayList(BenchMetaknowReplayNode).empty;
    errdefer {
        for (nodes.items) |node| node.deinit(allocator);
        nodes.deinit(allocator);
    }
    try nodes.ensureTotalCapacity(allocator, node_lines.records.len);

    var seen_ids = std.StringHashMap(void).init(allocator);
    defer seen_ids.deinit();
    try seen_ids.ensureTotalCapacity(@intCast(node_lines.records.len));

    for (node_lines.records) |line| {
        switch (input_shape) {
            .metaknow_export => {
                var parsed = try std.json.parseFromSlice(BenchMetaknowNodeJson, allocator, line, .{
                    .ignore_unknown_fields = true,
                    .allocate = .alloc_always,
                });
                defer parsed.deinit();
                if (parsed.value.id.len == 0) return error.InvalidRecord;
                if (seen_ids.contains(parsed.value.id)) return error.InvalidRecord;
                const original_id = try allocator.dupe(u8, parsed.value.id);
                errdefer allocator.free(original_id);
                try seen_ids.put(original_id, {});
                const text = try benchMetaknowNodeText(allocator, parsed.value);
                errdefer allocator.free(text);
                if (text.len == 0) return error.InvalidRecord;
                try nodes.append(allocator, .{
                    .original_id = original_id,
                    .kind = benchMetaknowNodeKind(parsed.value.kind),
                    .text = text,
                });
            },
            .native_jsonl => {
                var parsed = try std.json.parseFromSlice(NativeJsonlNodeJson, allocator, line, .{
                    .ignore_unknown_fields = true,
                    .allocate = .alloc_always,
                });
                defer parsed.deinit();
                if (parsed.value.id == 0 or parsed.value.text.len == 0) return error.InvalidRecord;
                const original_id = try benchMetaknowReplayIdFromU64(allocator, parsed.value.id);
                errdefer allocator.free(original_id);
                if (seen_ids.contains(original_id)) return error.InvalidRecord;
                try seen_ids.put(original_id, {});
                const text = try allocator.dupe(u8, parsed.value.text);
                errdefer allocator.free(text);
                try nodes.append(allocator, .{
                    .original_id = original_id,
                    .kind = parseCliNodeKind(parsed.value.kind) orelse return error.InvalidNodeKind,
                    .text = text,
                });
            },
        }
    }

    var edges = std.ArrayList(BenchMetaknowReplayEdge).empty;
    errdefer {
        for (edges.items) |edge| edge.deinit(allocator);
        edges.deinit(allocator);
    }
    try edges.ensureTotalCapacity(allocator, edge_lines.records.len);

    for (edge_lines.records) |line| {
        switch (input_shape) {
            .metaknow_export => {
                var parsed = try std.json.parseFromSlice(BenchMetaknowEdgeJson, allocator, line, .{
                    .ignore_unknown_fields = true,
                    .allocate = .alloc_always,
                });
                defer parsed.deinit();
                if (parsed.value.src.len == 0 or parsed.value.dst.len == 0) return error.InvalidRecord;
                const src = try allocator.dupe(u8, parsed.value.src);
                errdefer allocator.free(src);
                const dst = try allocator.dupe(u8, parsed.value.dst);
                errdefer allocator.free(dst);
                const rel_raw = if (parsed.value.rel) |rel| rel else parsed.value.relation;
                try edges.append(allocator, .{
                    .src_original_id = src,
                    .dst_original_id = dst,
                    .rel = benchMetaknowRelKind(rel_raw),
                });
            },
            .native_jsonl => {
                var parsed = try std.json.parseFromSlice(NativeJsonlEdgeJson, allocator, line, .{
                    .ignore_unknown_fields = true,
                    .allocate = .alloc_always,
                });
                defer parsed.deinit();
                if (parsed.value.id == 0 or parsed.value.src == 0 or parsed.value.dst == 0) return error.InvalidRecord;
                const src = try benchMetaknowReplayIdFromU64(allocator, parsed.value.src);
                errdefer allocator.free(src);
                const dst = try benchMetaknowReplayIdFromU64(allocator, parsed.value.dst);
                errdefer allocator.free(dst);
                try edges.append(allocator, .{
                    .src_original_id = src,
                    .dst_original_id = dst,
                    .rel = parseCliRelKind(parsed.value.rel) orelse return error.InvalidRelKind,
                });
            },
        }
    }

    var deferred_based_on = std.ArrayList(BenchMetaknowDeferredBasedOnRow).empty;
    errdefer {
        for (deferred_based_on.items) |row| row.deinit(allocator);
        deferred_based_on.deinit(allocator);
    }
    if (manifest.deferred_based_on_rows != 0 or (input_shape == .native_jsonl and try fileExists(io, deferred_based_on_path))) {
        const deferred_lines = try loadBenchLineFile(allocator, io, deferred_based_on_path, bench_metaknow_jsonl_max_bytes);
        defer deferred_lines.deinit(allocator);
        if (input_shape == .metaknow_export and deferred_lines.records.len != manifest.deferred_based_on_rows) return error.InvalidRecord;
        try deferred_based_on.ensureTotalCapacity(allocator, deferred_lines.records.len);
        for (deferred_lines.records) |line| {
            switch (input_shape) {
                .metaknow_export => {
                    var parsed = try std.json.parseFromSlice(BenchMetaknowDeferredBasedOnJson, allocator, line, .{
                        .ignore_unknown_fields = true,
                        .allocate = .alloc_always,
                    });
                    defer parsed.deinit();
                    if (parsed.value.fragment_id.len == 0 or parsed.value.dst_ids.len == 0) return error.InvalidRecord;
                    const fragment_original_id = try allocator.dupe(u8, parsed.value.fragment_id);
                    errdefer allocator.free(fragment_original_id);
                    const dst_original_ids = try allocator.alloc([]u8, parsed.value.dst_ids.len);
                    errdefer allocator.free(dst_original_ids);
                    var copied: usize = 0;
                    errdefer {
                        for (dst_original_ids[0..copied]) |id| allocator.free(id);
                    }
                    for (parsed.value.dst_ids, 0..) |id, index| {
                        if (id.len == 0) return error.InvalidRecord;
                        dst_original_ids[index] = try allocator.dupe(u8, id);
                        copied += 1;
                    }
                    try deferred_based_on.append(allocator, .{
                        .fragment_original_id = fragment_original_id,
                        .dst_original_ids = dst_original_ids,
                    });
                },
                .native_jsonl => {
                    var parsed = try std.json.parseFromSlice(NativeJsonlDeferredBasedOnJson, allocator, line, .{
                        .ignore_unknown_fields = true,
                        .allocate = .alloc_always,
                    });
                    defer parsed.deinit();
                    if (parsed.value.src == 0 or parsed.value.dst == 0) return error.InvalidRecord;
                    const fragment_original_id = try benchMetaknowReplayIdFromU64(allocator, parsed.value.src);
                    errdefer allocator.free(fragment_original_id);
                    const dst_original_ids = try allocator.alloc([]u8, 1);
                    errdefer allocator.free(dst_original_ids);
                    const dst_original_id = try benchMetaknowReplayIdFromU64(allocator, parsed.value.dst);
                    errdefer allocator.free(dst_original_id);
                    dst_original_ids[0] = dst_original_id;
                    try deferred_based_on.append(allocator, .{
                        .fragment_original_id = fragment_original_id,
                        .dst_original_ids = dst_original_ids,
                    });
                },
            }
        }
    }

    const native_deferred_rows = deferred_based_on.items.len;
    const native_deferred_bytes = if (input_shape == .native_jsonl and manifest.deferred_based_on_rows == 0 and native_deferred_rows != 0)
        try fileSize(io, deferred_based_on_path)
    else
        0;
    var result = BenchMetaknowReplay{};
    errdefer result.deinit(allocator);
    result.nodes = try nodes.toOwnedSlice(allocator);
    result.edges = try edges.toOwnedSlice(allocator);
    result.deferred_based_on = try deferred_based_on.toOwnedSlice(allocator);
    result.manifest = if (native_deferred_bytes != 0) manifest: {
        var next = manifest;
        next.deferred_based_on_rows = native_deferred_rows;
        next.deferred_based_on_bytes = @intCast(native_deferred_bytes);
        break :manifest next;
    } else manifest;
    return result;
}

fn detectBenchMetaknowReplayInputShape(
    allocator: std.mem.Allocator,
    node_lines: []const []const u8,
    edge_lines: []const []const u8,
) !BenchMetaknowReplayInputShape {
    if (node_lines.len == 0 or edge_lines.len == 0) return error.InvalidRecord;
    if (std.json.parseFromSlice(NativeJsonlNodeJson, allocator, node_lines[0], .{
        .ignore_unknown_fields = true,
        .allocate = .alloc_always,
    })) |parsed_node| {
        defer parsed_node.deinit();
        if (std.json.parseFromSlice(NativeJsonlEdgeJson, allocator, edge_lines[0], .{
            .ignore_unknown_fields = true,
            .allocate = .alloc_always,
        })) |parsed_edge| {
            defer parsed_edge.deinit();
            if (parsed_node.value.id != 0 and parsed_node.value.text.len != 0 and parsed_edge.value.id != 0 and parsed_edge.value.src != 0 and parsed_edge.value.dst != 0) {
                return .native_jsonl;
            }
        } else |_| {}
    } else |_| {}
    return .metaknow_export;
}

fn benchMetaknowReplayIdFromU64(allocator: std.mem.Allocator, value: u64) ![]u8 {
    if (value == 0 or value == std.math.maxInt(u64)) return error.InvalidRecord;
    return try std.fmt.allocPrint(allocator, "{d}", .{value});
}

fn fileSize(io: std.Io, path: []const u8) !u64 {
    const stat = try std.Io.Dir.cwd().statFile(io, path, .{});
    if (stat.kind != .file) return error.InvalidRecord;
    return stat.size;
}

fn loadBenchMetaknowManifest(allocator: std.mem.Allocator, io: std.Io, path: []const u8) !BenchMetaknowReplayManifestStats {
    const stat = try std.Io.Dir.cwd().statFile(io, path, .{});
    if (stat.kind != .file or stat.size == 0 or stat.size > bench_metaknow_manifest_max_bytes) return error.InvalidRecord;
    const size: usize = @intCast(stat.size);
    const bytes = try allocator.alloc(u8, size);
    defer allocator.free(bytes);

    var file = try std.Io.Dir.cwd().openFile(io, path, .{});
    defer file.close(io);
    const read = try file.readPositionalAll(io, bytes, 0);
    if (read != bytes.len) return error.InvalidRecord;

    var parsed = try std.json.parseFromSlice(BenchMetaknowManifestJson, allocator, bytes, .{
        .ignore_unknown_fields = true,
        .allocate = .alloc_always,
    });
    defer parsed.deinit();

    return .{
        .based_on_materialize_threshold = parsed.value.based_on_materialize_threshold orelse 0,
        .based_on_materialized_edges = parsed.value.based_on_materialized_edges orelse 0,
        .based_on_deferred_edges = parsed.value.based_on_deferred_edges orelse 0,
        .based_on_deferred_fragment_count = parsed.value.based_on_deferred_fragment_count orelse 0,
        .based_on_document_container_skipped_edges = parsed.value.based_on_document_container_skipped_edges orelse 0,
        .deferred_based_on_rows = parsed.value.deferred_based_on_rows orelse 0,
        .deferred_based_on_bytes = parsed.value.deferred_based_on_bytes orelse 0,
    };
}

fn benchMetaknowAppendPart(out: *std.ArrayList(u8), allocator: std.mem.Allocator, label: []const u8, value: ?[]const u8) !void {
    const bytes = value orelse return;
    if (bytes.len == 0) return;
    if (out.items.len != 0) try out.appendSlice(allocator, " ");
    try out.appendSlice(allocator, label);
    try out.appendSlice(allocator, "=\"");
    try out.appendSlice(allocator, bytes);
    try out.appendSlice(allocator, "\"");
}

fn benchMetaknowNodeText(allocator: std.mem.Allocator, node: BenchMetaknowNodeJson) ![]u8 {
    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    try benchMetaknowAppendPart(&out, allocator, "kind", node.kind);
    try benchMetaknowAppendPart(&out, allocator, "title", node.title orelse node.text);
    try benchMetaknowAppendPart(&out, allocator, "summary", node.summary);
    try benchMetaknowAppendPart(&out, allocator, "description", node.description);
    try benchMetaknowAppendPart(&out, allocator, "properties", node.properties);
    try benchMetaknowAppendPart(&out, allocator, "fragment_text", node.fragment);
    try benchMetaknowAppendPart(&out, allocator, "text", node.text);
    return try out.toOwnedSlice(allocator);
}

fn benchMetaknowNodeKind(raw: ?[]const u8) core.NodeKind {
    const value = raw orelse return .concept;
    if (core.parseNodeKind(value)) |kind| return kind;
    if (std.ascii.eqlIgnoreCase(value, "note")) return .observation;
    if (std.ascii.eqlIgnoreCase(value, "knowledge_node")) return .concept;
    if (std.ascii.eqlIgnoreCase(value, "entity")) return .concept;
    if (std.ascii.eqlIgnoreCase(value, "fragment")) return .document_section;
    if (std.ascii.eqlIgnoreCase(value, "error")) return .error_event;
    return .concept;
}

fn benchMetaknowRelKind(raw: ?[]const u8) core.RelKind {
    const value = raw orelse return .related_to;
    if (core.parseRelKind(value)) |rel| return rel;
    if (std.ascii.eqlIgnoreCase(value, "supports")) return .evidences;
    if (std.ascii.eqlIgnoreCase(value, "supported_by")) return .evidences;
    if (std.ascii.eqlIgnoreCase(value, "support")) return .evidences;
    if (std.ascii.eqlIgnoreCase(value, "dependency")) return .depends_on;
    if (std.ascii.eqlIgnoreCase(value, "depends")) return .depends_on;
    if (std.ascii.eqlIgnoreCase(value, "related")) return .related_to;
    return .related_to;
}

const metaknow_deferred_based_on_file = query.metaknow_deferred_based_on_file;
const metaknow_deferred_based_on_magic = query.metaknow_deferred_based_on_magic;
const metaknow_deferred_based_on_header_len = query.metaknow_deferred_based_on_header_len;
const metaknow_deferred_based_on_index_record_len = query.metaknow_deferred_based_on_index_record_len;
const metaknow_deferred_based_on_target_record_len = query.metaknow_deferred_based_on_target_record_len;
const metaknow_deferred_based_on_edge_id_base = query.metaknow_deferred_based_on_edge_id_base;

const MetaknowDeferredBasedOnBuildStats = struct {
    sources: usize = 0,
    links: usize = 0,
    bytes: u64 = 0,
};

const MetaknowDeferredBasedOnPair = struct {
    src: u64,
    dst: u64,
};

const MetaknowDeferredBasedOnSidecarPairs = struct {
    present: bool = false,
    pairs: std.ArrayList(MetaknowDeferredBasedOnPair) = .empty,

    fn deinit(self: *MetaknowDeferredBasedOnSidecarPairs, allocator: std.mem.Allocator) void {
        self.pairs.deinit(allocator);
        self.* = .{};
    }
};

fn normalizeMetaknowDeferredBasedOnPairs(snapshot: *MetaknowDeferredBasedOnSidecarPairs) void {
    std.mem.sort(MetaknowDeferredBasedOnPair, snapshot.pairs.items, {}, struct {
        fn lessThan(_: void, a: MetaknowDeferredBasedOnPair, b: MetaknowDeferredBasedOnPair) bool {
            if (a.src != b.src) return a.src < b.src;
            return a.dst < b.dst;
        }
    }.lessThan);
    var write_index: usize = 0;
    var previous: ?MetaknowDeferredBasedOnPair = null;
    for (snapshot.pairs.items) |pair| {
        if (previous) |last| {
            if (last.src == pair.src and last.dst == pair.dst) continue;
        }
        snapshot.pairs.items[write_index] = pair;
        write_index += 1;
        previous = pair;
    }
    snapshot.pairs.shrinkRetainingCapacity(write_index);
}

fn metaknowDeferredBasedOnPath(allocator: std.mem.Allocator, store: storage.Store) ![]u8 {
    return query.metaknowDeferredBasedOnPath(allocator, store);
}

fn metaknowDeferredBasedOnPathForDb(allocator: std.mem.Allocator, db_path: []const u8) ![]u8 {
    return std.fs.path.join(allocator, &.{ db_path, metaknow_deferred_based_on_file });
}

const MigrationSidecarRecordStream = struct {
    file: *std.Io.File,
    io: std.Io,
    record_len: usize,
    remaining: u64,
    file_offset: u64,
    buffer: []u8,
    cursor: usize = 0,
    len: usize = 0,

    fn next(self: *MigrationSidecarRecordStream) !?[]const u8 {
        if (self.remaining == 0) return null;
        if (self.cursor == self.len) {
            const capacity_records = self.buffer.len / self.record_len;
            if (capacity_records == 0) return error.InvalidRecord;
            const take_records: usize = @intCast(@min(self.remaining, capacity_records));
            const byte_len = std.math.mul(usize, take_records, self.record_len) catch return error.InvalidRecord;
            const n = try self.file.readPositionalAll(self.io, self.buffer[0..byte_len], self.file_offset);
            if (n != byte_len) return error.InvalidRecord;
            self.file_offset = std.math.add(u64, self.file_offset, byte_len) catch return error.InvalidRecord;
            self.cursor = 0;
            self.len = byte_len;
        }
        const record = self.buffer[self.cursor..][0..self.record_len];
        self.cursor += self.record_len;
        self.remaining -= 1;
        return record;
    }
};

const MigrationDeferredPairDigest = struct {
    xor_a: u64 = 0,
    xor_b: u64 = 0,

    fn add(self: *MigrationDeferredPairDigest, src: u64, dst: u64) void {
        var bytes: [16]u8 = undefined;
        std.mem.writeInt(u64, bytes[0..8], src, .little);
        std.mem.writeInt(u64, bytes[8..16], dst, .little);
        self.xor_a ^= std.hash.Wyhash.hash(0x544B_4446, &bytes);
        self.xor_b ^= std.hash.Wyhash.hash(0x544B_4452, &bytes);
    }
};

fn validateMetaknowDeferredBasedOnDirection(
    file: *std.Io.File,
    io: std.Io,
    index_offset: u64,
    target_offset: u64,
    source_count: u64,
    link_count: u64,
    reverse: bool,
) !MigrationDeferredPairDigest {
    var index_buffer: [metaknow_deferred_based_on_index_record_len * 4096]u8 = undefined;
    var target_buffer: [metaknow_deferred_based_on_target_record_len * 8192]u8 = undefined;
    var indexes = MigrationSidecarRecordStream{
        .file = file,
        .io = io,
        .record_len = metaknow_deferred_based_on_index_record_len,
        .remaining = source_count,
        .file_offset = index_offset,
        .buffer = &index_buffer,
    };
    var targets = MigrationSidecarRecordStream{
        .file = file,
        .io = io,
        .record_len = metaknow_deferred_based_on_target_record_len,
        .remaining = link_count,
        .file_offset = target_offset,
        .buffer = &target_buffer,
    };
    var digest = MigrationDeferredPairDigest{};
    var previous_source: u64 = 0;
    var consumed_links: u64 = 0;
    var source_index: u64 = 0;
    while (source_index < source_count) : (source_index += 1) {
        const record = (try indexes.next()) orelse return error.InvalidRecord;
        const source: u64 = std.mem.readInt(u32, record[0..4], .little);
        const target_start: u64 = std.mem.readInt(u32, record[4..8], .little);
        const count: u64 = std.mem.readInt(u32, record[8..12], .little);
        if (source == 0 or (source_index != 0 and source <= previous_source)) return error.InvalidRecord;
        if (target_start != consumed_links or count == 0 or count > link_count - consumed_links) return error.InvalidRecord;
        var previous_target: u64 = 0;
        var target_index: u64 = 0;
        while (target_index < count) : (target_index += 1) {
            const target_record = (try targets.next()) orelse return error.InvalidRecord;
            const target: u64 = std.mem.readInt(u32, target_record[0..4], .little);
            if (target == 0 or (target_index != 0 and target <= previous_target)) return error.InvalidRecord;
            if (reverse) {
                digest.add(target, source);
            } else {
                digest.add(source, target);
            }
            previous_target = target;
        }
        consumed_links = std.math.add(u64, consumed_links, count) catch return error.InvalidRecord;
        previous_source = source;
    }
    if (consumed_links != link_count or try indexes.next() != null or try targets.next() != null) return error.InvalidRecord;
    return digest;
}

fn validateMetaknowDeferredBasedOnSidecarForMigration(file: *std.Io.File, io: std.Io, file_size: u64) !void {
    var header: [metaknow_deferred_based_on_header_len]u8 = undefined;
    if (try file.readPositionalAll(io, &header, 0) != header.len) return error.InvalidRecord;
    if (!std.mem.eql(u8, header[0..8], &metaknow_deferred_based_on_magic) or
        !std.mem.allEqual(u8, header[72..80], 0)) return error.InvalidRecord;

    const forward_source_count = std.mem.readInt(u64, header[8..16], .little);
    const forward_link_count = std.mem.readInt(u64, header[16..24], .little);
    const forward_target_offset = std.mem.readInt(u64, header[24..32], .little);
    const edge_id_base = std.mem.readInt(u64, header[32..40], .little);
    const reverse_source_count = std.mem.readInt(u64, header[48..56], .little);
    const reverse_link_count = std.mem.readInt(u64, header[56..64], .little);
    const reverse_target_offset = std.mem.readInt(u64, header[64..72], .little);
    if (forward_link_count != reverse_link_count or
        forward_source_count > std.math.maxInt(u32) or
        reverse_source_count > std.math.maxInt(u32) or
        forward_link_count > std.math.maxInt(u32) or
        edge_id_base != metaknow_deferred_based_on_edge_id_base) return error.InvalidRecord;
    if ((forward_source_count == 0) != (forward_link_count == 0) or
        (reverse_source_count == 0) != (reverse_link_count == 0)) return error.InvalidRecord;

    const forward_index_bytes = std.math.mul(u64, forward_source_count, metaknow_deferred_based_on_index_record_len) catch return error.InvalidRecord;
    const forward_target_bytes = std.math.mul(u64, forward_link_count, metaknow_deferred_based_on_target_record_len) catch return error.InvalidRecord;
    const reverse_index_bytes = std.math.mul(u64, reverse_source_count, metaknow_deferred_based_on_index_record_len) catch return error.InvalidRecord;
    const reverse_target_bytes = std.math.mul(u64, reverse_link_count, metaknow_deferred_based_on_target_record_len) catch return error.InvalidRecord;
    const expected_forward_target_offset = std.math.add(u64, metaknow_deferred_based_on_header_len, forward_index_bytes) catch return error.InvalidRecord;
    const reverse_index_offset = std.math.add(u64, expected_forward_target_offset, forward_target_bytes) catch return error.InvalidRecord;
    const expected_reverse_target_offset = std.math.add(u64, reverse_index_offset, reverse_index_bytes) catch return error.InvalidRecord;
    const expected_size = std.math.add(u64, expected_reverse_target_offset, reverse_target_bytes) catch return error.InvalidRecord;
    if (forward_target_offset != expected_forward_target_offset or
        reverse_target_offset != expected_reverse_target_offset or
        file_size != expected_size) return error.InvalidRecord;

    const forward_digest = try validateMetaknowDeferredBasedOnDirection(
        file,
        io,
        metaknow_deferred_based_on_header_len,
        forward_target_offset,
        forward_source_count,
        forward_link_count,
        false,
    );
    const reverse_digest = try validateMetaknowDeferredBasedOnDirection(
        file,
        io,
        reverse_index_offset,
        reverse_target_offset,
        reverse_source_count,
        reverse_link_count,
        true,
    );
    if (forward_digest.xor_a != reverse_digest.xor_a or forward_digest.xor_b != reverse_digest.xor_b) return error.InvalidRecord;
}

/// Schema and store-v2 migrations preserve node ids, so the deferred
/// `based_on` sidecar can be copied byte-for-byte.  Do not expand its complete
/// pair set into memory merely to rewrite the same representation: large
/// knowledge stores deliberately keep these edges deferred for density.
fn copyMetaknowDeferredBasedOnSidecarForMigration(
    allocator: std.mem.Allocator,
    io: std.Io,
    source_db_path: []const u8,
    target_db_path: []const u8,
) !bool {
    const source_path = try metaknowDeferredBasedOnPathForDb(allocator, source_db_path);
    defer allocator.free(source_path);
    const source_stat = std.Io.Dir.cwd().statFile(io, source_path, .{ .follow_symlinks = false }) catch |err| switch (err) {
        error.FileNotFound => return false,
        else => |e| return e,
    };
    if (source_stat.kind != .file or source_stat.size < metaknow_deferred_based_on_header_len) return error.InvalidRecord;

    const target_path = try metaknowDeferredBasedOnPathForDb(allocator, target_db_path);
    defer allocator.free(target_path);
    if (try anyPathExists(io, target_path)) return error.AlreadyExists;
    try std.Io.Dir.copyFile(std.Io.Dir.cwd(), source_path, std.Io.Dir.cwd(), target_path, io, .{ .replace = false });
    errdefer std.Io.Dir.cwd().deleteFile(io, target_path) catch {};

    const copied_stat = try std.Io.Dir.cwd().statFile(io, target_path, .{ .follow_symlinks = false });
    if (copied_stat.kind != .file or copied_stat.size != source_stat.size) return error.InvalidRecord;
    var copied_file = try std.Io.Dir.cwd().openFile(io, target_path, .{ .allow_directory = false });
    defer copied_file.close(io);
    try validateMetaknowDeferredBasedOnSidecarForMigration(&copied_file, io, copied_stat.size);
    if (builtin.os.tag != .windows) {
        try copied_file.sync(io);
        try syncParentDirectory(io, target_path);
    }
    return true;
}

fn writeBenchMetaknowDeferredBasedOnSidecar(
    allocator: std.mem.Allocator,
    store: storage.Store,
    replay: *const BenchMetaknowReplay,
    node_count: usize,
) !MetaknowDeferredBasedOnBuildStats {
    if (replay.deferred_based_on.len == 0) return .{};
    var id_map = try buildBenchMetaknowNodeIdMap(allocator, replay, node_count);
    defer id_map.deinit();

    var pairs = std.ArrayList(MetaknowDeferredBasedOnPair).empty;
    defer pairs.deinit(allocator);
    for (replay.deferred_based_on) |row| {
        const fragment_id = id_map.get(row.fragment_original_id) orelse continue;
        for (row.dst_original_ids) |dst_original_id| {
            const source_id = id_map.get(dst_original_id) orelse continue;
            try pairs.append(allocator, .{ .src = source_id, .dst = fragment_id });
        }
    }
    return try writeMetaknowDeferredBasedOnForwardPairsSidecar(allocator, store, pairs.items, node_count);
}

fn writeMetaknowDeferredBasedOnForwardPairsSidecar(
    allocator: std.mem.Allocator,
    store: storage.Store,
    forward_pairs: []const MetaknowDeferredBasedOnPair,
    node_count: usize,
) !MetaknowDeferredBasedOnBuildStats {
    if (forward_pairs.len == 0) return .{};
    var pairs = std.ArrayList(MetaknowDeferredBasedOnPair).empty;
    defer pairs.deinit(allocator);
    try pairs.ensureTotalCapacity(allocator, forward_pairs.len);
    pairs.appendSliceAssumeCapacity(forward_pairs);

    std.mem.sort(MetaknowDeferredBasedOnPair, pairs.items, {}, struct {
        fn lessThan(_: void, a: MetaknowDeferredBasedOnPair, b: MetaknowDeferredBasedOnPair) bool {
            if (a.src != b.src) return a.src < b.src;
            return a.dst < b.dst;
        }
    }.lessThan);

    var deduped = std.ArrayList(MetaknowDeferredBasedOnPair).empty;
    defer deduped.deinit(allocator);
    try deduped.ensureTotalCapacity(allocator, pairs.items.len);
    var previous: ?MetaknowDeferredBasedOnPair = null;
    for (pairs.items) |pair| {
        if (previous) |last| {
            if (last.src == pair.src and last.dst == pair.dst) continue;
        }
        try deduped.append(allocator, pair);
        previous = pair;
    }

    var reverse_pairs = std.ArrayList(MetaknowDeferredBasedOnPair).empty;
    defer reverse_pairs.deinit(allocator);
    try reverse_pairs.ensureTotalCapacity(allocator, deduped.items.len);
    for (deduped.items) |pair| {
        reverse_pairs.appendAssumeCapacity(.{ .src = pair.dst, .dst = pair.src });
    }
    std.mem.sort(MetaknowDeferredBasedOnPair, reverse_pairs.items, {}, struct {
        fn lessThan(_: void, a: MetaknowDeferredBasedOnPair, b: MetaknowDeferredBasedOnPair) bool {
            if (a.src != b.src) return a.src < b.src;
            return a.dst < b.dst;
        }
    }.lessThan);

    const forward_source_count = metaknowDeferredBasedOnGroupCount(deduped.items);
    const reverse_source_count = metaknowDeferredBasedOnGroupCount(reverse_pairs.items);
    try ensureMetaknowDeferredBasedOnU32Sized(deduped.items, forward_source_count);
    try ensureMetaknowDeferredBasedOnU32Sized(reverse_pairs.items, reverse_source_count);

    const forward_index_bytes = try std.math.mul(usize, forward_source_count, metaknow_deferred_based_on_index_record_len);
    const forward_target_bytes = try std.math.mul(usize, deduped.items.len, metaknow_deferred_based_on_target_record_len);
    const reverse_index_bytes = try std.math.mul(usize, reverse_source_count, metaknow_deferred_based_on_index_record_len);
    const reverse_target_bytes = try std.math.mul(usize, reverse_pairs.items.len, metaknow_deferred_based_on_target_record_len);
    const forward_target_offset = metaknow_deferred_based_on_header_len + forward_index_bytes;
    const reverse_index_offset = forward_target_offset + forward_target_bytes;
    const reverse_target_offset = reverse_index_offset + reverse_index_bytes;
    const total_bytes = try std.math.add(usize, reverse_target_offset, reverse_target_bytes);
    var bytes = try allocator.alloc(u8, total_bytes);
    defer allocator.free(bytes);
    @memset(bytes, 0);
    @memcpy(bytes[0..8], &metaknow_deferred_based_on_magic);
    std.mem.writeInt(u64, bytes[8..16], @intCast(forward_source_count), .little);
    std.mem.writeInt(u64, bytes[16..24], @intCast(deduped.items.len), .little);
    std.mem.writeInt(u64, bytes[24..32], @intCast(forward_target_offset), .little);
    std.mem.writeInt(u64, bytes[32..40], metaknow_deferred_based_on_edge_id_base, .little);
    std.mem.writeInt(u64, bytes[40..48], @intCast(node_count), .little);
    std.mem.writeInt(u64, bytes[48..56], @intCast(reverse_source_count), .little);
    std.mem.writeInt(u64, bytes[56..64], @intCast(reverse_pairs.items.len), .little);
    std.mem.writeInt(u64, bytes[64..72], @intCast(reverse_target_offset), .little);

    writeMetaknowDeferredBasedOnGroups(bytes, deduped.items, metaknow_deferred_based_on_header_len, forward_target_offset);
    writeMetaknowDeferredBasedOnGroups(bytes, reverse_pairs.items, reverse_index_offset, reverse_target_offset);

    const path = try metaknowDeferredBasedOnPath(allocator, store);
    defer allocator.free(path);
    var file = try std.Io.Dir.cwd().createFile(store.io, path, .{ .truncate = true });
    defer file.close(store.io);
    try file.writePositionalAll(store.io, bytes, 0);
    try file.setLength(store.io, @intCast(bytes.len));

    return .{
        .sources = forward_source_count,
        .links = deduped.items.len,
        .bytes = @intCast(bytes.len),
    };
}

fn readMetaknowDeferredBasedOnSidecarForwardPairs(
    allocator: std.mem.Allocator,
    io: std.Io,
    db_path: []const u8,
) !MetaknowDeferredBasedOnSidecarPairs {
    const path = try metaknowDeferredBasedOnPathForDb(allocator, db_path);
    defer allocator.free(path);
    const stat = std.Io.Dir.cwd().statFile(io, path, .{}) catch |err| switch (err) {
        error.FileNotFound => return .{},
        else => |e| return e,
    };
    if (stat.kind != .file or stat.size < metaknow_deferred_based_on_header_len) return error.InvalidRecord;

    var file = try std.Io.Dir.cwd().openFile(io, path, .{});
    defer file.close(io);

    var header: [metaknow_deferred_based_on_header_len]u8 = undefined;
    if (try file.readPositionalAll(io, &header, 0) != header.len) return error.InvalidRecord;
    if (!std.mem.eql(u8, header[0..8], &metaknow_deferred_based_on_magic)) return error.InvalidRecord;

    const forward_source_count = std.mem.readInt(u64, header[8..16], .little);
    const forward_link_count = std.mem.readInt(u64, header[16..24], .little);
    const forward_target_offset = std.mem.readInt(u64, header[24..32], .little);
    const reverse_source_count = std.mem.readInt(u64, header[48..56], .little);
    const reverse_link_count = std.mem.readInt(u64, header[56..64], .little);
    const reverse_target_offset = std.mem.readInt(u64, header[64..72], .little);

    const forward_index_bytes = try std.math.mul(u64, forward_source_count, metaknow_deferred_based_on_index_record_len);
    const forward_target_bytes = try std.math.mul(u64, forward_link_count, metaknow_deferred_based_on_target_record_len);
    const reverse_index_bytes = try std.math.mul(u64, reverse_source_count, metaknow_deferred_based_on_index_record_len);
    const reverse_target_bytes = try std.math.mul(u64, reverse_link_count, metaknow_deferred_based_on_target_record_len);
    const expected_forward_target_offset = try std.math.add(u64, metaknow_deferred_based_on_header_len, forward_index_bytes);
    if (forward_target_offset != expected_forward_target_offset) return error.InvalidRecord;
    const reverse_index_offset = try std.math.add(u64, forward_target_offset, forward_target_bytes);
    const expected_reverse_target_offset = try std.math.add(u64, reverse_index_offset, reverse_index_bytes);
    if (reverse_target_offset != expected_reverse_target_offset) return error.InvalidRecord;
    const expected_size = try std.math.add(u64, reverse_target_offset, reverse_target_bytes);
    if (stat.size != expected_size) return error.InvalidRecord;
    if (forward_link_count > std.math.maxInt(usize) or forward_index_bytes > std.math.maxInt(usize) or forward_target_bytes > std.math.maxInt(usize)) return error.RecordTooLarge;

    const index_len: usize = @intCast(forward_index_bytes);
    const target_len: usize = @intCast(forward_target_bytes);
    const index_bytes = try allocator.alloc(u8, index_len);
    defer allocator.free(index_bytes);
    const target_bytes = try allocator.alloc(u8, target_len);
    defer allocator.free(target_bytes);
    if (index_len != 0 and try file.readPositionalAll(io, index_bytes, metaknow_deferred_based_on_header_len) != index_len) return error.InvalidRecord;
    if (target_len != 0 and try file.readPositionalAll(io, target_bytes, forward_target_offset) != target_len) return error.InvalidRecord;

    var snapshot = MetaknowDeferredBasedOnSidecarPairs{ .present = true };
    errdefer snapshot.deinit(allocator);
    try snapshot.pairs.ensureTotalCapacity(allocator, @intCast(forward_link_count));
    var previous_src: u64 = 0;
    var previous_start: u64 = 0;
    for (0..@intCast(forward_source_count)) |index_pos| {
        const record_offset = index_pos * metaknow_deferred_based_on_index_record_len;
        const src: u64 = std.mem.readInt(u32, index_bytes[record_offset..][0..4], .little);
        const target_start: u64 = std.mem.readInt(u32, index_bytes[record_offset + 4 ..][0..4], .little);
        const count: u64 = std.mem.readInt(u32, index_bytes[record_offset + 8 ..][0..4], .little);
        if (index_pos != 0 and src <= previous_src) return error.InvalidRecord;
        if (index_pos != 0 and target_start < previous_start) return error.InvalidRecord;
        if (target_start > forward_link_count or count > forward_link_count - target_start) return error.InvalidRecord;
        previous_src = src;
        previous_start = target_start;
        for (0..@intCast(count)) |target_index| {
            const target_record_offset = (@as(usize, @intCast(target_start)) + target_index) * metaknow_deferred_based_on_target_record_len;
            const dst: u64 = std.mem.readInt(u32, target_bytes[target_record_offset..][0..4], .little);
            try snapshot.pairs.append(allocator, .{ .src = src, .dst = dst });
        }
    }
    return snapshot;
}

fn pruneMetaknowDeferredBasedOnPairsForNode(snapshot: *MetaknowDeferredBasedOnSidecarPairs, node_id: core.NodeId) void {
    const deleted = node_id.toInt();
    var write_index: usize = 0;
    for (snapshot.pairs.items) |pair| {
        if (pair.src == deleted or pair.dst == deleted) continue;
        snapshot.pairs.items[write_index] = pair;
        write_index += 1;
    }
    snapshot.pairs.shrinkRetainingCapacity(write_index);
}

fn restoreMetaknowDeferredBasedOnSidecar(
    allocator: std.mem.Allocator,
    store: storage.Store,
    snapshot: *const MetaknowDeferredBasedOnSidecarPairs,
) !void {
    if (!snapshot.present) return;
    const path = try metaknowDeferredBasedOnPath(allocator, store);
    defer allocator.free(path);
    if (snapshot.pairs.items.len == 0) {
        std.Io.Dir.cwd().deleteFile(store.io, path) catch |err| switch (err) {
            error.FileNotFound => {},
            else => |e| return e,
        };
        return;
    }
    const meta = try store.readIndexMeta();
    _ = try writeMetaknowDeferredBasedOnForwardPairsSidecar(allocator, store, snapshot.pairs.items, @intCast(meta.nodes));
}

fn metaknowDeferredBasedOnGroupCount(pairs: []const MetaknowDeferredBasedOnPair) usize {
    var count: usize = 0;
    var last_src: u64 = 0;
    for (pairs, 0..) |pair, index| {
        if (index == 0 or pair.src != last_src) {
            count += 1;
            last_src = pair.src;
        }
    }
    return count;
}

fn writeMetaknowDeferredBasedOnGroups(
    bytes: []u8,
    pairs: []const MetaknowDeferredBasedOnPair,
    index_offset: usize,
    target_offset: usize,
) void {
    var index_cursor: usize = index_offset;
    var target_cursor: usize = target_offset;
    var pair_index: usize = 0;
    while (pair_index < pairs.len) {
        const src = pairs[pair_index].src;
        const start = pair_index;
        while (pair_index < pairs.len and pairs[pair_index].src == src) : (pair_index += 1) {
            std.mem.writeInt(u32, bytes[target_cursor..][0..4], @intCast(pairs[pair_index].dst), .little);
            target_cursor += metaknow_deferred_based_on_target_record_len;
        }
        std.mem.writeInt(u32, bytes[index_cursor..][0..4], @intCast(src), .little);
        std.mem.writeInt(u32, bytes[index_cursor + 4 ..][0..4], @intCast(start), .little);
        std.mem.writeInt(u32, bytes[index_cursor + 8 ..][0..4], @intCast(pair_index - start), .little);
        index_cursor += metaknow_deferred_based_on_index_record_len;
    }
}

fn ensureMetaknowDeferredBasedOnU32Sized(pairs: []const MetaknowDeferredBasedOnPair, source_count: usize) !void {
    if (pairs.len > std.math.maxInt(u32)) return error.RecordTooLarge;
    if (source_count > std.math.maxInt(u32)) return error.RecordTooLarge;
    for (pairs) |pair| {
        if (pair.src > std.math.maxInt(u32) or pair.dst > std.math.maxInt(u32)) return error.RecordTooLarge;
    }
}

fn metaknowReplayCorpusIdentity(
    allocator: std.mem.Allocator,
    io: std.Io,
    corpus_dir_path: []const u8,
) !StoreContentIdentity {
    const input_names = [_][]const u8{
        "nodes.jsonl",
        "edges.jsonl",
        "manifest.json",
        "deferred_based_on.jsonl",
    };
    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    var total_bytes: u64 = 0;
    for (input_names) |name| {
        const path = try std.fs.path.join(allocator, &.{ corpus_dir_path, name });
        defer allocator.free(path);
        const stat = std.Io.Dir.cwd().statFile(io, path, .{ .follow_symlinks = false }) catch |err| switch (err) {
            error.FileNotFound, error.NotDir => {
                hasher.update("missing\x00");
                hashLengthPrefixed(&hasher, name);
                continue;
            },
            else => |e| return e,
        };
        if (stat.kind != .file) return error.InvalidRecord;
        total_bytes = std.math.add(u64, total_bytes, stat.size) catch return error.RecordTooLarge;
        try hashStoreFile(io, path, name, stat.size, &hasher);
    }
    return .{ .bytes = total_bytes, .digest = finalizeContentDigest(&hasher) };
}

fn planMetaknowReplayEdges(
    allocator: std.mem.Allocator,
    replay: *const BenchMetaknowReplay,
) !BenchMetaknowReplayEdgeStats {
    var id_map = try buildBenchMetaknowNodeIdMap(allocator, replay, replay.nodes.len);
    defer id_map.deinit();
    var stats = BenchMetaknowReplayEdgeStats{};
    for (replay.edges) |edge| {
        if (!id_map.contains(edge.src_original_id) or !id_map.contains(edge.dst_original_id)) {
            stats.edges_skipped_missing_endpoint += 1;
            continue;
        }
        stats.edges_used += 1;
        stats.recordRelation(edge.rel);
    }
    return stats;
}

const MetaknowReplayTaskStatusStream = struct {
    replay: *const BenchMetaknowReplay,
    next_node_index: usize = 0,

    fn next(raw_context: *anyopaque) anyerror!?storage.SortedPropertyPayloadEntry {
        const self: *MetaknowReplayTaskStatusStream = @ptrCast(@alignCast(raw_context));
        while (self.next_node_index < self.replay.nodes.len) {
            const node_index = self.next_node_index;
            self.next_node_index += 1;
            if (self.replay.nodes[node_index].kind != .task) continue;
            return .{
                .owner = .{ .node = .fromInt(@intCast(node_index + 1)) },
                .key_hash = storage.propertyKeyHashForLookup(task.status_property),
                .value = .{ .string = @tagName(task.Status.open) },
            };
        }
        return null;
    }
};

/// A replay import creates schema-v3 tasks, so every imported task needs the
/// canonical durable `status=open` marker.  Feed the already-sorted node ids
/// directly into the empty property base: repeated point writes would rebuild
/// the complete COW payload once per task and turn a dense import into O(N²).
fn materializeMetaknowReplayTaskStatuses(store: storage.Store, replay: *const BenchMetaknowReplay) !void {
    var task_count: u64 = 0;
    for (replay.nodes) |node| {
        if (node.kind == .task) task_count = std.math.add(u64, task_count, 1) catch return error.RecordTooLarge;
    }
    var stream = MetaknowReplayTaskStatusStream{ .replay = replay };
    try store.replaceEmptyPropertyPayloadFromSortedStream(task_count, &stream, MetaknowReplayTaskStatusStream.next);
}

fn importMetaknowReplayCorpus(
    allocator: std.mem.Allocator,
    io: std.Io,
    db_path: []const u8,
    corpus_dir_path: []const u8,
    chunk_size: usize,
    warm_text: bool,
) !MetaknowReplayImportResult {
    if (try pathsOverlap(allocator, io, db_path, corpus_dir_path)) return error.InvalidFileName;
    const corpus_identity_before = try metaknowReplayCorpusIdentity(allocator, io, corpus_dir_path);
    const replay = try loadBenchMetaknowReplay(allocator, io, corpus_dir_path);
    defer replay.deinit(allocator);
    const corpus_identity = try metaknowReplayCorpusIdentity(allocator, io, corpus_dir_path);
    if (corpus_identity.bytes != corpus_identity_before.bytes or
        !std.meta.eql(corpus_identity.digest, corpus_identity_before.digest))
    {
        return error.ImportSourceChanged;
    }
    const canonical_source_path = try canonicalProspectivePath(allocator, io, corpus_dir_path);
    defer allocator.free(canonical_source_path);
    const planned_edges = try planMetaknowReplayEdges(allocator, &replay);
    const expected_publication_result = ImportPublicationResult{
        .nodes_loaded = @intCast(replay.nodes.len),
        .nodes_imported = @intCast(replay.nodes.len),
        .edges_loaded = @intCast(replay.edges.len),
        .edges_imported = @intCast(planned_edges.edges_used),
        .edges_skipped_missing_endpoint = @intCast(planned_edges.edges_skipped_missing_endpoint),
        .source_bytes = corpus_identity.bytes,
        .text_warmed = warm_text,
    };
    const import_expectation = ImportTransactionExpectation{
        .format = "metaknow-replay",
        .canonical_source_path = canonical_source_path,
        .source_digest = corpus_identity.digest,
        .warm_text = warm_text,
        .chunk_size = @intCast(chunk_size),
    };
    const publish_lock = try CliStoreLock.acquireAdjacent(allocator, io, db_path, import_publish_lock_suffix);
    defer publish_lock.deinit();
    const staging_path = try importStagingPath(allocator, db_path);
    defer allocator.free(staging_path);
    try recoverImportStaging(allocator, io, staging_path, import_expectation, expected_publication_result);
    if (try recoverCompletedImport(allocator, io, db_path, import_expectation, expected_publication_result)) |recovered| {
        return .{
            .nodes_loaded = std.math.cast(usize, recovered.nodes_loaded) orelse return error.InvalidRecord,
            .nodes_imported = std.math.cast(usize, recovered.nodes_imported) orelse return error.InvalidRecord,
            .edges_loaded = std.math.cast(usize, recovered.edges_loaded) orelse return error.InvalidRecord,
            .edges_imported = std.math.cast(usize, recovered.edges_imported) orelse return error.InvalidRecord,
            .edges_skipped_missing_endpoint = std.math.cast(usize, recovered.edges_skipped_missing_endpoint) orelse return error.InvalidRecord,
            .corpus_bytes = recovered.source_bytes,
            .text_warmed = recovered.text_warmed,
            .marker_cleanup_pending = recovered.marker_cleanup_pending,
        };
    }
    if (try anyPathExists(io, db_path)) return error.AlreadyExists;
    try createOwnedDirectory(io, staging_path);
    var staging_owned = true;
    defer if (staging_owned) std.Io.Dir.cwd().deleteTree(io, staging_path) catch {};
    try writeImportTransactionMarker(allocator, io, staging_path, import_expectation, null);
    try syncExportDirectoryTree(allocator, io, staging_path);

    var store = try storage.Store.initWithOptions(allocator, io, staging_path, .{
        .primary_text_write_mode = .bulk_ingest,
    });
    var store_open = true;
    defer if (store_open) store.deinit();
    try store.createEmpty();

    var text_density = BenchTextDensityStats{};
    var node_timings = BenchNodeLoadTimings{};
    try appendBenchMetaknowNodesChunked(allocator, store, &replay, replay.nodes.len, chunk_size, false, &text_density, &node_timings);
    try store.finalizePrimaryTextStorage();
    try materializeMetaknowReplayTaskStatuses(store, &replay);
    const edge_stats = try appendBenchMetaknowEdgesChunked(allocator, store, &replay, replay.nodes.len, replay.edges.len, chunk_size, false);
    const deferred_stats = try writeBenchMetaknowDeferredBasedOnSidecar(allocator, store, &replay, replay.nodes.len);
    var import_edge_stats = edge_stats;
    import_edge_stats.deferred_based_on_binary_sources = deferred_stats.sources;
    import_edge_stats.deferred_based_on_binary_links = deferred_stats.links;
    import_edge_stats.deferred_based_on_binary_bytes = deferred_stats.bytes;
    if (warm_text) {
        _ = try text_search.rebuildPersistentTextCatalog(allocator, store);
    }
    try writeStoreManifest(allocator, io, staging_path, .{
        .profiles = "",
        .migration_name = "import-metaknow-replay",
    });
    var result = MetaknowReplayImportResult{
        .nodes_loaded = replay.nodes.len,
        .nodes_imported = replay.nodes.len,
        .edges_loaded = replay.edges.len,
        .edges_imported = import_edge_stats.edges_used,
        .edges_skipped_missing_endpoint = import_edge_stats.edges_skipped_missing_endpoint,
        .corpus_bytes = corpus_identity.bytes,
        .text_warmed = warm_text,
    };
    store.deinit();
    store_open = false;
    var publication_result = ImportPublicationResult{
        .nodes_loaded = @intCast(result.nodes_loaded),
        .nodes_imported = @intCast(result.nodes_imported),
        .edges_loaded = @intCast(result.edges_loaded),
        .edges_imported = @intCast(result.edges_imported),
        .edges_skipped_missing_endpoint = @intCast(result.edges_skipped_missing_endpoint),
        .source_bytes = result.corpus_bytes,
        .text_warmed = result.text_warmed,
    };
    if (!importPublicationMatchesSource(publication_result, expected_publication_result)) return error.InvalidRecord;
    try publishImportedStore(allocator, io, staging_path, db_path, import_expectation, &publication_result);
    staging_owned = false;
    result.marker_cleanup_pending = publication_result.marker_cleanup_pending;
    return result;
}

const native_jsonl_max_bytes: u64 = 256 * 1024 * 1024;
const native_jsonl_export_buffer_bytes: usize = 1024 * 1024;

const apply_batch_version: u32 = 1;
const apply_jsonl_max_bytes: u64 = 64 * 1024 * 1024;

const ApplyBatchResult = struct {
    nodes_created: usize = 0,
    nodes_existing: usize = 0,
    edges_created: usize = 0,
    edges_existing: usize = 0,
};

const ApplyHeaderJson = struct {
    version: u32,
};

const ApplyOpProbeJson = struct {
    op: ?[]const u8 = null,
    version: ?u32 = null,
};

const ApplyNodeJson = struct {
    op: []const u8,
    id: u64,
    kind: []const u8,
    name: []const u8,
};

const ApplyEdgeJson = struct {
    op: []const u8,
    id: u64,
    src: u64,
    rel: []const u8,
    dst: u64,
};

fn applyJsonlBatch(allocator: std.mem.Allocator, io: std.Io, store: storage.Store, path: []const u8) !ApplyBatchResult {
    const lines = try loadJsonlLineFile(allocator, io, path, apply_jsonl_max_bytes);
    defer lines.deinit(allocator);
    if (lines.records.len == 0) return error.InvalidRecord;

    var header = try std.json.parseFromSlice(ApplyHeaderJson, allocator, lines.records[0], .{
        .ignore_unknown_fields = true,
        .allocate = .alloc_always,
    });
    defer header.deinit();
    if (header.value.version != apply_batch_version) return core.Error.Unsupported;

    var result = ApplyBatchResult{};
    for (lines.records[1..]) |line| {
        var probe = try std.json.parseFromSlice(ApplyOpProbeJson, allocator, line, .{
            .ignore_unknown_fields = true,
            .allocate = .alloc_always,
        });
        defer probe.deinit();
        if (probe.value.version != null) return error.InvalidRecord;
        const op = probe.value.op orelse return error.InvalidRecord;
        if (std.mem.eql(u8, op, "node")) {
            var parsed = try std.json.parseFromSlice(ApplyNodeJson, allocator, line, .{
                .ignore_unknown_fields = true,
                .allocate = .alloc_always,
            });
            defer parsed.deinit();
            try applyNodeOp(allocator, store, parsed.value, &result);
        } else if (std.mem.eql(u8, op, "edge")) {
            var parsed = try std.json.parseFromSlice(ApplyEdgeJson, allocator, line, .{
                .ignore_unknown_fields = true,
                .allocate = .alloc_always,
            });
            defer parsed.deinit();
            try applyEdgeOp(store, parsed.value, &result);
        } else {
            return error.Unsupported;
        }
    }
    return result;
}

fn applyNodeOp(allocator: std.mem.Allocator, store: storage.Store, op: ApplyNodeJson, result: *ApplyBatchResult) !void {
    if (!std.mem.eql(u8, op.op, "node")) return error.InvalidRecord;
    const id = core.NodeId.fromInt(op.id);
    if (id == .none or id.toInt() == std.math.maxInt(u64)) return core.Error.InvalidId;
    const kind = parseCliNodeKind(op.kind) orelse return error.InvalidNodeKind;
    if (try store.readNodeById(allocator, id)) |existing_node| {
        var existing = existing_node;
        defer existing.deinit(allocator);
        if (existing.kind != kind or !std.mem.eql(u8, existing.text, op.name)) return error.Conflict;
        result.nodes_existing += 1;
        return;
    }
    try store.appendNode(.{
        .id = id,
        .kind = kind,
        .text = op.name,
    });
    result.nodes_created += 1;
}

fn applyEdgeOp(store: storage.Store, op: ApplyEdgeJson, result: *ApplyBatchResult) !void {
    if (!std.mem.eql(u8, op.op, "edge")) return error.InvalidRecord;
    const id = core.EdgeId.fromInt(op.id);
    if (id == .none or id.toInt() == std.math.maxInt(u64)) return core.Error.InvalidId;
    const src = core.NodeId.fromInt(op.src);
    const dst = core.NodeId.fromInt(op.dst);
    const rel = parseCliRelKind(op.rel) orelse return error.InvalidRelKind;
    // `readEdgeById` returns `core.Error.InvalidId` for an absent edge id; treat that as
    // "not present" so the batch stays idempotent (existing identical edges are skipped).
    const existing_edge: ?graph.Edge = store.readEdgeById(id) catch |err| switch (err) {
        core.Error.InvalidId => null,
        else => |e| return e,
    };
    if (existing_edge) |existing| {
        if (existing.src != src or existing.dst != dst or existing.rel != rel) return error.Conflict;
        result.edges_existing += 1;
        return;
    }
    try store.appendEdge(.{
        .id = id,
        .src = src,
        .rel = rel,
        .dst = dst,
    });
    result.edges_created += 1;
}
const native_jsonl_deferred_based_on_file = "deferred_based_on.jsonl";
const native_markdown_max_bytes: u64 = 512 * 1024 * 1024;
const agent_write_json_max_bytes: u64 = 16 * 1024 * 1024;
const markdown_ast_text_chunk_chars: usize = 5000;
const markdown_nodes_dir = "nodes";
const markdown_edges_file = "edges.md";
const markdown_relations_dir = "relations";
const markdown_deferred_based_on_file = "deferred_based_on.md";
const markdown_readme_file = "README.md";

