    edge_created: bool,
};

const MarkdownPendingProjectionEdge = struct {
    src: core.NodeId,
    rel: core.RelKind,
    dst: core.NodeId,
    order_key: u64,
};

const MarkdownPendingNodeProperties = struct {
    node_id: core.NodeId,
    schema_type: []u8,
    external_key: []u8,
    content_hash: ?[]u8 = null,

    fn deinit(self: *MarkdownPendingNodeProperties, allocator: std.mem.Allocator) void {
        allocator.free(self.schema_type);
        allocator.free(self.external_key);
        if (self.content_hash) |value| allocator.free(value);
    }
};

fn markdownPendingNodePropertiesAlloc(
    allocator: std.mem.Allocator,
    node_id: core.NodeId,
    schema_type: []const u8,
    external_key: []const u8,
    content_hash: ?[]const u8,
) !MarkdownPendingNodeProperties {
    const owned_schema_type = try allocator.dupe(u8, schema_type);
    errdefer allocator.free(owned_schema_type);
    const owned_external_key = try allocator.dupe(u8, external_key);
    errdefer allocator.free(owned_external_key);
    const owned_content_hash = if (content_hash) |value| try allocator.dupe(u8, value) else null;
    errdefer if (owned_content_hash) |value| allocator.free(value);
    return .{
        .node_id = node_id,
        .schema_type = owned_schema_type,
        .external_key = owned_external_key,
        .content_hash = owned_content_hash,
    };
}

const MarkdownImportContext = struct {
    allocator: std.mem.Allocator,
    io: std.Io,
    store: storage.Store,
    document_external_key: []const u8,
    lookup_view: storage.Store.NodeTextLookupView,
    session_node_ids: std.StringHashMap(core.NodeId),
    session_node_external_keys: std.AutoHashMap(u64, []u8),
    session_edge_counts: std.StringHashMap(usize),
    desired_projection_owners: std.AutoHashMap(u64, void),
    session_owner_order_counts: std.AutoHashMap(u64, usize),
    pending_nodes: std.ArrayList(graph.Node) = .empty,
    pending_node_properties: std.ArrayList(MarkdownPendingNodeProperties) = .empty,
    pending_edges: std.ArrayList(MarkdownPendingProjectionEdge) = .empty,
    next_pending_node_id: ?core.NodeId = null,
    node_lookup_cache: ?storage.NodeExternalKeyLookupCache = null,
    edge_lookup_cache: ?storage.EdgeExternalKeyLookupCache = null,
    use_cached_node_lookup: bool = false,
    reuse_existing_projection_edges: bool = true,
    session_chunked_block_count: usize = 0,
    edge_identity_index_dirty: bool = false,
    /// order_key 撞车修复:每个 (src,rel,dst) 位置键按**文档出现序**入队(所有路径,不只复用)。
    /// import 尾 assignProjectionOrderKeys 用与 reconcile **同一 ordered 读**遍历活边,逐边 pop
    /// 队首键,diff 才 upsert——与 reconcile 的保留选择天然一致(Linus 严重2:旧 claim 用索引序
    /// 选边、reconcile 用 order 序保留,两套顺序会把新键写给将被删的边,活边留陈旧键撞车没修)。
    /// key 含 dst → 分配不依赖遍历序(每 dst 队列独立);同 dst 重复段按遍历序 pop,相对序保持。
    /// agent-write 路径不 reconcile 不消费此表(其边 order 由 append 正确写,行为同旧版)。
    pending_position_keys: std.StringHashMap(std.ArrayList(u64)),

    fn deinit(self: *MarkdownImportContext) void {
        if (self.node_lookup_cache) |*cache| cache.deinit();
        if (self.edge_lookup_cache) |*cache| cache.deinit();
        for (self.pending_nodes.items) |node| self.allocator.free(node.text);
        self.pending_nodes.deinit(self.allocator);
        for (self.pending_node_properties.items) |*properties| properties.deinit(self.allocator);
        self.pending_node_properties.deinit(self.allocator);
        self.pending_edges.deinit(self.allocator);
        var node_iterator = self.session_node_ids.iterator();
        while (node_iterator.next()) |entry| self.allocator.free(entry.key_ptr.*);
        self.session_node_ids.deinit();
        var node_key_iterator = self.session_node_external_keys.iterator();
        while (node_key_iterator.next()) |entry| self.allocator.free(entry.value_ptr.*);
        self.session_node_external_keys.deinit();
        var edge_iterator = self.session_edge_counts.iterator();
        while (edge_iterator.next()) |entry| self.allocator.free(entry.key_ptr.*);
        self.session_edge_counts.deinit();
        self.desired_projection_owners.deinit();
        self.session_owner_order_counts.deinit();
        var pk_it = self.pending_position_keys.iterator();
        while (pk_it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            entry.value_ptr.deinit(self.allocator);
        }
        self.pending_position_keys.deinit();
        self.lookup_view.deinit();
    }
};

fn importMarkdownDocument(
    allocator: std.mem.Allocator,
    io: std.Io,
    store: storage.Store,
    file_path: []const u8,
) !MarkdownDocumentImportResult {
    const stat = try std.Io.Dir.cwd().statFile(io, file_path, .{});
    if (stat.kind != .file or stat.size > native_markdown_max_bytes) return error.InvalidRecord;
    const content = try std.Io.Dir.cwd().readFileAlloc(io, file_path, allocator, .limited(native_markdown_max_bytes));
    defer allocator.free(content);

    const title = markdownDocumentTitle(content) orelse std.fs.path.basename(file_path);
    const document_external_key = try std.fmt.allocPrint(allocator, "md-doc:{s}", .{file_path});
    defer allocator.free(document_external_key);
    const document_text = try std.fmt.allocPrint(allocator, "markdown_document title=\"{s}\" source=\"{s}\"", .{ title, file_path });
    defer allocator.free(document_text);
    const document_node_text = try markdownIdentityNodeText(allocator, .{
        .text = document_text,
        .schema_type = "document",
        .external_key = document_external_key,
    });
    defer allocator.free(document_node_text);

    var context = MarkdownImportContext{
        .allocator = allocator,
        .io = io,
        .store = store,
        .document_external_key = document_external_key,
        .lookup_view = try store.openNodeTextLookupView(allocator),
        .session_node_ids = std.StringHashMap(core.NodeId).init(allocator),
        .session_node_external_keys = std.AutoHashMap(u64, []u8).init(allocator),
        .session_edge_counts = std.StringHashMap(usize).init(allocator),
        .desired_projection_owners = std.AutoHashMap(u64, void).init(allocator),
        .session_owner_order_counts = std.AutoHashMap(u64, usize).init(allocator),
        .pending_position_keys = std.StringHashMap(std.ArrayList(u64)).init(allocator),
    };
    defer context.deinit();

    var result = MarkdownDocumentImportResult{
        .document_id = .none,
        .markdown_bytes = @intCast(content.len),
    };
    const nodes_before_document = result.nodes_imported;
    result.document_id = try markdownUpsertNode(&context, .document, document_node_text, document_external_key, "document", null, &result);
    const document_created = result.nodes_imported != nodes_before_document;
    context.use_cached_node_lookup = !document_created;
    context.reuse_existing_projection_edges = !document_created;
    const document_id = result.document_id;

    var lines = std.ArrayList([]const u8).empty;
    defer lines.deinit(allocator);
    var split = std.mem.splitScalar(u8, content, '\n');
    while (split.next()) |line_raw| {
        try lines.append(allocator, trimMarkdownLineRight(line_raw));
    }

    var paragraph = std.ArrayList(u8).empty;
    defer paragraph.deinit(allocator);

    var index: usize = 0;
    var table_index: usize = 0;
    var heading_index: usize = 0;
    var current_owner_id = document_id;
    while (index < lines.items.len) {
        const line = lines.items[index];
        if (std.mem.trim(u8, line, " \t").len == 0) {
            try importMarkdownFlushParagraph(&context, current_owner_id, &paragraph, &result);
            index += 1;
            continue;
        }
        if (markdownHeading(line)) |heading| {
            try importMarkdownFlushParagraph(&context, current_owner_id, &paragraph, &result);
            const section = try importMarkdownHeadingSection(&context, document_id, heading_index, heading, &result);
            if (section.edge_created) result.edges_imported += 1;
            current_owner_id = section.id;
            heading_index += 1;
            index += 1;
            continue;
        }
        if (markdownFenceMarker(line)) |marker| {
            try importMarkdownFlushParagraph(&context, current_owner_id, &paragraph, &result);
            var block = std.ArrayList(u8).empty;
            defer block.deinit(allocator);
            try block.appendSlice(allocator, line);
            try block.append(allocator, '\n');
            index += 1;
            while (index < lines.items.len) : (index += 1) {
                try block.appendSlice(allocator, lines.items[index]);
                try block.append(allocator, '\n');
                if (markdownFenceCloses(lines.items[index], marker)) {
                    index += 1;
                    break;
                }
            }
            try importMarkdownProjectionBlock(&context, current_owner_id, .{ .rel = md_rel_code_block, .text = block.items }, &result);
            continue;
        }
        if (markdownImageLine(line)) {
            try importMarkdownFlushParagraph(&context, current_owner_id, &paragraph, &result);
            try importMarkdownProjectionBlock(&context, current_owner_id, .{ .rel = md_rel_image, .text = std.mem.trim(u8, line, " \t") }, &result);
            index += 1;
            continue;
        }
        if (markdownListLine(line)) {
            try importMarkdownFlushParagraph(&context, current_owner_id, &paragraph, &result);
            const start = index;
            index += 1;
            while (index < lines.items.len and markdownListContinuationLine(lines.items[index])) : (index += 1) {}
            try importMarkdownProjectionLines(&context, current_owner_id, md_rel_list, lines.items[start..index], &result);
            continue;
        }
        if (markdownBlockquoteLine(line)) {
            try importMarkdownFlushParagraph(&context, current_owner_id, &paragraph, &result);
            const start = index;
            while (index < lines.items.len and markdownBlockquoteLine(lines.items[index])) : (index += 1) {}
            try importMarkdownProjectionLines(&context, current_owner_id, md_rel_blockquote, lines.items[start..index], &result);
            continue;
        }
        if (markdownFootnoteDefinitionLine(line)) {
            try importMarkdownFlushParagraph(&context, current_owner_id, &paragraph, &result);
            const start = index;
            index += 1;
            while (index < lines.items.len and markdownIndentedContinuationLine(lines.items[index])) : (index += 1) {}
            try importMarkdownProjectionLines(&context, current_owner_id, md_rel_footnote_def, lines.items[start..index], &result);
            continue;
        }
        if (markdownLinkReferenceLine(line)) {
            try importMarkdownFlushParagraph(&context, current_owner_id, &paragraph, &result);
            try importMarkdownProjectionBlock(&context, current_owner_id, .{ .rel = md_rel_link_reference, .text = std.mem.trim(u8, line, " \t") }, &result);
            index += 1;
            continue;
        }
        if (markdownHtmlBlockLine(line)) {
            try importMarkdownFlushParagraph(&context, current_owner_id, &paragraph, &result);
            const start = index;
            while (index < lines.items.len and std.mem.trim(u8, lines.items[index], " \t").len != 0) : (index += 1) {}
            try importMarkdownProjectionLines(&context, current_owner_id, md_rel_html_block, lines.items[start..index], &result);
            continue;
        }
        if (markdownThematicBreakLine(line)) {
            try importMarkdownFlushParagraph(&context, current_owner_id, &paragraph, &result);
            try importMarkdownProjectionBlock(&context, current_owner_id, .{ .rel = md_rel_thematic_break, .text = std.mem.trim(u8, line, " \t") }, &result);
            index += 1;
            continue;
        }
        if (markdownRawFallbackLine(line)) {
            try importMarkdownFlushParagraph(&context, current_owner_id, &paragraph, &result);
            const start = index;
            index += 1;
            while (index < lines.items.len and markdownRawFallbackContinuationLine(lines.items[index])) : (index += 1) {}
            try importMarkdownProjectionLines(&context, current_owner_id, md_rel_raw_block, lines.items[start..index], &result);
            continue;
        }
        if (markdownTableLine(line)) {
            try importMarkdownFlushParagraph(&context, current_owner_id, &paragraph, &result);
            const start = index;
            while (index < lines.items.len and markdownTableLine(lines.items[index])) : (index += 1) {}
            try importMarkdownTable(&context, current_owner_id, table_index, lines.items[start..index], &result);
            table_index += 1;
            continue;
        }
        if (markdownSetextHeadingStart(lines.items, index)) {
            try importMarkdownFlushParagraph(&context, current_owner_id, &paragraph, &result);
            try importMarkdownProjectionLines(&context, current_owner_id, md_rel_raw_block, lines.items[index .. index + 2], &result);
            index += 2;
            continue;
        }
        if (paragraph.items.len != 0) try paragraph.append(allocator, '\n');
        try paragraph.appendSlice(allocator, line);
        index += 1;
    }
    try importMarkdownFlushParagraph(&context, current_owner_id, &paragraph, &result);
    try flushMarkdownImportPendingWrites(&context);
    if (!document_created) {
        result.projection_edges_deleted = try reconcileMarkdownProjectionEdges(&context, document_id);
        try assignProjectionOrderKeys(&context, document_id);
    }
    if (context.edge_identity_index_dirty or result.projection_edges_deleted != 0) {
        try context.store.rebuildEdgeExternalKeyIndex();
    }
    return result;
}

fn importMarkdownAst(
    allocator: std.mem.Allocator,
    io: std.Io,
    store: storage.Store,
    parsed: ParsedImportMarkdownAstArgs,
) !MarkdownDocumentImportResult {
    const bytes = try readMarkdownAstInputAlloc(allocator, io, parsed.ast_path);
    defer allocator.free(bytes);
    var parsed_json = try std.json.parseFromSlice(std.json.Value, allocator, bytes, .{});
    defer parsed_json.deinit();
    const root = try mdastRootValue(&parsed_json.value);
    return importMarkdownAstRoot(allocator, io, store, parsed.source_id, root, bytes.len);
}

fn mdastRootValue(value: *const std.json.Value) !*const std.json.Value {
    if (mdastStringField(value, "type")) |node_type| {
        if (std.mem.eql(u8, node_type, "root")) return value;
    }
    const tree = mdastObjectField(value, "tree") orelse return error.InvalidRecord;
    if (!std.mem.eql(u8, try mdastNodeType(tree), "root")) return error.InvalidRecord;
    return tree;
}

fn readMarkdownAstInputAlloc(allocator: std.mem.Allocator, io: std.Io, ast_path: []const u8) ![]u8 {
    if (std.mem.eql(u8, ast_path, "-")) {
        var buffer: [8192]u8 = undefined;
        var reader = std.Io.File.stdin().readerStreaming(io, &buffer);
        return try reader.interface.allocRemaining(allocator, .limited64(native_markdown_max_bytes));
    }
    const stat = try std.Io.Dir.cwd().statFile(io, ast_path, .{});
    if (stat.kind != .file or stat.size == 0 or stat.size > native_markdown_max_bytes) return error.InvalidRecord;
    return try std.Io.Dir.cwd().readFileAlloc(io, ast_path, allocator, .limited(native_markdown_max_bytes));
}

fn importMarkdownAstRoot(
    allocator: std.mem.Allocator,
    io: std.Io,
    store: storage.Store,
    source_id: []const u8,
    root: *const std.json.Value,
    ast_bytes: usize,
) !MarkdownDocumentImportResult {
    const title = try mdastDocumentTitleAlloc(allocator, root, source_id);
    defer allocator.free(title);
    const safe_title = try markdownNodeLabelWithinMaxCharsAlloc(allocator, title, "document-title", 4096);
    defer allocator.free(safe_title);
    const document_external_key = try std.fmt.allocPrint(allocator, "md-ast:{s}", .{source_id});
    defer allocator.free(document_external_key);
    const document_text = try std.fmt.allocPrint(allocator, "markdown_ast_document title=\"{s}\" source=\"{s}\"", .{ safe_title, source_id });
    defer allocator.free(document_text);
    const document_node_text = try markdownIdentityNodeText(allocator, .{
        .text = document_text,
        .schema_type = "document",
        .external_key = document_external_key,
    });
    defer allocator.free(document_node_text);

    var context = MarkdownImportContext{
        .allocator = allocator,
        .io = io,
        .store = store,
        .document_external_key = document_external_key,
        .lookup_view = try store.openNodeTextLookupView(allocator),
        .session_node_ids = std.StringHashMap(core.NodeId).init(allocator),
        .session_node_external_keys = std.AutoHashMap(u64, []u8).init(allocator),
        .session_edge_counts = std.StringHashMap(usize).init(allocator),
        .desired_projection_owners = std.AutoHashMap(u64, void).init(allocator),
        .session_owner_order_counts = std.AutoHashMap(u64, usize).init(allocator),
        .pending_position_keys = std.StringHashMap(std.ArrayList(u64)).init(allocator),
    };
    defer context.deinit();

    var result = MarkdownDocumentImportResult{
        .document_id = .none,
        .markdown_bytes = @intCast(ast_bytes),
    };
    const nodes_before_document = result.nodes_imported;
    result.document_id = try markdownUpsertNode(&context, .document, document_node_text, document_external_key, "document", null, &result);
    const document_created = result.nodes_imported != nodes_before_document;
    context.use_cached_node_lookup = !document_created;
    context.reuse_existing_projection_edges = !document_created;
    try importMdastChildren(&context, result.document_id, mdastChildren(root), &result);
    try flushMarkdownImportPendingWrites(&context);
    if (!document_created) {
        result.projection_edges_deleted = try reconcileMarkdownProjectionEdges(&context, result.document_id);
        try assignProjectionOrderKeys(&context, result.document_id);
    }
    if (context.edge_identity_index_dirty or result.projection_edges_deleted != 0) {
        try context.store.rebuildEdgeExternalKeyIndex();
    }
    return result;
}

fn mdastObjectField(value: *const std.json.Value, name: []const u8) ?*const std.json.Value {
    if (value.* != .object) return null;
    return value.object.getPtr(name);
}

fn mdastNodeType(value: *const std.json.Value) ![]const u8 {
    const type_value = mdastObjectField(value, "type") orelse return error.InvalidRecord;
    if (type_value.* != .string) return error.InvalidRecord;
    return type_value.string;
}

fn mdastStringField(value: *const std.json.Value, name: []const u8) ?[]const u8 {
    const field = mdastObjectField(value, name) orelse return null;
    return if (field.* == .string) field.string else null;
}

fn mdastBoolField(value: *const std.json.Value, name: []const u8) ?bool {
    const field = mdastObjectField(value, name) orelse return null;
    return if (field.* == .bool) field.bool else null;
}

fn mdastIntegerField(value: *const std.json.Value, name: []const u8) ?i64 {
    const field = mdastObjectField(value, name) orelse return null;
    return switch (field.*) {
        .integer => |int| int,
        else => null,
    };
}

fn mdastChildren(value: *const std.json.Value) []const std.json.Value {
    const children = mdastObjectField(value, "children") orelse return &.{};
    return if (children.* == .array) children.array.items else &.{};
}

const MdastImportState = struct {
    heading_index: usize = 0,
    table_index: usize = 0,
};

fn importMdastChildren(
    context: *MarkdownImportContext,
    document_id: core.NodeId,
    children: []const std.json.Value,
    result: *MarkdownDocumentImportResult,
) !void {
    var state = MdastImportState{};
    var current_owner_id = document_id;
    for (children) |*child| {
        if (std.mem.eql(u8, try mdastNodeType(child), "heading")) {
            const section = try importMdastHeading(context, document_id, child, &state, result);
            if (section.edge_created) result.edges_imported += 1;
            current_owner_id = section.id;
        } else {
            try importMdastBlock(context, current_owner_id, child, &state, result);
        }
    }
}

fn importMdastHeading(
    context: *MarkdownImportContext,
    document_id: core.NodeId,
    node: *const std.json.Value,
    state: *MdastImportState,
    result: *MarkdownDocumentImportResult,
) !MarkdownHeadingSection {
    const depth_raw = mdastIntegerField(node, "depth") orelse 1;
    const depth: usize = @intCast(@max(1, @min(depth_raw, 6)));
    const text = try mdastInlineTextAlloc(context.allocator, node);
    defer context.allocator.free(text);
    const section = try importMarkdownHeadingSection(context, document_id, state.heading_index, .{
        .level = depth,
        .text = text,
    }, result);
    state.heading_index += 1;
    return section;
}

fn importMdastBlock(
    context: *MarkdownImportContext,
    owner_id: core.NodeId,
    node: *const std.json.Value,
    state: *MdastImportState,
    result: *MarkdownDocumentImportResult,
) !void {
    const node_type = try mdastNodeType(node);
    if (std.mem.eql(u8, node_type, "paragraph")) {
        const text = try mdastInlineTextAlloc(context.allocator, node);
        defer context.allocator.free(text);
        return importMarkdownProjectionBlock(context, owner_id, .{ .rel = md_rel_paragraph, .text = text }, result);
    }
    if (std.mem.eql(u8, node_type, "code")) {
        const text = try mdastCodeBlockTextAlloc(context.allocator, node);
        defer context.allocator.free(text);
        return importMarkdownProjectionBlock(context, owner_id, .{ .rel = md_rel_code_block, .text = text }, result);
    }
    if (std.mem.eql(u8, node_type, "html")) {
        const text = try context.allocator.dupe(u8, mdastStringField(node, "value") orelse "");
        defer context.allocator.free(text);
        return importMarkdownProjectionBlock(context, owner_id, .{ .rel = md_rel_html_block, .text = text }, result);
    }
    if (std.mem.eql(u8, node_type, "image")) {
        const text = try mdastImageTextAlloc(context.allocator, node);
        defer context.allocator.free(text);
        return importMarkdownProjectionBlock(context, owner_id, .{ .rel = md_rel_image, .text = text }, result);
    }
    if (std.mem.eql(u8, node_type, "list")) {
        const text = try mdastListTextAlloc(context.allocator, node);
        defer context.allocator.free(text);
        return importMarkdownProjectionBlock(context, owner_id, .{ .rel = md_rel_list, .text = text }, result);
    }
    if (std.mem.eql(u8, node_type, "blockquote")) {
        const text = try mdastBlockquoteTextAlloc(context.allocator, node);
        defer context.allocator.free(text);
        return importMarkdownProjectionBlock(context, owner_id, .{ .rel = md_rel_blockquote, .text = text }, result);
    }
    if (std.mem.eql(u8, node_type, "thematicBreak")) {
        return importMarkdownProjectionBlock(context, owner_id, .{ .rel = md_rel_thematic_break, .text = "---" }, result);
    }
    if (std.mem.eql(u8, node_type, "definition")) {
        const text = try mdastDefinitionTextAlloc(context.allocator, node, false);
        defer context.allocator.free(text);
        return importMarkdownProjectionBlock(context, owner_id, .{ .rel = md_rel_link_reference, .text = text }, result);
    }
    if (std.mem.eql(u8, node_type, "footnoteDefinition")) {
        const text = try mdastDefinitionTextAlloc(context.allocator, node, true);
        defer context.allocator.free(text);
        return importMarkdownProjectionBlock(context, owner_id, .{ .rel = md_rel_footnote_def, .text = text }, result);
    }
    if (std.mem.eql(u8, node_type, "table")) {
        return importMdastTable(context, owner_id, node, state, result);
    }
    const text = try mdastFallbackTextAlloc(context.allocator, node);
    defer context.allocator.free(text);
    if (text.len != 0) {
        try importMarkdownProjectionBlock(context, owner_id, .{ .rel = md_rel_raw_block, .text = text }, result);
    }
}

fn importMdastTable(
    context: *MarkdownImportContext,
    owner_id: core.NodeId,
    node: *const std.json.Value,
    state: *MdastImportState,
    result: *MarkdownDocumentImportResult,
) !void {
    const table_external_key = try std.fmt.allocPrint(context.allocator, "{s}#ast-table:{d}", .{ context.document_external_key, state.table_index });
    defer context.allocator.free(table_external_key);
    state.table_index += 1;
    const table_id = try importMarkdownOccurrenceNode(context, "markdown_table", "markdown_table", table_external_key, result);
    if (try appendMarkdownProjectionEdge(context, owner_id, md_rel_table, table_id)) result.edges_imported += 1;
    for (mdastChildren(node), 0..) |*row, row_index| {
        if (!std.mem.eql(u8, try mdastNodeType(row), "tableRow")) continue;
        const row_external_key = try std.fmt.allocPrint(context.allocator, "{s}#row:{d}", .{ table_external_key, row_index });
        defer context.allocator.free(row_external_key);
        const row_id = try importMarkdownOccurrenceNode(context, "markdown_table_row", "markdown_table_row", row_external_key, result);
        if (try appendMarkdownProjectionEdge(context, table_id, md_rel_table_row, row_id)) result.edges_imported += 1;
        for (mdastChildren(row)) |*cell| {
            if (!std.mem.eql(u8, try mdastNodeType(cell), "tableCell")) continue;
            const text = try mdastInlineTextAlloc(context.allocator, cell);
            defer context.allocator.free(text);
            try importMarkdownProjectionBlock(context, row_id, .{ .rel = md_rel_table_cell, .text = text }, result);
        }
    }
}

fn mdastDocumentTitleAlloc(allocator: std.mem.Allocator, root: *const std.json.Value, fallback: []const u8) ![]u8 {
    for (mdastChildren(root)) |*child| {
        if (std.mem.eql(u8, try mdastNodeType(child), "heading")) {
            const depth = mdastIntegerField(child, "depth") orelse 1;
            if (depth == 1) return mdastInlineTextAlloc(allocator, child);
        }
    }
    return try allocator.dupe(u8, fallback);
}

fn mdastInlineTextAlloc(allocator: std.mem.Allocator, node: *const std.json.Value) ![]u8 {
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);
    try appendMdastInlineText(&out, allocator, node);
    return out.buffer.toOwnedSlice(allocator);
}

fn appendMdastInlineText(out: *QueryOutputWriter, allocator: std.mem.Allocator, node: *const std.json.Value) !void {
    const node_type = try mdastNodeType(node);
    if (std.mem.eql(u8, node_type, "text")) return out.writeAll(mdastStringField(node, "value") orelse "");
    if (std.mem.eql(u8, node_type, "inlineCode")) {
        try out.writeAll("`");
        try out.writeAll(mdastStringField(node, "value") orelse "");
        return out.writeAll("`");
    }
    if (std.mem.eql(u8, node_type, "break")) return out.writeAll("\n");
    if (std.mem.eql(u8, node_type, "image")) {
        const image = try mdastImageTextAlloc(allocator, node);
        defer allocator.free(image);
        return out.writeAll(image);
    }
    if (std.mem.eql(u8, node_type, "link")) {
        try out.writeAll("[");
        for (mdastChildren(node)) |*child| try appendMdastInlineText(out, allocator, child);
        try out.writeAll("](");
        try out.writeAll(mdastStringField(node, "url") orelse "");
        return out.writeAll(")");
    }
    if (std.mem.eql(u8, node_type, "strong")) try out.writeAll("**");
    if (std.mem.eql(u8, node_type, "emphasis")) try out.writeAll("*");
    if (std.mem.eql(u8, node_type, "delete")) try out.writeAll("~~");
    if (mdastStringField(node, "value")) |value| try out.writeAll(value);
    for (mdastChildren(node)) |*child| try appendMdastInlineText(out, allocator, child);
    if (std.mem.eql(u8, node_type, "strong")) return out.writeAll("**");
    if (std.mem.eql(u8, node_type, "emphasis")) return out.writeAll("*");
    if (std.mem.eql(u8, node_type, "delete")) return out.writeAll("~~");
}

fn mdastCodeBlockTextAlloc(allocator: std.mem.Allocator, node: *const std.json.Value) ![]u8 {
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);
    try out.writeAll("```");
    if (mdastStringField(node, "lang")) |lang| try out.writeAll(lang);
    if (mdastStringField(node, "meta")) |meta| {
        try out.writeAll(" ");
        try out.writeAll(meta);
    }
    try out.writeAll("\n");
    try out.writeAll(mdastStringField(node, "value") orelse "");
    try out.writeAll("\n```");
    return out.buffer.toOwnedSlice(allocator);
}

fn mdastImageTextAlloc(allocator: std.mem.Allocator, node: *const std.json.Value) ![]u8 {
    return try std.fmt.allocPrint(allocator, "![{s}]({s})", .{ mdastStringField(node, "alt") orelse "", mdastStringField(node, "url") orelse "" });
}

fn mdastListTextAlloc(allocator: std.mem.Allocator, node: *const std.json.Value) ![]u8 {
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);
    const ordered = mdastBoolField(node, "ordered") orelse false;
    var ordinal: usize = @intCast(@max(1, mdastIntegerField(node, "start") orelse 1));
    for (mdastChildren(node)) |*item| {
        const marker = if (ordered) try std.fmt.allocPrint(allocator, "{}. ", .{ordinal}) else try allocator.dupe(u8, "- ");
        defer allocator.free(marker);
        const item_text = try mdastFallbackTextAlloc(allocator, item);
        defer allocator.free(item_text);
        try appendMarkdownPrefixedLines(&out, marker, item_text);
        ordinal += 1;
    }
    return out.buffer.toOwnedSlice(allocator);
}

fn mdastBlockquoteTextAlloc(allocator: std.mem.Allocator, node: *const std.json.Value) ![]u8 {
    const text = try mdastFallbackTextAlloc(allocator, node);
    defer allocator.free(text);
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);
    try appendMarkdownPrefixedLines(&out, "> ", text);
    return out.buffer.toOwnedSlice(allocator);
}

fn appendMarkdownPrefixedLines(out: *QueryOutputWriter, prefix: []const u8, text: []const u8) !void {
    var lines = std.mem.splitScalar(u8, text, '\n');
    var first = true;
    while (lines.next()) |line| {
        if (!first) try out.writeAll("\n");
        first = false;
        if (line.len != 0) try out.writeAll(prefix);
        try out.writeAll(line);
    }
    try out.writeAll("\n");
}

fn mdastDefinitionTextAlloc(allocator: std.mem.Allocator, node: *const std.json.Value, footnote: bool) ![]u8 {
    const id = mdastStringField(node, "identifier") orelse mdastStringField(node, "label") orelse "ref";
    if (footnote) {
        const text = try mdastFallbackTextAlloc(allocator, node);
        defer allocator.free(text);
        return try std.fmt.allocPrint(allocator, "[^{s}]: {s}", .{ id, text });
    }
    if (mdastStringField(node, "title")) |title| {
        return try std.fmt.allocPrint(allocator, "[{s}]: {s} \"{s}\"", .{ id, mdastStringField(node, "url") orelse "", title });
    }
    return try std.fmt.allocPrint(allocator, "[{s}]: {s}", .{ id, mdastStringField(node, "url") orelse "" });
}

fn mdastFallbackTextAlloc(allocator: std.mem.Allocator, node: *const std.json.Value) ![]u8 {
    if (mdastStringField(node, "value")) |value| return try allocator.dupe(u8, value);
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);
    for (mdastChildren(node), 0..) |*child, index| {
        if (index != 0) try out.writeAll("\n");
        const child_type = try mdastNodeType(child);
        if (std.mem.eql(u8, child_type, "paragraph") or
            std.mem.eql(u8, child_type, "tableCell") or
            std.mem.eql(u8, child_type, "listItem"))
        {
            const text = try mdastInlineTextAlloc(allocator, child);
            defer allocator.free(text);
            try out.writeAll(text);
        } else if (std.mem.eql(u8, child_type, "code")) {
            const text = try mdastCodeBlockTextAlloc(allocator, child);
            defer allocator.free(text);
            try out.writeAll(text);
        } else {
            const text = try mdastFallbackTextAlloc(allocator, child);
            defer allocator.free(text);
            try out.writeAll(text);
        }
    }
    return out.buffer.toOwnedSlice(allocator);
}

fn gcMarkdownOrphanNodes(
    allocator: std.mem.Allocator,
    io: std.Io,
    store: storage.Store,
    parsed: ParsedMarkdownOrphanGcArgs,
) !MarkdownOrphanGcResult {
    const start_ns = monotonicNs(io);
    var graph_snapshot = try store.loadGraph();
    defer graph_snapshot.deinit();

    var incoming = std.AutoHashMap(u64, usize).init(allocator);
    defer incoming.deinit();
    for (graph_snapshot.edges.items) |edge| {
        if (edge.status != .active) continue;
        const entry = try incoming.getOrPut(edge.dst.toInt());
        if (!entry.found_existing) entry.value_ptr.* = 0;
        entry.value_ptr.* += 1;
    }

    var candidates = std.ArrayList(core.NodeId).empty;
    defer candidates.deinit(allocator);
    var result = MarkdownOrphanGcResult{};
    for (graph_snapshot.nodes.items) |node| {
        if (node.status != .active) continue;
        const gc_managed = markdownNodeIsGcManaged(allocator, store, node.id, node.text) catch false;
        if (!gc_managed) {
            result.skipped_unmanaged += 1;
            continue;
        }
        if ((incoming.get(node.id.toInt()) orelse 0) != 0) {
            result.skipped_referenced += 1;
            continue;
        }
        try candidates.append(allocator, node.id);
    }
    result.candidates = candidates.items.len;

    if (parsed.apply and candidates.items.len != 0) {
        for (candidates.items) |node_id| {
            _ = try store.deleteNode(node_id);
            result.deleted += 1;
        }
        try store.repairPersistentIndexesFromLog();
    }
    result.elapsed_ns = elapsedNs(io, start_ns);
    return result;
}

fn markdownNodeIsGcManaged(allocator: std.mem.Allocator, store: storage.Store, node_id: core.NodeId, text: []const u8) !bool {
    _ = text;
    const property_schema = try store.getNodeStringProperty(allocator, node_id, "schema_type");
    defer if (property_schema) |value| allocator.free(value);
    const property_external_key = try store.getNodeStringProperty(allocator, node_id, "external_key");
    defer if (property_external_key) |value| allocator.free(value);
    const schema_type = property_schema orelse return false;
    const external_key = property_external_key orelse return false;
    if (std.mem.eql(u8, schema_type, "content_text") or std.mem.eql(u8, schema_type, "content_image")) {
        return std.mem.startsWith(u8, external_key, "content:");
    }
    if (std.mem.eql(u8, schema_type, "document_section")) {
        return std.mem.startsWith(u8, external_key, "md-doc:") and std.mem.indexOf(u8, external_key, "#heading:") != null;
    }
    if (std.mem.eql(u8, schema_type, "markdown_table") or std.mem.eql(u8, schema_type, "markdown_table_row")) {
        return std.mem.startsWith(u8, external_key, "md-doc:") and std.mem.indexOf(u8, external_key, "#") != null;
    }
    return false;
}

fn agentWriteFactAndProjection(
    allocator: std.mem.Allocator,
    io: std.Io,
    store: storage.Store,
    parsed: ParsedAgentWriteArgs,
    src: core.NodeId,
    fact_rel: core.RelKind,
    dst: core.NodeId,
    render_rel: core.RelKind,
) !AgentWriteResult {
    const fact = try agentWriteUpsertFactEdge(allocator, store, src, fact_rel, dst);
    var projection_result = MarkdownDocumentImportResult{ .document_id = .none };
    const root = try agentWriteProjectionRoot(allocator, io, store, parsed, &projection_result);
    defer allocator.free(root.external_key);

    var context = MarkdownImportContext{
        .allocator = allocator,
        .io = io,
        .store = store,
        .document_external_key = root.external_key,
        .lookup_view = try store.openNodeTextLookupView(allocator),
        .session_node_ids = std.StringHashMap(core.NodeId).init(allocator),
        .session_node_external_keys = std.AutoHashMap(u64, []u8).init(allocator),
        .session_edge_counts = std.StringHashMap(usize).init(allocator),
        .desired_projection_owners = std.AutoHashMap(u64, void).init(allocator),
        .session_owner_order_counts = std.AutoHashMap(u64, usize).init(allocator),
        .pending_position_keys = std.StringHashMap(std.ArrayList(u64)).init(allocator),
    };
    defer context.deinit();

    try markdownRememberSessionNodeExternalKey(&context, root.external_key, root.id);
    try seedMarkdownOwnerOrderCount(&context, root.id);

    const node_kind: core.NodeKind = if (render_rel == md_rel_image) .image else .observation;
    const schema_type = if (render_rel == md_rel_image) "content_image" else "content_text";
    const content_id = try importMarkdownContentNode(&context, node_kind, parsed.text, schema_type, &projection_result);
    const projection_edge_created = try appendMarkdownProjectionEdge(&context, root.id, render_rel, content_id);
    try flushMarkdownImportPendingWrites(&context);
    if (context.edge_identity_index_dirty or projection_edge_created) try context.store.rebuildEdgeExternalKeyIndex();
    const projection_edge_id = (try lookupMarkdownProjectionEdgeByEndpoints(allocator, store, root.id, render_rel, content_id)) orelse return error.InvalidRecord;
    const content_node_properties = try applyAgentWriteNodeProperties(allocator, store, content_id, parsed.name, parsed.summary, parsed.retrieval_hints);
    const projection_links = try linkAgentWriteFactAndProjection(allocator, store, fact.edge_id, projection_edge_id);

    return .{
        .fact_edge_id = fact.edge_id,
        .fact_created = fact.created,
        .projection_root_id = root.id,
        .projection_content_id = content_id,
        .projection_edge_id = projection_edge_id,
        .projection_nodes_imported = projection_result.nodes_imported,
        .projection_edge_created = projection_edge_created,
        .content_node_properties = content_node_properties,
        .projection_links = projection_links,
        .agent_inbox_created = root.created,
    };
}

fn agentWriteJsonBatch(
    allocator: std.mem.Allocator,
    io: std.Io,
    store: storage.Store,
    parsed: ParsedAgentWriteJsonArgs,
    loaded_schema: schema.Registry,
    enforce_application_schema: bool,
) !AgentWriteJsonBatchResult {
    const stat = try std.Io.Dir.cwd().statFile(io, parsed.json_path, .{});
    if (stat.kind != .file or stat.size == 0 or stat.size > agent_write_json_max_bytes) return error.InvalidRecord;
    const bytes = try std.Io.Dir.cwd().readFileAlloc(io, parsed.json_path, allocator, .limited(agent_write_json_max_bytes));
    defer allocator.free(bytes);
    var batch = try std.json.parseFromSlice(AgentWriteBatchJson, allocator, bytes, .{
        .ignore_unknown_fields = true,
    });
    defer batch.deinit();

    if (batch.value.items.len == 0) return error.MissingArgument;
    var result = AgentWriteJsonBatchResult{};
    errdefer result.deinit(allocator);

    for (batch.value.items) |item| {
        try validateNodeTextGranularity(item.text);
        try validateNodeLlmMetadataGranularity(item.name, item.summary, item.retrieval_hints);
        const target_count: usize =
            @intFromBool(item.document != null) +
            @intFromBool(item.section != null) +
            @intFromBool(item.agent_inbox);
        if (target_count > 1) return error.MissingArgument;

        const src_text = try std.fmt.allocPrint(allocator, "{}", .{item.src});
        defer allocator.free(src_text);
        const dst_text = try std.fmt.allocPrint(allocator, "{}", .{item.dst});
        defer allocator.free(dst_text);
        const document_text = if (item.document) |id| try std.fmt.allocPrint(allocator, "{}", .{id}) else null;
        defer if (document_text) |text| allocator.free(text);
        const section_text = if (item.section) |id| try std.fmt.allocPrint(allocator, "{}", .{id}) else null;
        defer if (section_text) |text| allocator.free(text);

        const src = core.NodeId.fromInt(item.src);
        const dst = core.NodeId.fromInt(item.dst);
        const fact_rel = try parseRelKindWithSchemaPolicy(item.rel, loaded_schema, enforce_application_schema);
        const render_rel = try parseRelKindWithLoadedSchema(item.render_rel orelse "md:paragraph", null);
        if (!agentWriteRenderRelSupported(render_rel)) return error.InvalidRelKind;
        if (enforce_application_schema) try validateSchemaEdgeEndpoints(store, loaded_schema, src, fact_rel, dst);

        const write_args = ParsedAgentWriteArgs{
            .db_path = parsed.db_path,
            .src_node_id = src_text,
            .rel_label = item.rel,
            .dst_node_id = dst_text,
            .document_node_id = document_text,
            .section_node_id = section_text,
            .agent_inbox = item.agent_inbox or target_count == 0,
            .text = item.text,
            .name = item.name,
            .summary = item.summary,
            .retrieval_hints = item.retrieval_hints,
            .render_rel_label = item.render_rel orelse "md:paragraph",
            .schema_path = parsed.schema_path,
        };
        const item_result = try agentWriteFactAndProjection(allocator, io, store, write_args, src, fact_rel, dst, render_rel);
        result.items += 1;
        result.fact_created += @intFromBool(item_result.fact_created);
        result.projection_nodes_imported += item_result.projection_nodes_imported;
        result.projection_edge_created += @intFromBool(item_result.projection_edge_created);
        result.content_node_properties += item_result.content_node_properties;
        result.projection_links += item_result.projection_links;
        result.agent_inbox_created += @intFromBool(item_result.agent_inbox_created);
        if (item.fact_properties) |properties| {
            result.fact_properties += try applyAgentWriteEdgeProperties(allocator, store, item_result.fact_edge_id, properties);
        }
        if (item.projection_properties) |properties| {
            result.projection_properties += try applyAgentWriteEdgeProperties(allocator, store, item_result.projection_edge_id, properties);
        }
    }
    return result;
}

fn applyAgentWriteNodeProperties(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_id: core.NodeId,
    name: ?[]const u8,
    summary: ?[]const u8,
    retrieval_hints: ?[]const u8,
) !usize {
    try validateNodeLlmMetadataGranularity(name, summary, retrieval_hints);
    var count: usize = 0;
    const owner: storage.PropertyOwner = .{ .node = node_id };
    if (name) |value| {
        try store.setStringProperty(allocator, owner, "name", value);
        count += 1;
    }
    if (summary) |value| {
        try store.setStringProperty(allocator, owner, "summary", value);
        count += 1;
    }
    if (retrieval_hints) |value| {
        try store.setStringProperty(allocator, owner, "retrieval_hints", value);
        count += 1;
    }
    return count;
}

fn linkAgentWriteFactAndProjection(
    allocator: std.mem.Allocator,
    store: storage.Store,
    fact_edge_id: core.EdgeId,
    projection_edge_id: core.EdgeId,
) !usize {
    const projection_text = try std.fmt.allocPrint(allocator, "{}", .{projection_edge_id.toInt()});
    defer allocator.free(projection_text);
    const fact_text = try std.fmt.allocPrint(allocator, "{}", .{fact_edge_id.toInt()});
    defer allocator.free(fact_text);
    var count: usize = 0;
    count += try setAgentWriteEdgeProperty(allocator, store, fact_edge_id, "projection_edge_id", projection_text);
    count += try setAgentWriteEdgeProperty(allocator, store, projection_edge_id, "fact_edge_id", fact_text);
    return count;
}

fn applyAgentWriteEdgeProperties(
    allocator: std.mem.Allocator,
    store: storage.Store,
    edge_id: core.EdgeId,
    properties: AgentWriteEdgePropertiesJson,
) !usize {
    var count: usize = 0;
    if (properties.markdown_attr) |value| count += try setAgentWriteEdgeProperty(allocator, store, edge_id, "markdown_attr", value);
    if (properties.render_flags) |value| count += try setAgentWriteEdgeProperty(allocator, store, edge_id, "render_flags", value);
    if (properties.source_span) |value| count += try setAgentWriteEdgeProperty(allocator, store, edge_id, "source_span", value);
    if (properties.confidence) |value| count += try setAgentWriteEdgeProperty(allocator, store, edge_id, "confidence", value);
    if (properties.created_by) |value| count += try setAgentWriteEdgeProperty(allocator, store, edge_id, "created_by", value);
    if (properties.projection_edge_id) |value| count += try setAgentWriteEdgeProperty(allocator, store, edge_id, "projection_edge_id", value);
    if (properties.fact_edge_id) |value| count += try setAgentWriteEdgeProperty(allocator, store, edge_id, "fact_edge_id", value);
    return count;
}

fn setAgentWriteEdgeProperty(
    allocator: std.mem.Allocator,
    store: storage.Store,
    edge_id: core.EdgeId,
    key: []const u8,
    value: []const u8,
) !usize {
    const owner: storage.PropertyOwner = .{ .edge = edge_id };
    try validateParsedStringProperty(owner, key, value);
    try store.setStringProperty(allocator, owner, key, value);
    return 1;
}

fn lookupMarkdownProjectionEdgeByEndpoints(
    allocator: std.mem.Allocator,
    store: storage.Store,
    src: core.NodeId,
    rel: core.RelKind,
    dst: core.NodeId,
) !?core.EdgeId {
    var records = try readVisibleEdgeRecordsByNode(allocator, store, .src, src, rel);
    defer records.deinit(allocator);
    for (records.items) |record| {
        if (record.rel == @intFromEnum(rel) and record.dst == dst.toInt()) return .fromInt(record.edge_id);
    }
    return null;
}

fn agentWriteUpsertFactEdge(
    allocator: std.mem.Allocator,
    store: storage.Store,
    src: core.NodeId,
    rel: core.RelKind,
    dst: core.NodeId,
) !AgentWriteFactResult {
    if (try store.lookupFactEdgeByNodeExternalKeys(allocator, src, rel, dst)) |existing_id| {
        return .{ .edge_id = existing_id, .created = false };
    }
    const id = try dag.addEdgeCheckedWithPersistentStore(allocator, store, src, rel, dst, .{});
    store.refreshFactEdgeExternalKeyIndexAfterAppend(.{ .id = id, .src = src, .rel = rel, .dst = dst }) catch {};
    return .{ .edge_id = id, .created = true };
}

const AgentWriteProjectionRoot = struct {
    id: core.NodeId,
    external_key: []const u8,
    created: bool = false,
};

fn agentWriteProjectionRoot(
    allocator: std.mem.Allocator,
    io: std.Io,
    store: storage.Store,
    parsed: ParsedAgentWriteArgs,
    import_result: *MarkdownDocumentImportResult,
) !AgentWriteProjectionRoot {
    if (parsed.agent_inbox) {
        const external_key = try std.fmt.allocPrint(allocator, "md-doc:agent-inbox:{s}", .{parsed.db_path});
        errdefer allocator.free(external_key);
        const text = "Agent Inbox";
        const node_text = try markdownIdentityNodeText(allocator, .{
            .text = text,
            .schema_type = "document",
            .external_key = external_key,
        });
        defer allocator.free(node_text);
        var context = MarkdownImportContext{
            .allocator = allocator,
            .io = io,
            .store = store,
            .document_external_key = external_key,
            .lookup_view = try store.openNodeTextLookupView(allocator),
            .session_node_ids = std.StringHashMap(core.NodeId).init(allocator),
            .session_node_external_keys = std.AutoHashMap(u64, []u8).init(allocator),
            .session_edge_counts = std.StringHashMap(usize).init(allocator),
            .desired_projection_owners = std.AutoHashMap(u64, void).init(allocator),
            .session_owner_order_counts = std.AutoHashMap(u64, usize).init(allocator),
            .pending_position_keys = std.StringHashMap(std.ArrayList(u64)).init(allocator),
        };
        defer context.deinit();
        const before = import_result.nodes_imported;
        const id = try markdownUpsertNode(&context, .document, node_text, external_key, "document", null, import_result);
        try flushMarkdownImportPendingWrites(&context);
        return .{ .id = id, .external_key = external_key, .created = import_result.nodes_imported > before };
    }

    const root_id = if (parsed.document_node_id) |id_text|
        try parseNodeIdArg(id_text)
    else if (parsed.section_node_id) |id_text|
        try parseNodeIdArg(id_text)
    else
        return error.MissingArgument;

    var node = (try store.readNodeById(allocator, root_id)) orelse return core.Error.NotFound;
    defer node.deinit(allocator);
    if (parsed.document_node_id != null and node.kind != .document) return core.Error.InvalidId;
    if (parsed.section_node_id != null and node.kind != .document_section and node.kind != .document) return core.Error.InvalidId;
    const external_key = (try markdownNodeExternalKeyForStoreAlloc(allocator, store, root_id, node.text)) orelse return error.InvalidRecord;
    return .{ .id = root_id, .external_key = external_key };
}

fn markdownNodeExternalKeyForStoreAlloc(allocator: std.mem.Allocator, store: storage.Store, node_id: core.NodeId, text: []const u8) !?[]const u8 {
    _ = text;
    const property_value = try store.getNodeStringProperty(allocator, node_id, "external_key");
    if (property_value) |value| return value;
    return null;
}

fn seedMarkdownOwnerOrderCount(context: *MarkdownImportContext, owner_id: core.NodeId) !void {
    var records = try markdownProjectionChildren(context.allocator, context.store, owner_id, null);
    defer records.deinit(context.allocator);
    if (records.items.len == 0) return;
    const entry = try context.session_owner_order_counts.getOrPut(owner_id.toInt());
    if (!entry.found_existing or entry.value_ptr.* < records.items.len) entry.value_ptr.* = records.items.len;
}

fn agentWriteRenderRelSupported(rel: core.RelKind) bool {
    return mdHeadingLevelFromRel(rel) != null or
        rel == md_rel_paragraph or
        rel == md_rel_image or
        rel == md_rel_code_block or
        isMarkdownRawTextProjectionRel(rel);
}

const MarkdownDocEditBenchGateResult = struct {
    edit_ns_per_paragraph: u128,
    edit_to_initial_bps: u128,
    changed_records_passed: bool,
    elapsed_passed: bool,
    per_paragraph_passed: bool,
    ratio_passed: bool,

    fn passed(self: MarkdownDocEditBenchGateResult) bool {
        return self.changed_records_passed and self.elapsed_passed and self.per_paragraph_passed and self.ratio_passed;
    }
};

const MarkdownDocEditMixedAgentBenchResult = struct {
    writes_requested: usize = 0,
    fact_created: usize = 0,
    projection_nodes_imported: usize = 0,
    projection_edge_created: usize = 0,
    agent_inbox_created: usize = 0,
    elapsed_ns: u128 = 0,
    render_local_subtree_elapsed_ns: u128 = 0,
    render_local_subtree_bytes: usize = 0,
    render_local_subtree_passed: bool = true,

    fn passed(self: MarkdownDocEditMixedAgentBenchResult) bool {
        return self.render_local_subtree_passed;
    }
};

const MarkdownDocEditRepeatedBenchResult = struct {
    edits_requested: usize = 0,
    insert_edits: usize = 0,
    delete_edits: usize = 0,
    nodes_imported: usize = 0,
    edges_imported: usize = 0,
    projection_edges_deleted: usize = 0,
    changed_records_total: usize = 0,
    changed_records_max: usize = 0,
    elapsed_ns: u128 = 0,
    elapsed_passed: bool = true,

    fn passed(self: MarkdownDocEditRepeatedBenchResult) bool {
        return self.elapsed_passed;
    }
};

const MarkdownDocEditRepeatedUpdateBenchResult = struct {
    edits_requested: usize = 0,
    update_edits: usize = 0,
    nodes_imported: usize = 0,
    edges_imported: usize = 0,
    projection_edges_deleted: usize = 0,
    changed_records_total: usize = 0,
    changed_records_max: usize = 0,
    elapsed_ns: u128 = 0,
    elapsed_passed: bool = true,

    fn passed(self: MarkdownDocEditRepeatedUpdateBenchResult) bool {
        return self.elapsed_passed;
    }
};

fn evaluateMarkdownDocEditBenchGates(
    parsed: ParsedMarkdownDocEditBenchArgs,
    initial_elapsed_ns: u128,
    edit_elapsed_ns: u128,
    edit_changed_records: usize,
) MarkdownDocEditBenchGateResult {
    const edit_ns_per_paragraph = ceilDivU128(edit_elapsed_ns, parsed.paragraphs);
    const edit_to_initial_bps = ratioBpsU128(edit_elapsed_ns, initial_elapsed_ns);
    return .{
        .edit_ns_per_paragraph = edit_ns_per_paragraph,
        .edit_to_initial_bps = edit_to_initial_bps,
        .changed_records_passed = if (parsed.max_edit_changed_records) |max_records| edit_changed_records <= max_records else true,
        .elapsed_passed = if (parsed.max_edit_elapsed_ns) |max_ns| edit_elapsed_ns <= max_ns else true,
        .per_paragraph_passed = if (parsed.max_edit_ns_per_paragraph) |max_ns| edit_ns_per_paragraph <= max_ns else true,
        .ratio_passed = if (parsed.max_edit_to_initial_bps) |max_bps| edit_to_initial_bps <= max_bps else true,
    };
}

fn ceilDivU128(numerator: u128, denominator: u128) u128 {
    if (denominator == 0) return std.math.maxInt(u128);
    return numerator / denominator + @intFromBool(numerator % denominator != 0);
}

fn ratioBpsU128(numerator: u128, denominator: u128) u128 {
    if (denominator == 0) return if (numerator == 0) 0 else std.math.maxInt(u128);
    const scaled = std.math.mul(u128, numerator, 10_000) catch return std.math.maxInt(u128);
    return ceilDivU128(scaled, denominator);
}

fn renderMarkdownDocEditBenchOutput(
    allocator: std.mem.Allocator,
    io: std.Io,
    parsed: ParsedMarkdownDocEditBenchArgs,
) ![]u8 {
    if (try anyPathExists(io, parsed.db_path)) return error.AlreadyExists;
    const markdown_path = try std.fmt.allocPrint(allocator, "{s}.mdbench.md", .{parsed.db_path});
    defer allocator.free(markdown_path);
    if (try anyPathExists(io, markdown_path)) return error.AlreadyExists;
    defer std.Io.Dir.cwd().deleteFile(io, markdown_path) catch {};

    const initial_markdown = try markdownDocEditBenchContent(allocator, parsed.paragraphs, parsed.edit_index, false);
    defer allocator.free(initial_markdown);
    try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = markdown_path, .data = initial_markdown, .flags = .{ .truncate = true } });

    var store = try storage.Store.init(allocator, io, parsed.db_path);
    defer store.deinit();
    try store.createEmpty();
    const store_bytes_after_create = try storeDirBytes(allocator, io, parsed.db_path);

    const initial_start_ns = monotonicNs(io);
    const initial_result = try importMarkdownDocument(allocator, io, store, markdown_path);
    const initial_elapsed_ns = elapsedNs(io, initial_start_ns);
    const store_bytes_after_initial = try storeDirBytes(allocator, io, parsed.db_path);

    const edited_markdown = try markdownDocEditBenchContent(allocator, parsed.paragraphs, parsed.edit_index, true);
    defer allocator.free(edited_markdown);
    try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = markdown_path, .data = edited_markdown, .flags = .{ .truncate = true } });

    const edit_start_ns = monotonicNs(io);
    const edit_result = try importMarkdownDocument(allocator, io, store, markdown_path);
    const edit_elapsed_ns = elapsedNs(io, edit_start_ns);
    const store_bytes_after_edit = try storeDirBytes(allocator, io, parsed.db_path);
    const edit_changed_records = edit_result.nodes_imported + edit_result.edges_imported + edit_result.projection_edges_deleted;
    const gate = evaluateMarkdownDocEditBenchGates(parsed, initial_elapsed_ns, edit_elapsed_ns, edit_changed_records);

    const rendered = try renderMarkdownDocument(allocator, store, initial_result.document_id);
    defer allocator.free(rendered);
    const expected_edit = try std.fmt.allocPrint(allocator, "Paragraph {d}: edited replacement", .{parsed.edit_index});
    defer allocator.free(expected_edit);
    if (std.mem.indexOf(u8, rendered, expected_edit) == null) return error.InvalidRecord;

    const local_render_root_id = try markdownDocEditBenchSectionId(allocator, store, markdown_path, markdown_doc_edit_bench_body_heading_index);
    const repeated_update_result = try runMarkdownDocEditRepeatedUpdateBench(allocator, io, store, parsed, markdown_path);
    const repeated_result = try runMarkdownDocEditRepeatedBench(allocator, io, store, parsed, markdown_path);
    const mixed_result = try runMarkdownDocEditMixedAgentBench(allocator, io, store, parsed, local_render_root_id);

    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);
    try out.print(
        "bench_workload=markdown-doc-edit paragraphs={} edit_index={}\n",
        .{ parsed.paragraphs, parsed.edit_index },
    );
    try out.print(
        "initial_document={} initial_nodes_imported={} initial_edges_imported={} initial_projection_edges_deleted={} initial_markdown_bytes={} initial_elapsed_ns={}\n",
        .{ initial_result.document_id.toInt(), initial_result.nodes_imported, initial_result.edges_imported, initial_result.projection_edges_deleted, initial_result.markdown_bytes, initial_elapsed_ns },
    );
    try out.print(
        "edit_document={} edit_nodes_imported={} edit_edges_imported={} edit_projection_edges_deleted={} edit_changed_records={} edit_markdown_bytes={} edit_elapsed_ns={} rendered_bytes={}\n",
        .{ edit_result.document_id.toInt(), edit_result.nodes_imported, edit_result.edges_imported, edit_result.projection_edges_deleted, edit_changed_records, edit_result.markdown_bytes, edit_elapsed_ns, rendered.len },
    );
    try out.print(
        "edit_latency_gate edit_ns_per_paragraph={} edit_to_initial_bps={} max_edit_changed_records_enabled={} max_edit_changed_records={} max_edit_elapsed_ns_enabled={} max_edit_elapsed_ns={} max_edit_ns_per_paragraph_enabled={} max_edit_ns_per_paragraph={} max_edit_to_initial_bps_enabled={} max_edit_to_initial_bps={} changed_records_passed={} elapsed_passed={} per_paragraph_passed={} ratio_passed={} passed={}\n",
        .{
            gate.edit_ns_per_paragraph,
            gate.edit_to_initial_bps,
            @intFromBool(parsed.max_edit_changed_records != null),
            parsed.max_edit_changed_records orelse 0,
            @intFromBool(parsed.max_edit_elapsed_ns != null),
            parsed.max_edit_elapsed_ns orelse 0,
            @intFromBool(parsed.max_edit_ns_per_paragraph != null),
            parsed.max_edit_ns_per_paragraph orelse 0,
            @intFromBool(parsed.max_edit_to_initial_bps != null),
            parsed.max_edit_to_initial_bps orelse 0,
            @intFromBool(gate.changed_records_passed),
            @intFromBool(gate.elapsed_passed),
            @intFromBool(gate.per_paragraph_passed),
            @intFromBool(gate.ratio_passed),
            @intFromBool(gate.passed()),
        },
    );
    try out.print(
        "store_bytes_after_create={} store_bytes_after_initial={} store_bytes_after_edit={} initial_store_bytes_delta={} edit_store_bytes_delta={}\n",
        .{
            store_bytes_after_create,
            store_bytes_after_initial,
            store_bytes_after_edit,
            store_bytes_after_initial -| store_bytes_after_create,
            store_bytes_after_edit -| store_bytes_after_initial,
        },
    );
    try out.print(
        "repeat_update_edit_gate enabled={} repeat_update_edits={} repeat_update_nodes_imported={} repeat_update_edges_imported={} repeat_update_projection_edges_deleted={} repeat_update_changed_records_total={} repeat_update_changed_records_max={} repeat_update_elapsed_ns={} max_repeat_update_edit_elapsed_ns_enabled={} max_repeat_update_edit_elapsed_ns={} elapsed_passed={} passed={}\n",
        .{
            @intFromBool(parsed.repeat_update_edits != 0 or parsed.max_repeat_update_edit_elapsed_ns != null),
            repeated_update_result.edits_requested,
            repeated_update_result.nodes_imported,
            repeated_update_result.edges_imported,
            repeated_update_result.projection_edges_deleted,
            repeated_update_result.changed_records_total,
            repeated_update_result.changed_records_max,
            repeated_update_result.elapsed_ns,
            @intFromBool(parsed.max_repeat_update_edit_elapsed_ns != null),
            parsed.max_repeat_update_edit_elapsed_ns orelse 0,
            @intFromBool(repeated_update_result.elapsed_passed),
            @intFromBool(repeated_update_result.passed()),
        },
    );
    try out.print(
        "repeat_local_edit_gate enabled={} repeat_local_edits={} repeat_insert_edits={} repeat_delete_edits={} repeat_nodes_imported={} repeat_edges_imported={} repeat_projection_edges_deleted={} repeat_changed_records_total={} repeat_changed_records_max={} repeat_elapsed_ns={} max_repeat_edit_elapsed_ns_enabled={} max_repeat_edit_elapsed_ns={} elapsed_passed={} passed={}\n",
        .{
            @intFromBool(parsed.repeat_local_edits != 0 or parsed.max_repeat_edit_elapsed_ns != null),
            repeated_result.edits_requested,
            repeated_result.insert_edits,
            repeated_result.delete_edits,
            repeated_result.nodes_imported,
            repeated_result.edges_imported,
            repeated_result.projection_edges_deleted,
            repeated_result.changed_records_total,
            repeated_result.changed_records_max,
            repeated_result.elapsed_ns,
            @intFromBool(parsed.max_repeat_edit_elapsed_ns != null),
            parsed.max_repeat_edit_elapsed_ns orelse 0,
            @intFromBool(repeated_result.elapsed_passed),
            @intFromBool(repeated_result.passed()),
        },
    );
    try out.print(
        "agent_mixed_gate enabled={} agent_mixed_writes={} agent_mixed_fact_created={} agent_mixed_projection_nodes_imported={} agent_mixed_projection_edge_created={} agent_mixed_agent_inbox_created={} agent_mixed_elapsed_ns={} render_local_subtree_root={} render_local_subtree_elapsed_ns={} render_local_subtree_bytes={} max_render_local_subtree_elapsed_ns_enabled={} max_render_local_subtree_elapsed_ns={} render_local_subtree_passed={} passed={}\n",
        .{
            @intFromBool(parsed.agent_mixed_writes != 0 or parsed.max_render_local_subtree_elapsed_ns != null),
            mixed_result.writes_requested,
            mixed_result.fact_created,
            mixed_result.projection_nodes_imported,
            mixed_result.projection_edge_created,
            mixed_result.agent_inbox_created,
            mixed_result.elapsed_ns,
            local_render_root_id.toInt(),
            mixed_result.render_local_subtree_elapsed_ns,
            mixed_result.render_local_subtree_bytes,
            @intFromBool(parsed.max_render_local_subtree_elapsed_ns != null),
            parsed.max_render_local_subtree_elapsed_ns orelse 0,
            @intFromBool(mixed_result.render_local_subtree_passed),
            @intFromBool(mixed_result.passed()),
        },
    );
    if (!gate.passed() or !repeated_update_result.passed() or !repeated_result.passed() or !mixed_result.passed()) return core.Error.BudgetExceeded;
    return out.buffer.toOwnedSlice(allocator);
}

fn runMarkdownDocEditRepeatedUpdateBench(
    allocator: std.mem.Allocator,
    io: std.Io,
    store: storage.Store,
    parsed: ParsedMarkdownDocEditBenchArgs,
    markdown_path: []const u8,
) !MarkdownDocEditRepeatedUpdateBenchResult {
    var result = MarkdownDocEditRepeatedUpdateBenchResult{
        .edits_requested = parsed.repeat_update_edits,
    };
    if (parsed.repeat_update_edits == 0) {
        result.elapsed_passed = if (parsed.max_repeat_update_edit_elapsed_ns) |max_ns| result.elapsed_ns <= max_ns else true;
        return result;
    }

    const start_ns = monotonicNs(io);
    var iteration: usize = 0;
    while (iteration < parsed.repeat_update_edits) : (iteration += 1) {
        const content = try markdownDocEditBenchContentVariant(allocator, parsed.paragraphs, parsed.edit_index, .update, iteration);
        defer allocator.free(content);
        try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = markdown_path, .data = content, .flags = .{ .truncate = true } });
        const edit_result = try importMarkdownDocument(allocator, io, store, markdown_path);
        const changed_records = edit_result.nodes_imported + edit_result.edges_imported + edit_result.projection_edges_deleted;
        result.nodes_imported += edit_result.nodes_imported;
        result.edges_imported += edit_result.edges_imported;
        result.projection_edges_deleted += edit_result.projection_edges_deleted;
        result.changed_records_total += changed_records;
        if (result.changed_records_max < changed_records) result.changed_records_max = changed_records;
        result.update_edits += 1;
    }
    result.elapsed_ns = elapsedNs(io, start_ns);
    result.elapsed_passed = if (parsed.max_repeat_update_edit_elapsed_ns) |max_ns| result.elapsed_ns <= max_ns else true;
    return result;
}

fn runMarkdownDocEditRepeatedBench(
    allocator: std.mem.Allocator,
    io: std.Io,
    store: storage.Store,
    parsed: ParsedMarkdownDocEditBenchArgs,
    markdown_path: []const u8,
) !MarkdownDocEditRepeatedBenchResult {
    var result = MarkdownDocEditRepeatedBenchResult{
        .edits_requested = parsed.repeat_local_edits,
    };
    if (parsed.repeat_local_edits == 0) {
        result.elapsed_passed = if (parsed.max_repeat_edit_elapsed_ns) |max_ns| result.elapsed_ns <= max_ns else true;
        return result;
    }

    const start_ns = monotonicNs(io);
    var iteration: usize = 0;
    while (iteration < parsed.repeat_local_edits) : (iteration += 1) {
        const mode: MarkdownDocEditBenchContentMode = if (iteration % 2 == 0) .insert else .delete;
        const content = try markdownDocEditBenchContentVariant(allocator, parsed.paragraphs, parsed.edit_index, mode, iteration);
        defer allocator.free(content);
        try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = markdown_path, .data = content, .flags = .{ .truncate = true } });
        const edit_result = try importMarkdownDocument(allocator, io, store, markdown_path);
        const changed_records = edit_result.nodes_imported + edit_result.edges_imported + edit_result.projection_edges_deleted;
        result.nodes_imported += edit_result.nodes_imported;
        result.edges_imported += edit_result.edges_imported;
        result.projection_edges_deleted += edit_result.projection_edges_deleted;
        result.changed_records_total += changed_records;
        if (result.changed_records_max < changed_records) result.changed_records_max = changed_records;
        switch (mode) {
            .insert => result.insert_edits += 1,
            .delete => result.delete_edits += 1,
            else => unreachable,
        }
    }
    result.elapsed_ns = elapsedNs(io, start_ns);
    result.elapsed_passed = if (parsed.max_repeat_edit_elapsed_ns) |max_ns| result.elapsed_ns <= max_ns else true;
    return result;
}

fn runMarkdownDocEditMixedAgentBench(
    allocator: std.mem.Allocator,
    io: std.Io,
    store: storage.Store,
    parsed: ParsedMarkdownDocEditBenchArgs,
    local_render_root_id: core.NodeId,
) !MarkdownDocEditMixedAgentBenchResult {
    var result = MarkdownDocEditMixedAgentBenchResult{
        .writes_requested = parsed.agent_mixed_writes,
    };
    if (parsed.agent_mixed_writes == 0) {
        const render_start_ns = monotonicNs(io);
        const rendered = try renderMarkdownDocument(allocator, store, local_render_root_id);
        defer allocator.free(rendered);
        result.render_local_subtree_elapsed_ns = elapsedNs(io, render_start_ns);
        result.render_local_subtree_bytes = rendered.len;
        result.render_local_subtree_passed = if (parsed.max_render_local_subtree_elapsed_ns) |max_ns| result.render_local_subtree_elapsed_ns <= max_ns else true;
        return result;
    }

    const src_id = try addMarkdownDocEditBenchNode(allocator, store, .concept, "Benchmark mixed source", "bench_claim", "mixed-src");
    const dst_ids = try allocator.alloc(core.NodeId, parsed.agent_mixed_writes);
    defer allocator.free(dst_ids);
    for (dst_ids, 0..) |*dst_id, i| {
        const label = try std.fmt.allocPrint(allocator, "Benchmark mixed evidence {d}", .{i});
        defer allocator.free(label);
        const suffix = try std.fmt.allocPrint(allocator, "mixed-dst-{d}", .{i});
        defer allocator.free(suffix);
        dst_id.* = try addMarkdownDocEditBenchNode(allocator, store, .evidence, label, "bench_evidence", suffix);
    }

    const src_text = try std.fmt.allocPrint(allocator, "{}", .{src_id.toInt()});
    defer allocator.free(src_text);
    const section_text = try std.fmt.allocPrint(allocator, "{}", .{local_render_root_id.toInt()});
    defer allocator.free(section_text);

    const mixed_start_ns = monotonicNs(io);
    for (dst_ids, 0..) |dst_id, i| {
        const dst_text = try std.fmt.allocPrint(allocator, "{}", .{dst_id.toInt()});
        defer allocator.free(dst_text);
        const text = try std.fmt.allocPrint(allocator, "Agent mixed write {d}: benchmark visible projection attachment.", .{i});
        defer allocator.free(text);
        const write_args = ParsedAgentWriteArgs{
            .db_path = parsed.db_path,
            .src_node_id = src_text,
            .rel_label = "references",
            .dst_node_id = dst_text,
            .section_node_id = section_text,
            .text = text,
            .render_rel_label = "md:paragraph",
        };
        const write_result = try agentWriteFactAndProjection(allocator, io, store, write_args, src_id, .references, dst_id, md_rel_paragraph);
        result.fact_created += @intFromBool(write_result.fact_created);
        result.projection_nodes_imported += write_result.projection_nodes_imported;
        result.projection_edge_created += @intFromBool(write_result.projection_edge_created);
        result.agent_inbox_created += @intFromBool(write_result.agent_inbox_created);
    }
    result.elapsed_ns = elapsedNs(io, mixed_start_ns);

    const render_start_ns = monotonicNs(io);
    const rendered = try renderMarkdownDocument(allocator, store, local_render_root_id);
    defer allocator.free(rendered);
    result.render_local_subtree_elapsed_ns = elapsedNs(io, render_start_ns);
    result.render_local_subtree_bytes = rendered.len;
    result.render_local_subtree_passed = if (parsed.max_render_local_subtree_elapsed_ns) |max_ns| result.render_local_subtree_elapsed_ns <= max_ns else true;
    return result;
}

fn addMarkdownDocEditBenchNode(
    allocator: std.mem.Allocator,
    store: storage.Store,
    kind: core.NodeKind,
    label: []const u8,
    schema_type: []const u8,
    external_suffix: []const u8,
) !core.NodeId {
    const external_key = try std.fmt.allocPrint(allocator, "bench-md-doc-edit:{s}", .{external_suffix});
    defer allocator.free(external_key);
    const node_text = try markdownIdentityNodeText(allocator, .{
        .text = label,
        .schema_type = schema_type,
        .external_key = external_key,
    });
    defer allocator.free(node_text);
    return try store.addNode(kind, node_text);
}

const markdown_doc_edit_bench_body_heading_index: usize = 1;

const MarkdownDocEditBenchContentMode = enum {
    initial,
    edited,
    update,
    insert,
    delete,
};

fn markdownDocEditBenchContent(allocator: std.mem.Allocator, paragraphs: usize, edit_index: usize, edited: bool) ![]u8 {
    return markdownDocEditBenchContentVariant(allocator, paragraphs, edit_index, if (edited) .edited else .initial, 0);
}

fn markdownDocEditBenchContentVariant(
    allocator: std.mem.Allocator,
    paragraphs: usize,
    edit_index: usize,
    mode: MarkdownDocEditBenchContentMode,
    iteration: usize,
) ![]u8 {
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);
    try out.writeAll("# Markdown Doc Edit Bench\n\n");
    try out.writeAll("## Local Edit Section\n\n");
    for (0..paragraphs) |i| {
        if (i == edit_index and mode == .delete) continue;
        if (i == edit_index and mode == .update) {
            try out.print("Paragraph {d}: update-only replacement iteration {d} for markdown doc edit benchmark local update.\n\n", .{ i, iteration });
        } else if (i == edit_index and (mode == .edited or mode == .insert)) {
            try out.print("Paragraph {d}: edited replacement for markdown doc edit benchmark local update.\n\n", .{i});
        } else {
            try out.print("Paragraph {d}: stable markdown doc edit benchmark content token_{d} remains unchanged across imports.\n\n", .{ i, i });
        }
        if (i == edit_index and mode == .insert) {
            try out.print("Repeated insert {d}: local inserted markdown doc edit benchmark paragraph.\n\n", .{iteration});
        }
    }
    return out.buffer.toOwnedSlice(allocator);
}

fn markdownDocEditBenchSectionId(
    allocator: std.mem.Allocator,
    store: storage.Store,
    markdown_path: []const u8,
    heading_index: usize,
) !core.NodeId {
    const heading_text = switch (heading_index) {
        0 => "Markdown Doc Edit Bench",
        1 => "Local Edit Section",
        else => return core.Error.NotFound,
    };
    const heading_hash = try markdownContentHashAlloc(allocator, heading_text);
    defer allocator.free(heading_hash);
    const external_key = try std.fmt.allocPrint(allocator, "md-doc:{s}#heading:{d}:{s}", .{ markdown_path, heading_index, heading_hash });
    defer allocator.free(external_key);
    var hits = try store.lookupNodeIdsByStringProperty(allocator, "external_key", external_key, .document_section, 1);
    defer hits.deinit(allocator);
    if (hits.items.len != 0) return hits.items[0];
    return (try store.lookupNodeByExternalKey(allocator, external_key, .document_section)) orelse core.Error.NotFound;
}

fn importMarkdownFlushParagraph(
    context: *MarkdownImportContext,
    document_id: core.NodeId,
    paragraph: *std.ArrayList(u8),
    result: *MarkdownDocumentImportResult,
) !void {
    const text = std.mem.trim(u8, paragraph.items, " \t\r\n");
    if (text.len != 0) {
        try importMarkdownProjectionBlock(context, document_id, .{ .rel = md_rel_paragraph, .text = text }, result);
    }
    paragraph.clearRetainingCapacity();
}

fn importMarkdownProjectionLines(
    context: *MarkdownImportContext,
    document_id: core.NodeId,
    rel: core.RelKind,
    lines: []const []const u8,
    result: *MarkdownDocumentImportResult,
) !void {
    var block = std.ArrayList(u8).empty;
    defer block.deinit(context.allocator);
    for (lines, 0..) |line, line_index| {
        if (line_index != 0) try block.append(context.allocator, '\n');
        try block.appendSlice(context.allocator, line);
    }
    try importMarkdownProjectionBlock(context, document_id, .{ .rel = rel, .text = block.items }, result);
}

fn importMarkdownProjectionBlock(
    context: *MarkdownImportContext,
    document_id: core.NodeId,
    block: MarkdownProjectionBlock,
    result: *MarkdownDocumentImportResult,
) !void {
    if (block.rel != md_rel_image and markdownTextExceedsChunkLimit(block.text)) {
        return importMarkdownChunkedProjectionBlock(context, document_id, block, result);
    }
    const node_kind: core.NodeKind = if (block.rel == md_rel_image) .image else .observation;
    const schema_type = if (block.rel == md_rel_image) "content_image" else "content_text";
    const content_id = try importMarkdownContentNode(context, node_kind, block.text, schema_type, result);
    if (try appendMarkdownProjectionEdge(context, document_id, block.rel, content_id)) result.edges_imported += 1;
}

fn importMarkdownChunkedProjectionBlock(
    context: *MarkdownImportContext,
    document_id: core.NodeId,
    block: MarkdownProjectionBlock,
    result: *MarkdownDocumentImportResult,
) !void {
    var chunks = try markdownHeuristicTextChunks(context.allocator, block.text, markdown_ast_text_chunk_chars);
    defer chunks.deinit(context.allocator);
    if (chunks.items.len <= 1) {
        const content_id = try importMarkdownContentNode(context, .observation, block.text, "content_text", result);
        if (try appendMarkdownProjectionEdge(context, document_id, block.rel, content_id)) result.edges_imported += 1;
        return;
    }
    const content_hash = try markdownContentHashAlloc(context.allocator, block.text);
    defer context.allocator.free(content_hash);
    const chunked_index = context.session_chunked_block_count;
    context.session_chunked_block_count += 1;
    const occurrence_external_key = try std.fmt.allocPrint(context.allocator, "{s}#chunked:{d}:{d}:{s}", .{ context.document_external_key, chunked_index, @intFromEnum(block.rel), content_hash });
    defer context.allocator.free(occurrence_external_key);
    const occurrence_text = try std.fmt.allocPrint(context.allocator, "markdown_chunked_block rel={s} chunks={}", .{ schema.markdownProjectionRelationNameById(@intFromEnum(block.rel)) orelse "md:unknown", chunks.items.len });
    defer context.allocator.free(occurrence_text);
    const occurrence_id = try importMarkdownOccurrenceNode(context, occurrence_text, "markdown_chunked_block", occurrence_external_key, result);
    if (try appendMarkdownProjectionEdge(context, document_id, block.rel, occurrence_id)) result.edges_imported += 1;
    for (chunks.items) |chunk| {
        const chunk_id = try importMarkdownContentNode(context, .observation, chunk, "content_text", result);
        if (try appendMarkdownProjectionEdge(context, occurrence_id, md_rel_text_chunk, chunk_id)) result.edges_imported += 1;
        result.text_chunks += 1;
    }
}

fn markdownTextExceedsChunkLimit(text: []const u8) bool {
    const chars = std.unicode.utf8CountCodepoints(text) catch return true;
    return chars > markdown_ast_text_chunk_chars;
}

fn markdownHeuristicTextChunks(allocator: std.mem.Allocator, text: []const u8, max_chars: usize) !std.ArrayList([]const u8) {
    var chunks = std.ArrayList([]const u8).empty;
    errdefer chunks.deinit(allocator);
    var start: usize = 0;
    while (start < text.len) {
        const remaining_chars = std.unicode.utf8CountCodepoints(text[start..]) catch return error.InvalidRecord;
        if (remaining_chars <= max_chars) {
            try chunks.append(allocator, text[start..]);
            break;
        }
        const hard_end = markdownUtf8PrefixEndByChars(text, start, max_chars);
        const end = markdownBestChunkBoundary(text, start, hard_end);
        try chunks.append(allocator, text[start..end]);
        start = end;
    }
    return chunks;
}

fn markdownUtf8PrefixEndByChars(text: []const u8, start: usize, max_chars: usize) usize {
    var index = start;
    var chars: usize = 0;
    while (index < text.len and chars < max_chars) : (chars += 1) {
        const len = std.unicode.utf8ByteSequenceLength(text[index]) catch 1;
        if (index + len > text.len) break;
        index += len;
    }
    return if (index > start) index else @min(text.len, start + 1);
}

fn markdownBestChunkBoundary(text: []const u8, start: usize, hard_end: usize) usize {
    const min_end = start + (hard_end - start) / 2;
    if (markdownLastPatternBoundary(text, start, hard_end, min_end, "\n\n")) |end| return end;
    if (markdownLastStrongPunctuationBoundary(text, start, hard_end, min_end)) |end| return end;
    if (markdownLastWeakPunctuationBoundary(text, start, hard_end, min_end)) |end| return end;
    if (markdownLastWhitespaceBoundary(text, start, hard_end, min_end)) |end| return end;
    return hard_end;
}

fn markdownLastPatternBoundary(text: []const u8, start: usize, hard_end: usize, min_end: usize, pattern: []const u8) ?usize {
    if (pattern.len == 0 or hard_end <= start + pattern.len) return null;
    var index = hard_end - pattern.len;
    while (index >= start) : (index -= 1) {
        const end = index + pattern.len;
        if (end >= min_end and std.mem.eql(u8, text[index..end], pattern)) return end;
        if (index == start) break;
    }
    return null;
}

fn markdownLastStrongPunctuationBoundary(text: []const u8, start: usize, hard_end: usize, min_end: usize) ?usize {
    var index = hard_end;
    while (index > start) {
        index -= 1;
        if (index + 3 <= text.len and markdownChineseStrongPunctuation(text[index..@min(text.len, index + 3)])) {
            const end = index + 3;
            if (end >= min_end and end <= hard_end) return end;
        }
        if (text[index] == '.' or text[index] == '!' or text[index] == '?' or text[index] == ';' or text[index] == ':') {
            const end = index + 1;
            if (end >= min_end) return end;
        }
    }
    return null;
}

fn markdownLastWeakPunctuationBoundary(text: []const u8, start: usize, hard_end: usize, min_end: usize) ?usize {
    var index = hard_end;
    while (index > start) {
        index -= 1;
        if (index + 3 <= text.len and markdownChineseWeakPunctuation(text[index..@min(text.len, index + 3)])) {
            const end = index + 3;
            if (end >= min_end and end <= hard_end) return end;
        }
        if (text[index] == ',' or text[index] == ')') {
            const end = index + 1;
            if (end >= min_end) return end;
        }
    }
    return null;
}

fn markdownChineseStrongPunctuation(bytes: []const u8) bool {
    return std.mem.startsWith(u8, bytes, "。") or
        std.mem.startsWith(u8, bytes, "！") or
        std.mem.startsWith(u8, bytes, "？") or
        std.mem.startsWith(u8, bytes, "；");
}

fn markdownChineseWeakPunctuation(bytes: []const u8) bool {
    return std.mem.startsWith(u8, bytes, "，") or
        std.mem.startsWith(u8, bytes, "、") or
        std.mem.startsWith(u8, bytes, "）");
}

fn markdownLastWhitespaceBoundary(text: []const u8, start: usize, hard_end: usize, min_end: usize) ?usize {
    var index = hard_end;
    while (index > start) {
        index -= 1;
        if (std.ascii.isWhitespace(text[index])) {
            const end = index + 1;
            if (end >= min_end) return end;
        }
    }
    return null;
}

fn importMarkdownHeadingSection(
    context: *MarkdownImportContext,
    document_id: core.NodeId,
    heading_index: usize,
    heading: MarkdownHeading,
    result: *MarkdownDocumentImportResult,
) !MarkdownHeadingSection {
    const heading_hash = try markdownContentHashAlloc(context.allocator, heading.text);
    defer context.allocator.free(heading_hash);
    const external_key = try std.fmt.allocPrint(context.allocator, "{s}#heading:{d}:{s}", .{ context.document_external_key, heading_index, heading_hash });
    defer context.allocator.free(external_key);
    const safe_heading = try markdownNodeLabelWithinLimitAlloc(context.allocator, heading.text, "heading");
    defer context.allocator.free(safe_heading);
    const section_id = try importMarkdownOccurrenceNode(context, safe_heading, "document_section", external_key, result);
    return .{
        .id = section_id,
        .edge_created = try appendMarkdownProjectionEdge(context, document_id, mdHeadingRel(heading.level), section_id),
    };
}

fn importMarkdownContentNode(
    context: *MarkdownImportContext,
    kind: core.NodeKind,
    text: []const u8,
    schema_type: []const u8,
    result: *MarkdownDocumentImportResult,
) !core.NodeId {
    const content_hash = try markdownContentHashAlloc(context.allocator, text);
    defer context.allocator.free(content_hash);
    const external_key = try std.fmt.allocPrint(context.allocator, "content:{s}:{s}", .{ schema_type, content_hash });
    defer context.allocator.free(external_key);
    const node_text = try markdownIdentityNodeText(context.allocator, .{
        .text = text,
        .schema_type = schema_type,
        .external_key = external_key,
        .content_hash = content_hash,
    });
    defer context.allocator.free(node_text);
    return try markdownUpsertNode(context, kind, node_text, external_key, schema_type, content_hash, result);
}

fn importMarkdownOccurrenceNode(
    context: *MarkdownImportContext,
    text: []const u8,
    schema_type: []const u8,
    external_key: []const u8,
    result: *MarkdownDocumentImportResult,
) !core.NodeId {
    const node_text = try markdownIdentityNodeText(context.allocator, .{
        .text = text,
        .schema_type = schema_type,
        .external_key = external_key,
    });
    defer context.allocator.free(node_text);
    return try markdownUpsertNode(context, .document_section, node_text, external_key, schema_type, null, result);
}

const MarkdownIdentityNodeTextArgs = struct {
    text: []const u8,
    schema_type: []const u8,
    external_key: []const u8,
    content_hash: ?[]const u8 = null,
};

fn markdownIdentityNodeText(
    allocator: std.mem.Allocator,
    args: MarkdownIdentityNodeTextArgs,
) ![]const u8 {
    try validateGovernanceMetadataToken(args.schema_type);
    try validateNodeTextGranularity(args.text);
    _ = args.external_key;
    _ = args.content_hash;
    return try allocator.dupe(u8, args.text);
}

fn markdownUpsertNode(
    context: *MarkdownImportContext,
    kind: core.NodeKind,
    node_text: []const u8,
    external_key: []const u8,
    schema_type: []const u8,
    content_hash: ?[]const u8,
    result: *MarkdownDocumentImportResult,
) !core.NodeId {
    if (context.session_node_ids.get(external_key)) |id| return id;
    if (try markdownLookupExistingNode(context, external_key, kind)) |id| {
        try markdownRememberSessionNode(context, external_key, id);
        return id;
    }
    if (try context.lookup_view.lookupFirstId(kind, node_text)) |id| {
        try markdownRememberSessionNode(context, external_key, id);
        return id;
    }
    const id = try markdownNextPendingNodeId(context);
    {
        const owned_name = try context.allocator.dupe(u8, node_text);
        errdefer context.allocator.free(owned_name);
        try context.pending_nodes.append(context.allocator, .{
            .id = id,
            .kind = kind,
            .text = owned_name,
        });
    }
    {
        var properties = try markdownPendingNodePropertiesAlloc(
            context.allocator,
            id,
            schema_type,
            external_key,
            content_hash,
        );
        errdefer properties.deinit(context.allocator);
        try context.pending_node_properties.append(context.allocator, properties);
    }
    result.nodes_imported += 1;
    try markdownRememberSessionNode(context, external_key, id);
    return id;
}

fn markdownLookupExistingNode(context: *MarkdownImportContext, external_key: []const u8, kind: core.NodeKind) !?core.NodeId {
    var property_hits = try context.store.lookupNodeIdsByStringProperty(context.allocator, "external_key", external_key, kind, 1);
    defer property_hits.deinit(context.allocator);
    if (property_hits.items.len != 0) return property_hits.items[0];
    if (context.use_cached_node_lookup) {
        if (context.node_lookup_cache == null) {
            context.node_lookup_cache = try context.store.buildNodeExternalKeyLookupCache(context.allocator);
        }
        return try context.store.lookupNodeByExternalKeyCached(context.allocator, external_key, kind, &context.node_lookup_cache.?);
    }
    return try context.store.lookupNodeByExternalKey(context.allocator, external_key, kind);
}

fn markdownNextPendingNodeId(context: *MarkdownImportContext) !core.NodeId {
    if (context.next_pending_node_id) |id| {
        if (id.toInt() == std.math.maxInt(u64)) return error.InvalidRecord;
        const next = core.NodeId.fromInt(id.toInt() + 1);
        context.next_pending_node_id = next;
        return next;
    }
    const id = try context.store.nextNodeId();
    context.next_pending_node_id = id;
    return id;
}

fn flushMarkdownImportPendingWrites(context: *MarkdownImportContext) !void {
    try flushMarkdownImportPendingNodes(context);
    try flushMarkdownImportPendingEdges(context);
}

fn flushMarkdownImportPendingNodes(context: *MarkdownImportContext) !void {
    if (context.pending_nodes.items.len == 0) return;
    try context.store.appendNodesBatch(context.pending_nodes.items);
    for (context.pending_node_properties.items) |properties| {
        const owner: storage.PropertyOwner = .{ .node = properties.node_id };
        try context.store.setStringProperty(context.allocator, owner, "schema_type", properties.schema_type);
        try context.store.setStringProperty(context.allocator, owner, "external_key", properties.external_key);
        if (properties.content_hash) |content_hash| try context.store.setStringProperty(context.allocator, owner, "content_hash", content_hash);
    }
    for (context.pending_nodes.items) |node| context.allocator.free(node.text);
    for (context.pending_node_properties.items) |*properties| properties.deinit(context.allocator);
    context.pending_nodes.clearRetainingCapacity();
    context.pending_node_properties.clearRetainingCapacity();
}

fn flushMarkdownImportPendingEdges(context: *MarkdownImportContext) !void {
    if (context.pending_edges.items.len == 0) return;
    var edges = try context.allocator.alloc(graph.Edge, context.pending_edges.items.len);
    defer context.allocator.free(edges);
    var order_keys = try context.allocator.alloc(u64, context.pending_edges.items.len);
    defer context.allocator.free(order_keys);

    const first_edge_id = try context.store.nextEdgeId();
    for (context.pending_edges.items, 0..) |edge, index| {
        const edge_id = std.math.add(u64, first_edge_id.toInt(), index) catch return error.InvalidRecord;
        edges[index] = .{
            .id = core.EdgeId.fromInt(edge_id),
            .src = edge.src,
            .rel = edge.rel,
            .dst = edge.dst,
        };
        order_keys[index] = edge.order_key;
    }
    try context.store.appendEdgesOrderedBatch(edges, order_keys);
    context.pending_edges.clearRetainingCapacity();
}

fn markdownRememberSessionNode(context: *MarkdownImportContext, external_key: []const u8, id: core.NodeId) !void {
    {
        const owned_key = try context.allocator.dupe(u8, external_key);
        errdefer context.allocator.free(owned_key);
        try context.session_node_ids.put(owned_key, id);
    }
    try markdownRememberSessionNodeExternalKey(context, external_key, id);
}

fn markdownRememberSessionNodeExternalKey(context: *MarkdownImportContext, external_key: []const u8, id: core.NodeId) !void {
    if (context.session_node_external_keys.contains(id.toInt())) return;
    const owned_key = try context.allocator.dupe(u8, external_key);
    errdefer context.allocator.free(owned_key);
    const entry = try context.session_node_external_keys.getOrPut(id.toInt());
    if (entry.found_existing) {
        context.allocator.free(owned_key);
        return;
    }
    entry.value_ptr.* = owned_key;
}

fn markdownContentHashAlloc(allocator: std.mem.Allocator, text: []const u8) ![]const u8 {
    return try std.fmt.allocPrint(allocator, "wyhash64:{x:0>16}", .{std.hash.Wyhash.hash(0, text)});
}

fn markdownNodeLabelWithinLimitAlloc(allocator: std.mem.Allocator, text: []const u8, label: []const u8) ![]u8 {
    return markdownNodeLabelWithinMaxCharsAlloc(allocator, text, label, node_text_char_limit);
}

fn markdownNodeLabelWithinMaxCharsAlloc(allocator: std.mem.Allocator, text: []const u8, label: []const u8, max_chars: usize) ![]u8 {
    const chars = std.unicode.utf8CountCodepoints(text) catch return error.InvalidRecord;
    if (chars <= max_chars) return try allocator.dupe(u8, text);
    const hash = try markdownContentHashAlloc(allocator, text);
    defer allocator.free(hash);
    const suffix = try std.fmt.allocPrint(allocator, " ... [truncated {s} {s}]", .{ label, hash });
    defer allocator.free(suffix);
    const suffix_chars = std.unicode.utf8CountCodepoints(suffix) catch return error.InvalidRecord;
    if (suffix_chars >= max_chars) return error.NodeTextTooLarge;
    const prefix_chars = max_chars - suffix_chars;
    const prefix_end = markdownUtf8PrefixEndByChars(text, 0, prefix_chars);
    return try std.fmt.allocPrint(allocator, "{s}{s}", .{ text[0..prefix_end], suffix });
}

fn importMarkdownTable(
    context: *MarkdownImportContext,
    document_id: core.NodeId,
    table_index: usize,
    rows: []const []const u8,
    result: *MarkdownDocumentImportResult,
) !void {
    const table_external_key = try std.fmt.allocPrint(context.allocator, "{s}#table:{d}", .{ context.document_external_key, table_index });
    defer context.allocator.free(table_external_key);
    const table_id = try importMarkdownOccurrenceNode(context, "markdown_table", "markdown_table", table_external_key, result);
    if (try appendMarkdownProjectionEdge(context, document_id, md_rel_table, table_id)) result.edges_imported += 1;
    for (rows, 0..) |row_line, row_index| {
        const row_external_key = try std.fmt.allocPrint(context.allocator, "{s}#row:{d}", .{ table_external_key, row_index });
        defer context.allocator.free(row_external_key);
        const row_id = try importMarkdownOccurrenceNode(context, "markdown_table_row", "markdown_table_row", row_external_key, result);
        if (try appendMarkdownProjectionEdge(context, table_id, md_rel_table_row, row_id)) result.edges_imported += 1;
        var cells = std.mem.splitScalar(u8, row_line, '|');
        while (cells.next()) |cell_raw| {
            const cell = std.mem.trim(u8, cell_raw, " \t");
            if (cell.len == 0) continue;
            const cell_id = try importMarkdownContentNode(context, .observation, cell, "content_text", result);
            if (try appendMarkdownProjectionEdge(context, row_id, md_rel_table_cell, cell_id)) result.edges_imported += 1;
        }
    }
}

fn appendMarkdownProjectionEdge(context: *MarkdownImportContext, src: core.NodeId, rel: core.RelKind, dst: core.NodeId) !bool {
    try context.desired_projection_owners.put(src.toInt(), {});
    const edge_key = try markdownProjectionEdgeKey(context.allocator, src, rel, dst);
    defer context.allocator.free(edge_key);
    const used_count = context.session_edge_counts.get(edge_key) orelse 0;
    const order_key = try markdownNextOwnerOrderKey(context, src);
    // 位置键入队(所有路径:新建/identity 复用/计数复用统一)——assign 阶段按活边消费。
    // **借用 key 永远不进 map**(Linus:getOrPut 借用 key 后 dupe OOM → map 持有将被 defer
    // free 的指针 → deinit double-free):先 get,miss 才 dupe 后 put。
    if (context.pending_position_keys.getPtr(edge_key)) |queue| {
        try queue.append(context.allocator, order_key);
    } else {
        {
            const key_owned = try context.allocator.dupe(u8, edge_key);
            errdefer context.allocator.free(key_owned);
            var queue: std.ArrayList(u64) = .empty;
            errdefer queue.deinit(context.allocator);
            try queue.append(context.allocator, order_key);
            try context.pending_position_keys.put(key_owned, queue);
        }
    }

    try markdownRememberSessionEdgeUse(context, edge_key, used_count + 1);
    var identity_edge: ?storage.EdgeIndexRecord = null;
    if (context.reuse_existing_projection_edges and !context.edge_identity_index_dirty) {
        if (context.session_node_external_keys.get(src.toInt())) |src_external_key| {
            const external_key = try storage.orderedEdgeExternalKeyAlloc(context.allocator, src_external_key, rel, order_key);
            defer context.allocator.free(external_key);
            if (context.edge_lookup_cache == null) {
                context.edge_lookup_cache = try context.store.buildEdgeExternalKeyLookupCache(context.allocator);
            }
            if (try context.store.lookupEdgeRecordByExternalKeyCached(context.allocator, external_key, &context.edge_lookup_cache.?)) |record| identity_edge = record;
        }
    }

    if (identity_edge) |record| {
        if (record.rel == @intFromEnum(rel) and record.dst == dst.toInt()) return false;
    }

    var existing_count: usize = 0;
    var identity_slot_conflict = false;
    // Markdown projection identity is defined only by persisted graph edges;
    // the metaknow deferred `based_on` sidecar is a query projection and must
    // not consume this bounded deduplication scan.
    var records = try context.store.readVisibleEdgeIndexRecordsByNodeForOrderedTraversal(context.allocator, src);
    defer records.deinit(context.allocator);
    for (records.items) |record| {
        if (identity_edge) |edge| {
            if (record.edge_id == edge.edge_id) {
                if (record.rel == @intFromEnum(rel) and record.dst == dst.toInt()) return false;
                identity_slot_conflict = true;
            }
        }
        if (record.rel == @intFromEnum(rel) and record.dst == dst.toInt()) existing_count += 1;
    }
    for (context.pending_edges.items) |edge| {
        if (edge.src == src and edge.rel == rel and edge.dst == dst) existing_count += 1;
    }

    if (!identity_slot_conflict and existing_count > used_count) return false;

    try context.pending_edges.append(context.allocator, .{
        .src = src,
        .rel = rel,
        .dst = dst,
        .order_key = order_key,
    });
    context.edge_identity_index_dirty = true;
    return true;
}

fn reconcileMarkdownProjectionEdges(context: *MarkdownImportContext, document_id: core.NodeId) !usize {
    var visited_owners = std.AutoHashMap(u64, void).init(context.allocator);
    defer visited_owners.deinit();
    var stack = std.ArrayList(core.NodeId).empty;
    defer stack.deinit(context.allocator);
    var seen_edge_counts = std.StringHashMap(usize).init(context.allocator);
    defer {
        var iterator = seen_edge_counts.iterator();
        while (iterator.next()) |entry| context.allocator.free(entry.key_ptr.*);
        seen_edge_counts.deinit();
    }
    var edge_ids_to_delete = std.ArrayList(core.EdgeId).empty;
    defer edge_ids_to_delete.deinit(context.allocator);
    var edge_order_map = try context.store.readEdgeOrderMap(context.allocator);
    defer edge_order_map.deinit();

    try stack.append(context.allocator, document_id);
    while (stack.pop()) |owner_id| {
        const visited = try visited_owners.getOrPut(owner_id.toInt());
        if (visited.found_existing) continue;

        var records = try markdownProjectionChildrenWithOrderMap(context.allocator, context.store, owner_id, null, &edge_order_map);
        defer records.deinit(context.allocator);
        for (records.items) |record| {
            const rel: core.RelKind = @enumFromInt(record.rel);
            const dst = core.NodeId.fromInt(record.dst);

            const edge_key = try markdownProjectionEdgeKey(context.allocator, owner_id, rel, dst);
            defer context.allocator.free(edge_key);
            const seen_count = seen_edge_counts.get(edge_key) orelse 0;
            const desired_count = context.session_edge_counts.get(edge_key) orelse 0;
            if (seen_count >= desired_count) {
                try edge_ids_to_delete.append(context.allocator, core.EdgeId.fromInt(record.edge_id));
                try stack.append(context.allocator, dst);
                continue;
            }
            try markdownRememberEdgeUse(context.allocator, &seen_edge_counts, edge_key, seen_count + 1);
            if (markdownProjectionRelAlwaysHasChildren(rel) or context.desired_projection_owners.contains(dst.toInt())) {
                try stack.append(context.allocator, dst);
            }
        }
    }

    try context.store.deleteEdgesBatch(edge_ids_to_delete.items);
    return edge_ids_to_delete.items.len;
}

/// order_key 撞车修复的分配阶段:reconcile 之后,用与其**同一 ordered 读**遍历文档活投影边,
/// 逐边 pop 该 (src,rel,dst) 的文档序位置键队列,与现 order 记录 diff 才 upsert。
/// 只写活边(死边不碰);新建/identity 边 pop 到自己的键 = no-op。
fn assignProjectionOrderKeys(context: *MarkdownImportContext, document_id: core.NodeId) !void {
    if (context.pending_position_keys.count() == 0) return;
    var edge_order_map = try context.store.readEdgeOrderMap(context.allocator);
    defer edge_order_map.deinit();
    var visited_owners = std.AutoHashMap(u64, void).init(context.allocator);
    defer visited_owners.deinit();
    var stack = std.ArrayList(core.NodeId).empty;
    defer stack.deinit(context.allocator);
    var rewrites = std.ArrayList(storage.EdgeOrderRecord).empty;
    defer rewrites.deinit(context.allocator);

    try stack.append(context.allocator, document_id);
    while (stack.pop()) |owner_id| {
        const visited = try visited_owners.getOrPut(owner_id.toInt());
        if (visited.found_existing) continue;
        var records = try markdownProjectionChildrenWithOrderMap(context.allocator, context.store, owner_id, null, &edge_order_map);
        defer records.deinit(context.allocator);
        for (records.items) |record| {
            const rel: core.RelKind = @enumFromInt(record.rel);
            const dst = core.NodeId.fromInt(record.dst);
            const edge_key = try markdownProjectionEdgeKey(context.allocator, owner_id, rel, dst);
            defer context.allocator.free(edge_key);
            if (context.pending_position_keys.getPtr(edge_key)) |queue| {
                if (queue.items.len > 0) {
                    const want = queue.orderedRemove(0);
                    const have = edge_order_map.get(record.edge_id);
                    if (have == null or have.? != want) {
                        try rewrites.append(context.allocator, .{
                            .src = owner_id.toInt(),
                            .rel = record.rel,
                            .edge_id = record.edge_id,
                            .order_key = want,
                        });
                    }
                }
            }
            if (markdownProjectionRelAlwaysHasChildren(rel) or context.desired_projection_owners.contains(dst.toInt())) {
                try stack.append(context.allocator, dst);
            }
        }
    }
    try context.store.upsertEdgeOrderRecordsBatch(context.allocator, rewrites.items);
}

fn markdownProjectionEdgeKey(allocator: std.mem.Allocator, src: core.NodeId, rel: core.RelKind, dst: core.NodeId) ![]u8 {
    return std.fmt.allocPrint(allocator, "{}\x1f{}\x1f{}", .{ src.toInt(), @intFromEnum(rel), dst.toInt() });
}

fn markdownNextOwnerOrderKey(context: *MarkdownImportContext, src: core.NodeId) !u64 {
    const entry = try context.session_owner_order_counts.getOrPut(src.toInt());
    if (!entry.found_existing) entry.value_ptr.* = 0;
    entry.value_ptr.* += 1;
    return @as(u64, @intCast(entry.value_ptr.*)) * 1024;
}

fn markdownRememberSessionEdgeUse(context: *MarkdownImportContext, edge_key: []const u8, count: usize) !void {
    return markdownRememberEdgeUse(context.allocator, &context.session_edge_counts, edge_key, count);
}

fn markdownRememberEdgeUse(allocator: std.mem.Allocator, counts: *std.StringHashMap(usize), edge_key: []const u8, count: usize) !void {
    if (counts.getEntry(edge_key)) |entry| {
        entry.value_ptr.* = count;
        return;
    }
    const owned_key = try allocator.dupe(u8, edge_key);
    errdefer allocator.free(owned_key);
    try counts.put(owned_key, count);
}

fn appendMarkdownProjectionEdgeRaw(store: storage.Store, src: core.NodeId, rel: core.RelKind, dst: core.NodeId) !void {
    try store.appendEdgeIndexed(.{
        .id = try store.nextEdgeId(),
        .src = src,
        .rel = rel,
        .dst = dst,
    });
}

fn renderMarkdownDocument(allocator: std.mem.Allocator, store: storage.Store, document_id: core.NodeId) ![]u8 {
    var document = (try store.readNodeById(allocator, document_id)) orelse return core.Error.NotFound;
    defer document.deinit(allocator);
    if (document.kind != .document and document.kind != .document_section) return core.Error.InvalidId;
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);
    try renderMarkdownSubtree(allocator, store, document_id, document.kind, &out);
    return out.buffer.toOwnedSlice(allocator);
}

const MarkdownSectionStats = struct {
    section_count: usize = 0,
    context_size: TextContextSize = .{ .text_bytes = 0, .text_chars = 0, .text_lines = 0 },
};

fn markdownPreviewPrefixLen(text: []const u8, max_lines: usize) struct { len: usize, lines: usize, truncated: bool } {
    if (max_lines == 0) return .{ .len = 0, .lines = 0, .truncated = text.len != 0 };
    if (text.len == 0) return .{ .len = 0, .lines = 0, .truncated = false };
    var lines: usize = 1;
    for (text, 0..) |byte, index| {
        if (byte == '\n') {
            if (lines >= max_lines) {
                return .{ .len = index + 1, .lines = lines, .truncated = index + 1 < text.len };
            }
            lines += 1;
        }
    }
    return .{ .len = text.len, .lines = lines, .truncated = false };
}

fn addTextContextSize(total: *TextContextSize, size: TextContextSize) !void {
    total.text_bytes = std.math.add(usize, total.text_bytes, size.text_bytes) catch return error.RecordTooLarge;
    total.text_chars = std.math.add(usize, total.text_chars, size.text_chars) catch return error.RecordTooLarge;
    total.text_lines = std.math.add(usize, total.text_lines, size.text_lines) catch return error.RecordTooLarge;
}

fn markdownSubtreeSectionStats(
    allocator: std.mem.Allocator,
    store: storage.Store,
    root_id: core.NodeId,
) !MarkdownSectionStats {
    var stats = MarkdownSectionStats{};
    var visited = std.AutoHashMap(u64, void).init(allocator);
    defer visited.deinit();
    try collectMarkdownSubtreeSectionStats(allocator, store, root_id, &visited, &stats);
    return stats;
}

fn collectMarkdownSubtreeSectionStats(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_id: core.NodeId,
    visited: *std.AutoHashMap(u64, void),
    stats: *MarkdownSectionStats,
) !void {
    if (visited.contains(node_id.toInt())) return;
    try visited.put(node_id.toInt(), {});

    var node = (try store.readNodeById(allocator, node_id)) orelse return core.Error.NotFound;
    defer node.deinit(allocator);
    if (node.kind == .document_section) {
        stats.section_count = std.math.add(usize, stats.section_count, 1) catch return error.RecordTooLarge;
        try addTextContextSize(&stats.context_size, try computeTextContextSize(node.text));
    }

    var records = try markdownProjectionChildren(allocator, store, node_id, null);
    defer records.deinit(allocator);
    for (records.items) |record| {
        try collectMarkdownSubtreeSectionStats(allocator, store, core.NodeId.fromInt(record.dst), visited, stats);
    }
}

fn renderMarkdownDocumentJsonOutput(
    allocator: std.mem.Allocator,
    store: storage.Store,
    args: ParsedRenderMarkdownDocumentArgs,
    rendered: []const u8,
) ![]u8 {
    var document = (try store.readNodeById(allocator, args.document_id)) orelse return core.Error.NotFound;
    defer document.deinit(allocator);
    if (document.kind != .document and document.kind != .document_section) return core.Error.InvalidId;
    var render_root = (try store.readNodeById(allocator, args.render_root_id)) orelse return core.Error.NotFound;
    defer render_root.deinit(allocator);
    if (render_root.kind != .document and render_root.kind != .document_section) return core.Error.InvalidId;

    const rendered_size = try computeTextContextSize(rendered);
    const preview = markdownPreviewPrefixLen(rendered, args.preview_lines);
    const section_stats = try markdownSubtreeSectionStats(allocator, store, args.render_root_id);

    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);
    try writeJsonObjectStart(&out);
    var first = true;
    try writeJsonStringField(&out, "schema_version", "tinykg-agent-retrieval-v1", &first);
    try writeJsonStringField(&out, "mode", "render-md-doc", &first);

    try writeJsonFieldPrefix(&out, "query", &first);
    try out.writeAll("{");
    var query_first = true;
    try writeJsonNumberField(&out, "document_id", args.document_id.toInt(), &query_first);
    try writeJsonNumberField(&out, "render_root_id", args.render_root_id.toInt(), &query_first);
    try writeJsonNumberField(&out, "preview_lines", args.preview_lines, &query_first);
    try out.writeAll("}");

    try writeJsonFieldPrefix(&out, "document", &first);
    try renderNodeObjectJson(&out, allocator, store, document, false);
    try writeJsonFieldPrefix(&out, "render_root", &first);
    try renderNodeObjectJson(&out, allocator, store, render_root, false);

    try writeJsonFieldPrefix(&out, "rendered_markdown", &first);
    try out.writeAll("{");
    var rendered_first = true;
    try writeJsonFieldPrefix(&out, "context_size", &rendered_first);
    try renderTextContextSizeJson(&out, rendered_size);
    try writeJsonNumberField(&out, "preview_lines", preview.lines, &rendered_first);
    try writeJsonBoolField(&out, "truncated", preview.truncated, &rendered_first);
    try writeJsonNullableStringField(&out, "truncate_reason", if (preview.truncated) "preview_lines" else null, &rendered_first);
    try writeJsonStringField(&out, "preview", rendered[0..preview.len], &rendered_first);
    try out.writeAll("}");

    try writeJsonFieldPrefix(&out, "sections", &first);
    try out.writeAll("{");
    var sections_first = true;
    try writeJsonNumberField(&out, "section_count", section_stats.section_count, &sections_first);
    try writeJsonFieldPrefix(&out, "context_size", &sections_first);
    try renderTextContextSizeJson(&out, section_stats.context_size);
    try out.writeAll("}");

    try writeJsonFieldPrefix(&out, "continuations", &first);
    try out.writeAll("[");
    try writeSearchContinuation(&out, "inspect_metadata", args.render_root_id, "inspect rendered markdown root metadata");
    try out.writeAll(",");
    try writeSearchContinuation(&out, "neighbors", args.render_root_id, "walk markdown projection graph around the rendered root");
    try out.writeAll("]");

    try writeJsonObjectEnd(&out);
    return out.buffer.toOwnedSlice(allocator);
}

const MarkdownRenderPage = struct {
    cursor: usize,
    markdown: []u8,
    context_size: TextContextSize,
    units_emitted: usize,
    next_cursor: ?usize,
    has_more: bool,

    fn deinit(self: MarkdownRenderPage, allocator: std.mem.Allocator) void {
        allocator.free(self.markdown);
    }
};

const MarkdownPageRenderState = struct {
    cursor: usize,
    page_size_bytes: usize,
    unit_index: usize = 0,
    units_emitted: usize = 0,
    stopped: bool = false,
    next_cursor: ?usize = null,
    out: *QueryOutputWriter,
};

fn renderMarkdownDocumentPageJsonOutput(
    allocator: std.mem.Allocator,
    store: storage.Store,
    args: ParsedRenderMarkdownDocumentArgs,
) ![]u8 {
    var document = (try store.readNodeById(allocator, args.document_id)) orelse return core.Error.NotFound;
    defer document.deinit(allocator);
    if (document.kind != .document and document.kind != .document_section) return core.Error.InvalidId;
    var render_root = (try store.readNodeById(allocator, args.render_root_id)) orelse return core.Error.NotFound;
    defer render_root.deinit(allocator);
    if (render_root.kind != .document and render_root.kind != .document_section) return core.Error.InvalidId;

    const page_size_bytes = args.page_size_bytes orelse return error.InvalidLimit;
    const page = try renderMarkdownDocumentPage(allocator, store, args.render_root_id, render_root.kind, args.cursor, page_size_bytes);
    defer page.deinit(allocator);

    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);
    try writeJsonObjectStart(&out);
    var first = true;
    try writeJsonStringField(&out, "schema_version", "tinykg-agent-retrieval-v1", &first);
    try writeJsonStringField(&out, "mode", "render-md-doc", &first);

    try writeJsonFieldPrefix(&out, "query", &first);
    try out.writeAll("{");
    var query_first = true;
    try writeJsonNumberField(&out, "document_id", args.document_id.toInt(), &query_first);
    try writeJsonNumberField(&out, "render_root_id", args.render_root_id.toInt(), &query_first);
    try writeJsonNumberField(&out, "page_size_bytes", page_size_bytes, &query_first);
    try writeJsonNumberField(&out, "cursor", args.cursor, &query_first);
    try out.writeAll("}");

    try writeJsonFieldPrefix(&out, "document", &first);
    try renderNodeObjectJson(&out, allocator, store, document, false);
    try writeJsonFieldPrefix(&out, "render_root", &first);
    try renderNodeObjectJson(&out, allocator, store, render_root, false);

    try writeJsonFieldPrefix(&out, "rendered_markdown", &first);
    try out.writeAll("{");
    var rendered_first = true;
    try writeJsonFieldPrefix(&out, "context_size", &rendered_first);
    try renderTextContextSizeJson(&out, page.context_size);
    try writeJsonNumberField(&out, "cursor", page.cursor, &rendered_first);
    try writeJsonNullableUsizeField(&out, "next_cursor", page.next_cursor, &rendered_first);
    try writeJsonBoolField(&out, "has_more", page.has_more, &rendered_first);
    try writeJsonBoolField(&out, "truncated", page.has_more, &rendered_first);
    try writeJsonNullableStringField(&out, "truncate_reason", if (page.has_more) "page_size_bytes" else null, &rendered_first);
    try writeJsonNumberField(&out, "page_size_bytes", page_size_bytes, &rendered_first);
    try writeJsonNumberField(&out, "units_emitted", page.units_emitted, &rendered_first);
    try writeJsonStringField(&out, "page", page.markdown, &rendered_first);
    try writeJsonStringField(&out, "preview", page.markdown, &rendered_first);
    try out.writeAll("}");

    try writeJsonFieldPrefix(&out, "continuations", &first);
    try out.writeAll("[");
    if (page.next_cursor) |next_cursor| {
        try out.writeAll("{");
        var cont_first = true;
        try writeJsonStringField(&out, "action", "render-md-doc", &cont_first);
        try writeJsonNumberField(&out, "node_id", args.render_root_id.toInt(), &cont_first);
        try writeJsonNumberField(&out, "cursor", next_cursor, &cont_first);
        try writeJsonStringField(&out, "reason", "fetch next markdown page", &cont_first);
        try out.writeAll("}");
    }
    try out.writeAll("]");

    try writeJsonObjectEnd(&out);
    return out.buffer.toOwnedSlice(allocator);
}

fn renderMarkdownDocumentPage(
    allocator: std.mem.Allocator,
    store: storage.Store,
    root_id: core.NodeId,
    root_kind: core.NodeKind,
    cursor: usize,
    page_size_bytes: usize,
) !MarkdownRenderPage {
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);
    var state = MarkdownPageRenderState{
        .cursor = cursor,
        .page_size_bytes = page_size_bytes,
        .out = &out,
    };
    try renderMarkdownSubtreePaged(allocator, store, root_id, root_kind, &state);
    const markdown = try out.buffer.toOwnedSlice(allocator);
    const context_size = try computeTextContextSize(markdown);
    return .{
        .cursor = cursor,
        .markdown = markdown,
        .context_size = context_size,
        .units_emitted = state.units_emitted,
        .next_cursor = state.next_cursor,
        .has_more = state.stopped,
    };
}

fn emitMarkdownPageUnit(state: *MarkdownPageRenderState, text: []const u8) !void {
    if (state.stopped) return;
    if (state.unit_index < state.cursor) {
        state.unit_index += 1;
        return;
    }
    const current_len = state.out.buffer.items.len;
    if (current_len != 0 and current_len + text.len > state.page_size_bytes) {
        state.stopped = true;
        state.next_cursor = state.unit_index;
        return;
    }
    try state.out.writeAll(text);
    state.units_emitted += 1;
    state.unit_index += 1;
}

fn emitMarkdownHeadingPageUnit(allocator: std.mem.Allocator, state: *MarkdownPageRenderState, level: usize, text: []const u8) !void {
    var temp = QueryOutputWriter{ .allocator = allocator };
    defer temp.buffer.deinit(allocator);
    var i: usize = 0;
    while (i < level) : (i += 1) try temp.writeAll("#");
    try temp.writeAll(" ");
    try temp.writeAll(text);
    try temp.writeAll("\n\n");
    try emitMarkdownPageUnit(state, temp.buffer.items);
}

fn emitMarkdownTextBlockPageUnit(allocator: std.mem.Allocator, state: *MarkdownPageRenderState, text: []const u8) !void {
    var temp = QueryOutputWriter{ .allocator = allocator };
    defer temp.buffer.deinit(allocator);
    try temp.writeAll(text);
    if (text.len == 0 or text[text.len - 1] != '\n') try temp.writeAll("\n");
    try temp.writeAll("\n");
    try emitMarkdownPageUnit(state, temp.buffer.items);
}

fn renderMarkdownSubtreePaged(allocator: std.mem.Allocator, store: storage.Store, root_id: core.NodeId, root_kind: core.NodeKind, state: *MarkdownPageRenderState) !void {
    if (state.stopped) return;
    if (root_kind == .document_section) {
        if (try markdownProjectionHasChild(allocator, store, root_id, md_rel_text_chunk)) {
            return renderMarkdownChunkedTextBlockPaged(allocator, store, root_id, state);
        }
        if (try markdownProjectionHasChild(allocator, store, root_id, md_rel_table_row)) {
            return renderMarkdownTablePaged(allocator, store, root_id, state);
        }
        if (try markdownProjectionHasChild(allocator, store, root_id, md_rel_table_cell)) {
            try renderMarkdownTableRowPaged(allocator, store, root_id, state);
            if (!state.stopped) try emitMarkdownPageUnit(state, "\n");
            return;
        }
        if (try markdownIncomingHeadingRel(allocator, store, root_id)) |rel| {
            var node = (try store.readNodeById(allocator, root_id)) orelse return core.Error.NotFound;
            defer node.deinit(allocator);
            return renderMarkdownSectionWithHeadingPaged(allocator, store, root_id, rel, markdownProjectionVisibleText(node.text), state);
        }
    }
    try renderMarkdownChildrenPaged(allocator, store, root_id, state);
}

fn renderMarkdownChildrenPaged(allocator: std.mem.Allocator, store: storage.Store, owner_id: core.NodeId, state: *MarkdownPageRenderState) !void {
    var records = try markdownProjectionChildren(allocator, store, owner_id, null);
    defer records.deinit(allocator);
    for (records.items) |record| {
        if (state.stopped) return;
        try renderMarkdownProjectionRecordPaged(allocator, store, record, state);
    }
}

fn renderMarkdownProjectionRecordPaged(allocator: std.mem.Allocator, store: storage.Store, record: storage.EdgeIndexRecord, state: *MarkdownPageRenderState) !void {
    const rel: core.RelKind = @enumFromInt(record.rel);
    if (rel == md_rel_table) return renderMarkdownTablePaged(allocator, store, core.NodeId.fromInt(record.dst), state);

    var node = (try store.readNodeById(allocator, core.NodeId.fromInt(record.dst))) orelse return core.Error.NotFound;
    defer node.deinit(allocator);
    const text_alloc = try renderMarkdownNodeVisibleTextAlloc(allocator, store, core.NodeId.fromInt(record.dst), node);
    defer allocator.free(text_alloc);
    const text = text_alloc;
    if (mdHeadingLevelFromRel(rel)) |level| {
        if (node.kind == .document_section) {
            return renderMarkdownSectionWithHeadingPaged(allocator, store, core.NodeId.fromInt(record.dst), rel, text, state);
        }
        try emitMarkdownHeadingPageUnit(allocator, state, level, text);
    } else if (rel == md_rel_paragraph or rel == md_rel_image or rel == md_rel_code_block or isMarkdownRawTextProjectionRel(rel) or rel == md_rel_table_cell) {
        try emitMarkdownTextBlockPageUnit(allocator, state, text);
    } else if (rel == md_rel_text_chunk) {
        try emitMarkdownPageUnit(state, text);
    }
}

fn renderMarkdownSectionWithHeadingPaged(
    allocator: std.mem.Allocator,
    store: storage.Store,
    section_id: core.NodeId,
    rel: core.RelKind,
    text: []const u8,
    state: *MarkdownPageRenderState,
) !void {
    const level = mdHeadingLevelFromRel(rel) orelse return error.InvalidRelKind;
    try emitMarkdownHeadingPageUnit(allocator, state, level, text);
    if (state.stopped) return;
    try renderMarkdownChildrenPaged(allocator, store, section_id, state);
}

fn renderMarkdownTablePaged(allocator: std.mem.Allocator, store: storage.Store, table_id: core.NodeId, state: *MarkdownPageRenderState) !void {
    var rows = try markdownProjectionChildren(allocator, store, table_id, md_rel_table_row);
    defer rows.deinit(allocator);
    for (rows.items) |row_record| {
        if (state.stopped) return;
        try renderMarkdownTableRowPaged(allocator, store, core.NodeId.fromInt(row_record.dst), state);
    }
    if (!state.stopped) try emitMarkdownPageUnit(state, "\n");
}

fn renderMarkdownTableRowPaged(allocator: std.mem.Allocator, store: storage.Store, row_id: core.NodeId, state: *MarkdownPageRenderState) !void {
    var temp = QueryOutputWriter{ .allocator = allocator };
    defer temp.buffer.deinit(allocator);
    var cells = try markdownProjectionChildren(allocator, store, row_id, md_rel_table_cell);
    defer cells.deinit(allocator);
    try temp.writeAll("|");
    for (cells.items) |cell_record| {
        var cell = (try store.readNodeById(allocator, core.NodeId.fromInt(cell_record.dst))) orelse return core.Error.NotFound;
        defer cell.deinit(allocator);
        const cell_text = try renderMarkdownNodeVisibleTextAlloc(allocator, store, core.NodeId.fromInt(cell_record.dst), cell);
        defer allocator.free(cell_text);
        try temp.writeAll(" ");
        try temp.writeAll(cell_text);
        try temp.writeAll(" |");
    }
    try temp.writeAll("\n");
    try emitMarkdownPageUnit(state, temp.buffer.items);
}

fn renderMarkdownChunkedTextBlockPaged(allocator: std.mem.Allocator, store: storage.Store, node_id: core.NodeId, state: *MarkdownPageRenderState) !void {
    var records = try markdownProjectionChildren(allocator, store, node_id, md_rel_text_chunk);
    defer records.deinit(allocator);
    var text_len: usize = 0;
    var last_byte: u8 = 0;
    for (records.items) |record| {
        if (state.stopped) return;
        var chunk = (try store.readNodeById(allocator, core.NodeId.fromInt(record.dst))) orelse return core.Error.NotFound;
        defer chunk.deinit(allocator);
        const text = markdownProjectionVisibleText(chunk.text);
        if (text.len != 0) {
            text_len += text.len;
            last_byte = text[text.len - 1];
        }
        try emitMarkdownPageUnit(state, text);
    }
    if (state.stopped) return;
    if (text_len == 0 or last_byte != '\n') try emitMarkdownPageUnit(state, "\n");
    if (state.stopped) return;
    try emitMarkdownPageUnit(state, "\n");
}

fn renderMarkdownSubtree(allocator: std.mem.Allocator, store: storage.Store, root_id: core.NodeId, root_kind: core.NodeKind, out: *QueryOutputWriter) !void {
    if (root_kind == .document_section) {
        if (try markdownProjectionHasChild(allocator, store, root_id, md_rel_text_chunk)) {
            const text = try renderMarkdownChunkedTextAlloc(allocator, store, root_id);
            defer allocator.free(text);
            try out.writeAll(text);
            if (text.len == 0 or text[text.len - 1] != '\n') try out.writeAll("\n");
            try out.writeAll("\n");
            return;
        }
        if (try markdownProjectionHasChild(allocator, store, root_id, md_rel_table_row)) {
            return renderMarkdownTable(allocator, store, root_id, out);
        }
        if (try markdownProjectionHasChild(allocator, store, root_id, md_rel_table_cell)) {
            try renderMarkdownTableRow(allocator, store, root_id, out);
            try out.writeAll("\n");
            return;
        }
        if (try markdownIncomingHeadingRel(allocator, store, root_id)) |rel| {
            var node = (try store.readNodeById(allocator, root_id)) orelse return core.Error.NotFound;
            defer node.deinit(allocator);
            return renderMarkdownSectionWithHeading(allocator, store, root_id, rel, markdownProjectionVisibleText(node.text), out);
        }
    }
    try renderMarkdownChildren(allocator, store, root_id, out);
}

fn renderMarkdownChildren(allocator: std.mem.Allocator, store: storage.Store, owner_id: core.NodeId, out: *QueryOutputWriter) !void {
    var records = try markdownProjectionChildren(allocator, store, owner_id, null);
    defer records.deinit(allocator);
    for (records.items) |record| {
        try renderMarkdownProjectionRecord(allocator, store, record, out);
    }
}

fn renderMarkdownProjectionRecord(allocator: std.mem.Allocator, store: storage.Store, record: storage.EdgeIndexRecord, out: *QueryOutputWriter) !void {
    const rel: core.RelKind = @enumFromInt(record.rel);
    if (rel == md_rel_table) return renderMarkdownTable(allocator, store, core.NodeId.fromInt(record.dst), out);

    var node = (try store.readNodeById(allocator, core.NodeId.fromInt(record.dst))) orelse return core.Error.NotFound;
    defer node.deinit(allocator);
    const text_alloc = try renderMarkdownNodeVisibleTextAlloc(allocator, store, core.NodeId.fromInt(record.dst), node);
    defer allocator.free(text_alloc);
    const text = text_alloc;
    if (mdHeadingLevelFromRel(rel)) |level| {
        if (node.kind == .document_section) {
            return renderMarkdownSectionWithHeading(allocator, store, core.NodeId.fromInt(record.dst), rel, text, out);
        }
        var i: usize = 0;
        while (i < level) : (i += 1) try out.writeAll("#");
        try out.writeAll(" ");
        try out.writeAll(text);
        try out.writeAll("\n\n");
    } else if (rel == md_rel_paragraph or rel == md_rel_image or rel == md_rel_code_block or isMarkdownRawTextProjectionRel(rel) or rel == md_rel_table_cell) {
        try out.writeAll(text);
        if (text.len == 0 or text[text.len - 1] != '\n') try out.writeAll("\n");
        try out.writeAll("\n");
    } else if (rel == md_rel_text_chunk) {
        try out.writeAll(text);
    }
}

fn renderMarkdownSectionWithHeading(
    allocator: std.mem.Allocator,
    store: storage.Store,
    section_id: core.NodeId,
    rel: core.RelKind,
    text: []const u8,
    out: *QueryOutputWriter,
) !void {
    const level = mdHeadingLevelFromRel(rel) orelse return error.InvalidRelKind;
    var i: usize = 0;
    while (i < level) : (i += 1) try out.writeAll("#");
    try out.writeAll(" ");
    try out.writeAll(text);
    try out.writeAll("\n\n");
    try renderMarkdownChildren(allocator, store, section_id, out);
}

fn markdownIncomingHeadingRel(allocator: std.mem.Allocator, store: storage.Store, section_id: core.NodeId) !?core.RelKind {
    // This is a physical projection lookup. Keep deferred query edges out of
    // the scan while opening the reverse segment direction only once.
    var records = try store.readVisibleEdgeIndexRecordsByNode(allocator, .dst, section_id, null);
    defer records.deinit(allocator);
    for (records.items) |record| {
        const rel: core.RelKind = @enumFromInt(record.rel);
        if (mdHeadingLevelFromRel(rel) != null) return rel;
    }
    return null;
}

fn renderMarkdownTable(allocator: std.mem.Allocator, store: storage.Store, table_id: core.NodeId, out: *QueryOutputWriter) !void {
    var rows = try markdownProjectionChildren(allocator, store, table_id, md_rel_table_row);
    defer rows.deinit(allocator);
    for (rows.items) |row_record| {
        try renderMarkdownTableRow(allocator, store, core.NodeId.fromInt(row_record.dst), out);
    }
    try out.writeAll("\n");
}

fn renderMarkdownTableRow(allocator: std.mem.Allocator, store: storage.Store, row_id: core.NodeId, out: *QueryOutputWriter) !void {
    var cells = try markdownProjectionChildren(allocator, store, row_id, md_rel_table_cell);
    defer cells.deinit(allocator);
    try out.writeAll("|");
    for (cells.items) |cell_record| {
        var cell = (try store.readNodeById(allocator, core.NodeId.fromInt(cell_record.dst))) orelse return core.Error.NotFound;
        defer cell.deinit(allocator);
        const cell_text = try renderMarkdownNodeVisibleTextAlloc(allocator, store, core.NodeId.fromInt(cell_record.dst), cell);
        defer allocator.free(cell_text);
        try out.writeAll(" ");
        try out.writeAll(cell_text);
        try out.writeAll(" |");
    }
    try out.writeAll("\n");
}

fn renderMarkdownNodeVisibleTextAlloc(allocator: std.mem.Allocator, store: storage.Store, node_id: core.NodeId, node: storage.StoredNode) ![]u8 {
    if (node.kind == .document_section and try markdownProjectionHasChild(allocator, store, node_id, md_rel_text_chunk)) {
        return renderMarkdownChunkedTextAlloc(allocator, store, node_id);
    }
    return try allocator.dupe(u8, markdownProjectionVisibleText(node.text));
}

fn renderMarkdownChunkedTextAlloc(allocator: std.mem.Allocator, store: storage.Store, node_id: core.NodeId) ![]u8 {
    var records = try markdownProjectionChildren(allocator, store, node_id, md_rel_text_chunk);
    defer records.deinit(allocator);
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);
    for (records.items) |record| {
        var chunk = (try store.readNodeById(allocator, core.NodeId.fromInt(record.dst))) orelse return core.Error.NotFound;
        defer chunk.deinit(allocator);
        try out.writeAll(markdownProjectionVisibleText(chunk.text));
    }
    return out.buffer.toOwnedSlice(allocator);
}

fn markdownProjectionHasChild(allocator: std.mem.Allocator, store: storage.Store, owner_id: core.NodeId, rel: core.RelKind) !bool {
    var records = try markdownProjectionChildren(allocator, store, owner_id, rel);
    defer records.deinit(allocator);
    return records.items.len != 0;
}

fn markdownProjectionChildren(allocator: std.mem.Allocator, store: storage.Store, owner_id: core.NodeId, rel_filter: ?core.RelKind) !std.ArrayList(storage.EdgeIndexRecord) {
    const all = try store.readEdgeIndexRecordsByNodeOrdered(allocator, owner_id);
    return filterMarkdownProjectionChildren(allocator, all, rel_filter);
}

fn markdownProjectionChildrenWithOrderMap(allocator: std.mem.Allocator, store: storage.Store, owner_id: core.NodeId, rel_filter: ?core.RelKind, edge_order_map: *std.AutoHashMap(u64, u64)) !std.ArrayList(storage.EdgeIndexRecord) {
    const all = try store.readEdgeIndexRecordsByNodeOrderedWithOrderMap(allocator, owner_id, edge_order_map);
    return filterMarkdownProjectionChildren(allocator, all, rel_filter);
}

fn filterMarkdownProjectionChildren(allocator: std.mem.Allocator, all: std.ArrayList(storage.EdgeIndexRecord), rel_filter: ?core.RelKind) !std.ArrayList(storage.EdgeIndexRecord) {
    var mutable_all = all;
    defer mutable_all.deinit(allocator);
    var out = std.ArrayList(storage.EdgeIndexRecord).empty;
    errdefer out.deinit(allocator);
    for (mutable_all.items) |record| {
        const rel: core.RelKind = @enumFromInt(record.rel);
        if (rel_filter) |wanted| {
            if (rel != wanted) continue;
        } else if (!isMarkdownProjectionRel(rel)) {
            continue;
        }
        try out.append(allocator, record);
    }
    return out;
}

fn markdownDocumentTitle(content: []const u8) ?[]const u8 {
    var lines = std.mem.splitScalar(u8, content, '\n');
    while (lines.next()) |line_raw| {
        const line = trimMarkdownLineRight(line_raw);
        if (markdownHeading(line)) |heading| return heading.text;
        if (std.mem.trim(u8, line, " \t").len != 0) return null;
    }
    return null;
}

fn trimMarkdownLineRight(line: []const u8) []const u8 {
    if (line.len != 0 and line[line.len - 1] == '\r') return line[0 .. line.len - 1];
    return line;
}

fn trimMarkdownLineLeft(line: []const u8) []const u8 {
    var index: usize = 0;
    while (index < line.len and (line[index] == ' ' or line[index] == '\t')) : (index += 1) {}
    return line[index..];
}

const MarkdownHeading = struct {
    level: usize,
    text: []const u8,
};

fn markdownHeading(line: []const u8) ?MarkdownHeading {
    var level: usize = 0;
    while (level < line.len and level < 6 and line[level] == '#') : (level += 1) {}
    if (level == 0 or level >= line.len or line[level] != ' ') return null;
    return .{ .level = level, .text = std.mem.trim(u8, line[level + 1 ..], " \t") };
}

fn mdHeadingRel(level: usize) core.RelKind {
    return switch (level) {
        1 => md_rel_h1,
        2 => md_rel_h2,
        3 => md_rel_h3,
        4 => md_rel_h4,
        5 => md_rel_h5,
        else => md_rel_h6,
    };
}

fn mdHeadingLevelFromRel(rel: core.RelKind) ?usize {
    if (rel == md_rel_h1) return 1;
    if (rel == md_rel_h2) return 2;
    if (rel == md_rel_h3) return 3;
    if (rel == md_rel_h4) return 4;
    if (rel == md_rel_h5) return 5;
    if (rel == md_rel_h6) return 6;
    return null;
}

fn isMarkdownProjectionRel(rel: core.RelKind) bool {
    return mdHeadingLevelFromRel(rel) != null or
        rel == md_rel_paragraph or
        rel == md_rel_code_block or
        rel == md_rel_image or
        rel == md_rel_table or
        rel == md_rel_table_row or
        rel == md_rel_table_cell or
        rel == md_rel_text_chunk or
        isMarkdownRawTextProjectionRel(rel);
}

fn markdownProjectionRelAlwaysHasChildren(rel: core.RelKind) bool {
    return mdHeadingLevelFromRel(rel) != null or
        rel == md_rel_table or
        rel == md_rel_table_row;
}

fn isMarkdownRawTextProjectionRel(rel: core.RelKind) bool {
    return rel == md_rel_list or
        rel == md_rel_blockquote or
        rel == md_rel_html_block or
        rel == md_rel_footnote_def or
        rel == md_rel_link_reference or
        rel == md_rel_thematic_break or
        rel == md_rel_raw_block;
}

fn markdownFenceMarker(line: []const u8) ?[]const u8 {
    const trimmed = trimMarkdownLineLeft(line);
    if (std.mem.startsWith(u8, trimmed, "```")) return "```";
    if (std.mem.startsWith(u8, trimmed, "~~~")) return "~~~";
    return null;
}

fn markdownFenceCloses(line: []const u8, marker: []const u8) bool {
    return std.mem.startsWith(u8, trimMarkdownLineLeft(line), marker);
}

fn markdownImageLine(line: []const u8) bool {
    return std.mem.startsWith(u8, trimMarkdownLineLeft(line), "![");
}

fn markdownTableLine(line: []const u8) bool {
    const trimmed = std.mem.trim(u8, line, " \t");
    return trimmed.len >= 3 and std.mem.indexOfScalar(u8, trimmed, '|') != null;
}

fn markdownListLine(line: []const u8) bool {
    const trimmed = trimMarkdownLineLeft(line);
    if (trimmed.len >= 2 and (trimmed[0] == '-' or trimmed[0] == '*' or trimmed[0] == '+') and trimmed[1] == ' ') return true;
    var index: usize = 0;
    while (index < trimmed.len and std.ascii.isDigit(trimmed[index])) : (index += 1) {}
    return index > 0 and index + 1 < trimmed.len and (trimmed[index] == '.' or trimmed[index] == ')') and trimmed[index + 1] == ' ';
}

fn markdownListContinuationLine(line: []const u8) bool {
    if (std.mem.trim(u8, line, " \t").len == 0) return false;
    return markdownListLine(line) or line[0] == ' ' or line[0] == '\t';
}

fn markdownBlockquoteLine(line: []const u8) bool {
    return std.mem.startsWith(u8, trimMarkdownLineLeft(line), ">");
}

fn markdownIndentedContinuationLine(line: []const u8) bool {
    if (std.mem.trim(u8, line, " \t").len == 0) return false;
    return std.mem.startsWith(u8, line, "    ") or std.mem.startsWith(u8, line, "\t");
}

fn markdownFootnoteDefinitionLine(line: []const u8) bool {
    const trimmed = trimMarkdownLineLeft(line);
    return std.mem.startsWith(u8, trimmed, "[^") and std.mem.indexOf(u8, trimmed, "]:") != null;
}

fn markdownLinkReferenceLine(line: []const u8) bool {
    const trimmed = trimMarkdownLineLeft(line);
    return std.mem.startsWith(u8, trimmed, "[") and !std.mem.startsWith(u8, trimmed, "[^") and std.mem.indexOf(u8, trimmed, "]:") != null;
}

fn markdownHtmlBlockLine(line: []const u8) bool {
    const trimmed = trimMarkdownLineLeft(line);
    if (trimmed.len < 3 or trimmed[0] != '<') return false;
    if (std.mem.startsWith(u8, trimmed, "<http://") or std.mem.startsWith(u8, trimmed, "<https://")) return false;
    return std.ascii.isAlphabetic(trimmed[1]) or trimmed[1] == '/' or trimmed[1] == '!' or trimmed[1] == '?';
}

fn markdownThematicBreakLine(line: []const u8) bool {
    const trimmed = std.mem.trim(u8, line, " \t");
    if (trimmed.len < 3) return false;
    var marker: u8 = 0;
    var count: usize = 0;
    for (trimmed) |ch| {
        if (ch == ' ' or ch == '\t') continue;
        if (ch != '-' and ch != '*' and ch != '_') return false;
        if (marker == 0) {
            marker = ch;
        } else if (marker != ch) {
            return false;
        }
        count += 1;
    }
    return count >= 3;
}

fn markdownSetextHeadingStart(lines: []const []const u8, index: usize) bool {
    if (index + 1 >= lines.len) return false;
    if (std.mem.trim(u8, lines[index], " \t").len == 0) return false;
    return markdownSetextUnderlineLine(lines[index + 1]);
}

fn markdownSetextUnderlineLine(line: []const u8) bool {
    const trimmed = std.mem.trim(u8, line, " \t");
    if (trimmed.len == 0) return false;
    for (trimmed) |ch| {
        if (ch != '=' and ch != '-') return false;
    }
    return true;
}

fn markdownRawFallbackLine(line: []const u8) bool {
    return markdownIndentedContinuationLine(line);
}

fn markdownRawFallbackContinuationLine(line: []const u8) bool {
    return markdownIndentedContinuationLine(line);
}

fn markdownProjectionVisibleText(text: []const u8) []const u8 {
    return text;
}

const store_manifest_dir = ".tinykg";
const store_manifest_file = "store-manifest.json";
const current_storage_format_version = 2;
const current_schema_version = 3;
const current_store_manifest_version = 1;

const StoreManifestWriteOptions = struct {
    profiles: []const u8 = "",
    migration_name: []const u8 = "",
    source_path: []const u8 = "",
    schema_version: u32 = current_schema_version,
};

const StoreManifestSummary = struct {
    status: []const u8,
    storage_format_version: []const u8,
    schema_version: []const u8,
    enabled_profiles: []const u8,
    migration_name: []const u8,
    migration_source: []const u8,
    owned_storage_format_version: ?[]u8 = null,
    owned_schema_version: ?[]u8 = null,
    owned_enabled_profiles: ?[]u8 = null,
    owned_migration_name: ?[]u8 = null,
    owned_migration_source: ?[]u8 = null,

    fn deinit(self: StoreManifestSummary, allocator: std.mem.Allocator) void {
        if (self.owned_storage_format_version) |value| allocator.free(value);
        if (self.owned_schema_version) |value| allocator.free(value);
        if (self.owned_enabled_profiles) |value| allocator.free(value);
        if (self.owned_migration_name) |value| allocator.free(value);
        if (self.owned_migration_source) |value| allocator.free(value);
    }
};

const StoreManifestJson = struct {
    store_manifest_version: ?u32 = null,
    storage_format_version: ?u32 = null,
    schema: ?struct {
        schema_version: ?u32 = null,
        enabled_profiles: ?[]const []const u8 = null,
    } = null,
    migration: ?struct {
        name: ?[]const u8 = null,
        source: ?[]const u8 = null,
    } = null,
};

fn storeManifestPath(allocator: std.mem.Allocator, db_path: []const u8) ![]u8 {
    return try std.fs.path.join(allocator, &.{ db_path, store_manifest_dir, store_manifest_file });
}

fn writeStoreManifest(allocator: std.mem.Allocator, io: std.Io, db_path: []const u8, options: StoreManifestWriteOptions) !void {
    const manifest_dir_path = try std.fs.path.join(allocator, &.{ db_path, store_manifest_dir });
    defer allocator.free(manifest_dir_path);
    try std.Io.Dir.cwd().createDirPath(io, manifest_dir_path);

    const manifest_path = try storeManifestPath(allocator, db_path);
    defer allocator.free(manifest_path);

    var out = QueryOutputWriter{ .allocator = allocator, .max_bytes = 64 * 1024 };
    defer out.buffer.deinit(allocator);
    try out.writeAll("{\n");
    try out.print("  \"store_manifest_version\": {},\n", .{current_store_manifest_version});
    try out.print("  \"storage_format_version\": {},\n", .{current_storage_format_version});
    try out.writeAll("  \"created_by\": \"tinykg\",\n");
    try out.writeAll("  \"schema\": {\n");
    try out.print("    \"schema_version\": {},\n", .{options.schema_version});
    try out.writeAll("    \"kernel_version\": 1,\n");
    try out.writeAll("    \"enabled_profiles\": [");
    var profile_it = std.mem.splitScalar(u8, options.profiles, ',');
    var first = true;
    while (profile_it.next()) |raw_profile| {
        const profile = std.mem.trim(u8, raw_profile, " \t\r\n");
        if (profile.len == 0) continue;
        if (!first) try out.writeAll(", ");
        try writeJsonString(&out, profile);
        first = false;
    }
    try out.writeAll("]\n  },\n");
    try out.writeAll("  \"migration\": {\n");
    try out.writeAll("    \"name\": ");
    try writeJsonString(&out, options.migration_name);
    try out.writeAll(",\n    \"source\": ");
    try writeJsonString(&out, options.source_path);
    try out.print(",\n    \"recorded_ns\": {}\n", .{persistentNowNs(io)});
    try out.writeAll("  }\n}\n");

    const tmp_path = try std.fmt.allocPrint(allocator, "{s}.tmp", .{manifest_path});
    defer allocator.free(tmp_path);
    errdefer std.Io.Dir.cwd().deleteFile(io, tmp_path) catch {};
    {
        var file = try std.Io.Dir.cwd().createFile(io, tmp_path, .{ .read = true, .truncate = true });
        defer file.close(io);
        try file.writePositionalAll(io, out.buffer.items, 0);
        try file.sync(io);
    }
    if (std.fs.path.isAbsolute(tmp_path) or std.fs.path.isAbsolute(manifest_path)) {
        try std.Io.Dir.renameAbsolute(tmp_path, manifest_path, io);
    } else {
        try std.Io.Dir.rename(.cwd(), tmp_path, .cwd(), manifest_path, io);
    }
    if (builtin.os.tag != .windows) {
        const parent = std.fs.path.dirname(manifest_path) orelse ".";
        var dir_file = if (std.fs.path.isAbsolute(parent))
            try std.Io.Dir.openFileAbsolute(io, parent, .{ .allow_directory = true })
        else
            try std.Io.Dir.cwd().openFile(io, parent, .{ .allow_directory = true });
        defer dir_file.close(io);
        try dir_file.sync(io);
    }
}

fn readStoreManifestSummary(allocator: std.mem.Allocator, io: std.Io, db_path: []const u8) !StoreManifestSummary {
    const manifest_path = try storeManifestPath(allocator, db_path);
    defer allocator.free(manifest_path);
    const bytes = std.Io.Dir.cwd().readFileAlloc(io, manifest_path, allocator, .limited(64 * 1024)) catch |err| switch (err) {
        error.FileNotFound, error.NotDir => return .{
            .status = "legacy",
            .storage_format_version = "legacy",
            .schema_version = "legacy",
            .enabled_profiles = "",
            .migration_name = "",
            .migration_source = "",
        },
        else => |e| return e,
    };
    defer allocator.free(bytes);

    var parsed = try std.json.parseFromSlice(StoreManifestJson, allocator, bytes, .{
        .ignore_unknown_fields = true,
        .allocate = .alloc_always,
    });
    defer parsed.deinit();

    const storage_version = try std.fmt.allocPrint(allocator, "{}", .{parsed.value.storage_format_version orelse 0});
    errdefer allocator.free(storage_version);
    const schema_version = try std.fmt.allocPrint(allocator, "{}", .{if (parsed.value.schema) |schema_value| schema_value.schema_version orelse 0 else 0});
    errdefer allocator.free(schema_version);

    var profiles_out = std.ArrayList(u8).empty;
    errdefer profiles_out.deinit(allocator);
    if (parsed.value.schema) |schema_value| {
        if (schema_value.enabled_profiles) |profiles| {
            for (profiles, 0..) |profile, index| {
                if (index != 0) try profiles_out.append(allocator, ',');
                try profiles_out.appendSlice(allocator, profile);
            }
        }
    }
    const profiles = try profiles_out.toOwnedSlice(allocator);
    errdefer allocator.free(profiles);
    const migration_name = try allocator.dupe(u8, if (parsed.value.migration) |migration| migration.name orelse "" else "");
    errdefer allocator.free(migration_name);
    const migration_source = try allocator.dupe(u8, if (parsed.value.migration) |migration| migration.source orelse "" else "");
    return .{
        .status = "present",
        .storage_format_version = storage_version,
        .schema_version = schema_version,
        .enabled_profiles = profiles,
        .migration_name = migration_name,
        .migration_source = migration_source,
        .owned_storage_format_version = storage_version,
        .owned_schema_version = schema_version,
        .owned_enabled_profiles = profiles,
        .owned_migration_name = migration_name,
        .owned_migration_source = migration_source,
    };
}

const migrate_node_string_property_keys = [_][]const u8{
    "name",
    "status",
    "claimed_by",
    "summary",
    "retrieval_hints",
    "schema_type",
    "external_key",
    "content_hash",
    "task_event_type",
    "dependency_relation",
};

const migrate_node_uint_property_keys = [_][]const u8{
    "generation",
    "created_at",
    "updated_at",
    "byte_start",
    "byte_end",
    "line_start",
    "line_end",
    "tombstone_generation",
    "task_recorded_ns",
    "task_created_ns",
    "task_completed_ns",
    "claim_expires_ns",
    "task_event_ns",
    "task_root_id",
    "task_id",
};

const migrate_edge_string_property_keys = [_][]const u8{
    "markdown_attr",
    "render_flags",
    "source_span",
    "confidence",
    "created_by",
    "projection_edge_id",
    "fact_edge_id",
};

const migrate_edge_uint_property_keys = [_][]const u8{
    "order_key",
    "generation",
    "created_at",
    "updated_at",
    "byte_start",
    "byte_end",
    "line_start",
    "line_end",
    "tombstone_generation",
};

const MigrationPropertyDomain = enum { node, edge };

const MigrationPropertyKeys = struct {
    allocator: std.mem.Allocator,
    items: std.ArrayList([]const u8) = .empty,
    by_hash: std.AutoHashMap(u64, []const u8),

    fn init(
        allocator: std.mem.Allocator,
        source_registry: schema.Registry,
        target_registry: schema.Registry,
        domain: MigrationPropertyDomain,
    ) !MigrationPropertyKeys {
        var out = MigrationPropertyKeys{
            .allocator = allocator,
            .by_hash = std.AutoHashMap(u64, []const u8).init(allocator),
        };
        errdefer out.deinit();
        switch (domain) {
            .node => {
                for (migrate_node_string_property_keys) |key| try out.add(key);
                for (migrate_node_uint_property_keys) |key| try out.add(key);
            },
            .edge => {
                for (migrate_edge_string_property_keys) |key| try out.add(key);
                for (migrate_edge_uint_property_keys) |key| try out.add(key);
            },
        }
        try out.addRegistry(source_registry, domain);
        try out.addRegistry(target_registry, domain);
        return out;
    }

    fn deinit(self: *MigrationPropertyKeys) void {
        self.items.deinit(self.allocator);
        self.by_hash.deinit();
        self.* = undefined;
    }

    fn add(self: *MigrationPropertyKeys, key: []const u8) !void {
        const hash = storage.propertyKeyHashForLookup(key);
        const entry = try self.by_hash.getOrPut(hash);
        if (entry.found_existing) {
            if (!std.mem.eql(u8, entry.value_ptr.*, key)) return error.InvalidRecord;
            return;
        }
        errdefer _ = self.by_hash.remove(hash);
        entry.value_ptr.* = key;
        try self.items.append(self.allocator, key);
    }

    fn addRegistry(self: *MigrationPropertyKeys, registry: schema.Registry, domain: MigrationPropertyDomain) !void {
        const max_types: usize = switch (domain) {
            .node => schema.max_node_types,
            .edge => schema.max_relation_types,
        };
        for (0..max_types) |raw_id| {
            const type_id: u16 = @intCast(raw_id);
            const present = switch (domain) {
                .node => registry.hasNodeTypeId(type_id),
                .edge => registry.hasRelationTypeId(type_id),
            };
            if (!present) continue;
            var property_index: usize = 0;
            while (true) : (property_index += 1) {
                const property = switch (domain) {
                    .node => registry.nodePropertyInfo(type_id, property_index),
                    .edge => registry.relationPropertyInfo(type_id, property_index),
                } orelse break;
                if (domain == .node and std.mem.eql(u8, property.name, "text")) continue;
                try self.add(property.name);
            }
        }
    }
};

const migration_property_run_chunk_records: usize = 256 * 1024;
const migration_property_max_runs: usize = 512;
const migration_property_merge_fan_in: usize = 64;
const migration_property_spool_record_len: usize = 56;
const migration_property_reader_buffer_bytes: usize = migration_property_spool_record_len * 256;
const migration_property_run_write_buffer_bytes: usize = 1024 * 1024;
const migration_property_value_buffer_bytes: usize = 1024 * 1024;

const MigrationPropertySpoolRecord = struct {
    owner_kind: u8,
    value_kind: storage.PropertySnapshotValueKind,
    owner_id: u64,
    key_hash: u64,
    version: u64,
    value_offset: u64 = 0,
    uint_value: u64 = 0,
    value_len: u32 = 0,

    fn encode(self: MigrationPropertySpoolRecord, out: *[migration_property_spool_record_len]u8) !void {
        @memset(out, 0);
        if ((self.owner_kind != 1 and self.owner_kind != 2) or self.owner_id == 0 or self.owner_id == std.math.maxInt(u64)) return error.InvalidRecord;
        out[0] = self.owner_kind;
        out[1] = @intFromEnum(self.value_kind);
        std.mem.writeInt(u64, out[8..16], self.owner_id, .little);
        std.mem.writeInt(u64, out[16..24], self.key_hash, .little);
        std.mem.writeInt(u64, out[24..32], self.version, .little);
        std.mem.writeInt(u64, out[32..40], self.value_offset, .little);
        std.mem.writeInt(u64, out[40..48], self.uint_value, .little);
        std.mem.writeInt(u32, out[48..52], self.value_len, .little);
        switch (self.value_kind) {
            .string => if (self.value_len == 0 or self.uint_value != 0) return error.InvalidRecord,
            .uint => if (self.value_len != 0 or self.value_offset != 0) return error.InvalidRecord,
        }
    }

    fn decode(bytes: *const [migration_property_spool_record_len]u8) !MigrationPropertySpoolRecord {
        if (!std.mem.allEqual(u8, bytes[2..8], 0) or !std.mem.allEqual(u8, bytes[52..56], 0)) return error.InvalidRecord;
        const raw_kind = bytes[1];
        const value_kind: storage.PropertySnapshotValueKind = switch (raw_kind) {
            @intFromEnum(storage.PropertySnapshotValueKind.string) => .string,
            @intFromEnum(storage.PropertySnapshotValueKind.uint) => .uint,
            else => return error.InvalidRecord,
        };
        const record = MigrationPropertySpoolRecord{
            .owner_kind = bytes[0],
            .value_kind = value_kind,
            .owner_id = std.mem.readInt(u64, bytes[8..16], .little),
            .key_hash = std.mem.readInt(u64, bytes[16..24], .little),
            .version = std.mem.readInt(u64, bytes[24..32], .little),
            .value_offset = std.mem.readInt(u64, bytes[32..40], .little),
            .uint_value = std.mem.readInt(u64, bytes[40..48], .little),
            .value_len = std.mem.readInt(u32, bytes[48..52], .little),
        };
        var canonical: [migration_property_spool_record_len]u8 = undefined;
        try record.encode(&canonical);
        if (!std.mem.eql(u8, &canonical, bytes)) return error.InvalidRecord;
        return record;
    }
};

const MigrationPropertySortOrder = enum { effective_owner, canonical_payload };

fn migrationPropertySpoolRecordLessThan(order: MigrationPropertySortOrder, lhs: MigrationPropertySpoolRecord, rhs: MigrationPropertySpoolRecord) bool {
    return switch (order) {
        .effective_owner => blk: {
            if (lhs.owner_kind != rhs.owner_kind) break :blk lhs.owner_kind < rhs.owner_kind;
            if (lhs.owner_id != rhs.owner_id) break :blk lhs.owner_id < rhs.owner_id;
            if (lhs.key_hash != rhs.key_hash) break :blk lhs.key_hash < rhs.key_hash;
            break :blk lhs.version < rhs.version;
        },
        .canonical_payload => blk: {
            if (lhs.key_hash != rhs.key_hash) break :blk lhs.key_hash < rhs.key_hash;
            if (lhs.value_kind != rhs.value_kind) break :blk @intFromEnum(lhs.value_kind) < @intFromEnum(rhs.value_kind);
            // Target-spool records store the canonical value_hash in version.
            if (lhs.version != rhs.version) break :blk lhs.version < rhs.version;
            if (lhs.owner_kind != rhs.owner_kind) break :blk lhs.owner_kind < rhs.owner_kind;
            break :blk lhs.owner_id < rhs.owner_id;
        },
    };
}

const MigrationPropertySpoolBuilder = struct {
    allocator: std.mem.Allocator,
    io: std.Io,
    scratch_dir: []const u8,
    nonce: u64,
    node_keys: *const MigrationPropertyKeys,
    edge_keys: *const MigrationPropertyKeys,
    filter_keys: bool = true,
    sort_order: MigrationPropertySortOrder,
    values_path: []u8,
    values_file: std.Io.File,
    values_offset: u64 = 0,
    record_count: u64 = 0,
    values_buffer: std.ArrayList(u8) = .empty,
    records: std.ArrayList(MigrationPropertySpoolRecord) = .empty,
    run_paths: std.ArrayList([]u8) = .empty,

    fn deinit(self: *MigrationPropertySpoolBuilder, keep_files: bool) void {
        self.values_file.close(self.io);
        self.values_buffer.deinit(self.allocator);
        self.records.deinit(self.allocator);
        if (!keep_files) {
            for (self.run_paths.items) |path| std.Io.Dir.cwd().deleteFile(self.io, path) catch {};
            std.Io.Dir.cwd().deleteFile(self.io, self.values_path) catch {};
        }
        for (self.run_paths.items) |path| self.allocator.free(path);
        self.run_paths.deinit(self.allocator);
        self.allocator.free(self.values_path);
        self.* = undefined;
    }

    fn flushValues(self: *MigrationPropertySpoolBuilder) !void {
        if (self.values_buffer.items.len == 0) return;
        const buffered_len: u64 = @intCast(self.values_buffer.items.len);
        if (buffered_len > self.values_offset) return error.InvalidRecord;
        try self.values_file.writePositionalAll(
            self.io,
            self.values_buffer.items,
            self.values_offset - buffered_len,
        );
        self.values_buffer.clearRetainingCapacity();
    }

    fn appendStringValue(self: *MigrationPropertySpoolBuilder, value: []const u8) !u64 {
        const offset = self.values_offset;
        const next_offset = std.math.add(u64, offset, value.len) catch return error.RecordTooLarge;
        if (value.len > migration_property_value_buffer_bytes) {
            try self.flushValues();
            try self.values_file.writePositionalAll(self.io, value, offset);
        } else {
            if (value.len > migration_property_value_buffer_bytes - self.values_buffer.items.len) try self.flushValues();
            try self.values_buffer.appendSlice(self.allocator, value);
        }
        self.values_offset = next_offset;
        return offset;
    }

    fn appendLayer(context: *anyopaque, entry: storage.PropertySnapshotLayerEntry) anyerror!void {
        const self: *MigrationPropertySpoolBuilder = @ptrCast(@alignCast(context));
        const domain_keys: *const MigrationPropertyKeys = switch (entry.owner) {
            .node => self.node_keys,
            .edge => self.edge_keys,
        };
        if (self.filter_keys and !domain_keys.by_hash.contains(entry.key_hash)) return;
        const owner_id: u64 = switch (entry.owner) {
            .node => |id| id.toInt(),
            .edge => |id| id.toInt(),
        };
        const owner_kind: u8 = switch (entry.owner) {
            .node => 1,
            .edge => 2,
        };
        var record = MigrationPropertySpoolRecord{
            .owner_kind = owner_kind,
            .value_kind = entry.value_kind,
            .owner_id = owner_id,
            .key_hash = entry.key_hash,
            .version = entry.version,
            .uint_value = entry.uint_value,
        };
        if (entry.value_kind == .string) {
            record.value_len = std.math.cast(u32, entry.string_value.len) orelse return error.RecordTooLarge;
            record.value_offset = try self.appendStringValue(entry.string_value);
        }
        try self.records.append(self.allocator, record);
        self.record_count = std.math.add(u64, self.record_count, 1) catch return error.RecordTooLarge;
        if (self.records.items.len >= migration_property_run_chunk_records) try self.flushRun();
    }

    fn flushRun(self: *MigrationPropertySpoolBuilder) !void {
        if (self.records.items.len == 0) return;
        if (self.run_paths.items.len >= migration_property_max_runs) return error.SchemaMigrationPropertyRunLimitExceeded;
        std.mem.sort(MigrationPropertySpoolRecord, self.records.items, self.sort_order, migrationPropertySpoolRecordLessThan);
        const run_path = try std.fmt.allocPrint(self.allocator, "{s}/.schema-property-{d}-{d}.run.tmp", .{ self.scratch_dir, self.nonce, self.run_paths.items.len });
        errdefer self.allocator.free(run_path);
        errdefer std.Io.Dir.cwd().deleteFile(self.io, run_path) catch {};
        const byte_len = std.math.mul(usize, self.records.items.len, migration_property_spool_record_len) catch return error.RecordTooLarge;
        const bytes = try self.allocator.alloc(u8, byte_len);
        defer self.allocator.free(bytes);
        for (self.records.items, 0..) |record, index| {
            const start = index * migration_property_spool_record_len;
            try record.encode(bytes[start..][0..migration_property_spool_record_len]);
        }
        var file = try std.Io.Dir.cwd().createFile(self.io, run_path, .{ .read = true, .truncate = true });
        defer file.close(self.io);
        try file.writePositionalAll(self.io, bytes, 0);
        try self.run_paths.append(self.allocator, run_path);
        self.records.clearRetainingCapacity();
    }
};

const MigrationPropertySpool = struct {
    allocator: std.mem.Allocator,
    io: std.Io,
    values_path: []u8,
    run_paths: [][]u8,
    sort_order: MigrationPropertySortOrder,
    record_count: u64,

    fn build(
        allocator: std.mem.Allocator,
        io: std.Io,
        scratch_dir: []const u8,
        source: storage.Store,
        node_keys: *const MigrationPropertyKeys,
        edge_keys: *const MigrationPropertyKeys,
    ) !MigrationPropertySpool {
        return buildFiltered(allocator, io, scratch_dir, source, node_keys, edge_keys, true);
    }

    fn buildAll(
        allocator: std.mem.Allocator,
        io: std.Io,
        scratch_dir: []const u8,
        source: storage.Store,
        node_keys: *const MigrationPropertyKeys,
        edge_keys: *const MigrationPropertyKeys,
    ) !MigrationPropertySpool {
        return buildFiltered(allocator, io, scratch_dir, source, node_keys, edge_keys, false);
    }

    fn buildFiltered(
        allocator: std.mem.Allocator,
        io: std.Io,
        scratch_dir: []const u8,
        source: storage.Store,
        node_keys: *const MigrationPropertyKeys,
        edge_keys: *const MigrationPropertyKeys,
        filter_keys: bool,
    ) !MigrationPropertySpool {
        const nonce = export_temp_nonce.fetchAdd(1, .monotonic);
        const values_path = try std.fmt.allocPrint(allocator, "{s}/.schema-property-{d}.values.tmp", .{ scratch_dir, nonce });
        var path_owned_by_builder = false;
        errdefer if (!path_owned_by_builder) allocator.free(values_path);
        var values_file = try std.Io.Dir.cwd().createFile(io, values_path, .{ .read = true, .truncate = true });
        var builder = MigrationPropertySpoolBuilder{
            .allocator = allocator,
            .io = io,
            .scratch_dir = scratch_dir,
            .nonce = nonce,
            .node_keys = node_keys,
            .edge_keys = edge_keys,
            .filter_keys = filter_keys,
            .sort_order = .effective_owner,
            .values_path = values_path,
            .values_file = values_file,
        };
        path_owned_by_builder = true;
        values_file = undefined;
        var keep_files = false;
        defer builder.deinit(keep_files);
        try builder.values_buffer.ensureTotalCapacityPrecise(allocator, migration_property_value_buffer_bytes);
        try builder.records.ensureTotalCapacityPrecise(allocator, migration_property_run_chunk_records);
        try source.scanPropertySnapshotLayers(allocator, &builder, MigrationPropertySpoolBuilder.appendLayer);
        const OrderLayerContext = struct {
            builder: *MigrationPropertySpoolBuilder,

            fn visit(raw_context: *anyopaque, record: storage.EdgeOrderRecord) anyerror!void {
                const context: *@This() = @ptrCast(@alignCast(raw_context));
                try MigrationPropertySpoolBuilder.appendLayer(context.builder, .{
                    .owner = .{ .edge = .fromInt(record.edge_id) },
                    .key_hash = storage.propertyKeyHashForLookup("order_key"),
                    // edge_order.idx is the authoritative ordered-composition
                    // sidecar, so it wins over every historical property layer.
                    .version = std.math.maxInt(u64),
                    .value_kind = .uint,
                    .uint_value = record.order_key,
                });
            }
        };
        var order_layer_context = OrderLayerContext{ .builder = &builder };
        _ = try source.scanEdgeOrderRecords(&order_layer_context, OrderLayerContext.visit);
        try builder.flushValues();
        try builder.flushRun();
        try coalesceMigrationPropertyRuns(allocator, io, scratch_dir, nonce, builder.sort_order, &builder.run_paths);
        const empty_values_path = try allocator.dupe(u8, "");
        errdefer allocator.free(empty_values_path);
        const run_paths = try builder.run_paths.toOwnedSlice(allocator);
        builder.run_paths = .empty;
        const owned_values_path = builder.values_path;
        builder.values_path = empty_values_path;
        keep_files = true;
        return .{
            .allocator = allocator,
            .io = io,
            .values_path = owned_values_path,
            .run_paths = run_paths,
            .sort_order = builder.sort_order,
            .record_count = builder.record_count,
        };
    }

    fn deinit(self: *MigrationPropertySpool) void {
        for (self.run_paths) |path| {
            std.Io.Dir.cwd().deleteFile(self.io, path) catch {};
            self.allocator.free(path);
        }
        self.allocator.free(self.run_paths);
        std.Io.Dir.cwd().deleteFile(self.io, self.values_path) catch {};
        self.allocator.free(self.values_path);
        self.* = undefined;
    }
};

const migration_edge_spool_record_len: usize = 32;
const migration_edge_run_chunk_records: usize = 256 * 1024;
const migration_edge_max_runs: usize = 512;
const migration_edge_merge_fan_in: usize = 64;
const migration_edge_reader_buffer_bytes: usize = migration_edge_spool_record_len * 256;
const migration_edge_run_write_buffer_bytes: usize = 1024 * 1024;

fn migrationEdgeRecordLessThan(_: void, lhs: storage.EdgeIndexRecord, rhs: storage.EdgeIndexRecord) bool {
    if (lhs.edge_id != rhs.edge_id) return lhs.edge_id < rhs.edge_id;
    if (lhs.src != rhs.src) return lhs.src < rhs.src;
    if (lhs.rel != rhs.rel) return lhs.rel < rhs.rel;
    return lhs.dst < rhs.dst;
}

fn encodeMigrationEdgeRecord(record: storage.EdgeIndexRecord, out: *[migration_edge_spool_record_len]u8) !void {
    if (record.src == 0 or record.dst == 0 or record.edge_id == 0 or
        record.src == std.math.maxInt(u64) or record.dst == std.math.maxInt(u64) or record.edge_id == std.math.maxInt(u64)) return error.InvalidRecord;
    _ = try record.relKind();
    @memset(out, 0);
    std.mem.writeInt(u64, out[0..8], record.src, .little);
    std.mem.writeInt(u64, out[8..16], record.dst, .little);
    std.mem.writeInt(u64, out[16..24], record.edge_id, .little);
    std.mem.writeInt(u16, out[24..26], record.rel, .little);
}

fn decodeMigrationEdgeRecord(bytes: *const [migration_edge_spool_record_len]u8) !storage.EdgeIndexRecord {
    if (!std.mem.allEqual(u8, bytes[26..], 0)) return error.InvalidRecord;
    const record = storage.EdgeIndexRecord{
        .src = std.mem.readInt(u64, bytes[0..8], .little),
        .dst = std.mem.readInt(u64, bytes[8..16], .little),
        .edge_id = std.mem.readInt(u64, bytes[16..24], .little),
        .rel = std.mem.readInt(u16, bytes[24..26], .little),
    };
    var canonical: [migration_edge_spool_record_len]u8 = undefined;
    try encodeMigrationEdgeRecord(record, &canonical);
    if (!std.mem.eql(u8, &canonical, bytes)) return error.InvalidRecord;
    return record;
}

const MigrationEdgeRunWriter = struct {
    allocator: std.mem.Allocator,
    io: std.Io,
    file: std.Io.File,
    offset: u64 = 0,
    buffer: std.ArrayList(u8) = .empty,

    fn init(allocator: std.mem.Allocator, io: std.Io, file: std.Io.File) !MigrationEdgeRunWriter {
        var out = MigrationEdgeRunWriter{ .allocator = allocator, .io = io, .file = file };
        errdefer out.buffer.deinit(allocator);
        try out.buffer.ensureTotalCapacityPrecise(allocator, migration_edge_run_write_buffer_bytes);
        return out;
    }

    fn deinit(self: *MigrationEdgeRunWriter) void {
        self.buffer.deinit(self.allocator);
        self.* = undefined;
    }

    fn append(self: *MigrationEdgeRunWriter, record: storage.EdgeIndexRecord) !void {
        if (migration_edge_spool_record_len > migration_edge_run_write_buffer_bytes - self.buffer.items.len) try self.flush();
        var bytes: [migration_edge_spool_record_len]u8 = undefined;
        try encodeMigrationEdgeRecord(record, &bytes);
        try self.buffer.appendSlice(self.allocator, &bytes);
    }

    fn flush(self: *MigrationEdgeRunWriter) !void {
        if (self.buffer.items.len == 0) return;
        try self.file.writePositionalAll(self.io, self.buffer.items, self.offset);
        self.offset = std.math.add(u64, self.offset, self.buffer.items.len) catch return error.RecordTooLarge;
        self.buffer.clearRetainingCapacity();
    }
};

const MigrationEdgeRunReader = struct {
    allocator: std.mem.Allocator,
    io: std.Io,
    file: std.Io.File,
    remaining: u64,
    file_offset: u64 = 0,
    buffer: []u8,
    cursor: usize = 0,
    len: usize = 0,

    fn init(allocator: std.mem.Allocator, io: std.Io, path: []const u8) !MigrationEdgeRunReader {
        var file = try std.Io.Dir.cwd().openFile(io, path, .{ .allow_directory = false });
        errdefer file.close(io);
        const stat = try file.stat(io);
        if (stat.kind != .file or stat.size == 0 or stat.size % migration_edge_spool_record_len != 0) return error.InvalidRecord;
        const buffer = try allocator.alloc(u8, migration_edge_reader_buffer_bytes);
        errdefer allocator.free(buffer);
        return .{
            .allocator = allocator,
            .io = io,
            .file = file,
            .remaining = stat.size / migration_edge_spool_record_len,
            .buffer = buffer,
        };
    }

    fn deinit(self: *MigrationEdgeRunReader) void {
        self.allocator.free(self.buffer);
        self.file.close(self.io);
        self.* = undefined;
    }

    fn refill(self: *MigrationEdgeRunReader) !void {
        const n = try self.file.readPositionalAll(self.io, self.buffer, self.file_offset);
        if (n == 0 or n % migration_edge_spool_record_len != 0) return error.InvalidRecord;
        self.file_offset = std.math.add(u64, self.file_offset, n) catch return error.InvalidRecord;
        self.cursor = 0;
        self.len = n;
    }

    fn next(self: *MigrationEdgeRunReader) !?storage.EdgeIndexRecord {
        if (self.remaining == 0) return null;
        if (self.cursor == self.len) try self.refill();
        if (self.len - self.cursor < migration_edge_spool_record_len) return error.InvalidRecord;
        const bytes = self.buffer[self.cursor..][0..migration_edge_spool_record_len];
        self.cursor += migration_edge_spool_record_len;
        self.remaining -= 1;
        return try decodeMigrationEdgeRecord(bytes);
    }
};

const MigrationEdgeQueueEntry = struct {
    run_index: usize,
    record: storage.EdgeIndexRecord,
};

fn compareMigrationEdgeQueueEntry(_: void, lhs: MigrationEdgeQueueEntry, rhs: MigrationEdgeQueueEntry) std.math.Order {
    if (migrationEdgeRecordLessThan({}, lhs.record, rhs.record)) return .lt;
    if (migrationEdgeRecordLessThan({}, rhs.record, lhs.record)) return .gt;
    return std.math.order(lhs.run_index, rhs.run_index);
}

fn mergeMigrationEdgeRunGroup(
    allocator: std.mem.Allocator,
    io: std.Io,
    input_paths: []const []u8,
    output_path: []const u8,
) !void {
    if (input_paths.len == 0 or input_paths.len > migration_edge_merge_fan_in) return error.InvalidRecord;
    var readers = std.ArrayList(MigrationEdgeRunReader).empty;
    defer {
        for (readers.items) |*reader| reader.deinit();
        readers.deinit(allocator);
    }
    var queue = std.PriorityQueue(MigrationEdgeQueueEntry, void, compareMigrationEdgeQueueEntry).initContext({});
    defer queue.deinit(allocator);
    try readers.ensureTotalCapacityPrecise(allocator, input_paths.len);
    try queue.ensureTotalCapacityPrecise(allocator, input_paths.len);
    for (input_paths) |path| {
        const run_index = readers.items.len;
        readers.appendAssumeCapacity(try MigrationEdgeRunReader.init(allocator, io, path));
        const first = (try readers.items[run_index].next()) orelse return error.InvalidRecord;
        try queue.push(allocator, .{ .run_index = run_index, .record = first });
    }

    var output_file = try std.Io.Dir.cwd().createFile(io, output_path, .{ .read = true, .truncate = true, .exclusive = true });
    defer output_file.close(io);
    var writer = try MigrationEdgeRunWriter.init(allocator, io, output_file);
    defer writer.deinit();
    var previous_edge_id: u64 = 0;
    while (queue.pop()) |entry| {
        if (entry.record.edge_id <= previous_edge_id) return error.InvalidRecord;
        previous_edge_id = entry.record.edge_id;
        try writer.append(entry.record);
        if (try readers.items[entry.run_index].next()) |next_record| {
            try queue.push(allocator, .{ .run_index = entry.run_index, .record = next_record });
        }
    }
    try writer.flush();
}

fn coalesceMigrationEdgeRuns(
    allocator: std.mem.Allocator,
    io: std.Io,
    scratch_dir: []const u8,
    nonce: u64,
    run_paths: *std.ArrayList([]u8),
) !void {
    var pass: usize = 0;
    while (run_paths.items.len > migration_edge_merge_fan_in) : (pass += 1) {
        var merged_paths = std.ArrayList([]u8).empty;
        errdefer {
            for (merged_paths.items) |path| {
                std.Io.Dir.cwd().deleteFile(io, path) catch {};
                allocator.free(path);
            }
            merged_paths.deinit(allocator);
        }
        const output_count = std.math.divCeil(usize, run_paths.items.len, migration_edge_merge_fan_in) catch return error.InvalidRecord;
        try merged_paths.ensureTotalCapacityPrecise(allocator, output_count);
        var start: usize = 0;
        while (start < run_paths.items.len) {
            const end = start + @min(migration_edge_merge_fan_in, run_paths.items.len - start);
            var output_path: ?[]u8 = try std.fmt.allocPrint(
                allocator,
                "{s}/.schema-edge-{d}-merge-{d}-{d}.run.tmp",
                .{ scratch_dir, nonce, pass, merged_paths.items.len },
            );
            defer if (output_path) |path| {
                std.Io.Dir.cwd().deleteFile(io, path) catch {};
                allocator.free(path);
            };
            try mergeMigrationEdgeRunGroup(allocator, io, run_paths.items[start..end], output_path.?);
            merged_paths.appendAssumeCapacity(output_path.?);
            output_path = null;
            start = end;
        }
        for (run_paths.items) |path| {
            std.Io.Dir.cwd().deleteFile(io, path) catch {};
            allocator.free(path);
        }
        run_paths.deinit(allocator);
        run_paths.* = merged_paths;
    }
}

const MigrationEdgeSpool = struct {
    allocator: std.mem.Allocator,
    io: std.Io,
    run_paths: [][]u8,
    record_count: u64,

    fn deinit(self: *MigrationEdgeSpool) void {
        for (self.run_paths) |path| {
            std.Io.Dir.cwd().deleteFile(self.io, path) catch {};
            self.allocator.free(path);
        }
        self.allocator.free(self.run_paths);
        self.* = undefined;
    }
};

const MigrationEdgeSpoolBuilder = struct {
    allocator: std.mem.Allocator,
    io: std.Io,
    scratch_dir: []const u8,
    nonce: u64,
    records: std.ArrayList(storage.EdgeIndexRecord) = .empty,
    run_paths: std.ArrayList([]u8) = .empty,
    record_count: u64 = 0,
    active: bool = true,

    fn init(allocator: std.mem.Allocator, io: std.Io, scratch_dir: []const u8) !MigrationEdgeSpoolBuilder {
        var out = MigrationEdgeSpoolBuilder{
            .allocator = allocator,
            .io = io,
            .scratch_dir = scratch_dir,
            .nonce = export_temp_nonce.fetchAdd(1, .monotonic),
        };
        errdefer out.deinit();
        try out.records.ensureTotalCapacityPrecise(allocator, migration_edge_run_chunk_records);
        return out;
    }

    fn deinit(self: *MigrationEdgeSpoolBuilder) void {
        self.records.deinit(self.allocator);
        if (self.active) {
            for (self.run_paths.items) |path| std.Io.Dir.cwd().deleteFile(self.io, path) catch {};
        }
        for (self.run_paths.items) |path| self.allocator.free(path);
        self.run_paths.deinit(self.allocator);
        self.* = undefined;
    }

    fn append(self: *MigrationEdgeSpoolBuilder, record: storage.EdgeIndexRecord) !void {
        if (!self.active) return error.InvalidRecord;
        try self.records.append(self.allocator, record);
        self.record_count = std.math.add(u64, self.record_count, 1) catch return error.RecordTooLarge;
        if (self.records.items.len >= migration_edge_run_chunk_records) try self.flushRun();
    }

    fn flushRun(self: *MigrationEdgeSpoolBuilder) !void {
        if (self.records.items.len == 0) return;
        if (self.run_paths.items.len >= migration_edge_max_runs) return error.SchemaMigrationEdgeRunLimitExceeded;
        std.mem.sort(storage.EdgeIndexRecord, self.records.items, {}, migrationEdgeRecordLessThan);
        var previous_edge_id: u64 = 0;
        for (self.records.items) |record| {
            if (record.edge_id <= previous_edge_id) return error.InvalidRecord;
            previous_edge_id = record.edge_id;
        }
        const run_path = try std.fmt.allocPrint(
            self.allocator,
            "{s}/.schema-edge-{d}-{d}.run.tmp",
            .{ self.scratch_dir, self.nonce, self.run_paths.items.len },
        );
        var keep_path = false;
        errdefer if (!keep_path) {
            std.Io.Dir.cwd().deleteFile(self.io, run_path) catch {};
            self.allocator.free(run_path);
        };
        var file = try std.Io.Dir.cwd().createFile(self.io, run_path, .{ .read = true, .truncate = true, .exclusive = true });
        defer file.close(self.io);
        var writer = try MigrationEdgeRunWriter.init(self.allocator, self.io, file);
        defer writer.deinit();
        for (self.records.items) |record| try writer.append(record);
        try writer.flush();
        try self.run_paths.append(self.allocator, run_path);
        keep_path = true;
        self.records.clearRetainingCapacity();
    }

    fn finish(self: *MigrationEdgeSpoolBuilder) !MigrationEdgeSpool {
        if (!self.active) return error.InvalidRecord;
        try self.flushRun();
        try coalesceMigrationEdgeRuns(self.allocator, self.io, self.scratch_dir, self.nonce, &self.run_paths);
        const run_paths = try self.run_paths.toOwnedSlice(self.allocator);
        self.run_paths = .empty;
        self.active = false;
        return .{
            .allocator = self.allocator,
            .io = self.io,
            .run_paths = run_paths,
            .record_count = self.record_count,
        };
    }
};

const MigrationEdgeStream = struct {
    allocator: std.mem.Allocator,
    readers: std.ArrayList(MigrationEdgeRunReader) = .empty,
    queue: std.PriorityQueue(MigrationEdgeQueueEntry, void, compareMigrationEdgeQueueEntry),
    expected_count: u64,
    seen: u64 = 0,
    previous_edge_id: u64 = 0,

    fn init(spool: *const MigrationEdgeSpool) !MigrationEdgeStream {
        if (spool.run_paths.len > migration_edge_merge_fan_in) return error.InvalidRecord;
        var out = MigrationEdgeStream{
            .allocator = spool.allocator,
            .queue = std.PriorityQueue(MigrationEdgeQueueEntry, void, compareMigrationEdgeQueueEntry).initContext({}),
            .expected_count = spool.record_count,
        };
        errdefer out.deinit();
        try out.readers.ensureTotalCapacityPrecise(out.allocator, spool.run_paths.len);
        try out.queue.ensureTotalCapacityPrecise(out.allocator, spool.run_paths.len);
        for (spool.run_paths) |path| {
            const run_index = out.readers.items.len;
            out.readers.appendAssumeCapacity(try MigrationEdgeRunReader.init(out.allocator, spool.io, path));
            const first = (try out.readers.items[run_index].next()) orelse return error.InvalidRecord;
            try out.queue.push(out.allocator, .{ .run_index = run_index, .record = first });
        }
        if ((spool.record_count == 0) != (spool.run_paths.len == 0)) return error.InvalidRecord;
        return out;
    }

    fn deinit(self: *MigrationEdgeStream) void {
        for (self.readers.items) |*reader| reader.deinit();
        self.readers.deinit(self.allocator);
        self.queue.deinit(self.allocator);
        self.* = undefined;
    }

    fn next(self: *MigrationEdgeStream) !?storage.EdgeIndexRecord {
        const entry = self.queue.pop() orelse {
            if (self.seen != self.expected_count) return error.InvalidRecord;
            return null;
        };
        if (entry.record.edge_id <= self.previous_edge_id) return error.InvalidRecord;
        self.previous_edge_id = entry.record.edge_id;
        self.seen = std.math.add(u64, self.seen, 1) catch return error.RecordTooLarge;
        if (self.seen > self.expected_count) return error.InvalidRecord;
        if (try self.readers.items[entry.run_index].next()) |next_record| {
            try self.queue.push(self.allocator, .{ .run_index = entry.run_index, .record = next_record });
        }
        return entry.record;
    }
};

const MigrationTargetPropertySpoolBuilder = struct {
    inner: MigrationPropertySpoolBuilder,
    nonce: u64,
    current_owner_kind: u8 = 0,
    current_owner_id: u64 = 0,
    current_owner_keys: std.AutoHashMap(u64, void),
    active: bool = true,

    fn init(
        allocator: std.mem.Allocator,
        io: std.Io,
        scratch_dir: []const u8,
        node_keys: *const MigrationPropertyKeys,
        edge_keys: *const MigrationPropertyKeys,
    ) !MigrationTargetPropertySpoolBuilder {
        const nonce = export_temp_nonce.fetchAdd(1, .monotonic);
        const values_path = try std.fmt.allocPrint(allocator, "{s}/.schema-target-property-{d}.values.tmp", .{ scratch_dir, nonce });
        var path_owned_by_out = false;
        errdefer if (!path_owned_by_out) allocator.free(values_path);
        var values_file = try std.Io.Dir.cwd().createFile(io, values_path, .{ .read = true, .truncate = true, .exclusive = true });
        var file_owned_by_out = false;
        errdefer if (!file_owned_by_out) values_file.close(io);
        var out = MigrationTargetPropertySpoolBuilder{
            .inner = .{
                .allocator = allocator,
                .io = io,
                .scratch_dir = scratch_dir,
                .nonce = nonce,
                .node_keys = node_keys,
                .edge_keys = edge_keys,
                // Target writes have already been selected and validated by
                // the migrator.  Do not silently discard a legal historical
                // key merely because it is absent from the current catalog.
                .filter_keys = false,
                .sort_order = .canonical_payload,
                .values_path = values_path,
                .values_file = values_file,
            },
            .nonce = nonce,
            .current_owner_keys = std.AutoHashMap(u64, void).init(allocator),
        };
        path_owned_by_out = true;
        file_owned_by_out = true;
        errdefer out.deinit();
        try out.inner.values_buffer.ensureTotalCapacityPrecise(allocator, migration_property_value_buffer_bytes);
        try out.inner.records.ensureTotalCapacityPrecise(allocator, migration_property_run_chunk_records);
        return out;
    }

    fn deinit(self: *MigrationTargetPropertySpoolBuilder) void {
        if (self.active) self.inner.deinit(false);
        self.current_owner_keys.deinit();
        self.* = undefined;
    }

    fn appendBatch(self: *MigrationTargetPropertySpoolBuilder, writes: []const storage.PropertyPayloadWrite) !void {
        for (writes) |write| {
            const key_hash = storage.propertyKeyHashForLookup(write.key);
            if (!migrationPropertyKeyValid(write.key)) return error.InvalidRecord;
            try self.appendValue(write.owner, key_hash, write.value);
        }
    }

    fn appendValue(
        self: *MigrationTargetPropertySpoolBuilder,
        owner: storage.PropertyOwner,
        key_hash: u64,
        value: storage.PropertyPayloadValue,
    ) !void {
        const owner_kind: u8 = switch (owner) {
            .node => 1,
            .edge => 2,
        };
        const owner_id: u64 = switch (owner) {
            .node => |id| id.toInt(),
            .edge => |id| id.toInt(),
        };
        if (owner_kind != self.current_owner_kind or owner_id != self.current_owner_id) {
            if (self.current_owner_kind != 0 and
                (owner_kind < self.current_owner_kind or
                    (owner_kind == self.current_owner_kind and owner_id <= self.current_owner_id))) return error.InvalidRecord;
            self.current_owner_kind = owner_kind;
            self.current_owner_id = owner_id;
            self.current_owner_keys.clearRetainingCapacity();
        }
        const key_entry = try self.current_owner_keys.getOrPut(key_hash);
        if (key_entry.found_existing) return error.InvalidRecord;
        const layer_entry: storage.PropertySnapshotLayerEntry = switch (value) {
            .string => |string_value| .{
                .owner = owner,
                .key_hash = key_hash,
                .version = storage.propertyValueHashForStorage(string_value),
                .value_kind = .string,
                .string_value = string_value,
            },
            .uint => |uint_value| .{
                .owner = owner,
                .key_hash = key_hash,
                .version = uint_value,
                .value_kind = .uint,
                .uint_value = uint_value,
            },
        };
        try MigrationPropertySpoolBuilder.appendLayer(&self.inner, layer_entry);
    }

    fn finish(self: *MigrationTargetPropertySpoolBuilder) !MigrationPropertySpool {
        if (!self.active) return error.InvalidRecord;
        try self.inner.flushValues();
        try self.inner.flushRun();
        try coalesceMigrationPropertyRuns(
            self.inner.allocator,
            self.inner.io,
            self.inner.scratch_dir,
            self.nonce,
            self.inner.sort_order,
            &self.inner.run_paths,
        );
        const empty_values_path = try self.inner.allocator.dupe(u8, "");
        errdefer self.inner.allocator.free(empty_values_path);
        const run_paths = try self.inner.run_paths.toOwnedSlice(self.inner.allocator);
        self.inner.run_paths = .empty;
        const values_path = self.inner.values_path;
        self.inner.values_path = empty_values_path;
        const result = MigrationPropertySpool{
            .allocator = self.inner.allocator,
            .io = self.inner.io,
            .values_path = values_path,
            .run_paths = run_paths,
            .sort_order = self.inner.sort_order,
            .record_count = self.inner.record_count,
        };
        self.inner.deinit(true);
        self.active = false;
        return result;
    }
};

const MigrationPropertyRunReader = struct {
    allocator: std.mem.Allocator,
    io: std.Io,
    file: std.Io.File,
    remaining: u64,
    file_offset: u64 = 0,
    buffer: []u8,
    cursor: usize = 0,
    len: usize = 0,

    fn init(allocator: std.mem.Allocator, io: std.Io, path: []const u8) !MigrationPropertyRunReader {
        var file = try std.Io.Dir.cwd().openFile(io, path, .{ .allow_directory = false });
        errdefer file.close(io);
        const stat = try file.stat(io);
        if (stat.kind != .file or stat.size % migration_property_spool_record_len != 0) return error.InvalidRecord;
        const buffer = try allocator.alloc(u8, migration_property_reader_buffer_bytes);
        errdefer allocator.free(buffer);
        return .{
            .allocator = allocator,
            .io = io,
            .file = file,
            .remaining = stat.size / migration_property_spool_record_len,
            .buffer = buffer,
        };
    }

    fn deinit(self: *MigrationPropertyRunReader) void {
        self.allocator.free(self.buffer);
        self.file.close(self.io);
        self.* = undefined;
    }

    fn refill(self: *MigrationPropertyRunReader) !void {
        const n = try self.file.readPositionalAll(self.io, self.buffer, self.file_offset);
        if (n == 0 or n % migration_property_spool_record_len != 0) return error.InvalidRecord;
        self.file_offset = std.math.add(u64, self.file_offset, n) catch return error.InvalidRecord;
        self.cursor = 0;
        self.len = n;
    }

    fn next(self: *MigrationPropertyRunReader) !?MigrationPropertySpoolRecord {
        if (self.remaining == 0) return null;
        if (self.cursor == self.len) try self.refill();
        if (self.len - self.cursor < migration_property_spool_record_len) return error.InvalidRecord;
        const bytes = self.buffer[self.cursor..][0..migration_property_spool_record_len];
        self.cursor += migration_property_spool_record_len;
        self.remaining -= 1;
        return try MigrationPropertySpoolRecord.decode(bytes);
    }
};

const MigrationPropertyQueueEntry = struct {
    run_index: usize,
    record: MigrationPropertySpoolRecord,
};

fn compareMigrationPropertyQueueEntry(order: MigrationPropertySortOrder, lhs: MigrationPropertyQueueEntry, rhs: MigrationPropertyQueueEntry) std.math.Order {
    if (migrationPropertySpoolRecordLessThan(order, lhs.record, rhs.record)) return .lt;
    if (migrationPropertySpoolRecordLessThan(order, rhs.record, lhs.record)) return .gt;
    return std.math.order(lhs.run_index, rhs.run_index);
}

const MigrationPropertyRunWriter = struct {
    allocator: std.mem.Allocator,
    io: std.Io,
    file: std.Io.File,
    offset: u64 = 0,
    buffer: std.ArrayList(u8) = .empty,

    fn init(allocator: std.mem.Allocator, io: std.Io, file: std.Io.File) !MigrationPropertyRunWriter {
        var out = MigrationPropertyRunWriter{ .allocator = allocator, .io = io, .file = file };
        errdefer out.buffer.deinit(allocator);
        try out.buffer.ensureTotalCapacityPrecise(allocator, migration_property_run_write_buffer_bytes);
        return out;
    }

    fn deinit(self: *MigrationPropertyRunWriter) void {
        self.buffer.deinit(self.allocator);
        self.* = undefined;
    }

    fn append(self: *MigrationPropertyRunWriter, record: MigrationPropertySpoolRecord) !void {
        if (migration_property_spool_record_len > migration_property_run_write_buffer_bytes - self.buffer.items.len) try self.flush();
        var bytes: [migration_property_spool_record_len]u8 = undefined;
        try record.encode(&bytes);
        try self.buffer.appendSlice(self.allocator, &bytes);
    }

    fn flush(self: *MigrationPropertyRunWriter) !void {
        if (self.buffer.items.len == 0) return;
        try self.file.writePositionalAll(self.io, self.buffer.items, self.offset);
        self.offset = std.math.add(u64, self.offset, self.buffer.items.len) catch return error.RecordTooLarge;
        self.buffer.clearRetainingCapacity();
    }
};

fn mergeMigrationPropertyRunGroup(
    allocator: std.mem.Allocator,
    io: std.Io,
    input_paths: []const []u8,
    output_path: []const u8,
    sort_order: MigrationPropertySortOrder,
) !void {
    if (input_paths.len == 0 or input_paths.len > migration_property_merge_fan_in) return error.InvalidRecord;
    var readers = std.ArrayList(MigrationPropertyRunReader).empty;
    defer {
        for (readers.items) |*reader| reader.deinit();
        readers.deinit(allocator);
    }
    var queue = std.PriorityQueue(MigrationPropertyQueueEntry, MigrationPropertySortOrder, compareMigrationPropertyQueueEntry).initContext(sort_order);
    defer queue.deinit(allocator);
    try readers.ensureTotalCapacityPrecise(allocator, input_paths.len);
    try queue.ensureTotalCapacityPrecise(allocator, input_paths.len);
    for (input_paths) |path| {
        const run_index = readers.items.len;
        readers.appendAssumeCapacity(try MigrationPropertyRunReader.init(allocator, io, path));
        if (try readers.items[run_index].next()) |record| {
            try queue.push(allocator, .{ .run_index = run_index, .record = record });
        }
    }

    var output_file = try std.Io.Dir.cwd().createFile(io, output_path, .{ .read = true, .truncate = true, .exclusive = true });
    defer output_file.close(io);
    var writer = try MigrationPropertyRunWriter.init(allocator, io, output_file);
    defer writer.deinit();
    var previous: ?MigrationPropertySpoolRecord = null;
    while (queue.pop()) |entry| {
        if (previous) |prior| {
            if (migrationPropertySpoolRecordLessThan(sort_order, entry.record, prior)) return error.InvalidRecord;
        }
        try writer.append(entry.record);
        previous = entry.record;
        if (try readers.items[entry.run_index].next()) |next_record| {
            try queue.push(allocator, .{ .run_index = entry.run_index, .record = next_record });
        }
    }
    try writer.flush();
}

fn coalesceMigrationPropertyRuns(
    allocator: std.mem.Allocator,
    io: std.Io,
    scratch_dir: []const u8,
    nonce: u64,
    sort_order: MigrationPropertySortOrder,
    run_paths: *std.ArrayList([]u8),
) !void {
    var pass: usize = 0;
    while (run_paths.items.len > migration_property_merge_fan_in) : (pass += 1) {
        var merged_paths = std.ArrayList([]u8).empty;
        errdefer {
            for (merged_paths.items) |path| {
                std.Io.Dir.cwd().deleteFile(io, path) catch {};
                allocator.free(path);
            }
            merged_paths.deinit(allocator);
        }
        const output_count = std.math.divCeil(usize, run_paths.items.len, migration_property_merge_fan_in) catch return error.InvalidRecord;
        try merged_paths.ensureTotalCapacityPrecise(allocator, output_count);
        var start: usize = 0;
        while (start < run_paths.items.len) {
            const end = start + @min(migration_property_merge_fan_in, run_paths.items.len - start);
            var output_path: ?[]u8 = try std.fmt.allocPrint(
                allocator,
                "{s}/.schema-property-{d}-merge-{d}-{d}.run.tmp",
                .{ scratch_dir, nonce, pass, merged_paths.items.len },
            );
            defer if (output_path) |path| {
                std.Io.Dir.cwd().deleteFile(io, path) catch {};
                allocator.free(path);
            };
            try mergeMigrationPropertyRunGroup(allocator, io, run_paths.items[start..end], output_path.?, sort_order);
            merged_paths.appendAssumeCapacity(output_path.?);
            output_path = null;
            start = end;
        }
        for (run_paths.items) |path| {
            std.Io.Dir.cwd().deleteFile(io, path) catch {};
            allocator.free(path);
        }
        run_paths.deinit(allocator);
        run_paths.* = merged_paths;
    }
}

fn sortedU64Contains(values: []const u64, target: u64) bool {
    var low: usize = 0;
    var high: usize = values.len;
    while (low < high) {
        const mid = low + (high - low) / 2;
        if (values[mid] < target) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    return low < values.len and values[low] == target;
}

const MigrationEffectiveProperty = struct {
    owner_kind: u8,
    owner_id: u64,
    key_hash: u64,
    value_kind: storage.PropertySnapshotValueKind,
    string_value: []const u8 = &.{},
    uint_value: u64 = 0,

    fn deinit(self: *MigrationEffectiveProperty, allocator: std.mem.Allocator) void {
        if (self.value_kind == .string) allocator.free(self.string_value);
        self.* = undefined;
    }
};

const MigrationPropertyStream = struct {
    allocator: std.mem.Allocator,
    io: std.Io,
    values_file: std.Io.File,
    values_size: u64,
    readers: std.ArrayList(MigrationPropertyRunReader) = .empty,
    sort_order: MigrationPropertySortOrder,
    queue: std.PriorityQueue(MigrationPropertyQueueEntry, MigrationPropertySortOrder, compareMigrationPropertyQueueEntry),
    physical_pending: ?MigrationPropertySpoolRecord = null,
    effective_pending: ?MigrationEffectiveProperty = null,
    canonical_borrowed: ?MigrationEffectiveProperty = null,

    fn init(spool: *const MigrationPropertySpool) !MigrationPropertyStream {
        var values_file = try std.Io.Dir.cwd().openFile(spool.io, spool.values_path, .{ .allow_directory = false });
        var values_file_owned = true;
        errdefer if (values_file_owned) values_file.close(spool.io);
        const values_stat = try values_file.stat(spool.io);
        if (values_stat.kind != .file) return error.InvalidRecord;
        var out = MigrationPropertyStream{
            .allocator = spool.allocator,
            .io = spool.io,
            .values_file = values_file,
            .values_size = values_stat.size,
            .sort_order = spool.sort_order,
            .queue = std.PriorityQueue(MigrationPropertyQueueEntry, MigrationPropertySortOrder, compareMigrationPropertyQueueEntry).initContext(spool.sort_order),
        };
        values_file_owned = false;
        errdefer out.deinit();
        try out.readers.ensureTotalCapacityPrecise(out.allocator, spool.run_paths.len);
        try out.queue.ensureTotalCapacityPrecise(out.allocator, spool.run_paths.len);
        for (spool.run_paths) |path| {
            const run_index = out.readers.items.len;
            out.readers.appendAssumeCapacity(try MigrationPropertyRunReader.init(out.allocator, out.io, path));
            if (try out.readers.items[run_index].next()) |record| {
                try out.queue.push(out.allocator, .{ .run_index = run_index, .record = record });
            }
        }
        return out;
    }

    fn deinit(self: *MigrationPropertyStream) void {
        if (self.effective_pending) |*entry| entry.deinit(self.allocator);
        if (self.canonical_borrowed) |*entry| entry.deinit(self.allocator);
        for (self.readers.items) |*reader| reader.deinit();
        self.readers.deinit(self.allocator);
        self.queue.deinit(self.allocator);
        self.values_file.close(self.io);
        self.* = undefined;
    }

    fn nextPhysical(self: *MigrationPropertyStream) !?MigrationPropertySpoolRecord {
        if (self.physical_pending) |record| {
            self.physical_pending = null;
            return record;
        }
        const entry = self.queue.pop() orelse return null;
        if (try self.readers.items[entry.run_index].next()) |next_record| {
            try self.queue.push(self.allocator, .{ .run_index = entry.run_index, .record = next_record });
        }
        return entry.record;
    }

    fn readEffectiveValue(self: *MigrationPropertyStream, record: MigrationPropertySpoolRecord) !MigrationEffectiveProperty {
        var out = MigrationEffectiveProperty{
            .owner_kind = record.owner_kind,
            .owner_id = record.owner_id,
            .key_hash = record.key_hash,
            .value_kind = record.value_kind,
            .uint_value = record.uint_value,
        };
        if (record.value_kind == .string) {
            const end = std.math.add(u64, record.value_offset, record.value_len) catch return error.InvalidRecord;
            if (end > self.values_size) return error.InvalidRecord;
            const value = try self.allocator.alloc(u8, record.value_len);
            errdefer self.allocator.free(value);
            const n = try self.values_file.readPositionalAll(self.io, value, record.value_offset);
            if (n != value.len) return error.InvalidRecord;
            out.string_value = value;
        }
        return out;
    }

    fn nextEffectiveUncached(self: *MigrationPropertyStream) !?MigrationEffectiveProperty {
        var latest = (try self.nextPhysical()) orelse return null;
        while (try self.nextPhysical()) |candidate| {
            const same_key = candidate.owner_kind == latest.owner_kind and
                candidate.owner_id == latest.owner_id and
                candidate.key_hash == latest.key_hash;
            if (!same_key) {
                self.physical_pending = candidate;
                break;
            }
            if (candidate.version == latest.version) return error.InvalidRecord;
            if (candidate.version < latest.version) return error.InvalidRecord;
            latest = candidate;
        }
        return try self.readEffectiveValue(latest);
    }

    fn nextSortedPayload(raw_context: *anyopaque) anyerror!?storage.SortedPropertyPayloadEntry {
        const self: *MigrationPropertyStream = @ptrCast(@alignCast(raw_context));
        if (self.sort_order != .canonical_payload) return error.InvalidRecord;
        if (self.canonical_borrowed) |*previous| previous.deinit(self.allocator);
        self.canonical_borrowed = null;
        const record = (try self.nextPhysical()) orelse return null;
        var value = try self.readEffectiveValue(record);
        errdefer value.deinit(self.allocator);
        switch (value.value_kind) {
            .string => if (storage.propertyValueHashForStorage(value.string_value) != record.version) return error.InvalidRecord,
            .uint => if (value.uint_value != record.version) return error.InvalidRecord,
        }
        self.canonical_borrowed = value;
        return .{
            .owner = if (value.owner_kind == 1)
                .{ .node = .fromInt(value.owner_id) }
            else if (value.owner_kind == 2)
                .{ .edge = .fromInt(value.owner_id) }
            else
                return error.InvalidRecord,
            .key_hash = value.key_hash,
            .value = switch (value.value_kind) {
                .string => .{ .string = value.string_value },
                .uint => .{ .uint = value.uint_value },
            },
        };
    }

    fn ensureEffectivePending(self: *MigrationPropertyStream) !void {
        if (self.effective_pending == null) self.effective_pending = try self.nextEffectiveUncached();
    }

    fn snapshotForOwners(self: *MigrationPropertyStream, owner_kind: u8, owner_ids: []const u64) !storage.PropertySnapshot {
        if (self.sort_order != .effective_owner) return error.InvalidRecord;
        var out = std.ArrayList(storage.PropertySnapshotEntry).empty;
        errdefer {
            for (out.items) |entry| if (entry.value_kind == .string) self.allocator.free(entry.string_value);
            out.deinit(self.allocator);
        }
        if (owner_ids.len == 0) return .{ .entries = try out.toOwnedSlice(self.allocator) };
        for (owner_ids, 0..) |owner_id, index| {
            if (owner_id == 0 or owner_id == std.math.maxInt(u64) or (index != 0 and owner_ids[index - 1] >= owner_id)) return error.InvalidRecord;
        }
        while (true) {
            try self.ensureEffectivePending();
            if (self.effective_pending == null) break;
            const entry = &self.effective_pending.?;
            if (entry.owner_kind > owner_kind or
                (entry.owner_kind == owner_kind and entry.owner_id > owner_ids[owner_ids.len - 1])) break;
            var keep = false;
            if (entry.owner_kind == owner_kind) {
                keep = sortedU64Contains(owner_ids, entry.owner_id);
            }
            var owned = entry.*;
            self.effective_pending = null;
            if (!keep) {
                owned.deinit(self.allocator);
                continue;
            }
            try out.append(self.allocator, .{
                .owner = if (owner_kind == 1) .{ .node = .fromInt(owned.owner_id) } else .{ .edge = .fromInt(owned.owner_id) },
                .key_hash = owned.key_hash,
                .value_kind = owned.value_kind,
                .string_len = if (owned.value_kind == .string) @intCast(owned.string_value.len) else 0,
                .string_value = owned.string_value,
                .uint_value = owned.uint_value,
            });
            if (owned.value_kind == .string) owned.string_value = &.{};
        }
        return .{ .entries = try out.toOwnedSlice(self.allocator) };
    }

    fn finish(self: *MigrationPropertyStream) !void {
        while (true) {
            try self.ensureEffectivePending();
            if (self.effective_pending == null) return;
            var entry = self.effective_pending.?;
            self.effective_pending = null;
            entry.deinit(self.allocator);
        }
    }
};

fn migrationLifecycleFields(
    source_properties: *const MigrationPropertyLookup,
    node_id: core.NodeId,
) task.StatusSnapshot.LifecycleFields {
    var fields: task.StatusSnapshot.LifecycleFields = .{};
    const owner: storage.PropertyOwner = .{ .node = node_id };
    if (source_properties.get(owner, task.status_property)) |entry| {
        if (entry.value_kind == .string) fields.stored_status_raw = entry.string_value else fields.invalid_value_type = true;
    }
    if (source_properties.get(owner, task.claimed_by_property)) |entry| {
        if (entry.value_kind == .string) fields.claimed_by = entry.string_value else fields.invalid_value_type = true;
    }
    if (source_properties.get(owner, task.claim_expires_ns_property)) |entry| {
        if (entry.value_kind == .uint) fields.claim_expires_ns = entry.uint_value else fields.invalid_value_type = true;
    }
    if (source_properties.get(owner, "task_recorded_ns")) |entry| {
        if (entry.value_kind == .uint) fields.task_recorded_ns = entry.uint_value else fields.invalid_value_type = true;
    }
    if (source_properties.get(owner, "task_created_ns")) |entry| {
        if (entry.value_kind == .uint) fields.task_created_ns = entry.uint_value else fields.invalid_value_type = true;
    }
    if (source_properties.get(owner, "task_completed_ns")) |entry| {
        if (entry.value_kind == .uint) fields.task_completed_ns = entry.uint_value else fields.invalid_value_type = true;
    }
    return fields;
}

const MigrationLifecycleFields = struct {
    fields: task.StatusSnapshot.LifecycleFields,
    owned_status: ?[]u8 = null,
    owned_claimed_by: ?[]u8 = null,

    fn deinit(self: *MigrationLifecycleFields, allocator: std.mem.Allocator) void {
        if (self.owned_status) |value| allocator.free(value);
        if (self.owned_claimed_by) |value| allocator.free(value);
        self.* = undefined;
    }
};

fn migrationLifecycleFieldsWithLegacyProps(
    allocator: std.mem.Allocator,
    source_properties: *const MigrationPropertyLookup,
    node_id: core.NodeId,
    props_json: ?[]const u8,
    strict: bool,
) !MigrationLifecycleFields {
    var result = MigrationLifecycleFields{ .fields = migrationLifecycleFields(source_properties, node_id) };
    errdefer result.deinit(allocator);
    const json = props_json orelse return result;
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, json, .{
        .ignore_unknown_fields = true,
        .allocate = .alloc_always,
    }) catch |err| {
        if (strict) return err;
        return result;
    };
    defer parsed.deinit();
    if (parsed.value != .object) return result;
    const object = parsed.value.object;
    const owner: storage.PropertyOwner = .{ .node = node_id };

    if (source_properties.get(owner, task.status_property) == null) {
        if (object.get(task.status_property)) |value| switch (value) {
            .string => |text| {
                result.owned_status = try allocator.dupe(u8, text);
                result.fields.stored_status_raw = result.owned_status.?;
            },
            else => result.fields.invalid_value_type = true,
        };
    }
    if (source_properties.get(owner, task.claimed_by_property) == null) {
        if (object.get(task.claimed_by_property)) |value| switch (value) {
            .string => |text| {
                result.owned_claimed_by = try allocator.dupe(u8, text);
                result.fields.claimed_by = result.owned_claimed_by.?;
            },
            else => result.fields.invalid_value_type = true,
        };
    }
    inline for (.{
        task.claim_expires_ns_property,
        "task_recorded_ns",
        "task_created_ns",
        "task_completed_ns",
    }) |key| {
        if (source_properties.get(owner, key) == null) {
            if (object.get(key)) |value| {
                const parsed_uint: ?u64 = switch (value) {
                    .integer => |integer| if (integer >= 0) @intCast(integer) else blk: {
                        result.fields.invalid_value_type = true;
                        break :blk null;
                    },
                    else => blk: {
                        result.fields.invalid_value_type = true;
                        break :blk null;
                    },
                };
                if (parsed_uint) |uint_value| {
                    if (comptime std.mem.eql(u8, key, "claim_expires_ns")) {
                        result.fields.claim_expires_ns = uint_value;
                    } else if (comptime std.mem.eql(u8, key, "task_recorded_ns")) {
                        result.fields.task_recorded_ns = uint_value;
                    } else if (comptime std.mem.eql(u8, key, "task_created_ns")) {
                        result.fields.task_created_ns = uint_value;
                    } else if (comptime std.mem.eql(u8, key, "task_completed_ns")) {
                        result.fields.task_completed_ns = uint_value;
                    } else comptime unreachable;
                }
            }
        }
    }
    return result;
}

fn taskStatusForMigration(
    node: storage.StoredNode,
    lifecycle: task.StatusSnapshot.LifecycleFields,
    now_ns: u64,
) !?task.Status {
    if (node.kind == .task) {
        // The explicit COW migration is also the repair boundary for the
        // pre-v3 crash window where completion time reached the legacy
        // property overlay but terminal status did not. Runtime reads remain
        // fail-closed; migration deliberately drops that non-authoritative
        // completion field and derives only the lease-backed effective state.
        return try task.effectiveStatusForLifecycleFields(lifecycle, now_ns, .migration_repair_nonterminal_completion);
    }
    if (node.kind == .verification or node.kind == .fix) {
        if (task.lifecycleFieldsRepresentLegacyClosedTask(lifecycle)) return .completed;
    }
    return null;
}

fn appendCatalogProfileLabel(allocator: std.mem.Allocator, cat: *catalog_mod.Catalog, label: []const u8) !void {
    for (cat.profiles.items) |existing| {
        if (std.mem.eql(u8, existing, label)) return;
    }
    const owned = try allocator.dupe(u8, label);
    errdefer allocator.free(owned);
    try cat.profiles.append(allocator, owned);
}

fn migrationCatalog(
    allocator: std.mem.Allocator,
    source: storage.Store,
    profiles: []const u8,
    profiles_explicit: bool,
    task_status_v1: bool,
) !catalog_mod.Catalog {
    var source_catalog = try source.readCatalog();
    const source_is_kernel_only = if (source_catalog) |existing|
        existing.profiles.items.len == 0 and existing.registry.nodeTypeCount() == 2 and existing.registry.relationTypeCount() == 2
    else
        false;
    var cat = if (source_catalog != null and !source_is_kernel_only)
        source_catalog.?
    else blk: {
        if (source_catalog) |*existing| existing.deinit();
        source_catalog = null;
        var registry = schema.Registry.init(allocator);
        errdefer registry.deinit();
        try registry.addKernelTypes();
        try addBuiltinProfilesFromCsvForSchemaVersion(&registry, profiles, if (task_status_v1) 3 else 2);
        var created = try catalog_mod.Catalog.fromRegistry(allocator, registry);
        var profile_it = std.mem.tokenizeScalar(u8, profiles, ',');
        while (profile_it.next()) |raw| {
            const label = std.mem.trim(u8, raw, " \t\r\n");
            const profile = schema.BuiltinProfile.fromLabel(label) orelse continue;
            try appendCatalogProfileLabel(allocator, &created, profile.label());
        }
        break :blk created;
    };
    errdefer cat.deinit();

    if (!source_is_kernel_only and profiles_explicit and !catalogProfilesMatchCsv(cat, profiles)) return error.Unsupported;

    if (task_status_v1) {
        // Revision is a schema generation, not a count of migration command
        // invocations. Snapshot the catalog before the narrow lifecycle
        // upgrade so a second task-status-v1 COW migration is semantically
        // idempotent and does not manufacture a new revision.
        const before = try catalog_mod.encodeCatalog(allocator, cat);
        defer allocator.free(before);
        const task_type = @intFromEnum(core.NodeKind.task);
        if (cat.registry.nodeTypeNameById(task_type)) |name| {
            if (!std.mem.eql(u8, name, "task")) return error.InvalidRecord;
        } else {
            if (cat.registry.findNodeType("task") != null) return error.InvalidRecord;
            try cat.registry.addNodeType("task", task_type, &.{schema.kernel_node_type_id});
        }
        try cat.registry.setTaskLifecycleProperties();
        const after = try catalog_mod.encodeCatalog(allocator, cat);
        defer allocator.free(after);
        if (!std.mem.eql(u8, before, after)) {
            cat.revision = std.math.add(u32, cat.revision, 1) catch return error.RecordTooLarge;
        }
    }
    return cat;
}

fn catalogProfilesMatchCsv(cat: catalog_mod.Catalog, profiles: []const u8) bool {
    var requested_count: usize = 0;
    var profile_it = std.mem.tokenizeScalar(u8, profiles, ',');
    while (profile_it.next()) |raw| {
        const label = std.mem.trim(u8, raw, " \t\r\n");
        const profile = schema.BuiltinProfile.fromLabel(label) orelse return false;
        var found = false;
        for (cat.profiles.items) |existing| {
            if (std.mem.eql(u8, existing, profile.label())) {
                found = true;
                break;
            }
        }
        if (!found) return false;
        requested_count += 1;
    }
    return requested_count == cat.profiles.items.len;
}

fn catalogProfilesCsvAlloc(allocator: std.mem.Allocator, cat: catalog_mod.Catalog) ![]u8 {
    var out = std.ArrayList(u8).empty;
    errdefer out.deinit(allocator);
    for (cat.profiles.items, 0..) |profile, index| {
        if (index != 0) try out.append(allocator, ',');
        try out.appendSlice(allocator, profile);
    }
    return try out.toOwnedSlice(allocator);
}

fn validateMigrateStoreV2PathRelationships(allocator: std.mem.Allocator, io: std.Io, parsed: ParsedMigrateStoreV2Args) !void {
    if (!try existingTinyKgStorePath(allocator, io, parsed.source_path)) return error.FileNotFound;
    if (try pathsOverlapForCopyTarget(allocator, io, parsed.source_path, parsed.target_path)) return error.InvalidFileName;
    if (parsed.backup_path) |backup_path| {
        if (try pathsOverlapForCopyTarget(allocator, io, parsed.source_path, backup_path) or
            try pathsOverlap(allocator, io, parsed.target_path, backup_path))
        {
            return error.InvalidFileName;
        }
    }
}

fn validateMigrateStoreV2Destinations(io: std.Io, parsed: ParsedMigrateStoreV2Args) !void {
    if (!parsed.dry_run and try anyPathExists(io, parsed.target_path)) return error.AlreadyExists;
}

fn validateMigrateStoreV2Paths(allocator: std.mem.Allocator, io: std.Io, parsed: ParsedMigrateStoreV2Args) !void {
    try validateMigrateStoreV2PathRelationships(allocator, io, parsed);
    try validateMigrateStoreV2Destinations(io, parsed);
    if (parsed.backup_path) |backup_path| {
        if (try anyPathExists(io, backup_path)) return error.AlreadyExists;
    }
}

const store_migration_node_batch_limit: usize = 4096;
const store_migration_edge_batch_limit: usize = 8192;

fn migrationLegacyTaskNeedsSchemaOverride(
    source_properties: *const MigrationPropertyLookup,
    node_id: core.NodeId,
) !bool {
    const entry = source_properties.get(.{ .node = node_id }, "schema_type") orelse return true;
    if (entry.value_kind != .string) return error.InvalidRecord;
    return std.mem.eql(u8, entry.string_value, "verification") or std.mem.eql(u8, entry.string_value, "fix");
}

fn processStoreMigrationNodeBatch(
    allocator: std.mem.Allocator,
    source_nodes: []const storage.StoredNode,
    target: ?storage.Store,
    target_catalog: catalog_mod.Catalog,
    property_stream: *MigrationPropertyStream,
    target_property_builder: ?*MigrationTargetPropertySpoolBuilder,
    parsed: ParsedMigrateStoreV2Args,
    migration_now_ns: u64,
    result: *StoreMigrationV2Result,
) !void {
    if (source_nodes.len == 0) return;
    var raw_ids = std.ArrayList(u64).empty;
    defer raw_ids.deinit(allocator);
    try raw_ids.ensureTotalCapacityPrecise(allocator, source_nodes.len);
    for (source_nodes) |node| raw_ids.appendAssumeCapacity(node.id.toInt());
    const snapshot = try property_stream.snapshotForOwners(1, raw_ids.items);
    var source_properties = try MigrationPropertyLookup.initFromSnapshot(allocator, snapshot);
    defer source_properties.deinit();

    var migrated_nodes = std.ArrayList(graph.Node).empty;
    defer {
        for (migrated_nodes.items) |node| allocator.free(node.text);
        migrated_nodes.deinit(allocator);
    }
    try migrated_nodes.ensureTotalCapacityPrecise(allocator, source_nodes.len);
    var property_batch = MigrationPropertyBatch.init(allocator);
    defer property_batch.deinit();

    for (source_nodes) |source_node| {
        var repaired = try repairLegacyNodeTextForMigration(allocator, source_node.text, parsed.strict, result, true);
        var repaired_owned = true;
        defer if (repaired_owned) repaired.deinit(allocator);
        var migration_lifecycle = if (parsed.task_status_v1)
            try migrationLifecycleFieldsWithLegacyProps(
                allocator,
                &source_properties,
                source_node.id,
                repaired.props_json,
                parsed.strict,
            )
        else
            MigrationLifecycleFields{ .fields = .{} };
        defer migration_lifecycle.deinit(allocator);
        const materialized_status = if (parsed.task_status_v1)
            try taskStatusForMigration(source_node, migration_lifecycle.fields, migration_now_ns)
        else
            null;
        const force_task_schema = materialized_status != null and source_node.kind != .task and
            try migrationLegacyTaskNeedsSchemaOverride(&source_properties, source_node.id);
        const migrated_kind: core.NodeKind = if (materialized_status != null) .task else source_node.kind;
        migrated_nodes.appendAssumeCapacity(.{
            .id = source_node.id,
            .kind = migrated_kind,
            .text = repaired.text,
        });
        repaired_owned = false;

        if (materialized_status != null) {
            result.task_statuses_written = std.math.add(u64, result.task_statuses_written, 1) catch return error.RecordTooLarge;
            if (source_node.kind != .task) {
                result.legacy_closed_tasks_converted = std.math.add(u64, result.legacy_closed_tasks_converted, 1) catch return error.RecordTooLarge;
            }
        }
        if (parsed.dry_run) {
            result.legacy_props_extracted += try countLegacyNodePropsTextProperties(
                allocator,
                &source_properties,
                source_node.id,
                repaired.props_json,
                parsed.strict,
                materialized_status != null,
                force_task_schema,
            );
            continue;
        }

        result.node_properties_written += collectKnownNodeProperties(
            &source_properties,
            target_catalog.registry,
            @intFromEnum(migrated_kind),
            source_node.id,
            &property_batch,
            materialized_status != null,
            force_task_schema,
        ) catch return error.MigrationNodePropertyFailed;
        result.node_properties_written += appendLegacyNodePropsTextProperties(
            allocator,
            &source_properties,
            source_node.id,
            repaired.props_json,
            parsed.strict,
            result,
            &property_batch,
            materialized_status != null,
            force_task_schema,
        ) catch return error.MigrationLegacyNodePropsFailed;
        if (materialized_status) |status| {
            property_batch.appendString(.{ .node = source_node.id }, task.status_property, @tagName(status)) catch return error.MigrationPropertyBatchFailed;
            result.node_properties_written += 1;
            const lifecycle_fields = migration_lifecycle.fields;
            if (status.isTerminal()) {
                const completed_ns = lifecycle_fields.task_completed_ns orelse return error.InvalidRecord;
                if (completed_ns == 0) return error.InvalidRecord;
                if (lifecycle_fields.task_created_ns) |created_ns| {
                    if (created_ns == 0 or completed_ns < created_ns) return error.InvalidRecord;
                }
                property_batch.appendUint(.{ .node = source_node.id }, "task_completed_ns", completed_ns) catch return error.MigrationPropertyBatchFailed;
                result.node_properties_written += 1;
            }
            if (lifecycle_fields.claim_expires_ns) |source_expiry| {
                const normalized_expiry = if (status == .claimed) source_expiry else 0;
                property_batch.appendUint(.{ .node = source_node.id }, task.claim_expires_ns_property, normalized_expiry) catch return error.MigrationPropertyBatchFailed;
                result.node_properties_written += 1;
            }
        }
        if (force_task_schema) {
            property_batch.appendString(.{ .node = source_node.id }, "schema_type", "task") catch return error.MigrationPropertyBatchFailed;
            result.node_properties_written += 1;
        }
    }

    if (target) |store| {
        store.appendNodesBatch(migrated_nodes.items) catch return error.MigrationAppendNodesFailed;
        const builder = target_property_builder orelse return error.InvalidRecord;
        builder.appendBatch(property_batch.writes.items) catch return error.MigrationPropertyBatchFailed;
    } else if (target_property_builder != null or !parsed.dry_run) {
        return error.InvalidRecord;
    }
    result.nodes_written = std.math.add(u64, result.nodes_written, migrated_nodes.items.len) catch return error.RecordTooLarge;
}

fn migrateStoreV2Nodes(
    allocator: std.mem.Allocator,
    source: storage.Store,
    target: ?storage.Store,
    target_catalog: catalog_mod.Catalog,
    property_stream: *MigrationPropertyStream,
    target_property_builder: ?*MigrationTargetPropertySpoolBuilder,
    parsed: ParsedMigrateStoreV2Args,
    migration_now_ns: u64,
    result: *StoreMigrationV2Result,
) !void {
    var batch = std.ArrayList(storage.StoredNode).empty;
    defer {
        for (batch.items) |*node| node.deinit(allocator);
        batch.deinit(allocator);
    }
    try batch.ensureTotalCapacityPrecise(allocator, store_migration_node_batch_limit);
    var node_iter = try source.nodeRecordsIterator(null);
    defer node_iter.deinit();
    while (try node_iter.next(allocator)) |stored_node| {
        var node = stored_node;
        result.nodes_scanned = std.math.add(u64, result.nodes_scanned, 1) catch return error.RecordTooLarge;
        if (isDeletedNodeTombstone(node)) {
            result.tombstone_nodes_skipped = std.math.add(u64, result.tombstone_nodes_skipped, 1) catch return error.RecordTooLarge;
            node.deinit(allocator);
            continue;
        }
        batch.appendAssumeCapacity(node);
        if (batch.items.len < store_migration_node_batch_limit) continue;
        try processStoreMigrationNodeBatch(
            allocator,
            batch.items,
            target,
            target_catalog,
            property_stream,
            target_property_builder,
            parsed,
            migration_now_ns,
            result,
        );
        for (batch.items) |*owned| owned.deinit(allocator);
        batch.clearRetainingCapacity();
    }
    if (batch.items.len != 0) {
        try processStoreMigrationNodeBatch(
            allocator,
            batch.items,
            target,
            target_catalog,
            property_stream,
            target_property_builder,
            parsed,
            migration_now_ns,
            result,
        );
        for (batch.items) |*owned| owned.deinit(allocator);
        batch.clearRetainingCapacity();
    }
}

fn sourceMigrationNodeIsLive(
    allocator: std.mem.Allocator,
    view: *const storage.Store.NodeRecordView,
    node_id: core.NodeId,
) !bool {
    const node_ref = (try view.readNodeRefById(node_id)) orelse return false;
    if (node_ref.kind != .edit) return true;
    if (try view.readNodeRefTextBorrowed(node_ref)) |text| {
        return !std.mem.startsWith(u8, text, deleted_node_tombstone_prefix);
    }
    const text = try view.readNodeRefTextAlloc(allocator, node_ref);
    defer allocator.free(text);
    return !std.mem.startsWith(u8, text, deleted_node_tombstone_prefix);
}

fn processStoreMigrationEdgePropertyBatch(
    allocator: std.mem.Allocator,
    edges: []const graph.Edge,
    target_catalog: catalog_mod.Catalog,
    property_stream: *MigrationPropertyStream,
    target_property_builder: *MigrationTargetPropertySpoolBuilder,
    result: *StoreMigrationV2Result,
) !void {
    if (edges.len == 0) return;
    var raw_ids = std.ArrayList(u64).empty;
    defer raw_ids.deinit(allocator);
    try raw_ids.ensureTotalCapacityPrecise(allocator, edges.len);
    for (edges) |edge| raw_ids.appendAssumeCapacity(edge.id.toInt());
    const snapshot = try property_stream.snapshotForOwners(2, raw_ids.items);
    var source_properties = try MigrationPropertyLookup.initFromSnapshot(allocator, snapshot);
    defer source_properties.deinit();

    var property_batch = MigrationPropertyBatch.init(allocator);
    defer property_batch.deinit();
    for (edges) |edge| {
        result.edge_properties_written += collectKnownEdgeProperties(
            &source_properties,
            target_catalog.registry,
            @intFromEnum(edge.rel),
            edge.id,
            null,
            &property_batch,
        ) catch return error.MigrationEdgePropertyFailed;
    }
    target_property_builder.appendBatch(property_batch.writes.items) catch return error.MigrationPropertyBatchFailed;
}

fn migrateStoreV2Edges(
    allocator: std.mem.Allocator,
    source: storage.Store,
    target: ?storage.Store,
    target_catalog: catalog_mod.Catalog,
    property_stream: *MigrationPropertyStream,
    target_property_builder: ?*MigrationTargetPropertySpoolBuilder,
    result: *StoreMigrationV2Result,
) !void {
    var batch = std.ArrayList(graph.Edge).empty;
    defer batch.deinit(allocator);
    try batch.ensureTotalCapacityPrecise(allocator, store_migration_edge_batch_limit);
    var source_node_view = try source.openNodeRecordView();
    defer source_node_view.deinit();
    const ScanContext = struct {
        allocator: std.mem.Allocator,
        source_node_view: *const storage.Store.NodeRecordView,
        target: ?storage.Store,
        batch: *std.ArrayList(graph.Edge),
        result: *StoreMigrationV2Result,

        fn flush(self: *@This()) !void {
            if (self.batch.items.len == 0) return;
            if (self.target) |store| {
                store.appendEdgesBatch(self.batch.items) catch return error.MigrationAppendUnorderedEdgesFailed;
            }
            self.result.edges_written = std.math.add(u64, self.result.edges_written, self.batch.items.len) catch return error.RecordTooLarge;
            self.batch.clearRetainingCapacity();
        }

        fn visit(raw_context: *anyopaque, record: storage.EdgeIndexRecord) anyerror!void {
            const self: *@This() = @ptrCast(@alignCast(raw_context));
            if (self.target == null and
                (!try sourceMigrationNodeIsLive(self.allocator, self.source_node_view, .fromInt(record.src)) or
                    !try sourceMigrationNodeIsLive(self.allocator, self.source_node_view, .fromInt(record.dst)))) return error.InvalidRecord;
            self.batch.appendAssumeCapacity(.{
                .id = .fromInt(record.edge_id),
                .src = .fromInt(record.src),
                .rel = try record.relKind(),
                .dst = .fromInt(record.dst),
            });
            self.result.edges_scanned = std.math.add(u64, self.result.edges_scanned, 1) catch return error.RecordTooLarge;
            if (self.batch.items.len == store_migration_edge_batch_limit) try self.flush();
        }
    };
    var scan_context = ScanContext{
        .allocator = allocator,
        .source_node_view = &source_node_view,
        .target = target,
        .batch = &batch,
        .result = result,
    };
    const scanned = try source.scanVisibleEdgeIndexRecords(allocator, &scan_context, ScanContext.visit);
    try scan_context.flush();
    if (scanned != result.edges_scanned or result.edges_scanned != result.edges_written) return error.InvalidRecord;

    if (target) |store| {
        if (result.edges_written != 0) try store.repairPersistentIndexesFromLog();
        _ = try store.replaceEdgeOrderIndexFromPresentEdges(source);
        const builder = target_property_builder orelse return error.InvalidRecord;
        var edge_iter = try store.visibleEdgeIndexRecordsIterator(.id);
        defer edge_iter.deinit();
        while (try edge_iter.next()) |record| {
            try batch.append(allocator, .{
                .id = .fromInt(record.edge_id),
                .src = .fromInt(record.src),
                .rel = try record.relKind(),
                .dst = .fromInt(record.dst),
            });
            if (batch.items.len < store_migration_edge_batch_limit) continue;
            try processStoreMigrationEdgePropertyBatch(
                allocator,
                batch.items,
                target_catalog,
                property_stream,
                builder,
                result,
            );
            batch.clearRetainingCapacity();
        }
        if (batch.items.len != 0) {
            try processStoreMigrationEdgePropertyBatch(
                allocator,
                batch.items,
                target_catalog,
                property_stream,
                builder,
                result,
            );
        }
    }
}

const StoreMigrationV2TransactionExpectation = struct {
    canonical_source_path: []const u8,
    canonical_backup_path: []const u8,
    source_store_bytes: u64,
    source_store_digest: ContentDigest,
    target_profiles: []const u8,
    target_catalog_revision: u32,
    target_schema_version: u32,
    strict: bool,
    warm_text: bool,
    verify: bool,
    task_status_v1: bool,
};

const StoreMigrationV2TransactionMarkerJson = struct {
    format: []const u8,
    canonical_source_path: []const u8,
    canonical_backup_path: []const u8,
    source_store_bytes: u64,
    source_store_digest: ContentDigest,
    target_profiles: []const u8,
    target_catalog_revision: u32,
    target_schema_version: u32,
    strict: bool,
    warm_text: bool,
    verify: bool,
    task_status_v1: bool,
    complete: bool,
    result: ?StoreMigrationV2Result = null,
};

const StoreMigrationV2MarkerState = struct {
    complete: bool,
    result: ?StoreMigrationV2Result,
    legacy_format: bool,
};

fn storeMigrationV2StagingPath(allocator: std.mem.Allocator, target_path: []const u8) ![]u8 {
    return try std.fmt.allocPrint(allocator, "{s}{s}", .{ target_path, store_migration_staging_suffix });
}

fn storeMigrationV2TransactionMarkerPath(allocator: std.mem.Allocator, dir_path: []const u8) ![]u8 {
    return try std.fs.path.join(allocator, &.{ dir_path, store_migration_transaction_marker_file });
}

fn appendStoreMigrationV2ResultJson(out: *QueryOutputWriter, result: StoreMigrationV2Result) !void {
    try out.print(
        "{{\"nodes_scanned\":{},\"nodes_written\":{},\"edges_scanned\":{},\"edges_written\":{},\"tombstone_nodes_skipped\":{},\"legacy_props_extracted\":{},\"legacy_text_repaired\":{},\"empty_text_physical_placeholders\":{},\"node_properties_written\":{},\"edge_properties_written\":{},\"task_statuses_written\":{},\"legacy_closed_tasks_converted\":{},\"text_warmed\":{},\"verified\":{},\"published_store_bytes\":{},\"published_store_digest\":[{},{},{},{}],\"marker_cleanup_pending\":{}}}",
        .{
            result.nodes_scanned,
            result.nodes_written,
            result.edges_scanned,
            result.edges_written,
            result.tombstone_nodes_skipped,
            result.legacy_props_extracted,
            result.legacy_text_repaired,
            result.empty_text_physical_placeholders,
            result.node_properties_written,
            result.edge_properties_written,
            result.task_statuses_written,
            result.legacy_closed_tasks_converted,
            result.text_warmed,
            result.verified,
            result.published_store_bytes,
            result.published_store_digest[0],
            result.published_store_digest[1],
            result.published_store_digest[2],
            result.published_store_digest[3],
            result.marker_cleanup_pending,
        },
    );
}

fn writeStoreMigrationV2TransactionMarker(
    allocator: std.mem.Allocator,
    io: std.Io,
    dir_path: []const u8,
    expected: StoreMigrationV2TransactionExpectation,
    result: ?StoreMigrationV2Result,
) !void {
    const marker_path = try storeMigrationV2TransactionMarkerPath(allocator, dir_path);
    defer allocator.free(marker_path);
    const tmp_path = try std.fmt.allocPrint(allocator, "{s}.tmp", .{marker_path});
    defer allocator.free(tmp_path);

    var out = QueryOutputWriter{ .allocator = allocator };
    defer out.buffer.deinit(allocator);
    try out.writeAll("{\"format\":");
    try writeJsonString(&out, store_migration_transaction_marker_format);
    try out.writeAll(",\"canonical_source_path\":");
    try writeJsonString(&out, expected.canonical_source_path);
    try out.writeAll(",\"canonical_backup_path\":");
    try writeJsonString(&out, expected.canonical_backup_path);
    try out.writeAll(",\"target_profiles\":");
    try writeJsonString(&out, expected.target_profiles);
    try out.print(
        ",\"source_store_bytes\":{},\"source_store_digest\":[{},{},{},{}],\"target_catalog_revision\":{},\"target_schema_version\":{},\"strict\":{},\"warm_text\":{},\"verify\":{},\"task_status_v1\":{},\"complete\":{},\"result\":",
        .{
            expected.source_store_bytes,
            expected.source_store_digest[0],
            expected.source_store_digest[1],
            expected.source_store_digest[2],
            expected.source_store_digest[3],
            expected.target_catalog_revision,
            expected.target_schema_version,
            expected.strict,
            expected.warm_text,
            expected.verify,
            expected.task_status_v1,
            result != null,
        },
    );
    if (result) |value| {
        try appendStoreMigrationV2ResultJson(&out, value);
    } else {
        try out.writeAll("null");
    }
    try out.writeAll("}\n");
    writeRecoverableTransactionMarker(allocator, io, tmp_path, marker_path, out.buffer.items) catch |err| switch (err) {
        error.TransactionMarkerConflict => return error.MigrationRecoveryConflict,
        else => |e| return e,
    };
}

fn readStoreMigrationV2TransactionMarker(
    allocator: std.mem.Allocator,
    io: std.Io,
    dir_path: []const u8,
    expected: StoreMigrationV2TransactionExpectation,
) !?StoreMigrationV2MarkerState {
    const marker_path = try storeMigrationV2TransactionMarkerPath(allocator, dir_path);
    defer allocator.free(marker_path);
    return try readStoreMigrationV2TransactionMarkerAtPath(allocator, io, marker_path, expected);
}

fn readStoreMigrationV2TransactionMarkerAtPath(
    allocator: std.mem.Allocator,
    io: std.Io,
    marker_path: []const u8,
    expected: StoreMigrationV2TransactionExpectation,
) !?StoreMigrationV2MarkerState {
    const bytes = std.Io.Dir.cwd().readFileAlloc(io, marker_path, allocator, .limited(32 * 1024)) catch |err| switch (err) {
        error.FileNotFound, error.NotDir => return null,
        error.StreamTooLong => return error.InvalidRecord,
        else => |e| return e,
    };
    defer allocator.free(bytes);
    var parsed = std.json.parseFromSlice(StoreMigrationV2TransactionMarkerJson, allocator, bytes, .{
        .ignore_unknown_fields = false,
        .allocate = .alloc_always,
    }) catch return error.InvalidRecord;
    defer parsed.deinit();
    const marker = parsed.value;
    const legacy_format = std.mem.eql(u8, marker.format, store_migration_transaction_marker_legacy_format);
    if ((!std.mem.eql(u8, marker.format, store_migration_transaction_marker_format) and !legacy_format) or
        !std.mem.eql(u8, marker.canonical_source_path, expected.canonical_source_path) or
        !std.mem.eql(u8, marker.canonical_backup_path, expected.canonical_backup_path) or
        marker.source_store_bytes != expected.source_store_bytes or
        !std.meta.eql(marker.source_store_digest, expected.source_store_digest) or
        !std.mem.eql(u8, marker.target_profiles, expected.target_profiles) or
        marker.target_catalog_revision != expected.target_catalog_revision or
        marker.target_schema_version != expected.target_schema_version or
        marker.strict != expected.strict or
        marker.warm_text != expected.warm_text or
        marker.verify != expected.verify or
        marker.task_status_v1 != expected.task_status_v1)
    {
        return error.MigrationRecoveryConflict;
    }
    if (marker.complete != (marker.result != null)) return error.InvalidRecord;
    if (marker.result) |result| {
        if (result.marker_cleanup_pending or
            result.text_warmed != expected.warm_text or
            result.verified != expected.verify or
            result.published_store_bytes == 0 or
            std.meta.eql(result.published_store_digest, ContentDigest{ 0, 0, 0, 0 }) or
            result.nodes_written > result.nodes_scanned or
            result.edges_written != result.edges_scanned)
        {
            return error.InvalidRecord;
        }
    }
    return .{ .complete = marker.complete, .result = marker.result, .legacy_format = legacy_format };
}

fn recoverStoreMigrationV2Staging(
    allocator: std.mem.Allocator,
    io: std.Io,
    staging_path: []const u8,
    expected: StoreMigrationV2TransactionExpectation,
) !void {
    if (!try anyPathExists(io, staging_path)) return;
    const stat = try std.Io.Dir.cwd().statFile(io, staging_path, .{ .follow_symlinks = false });
    if (stat.kind != .directory) return error.MigrationRecoveryConflict;
    var marker = try readStoreMigrationV2TransactionMarker(allocator, io, staging_path, expected);
    if (marker == null) {
        const marker_path = try storeMigrationV2TransactionMarkerPath(allocator, staging_path);
        defer allocator.free(marker_path);
        const tmp_path = try std.fmt.allocPrint(allocator, "{s}.tmp", .{marker_path});
        defer allocator.free(tmp_path);
        marker = try readStoreMigrationV2TransactionMarkerAtPath(allocator, io, tmp_path, expected);
    }
    _ = marker orelse return error.MigrationRecoveryConflict;
    try std.Io.Dir.cwd().deleteTree(io, staging_path);
    try syncParentDirectory(io, staging_path);
}

fn recoverCompletedStoreMigrationV2(
    allocator: std.mem.Allocator,
    io: std.Io,
    target_path: []const u8,
    expected: StoreMigrationV2TransactionExpectation,
    expected_catalog: catalog_mod.Catalog,
) !?StoreMigrationV2Result {
    if (!try anyPathExists(io, target_path)) return null;
    const stat = try std.Io.Dir.cwd().statFile(io, target_path, .{ .follow_symlinks = false });
    if (stat.kind != .directory) return error.AlreadyExists;
    const marker = (try readStoreMigrationV2TransactionMarker(allocator, io, target_path, expected)) orelse
        return error.AlreadyExists;
    if (!marker.complete) return error.InvalidRecord;
    _ = marker.result orelse return error.InvalidRecord;
    // The adjacent publication lock protects the path claim, not normal CLI
    // writers inside an already published store. Take that store's writer
    // lock and re-read the marker before hashing or validating its contents.
    const target_lock = try CliStoreLock.acquire(allocator, io, target_path);
    defer target_lock.deinit();
    const locked_marker = (try readStoreMigrationV2TransactionMarker(allocator, io, target_path, expected)) orelse
        return error.MigrationRecoveryConflict;
    if (!locked_marker.complete) return error.InvalidRecord;
    var result = locked_marker.result orelse return error.InvalidRecord;
    const target_identity = try storeContentIdentity(allocator, io, target_path);
    if (target_identity.bytes != result.published_store_bytes or
        !std.meta.eql(target_identity.digest, result.published_store_digest))
    {
        return error.MigrationRecoveryConflict;
    }
    if (!try existingTinyKgStorePath(allocator, io, target_path)) return error.InvalidRecord;

    var target = try storage.Store.open(allocator, io, target_path);
    defer target.deinit();
    const stats_out = try target.stats();
    if (stats_out.nodes != result.nodes_written or stats_out.edges != result.edges_written) return error.InvalidRecord;
    var actual_catalog = (try target.readCatalog()) orelse return error.InvalidRecord;
    defer actual_catalog.deinit();
    const actual_catalog_bytes = try catalog_mod.encodeCatalog(allocator, actual_catalog);
    defer allocator.free(actual_catalog_bytes);
    const expected_catalog_bytes = try catalog_mod.encodeCatalog(allocator, expected_catalog);
    defer allocator.free(expected_catalog_bytes);
    if (!std.mem.eql(u8, actual_catalog_bytes, expected_catalog_bytes)) return error.MigrationRecoveryConflict;

    const manifest = try readStoreManifestSummary(allocator, io, target_path);
    defer manifest.deinit(allocator);
    const expected_schema_version = try std.fmt.allocPrint(allocator, "{}", .{expected.target_schema_version});
    defer allocator.free(expected_schema_version);
    const expected_migration_name = if (expected.task_status_v1) "migrate-store-v2+task-status-v1" else "migrate-store-v2";
    if (!std.mem.eql(u8, manifest.status, "present") or
        !std.mem.eql(u8, manifest.storage_format_version, "2") or
        !std.mem.eql(u8, manifest.schema_version, expected_schema_version) or
        !std.mem.eql(u8, manifest.enabled_profiles, expected.target_profiles) or
        !std.mem.eql(u8, manifest.migration_name, expected_migration_name) or
        manifest.migration_source.len == 0)
    {
        return error.MigrationRecoveryConflict;
    }
    const canonical_manifest_source = canonicalProspectivePath(allocator, io, manifest.migration_source) catch
        return error.MigrationRecoveryConflict;
    defer allocator.free(canonical_manifest_source);
    if (!canonicalPathsEqual(canonical_manifest_source, expected.canonical_source_path)) return error.MigrationRecoveryConflict;
    if (expected.warm_text and try text_search.persistentTextCatalogQuickStale(allocator, target)) return error.InvalidRecord;

    if (locked_marker.legacy_format) {
        try writeStoreMigrationV2TransactionMarker(allocator, io, target_path, expected, result);
    }

    // A retry that can still observe the renamed directory makes the earlier
    // rename durable before it acknowledges the committed result.
    try syncParentDirectory(io, target_path);
    // Keep the complete marker as a durable commit receipt.  stdout may fail
    // after this function returns; deleting the only request-bound receipt
    // here would make that committed migration impossible to acknowledge on
    // retry without trusting an arbitrary pre-existing target.
    result.marker_cleanup_pending = false;
    return result;
}

fn validateSchemaMigratePathRelationship(allocator: std.mem.Allocator, io: std.Io, parsed: ParsedSchemaMigrateArgs) !void {
    if (!try existingTinyKgStorePath(allocator, io, parsed.old_db_path)) return error.FileNotFound;
    if (try pathsOverlapForCopyTarget(allocator, io, parsed.old_db_path, parsed.new_db_path)) return error.InvalidFileName;
}

fn validateSchemaMigratePaths(allocator: std.mem.Allocator, io: std.Io, parsed: ParsedSchemaMigrateArgs) !void {
    try validateSchemaMigratePathRelationship(allocator, io, parsed);
    // Any pre-existing path is foreign state.  Looking only for a TinyKG
    // marker allowed an empty/non-store directory to be opened and then
    // recursively deleted by migration cleanup.
    if (try anyPathExists(io, parsed.new_db_path)) return error.AlreadyExists;
}

fn migrateStoreV2(allocator: std.mem.Allocator, io: std.Io, parsed: ParsedMigrateStoreV2Args) !StoreMigrationV2Result {
    // Keep the validation here as well: migrateStoreV2 is used directly by
    // tests/embedders and must not rely on the CLI dispatcher for safety.
    try validateMigrateStoreV2PathRelationships(allocator, io, parsed);
    if (parsed.dry_run) try validateMigrateStoreV2Destinations(io, parsed);

    var source = try storage.Store.open(allocator, io, parsed.source_path);
    defer source.deinit();
    var target_catalog = try migrationCatalog(allocator, source, parsed.profiles, parsed.profiles_explicit, parsed.task_status_v1);
    defer target_catalog.deinit();
    const target_profiles = try catalogProfilesCsvAlloc(allocator, target_catalog);
    defer allocator.free(target_profiles);
    const target_schema_version: u32 = if (parsed.task_status_v1) current_schema_version else 2;
    const canonical_source_path = try canonicalProspectivePath(allocator, io, parsed.source_path);
    defer allocator.free(canonical_source_path);
    const canonical_backup_path = if (parsed.backup_path) |backup_path|
        try canonicalProspectivePath(allocator, io, backup_path)
    else
        try allocator.dupe(u8, "");
    defer allocator.free(canonical_backup_path);
    const source_identity = try storeContentIdentity(allocator, io, parsed.source_path);
    const migration_expectation = StoreMigrationV2TransactionExpectation{
        .canonical_source_path = canonical_source_path,
        .canonical_backup_path = canonical_backup_path,
        .source_store_bytes = source_identity.bytes,
        .source_store_digest = source_identity.digest,
        .target_profiles = target_profiles,
        .target_catalog_revision = target_catalog.revision,
        .target_schema_version = target_schema_version,
        .strict = parsed.strict,
        .warm_text = parsed.warm_text,
        .verify = parsed.verify,
        .task_status_v1 = parsed.task_status_v1,
    };
    const staging_path = try storeMigrationV2StagingPath(allocator, parsed.target_path);
    defer allocator.free(staging_path);
    // Dry runs use the same private scratch path and marker discipline. A
    // crash while external-sorting must be reclaimable by the next request,
    // not leave an unmarked directory that blocks every future migration.
    try recoverStoreMigrationV2Staging(allocator, io, staging_path, migration_expectation);
    if (!parsed.dry_run) {
        if (try recoverCompletedStoreMigrationV2(allocator, io, parsed.target_path, migration_expectation, target_catalog)) |recovered| {
            return recovered;
        }
        try validateMigrateStoreV2Destinations(io, parsed);
        if (parsed.backup_path) |backup_path| {
            if (try anyPathExists(io, backup_path)) {
                _ = try validateExistingBackupForSource(allocator, io, parsed.source_path, backup_path);
            } else {
                _ = try backupStore(allocator, io, parsed.source_path, backup_path);
            }
        }
    }
    var result = StoreMigrationV2Result{};
    const migration_now_ns = try u128ToU64(persistentNowNs(io));
    try createOwnedDirectory(io, staging_path);
    var staging_owned = true;
    defer if (staging_owned) std.Io.Dir.cwd().deleteTree(io, staging_path) catch {};
    try writeStoreMigrationV2TransactionMarker(allocator, io, staging_path, migration_expectation, null);
    try syncExportDirectoryTree(allocator, io, staging_path);

    {
        var node_property_keys = try MigrationPropertyKeys.init(allocator, target_catalog.registry, target_catalog.registry, .node);
        defer node_property_keys.deinit();
        var edge_property_keys = try MigrationPropertyKeys.init(allocator, target_catalog.registry, target_catalog.registry, .edge);
        defer edge_property_keys.deinit();
        var source_property_spool = try MigrationPropertySpool.buildAll(
            allocator,
            io,
            staging_path,
            source,
            &node_property_keys,
            &edge_property_keys,
        );
        defer source_property_spool.deinit();

        if (parsed.dry_run) {
            var source_property_stream = try MigrationPropertyStream.init(&source_property_spool);
            defer source_property_stream.deinit();
            try migrateStoreV2Nodes(
                allocator,
                source,
                null,
                target_catalog,
                &source_property_stream,
                null,
                parsed,
                migration_now_ns,
                &result,
            );
            try migrateStoreV2Edges(
                allocator,
                source,
                null,
                target_catalog,
                &source_property_stream,
                null,
                &result,
            );
            try source_property_stream.finish();
            result.verified = true;
            return result;
        }

        // Materialize only in the private staging tree. The final target remains
        // absent until a complete, verified and synced store can claim it with a
        // single directory rename.
        var target = storage.Store.initWithOptions(allocator, io, staging_path, .{
            .primary_text_write_mode = .bulk_ingest,
            // Migration emits many bounded edge batches before one final
            // consolidation. Avoid periodically compacting the growing
            // segment overlay into the base indexes during that stream.
            .auto_compact_edge_segment_entries = std.math.maxInt(u32),
        }) catch |err| return err;
        var target_open = true;
        defer if (target_open) target.deinit();
        try target.createEmpty();
        try target.writeCatalog(target_catalog);
        var source_property_stream = try MigrationPropertyStream.init(&source_property_spool);
        defer source_property_stream.deinit();
        var target_property_builder = try MigrationTargetPropertySpoolBuilder.init(
            allocator,
            io,
            staging_path,
            &node_property_keys,
            &edge_property_keys,
        );
        defer target_property_builder.deinit();
        try migrateStoreV2Nodes(
            allocator,
            source,
            target,
            target_catalog,
            &source_property_stream,
            &target_property_builder,
            parsed,
            migration_now_ns,
            &result,
        );
        target.finalizePrimaryTextStorage() catch return error.MigrationAppendNodesFailed;
        try migrateStoreV2Edges(
            allocator,
            source,
            target,
            target_catalog,
            &source_property_stream,
            &target_property_builder,
            &result,
        );
        try source_property_stream.finish();
        var target_property_spool = try target_property_builder.finish();
        defer target_property_spool.deinit();
        const expected_property_writes = std.math.add(u64, result.node_properties_written, result.edge_properties_written) catch return error.MigrationPropertyBatchFailed;
        if (target_property_spool.record_count != expected_property_writes) return error.MigrationPropertyBatchFailed;
        var target_property_stream = try MigrationPropertyStream.init(&target_property_spool);
        defer target_property_stream.deinit();
        target.replaceEmptyPropertyPayloadFromSortedStream(
            target_property_spool.record_count,
            &target_property_stream,
            MigrationPropertyStream.nextSortedPayload,
        ) catch return error.MigrationPropertyBatchFailed;

        _ = try copyMetaknowDeferredBasedOnSidecarForMigration(allocator, io, source.dir_path, target.dir_path);

        if (parsed.warm_text) {
            _ = try text_search.rebuildPersistentTextCatalog(allocator, target);
            result.text_warmed = true;
        }

        try writeStoreManifest(allocator, io, staging_path, .{
            .profiles = target_profiles,
            .migration_name = if (parsed.task_status_v1) "migrate-store-v2+task-status-v1" else "migrate-store-v2",
            .source_path = canonical_source_path,
            // Schema v3 is an on-disk promise that every task has a durable
            // status marker. A compatibility migration without --task-status-v1
            // must remain v2 or effective-status queries can silently omit tasks.
            .schema_version = target_schema_version,
        });

        if (parsed.verify) {
            try verifyMigratedStoreV2(
                allocator,
                source,
                target,
                &source_property_spool,
                &target_property_spool,
                parsed,
                migration_now_ns,
                target_catalog,
                target_profiles,
                target_schema_version,
                result,
            );
            result.verified = true;
        }

        target.deinit();
        target_open = false;
    }
    const current_source_identity = try storeContentIdentity(allocator, io, parsed.source_path);
    if (current_source_identity.bytes != source_identity.bytes or
        !std.meta.eql(current_source_identity.digest, source_identity.digest))
    {
        return error.MigrationSourceChanged;
    }
    const published_identity = try storeContentIdentity(allocator, io, staging_path);
    result.published_store_bytes = published_identity.bytes;
    result.published_store_digest = published_identity.digest;
    try writeStoreMigrationV2TransactionMarker(allocator, io, staging_path, migration_expectation, result);
    try syncExportDirectoryTree(allocator, io, staging_path);
    // A foreign path can still appear after preflight. Never overwrite it and
    // never reinterpret it as our staging tree.
    try validateMigrateStoreV2PathRelationships(allocator, io, parsed);
    if (try anyPathExists(io, parsed.target_path)) return error.AlreadyExists;
    try renamePath(io, staging_path, parsed.target_path);
    staging_owned = false;
    try syncParentDirectory(io, parsed.target_path);
    // The complete transaction marker is retained as the idempotency receipt
    // for a caller that loses the success response after the rename commit.
    result.marker_cleanup_pending = false;
    return result;
}

const LegacyNodeTextRepair = struct {
    text: []u8,
    props_json: ?[]const u8 = null,
    repaired: bool = false,

    fn deinit(self: *LegacyNodeTextRepair, allocator: std.mem.Allocator) void {
        allocator.free(self.text);
    }
};

fn repairLegacyNodeTextForMigration(allocator: std.mem.Allocator, text: []const u8, strict: bool, result: *StoreMigrationV2Result, count_repair: bool) !LegacyNodeTextRepair {
    const marker = " props_text=\"";
    const marker_index = std.mem.indexOf(u8, text, marker) orelse {
        return .{ .text = try allocator.dupe(u8, text) };
    };
    const json_start = marker_index + marker.len;
    const json_slice = legacyJsonObjectSlice(text[json_start..]) orelse {
        if (strict) return error.InvalidRecord;
        return .{ .text = try allocator.dupe(u8, text) };
    };
    const visible = std.mem.trim(u8, text[0..marker_index], " \t\r\n");
    if (count_repair) result.legacy_text_repaired += 1;
    return .{
        .text = try allocator.dupe(u8, visible),
        .props_json = json_slice,
        .repaired = true,
    };
}

fn legacyJsonObjectSlice(text: []const u8) ?[]const u8 {
    if (text.len == 0 or text[0] != '{') return null;
    var depth: usize = 0;
    var in_string = false;
    var escaped = false;
    for (text, 0..) |byte, index| {
        if (escaped) {
            escaped = false;
            continue;
        }
        if (in_string and byte == '\\') {
            escaped = true;
            continue;
        }
        if (byte == '"') {
            in_string = !in_string;
            continue;
        }
        if (in_string) continue;
        if (byte == '{') {
            depth += 1;
        } else if (byte == '}') {
            if (depth == 0) return null;
            depth -= 1;
            if (depth == 0) return text[0 .. index + 1];
        }
    }
    return null;
}

fn appendLegacyNodePropsTextProperties(
    allocator: std.mem.Allocator,
    source_properties: *const MigrationPropertyLookup,
    node_id: core.NodeId,
    props_json_input: ?[]const u8,
    strict: bool,
    result: *StoreMigrationV2Result,
    batch: *MigrationPropertyBatch,
    materialize_status: bool,
    force_task_schema: bool,
) !u64 {
    const props_json = props_json_input orelse return 0;

    var parsed = std.json.parseFromSlice(std.json.Value, allocator, props_json, .{
        .ignore_unknown_fields = true,
        .allocate = .alloc_always,
    }) catch |err| {
        if (strict) return err;
        return 0;
    };
    defer parsed.deinit();
    if (parsed.value != .object) return 0;

    var count: u64 = 0;
    var it = parsed.value.object.iterator();
    while (it.next()) |entry| {
        const key = entry.key_ptr.*;
        if (!migrationPropertyKeyValid(key) or std.mem.eql(u8, key, "text")) continue;
        if (migrationPropertySuppressedByTaskStatusV1(key, materialize_status, force_task_schema)) continue;
        const owner: storage.PropertyOwner = .{ .node = node_id };
        if (source_properties.get(owner, key) != null) continue;
        switch (entry.value_ptr.*) {
            .string => |value| {
                try batch.appendString(owner, key, value);
                count += 1;
                result.legacy_props_extracted += 1;
            },
            .integer => |value| {
                if (value < 0) continue;
                try batch.appendUint(owner, key, @intCast(value));
                count += 1;
                result.legacy_props_extracted += 1;
            },
            .bool => |value| {
                try batch.appendString(owner, key, if (value) "true" else "false");
                count += 1;
                result.legacy_props_extracted += 1;
            },
            else => {},
        }
    }
    return count;
}

fn countLegacyNodePropsTextProperties(
    allocator: std.mem.Allocator,
    source_properties: *const MigrationPropertyLookup,
    node_id: core.NodeId,
    props_json: ?[]const u8,
    strict: bool,
    materialize_status: bool,
    force_task_schema: bool,
) !u64 {
    const json = props_json orelse return 0;
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, json, .{
        .ignore_unknown_fields = true,
        .allocate = .alloc_always,
    }) catch |err| {
        if (strict) return err;
        return 0;
    };
    defer parsed.deinit();
    if (parsed.value != .object) return 0;
    var count: u64 = 0;
    var it = parsed.value.object.iterator();
    while (it.next()) |entry| {
        const key = entry.key_ptr.*;
        if (!migrationPropertyKeyValid(key) or std.mem.eql(u8, key, "text")) continue;
        if (migrationPropertySuppressedByTaskStatusV1(key, materialize_status, force_task_schema)) continue;
        const owner: storage.PropertyOwner = .{ .node = node_id };
        if (source_properties.get(owner, key) != null) continue;
        switch (entry.value_ptr.*) {
            .string, .integer, .bool => count += 1,
            else => {},
        }
    }
    return count;
}

fn migrationPropertyKeyValid(key: []const u8) bool {
    if (key.len == 0 or key.len > 128) return false;
    for (key) |byte| {
        const ok = std.ascii.isAlphanumeric(byte) or byte == '_' or byte == '-' or byte == ':' or byte == '.';
        if (!ok) return false;
    }
    return true;
}

fn migrationPropertySuppressedByTaskStatusV1(key: []const u8, materialize_status: bool, force_task_schema: bool) bool {
    return (materialize_status and
        (std.mem.eql(u8, key, task.status_property) or
            std.mem.eql(u8, key, task.claim_expires_ns_property) or
            std.mem.eql(u8, key, "task_completed_ns"))) or
        (force_task_schema and std.mem.eql(u8, key, "schema_type"));
}

fn appendMigrationSnapshotProperty(
    source_properties: *const MigrationPropertyLookup,
    owner: storage.PropertyOwner,
    key: []const u8,
    target_property: ?schema.PropertyMeta,
    batch: *MigrationPropertyBatch,
) !u64 {
    const entry = source_properties.get(owner, key) orelse return 0;
    if (target_property) |property| {
        switch (property.value_type) {
            .string, .json => if (entry.value_kind != .string) return error.SchemaPropertyValueMismatch,
            .@"enum" => {
                if (entry.value_kind != .string or !property.enumAllows(entry.string_value)) return error.SchemaPropertyValueMismatch;
            },
            .uint => if (entry.value_kind != .uint) return error.SchemaPropertyValueMismatch,
            // The current persistent property payload has no signed/bool
            // value variant.  A catalog may describe those types for future
            // evolution, but schema migration must not reinterpret an
            // existing string/uint payload as one of them.
            .int, .bool => return error.SchemaPropertyValueMismatch,
        }
    }
    switch (entry.value_kind) {
        .string => try batch.appendString(owner, key, entry.string_value),
        .uint => try batch.appendUint(owner, key, entry.uint_value),
    }
    return 1;
}

fn ensureDeclaredNodePropertiesRetained(
    source_properties: *const MigrationPropertyLookup,
    source_registry: schema.Registry,
    source_type_id: u16,
    target_registry: schema.Registry,
    target_type_id: u16,
    node_id: core.NodeId,
) !void {
    var property_index: usize = 0;
    while (source_registry.nodePropertyInfo(source_type_id, property_index)) |property| : (property_index += 1) {
        if (source_properties.get(.{ .node = node_id }, property.name) == null) continue;
        if (target_registry.nodePropertyByTypeId(target_type_id, property.name) == null) return error.SchemaOrphanedPropertyInUse;
    }
}

fn ensureDeclaredEdgePropertiesRetained(
    source_properties: *const MigrationPropertyLookup,
    source_registry: schema.Registry,
    source_type_id: u16,
    target_registry: schema.Registry,
    target_type_id: u16,
    edge_id: core.EdgeId,
) !void {
    var property_index: usize = 0;
    while (source_registry.relationPropertyInfo(source_type_id, property_index)) |property| : (property_index += 1) {
        if (source_properties.get(.{ .edge = edge_id }, property.name) == null) continue;
        if (target_registry.relationPropertyByTypeId(target_type_id, property.name) == null) return error.SchemaOrphanedPropertyInUse;
    }
}

fn collectKnownNodeProperties(
    source_properties: *const MigrationPropertyLookup,
    registry: schema.Registry,
    target_type_id: u16,
    node_id: core.NodeId,
    batch: *MigrationPropertyBatch,
    materialize_status: bool,
    force_task_schema: bool,
) !u64 {
    var count: u64 = 0;
    const owner: storage.PropertyOwner = .{ .node = node_id };
    var seen = std.AutoHashMap(u64, void).init(batch.allocator);
    defer seen.deinit();
    for (migrate_node_string_property_keys) |key| {
        if (migrationPropertySuppressedByTaskStatusV1(key, materialize_status, force_task_schema)) continue;
        try seen.put(storage.propertyKeyHashForLookup(key), {});
        const target_property = registry.nodePropertyByTypeId(target_type_id, key);
        const copied = try appendMigrationSnapshotProperty(source_properties, owner, key, target_property, batch);
        if (copied == 0 and target_property != null and target_property.?.required and !std.mem.eql(u8, key, "text")) return error.SchemaRequiredPropertyMissing;
        count += copied;
    }
    for (migrate_node_uint_property_keys) |key| {
        if (migrationPropertySuppressedByTaskStatusV1(key, materialize_status, force_task_schema)) continue;
        const key_hash = storage.propertyKeyHashForLookup(key);
        const seen_entry = try seen.getOrPut(key_hash);
        if (seen_entry.found_existing) continue;
        const target_property = registry.nodePropertyByTypeId(target_type_id, key);
        const copied = try appendMigrationSnapshotProperty(source_properties, owner, key, target_property, batch);
        if (copied == 0 and target_property != null and target_property.?.required) return error.SchemaRequiredPropertyMissing;
        count += copied;
    }
    var property_index: usize = 0;
    while (registry.nodePropertyInfo(target_type_id, property_index)) |property| : (property_index += 1) {
        if (migrationPropertySuppressedByTaskStatusV1(property.name, materialize_status, force_task_schema)) continue;
        const seen_entry = try seen.getOrPut(storage.propertyKeyHashForLookup(property.name));
        if (seen_entry.found_existing) continue;
        const copied = try appendMigrationSnapshotProperty(source_properties, owner, property.name, property, batch);
        if (copied == 0 and property.required and !std.mem.eql(u8, property.name, "text")) return error.SchemaRequiredPropertyMissing;
        count += copied;
    }
    return count;
}

fn collectKnownEdgeProperties(
    source_properties: *const MigrationPropertyLookup,
    registry: schema.Registry,
    target_type_id: u16,
    edge_id: core.EdgeId,
    source_edge_order_map: ?*const std.AutoHashMap(u64, u64),
    batch: *MigrationPropertyBatch,
) !u64 {
    var count: u64 = 0;
    const owner: storage.PropertyOwner = .{ .edge = edge_id };
    var seen = std.AutoHashMap(u64, void).init(batch.allocator);
    defer seen.deinit();
    for (migrate_edge_string_property_keys) |key| {
        try seen.put(storage.propertyKeyHashForLookup(key), {});
        const target_property = registry.relationPropertyByTypeId(target_type_id, key);
        const copied = try appendMigrationSnapshotProperty(source_properties, owner, key, target_property, batch);
        if (copied == 0 and target_property != null and target_property.?.required) return error.SchemaRequiredPropertyMissing;
        count += copied;
    }
    for (migrate_edge_uint_property_keys) |key| {
        if (std.mem.eql(u8, key, "order_key") and source_edge_order_map != null and source_edge_order_map.?.contains(edge_id.toInt())) continue;
        const seen_entry = try seen.getOrPut(storage.propertyKeyHashForLookup(key));
        if (seen_entry.found_existing) continue;
        const target_property = registry.relationPropertyByTypeId(target_type_id, key);
        const copied = try appendMigrationSnapshotProperty(source_properties, owner, key, target_property, batch);
        if (copied == 0 and target_property != null and target_property.?.required) return error.SchemaRequiredPropertyMissing;
        count += copied;
    }
    var property_index: usize = 0;
    while (registry.relationPropertyInfo(target_type_id, property_index)) |property| : (property_index += 1) {
        if (std.mem.eql(u8, property.name, "order_key") and source_edge_order_map != null and source_edge_order_map.?.contains(edge_id.toInt())) continue;
        const seen_entry = try seen.getOrPut(storage.propertyKeyHashForLookup(property.name));
        if (seen_entry.found_existing) continue;
        const copied = try appendMigrationSnapshotProperty(source_properties, owner, property.name, property, batch);
        if (copied == 0 and property.required) return error.SchemaRequiredPropertyMissing;
        count += copied;
    }
    return count;
}

fn verifyStoreMigrationNodeBatch(
    allocator: std.mem.Allocator,
    source_nodes: []const storage.StoredNode,
    property_stream: *MigrationPropertyStream,
    target_nodes: *storage.Store.NodeRecordIterator,
    parsed: ParsedMigrateStoreV2Args,
    migration_now_ns: u64,
) !u64 {
    if (source_nodes.len == 0) return 0;
    var raw_ids = std.ArrayList(u64).empty;
    defer raw_ids.deinit(allocator);
    try raw_ids.ensureTotalCapacityPrecise(allocator, source_nodes.len);
    for (source_nodes) |node| raw_ids.appendAssumeCapacity(node.id.toInt());
    const snapshot = try property_stream.snapshotForOwners(1, raw_ids.items);
    var source_properties = try MigrationPropertyLookup.initFromSnapshot(allocator, snapshot);
    defer source_properties.deinit();
    var dummy_result = StoreMigrationV2Result{};
    for (source_nodes) |source_node| {
        var repaired = try repairLegacyNodeTextForMigration(allocator, source_node.text, parsed.strict, &dummy_result, false);
        defer repaired.deinit(allocator);
        var migration_lifecycle = if (parsed.task_status_v1)
            try migrationLifecycleFieldsWithLegacyProps(
                allocator,
                &source_properties,
                source_node.id,
                repaired.props_json,
                parsed.strict,
            )
        else
            MigrationLifecycleFields{ .fields = .{} };
        defer migration_lifecycle.deinit(allocator);
        const materialized_status = if (parsed.task_status_v1)
            try taskStatusForMigration(source_node, migration_lifecycle.fields, migration_now_ns)
        else
            null;
        const expected_kind: core.NodeKind = if (materialized_status != null) .task else source_node.kind;
        var actual = (try target_nodes.next(allocator)) orelse return error.InvalidRecord;
        defer actual.deinit(allocator);
        if (actual.id != source_node.id or actual.kind != expected_kind or !std.mem.eql(u8, actual.text, repaired.text)) return error.InvalidRecord;
    }
    return @intCast(source_nodes.len);
}

fn verifyMigratedStoreV2(
    allocator: std.mem.Allocator,
    source: storage.Store,
    target: storage.Store,
    source_property_spool: *const MigrationPropertySpool,
    expected_property_spool: *const MigrationPropertySpool,
    parsed: ParsedMigrateStoreV2Args,
    migration_now_ns: u64,
    expected_catalog: catalog_mod.Catalog,
    expected_profiles: []const u8,
    expected_schema_version: u32,
    result: StoreMigrationV2Result,
) !void {
    const source_stats = try source.stats();
    const target_stats = try target.stats();
    if (target_stats.nodes != result.nodes_written or target_stats.edges != result.edges_written) return error.InvalidRecord;
    if (source_stats.nodes < target_stats.nodes or source_stats.edges < target_stats.edges) return error.InvalidRecord;

    var actual_catalog = (try target.readCatalog()) orelse return error.InvalidRecord;
    defer actual_catalog.deinit();
    const expected_catalog_bytes = try catalog_mod.encodeCatalog(allocator, expected_catalog);
    defer allocator.free(expected_catalog_bytes);
    const actual_catalog_bytes = try catalog_mod.encodeCatalog(allocator, actual_catalog);
    defer allocator.free(actual_catalog_bytes);
    if (!std.mem.eql(u8, expected_catalog_bytes, actual_catalog_bytes)) return error.InvalidRecord;

    const manifest = try readStoreManifestSummary(allocator, target.io, target.dir_path);
    defer manifest.deinit(allocator);
    if (!std.mem.eql(u8, manifest.status, "present") or
        !std.mem.eql(u8, manifest.storage_format_version, "2") or
        !std.mem.eql(u8, manifest.enabled_profiles, expected_profiles)) return error.InvalidRecord;
    const expected_schema_text = try std.fmt.allocPrint(allocator, "{}", .{expected_schema_version});
    defer allocator.free(expected_schema_text);
    if (!std.mem.eql(u8, manifest.schema_version, expected_schema_text)) return error.InvalidRecord;

    var source_property_stream = try MigrationPropertyStream.init(source_property_spool);
    defer source_property_stream.deinit();
    var source_nodes = try source.nodeRecordsIterator(null);
    defer source_nodes.deinit();
    var target_nodes = try target.nodeRecordsIterator(null);
    defer target_nodes.deinit();
    var node_batch = std.ArrayList(storage.StoredNode).empty;
    defer {
        for (node_batch.items) |*node| node.deinit(allocator);
        node_batch.deinit(allocator);
    }
    try node_batch.ensureTotalCapacityPrecise(allocator, store_migration_node_batch_limit);
    var nodes_verified: u64 = 0;
    while (try source_nodes.next(allocator)) |stored_node| {
        var node = stored_node;
        if (isDeletedNodeTombstone(node)) {
            node.deinit(allocator);
            continue;
        }
        node_batch.appendAssumeCapacity(node);
        if (node_batch.items.len < store_migration_node_batch_limit) continue;
        nodes_verified += try verifyStoreMigrationNodeBatch(
            allocator,
            node_batch.items,
            &source_property_stream,
            &target_nodes,
            parsed,
            migration_now_ns,
        );
        for (node_batch.items) |*owned| owned.deinit(allocator);
        node_batch.clearRetainingCapacity();
    }
    if (node_batch.items.len != 0) {
        nodes_verified += try verifyStoreMigrationNodeBatch(
            allocator,
            node_batch.items,
            &source_property_stream,
            &target_nodes,
            parsed,
            migration_now_ns,
        );
        for (node_batch.items) |*owned| owned.deinit(allocator);
        node_batch.clearRetainingCapacity();
    }
    if (nodes_verified != result.nodes_written) return error.InvalidRecord;
    if (try target_nodes.next(allocator)) |extra_node| {
        var owned_extra = extra_node;
        owned_extra.deinit(allocator);
        return error.InvalidRecord;
    }
    try source_property_stream.finish();

    var target_edges = try target.visibleEdgeIndexRecordsIterator(.src);
    defer target_edges.deinit();
    const EdgeCompare = struct {
        target_edges: *storage.Store.VisibleEdgeIndexRecordIterator,
        count: u64 = 0,

        fn visit(raw_context: *anyopaque, expected: storage.EdgeIndexRecord) anyerror!void {
            const context: *@This() = @ptrCast(@alignCast(raw_context));
            const actual = (try context.target_edges.next()) orelse return error.InvalidRecord;
            if (actual.edge_id != expected.edge_id or actual.src != expected.src or actual.dst != expected.dst or actual.rel != expected.rel) return error.InvalidRecord;
            context.count = std.math.add(u64, context.count, 1) catch return error.RecordTooLarge;
        }
    };
    var edge_compare = EdgeCompare{ .target_edges = &target_edges };
    const edges_verified = try source.scanVisibleEdgeIndexRecords(allocator, &edge_compare, EdgeCompare.visit);
    if (edges_verified != edge_compare.count) return error.InvalidRecord;
    if (edges_verified != result.edges_written or try target_edges.next() != null) return error.InvalidRecord;

    var expected_property_stream = try MigrationPropertyStream.init(expected_property_spool);
    defer expected_property_stream.deinit();
    const PropertyCompare = struct {
        expected: *MigrationPropertyStream,
        count: u64 = 0,

        fn visit(raw_context: *anyopaque, actual: storage.PropertySnapshotLayerEntry) anyerror!void {
            const context: *@This() = @ptrCast(@alignCast(raw_context));
            const expected = (try MigrationPropertyStream.nextSortedPayload(context.expected)) orelse return error.InvalidRecord;
            const same_owner = switch (expected.owner) {
                .node => |expected_id| switch (actual.owner) {
                    .node => |actual_id| expected_id == actual_id,
                    .edge => false,
                },
                .edge => |expected_id| switch (actual.owner) {
                    .node => false,
                    .edge => |actual_id| expected_id == actual_id,
                },
            };
            if (!same_owner or expected.key_hash != actual.key_hash) return error.InvalidRecord;
            switch (expected.value) {
                .string => |value| if (actual.value_kind != .string or !std.mem.eql(u8, value, actual.string_value)) return error.InvalidRecord,
                .uint => |value| if (actual.value_kind != .uint or value != actual.uint_value) return error.InvalidRecord,
            }
            context.count = std.math.add(u64, context.count, 1) catch return error.RecordTooLarge;
        }
    };
    var property_compare = PropertyCompare{ .expected = &expected_property_stream };
    try target.scanPropertySnapshotLayers(allocator, &property_compare, PropertyCompare.visit);
    if (try MigrationPropertyStream.nextSortedPayload(&expected_property_stream) != null or
        property_compare.count != expected_property_spool.record_count) return error.InvalidRecord;
}

fn exportTemporaryPath(allocator: std.mem.Allocator, io: std.Io, dir_path: []const u8, suffix: []const u8) ![]u8 {
    const nonce = export_temp_nonce.fetchAdd(1, .monotonic);
    return try std.fmt.allocPrint(
        allocator,
        "{s}.tinykg-export-{d}-{d}.{s}",
        .{ dir_path, persistentNowNs(io), nonce, suffix },
    );
}

fn renamePath(io: std.Io, old_path: []const u8, new_path: []const u8) !void {
    if (std.fs.path.isAbsolute(old_path) or std.fs.path.isAbsolute(new_path)) {
        try std.Io.Dir.renameAbsolute(old_path, new_path, io);
    } else {
        try std.Io.Dir.rename(.cwd(), old_path, .cwd(), new_path, io);
    }
}

fn writeAtomicReplacementFile(io: std.Io, tmp_path: []const u8, final_path: []const u8, bytes: []const u8) !void {
    var tmp_owned = false;
    errdefer if (tmp_owned) std.Io.Dir.cwd().deleteFile(io, tmp_path) catch {};
    {
        var file = try std.Io.Dir.cwd().createFile(io, tmp_path, .{ .read = true, .truncate = true, .exclusive = true });
        tmp_owned = true;
        defer file.close(io);
        try file.writePositionalAll(io, bytes, 0);
        try file.sync(io);
    }
    try renamePath(io, tmp_path, final_path);
    tmp_owned = false;
    try syncParentDirectory(io, final_path);
}

/// Complete a marker publication interrupted after its fixed temp file was
/// written. Callers hold the transaction's stable publication lock (or own a
/// newly-created private staging directory), so an existing exact byte match
/// is a request-bound recovery artifact rather than a concurrent writer.
/// Unknown or partial temp content is never removed or overwritten.
fn writeRecoverableTransactionMarker(
    allocator: std.mem.Allocator,
    io: std.Io,
    tmp_path: []const u8,
    final_path: []const u8,
    bytes: []const u8,
) !void {
    const stat = std.Io.Dir.cwd().statFile(io, tmp_path, .{ .follow_symlinks = false }) catch |err| switch (err) {
        error.FileNotFound, error.NotDir => return writeAtomicReplacementFile(io, tmp_path, final_path, bytes) catch |write_err| switch (write_err) {
            error.PathAlreadyExists => error.TransactionMarkerConflict,
            else => |e| e,
        },
        else => |e| return e,
    };
    if (stat.kind != .file) return error.TransactionMarkerConflict;
    const read_limit = std.math.add(usize, bytes.len, 1) catch return error.TransactionMarkerConflict;
    const existing = std.Io.Dir.cwd().readFileAlloc(io, tmp_path, allocator, .limited(read_limit)) catch |err| switch (err) {
        error.StreamTooLong, error.FileNotFound, error.NotDir, error.IsDir => return error.TransactionMarkerConflict,
        else => |e| return e,
    };
    defer allocator.free(existing);
    if (!std.mem.eql(u8, existing, bytes)) return error.TransactionMarkerConflict;

    // The former writer may have died before fsync returned. Re-sync the
    // validated inode ourselves before making its name authoritative.
    {
        var file = std.Io.Dir.cwd().openFile(io, tmp_path, .{ .mode = .read_write, .allow_directory = false }) catch |err| switch (err) {
            error.FileNotFound, error.NotDir, error.IsDir => return error.TransactionMarkerConflict,
            else => |e| return e,
        };
        defer file.close(io);
        try file.sync(io);
    }
    try renamePath(io, tmp_path, final_path);
    try syncParentDirectory(io, final_path);
}

test "atomic replacement never deletes an unowned temp file" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const tmp_path = try std.fs.path.join(std.testing.allocator, &.{ path_buf[0..root_len], "marker.tmp" });
    defer std.testing.allocator.free(tmp_path);
    const final_path = try std.fs.path.join(std.testing.allocator, &.{ path_buf[0..root_len], "marker" });
    defer std.testing.allocator.free(final_path);

    try std.Io.Dir.cwd().writeFile(std.testing.io, .{
        .sub_path = tmp_path,
        .data = "foreign temp contents",
        .flags = .{ .truncate = true },
    });
    try std.testing.expectError(error.PathAlreadyExists, writeAtomicReplacementFile(std.testing.io, tmp_path, final_path, "ours"));
    const preserved = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, tmp_path, std.testing.allocator, .limited(64));
    defer std.testing.allocator.free(preserved);
    try std.testing.expectEqualStrings("foreign temp contents", preserved);
    try std.testing.expect(!try anyPathExists(std.testing.io, final_path));
}

test "recoverable transaction marker promotes only exact temp content" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const tmp_path = try std.fs.path.join(std.testing.allocator, &.{ path_buf[0..root_len], "marker.tmp" });
    defer std.testing.allocator.free(tmp_path);
    const final_path = try std.fs.path.join(std.testing.allocator, &.{ path_buf[0..root_len], "marker" });
    defer std.testing.allocator.free(final_path);

    try std.Io.Dir.cwd().writeFile(std.testing.io, .{
        .sub_path = tmp_path,
        .data = "complete request-bound marker",
        .flags = .{ .truncate = true },
    });
    try writeRecoverableTransactionMarker(
        std.testing.allocator,
        std.testing.io,
        tmp_path,
        final_path,
        "complete request-bound marker",
    );
    try std.testing.expect(!try anyPathExists(std.testing.io, tmp_path));
    const published = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, final_path, std.testing.allocator, .limited(64));
    defer std.testing.allocator.free(published);
    try std.testing.expectEqualStrings("complete request-bound marker", published);

    try std.Io.Dir.cwd().writeFile(std.testing.io, .{
        .sub_path = tmp_path,
        .data = "foreign marker",
        .flags = .{ .truncate = true },
    });
    try std.testing.expectError(
        error.TransactionMarkerConflict,
        writeRecoverableTransactionMarker(std.testing.allocator, std.testing.io, tmp_path, final_path, "new marker"),
    );
    const preserved = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, tmp_path, std.testing.allocator, .limited(64));
    defer std.testing.allocator.free(preserved);
    try std.testing.expectEqualStrings("foreign marker", preserved);
    const final_preserved = try std.Io.Dir.cwd().readFileAlloc(std.testing.io, final_path, std.testing.allocator, .limited(64));
    defer std.testing.allocator.free(final_preserved);
    try std.testing.expectEqualStrings("complete request-bound marker", final_preserved);
}

