fn renderContextPlanJsonOutput(
    allocator: std.mem.Allocator,
    io: std.Io,
    store: storage.Store,
    args: ParsedContextArgs,
) ![]u8 {
    const options = contextSearchOptions(io, args);
    const plan_stats = try text_search.textQueryPlanStats(allocator, store, args.query, options);

    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);
    try writeJsonObjectStart(&out);
    var first = true;
    try writeJsonStringField(&out, "schema_version", "tinykg-agent-retrieval-v1", &first);
    try writeJsonStringField(&out, "mode", "context-plan", &first);

    try writeJsonFieldPrefix(&out, "query", &first);
    try out.writeAll("{");
    var query_first = true;
    try writeJsonStringField(&out, "text", args.query, &query_first);
    try writeJsonNullableNodeIdField(&out, "task_id", args.task_id, &query_first);
    try writeJsonNullableNodeIdField(&out, "root_node_id", args.root_node_id, &query_first);
    try writeJsonBoolField(&out, "include_history", args.include_history, &query_first);
    try out.writeAll("}");

    try writeJsonFieldPrefix(&out, "budget", &first);
    try renderContextBudgetJson(&out, args);

    try writeJsonFieldPrefix(&out, "plan", &first);
    try out.writeAll("{");
    var plan_first = true;
    try writeJsonStringField(&out, "score_model", "bm25", &plan_first);
    try writeJsonStringField(&out, "profile", textBudgetProfileName(args.profile), &plan_first);
    try writeJsonNumberField(&out, "query_terms", plan_stats.query_terms, &plan_first);
    try writeJsonNumberField(&out, "unique_query_terms", plan_stats.unique_query_terms, &plan_first);
    try writeJsonNumberField(&out, "matched_terms", plan_stats.matched_terms, &plan_first);
    try writeJsonNumberField(&out, "postings_planned", plan_stats.postings_count_total, &plan_first);
    try writeJsonNumberField(&out, "max_term_postings", plan_stats.max_postings_count, &plan_first);
    try writeJsonStringField(&out, "retrieval_order", "search -> focus metadata -> task packet -> neighbors -> markdown previews", &plan_first);
    try out.writeAll("}");

    try writeJsonFieldPrefix(&out, "steps", &first);
    try out.writeAll("[");
    try writeContextStep(&out, "search", "bounded bm25 over node texts", "find lexical anchors with scores and matched-term diagnostics");
    try out.writeAll(",");
    try writeContextStep(&out, "inspect_metadata", "selected task/node/search hits", "read schema, context_size, generation status, and local graph fanout before raw text");
    if (args.task_id != null) {
        try out.writeAll(",");
        try writeContextStep(&out, "task-packet", "bounded task DAG packet", "recover parent, dependencies, blockers, recent child rounds, and verification evidence");
    }
    try out.writeAll(",");
    try writeContextStep(&out, "neighbors", "bounded local subgraphs for focus nodes", "estimate expansion cost and gather adjacent graph context");
    try out.writeAll(",");
    try writeContextStep(&out, "render-md-doc", "bounded markdown previews for document nodes", "preview markdown without dumping full rendered documents");
    try out.writeAll("]");

    try writeJsonFieldPrefix(&out, "continuations", &first);
    try out.writeAll("[");
    try out.writeAll("{");
    var cont_first = true;
    try writeJsonStringField(&out, "action", "context-packet", &cont_first);
    try writeJsonStringField(&out, "reason", "execute this plan and return compact context sections", &cont_first);
    try writeJsonFieldPrefix(&out, "command", &cont_first);
    const suggested_max_postings = @max(args.max_postings_scanned, plan_stats.postings_count_total);
    try writeContextPacketCommand(&out, args, args.limit, suggested_max_postings, args.max_chars);
    try out.writeAll("}");
    try out.writeAll("]");

    try writeJsonObjectEnd(&out);
    return out.buffer.toOwnedSlice(allocator);
}

fn appendUniqueContextNodeId(allocator: std.mem.Allocator, node_ids: *std.ArrayList(core.NodeId), node_id: core.NodeId, max_len: usize) !bool {
    for (node_ids.items) |existing| {
        if (existing.toInt() == node_id.toInt()) return true;
    }
    if (node_ids.items.len >= max_len) return false;
    try node_ids.append(allocator, node_id);
    return true;
}

fn contextSubBudget(total: usize, roots: usize) usize {
    if (roots == 0) return total;
    return @max(@as(usize, 1), total / roots);
}

const ContextPacketTextBudget = struct {
    max_chars: usize,
    used_bytes: usize = 0,
    used_chars: usize = 0,
    used_lines: usize = 0,
    requested_bytes: usize = 0,
    requested_chars: usize = 0,
    requested_lines: usize = 0,
    truncated: bool = false,
    truncate_reason: ?[]const u8 = null,
    omitted_texts: usize = 0,

    fn take(self: *ContextPacketTextBudget, text: []const u8) !struct { text: []const u8, truncated: bool } {
        if (text.len == 0) return .{ .text = text, .truncated = false };
        const full_size = try computeTextContextSize(text);
        try self.addRequestedSize(full_size);
        if (self.used_chars <= self.max_chars and full_size.text_chars <= self.max_chars - self.used_chars) {
            try self.addSize(full_size);
            return .{ .text = text, .truncated = false };
        }
        self.markTruncated("max_chars");
        const remaining = self.max_chars -| self.used_chars;
        if (remaining == 0) {
            self.omitted_texts = std.math.add(usize, self.omitted_texts, 1) catch return error.RecordTooLarge;
            return .{ .text = "", .truncated = true };
        }
        const prefix_end = markdownUtf8PrefixEndByChars(text, 0, remaining);
        const prefix = text[0..prefix_end];
        try self.addSize(try computeTextContextSize(prefix));
        return .{ .text = prefix, .truncated = prefix.len < text.len };
    }

    fn addSize(self: *ContextPacketTextBudget, size: TextContextSize) !void {
        self.used_bytes = std.math.add(usize, self.used_bytes, size.text_bytes) catch return error.RecordTooLarge;
        self.used_chars = std.math.add(usize, self.used_chars, size.text_chars) catch return error.RecordTooLarge;
        self.used_lines = std.math.add(usize, self.used_lines, size.text_lines) catch return error.RecordTooLarge;
    }

    fn addRequestedSize(self: *ContextPacketTextBudget, size: TextContextSize) !void {
        self.requested_bytes = std.math.add(usize, self.requested_bytes, size.text_bytes) catch return error.RecordTooLarge;
        self.requested_chars = std.math.add(usize, self.requested_chars, size.text_chars) catch return error.RecordTooLarge;
        self.requested_lines = std.math.add(usize, self.requested_lines, size.text_lines) catch return error.RecordTooLarge;
    }

    fn markTruncated(self: *ContextPacketTextBudget, reason: []const u8) void {
        self.truncated = true;
        if (self.truncate_reason == null) self.truncate_reason = reason;
    }
};

fn renderContextPacketTextBudgetJson(out: *QueryOutputWriter, budget: ContextPacketTextBudget) !void {
    try out.writeAll("{");
    var first = true;
    try writeJsonFieldPrefix(out, "context_size", &first);
    try renderTextContextSizeAggregateJson(out, budget.used_bytes, budget.used_chars, budget.used_lines);
    try writeJsonFieldPrefix(out, "requested_context_size", &first);
    try renderTextContextSizeAggregateJson(out, budget.requested_bytes, budget.requested_chars, budget.requested_lines);
    try writeJsonNumberField(out, "max_chars", budget.max_chars, &first);
    try writeJsonBoolField(out, "truncated", budget.truncated, &first);
    try writeJsonNullableStringField(out, "truncate_reason", budget.truncate_reason, &first);
    try writeJsonNumberField(out, "omitted_texts", budget.omitted_texts, &first);
    try out.writeAll("}");
}

fn renderContextNodeObjectJson(
    out: *QueryOutputWriter,
    allocator: std.mem.Allocator,
    store: storage.Store,
    node: storage.StoredNode,
    budget: *ContextPacketTextBudget,
) !void {
    const kind_label = try nodeKindNameAlloc(allocator, node.kind);
    defer allocator.free(kind_label);
    const text_value = markdownProjectionVisibleText(node.text);
    const context_size = try computeTextContextSize(text_value);
    const logical_name = try store.getNodeStringProperty(allocator, node.id, "name");
    defer if (logical_name) |value| allocator.free(value);
    const logical_summary = try store.getNodeStringProperty(allocator, node.id, "summary");
    defer if (logical_summary) |value| allocator.free(value);
    const name_budget = try budget.take(logical_name orelse text_value);
    const deprecated_by = try nodeDeprecatedBy(store, node.id);
    const local_graph = try nodeLocalGraphStats(store, node.id);

    const schema_type = try store.getNodeStringProperty(allocator, node.id, "schema_type");
    defer if (schema_type) |value| allocator.free(value);
    const source_label = try store.getNodeStringProperty(allocator, node.id, "source_label");
    defer if (source_label) |v| allocator.free(v);
    const external_key = try store.getNodeStringProperty(allocator, node.id, "external_key");
    defer if (external_key) |value| allocator.free(value);

    try out.writeAll("{");
    var node_first = true;
    try writeJsonNumberField(out, "id", node.id.toInt(), &node_first);
    try writeJsonStringField(out, "kind", kind_label, &node_first);
    try writeJsonStringField(out, "name", name_budget.text, &node_first);
    try writeJsonBoolField(out, "name_truncated", name_budget.truncated, &node_first);

    try writeJsonFieldPrefix(out, "summary", &node_first);
    try out.writeAll("{");
    var summary_first = true;
    try writeJsonNullableStringField(out, "text", logical_summary, &summary_first);
    try writeJsonStringField(out, "source", if (logical_summary != null) "node_property" else "none", &summary_first);
    try writeJsonNullableStringField(out, "node_id", null, &summary_first);
    try writeJsonBoolField(out, "stale", false, &summary_first);
    try out.writeAll("}");

    try writeJsonFieldPrefix(out, "schema", &node_first);
    try out.writeAll("{");
    var schema_first = true;
    try writeJsonNullableStringField(out, "schema_type", schema_type, &schema_first);
    try writeJsonNullableStringField(out, "external_key", external_key, &schema_first);
    try writeJsonNullableStringField(out, "source_label", source_label, &schema_first);
    try out.writeAll("}");

    try writeJsonFieldPrefix(out, "context_size", &node_first);
    try renderTextContextSizeJson(out, context_size);

    try writeJsonFieldPrefix(out, "status", &node_first);
    try out.writeAll("{");
    var status_first = true;
    try writeJsonBoolField(out, "current_generation", deprecated_by == null, &status_first);
    try writeJsonFieldPrefix(out, "deprecated_by", &status_first);
    if (deprecated_by) |id| {
        try out.print("{}", .{id.toInt()});
    } else {
        try out.writeAll("null");
    }
    try out.writeAll("}");

    try writeJsonFieldPrefix(out, "expand", &node_first);
    try out.writeAll("{");
    var expand_first = true;
    try writeJsonBoolField(out, "has_text", node.text.len != 0, &expand_first);
    try writeJsonBoolField(out, "has_summary", logical_summary != null and logical_summary.?.len != 0, &expand_first);
    try writeJsonBoolField(out, "has_children", local_graph.out_degree != 0, &expand_first);
    try writeJsonStringField(out, "recommended", if (local_graph.out_degree != 0) "children_first" else "raw_text", &expand_first);
    try out.writeAll("}");

    try writeJsonFieldPrefix(out, "local_graph", &node_first);
    try out.writeAll("{");
    var graph_first = true;
    try writeJsonNumberField(out, "in_degree", local_graph.in_degree, &graph_first);
    try writeJsonNumberField(out, "out_degree", local_graph.out_degree, &graph_first);
    try out.writeAll("}");

    try out.writeAll("}");
}

fn renderContextSubgraphJson(
    out: *QueryOutputWriter,
    allocator: std.mem.Allocator,
    store: storage.Store,
    root_id: core.NodeId,
    result: SubgraphBuildResult,
    budget: *ContextPacketTextBudget,
) !void {
    var node_view = try store.openNodeRecordView();
    defer node_view.deinit();

    try out.writeAll("{");
    var first = true;
    try writeJsonNumberField(out, "root_id", root_id.toInt(), &first);
    try writeJsonFieldPrefix(out, "summary", &first);
    try out.writeAll("{");
    var summary_first = true;
    try writeJsonNumberField(out, "node_count", result.node_ids.items.len, &summary_first);
    try writeJsonNumberField(out, "edge_count", result.edges.items.len, &summary_first);
    try writeJsonNumberField(out, "backref_count", result.backrefs.items.len, &summary_first);
    try writeJsonBoolField(out, "truncated", result.truncated, &summary_first);
    try writeJsonNullableStringField(out, "truncate_reason", result.truncate_reason, &summary_first);
    try writeJsonNumberField(out, "used_nodes", result.node_ids.items.len, &summary_first);
    try writeJsonNumberField(out, "used_edges", subgraphUsedEdgeRefs(result), &summary_first);
    try writeJsonNumberField(out, "used_chars", result.used_chars, &summary_first);
    try writeJsonNumberField(out, "edges_scanned", result.scanned_edges, &summary_first);
    try writeJsonFieldPrefix(out, "context_size", &summary_first);
    try renderTextContextSizeAggregateJson(out, result.used_bytes, result.used_chars, result.used_lines);
    try out.writeAll("}");

    try writeJsonFieldPrefix(out, "nodes", &first);
    try out.writeAll("[");
    for (result.node_ids.items, 0..) |node_id, index| {
        if (index != 0) try out.writeAll(",");
        var node = (try node_view.readNodeById(allocator, node_id)) orelse return error.InvalidRecord;
        defer node.deinit(allocator);
        try renderContextNodeObjectJson(out, allocator, store, node, budget);
    }
    try out.writeAll("]");

    try writeJsonFieldPrefix(out, "edges", &first);
    try out.writeAll("[");
    for (result.edges.items, 0..) |edge, index| {
        if (index != 0) try out.writeAll(",");
        try renderSubgraphEdgeJson(out, allocator, store, edge);
    }
    try out.writeAll("]");

    try writeJsonFieldPrefix(out, "backrefs", &first);
    try out.writeAll("[");
    for (result.backrefs.items, 0..) |edge, index| {
        if (index != 0) try out.writeAll(",");
        try renderSubgraphEdgeJson(out, allocator, store, edge);
    }
    try out.writeAll("]");

    try writeJsonFieldPrefix(out, "omitted", &first);
    try out.writeAll("[");
    for (result.omitted.items, 0..) |item, index| {
        if (index != 0) try out.writeAll(",");
        try renderSubgraphOmittedJson(out, item);
    }
    try out.writeAll("]");
    try out.writeAll("}");
}

fn renderContextTaskPacketJson(
    out: *QueryOutputWriter,
    allocator: std.mem.Allocator,
    store: storage.Store,
    task_id: core.NodeId,
    args: ParsedContextArgs,
    budget: *ContextPacketTextBudget,
) !void {
    var task_node = (try store.readNodeById(allocator, task_id)) orelse return core.Error.NotFound;
    defer task_node.deinit(allocator);
    if (task_node.kind != .task) return core.Error.InvalidId;

    const now_ns = try u128ToU64(persistentNowNs(store.io));
    const lifecycle = try task.statusForStoredNode(allocator, store, task_node, now_ns);
    const state: ?task.ReadyState = if (lifecycle.isTerminal()) null else try task.readyStateWithPersistentStoreAt(allocator, store, task_id, now_ns);
    const packet_args = ParsedTaskPacketArgs{
        .task_id = "",
        .limit = args.limit,
        .format = .json,
        .meta = true,
        .max_nodes = args.max_nodes,
        .max_edges = args.max_edges,
        .max_chars = args.max_chars,
    };
    const task_budget = taskPacketJsonBudget(packet_args);
    var result = try buildTaskPacketSubgraph(allocator, store, task_id, packet_args, task_budget);
    defer result.deinit(allocator);

    try out.writeAll("{");
    var first = true;
    try writeJsonNumberField(out, "task_id", task_id.toInt(), &first);
    try writeJsonStringField(out, "status", @tagName(lifecycle), &first);
    try writeJsonNullableStringField(out, "readiness", if (state) |value| @tagName(value) else null, &first);
    try writeJsonFieldPrefix(out, "root", &first);
    try renderContextNodeObjectJson(out, allocator, store, task_node, budget);
    try writeJsonFieldPrefix(out, "subgraph", &first);
    try renderContextSubgraphJson(out, allocator, store, task_id, result, budget);
    try out.writeAll("}");
}

fn renderContextMarkdownPreviewJson(
    out: *QueryOutputWriter,
    allocator: std.mem.Allocator,
    store: storage.Store,
    node: storage.StoredNode,
    preview_lines: usize,
    budget: *ContextPacketTextBudget,
) !void {
    const rendered = try renderMarkdownDocument(allocator, store, node.id);
    defer allocator.free(rendered);
    const rendered_size = try computeTextContextSize(rendered);
    const preview = markdownPreviewPrefixLen(rendered, preview_lines);
    const section_stats = try markdownSubtreeSectionStats(allocator, store, node.id);

    try out.writeAll("{");
    var first = true;
    try writeJsonNumberField(out, "node_id", node.id.toInt(), &first);
    try writeJsonFieldPrefix(out, "node", &first);
    try renderContextNodeObjectJson(out, allocator, store, node, budget);
    try writeJsonFieldPrefix(out, "rendered_markdown", &first);
    try out.writeAll("{");
    var rendered_first = true;
    try writeJsonFieldPrefix(out, "context_size", &rendered_first);
    try renderTextContextSizeJson(out, rendered_size);
    const preview_budget = try budget.take(rendered[0..preview.len]);
    const preview_size = try computeTextContextSize(preview_budget.text);
    const preview_truncated = preview.truncated or preview_budget.truncated;
    const preview_truncate_reason: ?[]const u8 = if (preview_budget.truncated) "max_chars" else if (preview.truncated) "preview_lines" else null;
    try writeJsonNumberField(out, "preview_lines", if (preview_budget.truncated) preview_size.text_lines else preview.lines, &rendered_first);
    try writeJsonBoolField(out, "truncated", preview_truncated, &rendered_first);
    try writeJsonNullableStringField(out, "truncate_reason", preview_truncate_reason, &rendered_first);
    try writeJsonStringField(out, "preview", preview_budget.text, &rendered_first);
    try out.writeAll("}");
    try writeJsonFieldPrefix(out, "sections", &first);
    try out.writeAll("{");
    var sections_first = true;
    try writeJsonNumberField(out, "section_count", section_stats.section_count, &sections_first);
    try writeJsonFieldPrefix(out, "context_size", &sections_first);
    try renderTextContextSizeJson(out, section_stats.context_size);
    try out.writeAll("}");
    try out.writeAll("}");
}

fn renderContextPacketJsonOutput(
    allocator: std.mem.Allocator,
    io: std.Io,
    store: storage.Store,
    edge_retention_registry: *storage.EdgeSegmentRetentionRegistry,
    args: ParsedContextArgs,
) ![]u8 {
    const options = contextSearchOptions(io, args);
    const plan_stats = try text_search.textQueryPlanStats(allocator, store, args.query, options);
    var maybe_hits = text_search.searchText(allocator, store, args.query, options) catch |err| switch (err) {
        core.Error.BudgetExceeded => null,
        else => |e| return e,
    };
    defer if (maybe_hits) |*hits| hits.deinit(allocator);
    const search_budget_exceeded = maybe_hits == null;
    if (maybe_hits) |*hits| {
        if (args.profile == .agent_memory) {
            std.mem.sort(text_search.TextSearchHit, hits.items, {}, textSearchHitAgentMemoryLessThan);
        }
    }

    var selected_hits = std.ArrayList(text_search.TextSearchHit).empty;
    defer selected_hits.deinit(allocator);
    var focus_node_ids = std.ArrayList(core.NodeId).empty;
    defer focus_node_ids.deinit(allocator);
    if (args.task_id) |id| _ = try appendUniqueContextNodeId(allocator, &focus_node_ids, id, args.max_nodes);
    if (args.root_node_id) |id| _ = try appendUniqueContextNodeId(allocator, &focus_node_ids, id, args.max_nodes);

    var node_view = try store.openNodeRecordView();
    defer node_view.deinit();
    var omitted_history: usize = 0;
    if (maybe_hits) |hits| {
        for (hits.items) |hit| {
            if (selected_hits.items.len >= args.limit) break;
            if (!args.include_history and !try nodeIsCurrentGeneration(store, hit.node_id)) {
                omitted_history += 1;
                continue;
            }
            try selected_hits.append(allocator, hit);
            _ = try appendUniqueContextNodeId(allocator, &focus_node_ids, hit.node_id, args.max_nodes);
        }
    }

    const roots = @max(@as(usize, 1), focus_node_ids.items.len);
    const per_root_nodes = contextSubBudget(args.max_nodes, roots);
    const per_root_edges = contextSubBudget(args.max_edges, roots);
    const per_root_chars = contextSubBudget(args.max_chars, roots);
    var packet_text_budget = ContextPacketTextBudget{ .max_chars = args.max_chars };

    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);
    try writeJsonObjectStart(&out);
    var first = true;
    try writeJsonStringField(&out, "schema_version", "tinykg-agent-retrieval-v1", &first);
    try writeJsonStringField(&out, "mode", "context-packet", &first);

    try writeJsonFieldPrefix(&out, "query", &first);
    try out.writeAll("{");
    var query_first = true;
    try writeJsonStringField(&out, "text", args.query, &query_first);
    try writeJsonNullableNodeIdField(&out, "task_id", args.task_id, &query_first);
    try writeJsonNullableNodeIdField(&out, "root_node_id", args.root_node_id, &query_first);
    try writeJsonBoolField(&out, "include_history", args.include_history, &query_first);
    try out.writeAll("}");

    try writeJsonFieldPrefix(&out, "budget", &first);
    try renderContextBudgetJson(&out, args);

    try writeJsonFieldPrefix(&out, "search", &first);
    try out.writeAll("{");
    var search_first = true;
    try writeJsonFieldPrefix(&out, "plan", &search_first);
    try out.writeAll("{");
    var plan_first = true;
    try writeJsonStringField(&out, "score_model", "bm25", &plan_first);
    try writeJsonStringField(&out, "profile", textBudgetProfileName(args.profile), &plan_first);
    try writeJsonNumberField(&out, "query_terms", plan_stats.query_terms, &plan_first);
    try writeJsonNumberField(&out, "unique_query_terms", plan_stats.unique_query_terms, &plan_first);
    try writeJsonNumberField(&out, "matched_terms", plan_stats.matched_terms, &plan_first);
    try writeJsonNumberField(&out, "postings_planned", plan_stats.postings_count_total, &plan_first);
    try writeJsonNumberField(&out, "max_term_postings", plan_stats.max_postings_count, &plan_first);
    try out.writeAll("}");
    try writeJsonFieldPrefix(&out, "hits", &search_first);
    try out.writeAll("[");
    var used_chars: usize = 0;
    for (selected_hits.items, 0..) |hit, index| {
        if (index != 0) try out.writeAll(",");
        var node = (try node_view.readNodeById(allocator, hit.node_id)) orelse return error.InvalidRecord;
        defer node.deinit(allocator);
        const size = try computeTextContextSize(node.text);
        used_chars = std.math.add(usize, used_chars, size.text_chars) catch return error.RecordTooLarge;
        try out.writeAll("{");
        var hit_first = true;
        try writeJsonNumberField(&out, "rank", index + 1, &hit_first);
        try writeJsonFieldPrefix(&out, "score", &hit_first);
        try out.print("{d:.6}", .{hit.score});
        try writeJsonFieldPrefix(&out, "node", &hit_first);
        try renderContextNodeObjectJson(&out, allocator, store, node, &packet_text_budget);
        try out.writeAll("}");
    }
    try out.writeAll("]");
    try writeJsonFieldPrefix(&out, "summary", &search_first);
    try out.writeAll("{");
    var search_summary_first = true;
    try writeJsonNumberField(&out, "hit_count", selected_hits.items.len, &search_summary_first);
    const candidate_count = if (maybe_hits) |hits| hits.items.len else @as(usize, 0);
    const search_truncated = search_budget_exceeded or selected_hits.items.len < candidate_count - omitted_history;
    try writeJsonNumberField(&out, "candidate_count", candidate_count, &search_summary_first);
    try writeJsonNumberField(&out, "omitted_history", omitted_history, &search_summary_first);
    try writeJsonBoolField(&out, "budget_exceeded", search_budget_exceeded, &search_summary_first);
    try writeJsonBoolField(&out, "truncated", search_truncated, &search_summary_first);
    try writeJsonNullableStringField(&out, "truncate_reason", if (search_budget_exceeded) "max_postings" else if (search_truncated) "max_search_hits" else null, &search_summary_first);
    try writeJsonNumberField(&out, "used_chars", used_chars, &search_summary_first);
    try out.writeAll("}");
    try out.writeAll("}");

    try writeJsonFieldPrefix(&out, "focus_nodes", &first);
    try out.writeAll("[");
    for (focus_node_ids.items, 0..) |node_id, index| {
        if (index != 0) try out.writeAll(",");
        var node = (try node_view.readNodeById(allocator, node_id)) orelse return error.InvalidRecord;
        defer node.deinit(allocator);
        try renderContextNodeObjectJson(&out, allocator, store, node, &packet_text_budget);
    }
    try out.writeAll("]");

    try writeJsonFieldPrefix(&out, "task_packet", &first);
    if (args.task_id) |task_id| {
        try renderContextTaskPacketJson(&out, allocator, store, task_id, args, &packet_text_budget);
    } else {
        try out.writeAll("null");
    }

    try writeJsonFieldPrefix(&out, "neighbor_subgraphs", &first);
    try out.writeAll("[");
    for (focus_node_ids.items, 0..) |node_id, index| {
        if (index != 0) try out.writeAll(",");
        const neighbor_args = ParsedNeighborsArgs{
            .node_id = "",
            .include_history = args.include_history,
            .format = .json,
            .meta = true,
            .depth = args.neighbor_depth,
            .max_nodes = per_root_nodes,
            .max_edges = per_root_edges,
            .max_chars = per_root_chars,
        };
        const budget = neighborsJsonBudget(neighbor_args);
        var result = try buildNeighborsSubgraph(allocator, store, edge_retention_registry, node_id, null, neighbor_args, budget);
        defer result.deinit(allocator);
        try renderContextSubgraphJson(&out, allocator, store, node_id, result, &packet_text_budget);
    }
    try out.writeAll("]");

    try writeJsonFieldPrefix(&out, "markdown_previews", &first);
    try out.writeAll("[");
    var preview_first = true;
    var first_markdown_node_id: ?core.NodeId = null;
    for (focus_node_ids.items) |node_id| {
        var node = (try node_view.readNodeById(allocator, node_id)) orelse return error.InvalidRecord;
        defer node.deinit(allocator);
        if (node.kind != .document and node.kind != .document_section) continue;
        if (first_markdown_node_id == null) first_markdown_node_id = node_id;
        if (!preview_first) try out.writeAll(",");
        preview_first = false;
        try renderContextMarkdownPreviewJson(&out, allocator, store, node, args.markdown_preview_lines, &packet_text_budget);
    }
    try out.writeAll("]");

    try writeJsonFieldPrefix(&out, "packet_summary", &first);
    try renderContextPacketTextBudgetJson(&out, packet_text_budget);

    try writeJsonFieldPrefix(&out, "continuations", &first);
    try out.writeAll("[");
    var continuation_first = true;
    const recommended_postings = @max(args.max_postings_scanned, plan_stats.postings_count_total);
    if (search_budget_exceeded) {
        if (!continuation_first) try out.writeAll(",");
        continuation_first = false;
        var cont_first = try writeContextCommandContinuationPrefix(&out, "context-packet", "search exceeded max_postings; rerun with planned postings budget or refine query");
        try writeJsonFieldPrefix(&out, "command", &cont_first);
        try writeContextPacketCommand(&out, args, args.limit, recommended_postings, args.max_chars);
        try writeJsonNumberField(&out, "postings_planned", plan_stats.postings_count_total, &cont_first);
        try writeJsonNumberField(&out, "current_max_postings", args.max_postings_scanned, &cont_first);
        try out.writeAll("}");
    } else if (search_truncated) {
        if (!continuation_first) try out.writeAll(",");
        continuation_first = false;
        const recommended_limit = @max(args.limit +| 1, candidate_count -| omitted_history);
        var cont_first = try writeContextCommandContinuationPrefix(&out, "context-packet", "search hits were truncated; raise --limit only if current anchors are insufficient");
        try writeJsonFieldPrefix(&out, "command", &cont_first);
        try writeContextPacketCommand(&out, args, recommended_limit, args.max_postings_scanned, args.max_chars);
        try writeJsonNumberField(&out, "current_limit", args.limit, &cont_first);
        try writeJsonNumberField(&out, "suggested_limit", recommended_limit, &cont_first);
        try out.writeAll("}");
    }
    if (packet_text_budget.truncated) {
        if (!continuation_first) try out.writeAll(",");
        continuation_first = false;
        const recommended_max_chars = @max(packet_text_budget.requested_chars, args.max_chars +| 1);
        var cont_first = try writeContextCommandContinuationPrefix(&out, "context-packet", "packet text payload reached max_chars; rerun with suggested_max_chars to fit the same packet shape, or reduce focus nodes");
        try writeJsonFieldPrefix(&out, "command", &cont_first);
        try writeContextPacketCommand(&out, args, args.limit, args.max_postings_scanned, recommended_max_chars);
        try writeJsonNumberField(&out, "current_max_chars", args.max_chars, &cont_first);
        try writeJsonNumberField(&out, "suggested_max_chars", recommended_max_chars, &cont_first);
        try out.writeAll("}");
    }
    if (focus_node_ids.items.len != 0) {
        if (!continuation_first) try out.writeAll(",");
        continuation_first = false;
        var cont_first = try writeContextCommandContinuationPrefix(&out, "neighbors", "expand graph around first focus node if local subgraph was insufficient");
        try writeJsonFieldPrefix(&out, "command", &cont_first);
        try writeNeighborsCommand(&out, args, focus_node_ids.items[0]);
        try out.writeAll("}");
    }
    if (first_markdown_node_id) |node_id| {
        if (!continuation_first) try out.writeAll(",");
        continuation_first = false;
        var cont_first = try writeContextCommandContinuationPrefix(&out, "render-md-doc", "retrieve markdown for the first document focus after preview confirms relevance");
        try writeJsonFieldPrefix(&out, "command", &cont_first);
        try writeRenderMarkdownCommand(&out, args, node_id);
        try out.writeAll("}");
    }
    if (continuation_first) {
        var cont_first = try writeContextCommandContinuationPrefix(&out, "context-plan", "refine the lexical query because no focus node was selected");
        try writeJsonFieldPrefix(&out, "command", &cont_first);
        try writeContextPlanCommand(&out, args, args.limit, args.max_postings_scanned, args.max_chars);
        try out.writeAll("}");
    }
    try out.writeAll("]");

    try writeJsonObjectEnd(&out);
    return out.buffer.toOwnedSlice(allocator);
}

fn textBudgetProfileName(profile: TextBudgetProfile) []const u8 {
    return switch (profile) {
        .interactive => "interactive",
        .agent_memory => "agent-memory",
    };
}

fn writeSearchContinuation(out: *QueryOutputWriter, action: []const u8, node_id: core.NodeId, reason: []const u8) !void {
    try out.writeAll("{");
    var first = true;
    try writeJsonStringField(out, "action", action, &first);
    try writeJsonNumberField(out, "node_id", node_id.toInt(), &first);
    try writeJsonStringField(out, "reason", reason, &first);
    try out.writeAll("}");
}

fn nodeIsCurrentGeneration(store: storage.Store, node_id: core.NodeId) !bool {
    return (try nodeDeprecatedBy(store, node_id)) == null;
}

fn currentGenerationLookupCandidateLimit(output_limit: usize) usize {
    if (output_limit == 0) return 0;
    const max_candidate_limit: usize = 4096;
    const expanded = std.math.add(usize, std.math.mul(usize, output_limit, 4) catch max_candidate_limit, 32) catch max_candidate_limit;
    return @min(max_candidate_limit, @max(output_limit, expanded));
}

fn searchCandidateLimit(profile: TextBudgetProfile, kind_filter: ?core.NodeKind, output_limit: usize, include_history: bool) usize {
    if (output_limit == 0) return 0;
    if (include_history) return output_limit;
    const agent_memory_candidate_limit: usize = 4096;
    if (profile != .agent_memory) {
        const expanded = std.math.add(usize, std.math.mul(usize, output_limit, 4) catch agent_memory_candidate_limit, 32) catch agent_memory_candidate_limit;
        return @min(agent_memory_candidate_limit, @max(output_limit, expanded));
    }
    if (kind_filter != null) {
        const expanded = std.math.add(usize, std.math.mul(usize, output_limit, 4) catch agent_memory_candidate_limit, 32) catch agent_memory_candidate_limit;
        return @min(agent_memory_candidate_limit, @max(output_limit, expanded));
    }
    const expanded = std.math.add(usize, std.math.mul(usize, output_limit, 8) catch agent_memory_candidate_limit, 32) catch agent_memory_candidate_limit;
    return @min(agent_memory_candidate_limit, @max(@as(usize, 256), @max(output_limit, expanded)));
}

fn textSearchHitAgentMemoryLessThan(_: void, lhs: text_search.TextSearchHit, rhs: text_search.TextSearchHit) bool {
    const lhs_rank = agentMemorySearchKindRank(lhs.kind);
    const rhs_rank = agentMemorySearchKindRank(rhs.kind);
    if (lhs_rank != rhs_rank) return lhs_rank < rhs_rank;
    const lhs_finite = std.math.isFinite(lhs.score);
    const rhs_finite = std.math.isFinite(rhs.score);
    if (lhs_finite != rhs_finite) return lhs_finite;
    if (lhs_finite and lhs.score != rhs.score) return lhs.score > rhs.score;
    return lhs.node_id.toInt() < rhs.node_id.toInt();
}

fn agentMemorySearchKindRank(kind: core.NodeKind) u8 {
    return switch (kind) {
        .decision,
        .concept,
        .verification,
        .fix,
        .error_event,
        .task,
        .command,
        .user_preference,
        .observation,
        => 0,
        .repo,
        .directory,
        .file,
        .symbol,
        .function,
        .type_decl,
        .relation_kind,
        .relation_policy,
        .edit,
        => 1,
        .evidence,
        .image,
        .media,
        => 2,
        .document,
        .document_section,
        => 3,
        else => 1,
    };
}

fn renderNodeMetadataJson(
    out: *QueryOutputWriter,
    allocator: std.mem.Allocator,
    store: storage.Store,
    registry: ?schema.Registry,
    node: storage.StoredNode,
    include_text: bool,
) !void {
    try writeJsonObjectStart(out);
    var first = true;
    try writeJsonStringField(out, "schema_version", "tinykg-agent-retrieval-v1", &first);
    try writeJsonBoolField(out, "found", true, &first);
    try writeJsonFieldPrefix(out, "node", &first);
    try renderNodeObjectJsonWithSchema(out, allocator, store, registry, node, include_text);
    try writeJsonObjectEnd(out);
}

fn renderNodeObjectJson(
    out: *QueryOutputWriter,
    allocator: std.mem.Allocator,
    store: storage.Store,
    node: storage.StoredNode,
    include_text: bool,
) !void {
    return renderNodeObjectJsonWithSchema(out, allocator, store, null, node, include_text);
}

fn renderNodeObjectJsonWithSchema(
    out: *QueryOutputWriter,
    allocator: std.mem.Allocator,
    store: storage.Store,
    registry: ?schema.Registry,
    node: storage.StoredNode,
    include_text: bool,
) !void {
    const kind_label = try nodeKindNameWithSchemaAlloc(allocator, registry, node.kind);
    defer allocator.free(kind_label);
    const text_value = markdownProjectionVisibleText(node.text);
    const context_size = try computeTextContextSize(text_value);
    const deprecated_by = try nodeDeprecatedBy(store, node.id);
    const local_graph = try nodeLocalGraphStats(store, node.id);

    const logical_name = try store.getNodeStringProperty(allocator, node.id, "name");
    defer if (logical_name) |value| allocator.free(value);
    const logical_summary = try store.getNodeStringProperty(allocator, node.id, "summary");
    defer if (logical_summary) |value| allocator.free(value);
    const schema_type = try store.getNodeStringProperty(allocator, node.id, "schema_type");
    defer if (schema_type) |value| allocator.free(value);
    const source_label = try store.getNodeStringProperty(allocator, node.id, "source_label");
    defer if (source_label) |v| allocator.free(v);
    const external_key = try store.getNodeStringProperty(allocator, node.id, "external_key");
    defer if (external_key) |value| allocator.free(value);

    try out.writeAll("{");
    var node_first = true;
    try writeJsonNumberField(out, "id", node.id.toInt(), &node_first);
    try writeJsonStringField(out, "kind", kind_label, &node_first);
    try writeJsonStringField(out, "name", logical_name orelse "", &node_first);

    try writeJsonFieldPrefix(out, "summary", &node_first);
    try out.writeAll("{");
    var summary_first = true;
    try writeJsonNullableStringField(out, "text", logical_summary, &summary_first);
    try writeJsonStringField(out, "source", if (logical_summary != null) "node_property" else "none", &summary_first);
    try writeJsonNullableStringField(out, "node_id", null, &summary_first);
    try writeJsonBoolField(out, "stale", false, &summary_first);
    try out.writeAll("}");

    try writeJsonFieldPrefix(out, "schema", &node_first);
    try out.writeAll("{");
    var schema_first = true;
    try writeJsonNullableStringField(out, "schema_type", schema_type, &schema_first);
    try writeJsonNullableStringField(out, "external_key", external_key, &schema_first);
    try writeJsonNullableStringField(out, "source_label", source_label, &schema_first);
    try out.writeAll("}");

    try writeJsonFieldPrefix(out, "context_size", &node_first);
    try renderTextContextSizeJson(out, context_size);

    try writeJsonFieldPrefix(out, "status", &node_first);
    try out.writeAll("{");
    var status_first = true;
    try writeJsonBoolField(out, "current_generation", deprecated_by == null, &status_first);
    try writeJsonFieldPrefix(out, "deprecated_by", &status_first);
    if (deprecated_by) |next| {
        try out.print("{}", .{next.toInt()});
    } else {
        try out.writeAll("null");
    }
    try out.writeAll("}");

    try writeJsonFieldPrefix(out, "expand", &node_first);
    try out.writeAll("{");
    var expand_first = true;
    try writeJsonBoolField(out, "has_text", node.text.len != 0, &expand_first);
    try writeJsonBoolField(out, "has_summary", logical_summary != null and logical_summary.?.len != 0, &expand_first);
    try writeJsonBoolField(out, "has_children", local_graph.out_degree != 0, &expand_first);
    try writeJsonStringField(out, "recommended", if (local_graph.out_degree != 0) "children_first" else "raw_text", &expand_first);
    try out.writeAll("}");

    try writeJsonFieldPrefix(out, "local_graph", &node_first);
    try out.writeAll("{");
    var graph_first = true;
    try writeJsonNumberField(out, "in_degree", local_graph.in_degree, &graph_first);
    try writeJsonNumberField(out, "out_degree", local_graph.out_degree, &graph_first);
    try out.writeAll("}");

    if (include_text) try writeJsonStringField(out, "text", text_value, &node_first);
    try out.writeAll("}");
}

fn renderNodeByIdOutput(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_id: core.NodeId,
    args: ParsedGetArgs,
) ![]u8 {
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);

    var node = (try store.readNodeById(allocator, node_id)) orelse {
        if (args.format == .json) {
            try writeJsonObjectStart(&out);
            var first = true;
            try writeJsonStringField(&out, "schema_version", "tinykg-agent-retrieval-v1", &first);
            try writeJsonNumberField(&out, "id", node_id.toInt(), &first);
            try writeJsonBoolField(&out, "found", false, &first);
            try writeJsonObjectEnd(&out);
            return out.buffer.toOwnedSlice(allocator);
        }
        try out.writeAll("not found\n");
        return out.buffer.toOwnedSlice(allocator);
    };
    defer node.deinit(allocator);

    var embedded_catalog = try store.readCatalog();
    defer if (embedded_catalog) |*cat| cat.deinit();
    const registry: ?schema.Registry = if (embedded_catalog) |cat| cat.registry else null;

    if (args.format == .json) {
        try renderNodeMetadataJson(&out, allocator, store, registry, node, args.include_text);
        return out.buffer.toOwnedSlice(allocator);
    }

    try out.print("{}\t", .{node.id.toInt()});
    try writeNodeKindNameWithSchema(&out, registry, node.kind);
    try out.writeAll("\t");
    try writeEscapedText(&out, node.text);
    try out.writeAll("\n");
    return out.buffer.toOwnedSlice(allocator);
}

fn renderNodeByIdOutputWithRepair(
    allocator: std.mem.Allocator,
    store: *storage.Store,
    node_id: core.NodeId,
    args: ParsedGetArgs,
) ![]u8 {
    return renderNodeByIdOutput(allocator, store.*, node_id, args) catch |err| switch (err) {
        error.FileNotFound, error.InvalidRecord => retry: {
            try store.repairPersistentIndexesFromLog();
            break :retry try renderNodeByIdOutput(allocator, store.*, node_id, args);
        },
        else => |e| return e,
    };
}

const NeighborsJsonBudget = struct {
    max_depth: usize,
    max_nodes: usize,
    max_edges: usize,
    max_chars: usize,
    timeout_ms: u64 = (core.QueryBudget{}).timeout_ms,
};

const SubgraphEdgeRole = enum { tree, backref };

const SubgraphEdgeRef = struct {
    edge_id: core.EdgeId,
    src: core.NodeId,
    rel: core.RelKind,
    dst: core.NodeId,
    depth: usize,
    role: SubgraphEdgeRole,
    direction: []const u8 = "outgoing",
    view_role: []const u8 = "",
};

const SubgraphOmittedItem = struct {
    reason: []const u8,
    edge_id: ?core.EdgeId = null,
    src: ?core.NodeId = null,
    dst: ?core.NodeId = null,
    depth: usize,
};

const SubgraphTraversalItem = struct {
    node_id: core.NodeId,
    depth: usize,
};

const SubgraphBuildResult = struct {
    node_ids: std.ArrayList(core.NodeId) = .empty,
    edges: std.ArrayList(SubgraphEdgeRef) = .empty,
    backrefs: std.ArrayList(SubgraphEdgeRef) = .empty,
    omitted: std.ArrayList(SubgraphOmittedItem) = .empty,
    used_bytes: usize = 0,
    used_chars: usize = 0,
    used_lines: usize = 0,
    scanned_edges: usize = 0,
    truncated: bool = false,
    truncate_reason: ?[]const u8 = null,

    pub fn deinit(self: *SubgraphBuildResult, allocator: std.mem.Allocator) void {
        self.node_ids.deinit(allocator);
        self.edges.deinit(allocator);
        self.backrefs.deinit(allocator);
        self.omitted.deinit(allocator);
    }
};

fn subgraphUsedEdgeRefs(result: SubgraphBuildResult) usize {
    return result.edges.items.len + result.backrefs.items.len;
}

fn neighborsJsonBudget(args: ParsedNeighborsArgs) NeighborsJsonBudget {
    const default_max_edges = args.max_edges orelse args.limit orelse (core.QueryBudget{}).max_results;
    const default_max_nodes = args.max_nodes orelse @min(default_max_edges + 1, (core.QueryBudget{}).max_results);
    return .{
        .max_depth = args.depth,
        .max_nodes = default_max_nodes,
        .max_edges = default_max_edges,
        .max_chars = args.max_chars orelse 200_000,
    };
}

fn markSubgraphTruncated(result: *SubgraphBuildResult, reason: []const u8) void {
    result.truncated = true;
    if (result.truncate_reason == null) result.truncate_reason = reason;
}

fn appendSubgraphOmitted(
    allocator: std.mem.Allocator,
    result: *SubgraphBuildResult,
    reason: []const u8,
    edge_id: ?core.EdgeId,
    src: ?core.NodeId,
    dst: ?core.NodeId,
    depth: usize,
) !void {
    try result.omitted.append(allocator, .{
        .reason = reason,
        .edge_id = edge_id,
        .src = src,
        .dst = dst,
        .depth = depth,
    });
    markSubgraphTruncated(result, reason);
}

fn tryAddSubgraphNode(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_view: *storage.Store.NodeRecordView,
    result: *SubgraphBuildResult,
    visited_nodes: *std.AutoHashMap(u64, void),
    queue: ?*std.ArrayList(SubgraphTraversalItem),
    node_id: core.NodeId,
    depth: usize,
    budget: NeighborsJsonBudget,
    include_history: bool,
) !bool {
    if (visited_nodes.contains(node_id.toInt())) return true;
    if (!include_history and !try nodeIsCurrentGeneration(store, node_id)) {
        try appendSubgraphOmitted(allocator, result, "history", null, null, node_id, depth);
        return false;
    }
    if (result.node_ids.items.len >= budget.max_nodes) {
        try appendSubgraphOmitted(allocator, result, "max_nodes", null, null, node_id, depth);
        return false;
    }

    var node = (try node_view.readNodeById(allocator, node_id)) orelse return core.Error.NotFound;
    defer node.deinit(allocator);
    const size = try computeTextContextSize(node.text);
    if (result.used_chars > budget.max_chars or size.text_chars > budget.max_chars - result.used_chars) {
        try appendSubgraphOmitted(allocator, result, "max_chars", null, null, node_id, depth);
        return false;
    }

    try visited_nodes.put(node_id.toInt(), {});
    try result.node_ids.append(allocator, node_id);
    result.used_bytes = std.math.add(usize, result.used_bytes, size.text_bytes) catch return error.RecordTooLarge;
    result.used_chars = std.math.add(usize, result.used_chars, size.text_chars) catch return error.RecordTooLarge;
    result.used_lines = std.math.add(usize, result.used_lines, size.text_lines) catch return error.RecordTooLarge;
    if (queue) |pending| {
        if (depth < budget.max_depth) try pending.append(allocator, .{ .node_id = node_id, .depth = depth });
    }
    return true;
}

fn buildNeighborsSubgraph(
    allocator: std.mem.Allocator,
    store: storage.Store,
    edge_retention_registry: *storage.EdgeSegmentRetentionRegistry,
    root_id: core.NodeId,
    rel_filter: ?core.RelKind,
    args: ParsedNeighborsArgs,
    budget: NeighborsJsonBudget,
) !SubgraphBuildResult {
    var result = SubgraphBuildResult{};
    errdefer result.deinit(allocator);

    var node_view = try store.openNodeRecordView();
    defer node_view.deinit();
    var visited_nodes = std.AutoHashMap(u64, void).init(allocator);
    defer visited_nodes.deinit();
    var visited_edges = std.AutoHashMap(u64, void).init(allocator);
    defer visited_edges.deinit();
    var queue = std.ArrayList(SubgraphTraversalItem).empty;
    defer queue.deinit(allocator);

    _ = try tryAddSubgraphNode(allocator, store, &node_view, &result, &visited_nodes, &queue, root_id, 0, budget, args.include_history);

    var cursor: usize = 0;
    while (cursor < queue.items.len) : (cursor += 1) {
        const current = queue.items[cursor];
        if (current.depth >= budget.max_depth) continue;
        if (subgraphUsedEdgeRefs(result) >= budget.max_edges) {
            markSubgraphTruncated(&result, "max_edges");
            break;
        }

        const remaining_edges = budget.max_edges - subgraphUsedEdgeRefs(result);
        var neighbor_result = try query.neighborsWithPersistentStoreRetained(allocator, store, edge_retention_registry, current.node_id, rel_filter, .{
            .max_results = remaining_edges + 1,
            .max_visited_edges = remaining_edges + 1,
            .timeout_ms = budget.timeout_ms,
        });
        defer neighbor_result.deinit(allocator);
        result.scanned_edges = std.math.add(usize, result.scanned_edges, neighbor_result.stats.edges_visited) catch return error.RecordTooLarge;
        if (neighbor_result.stats.budget_exceeded) markSubgraphTruncated(&result, "max_edges");

        for (neighbor_result.neighbors.items) |neighbor| {
            if (visited_edges.contains(neighbor.edge_id.toInt())) continue;
            if (subgraphUsedEdgeRefs(result) >= budget.max_edges) {
                try appendSubgraphOmitted(allocator, &result, "max_edges", neighbor.edge_id, current.node_id, neighbor.node_id, current.depth + 1);
                break;
            }
            try visited_edges.put(neighbor.edge_id.toInt(), {});

            if (visited_nodes.contains(neighbor.node_id.toInt())) {
                try result.backrefs.append(allocator, .{
                    .edge_id = neighbor.edge_id,
                    .src = current.node_id,
                    .rel = neighbor.rel,
                    .dst = neighbor.node_id,
                    .depth = current.depth + 1,
                    .role = .backref,
                });
                continue;
            }

            const added = try tryAddSubgraphNode(allocator, store, &node_view, &result, &visited_nodes, &queue, neighbor.node_id, current.depth + 1, budget, args.include_history);
            if (!added) continue;
            try result.edges.append(allocator, .{
                .edge_id = neighbor.edge_id,
                .src = current.node_id,
                .rel = neighbor.rel,
                .dst = neighbor.node_id,
                .depth = current.depth + 1,
                .role = .tree,
            });
        }
    }

    return result;
}

fn renderTextContextSizeAggregateJson(writer: *QueryOutputWriter, text_bytes: usize, text_chars: usize, text_lines: usize) !void {
    try writer.writeAll("{");
    var first = true;
    try writeJsonNumberField(writer, "text_bytes", text_bytes, &first);
    try writeJsonNumberField(writer, "text_chars", text_chars, &first);
    try writeJsonNumberField(writer, "text_lines", text_lines, &first);
    try writeJsonNumberField(writer, "size_version", 1, &first);
    try writer.writeAll("}");
}

fn writeNullableRelKindJson(out: *QueryOutputWriter, allocator: std.mem.Allocator, registry: ?schema.Registry, rel_filter: ?core.RelKind) !void {
    if (rel_filter) |rel| {
        const rel_label = try relKindNameWithSchemaAlloc(allocator, registry, rel);
        defer allocator.free(rel_label);
        try writeJsonString(out, rel_label);
    } else {
        try out.writeAll("null");
    }
}

fn renderSubgraphEdgeJson(
    out: *QueryOutputWriter,
    allocator: std.mem.Allocator,
    store: storage.Store,
    edge: SubgraphEdgeRef,
) !void {
    return renderSubgraphEdgeJsonWithSchema(out, allocator, store, null, edge);
}

fn renderSubgraphEdgeJsonWithSchema(
    out: *QueryOutputWriter,
    allocator: std.mem.Allocator,
    store: storage.Store,
    registry: ?schema.Registry,
    edge: SubgraphEdgeRef,
) !void {
    const rel_label = try relKindNameWithSchemaAlloc(allocator, registry, edge.rel);
    defer allocator.free(rel_label);
    try out.writeAll("{");
    var first = true;
    try writeJsonNumberField(out, "id", edge.edge_id.toInt(), &first);
    try writeJsonNumberField(out, "src", edge.src.toInt(), &first);
    try writeJsonStringField(out, "rel", rel_label, &first);
    try writeJsonNumberField(out, "dst", edge.dst.toInt(), &first);
    try writeJsonFieldPrefix(out, "props", &first);
    // 边字符串属性:分类性引用边(acts_on/uses/produces/about)带 state=tentative|confirmed
    // (改动三两态位)。旧版硬编码 "{}" 让 state 写而不可读——补上使其可测/可用于展示。
    // **只对 ref 类关系查属性**:结构边(contains/depends_on/…)从不带 state,跳过 property
    // 索引查找,免掉每条边一次读盘的读热路径回归(subgraph 可达 200 边)。
    const is_ref_edge = switch (edge.rel) {
        .acts_on, .uses, .produces, .about => true,
        else => false,
    };
    const state_prop = if (is_ref_edge) (store.getEdgeStringProperty(allocator, edge.edge_id, "state") catch null) else null;
    defer if (state_prop) |sp| allocator.free(sp);
    if (state_prop) |sp| {
        try out.writeAll("{");
        var props_first = true;
        try writeJsonStringField(out, "state", sp, &props_first);
        try out.writeAll("}");
    } else {
        try out.writeAll("{}");
    }
    try writeJsonFieldPrefix(out, "summary", &first);
    try out.writeAll("{");
    var summary_first = true;
    try writeJsonNullableStringField(out, "text", null, &summary_first);
    try writeJsonStringField(out, "source", "none", &summary_first);
    try out.writeAll("}");
    try writeJsonStringField(out, "direction", edge.direction, &first);
    if (edge.view_role.len != 0) try writeJsonStringField(out, "view_role", edge.view_role, &first);
    try writeJsonStringField(out, "role", switch (edge.role) {
        .tree => "tree",
        .backref => "backref",
    }, &first);
    try writeJsonBoolField(out, "traversed", edge.role == .tree, &first);
    try writeJsonNumberField(out, "depth", edge.depth, &first);
    try out.writeAll("}");
}

fn renderSubgraphOmittedJson(out: *QueryOutputWriter, item: SubgraphOmittedItem) !void {
    try out.writeAll("{");
    var first = true;
    try writeJsonStringField(out, "reason", item.reason, &first);
    try writeJsonNumberField(out, "depth", item.depth, &first);
    try writeJsonFieldPrefix(out, "edge_id", &first);
    if (item.edge_id) |edge_id| try out.print("{}", .{edge_id.toInt()}) else try out.writeAll("null");
    try writeJsonFieldPrefix(out, "src", &first);
    if (item.src) |src| try out.print("{}", .{src.toInt()}) else try out.writeAll("null");
    try writeJsonFieldPrefix(out, "dst", &first);
    if (item.dst) |dst| try out.print("{}", .{dst.toInt()}) else try out.writeAll("null");
    try out.writeAll("}");
}

fn renderNeighborsJsonOutputRetained(
    allocator: std.mem.Allocator,
    store: storage.Store,
    edge_retention_registry: *storage.EdgeSegmentRetentionRegistry,
    registry: ?schema.Registry,
    root_id: core.NodeId,
    rel_filter: ?core.RelKind,
    args: ParsedNeighborsArgs,
) ![]u8 {
    const budget = neighborsJsonBudget(args);
    var result = try buildNeighborsSubgraph(allocator, store, edge_retention_registry, root_id, rel_filter, args, budget);
    defer result.deinit(allocator);

    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);

    var node_view = try store.openNodeRecordView();
    defer node_view.deinit();

    try writeJsonObjectStart(&out);
    var first = true;
    try writeJsonStringField(&out, "schema_version", "tinykg-agent-retrieval-v1", &first);
    try writeJsonStringField(&out, "mode", "neighbors", &first);
    try writeJsonFieldPrefix(&out, "query", &first);
    try out.writeAll("{");
    var query_first = true;
    try writeJsonNumberField(&out, "root_id", root_id.toInt(), &query_first);
    try writeJsonFieldPrefix(&out, "rel_filter", &query_first);
    try writeNullableRelKindJson(&out, allocator, registry, rel_filter);
    try writeJsonNumberField(&out, "depth", args.depth, &query_first);
    try out.writeAll("}");

    try writeJsonFieldPrefix(&out, "budget", &first);
    try out.writeAll("{");
    var budget_first = true;
    try writeJsonNumberField(&out, "max_nodes", budget.max_nodes, &budget_first);
    try writeJsonNumberField(&out, "max_edges", budget.max_edges, &budget_first);
    try writeJsonNumberField(&out, "max_chars", budget.max_chars, &budget_first);
    try writeJsonNumberField(&out, "max_depth", budget.max_depth, &budget_first);
    try writeJsonNumberField(&out, "timeout_ms", budget.timeout_ms, &budget_first);
    try out.writeAll("}");

    try writeJsonFieldPrefix(&out, "summary", &first);
    try out.writeAll("{");
    var summary_first = true;
    try writeJsonNumberField(&out, "node_count", result.node_ids.items.len, &summary_first);
    try writeJsonNumberField(&out, "edge_count", result.edges.items.len, &summary_first);
    try writeJsonNumberField(&out, "backref_count", result.backrefs.items.len, &summary_first);
    try writeJsonBoolField(&out, "truncated", result.truncated, &summary_first);
    try writeJsonNullableStringField(&out, "truncate_reason", result.truncate_reason, &summary_first);
    try writeJsonNumberField(&out, "used_nodes", result.node_ids.items.len, &summary_first);
    try writeJsonNumberField(&out, "used_edges", subgraphUsedEdgeRefs(result), &summary_first);
    try writeJsonNumberField(&out, "used_chars", result.used_chars, &summary_first);
    try writeJsonNumberField(&out, "postings_scanned", 0, &summary_first);
    try writeJsonNumberField(&out, "edges_scanned", result.scanned_edges, &summary_first);
    try writeJsonFieldPrefix(&out, "context_size", &summary_first);
    try renderTextContextSizeAggregateJson(&out, result.used_bytes, result.used_chars, result.used_lines);
    try out.writeAll("}");

    try writeJsonFieldPrefix(&out, "root", &first);
    if (result.node_ids.items.len == 0) {
        try out.writeAll("null");
    } else {
        var root_node = (try node_view.readNodeById(allocator, root_id)) orelse return error.InvalidRecord;
        defer root_node.deinit(allocator);
        try renderNodeObjectJsonWithSchema(&out, allocator, store, registry, root_node, false);
    }

    try writeJsonFieldPrefix(&out, "nodes", &first);
    try out.writeAll("[");
    for (result.node_ids.items, 0..) |node_id, index| {
        if (index != 0) try out.writeAll(",");
        var node = (try node_view.readNodeById(allocator, node_id)) orelse return error.InvalidRecord;
        defer node.deinit(allocator);
        try renderNodeObjectJsonWithSchema(&out, allocator, store, registry, node, false);
    }
    try out.writeAll("]");

    try writeJsonFieldPrefix(&out, "edges", &first);
    try out.writeAll("[");
    for (result.edges.items, 0..) |edge, index| {
        if (index != 0) try out.writeAll(",");
        try renderSubgraphEdgeJsonWithSchema(&out, allocator, store, registry, edge);
    }
    try out.writeAll("]");

    try writeJsonFieldPrefix(&out, "backrefs", &first);
    try out.writeAll("[");
    for (result.backrefs.items, 0..) |edge, index| {
        if (index != 0) try out.writeAll(",");
        try renderSubgraphEdgeJsonWithSchema(&out, allocator, store, registry, edge);
    }
    try out.writeAll("]");

    try writeJsonFieldPrefix(&out, "omitted", &first);
    try out.writeAll("[");
    for (result.omitted.items, 0..) |item, index| {
        if (index != 0) try out.writeAll(",");
        try renderSubgraphOmittedJson(&out, item);
    }
    try out.writeAll("]");

    try writeJsonFieldPrefix(&out, "continuations", &first);
    try out.writeAll("[");
    var continuation_first = true;
    if (result.truncated) {
        try out.writeAll("{");
        var cont_first = true;
        try writeJsonStringField(&out, "action", "neighbors", &cont_first);
        try writeJsonNumberField(&out, "node_id", root_id.toInt(), &cont_first);
        try writeJsonStringField(&out, "args", "raise --max-nodes/--max-edges/--max-chars or lower --depth", &cont_first);
        try writeJsonStringField(&out, "reason", "subgraph traversal was truncated", &cont_first);
        try out.writeAll("}");
        continuation_first = false;
    }
    if (!continuation_first) try out.writeAll(",");
    try writeSearchContinuation(&out, "inspect_metadata", root_id, "inspect root node metadata before expanding raw text");
    try out.writeAll("]");

    try writeJsonObjectEnd(&out);
    return out.buffer.toOwnedSlice(allocator);
}

fn renderNodeVersionsOutput(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_id: core.NodeId,
    limit: usize,
) ![]u8 {
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);

    var base_node = (try store.readNodeById(allocator, node_id)) orelse return core.Error.NotFound;
    defer base_node.deinit(allocator);
    try out.print("node_versions\t{}\tlimit={}\n", .{ node_id.toInt(), limit });
    try writeTaskPacketNodeRow(&out, "base", base_node.id, base_node.kind, base_node.text);

    var node_view = try store.openNodeRecordView();
    defer node_view.deinit();
    var queue = std.ArrayList(core.NodeId).empty;
    defer queue.deinit(allocator);
    try queue.append(allocator, node_id);

    var cursor: usize = 0;
    var rows: usize = 0;
    var truncated = false;
    while (cursor < queue.items.len) : (cursor += 1) {
        const current = queue.items[cursor];
        const remaining = limit - rows;
        var records = try readVisibleEdgeRecordsByNodeLimited(allocator, store, .src, current, .deprecated_by, remaining +| 1);
        defer records.deinit(allocator);
        for (records.items) |record| {
            if (rows >= limit) {
                truncated = true;
                break;
            }
            const next_id = core.NodeId.fromInt(record.dst);
            var node = (try node_view.readNodeById(allocator, next_id)) orelse return error.InvalidRecord;
            defer node.deinit(allocator);
            try out.print("version\t{}\tdeprecated_by\t{}\t{}\t", .{ record.edge_id, current.toInt(), next_id.toInt() });
            try writeNodeKindName(&out, node.kind);
            try out.writeAll("\t");
            try writeEscapedText(&out, node.text);
            try out.writeAll("\n");
            try queue.append(allocator, next_id);
            rows += 1;
        }
        if (truncated) break;
    }
    if (truncated) try out.print("version_truncated\tlimit={}\n", .{limit});

    return out.buffer.toOwnedSlice(allocator);
}

const NodeLatestVisit = struct {
    node_id: core.NodeId,
    parent_id: ?core.NodeId = null,
    edge_id: ?u64 = null,
    has_child: bool = false,
};

fn renderNodeLatestOutput(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_id: core.NodeId,
    limit: usize,
) ![]u8 {
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);

    var base_node = (try store.readNodeById(allocator, node_id)) orelse return core.Error.NotFound;
    defer base_node.deinit(allocator);

    var visits = std.ArrayList(NodeLatestVisit).empty;
    defer visits.deinit(allocator);
    try visits.append(allocator, .{ .node_id = node_id });

    var cursor: usize = 0;
    var version_edges: usize = 0;
    var truncated = false;
    while (cursor < visits.items.len) : (cursor += 1) {
        const current_id = visits.items[cursor].node_id;
        const remaining = limit - version_edges;
        var records = try readVisibleEdgeRecordsByNodeLimited(allocator, store, .src, current_id, .deprecated_by, remaining +| 1);
        defer records.deinit(allocator);
        for (records.items) |record| {
            if (version_edges >= limit) {
                truncated = true;
                break;
            }
            visits.items[cursor].has_child = true;
            try visits.append(allocator, .{
                .node_id = core.NodeId.fromInt(record.dst),
                .parent_id = current_id,
                .edge_id = record.edge_id,
            });
            version_edges += 1;
        }
        if (truncated) break;
    }

    var latest_count: usize = 0;
    if (!truncated) {
        for (visits.items) |visit| {
            if (!visit.has_child) latest_count += 1;
        }
    }
    try out.print(
        "node_latest\t{}\tlimit={}\tscanned_versions={}\ttruncated={}\tlatest_count={}\n",
        .{ node_id.toInt(), limit, version_edges, @intFromBool(truncated), latest_count },
    );
    try writeTaskPacketNodeRow(&out, "base", base_node.id, base_node.kind, base_node.text);
    if (truncated) {
        try out.print("latest_truncated\tlimit={}\tscanned_versions={}\n", .{ limit, version_edges });
        return out.buffer.toOwnedSlice(allocator);
    }

    var node_view = try store.openNodeRecordView();
    defer node_view.deinit();
    for (visits.items) |visit| {
        if (visit.has_child) continue;
        var node = (try node_view.readNodeById(allocator, visit.node_id)) orelse return error.InvalidRecord;
        defer node.deinit(allocator);
        if (visit.parent_id) |parent_id| {
            try out.print("latest\t{}\tdeprecated_by\t{}\t{}\t", .{ visit.edge_id.?, parent_id.toInt(), visit.node_id.toInt() });
        } else {
            try out.print("latest\troot\t{}\t", .{visit.node_id.toInt()});
        }
        try writeNodeKindName(&out, node.kind);
        try out.writeAll("\t");
        try writeEscapedText(&out, node.text);
        try out.writeAll("\n");
    }

    return out.buffer.toOwnedSlice(allocator);
}

fn renderNeighborsOutput(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_id: core.NodeId,
    rel_filter: ?core.RelKind,
    budget: core.QueryBudget,
) ![]u8 {
    return renderNeighborsOutputMaybeRetained(allocator, store, null, null, node_id, rel_filter, budget, false, 0, false);
}

fn renderNeighborsOutputRetained(
    allocator: std.mem.Allocator,
    store: storage.Store,
    edge_retention_registry: *storage.EdgeSegmentRetentionRegistry,
    node_id: core.NodeId,
    rel_filter: ?core.RelKind,
    budget: core.QueryBudget,
    include_history: bool,
) ![]u8 {
    return renderNeighborsOutputMaybeRetained(allocator, store, edge_retention_registry, null, node_id, rel_filter, budget, false, 0, include_history);
}

fn renderNeighborsOutputBounded(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_id: core.NodeId,
    rel_filter: ?core.RelKind,
    limit: usize,
    offset: usize,
) ![]u8 {
    return renderNeighborsOutputMaybeRetained(allocator, store, null, null, node_id, rel_filter, .{
        .max_results = limit + offset,
        .max_visited_edges = limit + offset,
    }, true, offset, false);
}

fn renderNeighborsOutputBoundedRetained(
    allocator: std.mem.Allocator,
    store: storage.Store,
    edge_retention_registry: *storage.EdgeSegmentRetentionRegistry,
    node_id: core.NodeId,
    rel_filter: ?core.RelKind,
    limit: usize,
    offset: usize,
    include_history: bool,
) ![]u8 {
    return renderNeighborsOutputMaybeRetained(allocator, store, edge_retention_registry, null, node_id, rel_filter, .{
        .max_results = limit + offset,
        .max_visited_edges = limit + offset,
    }, true, offset, include_history);
}

fn renderNeighborsOutputMaybeRetained(
    allocator: std.mem.Allocator,
    store: storage.Store,
    edge_retention_registry: ?*storage.EdgeSegmentRetentionRegistry,
    registry: ?schema.Registry,
    node_id: core.NodeId,
    rel_filter: ?core.RelKind,
    budget: core.QueryBudget,
    allow_partial_results: bool,
    offset: usize,
    include_history: bool,
) ![]u8 {
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);

    if (!include_history and !try nodeIsCurrentGeneration(store, node_id)) return out.buffer.toOwnedSlice(allocator);

    var result = if (edge_retention_registry) |edge_registry|
        try query.neighborsWithPersistentStoreRetained(allocator, store, edge_registry, node_id, rel_filter, budget)
    else
        try query.neighborsWithPersistentStore(allocator, store, node_id, rel_filter, budget);
    defer result.deinit(allocator);
    if (!allow_partial_results and result.stats.budget_exceeded) return core.Error.BudgetExceeded;

    if (result.neighbors.items.len <= offset) return out.buffer.toOwnedSlice(allocator);

    var node_view = try store.openNodeRecordView();
    defer node_view.deinit();
    for (result.neighbors.items[offset..]) |neighbor| {
        if (!include_history and !try nodeIsCurrentGeneration(store, neighbor.node_id)) continue;
        var node = (try node_view.readNodeById(allocator, neighbor.node_id)) orelse return error.InvalidRecord;
        defer node.deinit(allocator);
        try out.print("{}\t", .{neighbor.edge_id.toInt()});
        try writeRelKindNameWithSchema(&out, registry, neighbor.rel);
        try out.print("\t{}\t", .{node.id.toInt()});
        try writeEscapedText(&out, node.text);
        try out.writeAll("\n");
    }

    return out.buffer.toOwnedSlice(allocator);
}

fn renderIncomingOutput(
    allocator: std.mem.Allocator,
    store: storage.Store,
    registry: ?schema.Registry,
    node_id: core.NodeId,
    rel_filter: ?core.RelKind,
    budget: core.QueryBudget,
    include_history: bool,
) ![]u8 {
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);

    var node_id_view = try store.openNodeByIdIndexView();
    defer node_id_view.deinit();
    if (!try node_id_view.nodeExists(node_id)) return core.Error.NotFound;
    if (!include_history and !try nodeIsCurrentGeneration(store, node_id)) return out.buffer.toOwnedSlice(allocator);

    var node_view = try store.openNodeRecordView();
    defer node_view.deinit();
    const IncomingContext = struct {
        allocator: std.mem.Allocator,
        store: storage.Store,
        registry: ?schema.Registry,
        node_view: *storage.Store.NodeRecordView,
        out: *QueryOutputWriter,
        budget: core.QueryBudget,
        include_history: bool,
        rows: usize = 0,
        visited: usize = 0,

        fn visit(self: *@This(), record: storage.EdgeIndexRecord) !bool {
            if (self.visited >= self.budget.max_visited_edges) return core.Error.BudgetExceeded;
            self.visited += 1;
            if (self.rows >= self.budget.max_results) return core.Error.BudgetExceeded;
            const src_id = core.NodeId.fromInt(record.src);
            if (!self.include_history and !try nodeIsCurrentGeneration(self.store, src_id)) return false;
            var node = (try self.node_view.readNodeById(self.allocator, src_id)) orelse return error.InvalidRecord;
            defer node.deinit(self.allocator);
            try self.out.print("{}\t", .{record.edge_id});
            try writeRelKindNameWithSchema(self.out, self.registry, @enumFromInt(record.rel));
            try self.out.print("\t{}\t", .{node.id.toInt()});
            try writeEscapedText(self.out, node.text);
            try self.out.writeAll("\n");
            self.rows += 1;
            return false;
        }
    };
    var context = IncomingContext{
        .allocator = allocator,
        .store = store,
        .registry = registry,
        .node_view = &node_view,
        .out = &out,
        .budget = budget,
        .include_history = include_history,
    };
    _ = try forEachVisibleEdgeRecordByNode(allocator, store, .dst, node_id, rel_filter, &context, IncomingContext.visit);

    return out.buffer.toOwnedSlice(allocator);
}

fn renderTaskPacketOutput(
    allocator: std.mem.Allocator,
    store: storage.Store,
    task_id: core.NodeId,
    limit: usize,
) ![]u8 {
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);

    var task_node = (try store.readNodeById(allocator, task_id)) orelse return core.Error.NotFound;
    defer task_node.deinit(allocator);
    if (task_node.kind != .task) return core.Error.InvalidId;

    const now_ns = try u128ToU64(persistentNowNs(store.io));
    const lifecycle = try task.statusForStoredNode(allocator, store, task_node, now_ns);
    const state: ?task.ReadyState = if (lifecycle.isTerminal()) null else try task.readyStateWithPersistentStoreAt(allocator, store, task_id, now_ns);
    try out.print("task_packet\t{}\tstatus={s}\treadiness=", .{ task_id.toInt(), @tagName(lifecycle) });
    if (state) |value| {
        try out.writeAll(@tagName(value));
    } else {
        try out.writeAll("-");
    }
    try out.print("\tlimit={}\n", .{limit});
    try writeTaskPacketNodeRow(&out, "task", task_node.id, task_node.kind, task_node.text);

    var node_view = try store.openNodeRecordView();
    defer node_view.deinit();
    try writeTaskPacketEdgeRows(allocator, store, &node_view, &out, "parent_in", .dst, task_id, .contains, limit);
    try writeTaskPacketEdgeRows(allocator, store, &node_view, &out, "goal_anchor_in", .dst, task_id, .related_to, limit);
    try writeTaskPacketEdgeRows(allocator, store, &node_view, &out, "goal_anchor_out", .src, task_id, .related_to, limit);
    try writeTaskPacketEdgeRows(allocator, store, &node_view, &out, "depends_on_out", .src, task_id, .depends_on, limit);
    try writeTaskPacketEdgeRows(allocator, store, &node_view, &out, "blocks_in", .dst, task_id, .blocks, limit);
    try writeTaskPacketRecentEdgeRows(allocator, store, &node_view, &out, "child_out", .src, task_id, .contains, limit);
    try writeTaskPacketRecentEdgeRows(allocator, store, &node_view, &out, "verified_by_out", .src, task_id, .verified_by, limit);

    return out.buffer.toOwnedSlice(allocator);
}

fn taskPacketJsonBudget(args: ParsedTaskPacketArgs) NeighborsJsonBudget {
    const default_max_edges = args.max_edges orelse @min((core.QueryBudget{}).max_visited_edges, args.limit * 7);
    const default_max_nodes = args.max_nodes orelse @min((core.QueryBudget{}).max_results, default_max_edges + 1);
    return .{
        .max_depth = 1,
        .max_nodes = default_max_nodes,
        .max_edges = default_max_edges,
        .max_chars = args.max_chars orelse 200_000,
    };
}

fn taskPacketEdgeDirection(order: storage.EdgeIndexOrder) []const u8 {
    return switch (order) {
        .src => "outgoing",
        .dst => "incoming",
        .id => "unknown",
    };
}

fn addTaskPacketEdgeToSubgraph(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_view: *storage.Store.NodeRecordView,
    result: *SubgraphBuildResult,
    visited_nodes: *std.AutoHashMap(u64, void),
    visited_edges: *std.AutoHashMap(u64, void),
    record: storage.EdgeIndexRecord,
    order: storage.EdgeIndexOrder,
    view_role: []const u8,
    budget: NeighborsJsonBudget,
) !bool {
    result.scanned_edges = std.math.add(usize, result.scanned_edges, 1) catch return error.RecordTooLarge;
    const edge_id = core.EdgeId.fromInt(record.edge_id);
    if (visited_edges.contains(edge_id.toInt())) return false;

    const node_id = switch (order) {
        .src => core.NodeId.fromInt(record.dst),
        .dst => core.NodeId.fromInt(record.src),
        .id => return core.Error.Unsupported,
    };
    var node = (try node_view.readNodeById(allocator, node_id)) orelse return error.InvalidRecord;
    defer node.deinit(allocator);
    if (taskPacketRoleIsGoalAnchor(view_role) and try nodeHasTaskEventSchema(allocator, store, node.id)) return false;

    if (subgraphUsedEdgeRefs(result.*) >= budget.max_edges) {
        try appendSubgraphOmitted(allocator, result, "max_edges", edge_id, core.NodeId.fromInt(record.src), core.NodeId.fromInt(record.dst), 1);
        return false;
    }
    try visited_edges.put(edge_id.toInt(), {});

    const role: SubgraphEdgeRole = if (visited_nodes.contains(node_id.toInt())) .backref else .tree;
    if (role == .tree) {
        const added = try tryAddSubgraphNode(allocator, store, node_view, result, visited_nodes, null, node_id, 1, budget, true);
        if (!added) return false;
    }
    const edge = SubgraphEdgeRef{
        .edge_id = edge_id,
        .src = core.NodeId.fromInt(record.src),
        .rel = @enumFromInt(record.rel),
        .dst = core.NodeId.fromInt(record.dst),
        .depth = 1,
        .role = role,
        .direction = taskPacketEdgeDirection(order),
        .view_role = view_role,
    };
    if (role == .backref) {
        try result.backrefs.append(allocator, edge);
    } else {
        try result.edges.append(allocator, edge);
    }
    return true;
}

fn collectTaskPacketEdgeRowsJson(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_view: *storage.Store.NodeRecordView,
    result: *SubgraphBuildResult,
    visited_nodes: *std.AutoHashMap(u64, void),
    visited_edges: *std.AutoHashMap(u64, void),
    view_role: []const u8,
    order: storage.EdgeIndexOrder,
    owner_id: core.NodeId,
    rel_filter: core.RelKind,
    limit: usize,
    budget: NeighborsJsonBudget,
) !void {
    var rows: usize = 0;
    var records = try readVisibleEdgeRecordsByNode(allocator, store, order, owner_id, rel_filter);
    defer records.deinit(allocator);
    for (records.items) |record| {
        if (rows >= limit) {
            try appendSubgraphOmitted(allocator, result, "max_role_rows", core.EdgeId.fromInt(record.edge_id), core.NodeId.fromInt(record.src), core.NodeId.fromInt(record.dst), 1);
            break;
        }
        if (try addTaskPacketEdgeToSubgraph(allocator, store, node_view, result, visited_nodes, visited_edges, record, order, view_role, budget)) rows += 1;
    }
}

fn collectTaskPacketRecentEdgeRowsJson(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_view: *storage.Store.NodeRecordView,
    result: *SubgraphBuildResult,
    visited_nodes: *std.AutoHashMap(u64, void),
    visited_edges: *std.AutoHashMap(u64, void),
    view_role: []const u8,
    order: storage.EdgeIndexOrder,
    owner_id: core.NodeId,
    rel_filter: core.RelKind,
    limit: usize,
    budget: NeighborsJsonBudget,
) !void {
    if (limit == 0) return error.InvalidLimit;

    const recent = try allocator.alloc(storage.EdgeIndexRecord, limit);
    defer allocator.free(recent);

    var scanned: usize = 0;
    var first_omitted: ?storage.EdgeIndexRecord = null;
    var records = try readVisibleEdgeRecordsByNode(allocator, store, order, owner_id, rel_filter);
    defer records.deinit(allocator);
    for (records.items) |record| {
        if (scanned >= limit and first_omitted == null) first_omitted = recent[scanned % limit];
        recent[scanned % limit] = record;
        scanned += 1;
    }
    if (first_omitted) |omitted| {
        try appendSubgraphOmitted(allocator, result, "max_role_rows", core.EdgeId.fromInt(omitted.edge_id), core.NodeId.fromInt(omitted.src), core.NodeId.fromInt(omitted.dst), 1);
    }

    const emitted = @min(scanned, limit);
    var offset: usize = 0;
    while (offset < emitted) : (offset += 1) {
        const index = (scanned - 1 - offset) % limit;
        _ = try addTaskPacketEdgeToSubgraph(allocator, store, node_view, result, visited_nodes, visited_edges, recent[index], order, view_role, budget);
    }
}

fn buildTaskPacketSubgraph(
    allocator: std.mem.Allocator,
    store: storage.Store,
    task_id: core.NodeId,
    args: ParsedTaskPacketArgs,
    budget: NeighborsJsonBudget,
) !SubgraphBuildResult {
    var result = SubgraphBuildResult{};
    errdefer result.deinit(allocator);

    var node_view = try store.openNodeRecordView();
    defer node_view.deinit();
    var visited_nodes = std.AutoHashMap(u64, void).init(allocator);
    defer visited_nodes.deinit();
    var visited_edges = std.AutoHashMap(u64, void).init(allocator);
    defer visited_edges.deinit();

    _ = try tryAddSubgraphNode(allocator, store, &node_view, &result, &visited_nodes, null, task_id, 0, budget, true);
    try collectTaskPacketEdgeRowsJson(allocator, store, &node_view, &result, &visited_nodes, &visited_edges, "parent_in", .dst, task_id, .contains, args.limit, budget);
    try collectTaskPacketEdgeRowsJson(allocator, store, &node_view, &result, &visited_nodes, &visited_edges, "goal_anchor_in", .dst, task_id, .related_to, args.limit, budget);
    try collectTaskPacketEdgeRowsJson(allocator, store, &node_view, &result, &visited_nodes, &visited_edges, "goal_anchor_out", .src, task_id, .related_to, args.limit, budget);
    try collectTaskPacketEdgeRowsJson(allocator, store, &node_view, &result, &visited_nodes, &visited_edges, "depends_on_out", .src, task_id, .depends_on, args.limit, budget);
    try collectTaskPacketEdgeRowsJson(allocator, store, &node_view, &result, &visited_nodes, &visited_edges, "blocks_in", .dst, task_id, .blocks, args.limit, budget);
    try collectTaskPacketRecentEdgeRowsJson(allocator, store, &node_view, &result, &visited_nodes, &visited_edges, "child_out", .src, task_id, .contains, args.limit, budget);
    try collectTaskPacketRecentEdgeRowsJson(allocator, store, &node_view, &result, &visited_nodes, &visited_edges, "verified_by_out", .src, task_id, .verified_by, args.limit, budget);
    return result;
}

fn renderTaskPacketJsonOutput(
    allocator: std.mem.Allocator,
    store: storage.Store,
    task_id: core.NodeId,
    args: ParsedTaskPacketArgs,
) ![]u8 {
    var task_node = (try store.readNodeById(allocator, task_id)) orelse return core.Error.NotFound;
    defer task_node.deinit(allocator);
    if (task_node.kind != .task) return core.Error.InvalidId;

    const now_ns = try u128ToU64(persistentNowNs(store.io));
    const lifecycle = try task.statusForStoredNode(allocator, store, task_node, now_ns);
    const state: ?task.ReadyState = if (lifecycle.isTerminal()) null else try task.readyStateWithPersistentStoreAt(allocator, store, task_id, now_ns);
    const budget = taskPacketJsonBudget(args);
    var result = try buildTaskPacketSubgraph(allocator, store, task_id, args, budget);
    defer result.deinit(allocator);

    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);
    var node_view = try store.openNodeRecordView();
    defer node_view.deinit();

    try writeJsonObjectStart(&out);
    var first = true;
    try writeJsonStringField(&out, "schema_version", "tinykg-agent-retrieval-v1", &first);
    try writeJsonStringField(&out, "mode", "task-packet", &first);
    try writeJsonFieldPrefix(&out, "query", &first);
    try out.writeAll("{");
    var query_first = true;
    try writeJsonNumberField(&out, "task_id", task_id.toInt(), &query_first);
    try writeJsonNumberField(&out, "limit", args.limit, &query_first);
    try writeJsonStringField(&out, "status", @tagName(lifecycle), &query_first);
    try writeJsonNullableStringField(&out, "readiness", if (state) |value| @tagName(value) else null, &query_first);
    try out.writeAll("}");

    try writeJsonFieldPrefix(&out, "budget", &first);
    try out.writeAll("{");
    var budget_first = true;
    try writeJsonNumberField(&out, "max_nodes", budget.max_nodes, &budget_first);
    try writeJsonNumberField(&out, "max_edges", budget.max_edges, &budget_first);
    try writeJsonNumberField(&out, "max_chars", budget.max_chars, &budget_first);
    try writeJsonNumberField(&out, "timeout_ms", budget.timeout_ms, &budget_first);
    try out.writeAll("}");

    try writeJsonFieldPrefix(&out, "summary", &first);
    try out.writeAll("{");
    var summary_first = true;
    try writeJsonNumberField(&out, "node_count", result.node_ids.items.len, &summary_first);
    try writeJsonNumberField(&out, "edge_count", result.edges.items.len, &summary_first);
    try writeJsonNumberField(&out, "backref_count", result.backrefs.items.len, &summary_first);
    try writeJsonBoolField(&out, "truncated", result.truncated, &summary_first);
    try writeJsonNullableStringField(&out, "truncate_reason", result.truncate_reason, &summary_first);
    try writeJsonNumberField(&out, "used_nodes", result.node_ids.items.len, &summary_first);
    try writeJsonNumberField(&out, "used_edges", subgraphUsedEdgeRefs(result), &summary_first);
    try writeJsonNumberField(&out, "used_chars", result.used_chars, &summary_first);
    try writeJsonNumberField(&out, "edges_scanned", result.scanned_edges, &summary_first);
    try writeJsonFieldPrefix(&out, "context_size", &summary_first);
    try renderTextContextSizeAggregateJson(&out, result.used_bytes, result.used_chars, result.used_lines);
    try out.writeAll("}");

    try writeJsonFieldPrefix(&out, "root", &first);
    try renderNodeObjectJson(&out, allocator, store, task_node, false);

    try writeJsonFieldPrefix(&out, "nodes", &first);
    try out.writeAll("[");
    for (result.node_ids.items, 0..) |node_id, index| {
        if (index != 0) try out.writeAll(",");
        var node = (try node_view.readNodeById(allocator, node_id)) orelse return error.InvalidRecord;
        defer node.deinit(allocator);
        try renderNodeObjectJson(&out, allocator, store, node, false);
    }
    try out.writeAll("]");

    try writeJsonFieldPrefix(&out, "edges", &first);
    try out.writeAll("[");
    for (result.edges.items, 0..) |edge, index| {
        if (index != 0) try out.writeAll(",");
        try renderSubgraphEdgeJson(&out, allocator, store, edge);
    }
    try out.writeAll("]");

    try writeJsonFieldPrefix(&out, "backrefs", &first);
    try out.writeAll("[");
    for (result.backrefs.items, 0..) |edge, index| {
        if (index != 0) try out.writeAll(",");
        try renderSubgraphEdgeJson(&out, allocator, store, edge);
    }
    try out.writeAll("]");

    try writeJsonFieldPrefix(&out, "omitted", &first);
    try out.writeAll("[");
    for (result.omitted.items, 0..) |item, index| {
        if (index != 0) try out.writeAll(",");
        try renderSubgraphOmittedJson(&out, item);
    }
    try out.writeAll("]");

    try writeJsonFieldPrefix(&out, "continuations", &first);
    try out.writeAll("[");
    var continuation_first = true;
    if (result.truncated) {
        try out.writeAll("{");
        var cont_first = true;
        try writeJsonStringField(&out, "action", "task-packet", &cont_first);
        try writeJsonNumberField(&out, "node_id", task_id.toInt(), &cont_first);
        try writeJsonStringField(&out, "args", "raise --limit/--max-nodes/--max-edges/--max-chars", &cont_first);
        try writeJsonStringField(&out, "reason", "task packet was truncated", &cont_first);
        try out.writeAll("}");
        continuation_first = false;
    }
    if (!continuation_first) try out.writeAll(",");
    try writeSearchContinuation(&out, "neighbors", task_id, "walk local graph around this task if task packet is insufficient");
    try out.writeAll("]");

    try writeJsonObjectEnd(&out);
    return out.buffer.toOwnedSlice(allocator);
}

/// task-frontier 深遍历预算(遍历面防爆;readiness 单查另有 QueryBudget)。
/// 生命周期 sidecar 在遍历前只做一次定向快照；每节点仍会建立 readiness
/// cursor/view，因此 4096 上限依旧是明确的 CPU/IO 防线。
const frontier_max_visited_nodes: usize = 4096;
const frontier_max_status_snapshot_nodes: usize = frontier_max_visited_nodes * 4;
const frontier_max_depth: usize = 64;
const frontier_path_segment_max_bytes: usize = 32;
/// task-claim 默认租约(读侧过期:frontier 判定时 expires<=now 即视为无人认领,无后台任务)。
const task_claim_default_ttl_s: u64 = 7200;

/// 行内 claim 状态(owned holder;active = 有 holder 且租约未过期)。
const FrontierClaim = struct {
    holder: ?[]const u8 = null,
    active: bool = false,
    owned: bool = false,

    fn deinit(self: *const FrontierClaim, allocator: std.mem.Allocator) void {
        if (self.owned) {
            if (self.holder) |h| allocator.free(h);
        }
    }
};

fn frontierReadClaim(
    allocator: std.mem.Allocator,
    store: storage.Store,
    status_snapshot: *const task.StatusSnapshot,
    node_id: core.NodeId,
    now_ns: u64,
) !FrontierClaim {
    if (status_snapshot.covers(node_id)) {
        const claim = status_snapshot.claim(node_id);
        return .{ .holder = claim.holder, .active = claim.active(now_ns) };
    }
    const holder = try store.getNodeStringProperty(allocator, node_id, task.claimed_by_property);
    if (holder == null or holder.?.len == 0) {
        if (holder) |value| allocator.free(value);
        return .{};
    }
    errdefer allocator.free(holder.?);
    const expires = (try store.getUintProperty(allocator, .{ .node = node_id }, task.claim_expires_ns_property)) orelse 0;
    return .{ .holder = holder.?, .active = expires > now_ns, .owned = true };
}

fn exerciseFrontierReadClaimAllocationFailure(
    allocator: std.mem.Allocator,
    store: storage.Store,
    snapshot: *const task.StatusSnapshot,
) !void {
    const claim = try frontierReadClaim(allocator, store, snapshot, .fromInt(1), 0);
    defer claim.deinit(allocator);
    try std.testing.expectEqualStrings("allocation-test-agent", claim.holder.?);
    try std.testing.expect(claim.active);
}

fn frontierStatusForNode(walk: *const FrontierWalk, node: storage.StoredNode) !task.Status {
    if (walk.status_snapshot.covers(node.id)) return try walk.status_snapshot.statusForStoredNode(node, walk.now_ns);
    return try task.statusForStoredNode(walk.allocator, walk.store, node, walk.now_ns);
}

/// child_task/related_task 行的 claim 过滤(branch 行不过滤,结构上下文恒发射)。
const FrontierClaimFilter = struct {
    mine: ?[]const u8 = null,
    unclaimed: bool = false,

    fn keeps(self: FrontierClaimFilter, claim: FrontierClaim) bool {
        if (self.mine) |agent_name| {
            return claim.active and std.mem.eql(u8, claim.holder.?, agent_name);
        }
        if (self.unclaimed) return !claim.active;
        return true;
    }
};

const FrontierChildRef = struct {
    edge_id: u64,
    node_id: core.NodeId,
    status: task.Status,
};

/// task-frontier 深遍历状态。语义(v2):frontier = 子树的**可执行叶子集**。
/// - child_task = 开放叶子(无开放 task 子节点),唯一计入 --limit 的可执行行;
/// - branch_task = 开放复合节点(有开放子节点,不可直接执行,靠子树闭合而闭合),
///   供看板重建结构("不在 frontier = 已完成"的推断因此对复合节点也成立);
/// - readiness 为**有效就绪度**:自身与祖先链取第一个非 ready(父被阻,子不虚报 ready)。
const FrontierWalk = struct {
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_view: *storage.Store.NodeRecordView,
    status_snapshot: *const task.StatusSnapshot,
    out: *QueryOutputWriter,
    limit: usize,
    now_ns: u64,
    claim_filter: FrontierClaimFilter = .{},
    emitted: usize = 0,
    leaf_truncated: bool = false,
    budget_truncated: bool = false,
    depth_truncated: bool = false,
    visited: std.AutoHashMap(u64, void),
    aggregate_readiness: std.AutoHashMap(u64, task.ReadyState),
    path: std.ArrayList(u8) = .empty,

    fn stopped(self: *const FrontierWalk) bool {
        return self.leaf_truncated or self.budget_truncated;
    }

    fn deinit(self: *FrontierWalk) void {
        self.aggregate_readiness.deinit();
        self.visited.deinit();
        self.path.deinit(self.allocator);
    }
};

fn frontierReadinessRank(state: task.ReadyState) u8 {
    return switch (state) {
        .ready => 0,
        .missing_dependencies => 1,
        .blocked => 2,
    };
}

fn stricterFrontierReadiness(lhs: task.ReadyState, rhs: task.ReadyState) task.ReadyState {
    return if (frontierReadinessRank(lhs) >= frontierReadinessRank(rhs)) lhs else rhs;
}

/// Precompute effective readiness before emitting rows. A contains graph is a
/// DAG, not necessarily a tree: a shared descendant must inherit the strictest
/// state from every root-to-node path. Emitting during the first DFS would make
/// the answer depend on edge order because a later, blocked parent could no
/// longer revise an already-written row. Each node can escalate at most twice
/// (ready -> missing -> blocked), so this fixed-point walk stays bounded.
fn aggregateFrontierReadiness(
    walk: *FrontierWalk,
    node_id: core.NodeId,
    depth: usize,
    inherited: task.ReadyState,
) !void {
    if (depth > frontier_max_depth) return;

    var node = (try walk.node_view.readNodeById(walk.allocator, node_id)) orelse return error.InvalidRecord;
    defer node.deinit(walk.allocator);
    if (node.kind != .task) return;
    const lifecycle = try frontierStatusForNode(walk, node);
    if (lifecycle == .completed) return;

    const own: task.ReadyState = if (lifecycle == .failed)
        .blocked
    else
        try task.readyStateWithPersistentStoreSnapshotAt(walk.allocator, walk.store, node_id, walk.now_ns, walk.status_snapshot);

    var children: std.ArrayList(FrontierChildRef) = .empty;
    defer children.deinit(walk.allocator);
    try frontierCollectTaskChildren(walk, node_id, &children);
    var has_failed_child = false;
    for (children.items) |child| {
        if (child.status == .failed) {
            has_failed_child = true;
            break;
        }
    }
    var effective = stricterFrontierReadiness(inherited, own);
    if (lifecycle == .failed or has_failed_child) effective = .blocked;

    const existing = walk.aggregate_readiness.get(node_id.toInt());
    if (existing) |previous| {
        effective = stricterFrontierReadiness(previous, effective);
        if (effective == previous) return;
    } else if (walk.aggregate_readiness.count() >= frontier_max_visited_nodes - 1) {
        // The emitting walk has the same DFS order and includes the root in
        // its node budget. Nodes beyond this point are never emitted.
        return;
    }
    try walk.aggregate_readiness.put(node_id.toInt(), effective);
    for (children.items) |child| {
        try aggregateFrontierReadiness(walk, child.node_id, depth + 1, effective);
    }
}

fn frontierCollectTaskChildren(
    walk: *FrontierWalk,
    parent_id: core.NodeId,
    children: *std.ArrayList(FrontierChildRef),
) !void {
    var records = try readVisibleEdgeRecordsByNode(walk.allocator, walk.store, .src, parent_id, .contains);
    defer records.deinit(walk.allocator);
    for (records.items) |record| {
        const child_id = core.NodeId.fromInt(record.dst);
        var child = (try walk.node_view.readNodeById(walk.allocator, child_id)) orelse return error.InvalidRecord;
        defer child.deinit(walk.allocator);
        if (child.kind != .task) continue;
        const lifecycle = try frontierStatusForNode(walk, child);
        if (lifecycle == .completed) continue;
        try children.append(walk.allocator, .{ .edge_id = record.edge_id, .node_id = child_id, .status = lifecycle });
    }
}

fn frontierWalkTask(
    walk: *FrontierWalk,
    edge_id: u64,
    rel: core.RelKind,
    node_id: core.NodeId,
    depth: usize,
    inherited: task.ReadyState,
) !void {
    if (walk.stopped()) return;
    if (depth > frontier_max_depth) {
        walk.depth_truncated = true;
        return;
    }
    // 菱形防重:同节点只发射一次；readiness 已在前置固定点遍历中聚合
    // 全部 root-to-node 路径，这里只让第一条路径决定展示用 breadcrumb。
    const gop = try walk.visited.getOrPut(node_id.toInt());
    if (gop.found_existing) return;
    if (walk.visited.count() > frontier_max_visited_nodes) {
        walk.budget_truncated = true;
        return;
    }
    var node = (try walk.node_view.readNodeById(walk.allocator, node_id)) orelse return error.InvalidRecord;
    defer node.deinit(walk.allocator);
    if (node.kind != .task) return;
    const lifecycle = try frontierStatusForNode(walk, node);
    if (lifecycle == .completed) return;

    var children: std.ArrayList(FrontierChildRef) = .empty;
    defer children.deinit(walk.allocator);
    try frontierCollectTaskChildren(walk, node_id, &children);
    const effective = walk.aggregate_readiness.get(node_id.toInt()) orelse fallback: {
        const own: task.ReadyState = if (lifecycle == .failed)
            .blocked
        else
            try task.readyStateWithPersistentStoreSnapshotAt(walk.allocator, walk.store, node_id, walk.now_ns, walk.status_snapshot);
        var path_effective = stricterFrontierReadiness(inherited, own);
        for (children.items) |child| {
            if (child.status == .failed) {
                path_effective = .blocked;
                break;
            }
        }
        break :fallback path_effective;
    };

    if (children.items.len == 0) {
        const claim = try frontierReadClaim(walk.allocator, walk.store, walk.status_snapshot, node_id, walk.now_ns);
        defer claim.deinit(walk.allocator);
        if (lifecycle == .failed) {
            try writeTaskFrontierRow(walk.out, "failed_task", edge_id, rel, node_id.toInt(), lifecycle, effective, depth, claim, walk.path.items, node.text);
            return;
        }
        if (!walk.claim_filter.keeps(claim)) return;
        if (walk.emitted >= walk.limit) {
            walk.leaf_truncated = true;
            return;
        }
        try writeTaskFrontierRow(walk.out, "child_task", edge_id, rel, node_id.toInt(), lifecycle, effective, depth, claim, walk.path.items, node.text);
        walk.emitted += 1;
        return;
    }

    const branch_claim = try frontierReadClaim(walk.allocator, walk.store, walk.status_snapshot, node_id, walk.now_ns);
    defer branch_claim.deinit(walk.allocator);
    try writeTaskFrontierRow(walk.out, if (lifecycle == .failed) "failed_task" else "branch_task", edge_id, rel, node_id.toInt(), lifecycle, effective, depth, branch_claim, walk.path.items, node.text);
    const path_len_before = walk.path.items.len;
    if (walk.path.items.len > 0) try walk.path.appendSlice(walk.allocator, " › ");
    try appendFirstLineTruncated(&walk.path, walk.allocator, node.text, frontier_path_segment_max_bytes);
    defer walk.path.shrinkRetainingCapacity(path_len_before);
    for (children.items) |child| {
        try frontierWalkTask(walk, child.edge_id, .contains, child.node_id, depth + 1, effective);
        if (walk.stopped()) return;
    }
}

fn writeTaskFrontierRow(
    out: *QueryOutputWriter,
    role: []const u8,
    edge_id: u64,
    rel: core.RelKind,
    node_id: u64,
    status: task.Status,
    readiness: task.ReadyState,
    depth: usize,
    claim: FrontierClaim,
    path_raw: []const u8,
    text: []const u8,
) !void {
    try out.print("{s}\t{}\t", .{ role, edge_id });
    try writeRelKindName(out, rel);
    try out.print("\t{}\tstatus={s}\treadiness={s}\tdepth={}\tclaimed_by=", .{ node_id, @tagName(status), @tagName(readiness), depth });
    if (claim.active) {
        try writeEscapedText(out, claim.holder.?);
    } else {
        try out.writeAll("-");
    }
    try out.writeAll("\tpath=");
    if (path_raw.len == 0) {
        try out.writeAll("-");
    } else {
        try writeEscapedText(out, path_raw);
    }
    try out.writeAll("\t");
    try writeEscapedText(out, text);
    try out.writeAll("\n");
}

/// 取 text 首行,UTF-8 安全截断到 max_bytes(超出加 …)。面包屑段用。
fn appendFirstLineTruncated(list: *std.ArrayList(u8), allocator: std.mem.Allocator, text: []const u8, max_bytes: usize) !void {
    const line_end = std.mem.indexOfScalar(u8, text, '\n') orelse text.len;
    const line = std.mem.trim(u8, text[0..line_end], " \t\r");
    if (line.len <= max_bytes) {
        try list.appendSlice(allocator, line);
        return;
    }
    var end: usize = 0;
    while (end < line.len) {
        const width = std.unicode.utf8ByteSequenceLength(line[end]) catch 1;
        if (end + width > max_bytes) break;
        end += width;
    }
    try list.appendSlice(allocator, line[0..end]);
    try list.appendSlice(allocator, "…");
}

fn collectFrontierStatusSnapshotNodeIds(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_view: *storage.Store.NodeRecordView,
    root_id: core.NodeId,
) !std.ArrayList(core.NodeId) {
    var ids = std.ArrayList(core.NodeId).empty;
    errdefer ids.deinit(allocator);
    var seen = std.AutoHashMap(u64, void).init(allocator);
    defer seen.deinit();
    try seen.put(root_id.toInt(), {});
    try ids.append(allocator, root_id);

    var cursor: usize = 0;
    while (cursor < ids.items.len and ids.items.len < frontier_max_visited_nodes) : (cursor += 1) {
        var records = try readVisibleEdgeRecordsByNode(allocator, store, .src, ids.items[cursor], .contains);
        defer records.deinit(allocator);
        for (records.items) |record| {
            const child_id = core.NodeId.fromInt(record.dst);
            const entry = try seen.getOrPut(child_id.toInt());
            if (entry.found_existing) continue;
            var child = (try node_view.readNodeById(allocator, child_id)) orelse return error.InvalidRecord;
            defer child.deinit(allocator);
            if (child.kind != .task) continue;
            try ids.append(allocator, child_id);
            if (ids.items.len >= frontier_max_visited_nodes) break;
        }
    }

    if (ids.items.len < frontier_max_visited_nodes) {
        var related = try readVisibleEdgeRecordsByNode(allocator, store, .dst, root_id, .related_to);
        defer related.deinit(allocator);
        for (related.items) |record| {
            const related_id = core.NodeId.fromInt(record.src);
            const entry = try seen.getOrPut(related_id.toInt());
            if (entry.found_existing) continue;
            var node = (try node_view.readNodeById(allocator, related_id)) orelse return error.InvalidRecord;
            defer node.deinit(allocator);
            if (node.kind != .task) continue;
            try ids.append(allocator, related_id);
            if (ids.items.len >= frontier_max_visited_nodes) break;
        }
    }
    // Readiness consults immediate scheduler endpoints that may live outside
    // the contains tree (shared prerequisites, blockers and predecessors).
    // Include those owners in the same lifecycle snapshot so a frontier walk
    // validates the property delta once instead of once per external task.
    // Do not recursively expand endpoints: readiness itself is one-hop.
    const readiness_owner_count = ids.items.len;
    var owner_index: usize = 0;
    while (owner_index < readiness_owner_count and ids.items.len < frontier_max_status_snapshot_nodes) : (owner_index += 1) {
        try appendFrontierReadinessEndpointIds(allocator, store, &ids, &seen, ids.items[owner_index], .src, .depends_on, false);
        try appendFrontierReadinessEndpointIds(allocator, store, &ids, &seen, ids.items[owner_index], .dst, .blocks, true);
        try appendFrontierReadinessEndpointIds(allocator, store, &ids, &seen, ids.items[owner_index], .dst, .precedes, true);
    }
    return ids;
}

fn appendFrontierReadinessEndpointIds(
    allocator: std.mem.Allocator,
    store: storage.Store,
    ids: *std.ArrayList(core.NodeId),
    seen: *std.AutoHashMap(u64, void),
    owner_id: core.NodeId,
    order: storage.EdgeIndexOrder,
    rel: core.RelKind,
    endpoint_is_src: bool,
) !void {
    if (ids.items.len >= frontier_max_status_snapshot_nodes) return;
    var records = try readVisibleEdgeRecordsByNode(allocator, store, order, owner_id, rel);
    defer records.deinit(allocator);
    for (records.items) |record| {
        const endpoint_id = core.NodeId.fromInt(if (endpoint_is_src) record.src else record.dst);
        const entry = try seen.getOrPut(endpoint_id.toInt());
        if (entry.found_existing) continue;
        try ids.append(allocator, endpoint_id);
        if (ids.items.len >= frontier_max_status_snapshot_nodes) return;
    }
}

fn renderTaskFrontierOutput(
    allocator: std.mem.Allocator,
    store: storage.Store,
    root_id: core.NodeId,
    frontier_arg: ParsedTaskFrontierArgs,
    now_ns: u64,
) ![]u8 {
    const limit = frontier_arg.limit;
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);

    var node_id_view = try store.openNodeByIdIndexView();
    defer node_id_view.deinit();
    if (!try node_id_view.nodeExists(root_id)) return core.Error.NotFound;

    try out.print("task_frontier\t{}\tlimit={}\tmode=deep\n", .{ root_id.toInt(), limit });

    var node_view = try store.openNodeRecordView();
    defer node_view.deinit();
    var snapshot_node_ids = try collectFrontierStatusSnapshotNodeIds(allocator, store, &node_view, root_id);
    defer snapshot_node_ids.deinit(allocator);
    var status_snapshot = try task.StatusSnapshot.initForNodeIds(allocator, store, snapshot_node_ids.items);
    defer status_snapshot.deinit();

    var root = (try node_view.readNodeById(allocator, root_id)) orelse return error.InvalidRecord;
    defer root.deinit(allocator);
    if (root.kind != .task) return core.Error.InvalidId;
    const root_lifecycle = try status_snapshot.statusForStoredNode(root, now_ns);
    if (root_lifecycle == .completed) return out.buffer.toOwnedSlice(allocator);

    var walk = FrontierWalk{
        .allocator = allocator,
        .store = store,
        .node_view = &node_view,
        .status_snapshot = &status_snapshot,
        .out = &out,
        .limit = limit,
        .now_ns = now_ns,
        .claim_filter = .{ .mine = frontier_arg.mine, .unclaimed = frontier_arg.unclaimed },
        .visited = std.AutoHashMap(u64, void).init(allocator),
        .aggregate_readiness = std.AutoHashMap(u64, task.ReadyState).init(allocator),
    };
    defer walk.deinit();
    try walk.visited.put(root_id.toInt(), {});

    var root_children: std.ArrayList(FrontierChildRef) = .empty;
    defer root_children.deinit(allocator);
    try frontierCollectTaskChildren(&walk, root_id, &root_children);
    var root_has_failed_child = false;
    for (root_children.items) |child| {
        if (child.status == .failed) {
            root_has_failed_child = true;
            break;
        }
    }
    const root_effective: task.ReadyState = if (root_lifecycle == .failed or root_has_failed_child)
        .blocked
    else
        try task.readyStateWithPersistentStoreSnapshotAt(allocator, store, root_id, now_ns, &status_snapshot);
    for (root_children.items) |child| {
        try aggregateFrontierReadiness(&walk, child.node_id, 1, root_effective);
    }
    for (root_children.items) |child| {
        try frontierWalkTask(&walk, child.edge_id, .contains, child.node_id, 1, root_effective);
        if (walk.stopped()) break;
    }

    if (walk.leaf_truncated) try out.print("child_task_truncated\tlimit={}\n", .{limit});
    if (walk.budget_truncated) try out.writeAll("frontier_truncated\tbudget=nodes\n");
    if (walk.depth_truncated) try out.writeAll("frontier_truncated\tbudget=depth\n");

    if (!walk.stopped() and walk.emitted < limit) {
        try writeTaskFrontierRelatedRows(&walk, root_id);
    }

    return out.buffer.toOwnedSlice(allocator);
}

fn writeTaskFrontierRelatedRows(walk: *FrontierWalk, owner_id: core.NodeId) !void {
    var truncated = false;
    var records = try readVisibleEdgeRecordsByNode(walk.allocator, walk.store, .dst, owner_id, .related_to);
    defer records.deinit(walk.allocator);
    for (records.items) |record| {
        const node_id = core.NodeId.fromInt(record.src);
        var node = (try walk.node_view.readNodeById(walk.allocator, node_id)) orelse return error.InvalidRecord;
        defer node.deinit(walk.allocator);
        if (node.kind != .task) continue;
        const lifecycle = try frontierStatusForNode(walk, node);
        if (lifecycle == .completed) continue;
        const claim = try frontierReadClaim(walk.allocator, walk.store, walk.status_snapshot, node_id, walk.now_ns);
        defer claim.deinit(walk.allocator);
        if (lifecycle != .failed and !walk.claim_filter.keeps(claim)) continue;
        if (walk.emitted >= walk.limit) {
            truncated = true;
            break;
        }
        const state: task.ReadyState = if (lifecycle == .failed)
            .blocked
        else
            try task.readyStateWithPersistentStoreSnapshotAt(walk.allocator, walk.store, node_id, walk.now_ns, walk.status_snapshot);
        try writeTaskFrontierRow(walk.out, if (lifecycle == .failed) "related_failed_task" else "related_task", record.edge_id, @enumFromInt(record.rel), node.id.toInt(), lifecycle, state, 1, claim, "", node.text);
        walk.emitted += 1;
    }
    if (truncated) try walk.out.print("related_task_truncated\tlimit={}\n", .{walk.limit});
}

fn renderTaskAncestryOutput(
    allocator: std.mem.Allocator,
    store: storage.Store,
    task_id: core.NodeId,
    depth: usize,
    limit: usize,
) ![]u8 {
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);

    var task_node = (try store.readNodeById(allocator, task_id)) orelse return core.Error.NotFound;
    defer task_node.deinit(allocator);
    if (task_node.kind != .task) return core.Error.InvalidId;

    const lifecycle = try task.statusForStoredNode(allocator, store, task_node, try u128ToU64(persistentNowNs(store.io)));
    try out.print("task_ancestry\t{}\tstatus={s}\tdepth={}\tlimit={}\n", .{ task_id.toInt(), @tagName(lifecycle), depth, limit });
    try writeTaskPacketNodeRow(&out, "focus", task_node.id, task_node.kind, task_node.text);

    var node_view = try store.openNodeRecordView();
    defer node_view.deinit();
    var current = std.ArrayList(core.NodeId).empty;
    defer current.deinit(allocator);
    var next = std.ArrayList(core.NodeId).empty;
    defer next.deinit(allocator);
    try current.append(allocator, task_id);

    var emitted: usize = 0;
    var level: usize = 0;
    while (level < depth and current.items.len > 0) : (level += 1) {
        next.clearRetainingCapacity();
        for (current.items) |node_id| {
            if (try writeTaskAncestryAnchorRows(allocator, store, &node_view, &out, "goal_anchor_out", .src, node_id, level, limit, &emitted)) return out.buffer.toOwnedSlice(allocator);
            if (try writeTaskAncestryAnchorRows(allocator, store, &node_view, &out, "goal_anchor_in", .dst, node_id, level, limit, &emitted)) return out.buffer.toOwnedSlice(allocator);
            if (try writeTaskAncestryParentRows(allocator, store, &node_view, &out, node_id, level, limit, &emitted, &next)) return out.buffer.toOwnedSlice(allocator);
        }
        current.clearRetainingCapacity();
        try current.appendSlice(allocator, next.items);
    }

    return out.buffer.toOwnedSlice(allocator);
}

fn writeTaskAncestryAnchorRows(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_view: anytype,
    out: *QueryOutputWriter,
    role: []const u8,
    order: storage.EdgeIndexOrder,
    owner_id: core.NodeId,
    level: usize,
    limit: usize,
    emitted: *usize,
) !bool {
    var records = try readVisibleEdgeRecordsByNode(allocator, store, order, owner_id, .related_to);
    defer records.deinit(allocator);
    for (records.items) |record| {
        if (emitted.* >= limit) {
            try out.print("{s}_truncated\tlevel={}\tlimit={}\n", .{ role, level, limit });
            return true;
        }
        const node_id = switch (order) {
            .src => core.NodeId.fromInt(record.dst),
            .dst => core.NodeId.fromInt(record.src),
            .id => return core.Error.Unsupported,
        };
        var node = (try node_view.readNodeById(allocator, node_id)) orelse return error.InvalidRecord;
        defer node.deinit(allocator);
        if (try nodeHasTaskEventSchema(allocator, store, node.id)) continue;
        try out.print("{s}\tlevel={}\t{}\t", .{ role, level, record.edge_id });
        try writeRelKindName(out, @enumFromInt(record.rel));
        try out.print("\t{}\t", .{node.id.toInt()});
        try writeNodeKindName(out, node.kind);
        try out.writeAll("\t");
        try writeEscapedText(out, node.text);
        try out.writeAll("\n");
        emitted.* += 1;
    }
    return false;
}

fn writeTaskAncestryParentRows(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_view: anytype,
    out: *QueryOutputWriter,
    owner_id: core.NodeId,
    level: usize,
    limit: usize,
    emitted: *usize,
    next: *std.ArrayList(core.NodeId),
) !bool {
    var records = try readVisibleEdgeRecordsByNode(allocator, store, .dst, owner_id, .contains);
    defer records.deinit(allocator);
    for (records.items) |record| {
        if (emitted.* >= limit) {
            try out.print("parent_in_truncated\tlevel={}\tlimit={}\n", .{ level, limit });
            return true;
        }
        const node_id = core.NodeId.fromInt(record.src);
        var node = (try node_view.readNodeById(allocator, node_id)) orelse return error.InvalidRecord;
        defer node.deinit(allocator);
        try out.print("parent_in\tlevel={}\t{}\t", .{ level, record.edge_id });
        try writeRelKindName(out, @enumFromInt(record.rel));
        try out.print("\t{}\t", .{node.id.toInt()});
        try writeNodeKindName(out, node.kind);
        try out.writeAll("\t");
        try writeEscapedText(out, node.text);
        try out.writeAll("\n");
        emitted.* += 1;
        try next.append(allocator, node_id);
    }
    return false;
}

const TaskMetrics = struct {
    scanned_edges: usize = 0,
    nested_event_edges: usize = 0,
    truncated: bool = false,
    open_tasks: usize = 0,
    claimed_tasks: usize = 0,
    completed_tasks: usize = 0,
    failed_tasks: usize = 0,
    legacy_closed_verifications: usize = 0,
    legacy_closed_fixes: usize = 0,
    other_nodes: usize = 0,
    ready_tasks: usize = 0,
    blocked_tasks: usize = 0,
    missing_dependency_tasks: usize = 0,
    dependency_edges: usize = 0,
    blocker_edges: usize = 0,
    verification_edges: usize = 0,
    rework_error_events: usize = 0,
    task_write_attempt_events: usize = 0,
    task_write_error_events: usize = 0,
    dependency_edge_created_events: usize = 0,
    dependency_edge_correction_events: usize = 0,
    prompt_adherence_ok_events: usize = 0,
    prompt_adherence_miss_events: usize = 0,
    stale_open_task_age_samples: usize = 0,
    stale_open_task_age_min_ns: u128 = 0,
    stale_open_task_age_max_ns: u128 = 0,
    completion_latency_samples: usize = 0,
    completion_latency_min_ns: u128 = 0,
    completion_latency_max_ns: u128 = 0,

    fn recordStaleOpenTaskAge(self: *TaskMetrics, recorded_ns: u128, now_ns: u128) void {
        const age_ns = if (now_ns >= recorded_ns) now_ns - recorded_ns else 0;
        if (self.stale_open_task_age_samples == 0 or age_ns < self.stale_open_task_age_min_ns) {
            self.stale_open_task_age_min_ns = age_ns;
        }
        if (age_ns > self.stale_open_task_age_max_ns) {
            self.stale_open_task_age_max_ns = age_ns;
        }
        self.stale_open_task_age_samples += 1;
    }

    fn recordCompletionLatency(self: *TaskMetrics, created_ns: u128, completed_ns: u128) void {
        const latency_ns = if (completed_ns >= created_ns) completed_ns - created_ns else 0;
        if (self.completion_latency_samples == 0 or latency_ns < self.completion_latency_min_ns) {
            self.completion_latency_min_ns = latency_ns;
        }
        if (latency_ns > self.completion_latency_max_ns) {
            self.completion_latency_max_ns = latency_ns;
        }
        self.completion_latency_samples += 1;
    }
};

const task_metric_detail_budget_multiplier: usize = 16;

const TaskMetricDetailBudget = struct {
    limit: usize,
    scanned_edges: usize = 0,
    truncated: bool = false,

    fn init(row_limit: usize) TaskMetricDetailBudget {
        return .{
            .limit = std.math.mul(usize, row_limit, task_metric_detail_budget_multiplier) catch std.math.maxInt(usize),
        };
    }

    fn charge(self: *TaskMetricDetailBudget, metrics: *TaskMetrics) bool {
        if (self.scanned_edges >= self.limit) {
            self.truncated = true;
            metrics.truncated = true;
            return false;
        }
        self.scanned_edges += 1;
        return true;
    }

    fn remaining(self: TaskMetricDetailBudget) usize {
        return self.limit - self.scanned_edges;
    }

    fn absorb(self: *TaskMetricDetailBudget, scanned_edges: usize) void {
        std.debug.assert(scanned_edges <= self.remaining());
        self.scanned_edges += scanned_edges;
    }

    fn markTruncated(self: *TaskMetricDetailBudget, metrics: *TaskMetrics) void {
        self.truncated = true;
        metrics.truncated = true;
    }
};

const PendingTaskMetricEvent = struct {
    node_id: core.NodeId,
    skip_root_id: ?core.NodeId,
    metrics: *TaskMetrics,
};

const TaskMetricEventSnapshot = struct {
    allocator: std.mem.Allocator,
    properties: storage.PropertySnapshot,
    by_node: std.AutoHashMap(u64, Fields),

    const Fields = struct {
        task_root_id: ?u64 = null,
        event_type: ?[]const u8 = null,
        dependency_relation: ?[]const u8 = null,
    };

    fn init(allocator: std.mem.Allocator, store: storage.Store, node_ids: []const core.NodeId) !TaskMetricEventSnapshot {
        var properties = try store.loadNodePropertySnapshotForNodeIds(allocator, node_ids, &.{
            "task_root_id",
            "task_event_type",
            "dependency_relation",
        });
        errdefer properties.deinit(allocator);
        var by_node = std.AutoHashMap(u64, Fields).init(allocator);
        errdefer by_node.deinit();

        const root_hash = storage.propertyKeyHashForLookup("task_root_id");
        const event_hash = storage.propertyKeyHashForLookup("task_event_type");
        const relation_hash = storage.propertyKeyHashForLookup("dependency_relation");
        for (properties.entries) |entry| {
            const node_id = switch (entry.owner) {
                .node => |id| id.toInt(),
                .edge => return error.InvalidTaskMetricEvent,
            };
            const slot = try by_node.getOrPut(node_id);
            if (!slot.found_existing) slot.value_ptr.* = .{};
            if (entry.key_hash == root_hash) {
                if (entry.value_kind != .uint) return error.InvalidTaskMetricEvent;
                slot.value_ptr.task_root_id = entry.uint_value;
            } else if (entry.key_hash == event_hash) {
                if (entry.value_kind != .string) return error.InvalidTaskMetricEvent;
                slot.value_ptr.event_type = entry.string_value;
            } else if (entry.key_hash == relation_hash) {
                if (entry.value_kind != .string) return error.InvalidTaskMetricEvent;
                slot.value_ptr.dependency_relation = entry.string_value;
            }
        }
        return .{ .allocator = allocator, .properties = properties, .by_node = by_node };
    }

    fn deinit(self: *TaskMetricEventSnapshot) void {
        self.by_node.deinit();
        self.properties.deinit(self.allocator);
        self.* = undefined;
    }

    fn fields(self: *const TaskMetricEventSnapshot, node_id: core.NodeId) Fields {
        return self.by_node.get(node_id.toInt()) orelse .{};
    }
};

fn renderTaskMetricsOutput(
    allocator: std.mem.Allocator,
    io: std.Io,
    store: storage.Store,
    root_id: core.NodeId,
    limit: usize,
) ![]u8 {
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);

    var node_id_view = try store.openNodeByIdIndexView();
    defer node_id_view.deinit();
    if (!try node_id_view.nodeExists(root_id)) return core.Error.NotFound;

    var node_view = try store.openNodeRecordView();
    defer node_view.deinit();
    var pending_events = std.ArrayList(PendingTaskMetricEvent).empty;
    defer pending_events.deinit(allocator);
    var aggregate_seen_nodes = std.AutoHashMap(u64, void).init(allocator);
    defer aggregate_seen_nodes.deinit();
    var detail_budget = TaskMetricDetailBudget.init(limit);

    const now_ns = persistentNowNs(io);
    var aggregate = TaskMetrics{};
    var child = TaskMetrics{};
    try collectTaskMetricsRows(allocator, store, &node_view, .src, root_id, .contains, limit, now_ns, &child, &aggregate, &aggregate_seen_nodes, &pending_events, &detail_budget);
    var related = TaskMetrics{};
    try collectTaskMetricsRows(allocator, store, &node_view, .dst, root_id, .related_to, limit, now_ns, &related, &aggregate, &aggregate_seen_nodes, &pending_events, &detail_budget);
    var event_links = TaskMetrics{};
    try collectTaskEventMetricsRows(allocator, store, &node_view, root_id, .task_event, limit, &event_links, &aggregate, &pending_events);
    try collectTaskEventMetricsRows(allocator, store, &node_view, root_id, .references, limit, &event_links, &aggregate, &pending_events);
    try recordPendingTaskMetricEvents(allocator, store, pending_events.items);

    const total_open = aggregate.open_tasks;
    const total_claimed = aggregate.claimed_tasks;
    const total_completed = aggregate.completed_tasks;
    const total_failed = aggregate.failed_tasks;
    const total_rework = aggregate.rework_error_events;
    const combined = aggregate;
    const metrics_truncated = child.truncated or related.truncated or event_links.truncated or detail_budget.truncated;
    try out.print("task_metrics\t{}\tlimit={}\ttruncated={}\topen_tasks={}\tclaimed_tasks={}\tcompleted_tasks={}\tfailed_tasks={}\trework_error_events={}\n", .{ root_id.toInt(), limit, @intFromBool(metrics_truncated), total_open, total_claimed, total_completed, total_failed, total_rework });
    try out.print("budget\tscope=detail_edges\tscanned_edges={}\tlimit={}\ttruncated={}\n", .{ detail_budget.scanned_edges, detail_budget.limit, @intFromBool(detail_budget.truncated) });
    try writeTaskMetricsScopeRow(&out, "child_contains", child);
    try writeTaskMetricsScopeRow(&out, "incoming_related_to", related);
    try writeTaskMetricsScopeRow(&out, "incoming_task_event", event_links);
    const task_write_attempt_samples = @max(combined.task_write_attempt_events, combined.task_write_error_events);
    if (task_write_attempt_samples > 0) {
        try out.print(
            "measured\tmetric=task_write_error_rate\tattempts={}\terrors={}\trate_bps={}\n",
            .{ task_write_attempt_samples, combined.task_write_error_events, rateBps(combined.task_write_error_events, task_write_attempt_samples) },
        );
    } else {
        try out.writeAll("unavailable\tmetric=task_write_error_rate\treason=no_write_attempt_event_log\n");
    }
    if (combined.dependency_edge_created_events > 0) {
        try out.print(
            "measured\tmetric=dependency_correction_rate\tcreated={}\tcorrections={}\trate_bps={}\n",
            .{ combined.dependency_edge_created_events, combined.dependency_edge_correction_events, rateBps(combined.dependency_edge_correction_events, combined.dependency_edge_created_events) },
        );
    } else {
        try out.writeAll("unavailable\tmetric=dependency_correction_rate\treason=no_edge_revision_event_log\n");
    }
    const prompt_samples = combined.prompt_adherence_ok_events + combined.prompt_adherence_miss_events;
    if (prompt_samples > 0) {
        try out.print(
            "measured\tmetric=prompt_adherence_rate\tok={}\tmisses={}\trate_bps={}\n",
            .{ combined.prompt_adherence_ok_events, combined.prompt_adherence_miss_events, rateBps(combined.prompt_adherence_ok_events, prompt_samples) },
        );
    } else {
        try out.writeAll("unavailable\tmetric=prompt_adherence_rate\treason=no_prompt_adherence_event_log\n");
    }
    const total_tasks = total_open + total_claimed + total_completed + total_failed;
    if (total_tasks > 0) {
        try out.print(
            "measured\tmetric=rework_density\ttasks={}\trework_error_events={}\trate_bps={}\n",
            .{ total_tasks, total_rework, rateBps(total_rework, total_tasks) },
        );
    } else {
        try out.writeAll("unavailable\tmetric=rework_density\treason=no_task_samples\n");
    }
    if (combined.completion_latency_samples > 0) {
        try out.print(
            "measured\tmetric=completion_latency\tsamples={}\tmin_ns={}\tmax_ns={}\n",
            .{ combined.completion_latency_samples, combined.completion_latency_min_ns, combined.completion_latency_max_ns },
        );
    } else {
        try out.writeAll("unavailable\tmetric=completion_latency\treason=no_task_timestamp_index\n");
    }
    if (combined.stale_open_task_age_samples > 0) {
        try out.print(
            "measured\tmetric=stale_open_task_age\tsamples={}\tmin_ns={}\tmax_ns={}\n",
            .{ combined.stale_open_task_age_samples, combined.stale_open_task_age_min_ns, combined.stale_open_task_age_max_ns },
        );
    } else {
        try out.writeAll("unavailable\tmetric=stale_open_task_age\treason=no_task_timestamp_index\n");
    }
    return out.buffer.toOwnedSlice(allocator);
}

fn writeTaskMetricsScopeRow(out: *QueryOutputWriter, scope: []const u8, metrics: TaskMetrics) !void {
    try out.print(
        "scope\t{s}\tscanned_edges={}\ttruncated={}\topen_tasks={}\tclaimed_tasks={}\tcompleted_tasks={}\tfailed_tasks={}\tlegacy_closed_verifications={}\tlegacy_closed_fixes={}\tother_nodes={}\tready={}\tblocked={}\tmissing_dependencies={}\tdepends_on_edges={}\tblocker_edges={}\tverified_by_edges={}\trework_error_events={}\tnested_event_edges={}\n",
        .{
            scope,
            metrics.scanned_edges,
            @intFromBool(metrics.truncated),
            metrics.open_tasks,
            metrics.claimed_tasks,
            metrics.completed_tasks,
            metrics.failed_tasks,
            metrics.legacy_closed_verifications,
            metrics.legacy_closed_fixes,
            metrics.other_nodes,
            metrics.ready_tasks,
            metrics.blocked_tasks,
            metrics.missing_dependency_tasks,
            metrics.dependency_edges,
            metrics.blocker_edges,
            metrics.verification_edges,
            metrics.rework_error_events,
            metrics.nested_event_edges,
        },
    );
}

fn recordTaskLifecycleMetric(
    metrics: *TaskMetrics,
    lifecycle: task.Status,
    fields: task.StatusSnapshot.LifecycleFields,
    now_ns: u128,
) void {
    switch (lifecycle) {
        .open => {
            metrics.open_tasks += 1;
            if (taskMetricRecordedNsFromFields(fields)) |recorded_ns| metrics.recordStaleOpenTaskAge(recorded_ns, now_ns);
        },
        .claimed => metrics.claimed_tasks += 1,
        .completed => {
            metrics.completed_tasks += 1;
            if (taskMetricCompletionLatencyFromFields(fields)) |latency| metrics.recordCompletionLatency(latency.created_ns, latency.completed_ns);
        },
        .failed => metrics.failed_tasks += 1,
    }
}

fn recordTaskReadinessMetric(metrics: *TaskMetrics, state: task.ReadyState) void {
    switch (state) {
        .ready => metrics.ready_tasks += 1,
        .blocked => metrics.blocked_tasks += 1,
        .missing_dependencies => metrics.missing_dependency_tasks += 1,
    }
}

fn recordLegacyClosedTaskMetric(metrics: *TaskMetrics, kind: core.NodeKind, fields: task.StatusSnapshot.LifecycleFields) void {
    metrics.completed_tasks += 1;
    switch (kind) {
        .verification => metrics.legacy_closed_verifications += 1,
        .fix => metrics.legacy_closed_fixes += 1,
        else => unreachable,
    }
    if (taskMetricCompletionLatencyFromFields(fields)) |latency| metrics.recordCompletionLatency(latency.created_ns, latency.completed_ns);
}

fn collectTaskMetricsRows(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_view: anytype,
    order: storage.EdgeIndexOrder,
    owner_id: core.NodeId,
    rel_filter: core.RelKind,
    limit: usize,
    now_ns: u128,
    metrics: *TaskMetrics,
    aggregate_metrics: *TaskMetrics,
    aggregate_seen_nodes: *std.AutoHashMap(u64, void),
    pending_events: *std.ArrayList(PendingTaskMetricEvent),
    detail_budget: *TaskMetricDetailBudget,
) !void {
    const MetricRow = struct {
        node_id: core.NodeId,
    };
    var rows = std.ArrayList(MetricRow).empty;
    defer rows.deinit(allocator);
    const remaining_rows = if (metrics.scanned_edges < limit) limit - metrics.scanned_edges else 0;
    var records = try readVisibleEdgeRecordsByNodeLimited(
        allocator,
        store,
        order,
        owner_id,
        rel_filter,
        taskEdgeLookaheadLimit(remaining_rows),
    );
    defer records.deinit(allocator);
    for (records.items) |record| {
        if (metrics.scanned_edges >= limit) {
            metrics.truncated = true;
            break;
        }
        metrics.scanned_edges += 1;
        const node_id = switch (order) {
            .src => core.NodeId.fromInt(record.dst),
            .dst => core.NodeId.fromInt(record.src),
            .id => return core.Error.Unsupported,
        };
        try rows.append(allocator, .{ .node_id = node_id });
    }
    if (rows.items.len == 0) return;

    const snapshot_ids = try allocator.alloc(core.NodeId, rows.items.len);
    defer allocator.free(snapshot_ids);
    for (rows.items, snapshot_ids) |row, *node_id| node_id.* = row.node_id;
    var lifecycle_snapshot = try task.StatusSnapshot.initForNodeIds(allocator, store, snapshot_ids);
    defer lifecycle_snapshot.deinit();
    const now_u64 = try u128ToU64(now_ns);
    var scope_seen_nodes = std.AutoHashMap(u64, void).init(allocator);
    defer scope_seen_nodes.deinit();

    for (rows.items) |row| {
        const node_id = row.node_id;
        const scope_entry = try scope_seen_nodes.getOrPut(node_id.toInt());
        if (scope_entry.found_existing) continue;
        const aggregate_entry = try aggregate_seen_nodes.getOrPut(node_id.toInt());
        const aggregate_target: ?*TaskMetrics = if (aggregate_entry.found_existing) null else aggregate_metrics;
        var node = (try node_view.readNodeById(allocator, node_id)) orelse return error.InvalidRecord;
        defer node.deinit(allocator);
        switch (node.kind) {
            .task => {
                const lifecycle = try lifecycle_snapshot.statusForStoredNode(node, now_u64);
                const lifecycle_fields = lifecycle_snapshot.fields(node.id);
                recordTaskLifecycleMetric(metrics, lifecycle, lifecycle_fields, now_ns);
                if (aggregate_target) |target| recordTaskLifecycleMetric(target, lifecycle, lifecycle_fields, now_ns);
                if (!lifecycle.isTerminal()) {
                    if (try taskMetricReadyState(allocator, store, node_id, now_u64, &lifecycle_snapshot, metrics, detail_budget)) |state| {
                        recordTaskReadinessMetric(metrics, state);
                        if (aggregate_target) |target| recordTaskReadinessMetric(target, state);
                    }
                }
                const dependency_edges = try countTaskMetricEdges(allocator, store, .src, node_id, .depends_on, limit, metrics, detail_budget);
                const blocker_edges = try countTaskMetricEdges(allocator, store, .dst, node_id, .blocks, limit, metrics, detail_budget);
                const verification_edges = try countTaskMetricEdges(allocator, store, .src, node_id, .verified_by, limit, metrics, detail_budget);
                const rework_events = try countTaskMetricEventKind(allocator, store, node_view, node_id, .error_event, limit, metrics, detail_budget);
                metrics.dependency_edges += dependency_edges;
                metrics.blocker_edges += blocker_edges;
                metrics.verification_edges += verification_edges;
                metrics.rework_error_events += rework_events;
                if (aggregate_target) |target| {
                    target.dependency_edges += dependency_edges;
                    target.blocker_edges += blocker_edges;
                    target.verification_edges += verification_edges;
                    target.rework_error_events += rework_events;
                }
                try collectTaskAnchorEventMetrics(allocator, store, node_view, node_id, owner_id, limit, metrics, aggregate_target, pending_events, detail_budget);
            },
            .verification => {
                if (lifecycle_snapshot.isLegacyClosedTaskNode(node)) {
                    recordLegacyClosedTaskMetric(metrics, node.kind, lifecycle_snapshot.fields(node.id));
                    if (aggregate_target) |target| recordLegacyClosedTaskMetric(target, node.kind, lifecycle_snapshot.fields(node.id));
                } else {
                    metrics.other_nodes += 1;
                    if (aggregate_target) |target| target.other_nodes += 1;
                }
                const rework_events = try countTaskMetricEventKind(allocator, store, node_view, node_id, .error_event, limit, metrics, detail_budget);
                metrics.rework_error_events += rework_events;
                if (aggregate_target) |target| target.rework_error_events += rework_events;
                try collectTaskAnchorEventMetrics(allocator, store, node_view, node_id, owner_id, limit, metrics, aggregate_target, pending_events, detail_budget);
            },
            .fix => {
                if (lifecycle_snapshot.isLegacyClosedTaskNode(node)) {
                    recordLegacyClosedTaskMetric(metrics, node.kind, lifecycle_snapshot.fields(node.id));
                    if (aggregate_target) |target| recordLegacyClosedTaskMetric(target, node.kind, lifecycle_snapshot.fields(node.id));
                } else {
                    metrics.other_nodes += 1;
                    if (aggregate_target) |target| target.other_nodes += 1;
                }
                const rework_events = try countTaskMetricEventKind(allocator, store, node_view, node_id, .error_event, limit, metrics, detail_budget);
                metrics.rework_error_events += rework_events;
                if (aggregate_target) |target| target.rework_error_events += rework_events;
                try collectTaskAnchorEventMetrics(allocator, store, node_view, node_id, owner_id, limit, metrics, aggregate_target, pending_events, detail_budget);
            },
            .command, .error_event, .observation => {
                metrics.other_nodes += 1;
                try pending_events.append(allocator, .{ .node_id = node.id, .skip_root_id = null, .metrics = metrics });
                if (aggregate_target) |target| {
                    target.other_nodes += 1;
                    try pending_events.append(allocator, .{ .node_id = node.id, .skip_root_id = null, .metrics = target });
                }
            },
            else => {
                metrics.other_nodes += 1;
                if (aggregate_target) |target| target.other_nodes += 1;
            },
        }
    }
}

fn collectTaskEventMetricsRows(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_view: anytype,
    root_id: core.NodeId,
    rel_filter: core.RelKind,
    limit: usize,
    metrics: *TaskMetrics,
    aggregate_metrics: *TaskMetrics,
    pending_events: *std.ArrayList(PendingTaskMetricEvent),
) !void {
    const remaining_rows = if (metrics.scanned_edges < limit) limit - metrics.scanned_edges else 0;
    var records = try readVisibleEdgeRecordsByNodeLimited(
        allocator,
        store,
        .dst,
        root_id,
        rel_filter,
        taskEdgeLookaheadLimit(remaining_rows),
    );
    defer records.deinit(allocator);
    for (records.items) |record| {
        if (metrics.scanned_edges >= limit) {
            metrics.truncated = true;
            break;
        }
        metrics.scanned_edges += 1;
        var node = (try node_view.readNodeById(allocator, core.NodeId.fromInt(record.src))) orelse return error.InvalidRecord;
        defer node.deinit(allocator);
        switch (node.kind) {
            .command, .error_event, .observation => {
                metrics.other_nodes += 1;
                try pending_events.append(allocator, .{ .node_id = node.id, .skip_root_id = null, .metrics = metrics });
                try pending_events.append(allocator, .{ .node_id = node.id, .skip_root_id = null, .metrics = aggregate_metrics });
            },
            else => metrics.other_nodes += 1,
        }
    }
}

fn collectTaskAnchorEventMetrics(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_view: anytype,
    anchor_id: core.NodeId,
    owner_id: core.NodeId,
    limit: usize,
    metrics: *TaskMetrics,
    aggregate_metrics: ?*TaskMetrics,
    pending_events: *std.ArrayList(PendingTaskMetricEvent),
    detail_budget: *TaskMetricDetailBudget,
) !void {
    try collectTaskAnchorEventMetricsForRelation(allocator, store, node_view, anchor_id, owner_id, .task_event, limit, metrics, aggregate_metrics, pending_events, detail_budget);
    try collectTaskAnchorEventMetricsForRelation(allocator, store, node_view, anchor_id, owner_id, .references, limit, metrics, aggregate_metrics, pending_events, detail_budget);
}

fn collectTaskAnchorEventMetricsForRelation(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_view: anytype,
    anchor_id: core.NodeId,
    owner_id: core.NodeId,
    rel_filter: core.RelKind,
    limit: usize,
    metrics: *TaskMetrics,
    aggregate_metrics: ?*TaskMetrics,
    pending_events: *std.ArrayList(PendingTaskMetricEvent),
    detail_budget: *TaskMetricDetailBudget,
) !void {
    var scanned: usize = 0;
    var records = try readVisibleEdgeRecordsByNodeLimited(
        allocator,
        store,
        .dst,
        anchor_id,
        rel_filter,
        taskEdgeLookaheadLimit(@min(limit, detail_budget.remaining())),
    );
    defer records.deinit(allocator);
    for (records.items) |record| {
        if (!detail_budget.charge(metrics)) break;
        if (scanned >= limit) {
            metrics.truncated = true;
            break;
        }
        scanned += 1;
        metrics.nested_event_edges += 1;
        var node = (try node_view.readNodeById(allocator, core.NodeId.fromInt(record.src))) orelse return error.InvalidRecord;
        defer node.deinit(allocator);
        switch (node.kind) {
            .command, .error_event, .observation => {
                try pending_events.append(allocator, .{ .node_id = node.id, .skip_root_id = owner_id, .metrics = metrics });
                if (aggregate_metrics) |target| try pending_events.append(allocator, .{ .node_id = node.id, .skip_root_id = owner_id, .metrics = target });
            },
            else => {},
        }
    }
}

fn rateBps(numerator: usize, denominator: usize) usize {
    if (denominator == 0) return 0;
    const scaled = @as(u128, numerator) * 10000 / @as(u128, denominator);
    return @intCast(@min(scaled, std.math.maxInt(usize)));
}

fn recordPendingTaskMetricEvents(
    allocator: std.mem.Allocator,
    store: storage.Store,
    pending_events: []const PendingTaskMetricEvent,
) !void {
    if (pending_events.len == 0) return;
    const node_ids = try allocator.alloc(core.NodeId, pending_events.len);
    defer allocator.free(node_ids);
    for (pending_events, node_ids) |pending, *node_id| node_id.* = pending.node_id;
    var snapshot = try TaskMetricEventSnapshot.init(allocator, store, node_ids);
    defer snapshot.deinit();
    const SeenEvent = struct {
        metrics_address: usize,
        node_id: u64,
    };
    var seen = std.AutoHashMap(SeenEvent, void).init(allocator);
    defer seen.deinit();
    for (pending_events) |pending| {
        const key = SeenEvent{
            .metrics_address = @intFromPtr(pending.metrics),
            .node_id = pending.node_id.toInt(),
        };
        if (seen.contains(key)) continue;
        // A task-root copy is intentionally skipped in favor of the direct
        // root event row. Do not mark that skipped path as seen, or the later
        // direct row would be suppressed as a duplicate.
        if (recordTaskMetricEventFromSnapshot(&snapshot, pending)) try seen.put(key, {});
    }
}

fn recordTaskMetricEventFromSnapshot(snapshot: *const TaskMetricEventSnapshot, pending: PendingTaskMetricEvent) bool {
    const fields = snapshot.fields(pending.node_id);
    if (pending.skip_root_id) |root_id| {
        if (fields.task_root_id == root_id.toInt()) return false;
    }
    const concrete_event_type = fields.event_type orelse return true;
    if (std.mem.eql(u8, concrete_event_type, "write_attempt")) {
        pending.metrics.task_write_attempt_events += 1;
    } else if (std.mem.eql(u8, concrete_event_type, "write_error")) {
        pending.metrics.task_write_error_events += 1;
    } else if (std.mem.eql(u8, concrete_event_type, "dependency_edge_created")) {
        if (taskMetricEventRelationIsDependency(fields.dependency_relation)) {
            pending.metrics.dependency_edge_created_events += 1;
        }
    } else if (std.mem.eql(u8, concrete_event_type, "dependency_edge_deleted")) {
        if (taskMetricEventRelationIsDependency(fields.dependency_relation)) {
            pending.metrics.dependency_edge_correction_events += 1;
        }
    } else if (std.mem.eql(u8, concrete_event_type, "prompt_adherence_ok")) {
        pending.metrics.prompt_adherence_ok_events += 1;
    } else if (std.mem.eql(u8, concrete_event_type, "prompt_adherence_miss")) {
        pending.metrics.prompt_adherence_miss_events += 1;
    }
    return true;
}

fn taskMetricEventRelationIsDependency(relation: ?[]const u8) bool {
    const value = relation orelse return false;
    return std.mem.eql(u8, value, "depends_on") or std.mem.eql(u8, value, "blocks");
}

const TaskMetricCompletionLatency = struct {
    created_ns: u128,
    completed_ns: u128,
};

const min_task_metric_epoch_ns: u128 = 1_500_000_000_000_000_000;

fn taskMetricEpochNs(value: ?u128) ?u128 {
    const timestamp = value orelse return null;
    return if (timestamp >= min_task_metric_epoch_ns) timestamp else null;
}

fn optionalU64ToU128(value: ?u64) ?u128 {
    return if (value) |concrete| @as(u128, concrete) else null;
}

fn taskMetricRecordedNsFromFields(fields: task.StatusSnapshot.LifecycleFields) ?u128 {
    return taskMetricEpochNs(optionalU64ToU128(fields.task_created_ns)) orelse
        taskMetricEpochNs(optionalU64ToU128(fields.task_recorded_ns));
}

fn taskMetricCompletionLatencyFromFields(fields: task.StatusSnapshot.LifecycleFields) ?TaskMetricCompletionLatency {
    const created_ns = taskMetricEpochNs(optionalU64ToU128(fields.task_created_ns)) orelse return null;
    const completed_ns = taskMetricEpochNs(optionalU64ToU128(fields.task_completed_ns)) orelse return null;
    if (completed_ns < created_ns) return null;
    return .{ .created_ns = created_ns, .completed_ns = completed_ns };
}

fn taskMetricReadyState(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_id: core.NodeId,
    now_ns: u64,
    lifecycle_snapshot: *const task.StatusSnapshot,
    metrics: *TaskMetrics,
    detail_budget: *TaskMetricDetailBudget,
) !?task.ReadyState {
    const remaining_edges = detail_budget.remaining();
    var stats = task.ReadyTraversalStats{};
    const state = task.readyStateWithPersistentStoreSnapshotBudgetAt(
        allocator,
        store,
        node_id,
        .{
            .max_visited_nodes = std.math.add(usize, remaining_edges, 1) catch std.math.maxInt(usize),
            .max_visited_edges = remaining_edges,
            // The aggregate detail-edge budget, not a fresh per-row clock,
            // is the authoritative bound for this local indexed traversal.
            .timeout_ms = std.math.maxInt(u64),
        },
        now_ns,
        lifecycle_snapshot,
        &stats,
    ) catch |err| {
        detail_budget.absorb(stats.edges_visited);
        if (err == core.Error.BudgetExceeded) {
            detail_budget.markTruncated(metrics);
            return null;
        }
        return err;
    };
    detail_budget.absorb(stats.edges_visited);
    return state;
}

fn countTaskMetricEdges(
    allocator: std.mem.Allocator,
    store: storage.Store,
    order: storage.EdgeIndexOrder,
    owner_id: core.NodeId,
    rel_filter: core.RelKind,
    limit: usize,
    metrics: *TaskMetrics,
    detail_budget: *TaskMetricDetailBudget,
) !usize {
    var count: usize = 0;
    var records = try readVisibleEdgeRecordsByNodeLimited(
        allocator,
        store,
        order,
        owner_id,
        rel_filter,
        taskEdgeLookaheadLimit(@min(limit, detail_budget.remaining())),
    );
    defer records.deinit(allocator);
    for (records.items) |_| {
        if (!detail_budget.charge(metrics)) break;
        if (count >= limit) {
            metrics.truncated = true;
            break;
        }
        count += 1;
    }
    return count;
}

fn countTaskMetricRelatedKind(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_view: anytype,
    node_id: core.NodeId,
    rel_filter: core.RelKind,
    kind: core.NodeKind,
    limit: usize,
    seen: *std.AutoHashMap(u64, void),
    count: *usize,
    metrics: *TaskMetrics,
    detail_budget: *TaskMetricDetailBudget,
) !void {
    var outgoing = try readVisibleEdgeRecordsByNodeLimited(
        allocator,
        store,
        .src,
        node_id,
        rel_filter,
        taskEdgeLookaheadLimit(detail_budget.remaining()),
    );
    defer outgoing.deinit(allocator);
    for (outgoing.items) |record| {
        if (!detail_budget.charge(metrics)) return;
        if (count.* >= limit) {
            metrics.truncated = true;
            return;
        }
        const related_id = core.NodeId.fromInt(record.dst);
        var node = (try node_view.readNodeById(allocator, related_id)) orelse return error.InvalidRecord;
        defer node.deinit(allocator);
        if (node.kind != kind) continue;
        const entry = try seen.getOrPut(related_id.toInt());
        if (!entry.found_existing) count.* += 1;
    }
    var incoming = try readVisibleEdgeRecordsByNodeLimited(
        allocator,
        store,
        .dst,
        node_id,
        rel_filter,
        taskEdgeLookaheadLimit(detail_budget.remaining()),
    );
    defer incoming.deinit(allocator);
    for (incoming.items) |record| {
        if (!detail_budget.charge(metrics)) return;
        if (count.* >= limit) {
            metrics.truncated = true;
            return;
        }
        const related_id = core.NodeId.fromInt(record.src);
        var node = (try node_view.readNodeById(allocator, related_id)) orelse return error.InvalidRecord;
        defer node.deinit(allocator);
        if (node.kind != kind) continue;
        const entry = try seen.getOrPut(related_id.toInt());
        if (!entry.found_existing) count.* += 1;
    }
}

fn countTaskMetricEventKind(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_view: anytype,
    node_id: core.NodeId,
    kind: core.NodeKind,
    limit: usize,
    metrics: *TaskMetrics,
    detail_budget: *TaskMetricDetailBudget,
) !usize {
    const event_relations = [_]core.RelKind{ .related_to, .task_event, .references };
    var seen = std.AutoHashMap(u64, void).init(allocator);
    defer seen.deinit();
    var count: usize = 0;
    inline for (event_relations, 0..) |relation, relation_index| {
        try countTaskMetricRelatedKind(allocator, store, node_view, node_id, relation, kind, limit, &seen, &count, metrics, detail_budget);
        if (count >= limit) {
            // An exact hit in the final relation is complete. Earlier exact
            // hits leave relation classes uninspected and are bounded samples.
            if (relation_index + 1 < event_relations.len) metrics.truncated = true;
            break;
        }
    }
    return count;
}

fn writeTaskPacketNodeRow(
    out: *QueryOutputWriter,
    role: []const u8,
    node_id: core.NodeId,
    kind: core.NodeKind,
    text: []const u8,
) !void {
    try out.print("{s}\t{}\t", .{ role, node_id.toInt() });
    try writeNodeKindName(out, kind);
    try out.writeAll("\t");
    try writeEscapedText(out, text);
    try out.writeAll("\n");
}

fn writeTaskPacketEdgeRows(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_view: anytype,
    out: *QueryOutputWriter,
    role: []const u8,
    order: storage.EdgeIndexOrder,
    owner_id: core.NodeId,
    rel_filter: core.RelKind,
    limit: usize,
) !void {
    var rows: usize = 0;
    var truncated = false;
    var records = try readVisibleEdgeRecordsByNode(allocator, store, order, owner_id, rel_filter);
    defer records.deinit(allocator);
    for (records.items) |record| {
        if (rows >= limit) {
            truncated = true;
            break;
        }
        if (try writeTaskPacketEdgeRow(allocator, store, node_view, out, role, order, record)) rows += 1;
    }
    if (truncated) try out.print("{s}_truncated\tlimit={}\n", .{ role, limit });
}

fn writeTaskPacketRecentEdgeRows(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_view: anytype,
    out: *QueryOutputWriter,
    role: []const u8,
    order: storage.EdgeIndexOrder,
    owner_id: core.NodeId,
    rel_filter: core.RelKind,
    limit: usize,
) !void {
    if (limit == 0) return error.InvalidLimit;

    const recent = try allocator.alloc(storage.EdgeIndexRecord, limit);
    defer allocator.free(recent);

    var scanned: usize = 0;
    var records = try readVisibleEdgeRecordsByNode(allocator, store, order, owner_id, rel_filter);
    defer records.deinit(allocator);
    for (records.items) |record| {
        recent[scanned % limit] = record;
        scanned += 1;
    }

    const emitted = @min(scanned, limit);
    var offset: usize = 0;
    while (offset < emitted) : (offset += 1) {
        const index = (scanned - 1 - offset) % limit;
        _ = try writeTaskPacketEdgeRow(allocator, store, node_view, out, role, order, recent[index]);
    }
    if (scanned > limit) {
        try out.print("{s}_truncated\tlimit={}\tscanned={}\trecent=1\n", .{ role, limit, scanned });
    }
}

fn writeTaskPacketEdgeRow(
    allocator: std.mem.Allocator,
    store: storage.Store,
    node_view: anytype,
    out: *QueryOutputWriter,
    role: []const u8,
    order: storage.EdgeIndexOrder,
    record: storage.EdgeIndexRecord,
) !bool {
    const node_id = switch (order) {
        .src => core.NodeId.fromInt(record.dst),
        .dst => core.NodeId.fromInt(record.src),
        .id => return core.Error.Unsupported,
    };
    var node = (try node_view.readNodeById(allocator, node_id)) orelse return error.InvalidRecord;
    defer node.deinit(allocator);
    if (taskPacketRoleIsGoalAnchor(role) and try nodeHasTaskEventSchema(allocator, store, node.id)) return false;
    try out.print("{s}\t{}\t", .{ role, record.edge_id });
    try writeRelKindName(out, @enumFromInt(record.rel));
    try out.print("\t{}\t", .{node.id.toInt()});
    try writeNodeKindName(out, node.kind);
    try out.writeAll("\t");
    try writeEscapedText(out, node.text);
    try out.writeAll("\n");
    return true;
}

fn taskPacketRoleIsGoalAnchor(role: []const u8) bool {
    return std.mem.eql(u8, role, "goal_anchor_in") or std.mem.eql(u8, role, "goal_anchor_out");
}

fn nodeHasTaskEventSchema(allocator: std.mem.Allocator, store: storage.Store, node_id: core.NodeId) !bool {
    const schema_type = try store.getNodeStringProperty(allocator, node_id, "schema_type");
    defer if (schema_type) |value| allocator.free(value);
    const concrete = schema_type orelse return false;
    return std.mem.eql(u8, concrete, "task_event");
}

fn renderBenchOutput(
    allocator: std.mem.Allocator,
    io: std.Io,
    db_path: []const u8,
    node_count: usize,
    edge_count: usize,
    chunk_size: usize,
    workload: BenchWorkload,
    corpus_file_path: ?[]const u8,
    corpus_dir_path: ?[]const u8,
    edge_id_pattern: BenchEdgeIdPattern,
    edge_delta_stats_enabled: bool,
    edge_tombstone_probe_enabled: bool,
    storage_only: bool,
    agent_mixed: bool,
    edge_compact_batch_entries: u32,
    edge_compact_threshold_entries: u32,
    maintenance_every_ops: usize,
    maintenance_max_segments: usize,
    maintenance_max_edges: u64,
    maintenance_gc: bool,
    maintenance_node_text_every_ops: usize,
    maintenance_node_text_max_records: u64,
    maintenance_node_text_runs_every_ops: usize,
    maintenance_node_text_runs_max_records: u64,
    no_regression_gates: BenchNoRegressionGateLimits,
) ![]u8 {
    var out = QueryOutputWriter{ .allocator = allocator };
    errdefer out.buffer.deinit(allocator);

    var store = try storage.Store.initWithOptions(allocator, io, db_path, .{
        .durability = .fast,
        .primary_text_write_mode = .bulk_ingest,
        .validate_indexes_on_read = false,
        .auto_compact_edge_segment_entries = 0,
        .auto_compact_edge_segment_batch_entries = edge_compact_batch_entries,
        .auto_gc_edge_segments = true,
    });
    var edge_delta_stats = storage.EdgeBatchSegmentDeltaStats{};
    store.edge_batch_segment_delta_stats = &edge_delta_stats;
    var node_batch_timings = storage.NodeBatchAppendTimings{};
    store.node_batch_append_timings = &node_batch_timings;
    var node_append_timings = storage.NodeAppendTimings{};
    store.node_append_timings = &node_append_timings;
    var store_live = true;
    defer if (store_live) store.deinit();
    const text_build_search_prebuilt = benchPrebuildsTextCatalogForSearch(node_count);
    var node_texts_pre_edge_compress_ns: u128 = 0;
    const corpus = if (corpus_file_path) |path| try loadBenchCorpusFile(allocator, io, path) else BenchCorpus{};
    defer corpus.deinit(allocator);
    const text_source = BenchTextSource{ .workload = workload, .corpus = if (corpus_file_path == null) null else &corpus };
    const replay = if (benchWorkloadUsesMetaknowReplay(workload)) try loadBenchMetaknowReplay(allocator, io, corpus_dir_path orelse return error.MissingArgument) else BenchMetaknowReplay{};
    defer replay.deinit(allocator);

    const create_start = monotonicNs(io);
    benchTrace("create_start");
    try store.createEmpty();
    const create_ns = elapsedNs(io, create_start);
    benchTrace("create_done");
    const create_rss = try benchRssSample();
    var bench_phase_store_bytes = BenchPhaseStoreBytes{};
    bench_phase_store_bytes.create = try storeDirBytes(allocator, io, db_path);

    const node_start = monotonicNs(io);
    var text_density = BenchTextDensityStats{};
    var node_load_timings = BenchNodeLoadTimings{};
    benchTrace("initial_nodes_start");
    if (benchWorkloadUsesMetaknowReplay(workload)) {
        try appendBenchMetaknowNodesChunked(allocator, store, &replay, node_count, chunk_size, workload == .metaknow_replay_shaped, &text_density, &node_load_timings);
    } else {
        try appendBenchNodesChunked(allocator, store, node_count, chunk_size, text_source, &text_density, &node_load_timings);
    }
    const add_node_ns = elapsedNs(io, node_start);
    benchTrace("initial_nodes_done");
    const add_node_rss = try benchRssSample();
    const compress_start = monotonicNs(io);
    try store.finalizePrimaryTextStorage();
    node_texts_pre_edge_compress_ns = elapsedNs(io, compress_start);
    bench_phase_store_bytes.add_node = try storeDirBytes(allocator, io, db_path);

    const edge_start = monotonicNs(io);
    benchTrace("initial_edges_start");
    var replay_edge_stats = BenchMetaknowReplayEdgeStats{};
    if (benchWorkloadUsesMetaknowReplay(workload)) {
        replay_edge_stats = try appendBenchMetaknowEdgesChunked(allocator, store, &replay, node_count, edge_count, chunk_size, workload == .metaknow_replay_shaped);
        const deferred_stats = try writeBenchMetaknowDeferredBasedOnSidecar(allocator, store, &replay, node_count);
        replay_edge_stats.deferred_based_on_binary_sources = deferred_stats.sources;
        replay_edge_stats.deferred_based_on_binary_links = deferred_stats.links;
        replay_edge_stats.deferred_based_on_binary_bytes = deferred_stats.bytes;
    } else {
        try appendBenchEdgesChunked(allocator, store, node_count, edge_count, chunk_size, edge_id_pattern);
    }
    const add_edge_total_ns = elapsedNs(io, edge_start);
    benchTrace("initial_edges_done");
    const edge_segment_synchronous_ns = edge_delta_stats.segment_publish_ns + edge_delta_stats.segment_maintenance_ns;
    const add_edge_ns = saturatingSubNs(add_edge_total_ns, edge_segment_synchronous_ns);
    const add_edge_rss = try benchRssSample();
    bench_phase_store_bytes.add_edge = try storeDirBytes(allocator, io, db_path);
    const edge_post_load_maintenance = try runBenchEdgePostLoadMaintenance(io, &store, edge_compact_threshold_entries, edge_compact_batch_entries);
    benchTrace("edge_post_load_maintenance_done");
    const edge_post_load_maintenance_rss = try benchRssSample();
    bench_phase_store_bytes.edge_maintenance = try storeDirBytes(allocator, io, db_path);
    const edge_tombstone_probe = if (edge_tombstone_probe_enabled)
        try runBenchEdgeTombstoneProbe(allocator, io, store, edge_count, edge_id_pattern)
    else
        BenchEdgeTombstoneProbeStats{};

    if (agent_mixed) {
        benchTrace("agent_mixed_start");
        return renderBenchAgentMixedOutput(
            allocator,
            io,
            store,
            db_path,
            node_count,
            edge_count,
            chunk_size,
            workload,
            text_source,
            corpus_file_path,
            corpus_dir_path,
            &text_density,
            edge_id_pattern,
            edge_compact_batch_entries,
            edge_compact_threshold_entries,
            maintenance_every_ops,
            maintenance_max_segments,
            maintenance_max_edges,
            maintenance_gc,
            maintenance_node_text_every_ops,
            maintenance_node_text_max_records,
            maintenance_node_text_runs_every_ops,
            maintenance_node_text_runs_max_records,
            create_ns,
            add_node_ns,
            add_edge_ns,
            create_rss,
            add_node_rss,
            add_edge_rss,
            edge_post_load_maintenance_rss,
            edge_post_load_maintenance,
            node_load_timings,
            node_batch_timings,
        );
    }

    if (storage_only) {
        const stats_out = try store.stats();
        store.deinit();
        store_live = false;
        const store_deinit_rss = try benchRssSample();
        bench_phase_store_bytes.store_deinit = try storeDirBytes(allocator, io, db_path);

        const open_start = monotonicNs(io);
        var reopened = try storage.Store.openWithOptions(allocator, io, db_path, .{
            .durability = .fast,
            .validate_indexes_on_read = false,
        });
        const open_ns = elapsedNs(io, open_start);
        const open_rss = try benchRssSample();
        bench_phase_store_bytes.open = try storeDirBytes(allocator, io, db_path);
        defer reopened.deinit();

        var validate_timings = storage.PersistentValidateTimings{};
        const validate_start = monotonicNs(io);
        try reopened.validatePersistentIndexesWithTimings(&validate_timings);
        const validate_ns = elapsedNs(io, validate_start);
        const validate_rss = try benchRssSample();
        bench_phase_store_bytes.validate = try storeDirBytes(allocator, io, db_path);
        const validate_rss_bytes = validate_rss.peak_bytes;
        const validate_current_rss_bytes = validate_rss.current_bytes;

        var repair_timings = storage.PersistentRepairTimings{};
        const repair_start = monotonicNs(io);
        try reopened.repairPersistentIndexesFromLogWithTimings(&repair_timings);
        const repair_ns = elapsedNs(io, repair_start);
        const repair_rss = try benchRssSample();
        bench_phase_store_bytes.repair = try storeDirBytes(allocator, io, db_path);
        const repair_rss_bytes = repair_rss.peak_bytes;
        const repair_current_rss_bytes = repair_rss.current_bytes;
        const ordered_edge_traversal = try benchOrderedEdgeTraversalProbe(allocator, io, reopened);

        const text_rebuild_start = monotonicNs(io);
        var text_rebuild_timings = text_search.PersistentTextRebuildTimings{};
        var text_rebuild_phase_rss = BenchTextRebuildPhaseRss{};
        const runs_base_path = try benchTextPostingRunsBasePath(allocator, db_path);
        defer allocator.free(runs_base_path);
        const result = rebuildPersistentTextCatalogForBenchWithPhaseRss(allocator, reopened, runs_base_path, &text_rebuild_phase_rss) catch |err|
            return benchBudgetPhase(err, error.BenchStorageOnlyTextRebuildBudgetExceeded);
        text_rebuild_timings = result.timings;
        const text_rebuild_ns = elapsedNs(io, text_rebuild_start);
        const text_rebuild_rss = try benchRssSample();
        bench_phase_store_bytes.text_rebuild = try storeDirBytes(allocator, io, db_path);
        const text_rebuild_rss_bytes = text_rebuild_rss.peak_bytes;
        const text_rebuild_current_rss_bytes = text_rebuild_rss.current_bytes;
        const text_index_bytes = try benchTextIndexBytes(allocator, io, db_path);
        const edge_segments_bytes = try benchEdgeSegmentBytes(allocator, io, db_path);
        const node_texts_compression = try benchNodeTextsCompressionEstimate(allocator, io, db_path);
        const posting_compression = try text_search.estimatePersistentPostingCompression(allocator, reopened);
        const density_breakdown = try benchDensityBreakdown(allocator, io, db_path, reopened, stats_out);
        const replay_warm_stats = if (benchWorkloadUsesMetaknowReplay(workload))
            try benchMetaknowReplayWarmStats(allocator, io, reopened, &replay, node_count, edge_count, workload == .metaknow_replay_shaped)
        else
            BenchMetaknowReplayWarmStats{};

        const total_bytes = try storeDirBytes(allocator, io, db_path);
        const edge_order_bytes = try benchEdgeOrderBytes(allocator, io, db_path);
        const rss_bytes = try peakRssBytes();
        const current_rss_bytes = try currentRssBytes();
        const current_footprint_bytes = try currentFootprintBytes();
        const footprint_samples = [_]BenchRssSample{
            create_rss,
            add_node_rss,
            add_edge_rss,
            edge_post_load_maintenance_rss,
            store_deinit_rss,
            open_rss,
            validate_rss,
            repair_rss,
            text_rebuild_rss,
            .{ .peak_bytes = rss_bytes, .current_bytes = current_rss_bytes, .footprint_bytes = current_footprint_bytes },
        };
        const footprint_peak_bytes = maxBenchFootprintBytes(&footprint_samples, text_rebuild_phase_rss);
        try out.print(
            "shape={s}\nbench_workload={s}\nbuild_optimize={s}\nmode=storage-only\ntext_rebuild_mode={s}\nnodes={} edges={} bytes={} rss_bytes={} current_rss_bytes={} footprint_peak_bytes={} current_footprint_bytes={} chunk={} edge_id_pattern={s} edge_compact_batch={} edge_compact_threshold={} edge_auto_gc=1\n",
            .{
                workload.shapeLabel(),
                workload.label(),
                buildOptimizeLabel(),
                "runs",
                stats_out.nodes,
                stats_out.edges,
                total_bytes,
                rss_bytes,
                current_rss_bytes,
                footprint_peak_bytes,
                current_footprint_bytes,
                chunk_size,
                edge_id_pattern.label(),
                edge_compact_batch_entries,
                edge_compact_threshold_entries,
            },
        );
        try out.print(
            "bench_corpus_file={s}\nbench_corpus_dir={s}\nbench_corpus_records={}\n",
            .{ corpus_file_path orelse "", corpus_dir_path orelse "", text_source.corpusRecordCount() },
        );
        try appendBenchMetaknowReplayStats(&out, replay.statsForOutput(node_count, workload == .metaknow_replay_shaped), replay_edge_stats, replay_warm_stats);
        try out.print(
            "edge_tombstone_probe_enabled={} edge_tombstone_probe_requested={} edge_tombstone_probe_deleted={} edge_tombstone_probe_ns={}\nedge_tombstone_probe_visible_edges={} edge_tombstone_probe_physical_edges={} edge_tombstone_probe_tombstone_edges={} edge_tombstone_probe_tombstone_ratio_bps={}\n",
            .{
                @intFromBool(edge_tombstone_probe_enabled),
                edge_tombstone_probe.requested,
                edge_tombstone_probe.deleted,
                edge_tombstone_probe.ns,
                edge_tombstone_probe.visible_edges,
                edge_tombstone_probe.physical_edges,
                edge_tombstone_probe.tombstone_edges,
                edge_tombstone_probe.tombstone_ratio_bps,
            },
        );
        try out.print(
            "create_ns={}\nadd_node_ns={} add_node_ns_per={} node_texts_pre_edge_compress_ns={}\nadd_edge_ns={} add_edge_ns_per={} add_edge_total_ns={} add_edge_total_ns_per={} edge_segment_synchronous_ns={} edge_segment_publish_ns={} edge_segment_maintenance_ns={}\n",
            .{
                create_ns,
                add_node_ns,
                perOpNs(add_node_ns, node_count),
                node_texts_pre_edge_compress_ns,
                add_edge_ns,
                perOpNs(add_edge_ns, edge_count),
                add_edge_total_ns,
                perOpNs(add_edge_total_ns, edge_count),
                edge_segment_synchronous_ns,
                edge_delta_stats.segment_publish_ns,
                edge_delta_stats.segment_maintenance_ns,
            },
        );
        try out.print(
            "open_ns={} validate_ns={} validate_stats_ns={} validate_index_files_ns={} repair_ns={} text_rebuild_ns={}\n",
            .{
                open_ns,
                validate_ns,
                validate_timings.stats_ns,
                validate_timings.index_files_ns,
                repair_ns,
                text_rebuild_ns,
            },
        );
        try out.print(
            "validate_rss_bytes={} validate_current_rss_bytes={} repair_rss_bytes={} repair_current_rss_bytes={} text_rebuild_rss_bytes={} text_rebuild_current_rss_bytes={}\n",
            .{
                validate_rss_bytes,
                validate_current_rss_bytes,
                repair_rss_bytes,
                repair_current_rss_bytes,
                text_rebuild_rss_bytes,
                text_rebuild_current_rss_bytes,
            },
        );
        try appendBenchPhaseRss(
            &out,
            create_rss,
            add_node_rss,
            add_edge_rss,
            edge_post_load_maintenance_rss,
            null,
            store_deinit_rss,
            open_rss,
            validate_rss,
            repair_rss,
            text_rebuild_rss,
        );
        try appendBenchPhaseStoreBytes(&out, bench_phase_store_bytes);
        try appendBenchOrderedEdgeMetrics(&out, edge_order_bytes, ordered_edge_traversal);
        try out.print(
            "edge_post_load_maintenance_ns={} edge_post_load_maintenance_compactions={}\n",
            .{ edge_post_load_maintenance.ns, edge_post_load_maintenance.compactions },
        );
        try appendNodeBatchAppendTimings(&out, node_load_timings, node_batch_timings);
        try appendBenchDensityMetrics(&out, &text_density, total_bytes, text_index_bytes, edge_segments_bytes, node_texts_compression, posting_compression, density_breakdown);
        if (edge_delta_stats_enabled) try appendEdgeDeltaStats(&out, edge_delta_stats);
        try appendValidateTimings(&out, validate_timings);
        try appendRepairTimings(&out, repair_timings);
        try appendTextRebuildTimings(&out, text_rebuild_timings);
        try appendTextRebuildPhaseRss(&out, text_rebuild_phase_rss);
        return out.buffer.toOwnedSlice(allocator);
    }

    var text_rebuild_timings = text_search.PersistentTextRebuildTimings{};
    var text_rebuild_ns: u128 = 0;
    var text_rebuild_rss_bytes: usize = 0;
    var text_rebuild_current_rss_bytes: usize = 0;
    var text_rebuild_rss = BenchRssSample{ .peak_bytes = 0, .current_bytes = 0, .footprint_bytes = 0 };
    var text_rebuild_phase_rss = BenchTextRebuildPhaseRss{};
    var repair_timings = storage.PersistentRepairTimings{};
    var repair_ns: u128 = 0;
    var repair_final_compress_ns: u128 = 0;
    var repair_rss = BenchRssSample{ .peak_bytes = 0, .current_bytes = 0, .footprint_bytes = 0 };
    var repair_rss_bytes: u64 = 0;
    var repair_current_rss_bytes: u64 = 0;
    if (text_build_search_prebuilt) {
        benchTrace("pre_search_repair_start");
        const repair_start = monotonicNs(io);
        try store.repairPersistentIndexesFromLogWithTimings(&repair_timings);
        repair_ns = elapsedNs(io, repair_start);
        repair_rss = try benchRssSample();
        bench_phase_store_bytes.repair = try storeDirBytes(allocator, io, db_path);
        repair_rss_bytes = repair_rss.peak_bytes;
        repair_current_rss_bytes = repair_rss.current_bytes;
        benchTrace("pre_search_repair_done");
    }

    const lookup_node_id = try benchExactTextLookupNodeId(node_count, text_source);
    const lookup_text = try benchNodeText(allocator, lookup_node_id, text_source);
    defer allocator.free(lookup_text);
    const lookup_base_text = try benchNodeText(allocator, 1, text_source);
    defer allocator.free(lookup_base_text);
    benchTraceOp("lookup_node_id", lookup_node_id);
    benchTrace("lookup_start");
    var lookup_full_timing_breakdown = storage.Store.NodeTextLookupTimings{};
    const lookup_start = monotonicNs(io);
    var matches = store.lookupNodesByTextLimitedWithTimings(allocator, .file, lookup_text, 1, &lookup_full_timing_breakdown) catch |err| {
        benchTrace("lookup_graph_error");
        return err;
    };
    const lookup_ns = elapsedNs(io, lookup_start);
    benchTraceOp("lookup_graph_rows", matches.items.len);
    if (matches.items.len != 1) {
        for (matches.items) |*node| node.deinit(allocator);
        matches.deinit(allocator);
        return error.InvalidRecord;
    }
    for (matches.items) |*node| node.deinit(allocator);
    matches.deinit(allocator);
    benchTrace("lookup_graph_done");

    var lookup_open_timing_breakdown = storage.Store.NodeTextLookupOpenTimings{};
    const lookup_view_open_start = monotonicNs(io);
    var lookup_view = try store.openNodeTextLookupViewWithTimings(allocator, &lookup_open_timing_breakdown);
    const lookup_view_open_ns = elapsedNs(io, lookup_view_open_start);
    defer lookup_view.deinit();
    benchTrace("lookup_view_open_done");

    var lookup_timing_breakdown = storage.Store.NodeTextLookupTimings{};
    const lookup_ids_retained_start = monotonicNs(io);
    var lookup_ids_retained = try lookup_view.lookupIdsWithTimings(allocator, .file, lookup_text, 1, &lookup_timing_breakdown);
    const lookup_ids_retained_ns = elapsedNs(io, lookup_ids_retained_start);
    if (lookup_ids_retained.items.len != 1) {
        lookup_ids_retained.deinit(allocator);
        return error.InvalidRecord;
    }
    lookup_ids_retained.deinit(allocator);

    const lookup_ids_retained_hot_start = monotonicNs(io);
    var lookup_ids_retained_hot = try lookup_view.lookupIds(allocator, .file, lookup_text, 1);
    const lookup_ids_retained_hot_ns = elapsedNs(io, lookup_ids_retained_hot_start);
    if (lookup_ids_retained_hot.items.len != 1) {
        lookup_ids_retained_hot.deinit(allocator);
        return error.InvalidRecord;
    }
    lookup_ids_retained_hot.deinit(allocator);

    var lookup_retained_samples: [bench_tinyql_suite_samples]u128 = undefined;
    var lookup_retained_rows_last: usize = 0;
    for (&lookup_retained_samples) |*sample| {
        const sample_start = monotonicNs(io);
        var lookup_retained = try lookup_view.lookupIds(allocator, .file, lookup_text, 1);
        sample.* = elapsedNs(io, sample_start);
        if (lookup_retained.items.len != 1) {
            lookup_retained.deinit(allocator);
            return error.InvalidRecord;
        }
        lookup_retained_rows_last = lookup_retained.items.len;
        lookup_retained.deinit(allocator);
    }
    const lookup_retained_stats = latencyStats(&lookup_retained_samples);

    var lookup_base_timing_breakdown = storage.Store.NodeTextLookupTimings{};
    const lookup_base_first = try lookup_view.lookupFirstIdWithTimings(.file, lookup_base_text, &lookup_base_timing_breakdown);
    if (lookup_base_first == null or lookup_base_first.?.toInt() != 1) return error.InvalidRecord;
    var lookup_base_retained_samples: [bench_tinyql_suite_samples]u128 = undefined;
    var lookup_base_retained_rows_last: usize = 0;
    for (&lookup_base_retained_samples) |*sample| {
        const sample_start = monotonicNs(io);
        const base_id = try lookup_view.lookupFirstId(.file, lookup_base_text);
        sample.* = elapsedNs(io, sample_start);
        if (base_id == null or base_id.?.toInt() != 1) return error.InvalidRecord;
        lookup_base_retained_rows_last = 1;
    }
    const lookup_base_retained_stats = latencyStats(&lookup_base_retained_samples);
    benchTrace("lookup_retained_done");

    const lookup_ids_public_start = monotonicNs(io);
    var lookup_ids_public_timing_breakdown = storage.Store.NodeTextLookupTimings{};
    var lookup_ids_public = try store.lookupNodeIdsByTextLimitedWithTimings(allocator, .file, lookup_text, 1, &lookup_ids_public_timing_breakdown);
    const lookup_ids_public_ns = elapsedNs(io, lookup_ids_public_start);
    if (lookup_ids_public.items.len != 1) {
        lookup_ids_public.deinit(allocator);
        return error.InvalidRecord;
    }
    lookup_ids_public.deinit(allocator);
    var lookup_base_public_timing_breakdown = storage.Store.NodeTextLookupTimings{};
    const lookup_base_public_start = monotonicNs(io);
    var lookup_base_public = try store.lookupNodeIdsByTextLimitedWithTimings(allocator, .file, lookup_base_text, 1, &lookup_base_public_timing_breakdown);
    const lookup_base_public_ns = elapsedNs(io, lookup_base_public_start);
    if (lookup_base_public.items.len != 1 or lookup_base_public.items[0].toInt() != 1) {
        lookup_base_public.deinit(allocator);
        return error.InvalidRecord;
    }
    lookup_base_public.deinit(allocator);

    var lookup_first_public_timing_breakdown = storage.Store.NodeTextLookupTimings{};
    const lookup_first_public_start = monotonicNs(io);
    const lookup_first_public = try store.lookupFirstNodeIdByTextWithTimings(allocator, .file, lookup_text, &lookup_first_public_timing_breakdown);
    const lookup_first_public_ns = elapsedNs(io, lookup_first_public_start);
    if (lookup_first_public == null) return error.InvalidRecord;

    var lookup_base_first_public_timing_breakdown = storage.Store.NodeTextLookupTimings{};
    const lookup_base_first_public_start = monotonicNs(io);
    const lookup_base_first_public = try store.lookupFirstNodeIdByTextWithTimings(allocator, .file, lookup_base_text, &lookup_base_first_public_timing_breakdown);
    const lookup_base_first_public_ns = elapsedNs(io, lookup_base_first_public_start);
    if (lookup_base_first_public == null or lookup_base_first_public.?.toInt() != 1) return error.InvalidRecord;

    const lookup_ids_public_samples = try benchPublicNodeTextIdLookupSamples(allocator, io, store, .file, lookup_text, null);
    const lookup_base_public_samples = try benchPublicNodeTextIdLookupSamples(allocator, io, store, .file, lookup_base_text, 1);
    const lookup_first_public_samples = try benchPublicNodeTextFirstIdLookupSamples(allocator, io, store, .file, lookup_text, null);
    const lookup_base_first_public_samples = try benchPublicNodeTextFirstIdLookupSamples(allocator, io, store, .file, lookup_base_text, 1);
    benchTrace("lookup_public_done");

    const neighbors_start = monotonicNs(io);
    var neighbors = query.neighborsWithPersistentStore(allocator, store, .fromInt(1), .mentions, .{}) catch |err|
        return benchBudgetPhase(err, error.BenchNeighborsBudgetExceeded);
    const neighbors_ns = elapsedNs(io, neighbors_start);
    if (neighbors.stats.budget_exceeded) {
        neighbors.deinit(allocator);
        return error.BenchNeighborsBudgetExceeded;
    }
    const neighbors_len = neighbors.neighbors.items.len;
    const neighbors_nodes_visited = neighbors.stats.nodes_visited;
    const neighbors_edges_visited = neighbors.stats.edges_visited;
    neighbors.deinit(allocator);
    benchTrace("neighbors_hit_done");

    const neighbors_rel_miss_start = monotonicNs(io);
    var neighbors_rel_miss = query.neighborsWithPersistentStore(allocator, store, .fromInt(1), .defines, .{}) catch |err|
        return benchBudgetPhase(err, error.BenchNeighborsRelMissBudgetExceeded);
    const neighbors_rel_miss_ns = elapsedNs(io, neighbors_rel_miss_start);
    if (neighbors_rel_miss.stats.budget_exceeded) {
        neighbors_rel_miss.deinit(allocator);
        return error.BenchNeighborsRelMissBudgetExceeded;
    }
    const neighbors_rel_miss_len = neighbors_rel_miss.neighbors.items.len;
    const neighbors_rel_miss_nodes_visited = neighbors_rel_miss.stats.nodes_visited;
    const neighbors_rel_miss_edges_visited = neighbors_rel_miss.stats.edges_visited;
    neighbors_rel_miss.deinit(allocator);
    if (neighbors_rel_miss_len != 0) return error.InvalidRecord;
    benchTrace("neighbors_miss_done");

    const ordered_edge_traversal = try benchOrderedEdgeTraversalProbe(allocator, io, store);
    benchTrace("ordered_edge_traversal_done");

    const search_query = try benchSearchQuery(allocator, node_count);
    defer allocator.free(search_query);
    if (text_build_search_prebuilt) {
        benchTrace("text_rebuild_pre_search_start");
        const text_rebuild_start = monotonicNs(io);
        const runs_base_path = try benchTextPostingRunsBasePath(allocator, db_path);
        defer allocator.free(runs_base_path);
        const result = rebuildPersistentTextCatalogForBenchWithPhaseRss(allocator, store, runs_base_path, &text_rebuild_phase_rss) catch |err|
            return benchBudgetPhase(err, error.BenchTextRebuildBudgetExceeded);
        text_rebuild_timings = result.timings;
        text_rebuild_ns = elapsedNs(io, text_rebuild_start);
        text_rebuild_rss = try benchRssSample();
        bench_phase_store_bytes.text_rebuild = try storeDirBytes(allocator, io, db_path);
        text_rebuild_rss_bytes = text_rebuild_rss.peak_bytes;
        text_rebuild_current_rss_bytes = text_rebuild_rss.current_bytes;
        benchTrace("text_rebuild_pre_search_done");
    }
    const text_build_search_start = monotonicNs(io);
    var cold_hits = text_search.searchText(allocator, store, search_query, .{ .limit = 8 }) catch |err|
        return benchBudgetPhase(err, error.BenchTextBuildSearchBudgetExceeded);
    const text_build_search_ns = elapsedNs(io, text_build_search_start);
    if (cold_hits.items.len == 0) {
        cold_hits.deinit(allocator);
        return error.InvalidRecord;
    }
    cold_hits.deinit(allocator);

    const search_start = monotonicNs(io);
    var hits = text_search.searchText(allocator, store, search_query, .{ .limit = 8 }) catch |err|
        return benchBudgetPhase(err, error.BenchTextWarmSearchBudgetExceeded);
    const search_ns = elapsedNs(io, search_start);
    const search_hits = hits.items.len;
    hits.deinit(allocator);
    if (search_hits == 0) return error.InvalidRecord;

    const path_query = try benchPathSearchQuery(allocator, node_count);
    defer allocator.free(path_query);
    const text_code = benchTextProbe(allocator, store, "parseInvalidRecord") catch |err|
        return benchBudgetPhase(err, error.BenchTextCodeBudgetExceeded);
    const text_path = benchTextProbe(allocator, store, path_query) catch |err|
        return benchBudgetPhase(err, error.BenchTextPathBudgetExceeded);
    const text_english = benchTextProbe(allocator, store, "agent latency budget") catch |err|
        return benchBudgetPhase(err, error.BenchTextEnglishBudgetExceeded);
    const text_cjk = benchTextProbe(allocator, store, "错误记录") catch |err|
        return benchBudgetPhase(err, error.BenchTextCjkBudgetExceeded);
    const text_japanese = benchTextProbe(allocator, store, "エラー解析") catch |err|
        return benchBudgetPhase(err, error.BenchTextJapaneseBudgetExceeded);
    const text_korean = benchTextProbe(allocator, store, "오류") catch |err|
        return benchBudgetPhase(err, error.BenchTextKoreanBudgetExceeded);
    const text_highfreq = benchTextProbe(allocator, store, "common") catch |err|
        return benchBudgetPhase(err, error.BenchTextHighfreqBudgetExceeded);

    const tinyql_lookup_query = try benchTinyQlLookupQuery(allocator, lookup_text);
    defer allocator.free(tinyql_lookup_query);
    const tinyql_path_query = try benchTinyQlPathQuery(allocator, lookup_text);
    defer allocator.free(tinyql_path_query);
    const reachable_from_text = try benchNodeText(allocator, 1, text_source);
    defer allocator.free(reachable_from_text);
    const reachable_to_text = try benchNodeText(allocator, @min(node_count, 3), text_source);
    defer allocator.free(reachable_to_text);
    const tinyql_context_render_query = try benchTinyQlContextQuery(allocator, lookup_text);
    defer allocator.free(tinyql_context_render_query);
    const tinyql_reachable_render_query = try benchTinyQlReachableQuery(allocator, reachable_from_text, reachable_to_text, benchHasPositiveReachableFixture(node_count, edge_count));
    defer allocator.free(tinyql_reachable_render_query);
    const tinyql_text_context_render_query = try benchTinyQlTextContextQuery(allocator, "benchdoc1");
    defer allocator.free(tinyql_text_context_render_query);
    const tinyql_text_path_render_query = try benchTinyQlTextPathQuery(allocator, "benchdoc1");
    defer allocator.free(tinyql_text_path_render_query);
    const tinyql_text_reachable_render_query = try benchTinyQlTextReachableQuery(allocator, "benchdoc1", reachable_to_text, benchHasPositiveReachableFixture(node_count, edge_count));
    defer allocator.free(tinyql_text_reachable_render_query);
    const tinyql_text_unreachable_render_query = try benchTinyQlTextUnreachableQuery(allocator, "benchdoc1", benchHasPositiveReachableFixture(node_count, edge_count));
    defer allocator.free(tinyql_text_unreachable_render_query);
    const tinyql_text_mixed_render_query = try benchTinyQlTextMixedRenderQuery(allocator, "benchdoc1", reachable_to_text, benchHasPositiveReachableFixture(node_count, edge_count));
    defer allocator.free(tinyql_text_mixed_render_query);
    const tinyql_lookup = benchTinyQlProbe(allocator, io, store, tinyql_lookup_query) catch |err|
        return benchBudgetPhase(err, error.BenchTinyQlLookupBudgetExceeded);
    const tinyql_text = benchTinyQlProbe(allocator, io, store, "MATCH TEXT \"错误记录\" AS f:file RETURN f LIMIT 8") catch |err|
        return benchBudgetPhase(err, error.BenchTinyQlTextBudgetExceeded);
    const tinyql_expand = benchTinyQlProbe(allocator, io, store, "MATCH TEXT \"benchdoc1\" AS f:file MATCH (f)-[:mentions]->(n:file) RETURN n LIMIT 8") catch |err|
        return benchBudgetPhase(err, error.BenchTinyQlExpandBudgetExceeded);
    const tinyql_path_probe = benchTinyQlProbe(allocator, io, store, tinyql_path_query) catch |err|
        return benchBudgetPhase(err, error.BenchTinyQlPathBudgetExceeded);
    const tinyql_lookup_suite = benchTinyQlSuite(allocator, io, store, tinyql_lookup_query) catch |err|
        return benchBudgetPhase(err, error.BenchTinyQlLookupSuiteBudgetExceeded);
    const tinyql_text_suite = benchTinyQlSuite(allocator, io, store, "MATCH TEXT \"错误记录\" AS f:file RETURN f LIMIT 8") catch |err|
        return benchBudgetPhase(err, error.BenchTinyQlTextSuiteBudgetExceeded);
    const tinyql_expand_suite = benchTinyQlSuite(allocator, io, store, "MATCH TEXT \"benchdoc1\" AS f:file MATCH (f)-[:mentions]->(n:file) RETURN n LIMIT 8") catch |err|
        return benchBudgetPhase(err, error.BenchTinyQlExpandSuiteBudgetExceeded);
    const tinyql_path_suite = benchTinyQlSuite(allocator, io, store, tinyql_path_query) catch |err|
        return benchBudgetPhase(err, error.BenchTinyQlPathSuiteBudgetExceeded);
    const tinyql_path_render_suite = benchTinyQlRenderSuite(allocator, io, store, tinyql_path_query) catch |err|
        return benchBudgetPhase(err, error.BenchTinyQlPathRenderBudgetExceeded);
    const tinyql_context_render_suite = benchTinyQlRenderSuite(allocator, io, store, tinyql_context_render_query) catch |err|
        return benchBudgetPhase(err, error.BenchTinyQlContextRenderBudgetExceeded);
    const tinyql_reachable_render_suite = benchTinyQlRenderSuite(allocator, io, store, tinyql_reachable_render_query) catch |err|
        return benchBudgetPhase(err, error.BenchTinyQlReachableRenderBudgetExceeded);
    const tinyql_text_context_render_suite = benchTinyQlRenderSuite(allocator, io, store, tinyql_text_context_render_query) catch |err|
        return benchBudgetPhase(err, error.BenchTinyQlTextContextRenderBudgetExceeded);
    const tinyql_text_path_render_suite = benchTinyQlRenderSuite(allocator, io, store, tinyql_text_path_render_query) catch |err|
        return benchBudgetPhase(err, error.BenchTinyQlTextPathRenderBudgetExceeded);
    const tinyql_text_reachable_render_suite = benchTinyQlRenderSuite(allocator, io, store, tinyql_text_reachable_render_query) catch |err|
        return benchBudgetPhase(err, error.BenchTinyQlTextReachableRenderBudgetExceeded);
    const tinyql_text_unreachable_render_suite = benchTinyQlRenderSuite(allocator, io, store, tinyql_text_unreachable_render_query) catch |err|
        return benchBudgetPhase(err, error.BenchTinyQlTextUnreachableRenderBudgetExceeded);
    const tinyql_text_mixed_render_suite = benchTinyQlRenderSuite(allocator, io, store, tinyql_text_mixed_render_query) catch |err|
        return benchBudgetPhase(err, error.BenchTinyQlTextMixedRenderBudgetExceeded);

    const path_to = core.NodeId.fromInt(@intCast(@min(node_count, 4)));
    const path_start = monotonicNs(io);
    var path = query.pathWithPersistentStore(allocator, store, .fromInt(1), path_to, .mentions, .{
        .max_depth = 4,
        .max_results = 8,
    }) catch |err| return benchBudgetPhase(err, error.BenchPathBudgetExceeded);
    const path_ns = elapsedNs(io, path_start);
    if (path.stats.budget_exceeded) {
        path.deinit(allocator);
        return error.BenchPathBudgetExceeded;
    }
    const path_nodes_len = path.nodes.items.len;
    const path_nodes_visited = path.stats.nodes_visited;
    const path_edges_visited = path.stats.edges_visited;
    path.deinit(allocator);
    if (path_nodes_len == 0) return error.InvalidRecord;
    const query_rss = try benchRssSample();
    bench_phase_store_bytes.query = try storeDirBytes(allocator, io, db_path);

    const stats_out = try store.stats();
    store.deinit();
    store_live = false;
    const store_deinit_rss = try benchRssSample();
    bench_phase_store_bytes.store_deinit = try storeDirBytes(allocator, io, db_path);

    const open_start = monotonicNs(io);
    var reopened = try storage.Store.openWithOptions(allocator, io, db_path, .{
        .durability = .fast,
        .validate_indexes_on_read = false,
    });
    const open_ns = elapsedNs(io, open_start);
    const open_rss = try benchRssSample();
    bench_phase_store_bytes.open = try storeDirBytes(allocator, io, db_path);
    defer reopened.deinit();

    var validate_timings = storage.PersistentValidateTimings{};
    const validate_start = monotonicNs(io);
    try reopened.validatePersistentIndexesWithTimings(&validate_timings);
    const validate_ns = elapsedNs(io, validate_start);
    const validate_rss = try benchRssSample();
    bench_phase_store_bytes.validate = try storeDirBytes(allocator, io, db_path);
    const validate_rss_bytes = validate_rss.peak_bytes;
    const validate_current_rss_bytes = validate_rss.current_bytes;

    if (!text_build_search_prebuilt) {
        const repair_start = monotonicNs(io);
        try reopened.repairPersistentIndexesFromLogWithTimings(&repair_timings);
        repair_ns = elapsedNs(io, repair_start);
        repair_rss = try benchRssSample();
        bench_phase_store_bytes.repair = try storeDirBytes(allocator, io, db_path);
        repair_rss_bytes = repair_rss.peak_bytes;
        repair_current_rss_bytes = repair_rss.current_bytes;
    } else {
        const repair_start = monotonicNs(io);
        try reopened.finalizePrimaryTextStorage();
        repair_final_compress_ns = elapsedNs(io, repair_start);
        repair_ns += repair_final_compress_ns;
        repair_rss = try benchRssSample();
        bench_phase_store_bytes.repair = try storeDirBytes(allocator, io, db_path);
        repair_rss_bytes = repair_rss.peak_bytes;
        repair_current_rss_bytes = repair_rss.current_bytes;
    }

    if (!text_build_search_prebuilt) {
        const text_rebuild_start = monotonicNs(io);
        const runs_base_path = try benchTextPostingRunsBasePath(allocator, db_path);
        defer allocator.free(runs_base_path);
        const result = rebuildPersistentTextCatalogForBenchWithPhaseRss(allocator, reopened, runs_base_path, &text_rebuild_phase_rss) catch |err|
            return benchBudgetPhase(err, error.BenchTextRebuildBudgetExceeded);
        text_rebuild_timings = result.timings;
        text_rebuild_ns = elapsedNs(io, text_rebuild_start);
        text_rebuild_rss = try benchRssSample();
        bench_phase_store_bytes.text_rebuild = try storeDirBytes(allocator, io, db_path);
        text_rebuild_rss_bytes = text_rebuild_rss.peak_bytes;
        text_rebuild_current_rss_bytes = text_rebuild_rss.current_bytes;
    }
    const post_repair_lookup = try benchNodeTextLookupProbe(allocator, io, reopened, lookup_text, lookup_base_text);
    const text_index_bytes = try benchTextIndexBytes(allocator, io, db_path);
    const edge_segments_bytes = try benchEdgeSegmentBytes(allocator, io, db_path);
    const node_texts_compression = try benchNodeTextsCompressionEstimate(allocator, io, db_path);
    const posting_compression = try text_search.estimatePersistentPostingCompression(allocator, reopened);
    const density_breakdown = try benchDensityBreakdown(allocator, io, db_path, reopened, stats_out);

    var text_repair_search_ns: u128 = 0;
    var text_stale_search_ns: u128 = 0;
    const text_repair_search_skipped = !benchRunsDestructiveTextRepairProbes(node_count);
    const text_stale_search_skipped = text_repair_search_skipped;
    if (!text_repair_search_skipped) {
        try corruptBenchTextPostings(allocator, io, db_path);
        const text_repair_search_start = monotonicNs(io);
        var repaired_hits = text_search.searchText(allocator, reopened, search_query, .{ .limit = 8 }) catch |err|
            return benchBudgetPhase(err, error.BenchTextRepairSearchBudgetExceeded);
