fn appendRatioMetric(out: *QueryOutputWriter, comptime key: []const u8, numerator: u64, denominator: u64) !void {
    const scale: u128 = 1_000_000;
    const scaled = (@as(u128, numerator) * scale) / @as(u128, denominator);
    try out.print("{s}={d}.{d:0>6}\n", .{ key, scaled / scale, scaled % scale });
}

const governance_sample_limit: usize = 8;
const governance_high_fanout_threshold: u64 = 128;
const governance_navigation_fanout_target_min: u64 = 5;
const governance_navigation_fanout_target_max: u64 = 32;
const governance_navigation_fanout_warn_threshold: u64 = 64;
const governance_high_fanout_name_sample_bytes: usize = 256;
const deleted_node_tombstone_prefix = "__tinykg_deleted_node__ ";

fn isDeletedNodeTombstone(node: storage.StoredNode) bool {
    return node.kind == .edit and std.mem.startsWith(u8, node.text, deleted_node_tombstone_prefix);
}

const BackupStoreResult = struct {
    nodes: u64,
    edges: u64,
    source_store_bytes: u64,
    backup_store_bytes: u64,
    marker_cleanup_pending: bool = false,
};

const BackupTransactionExpectation = struct {
    canonical_source_path: []const u8,
    nodes: u64,
    edges: u64,
    source_store_bytes: u64,
    source_store_digest: ContentDigest,
    source_payload_bytes: u64,
    source_payload_digest: ContentDigest,
};

const BackupTransactionMarkerJson = struct {
    format: []const u8,
    canonical_source_path: []const u8,
    nodes: u64,
    edges: u64,
    source_store_bytes: u64,
    source_store_digest: ContentDigest,
    source_payload_bytes: u64,
    source_payload_digest: ContentDigest,
    complete: bool,
};

const BackupMarkerState = struct {
    complete: bool,
    legacy_format: bool,
};

fn backupStagingPath(allocator: std.mem.Allocator, target_path: []const u8) ![]u8 {
    return try std.fmt.allocPrint(allocator, "{s}{s}", .{ target_path, backup_staging_suffix });
}

fn backupTransactionMarkerPath(allocator: std.mem.Allocator, dir_path: []const u8) ![]u8 {
    return try std.fs.path.join(allocator, &.{ dir_path, backup_transaction_marker_file });
}

fn writeBackupTransactionMarker(
    allocator: std.mem.Allocator,
    io: std.Io,
    dir_path: []const u8,
    expected: BackupTransactionExpectation,
    complete: bool,
) !void {
    const marker_path = try backupTransactionMarkerPath(allocator, dir_path);
    defer allocator.free(marker_path);
    const tmp_path = try std.fmt.allocPrint(allocator, "{s}.tmp", .{marker_path});
    defer allocator.free(tmp_path);
    var out = QueryOutputWriter{ .allocator = allocator };
    defer out.buffer.deinit(allocator);
    try out.writeAll("{\"format\":");
    try writeJsonString(&out, backup_transaction_marker_format);
    try out.writeAll(",\"canonical_source_path\":");
    try writeJsonString(&out, expected.canonical_source_path);
    try out.print(
        ",\"nodes\":{},\"edges\":{},\"source_store_bytes\":{},\"source_store_digest\":[{},{},{},{}],\"source_payload_bytes\":{},\"source_payload_digest\":[{},{},{},{}],\"complete\":{}}}\n",
        .{
            expected.nodes,
            expected.edges,
            expected.source_store_bytes,
            expected.source_store_digest[0],
            expected.source_store_digest[1],
            expected.source_store_digest[2],
            expected.source_store_digest[3],
            expected.source_payload_bytes,
            expected.source_payload_digest[0],
            expected.source_payload_digest[1],
            expected.source_payload_digest[2],
            expected.source_payload_digest[3],
            complete,
        },
    );
    writeRecoverableTransactionMarker(allocator, io, tmp_path, marker_path, out.buffer.items) catch |err| switch (err) {
        error.TransactionMarkerConflict => return error.BackupRecoveryConflict,
        else => |e| return e,
    };
}

fn readBackupTransactionMarker(
    allocator: std.mem.Allocator,
    io: std.Io,
    dir_path: []const u8,
    expected: BackupTransactionExpectation,
) !?BackupMarkerState {
    const marker_path = try backupTransactionMarkerPath(allocator, dir_path);
    defer allocator.free(marker_path);
    return try readBackupTransactionMarkerAtPath(allocator, io, marker_path, expected);
}

fn readBackupTransactionMarkerAtPath(
    allocator: std.mem.Allocator,
    io: std.Io,
    marker_path: []const u8,
    expected: BackupTransactionExpectation,
) !?BackupMarkerState {
    const bytes = std.Io.Dir.cwd().readFileAlloc(io, marker_path, allocator, .limited(16 * 1024)) catch |err| switch (err) {
        error.FileNotFound, error.NotDir => return null,
        error.StreamTooLong => return error.InvalidRecord,
        else => |e| return e,
    };
    defer allocator.free(bytes);
    var parsed = std.json.parseFromSlice(BackupTransactionMarkerJson, allocator, bytes, .{
        .ignore_unknown_fields = false,
        .allocate = .alloc_always,
    }) catch return error.InvalidRecord;
    defer parsed.deinit();
    const marker = parsed.value;
    const legacy_format = std.mem.eql(u8, marker.format, backup_transaction_marker_legacy_format);
    if ((!std.mem.eql(u8, marker.format, backup_transaction_marker_format) and !legacy_format) or
        !std.mem.eql(u8, marker.canonical_source_path, expected.canonical_source_path) or
        marker.nodes != expected.nodes or
        marker.edges != expected.edges or
        marker.source_store_bytes != expected.source_store_bytes or
        !std.meta.eql(marker.source_store_digest, expected.source_store_digest) or
        marker.source_payload_bytes != expected.source_payload_bytes or
        !std.meta.eql(marker.source_payload_digest, expected.source_payload_digest))
    {
        return error.BackupRecoveryConflict;
    }
    return .{ .complete = marker.complete, .legacy_format = legacy_format };
}

fn deleteBackupTransactionMarker(allocator: std.mem.Allocator, io: std.Io, dir_path: []const u8) !void {
    const marker_path = try backupTransactionMarkerPath(allocator, dir_path);
    defer allocator.free(marker_path);
    try std.Io.Dir.cwd().deleteFile(io, marker_path);
    try syncParentDirectory(io, marker_path);
}

fn recoverBackupStaging(
    allocator: std.mem.Allocator,
    io: std.Io,
    staging_path: []const u8,
    expected: BackupTransactionExpectation,
) !void {
    if (!try anyPathExists(io, staging_path)) return;
    const stat = try std.Io.Dir.cwd().statFile(io, staging_path, .{ .follow_symlinks = false });
    if (stat.kind != .directory) return error.BackupRecoveryConflict;
    var marker = try readBackupTransactionMarker(allocator, io, staging_path, expected);
    if (marker == null) {
        const marker_path = try backupTransactionMarkerPath(allocator, staging_path);
        defer allocator.free(marker_path);
        const tmp_path = try std.fmt.allocPrint(allocator, "{s}.tmp", .{marker_path});
        defer allocator.free(tmp_path);
        marker = try readBackupTransactionMarkerAtPath(allocator, io, tmp_path, expected);
    }
    _ = marker orelse return error.BackupRecoveryConflict;
    try std.Io.Dir.cwd().deleteTree(io, staging_path);
    try syncParentDirectory(io, staging_path);
}

fn backupManifestBytesAlloc(allocator: std.mem.Allocator, expected: BackupTransactionExpectation) ![]u8 {
    return try std.fmt.allocPrint(
        allocator,
        "format=tinykg-backup-v2\nsource={s}\nnodes={}\nedges={}\nsource_store_bytes={}\nsource_store_digest={},{},{},{}\nsource_payload_bytes={}\nsource_payload_digest={},{},{},{}\n",
        .{
            expected.canonical_source_path,
            expected.nodes,
            expected.edges,
            expected.source_store_bytes,
            expected.source_store_digest[0],
            expected.source_store_digest[1],
            expected.source_store_digest[2],
            expected.source_store_digest[3],
            expected.source_payload_bytes,
            expected.source_payload_digest[0],
            expected.source_payload_digest[1],
            expected.source_payload_digest[2],
            expected.source_payload_digest[3],
        },
    );
}

fn validateBackupStore(
    allocator: std.mem.Allocator,
    io: std.Io,
    target_path: []const u8,
    expected: BackupTransactionExpectation,
) !BackupStoreResult {
    if (!try existingTinyKgStorePath(allocator, io, target_path)) return error.InvalidRecord;
    var backup = try storage.Store.open(allocator, io, target_path);
    defer backup.deinit();
    const backup_stats = try backup.stats();
    if (backup_stats.nodes != expected.nodes or backup_stats.edges != expected.edges) return error.InvalidRecord;
    const manifest_path = try std.fs.path.join(allocator, &.{ target_path, backup_manifest_file });
    defer allocator.free(manifest_path);
    const actual_manifest = try std.Io.Dir.cwd().readFileAlloc(io, manifest_path, allocator, .limited(64 * 1024));
    defer allocator.free(actual_manifest);
    const expected_manifest = try backupManifestBytesAlloc(allocator, expected);
    defer allocator.free(expected_manifest);
    if (!std.mem.eql(u8, actual_manifest, expected_manifest)) return error.BackupRecoveryConflict;
    const payload_identity = try backupPayloadContentIdentity(allocator, io, target_path);
    if (payload_identity.bytes != expected.source_payload_bytes or
        !std.meta.eql(payload_identity.digest, expected.source_payload_digest))
    {
        return error.BackupRecoveryConflict;
    }
    return .{
        .nodes = expected.nodes,
        .edges = expected.edges,
        .source_store_bytes = expected.source_store_bytes,
        .backup_store_bytes = std.math.add(u64, payload_identity.bytes, actual_manifest.len) catch return error.RecordTooLarge,
    };
}

fn recoverCompletedBackup(
    allocator: std.mem.Allocator,
    io: std.Io,
    target_path: []const u8,
    expected: BackupTransactionExpectation,
) !?BackupStoreResult {
    if (!try anyPathExists(io, target_path)) return null;
    const stat = try std.Io.Dir.cwd().statFile(io, target_path, .{ .follow_symlinks = false });
    if (stat.kind != .directory) return error.AlreadyExists;
    const marker = (try readBackupTransactionMarker(allocator, io, target_path, expected)) orelse
        return null;
    if (!marker.complete) return error.InvalidRecord;
    // The adjacent publication lock protects the target pathname, but an
    // already-published backup is also an ordinary TinyKG store. Coordinate
    // with normal CLI writers, then reread the receipt under that lock before
    // hashing any payload.
    const target_lock = try CliStoreLock.acquire(allocator, io, target_path);
    defer target_lock.deinit();
    const locked_marker = (try readBackupTransactionMarker(allocator, io, target_path, expected)) orelse
        return error.BackupRecoveryConflict;
    if (!locked_marker.complete) return error.InvalidRecord;
    var result = try validateBackupStore(allocator, io, target_path, expected);
    if (locked_marker.legacy_format) {
        try writeBackupTransactionMarker(allocator, io, target_path, expected, true);
    }
    try syncParentDirectory(io, target_path);
    // A complete marker is retained as the request-bound commit receipt; it
    // is excluded from payload identity and future store copies.
    result.marker_cleanup_pending = false;
    return result;
}

fn backupExpectationForSource(
    allocator: std.mem.Allocator,
    io: std.Io,
    db_path: []const u8,
    canonical_source_path: []const u8,
) !BackupTransactionExpectation {
    var store = try storage.Store.open(allocator, io, db_path);
    defer store.deinit();
    const stats_out = try store.stats();
    const source_identity = try storeContentIdentity(allocator, io, db_path);
    const source_manifest_path = try std.fs.path.join(allocator, &.{ db_path, backup_manifest_file });
    defer allocator.free(source_manifest_path);
    const payload_identity = if (try fileExists(io, source_manifest_path))
        try backupPayloadContentIdentity(allocator, io, db_path)
    else
        source_identity;
    return .{
        .canonical_source_path = canonical_source_path,
        .nodes = stats_out.nodes,
        .edges = stats_out.edges,
        .source_store_bytes = source_identity.bytes,
        .source_store_digest = source_identity.digest,
        .source_payload_bytes = payload_identity.bytes,
        .source_payload_digest = payload_identity.digest,
    };
}

fn validateExistingBackupForSource(
    allocator: std.mem.Allocator,
    io: std.Io,
    db_path: []const u8,
    target_path: []const u8,
) !BackupStoreResult {
    const canonical_source_path = try canonicalProspectivePath(allocator, io, db_path);
    defer allocator.free(canonical_source_path);
    const expected = try backupExpectationForSource(allocator, io, db_path, canonical_source_path);
    const publish_lock = try CliStoreLock.acquireAdjacent(allocator, io, target_path, backup_publish_lock_suffix);
    defer publish_lock.deinit();
    if (try recoverCompletedBackup(allocator, io, target_path, expected)) |recovered| return recovered;
    return try validateBackupStore(allocator, io, target_path, expected);
}

fn backupStore(allocator: std.mem.Allocator, io: std.Io, db_path: []const u8, target_path: []const u8) !BackupStoreResult {
    if (target_path.len == 0) return error.InvalidFileName;
    if (try pathsOverlapForCopyTarget(allocator, io, db_path, target_path)) return error.InvalidFileName;
    const canonical_source_path = try canonicalProspectivePath(allocator, io, db_path);
    defer allocator.free(canonical_source_path);
    const expected = try backupExpectationForSource(allocator, io, db_path, canonical_source_path);
    const publish_lock = try CliStoreLock.acquireAdjacent(allocator, io, target_path, backup_publish_lock_suffix);
    defer publish_lock.deinit();
    const staging_path = try backupStagingPath(allocator, target_path);
    defer allocator.free(staging_path);
    try recoverBackupStaging(allocator, io, staging_path, expected);
    if (try recoverCompletedBackup(allocator, io, target_path, expected)) |recovered| return recovered;
    if (try anyPathExists(io, target_path)) return error.AlreadyExists;

    try createOwnedDirectory(io, staging_path);
    var staging_owned = true;
    defer if (staging_owned) std.Io.Dir.cwd().deleteTree(io, staging_path) catch {};
    try writeBackupTransactionMarker(allocator, io, staging_path, expected, false);
    try syncExportDirectoryTree(allocator, io, staging_path);
    try copyDirectoryTreeContents(allocator, io, db_path, staging_path);
    const copied_identity = try storeContentIdentity(allocator, io, staging_path);
    if (copied_identity.bytes != expected.source_store_bytes or
        !std.meta.eql(copied_identity.digest, expected.source_store_digest))
    {
        return error.BackupSourceChanged;
    }
    try writeBackupManifest(allocator, io, staging_path, expected);

    var result = try validateBackupStore(allocator, io, staging_path, expected);
    const source_after_copy = try backupExpectationForSource(allocator, io, db_path, canonical_source_path);
    if (source_after_copy.nodes != expected.nodes or
        source_after_copy.edges != expected.edges or
        source_after_copy.source_store_bytes != expected.source_store_bytes or
        !std.meta.eql(source_after_copy.source_store_digest, expected.source_store_digest) or
        source_after_copy.source_payload_bytes != expected.source_payload_bytes or
        !std.meta.eql(source_after_copy.source_payload_digest, expected.source_payload_digest))
    {
        return error.BackupSourceChanged;
    }
    try writeBackupTransactionMarker(allocator, io, staging_path, expected, true);
    try syncExportDirectoryTree(allocator, io, staging_path);
    if (try anyPathExists(io, target_path)) return error.AlreadyExists;
    try renamePath(io, staging_path, target_path);
    staging_owned = false;
    try syncParentDirectory(io, target_path);
    // Keep the complete receipt so a lost CLI acknowledgment can be retried
    // without mistaking the committed backup for a foreign directory.
    result.marker_cleanup_pending = false;
    return result;
}

const RestoreTransactionExpectation = struct {
    canonical_source_path: []const u8,
    nodes: u64,
    edges: u64,
    source_store_bytes: u64,
    source_store_digest: ContentDigest,
};

const RestoreTransactionMarkerJson = struct {
    format: []const u8,
    canonical_source_path: []const u8,
    nodes: u64,
    edges: u64,
    source_store_bytes: u64,
    source_store_digest: ContentDigest,
    complete: bool,
};

const RestoreMarkerState = struct {
    complete: bool,
    legacy_format: bool,
};

const RestoreStoreLocks = struct {
    first: CliStoreLock,
    second: CliStoreLock,

    fn deinit(self: RestoreStoreLocks) void {
        self.second.deinit();
        self.first.deinit();
    }
};

fn restoreStagingPath(allocator: std.mem.Allocator, target_path: []const u8) ![]u8 {
    return try std.fmt.allocPrint(allocator, "{s}{s}", .{ target_path, restore_staging_suffix });
}

fn restoreTransactionMarkerPath(allocator: std.mem.Allocator, dir_path: []const u8) ![]u8 {
    return try std.fs.path.join(allocator, &.{ dir_path, restore_transaction_marker_file });
}

fn writeRestoreTransactionMarker(
    allocator: std.mem.Allocator,
    io: std.Io,
    dir_path: []const u8,
    expected: RestoreTransactionExpectation,
    complete: bool,
) !void {
    const marker_path = try restoreTransactionMarkerPath(allocator, dir_path);
    defer allocator.free(marker_path);
    const tmp_path = try std.fmt.allocPrint(allocator, "{s}.tmp", .{marker_path});
    defer allocator.free(tmp_path);
    var out = QueryOutputWriter{ .allocator = allocator };
    defer out.buffer.deinit(allocator);
    try out.writeAll("{\"format\":");
    try writeJsonString(&out, restore_transaction_marker_format);
    try out.writeAll(",\"canonical_source_path\":");
    try writeJsonString(&out, expected.canonical_source_path);
    try out.print(
        ",\"nodes\":{},\"edges\":{},\"source_store_bytes\":{},\"source_store_digest\":[{},{},{},{}],\"complete\":{}}}\n",
        .{
            expected.nodes,
            expected.edges,
            expected.source_store_bytes,
            expected.source_store_digest[0],
            expected.source_store_digest[1],
            expected.source_store_digest[2],
            expected.source_store_digest[3],
            complete,
        },
    );
    writeRecoverableTransactionMarker(allocator, io, tmp_path, marker_path, out.buffer.items) catch |err| switch (err) {
        error.TransactionMarkerConflict => return error.RestoreRecoveryConflict,
        else => |e| return e,
    };
}

fn readRestoreTransactionMarker(
    allocator: std.mem.Allocator,
    io: std.Io,
    dir_path: []const u8,
    expected: RestoreTransactionExpectation,
) !?RestoreMarkerState {
    const marker_path = try restoreTransactionMarkerPath(allocator, dir_path);
    defer allocator.free(marker_path);
    return try readRestoreTransactionMarkerAtPath(allocator, io, marker_path, expected);
}

fn readRestoreTransactionMarkerAtPath(
    allocator: std.mem.Allocator,
    io: std.Io,
    marker_path: []const u8,
    expected: RestoreTransactionExpectation,
) !?RestoreMarkerState {
    const bytes = std.Io.Dir.cwd().readFileAlloc(io, marker_path, allocator, .limited(16 * 1024)) catch |err| switch (err) {
        error.FileNotFound, error.NotDir => return null,
        error.StreamTooLong => return error.InvalidRecord,
        else => |e| return e,
    };
    defer allocator.free(bytes);
    var parsed = std.json.parseFromSlice(RestoreTransactionMarkerJson, allocator, bytes, .{
        .ignore_unknown_fields = false,
        .allocate = .alloc_always,
    }) catch return error.InvalidRecord;
    defer parsed.deinit();
    const marker = parsed.value;
    const legacy_format = std.mem.eql(u8, marker.format, restore_transaction_marker_legacy_format);
    if ((!std.mem.eql(u8, marker.format, restore_transaction_marker_format) and !legacy_format) or
        !std.mem.eql(u8, marker.canonical_source_path, expected.canonical_source_path) or
        marker.nodes != expected.nodes or
        marker.edges != expected.edges or
        marker.source_store_bytes != expected.source_store_bytes or
        !std.meta.eql(marker.source_store_digest, expected.source_store_digest))
    {
        return error.RestoreRecoveryConflict;
    }
    return .{ .complete = marker.complete, .legacy_format = legacy_format };
}

fn restoreMarkerPresent(allocator: std.mem.Allocator, io: std.Io, dir_path: []const u8) !bool {
    const marker_path = try restoreTransactionMarkerPath(allocator, dir_path);
    defer allocator.free(marker_path);
    const stat = std.Io.Dir.cwd().statFile(io, marker_path, .{ .follow_symlinks = false }) catch |err| switch (err) {
        error.FileNotFound, error.NotDir => return false,
        else => |e| return e,
    };
    if (stat.kind != .file) return error.RestoreRecoveryConflict;
    return true;
}

fn restoreExpectationForSource(
    allocator: std.mem.Allocator,
    io: std.Io,
    source_path: []const u8,
    canonical_source_path: []const u8,
) !RestoreTransactionExpectation {
    var source = try storage.Store.open(allocator, io, source_path);
    defer source.deinit();
    const stats_out = try source.stats();
    const identity = try storeContentIdentity(allocator, io, source_path);
    return .{
        .canonical_source_path = canonical_source_path,
        .nodes = stats_out.nodes,
        .edges = stats_out.edges,
        .source_store_bytes = identity.bytes,
        .source_store_digest = identity.digest,
    };
}

fn restoreExpectationsEqual(a: RestoreTransactionExpectation, b: RestoreTransactionExpectation) bool {
    return std.mem.eql(u8, a.canonical_source_path, b.canonical_source_path) and
        a.nodes == b.nodes and
        a.edges == b.edges and
        a.source_store_bytes == b.source_store_bytes and
        std.meta.eql(a.source_store_digest, b.source_store_digest);
}

fn acquireRestoreStoreLocks(
    allocator: std.mem.Allocator,
    io: std.Io,
    canonical_source_path: []const u8,
    canonical_target_path: []const u8,
) !RestoreStoreLocks {
    const source_first = std.mem.lessThan(u8, canonical_source_path, canonical_target_path);
    const first_path = if (source_first) canonical_source_path else canonical_target_path;
    const second_path = if (source_first) canonical_target_path else canonical_source_path;
    const first = try CliStoreLock.acquire(allocator, io, first_path);
    errdefer first.deinit();
    const second = try CliStoreLock.acquire(allocator, io, second_path);
    return .{ .first = first, .second = second };
}

fn recoverRestoreStaging(
    allocator: std.mem.Allocator,
    io: std.Io,
    staging_path: []const u8,
    expected: RestoreTransactionExpectation,
) !void {
    if (!try anyPathExists(io, staging_path)) return;
    const stat = try std.Io.Dir.cwd().statFile(io, staging_path, .{ .follow_symlinks = false });
    if (stat.kind != .directory) return error.RestoreRecoveryConflict;
    var marker = try readRestoreTransactionMarker(allocator, io, staging_path, expected);
    if (marker == null) {
        const marker_path = try restoreTransactionMarkerPath(allocator, staging_path);
        defer allocator.free(marker_path);
        const tmp_path = try std.fmt.allocPrint(allocator, "{s}.tmp", .{marker_path});
        defer allocator.free(tmp_path);
        marker = try readRestoreTransactionMarkerAtPath(allocator, io, tmp_path, expected);
    }
    _ = marker orelse return error.RestoreRecoveryConflict;
    try std.Io.Dir.cwd().deleteTree(io, staging_path);
    try syncParentDirectory(io, staging_path);
}

fn validateRestoredStore(
    allocator: std.mem.Allocator,
    io: std.Io,
    target_path: []const u8,
    expected: RestoreTransactionExpectation,
) !BackupStoreResult {
    const identity = try storeContentIdentity(allocator, io, target_path);
    if (identity.bytes != expected.source_store_bytes or
        !std.meta.eql(identity.digest, expected.source_store_digest))
    {
        return error.RestoreRecoveryConflict;
    }
    if (!try existingTinyKgStorePath(allocator, io, target_path)) return error.InvalidRecord;
    var restored = try storage.Store.open(allocator, io, target_path);
    defer restored.deinit();
    const restored_stats = try restored.stats();
    if (restored_stats.nodes != expected.nodes or restored_stats.edges != expected.edges) return error.InvalidRecord;
    return .{
        .nodes = expected.nodes,
        .edges = expected.edges,
        .source_store_bytes = expected.source_store_bytes,
        .backup_store_bytes = identity.bytes,
    };
}

fn recoverCompletedRestore(
    allocator: std.mem.Allocator,
    io: std.Io,
    source_path: []const u8,
    target_path: []const u8,
    canonical_source_path: []const u8,
    canonical_target_path: []const u8,
) !BackupStoreResult {
    if (!try restoreMarkerPresent(allocator, io, target_path)) return error.AlreadyExists;
    const store_locks = try acquireRestoreStoreLocks(allocator, io, canonical_source_path, canonical_target_path);
    defer store_locks.deinit();
    const expected = try restoreExpectationForSource(allocator, io, source_path, canonical_source_path);
    const marker = (try readRestoreTransactionMarker(allocator, io, target_path, expected)) orelse
        return error.RestoreRecoveryConflict;
    if (!marker.complete) return error.InvalidRecord;
    var result = try validateRestoredStore(allocator, io, target_path, expected);
    if (marker.legacy_format) {
        try writeRestoreTransactionMarker(allocator, io, target_path, expected, true);
    }
    try syncParentDirectory(io, target_path);
    // Retain the complete marker as an authenticated commit receipt.
    result.marker_cleanup_pending = false;
    return result;
}

fn restoreBackup(allocator: std.mem.Allocator, io: std.Io, backup_path: []const u8, target_path: []const u8) !BackupStoreResult {
    if (backup_path.len == 0 or target_path.len == 0) return error.InvalidFileName;
    if (try pathsOverlapForCopyTarget(allocator, io, backup_path, target_path)) return error.InvalidFileName;
    const canonical_source_path = try canonicalProspectivePath(allocator, io, backup_path);
    defer allocator.free(canonical_source_path);
    const canonical_target_path = try canonicalProspectivePath(allocator, io, target_path);
    defer allocator.free(canonical_target_path);
    const publish_lock = try CliStoreLock.acquireAdjacent(allocator, io, canonical_target_path, restore_publish_lock_suffix);
    defer publish_lock.deinit();
    if (try anyPathExists(io, canonical_target_path)) {
        const stat = try std.Io.Dir.cwd().statFile(io, canonical_target_path, .{ .follow_symlinks = false });
        if (stat.kind != .directory) return error.AlreadyExists;
        return try recoverCompletedRestore(
            allocator,
            io,
            canonical_source_path,
            canonical_target_path,
            canonical_source_path,
            canonical_target_path,
        );
    }

    const source_lock = try CliStoreLock.acquire(allocator, io, canonical_source_path);
    defer source_lock.deinit();
    const expected = try restoreExpectationForSource(allocator, io, canonical_source_path, canonical_source_path);
    const staging_path = try restoreStagingPath(allocator, canonical_target_path);
    defer allocator.free(staging_path);
    try recoverRestoreStaging(allocator, io, staging_path, expected);
    if (try anyPathExists(io, canonical_target_path)) return error.AlreadyExists;

    try createOwnedDirectory(io, staging_path);
    var staging_owned = true;
    defer if (staging_owned) std.Io.Dir.cwd().deleteTree(io, staging_path) catch {};
    try writeRestoreTransactionMarker(allocator, io, staging_path, expected, false);
    try syncExportDirectoryTree(allocator, io, staging_path);
    try copyDirectoryTreeContents(allocator, io, canonical_source_path, staging_path);
    var result = try validateRestoredStore(allocator, io, staging_path, expected);
    const source_after_copy = try restoreExpectationForSource(allocator, io, canonical_source_path, canonical_source_path);
    if (!restoreExpectationsEqual(source_after_copy, expected)) return error.RestoreSourceChanged;
    try writeRestoreTransactionMarker(allocator, io, staging_path, expected, true);
    try syncExportDirectoryTree(allocator, io, staging_path);
    if (try anyPathExists(io, canonical_target_path)) return error.AlreadyExists;
    try renamePath(io, staging_path, canonical_target_path);
    staging_owned = false;
    try syncParentDirectory(io, canonical_target_path);
    // Receipt retention closes the rename-committed / stdout-lost retry gap.
    result.marker_cleanup_pending = false;
    return result;
}

/// Canonicalize a path that may not exist yet. `realPathFileAlloc` resolves
/// symlinks in the nearest existing ancestor; the remaining suffix is then
/// normalized lexically. This closes `./`, `..`, and symlink-parent aliases
/// before copy/migration code creates a directory or installs an errdefer that
/// could recursively delete the wrong tree.
fn canonicalProspectivePath(allocator: std.mem.Allocator, io: std.Io, path: []const u8) ![]u8 {
    if (path.len == 0) return error.InvalidFileName;
    var probe = path;
    while (true) {
        const canonical_ancestor = std.Io.Dir.cwd().realPathFileAlloc(io, probe, allocator) catch |err| switch (err) {
            error.FileNotFound, error.NotDir => null,
            else => |e| return e,
        };
        if (canonical_ancestor) |ancestor| {
            defer allocator.free(ancestor);
            if (probe.len == path.len) return try allocator.dupe(u8, ancestor);
            const raw_suffix = if (std.mem.eql(u8, probe, ".")) path else path[probe.len..];
            var suffix_start: usize = 0;
            while (suffix_start < raw_suffix.len and (raw_suffix[suffix_start] == '/' or raw_suffix[suffix_start] == '\\')) : (suffix_start += 1) {}
            const suffix = raw_suffix[suffix_start..];
            return try std.fs.path.resolve(allocator, &.{ ancestor, suffix });
        }
        probe = std.fs.path.dirname(probe) orelse ".";
    }
}

fn canonicalPathsEqual(a: []const u8, b: []const u8) bool {
    return if (builtin.os.tag == .windows) std.ascii.eqlIgnoreCase(a, b) else std.mem.eql(u8, a, b);
}

fn canonicalPathContains(parent: []const u8, child: []const u8) bool {
    if (child.len <= parent.len) return false;
    const prefix_matches = if (builtin.os.tag == .windows)
        std.ascii.eqlIgnoreCase(parent, child[0..parent.len])
    else
        std.mem.eql(u8, parent, child[0..parent.len]);
    if (!prefix_matches) return false;
    // Canonical filesystem roots already end in a separator (`/`, `C:\\`,
    // or a UNC share root). Requiring another separator after that prefix
    // would incorrectly claim that the root contains no descendants.
    if (parent[parent.len - 1] == '/' or parent[parent.len - 1] == '\\') return true;
    return child[parent.len] == '/' or child[parent.len] == '\\';
}

fn pathsOverlap(allocator: std.mem.Allocator, io: std.Io, a: []const u8, b: []const u8) !bool {
    const canonical_a = try canonicalProspectivePath(allocator, io, a);
    defer allocator.free(canonical_a);
    const canonical_b = try canonicalProspectivePath(allocator, io, b);
    defer allocator.free(canonical_b);
    return canonicalPathsEqual(canonical_a, canonical_b) or
        canonicalPathContains(canonical_a, canonical_b) or
        canonicalPathContains(canonical_b, canonical_a);
}

fn pathsOverlapForCopyTarget(allocator: std.mem.Allocator, io: std.Io, source_path: []const u8, target_path: []const u8) !bool {
    return try pathsOverlap(allocator, io, source_path, target_path);
}

fn createOwnedDirectory(io: std.Io, path: []const u8) !void {
    if (path.len == 0) return error.InvalidFileName;
    const status = try std.Io.Dir.cwd().createDirPathStatus(io, path, .default_dir);
    if (status == .existed) return error.AlreadyExists;
}

/// Root-level transaction controls are not logical store payload.  Complete
/// markers may persist as commit receipts; incomplete markers and temporary
/// files remain recovery state.  Neither class participates in content
/// identity, backup payloads, recursive copies, or user-visible store bytes.
fn isStoreControlEntry(name: []const u8) bool {
    return std.mem.eql(u8, name, cli_store_lock_suffix) or
        std.mem.eql(u8, name, backup_transaction_marker_file) or
        std.mem.eql(u8, name, import_transaction_marker_file) or
        std.mem.eql(u8, name, restore_transaction_marker_file) or
        std.mem.eql(u8, name, store_migration_transaction_marker_file) or
        std.mem.eql(u8, name, schema_migration_transaction_marker_file) or
        std.mem.eql(u8, name, backup_transaction_marker_file ++ ".tmp") or
        std.mem.eql(u8, name, import_transaction_marker_file ++ ".tmp") or
        std.mem.eql(u8, name, restore_transaction_marker_file ++ ".tmp") or
        std.mem.eql(u8, name, store_migration_transaction_marker_file ++ ".tmp") or
        std.mem.eql(u8, name, schema_migration_transaction_marker_file ++ ".tmp");
}

fn copyDirectoryTreeContentsAtDepth(
    allocator: std.mem.Allocator,
    io: std.Io,
    source_path: []const u8,
    target_path: []const u8,
    is_root: bool,
) !void {
    var source_dir = try std.Io.Dir.cwd().openDir(io, source_path, .{ .iterate = true });
    defer source_dir.close(io);
    var iter = source_dir.iterate();
    while (try iter.next(io)) |entry| {
        if (is_root and isStoreControlEntry(entry.name)) continue;
        const child_source_path = try std.fs.path.join(allocator, &.{ source_path, entry.name });
        defer allocator.free(child_source_path);
        const child_target_path = try std.fs.path.join(allocator, &.{ target_path, entry.name });
        defer allocator.free(child_target_path);
        switch (entry.kind) {
            .file => try std.Io.Dir.copyFile(std.Io.Dir.cwd(), child_source_path, std.Io.Dir.cwd(), child_target_path, io, .{
                .replace = false,
                .make_path = true,
            }),
            .directory => {
                try createOwnedDirectory(io, child_target_path);
                errdefer std.Io.Dir.cwd().deleteTree(io, child_target_path) catch {};
                try copyDirectoryTreeContentsAtDepth(allocator, io, child_source_path, child_target_path, false);
            },
            else => return core.Error.Unsupported,
        }
    }
}

fn copyDirectoryTreeContents(allocator: std.mem.Allocator, io: std.Io, source_path: []const u8, target_path: []const u8) !void {
    return copyDirectoryTreeContentsAtDepth(allocator, io, source_path, target_path, true);
}

fn copyDirectoryTree(allocator: std.mem.Allocator, io: std.Io, source_path: []const u8, target_path: []const u8) !void {
    // Every recursive destination is claimed exclusively. In particular, a
    // target appearing after backup/restore preflight is never treated as our
    // partial copy and therefore never removed by this function's cleanup.
    try createOwnedDirectory(io, target_path);
    errdefer std.Io.Dir.cwd().deleteTree(io, target_path) catch {};
    try copyDirectoryTreeContents(allocator, io, source_path, target_path);
}

fn writeBackupManifest(
    allocator: std.mem.Allocator,
    io: std.Io,
    target_path: []const u8,
    expected: BackupTransactionExpectation,
) !void {
    const manifest_path = try std.fs.path.join(allocator, &.{ target_path, backup_manifest_file });
    defer allocator.free(manifest_path);
    const manifest = try backupManifestBytesAlloc(allocator, expected);
    defer allocator.free(manifest);
    try std.Io.Dir.cwd().writeFile(io, .{
        .sub_path = manifest_path,
        .data = manifest,
        .flags = .{ .truncate = true },
    });
}

const governance_progress_interval: u64 = 1_000_000;

fn governanceProgress(writer: anytype, io: std.Io, phase: []const u8, status: []const u8, checked: u64, total: u64, phase_start_ns: u128, what: []const u8) !void {
    const elapsed_ms = elapsedNs(io, phase_start_ns) / 1_000_000;
    try writer.print(
        "governance_progress phase={s} status={s} checked={} total={} elapsed_ms={} what=\"{s}\"\n",
        .{ phase, status, checked, total, elapsed_ms, what },
    );
    const Writer = @TypeOf(writer);
    const writer_info = @typeInfo(Writer);
    const can_flush = comptime switch (writer_info) {
        .pointer => |pointer| @hasDecl(pointer.child, "flush"),
        else => @hasDecl(Writer, "flush"),
    };
    if (can_flush) {
        try writer.flush();
    }
}

fn governanceProgressMaybe(writer: anytype, io: std.Io, phase: []const u8, checked: u64, total: u64, phase_start_ns: u128, what: []const u8) !void {
    if (checked == 0) return;
    if (checked % governance_progress_interval != 0 and checked != total) return;
    try governanceProgress(writer, io, phase, "progress", checked, total, phase_start_ns, what);
}

fn renderGovernanceReport(allocator: std.mem.Allocator, io: std.Io, db_path: []const u8, store: storage.Store, registry: ?schema.Registry, writer: anytype) !void {
    var phase_start_ns = monotonicNs(io);
    try governanceProgress(writer, io, "store_summary", "begin", 0, 0, phase_start_ns, "reading store stats, store size, and text index presence");
    const stats_out = try store.stats();
    const store_bytes = try storeDirBytes(allocator, io, db_path);
    const text_docs_exists = (try storeFileSize(allocator, io, db_path, "text_docs.idx")) != null;
    const text_terms_exists = (try storeFileSize(allocator, io, db_path, "text_terms.idx")) != null;
    const text_postings_exists = (try storeFileSize(allocator, io, db_path, "text_postings.dat")) != null;
    const text_files_present = text_docs_exists and text_terms_exists and text_postings_exists;
    const text_warm = text_files_present and !try text_search.persistentTextCatalogQuickStale(allocator, store);
    try governanceProgress(writer, io, "store_summary", "end", 1, 1, phase_start_ns, "store summary loaded");

    var isolated_nodes: u64 = 0;
    var tombstone_nodes: u64 = 0;
    var oversized_text_nodes: u64 = 0;
    var max_outgoing_edges: u64 = 0;
    var high_fanout_nodes: u64 = 0;
    var navigation_fanout_violations: u64 = 0;
    var isolated_samples: usize = 0;
    var tombstone_samples: usize = 0;
    var oversized_text_samples: usize = 0;
    var high_fanout_samples: usize = 0;
    var navigation_fanout_samples: usize = 0;
    const id_count = @as(usize, std.math.maxInt(u16)) + 1;
    const node_kind_counts = try allocator.alloc(u64, id_count);
    defer allocator.free(node_kind_counts);
    @memset(node_kind_counts, 0);
    const rel_kind_counts = try allocator.alloc(u64, id_count);
    defer allocator.free(rel_kind_counts);
    @memset(rel_kind_counts, 0);
    var role_index = GovernanceRoleIndex.init(allocator);
    defer role_index.deinit();

    phase_start_ns = monotonicNs(io);
    try governanceProgress(writer, io, "property_snapshot", "begin", 0, 0, phase_start_ns, "loading node and edge property snapshot for governance lookups");
    var property_snapshot = try GovernancePropertySnapshot.load(allocator, store);
    defer property_snapshot.deinit(allocator);
    const property_count: u64 = @intCast(property_snapshot.backing.entries.len);
    try governanceProgress(writer, io, "property_snapshot", "end", property_count, property_count, phase_start_ns, "property snapshot ready");

    var role_nodes = try store.nodeRecordsIterator(null);
    defer role_nodes.deinit();
    var sample_buffer = QueryOutputWriter{ .allocator = allocator };
    defer sample_buffer.buffer.deinit(allocator);
    var outgoing_relation_counts: std.ArrayList(GovernanceRelationCount) = .empty;
    defer outgoing_relation_counts.deinit(allocator);

    phase_start_ns = monotonicNs(io);
    try governanceProgress(writer, io, "scan_nodes_roles", "begin", 0, stats_out.nodes, phase_start_ns, "scanning nodes for kind counts and governance roles");
    var scanned_nodes: u64 = 0;
    while (try role_nodes.next(allocator)) |stored_node| {
        var node = stored_node;
        defer node.deinit(allocator);
        node_kind_counts[@as(usize, @intFromEnum(node.kind))] += 1;
        try role_index.recordNode(&property_snapshot, node);
        scanned_nodes += 1;
        try governanceProgressMaybe(writer, io, "scan_nodes_roles", scanned_nodes, stats_out.nodes, phase_start_ns, "scanning nodes for kind counts and governance roles");
    }
    try governanceProgress(writer, io, "scan_nodes_roles", "end", scanned_nodes, stats_out.nodes, phase_start_ns, "node role scan complete");

    var fanout_by_src = std.AutoHashMap(u64, GovernanceFanoutStats).init(allocator);
    defer fanout_by_src.deinit();
    var incoming_nodes = std.AutoHashMap(u64, void).init(allocator);
    defer incoming_nodes.deinit();
    try fanout_by_src.ensureTotalCapacity(@intCast(@min(stats_out.edges, @as(u64, 65536))));
    try incoming_nodes.ensureTotalCapacity(@intCast(@min(stats_out.edges, @as(u64, 65536))));

    phase_start_ns = monotonicNs(io);
    try governanceProgress(writer, io, "scan_edges", "begin", 0, stats_out.edges, phase_start_ns, "scanning visible edges for relation counts, fanout, and incoming nodes");
    var scanned_edges: u64 = 0;
    const GovernanceEdgeScanContext = struct {
        allocator: std.mem.Allocator,
        registry: ?schema.Registry,
        properties: *const GovernancePropertySnapshot,
        roles: *GovernanceRoleIndex,
        fanout_by_src: *std.AutoHashMap(u64, GovernanceFanoutStats),
        incoming_nodes: *std.AutoHashMap(u64, void),
        rel_kind_counts: []u64,
        scanned_edges: *u64,
        writer: @TypeOf(writer),
        io: std.Io,
        total: u64,
        phase_start_ns: u128,

        fn visit(raw_context: *anyopaque, record: storage.EdgeIndexRecord) anyerror!void {
            const context: *@This() = @ptrCast(@alignCast(raw_context));
            const edge = storedEdgeRefFromIndexRecord(record);
            try recordGovernanceEdgeStats(
                context.allocator,
                context.registry,
                context.properties,
                context.roles,
                context.fanout_by_src,
                context.incoming_nodes,
                context.rel_kind_counts,
                edge,
            );
            context.scanned_edges.* = std.math.add(u64, context.scanned_edges.*, 1) catch return error.RecordTooLarge;
            try governanceProgressMaybe(
                context.writer,
                context.io,
                "scan_edges",
                context.scanned_edges.*,
                context.total,
                context.phase_start_ns,
                "scanning visible edges for relation counts, fanout, and incoming nodes",
            );
        }
    };
    var governance_edge_scan_context = GovernanceEdgeScanContext{
        .allocator = allocator,
        .registry = registry,
        .properties = &property_snapshot,
        .roles = &role_index,
        .fanout_by_src = &fanout_by_src,
        .incoming_nodes = &incoming_nodes,
        .rel_kind_counts = rel_kind_counts,
        .scanned_edges = &scanned_edges,
        .writer = writer,
        .io = io,
        .total = stats_out.edges,
        .phase_start_ns = phase_start_ns,
    };
    const scanned_visible_edges = try store.scanVisibleEdgeIndexRecords(allocator, &governance_edge_scan_context, GovernanceEdgeScanContext.visit);
    if (scanned_visible_edges != scanned_edges) return error.InvalidRecord;
    try governanceProgress(writer, io, "scan_edges", "end", scanned_edges, stats_out.edges, phase_start_ns, "edge scan complete");

    phase_start_ns = monotonicNs(io);
    try governanceProgress(writer, io, "deferred_sidecar", "begin", 0, 0, phase_start_ns, "reading deferred based_on sidecar edges");
    var deferred_based_on = try readMetaknowDeferredBasedOnSidecarForwardPairs(allocator, io, db_path);
    defer deferred_based_on.deinit(allocator);
    if (deferred_based_on.present) {
        for (deferred_based_on.pairs.items, 0..) |pair, index| {
            const edge = storage.StoredEdgeRef{
                .src = core.NodeId.fromInt(pair.src),
                .dst = core.NodeId.fromInt(pair.dst),
                .edge_id = core.EdgeId.fromInt(metaknow_deferred_based_on_edge_id_base + @as(u64, @intCast(index)) + 1),
                .rel = .based_on,
            };
            try recordGovernanceEdgeStats(allocator, registry, &property_snapshot, &role_index, &fanout_by_src, &incoming_nodes, rel_kind_counts, edge);
        }
    }
    try governanceProgress(writer, io, "deferred_sidecar", "end", deferred_based_on.pairs.items.len, deferred_based_on.pairs.items.len, phase_start_ns, "deferred sidecar scan complete");

    var nodes = try store.nodeRecordsIterator(null);
    defer nodes.deinit();
    phase_start_ns = monotonicNs(io);
    try governanceProgress(writer, io, "scan_nodes_health", "begin", 0, stats_out.nodes, phase_start_ns, "checking isolated nodes, tombstones, oversized text, and fanout samples");
    scanned_nodes = 0;
    while (try nodes.next(allocator)) |stored_node| {
        var node = stored_node;
        defer node.deinit(allocator);
        scanned_nodes += 1;
        try governanceProgressMaybe(writer, io, "scan_nodes_health", scanned_nodes, stats_out.nodes, phase_start_ns, "checking isolated nodes, tombstones, oversized text, and fanout samples");
        const fanout = fanout_by_src.get(node.id.toInt()) orelse GovernanceFanoutStats{};
        if (fanout.outgoing_edges > max_outgoing_edges) max_outgoing_edges = fanout.outgoing_edges;
        if (fanout.navigation_relation_edges > governance_navigation_fanout_warn_threshold) {
            navigation_fanout_violations += 1;
            if (navigation_fanout_samples < governance_sample_limit) {
                outgoing_relation_counts.clearRetainingCapacity();
                try collectGovernanceRelationCountsForNode(allocator, store, &outgoing_relation_counts, node.id);
                try sample_buffer.print("navigation_fanout_violation_sample id={} kind=", .{node.id.toInt()});
                try writeNodeKindName(&sample_buffer, node.kind);
                try sample_buffer.print(
                    " navigation_edges={} outgoing_edges={}",
                    .{ fanout.navigation_relation_edges, fanout.outgoing_edges },
                );
                try writeGovernanceRelationCountSummary(&sample_buffer, registry, outgoing_relation_counts.items);
                try sample_buffer.writeAll(" name=");
                try writeEscapedTextPrefix(&sample_buffer, node.text, governance_high_fanout_name_sample_bytes);
                try sample_buffer.writeAll("\n");
                navigation_fanout_samples += 1;
            }
        }
        if (fanout.outgoing_edges >= governance_high_fanout_threshold) {
            high_fanout_nodes += 1;
            if (high_fanout_samples < governance_sample_limit) {
                outgoing_relation_counts.clearRetainingCapacity();
                try collectGovernanceRelationCountsForNode(allocator, store, &outgoing_relation_counts, node.id);
                try sample_buffer.print("high_fanout_node_sample id={} kind=", .{node.id.toInt()});
                try writeNodeKindName(&sample_buffer, node.kind);
                try sample_buffer.print(" outgoing_edges={}", .{fanout.outgoing_edges});
                try writeGovernanceRelationCountSummary(&sample_buffer, registry, outgoing_relation_counts.items);
                try sample_buffer.writeAll(" name=");
                try writeEscapedTextPrefix(&sample_buffer, node.text, governance_high_fanout_name_sample_bytes);
                try sample_buffer.writeAll("\n");
                high_fanout_samples += 1;
            }
        }
        const is_tombstone = isDeletedNodeTombstone(node);
        if (is_tombstone) {
            tombstone_nodes += 1;
            if (tombstone_samples < governance_sample_limit) {
                try sample_buffer.print("tombstone_node_sample id={} kind=", .{node.id.toInt()});
                try writeNodeKindName(&sample_buffer, node.kind);
                try sample_buffer.writeAll(" name=");
                try writeEscapedText(&sample_buffer, node.text);
                try sample_buffer.writeAll("\n");
                tombstone_samples += 1;
            }
            continue;
        }
        const governance_visible_text = markdownProjectionVisibleText(node.text);
        const node_text_chars = std.unicode.utf8CountCodepoints(governance_visible_text) catch 0;
        if (node_text_chars > node_text_char_limit) {
            oversized_text_nodes += 1;
            if (oversized_text_samples < governance_sample_limit) {
                try sample_buffer.print("oversized_node_text_sample id={} kind=", .{node.id.toInt()});
                try writeNodeKindName(&sample_buffer, node.kind);
                try sample_buffer.print(" chars={} limit={} name=", .{ node_text_chars, node_text_char_limit });
                try writeEscapedTextPrefix(&sample_buffer, governance_visible_text, governance_high_fanout_name_sample_bytes);
                try sample_buffer.writeAll("\n");
                oversized_text_samples += 1;
            }
        }
        if (fanout.outgoing_edges == 0 and !incoming_nodes.contains(node.id.toInt())) {
            isolated_nodes += 1;
            if (isolated_samples < governance_sample_limit) {
                try sample_buffer.print("isolated_node_sample id={} kind=", .{node.id.toInt()});
                try writeNodeKindName(&sample_buffer, node.kind);
                try sample_buffer.writeAll(" name=");
                try writeEscapedText(&sample_buffer, node.text);
                try sample_buffer.writeAll("\n");
                isolated_samples += 1;
            }
        }
    }
    try governanceProgress(writer, io, "scan_nodes_health", "end", scanned_nodes, stats_out.nodes, phase_start_ns, "node health scan complete");

    const active_nodes = stats_out.nodes - tombstone_nodes;
    const tombstone_node_ratio_bps: u64 = if (stats_out.nodes == 0)
        0
    else
        @intCast((@as(u128, tombstone_nodes) * 10_000) / @as(u128, stats_out.nodes));
    const tombstone_edges = try store.edgeTombstoneCount();
    const physical_edges = std.math.add(u64, stats_out.edges, tombstone_edges) catch return error.InvalidRecord;
    const tombstone_edge_ratio_bps: u64 = if (physical_edges == 0)
        0
    else
        @intCast((@as(u128, tombstone_edges) * 10_000) / @as(u128, physical_edges));

    try writer.print(
        "db={s}\nnodes={}\nactive_nodes={}\nedges={}\nphysical_edges={}\nstore_dir_bytes={}\ntext_warm={}\ntext_files_present={}\ntext_current={}\ntext_stale={}\nisolated_nodes={}\ntombstone_nodes={}\ntombstone_node_ratio_bps={}\ntombstone_edges={}\ntombstone_edge_ratio_bps={}\noversized_text_nodes={}\nnode_text_char_limit={}\nmax_outgoing_edges={}\nhigh_fanout_nodes={}\nhigh_fanout_threshold={}\nnavigation_entry_nodes={}\nnavigation_fanout_violations={}\nnavigation_fanout_target_min={}\nnavigation_fanout_target_max={}\nnavigation_fanout_warn_threshold={}\n",
        .{
            db_path,
            stats_out.nodes,
            active_nodes,
            stats_out.edges,
            physical_edges,
            store_bytes,
            @intFromBool(text_warm),
            @intFromBool(text_files_present),
            @intFromBool(text_warm),
            @intFromBool(!text_warm),
            isolated_nodes,
            tombstone_nodes,
            tombstone_node_ratio_bps,
            tombstone_edges,
            tombstone_edge_ratio_bps,
            oversized_text_nodes,
            node_text_char_limit,
            max_outgoing_edges,
            high_fanout_nodes,
            governance_high_fanout_threshold,
            role_index.navigation_entry_nodes,
            navigation_fanout_violations,
            governance_navigation_fanout_target_min,
            governance_navigation_fanout_target_max,
            governance_navigation_fanout_warn_threshold,
        },
    );
    try renderGovernanceDistribution(writer, "node_kind_count", .node, registry, node_kind_counts);
    try renderGovernanceDistribution(writer, "traversable_relation_count", .relation, registry, rel_kind_counts);
    try renderGovernanceRoleStats(writer, &role_index);
    if (registry) |schema_registry| {
        var schema_stats = try governanceSchemaStats(allocator, store, schema_registry, &property_snapshot, stats_out.nodes, stats_out.edges, writer, io);
        defer schema_stats.deinit(allocator);
        try writer.print(
            "schema_edge_endpoint_violations={}\nschema_unknown_node_type_nodes={}\nschema_unknown_relation_type_edges={}\nschema_unknown_node_properties={}\nschema_unknown_edge_properties={}\nschema_missing_required_node_properties={}\nschema_invalid_property_type={}\nschema_agent_fillable_missing_fields={}\nschema_human_fillable_missing_fields={}\nschema_composition_orphans={}\nschema_composition_cardinality_violations={}\nschema_ordered_composition_missing_ordered_by={}\nschema_duplicate_order_key={}\nschema_relation_namespace_class_mismatches={}\nschema_namespaced_relation_endpoint_gaps={}\n",
            .{
                schema_stats.endpoint_violations,
                schema_stats.unknown_node_type_nodes,
                schema_stats.unknown_relation_type_edges,
                schema_stats.unknown_node_properties,
                schema_stats.unknown_edge_properties,
                schema_stats.missing_required_node_properties,
                schema_stats.invalid_property_type,
                schema_stats.agent_fillable_missing_fields,
                schema_stats.human_fillable_missing_fields,
                schema_stats.composition_orphans,
                schema_stats.composition_cardinality_violations,
                schema_stats.ordered_composition_missing_ordered_by,
                schema_stats.duplicate_order_key,
                schema_stats.relation_namespace_class_mismatches,
                schema_stats.namespaced_relation_endpoint_gaps,
            },
        );
        try renderGovernanceRelationClassDistribution(writer, schema_registry, rel_kind_counts);
        try writer.writeAll(schema_stats.samples.buffer.items);
    }
    try writer.writeAll(sample_buffer.buffer.items);
}

const GovernanceNodeRole = enum(u8) {
    unknown,
    navigation,
    content,
    entity,
};

const GovernanceRoleIndex = struct {
    allocator: std.mem.Allocator,
    node_roles: std.AutoHashMap(u64, GovernanceNodeRole),
    navigation_entry_nodes: u64 = 0,
    unattached_fact_edges: u64 = 0,
    samples: QueryOutputWriter,

    fn init(allocator: std.mem.Allocator) GovernanceRoleIndex {
        return .{
            .allocator = allocator,
            .node_roles = std.AutoHashMap(u64, GovernanceNodeRole).init(allocator),
            .samples = .{ .allocator = allocator },
        };
    }

    fn deinit(self: *GovernanceRoleIndex) void {
        self.node_roles.deinit();
        self.samples.buffer.deinit(self.allocator);
    }

    fn recordNode(self: *GovernanceRoleIndex, properties: *const GovernancePropertySnapshot, node: storage.StoredNode) !void {
        const schema_type = properties.getString(.{ .node = node.id }, "schema_type");
        try self.recordNodeRole(node.id, governanceRoleForNode(node.kind, schema_type));
    }

    fn recordNodeRole(self: *GovernanceRoleIndex, node_id: core.NodeId, role: GovernanceNodeRole) !void {
        try self.node_roles.put(node_id.toInt(), role);
        if (role == .navigation) self.navigation_entry_nodes += 1;
    }

    fn recordEdge(self: *GovernanceRoleIndex, src: core.NodeId, rel: core.RelKind, dst: core.NodeId) !void {
        _ = self;
        _ = src;
        _ = rel;
        _ = dst;
    }
};

fn renderGovernanceRoleStats(writer: anytype, roles: *const GovernanceRoleIndex) !void {
    try writer.print(
        "unattached_fact_edges={}\n",
        .{roles.unattached_fact_edges},
    );
    try writer.writeAll(roles.samples.buffer.items);
}

const GovernanceDistributionKind = enum { node, relation };

fn renderGovernanceDistribution(writer: anytype, prefix: []const u8, kind: GovernanceDistributionKind, registry: ?schema.Registry, counts: []const u64) !void {
    for (counts, 0..) |count, id| {
        if (count == 0) continue;
        try writer.print("{s} ", .{prefix});
        switch (kind) {
            .node => try writeGovernanceNodeKindLabel(writer, registry, @intCast(id)),
            .relation => try writeGovernanceRelKindLabel(writer, registry, @intCast(id)),
        }
        try writer.print("={}\n", .{count});
    }
}

fn writeGovernanceNodeKindLabel(writer: anytype, registry: ?schema.Registry, id: u16) !void {
    if (registry) |loaded| {
        if (loaded.nodeTypeNameById(id)) |name| return writer.writeAll(name);
    }
    return writeNodeKindName(writer, @enumFromInt(id));
}

fn writeGovernanceRelKindLabel(writer: anytype, registry: ?schema.Registry, id: u16) !void {
    if (registry) |loaded| {
        if (loaded.relationTypeNameById(id)) |name| return writer.writeAll(name);
    }
    return writeRelKindName(writer, @enumFromInt(id));
}

fn renderGovernanceRelationClassDistribution(writer: anytype, registry: schema.Registry, counts: []const u64) !void {
    var class_counts = [_]u64{0} ** @typeInfo(schema.RelationClass).@"enum".fields.len;
    for (counts, 0..) |count, id| {
        if (count == 0) continue;
        const id16 = std.math.cast(u16, id) orelse continue;
        const relation_class = registry.relationClassById(id16) orelse continue;
        class_counts[@intFromEnum(relation_class)] += count;
    }
    inline for (@typeInfo(schema.RelationClass).@"enum".fields) |field| {
        const relation_class: schema.RelationClass = @enumFromInt(field.value);
        try writer.print("traversable_relation_class_count {s}={}\n", .{ relation_class.label(), class_counts[field.value] });
    }
}

const GovernanceRelationCount = struct {
    rel: core.RelKind,
    count: u64,
};

const GovernanceFanoutStats = struct {
    outgoing_edges: u64 = 0,
    navigation_relation_edges: u64 = 0,
};

fn recordGovernanceRelationCount(allocator: std.mem.Allocator, counts: *std.ArrayList(GovernanceRelationCount), rel: core.RelKind) !void {
    return recordGovernanceRelationCountBy(allocator, counts, rel, 1);
}

fn recordGovernanceRelationCountBy(allocator: std.mem.Allocator, counts: *std.ArrayList(GovernanceRelationCount), rel: core.RelKind, amount: u64) !void {
    if (amount == 0) return;
    for (counts.items) |*entry| {
        if (entry.rel == rel) {
            entry.count = std.math.add(u64, entry.count, amount) catch return error.RecordTooLarge;
            return;
        }
    }
    try counts.append(allocator, .{ .rel = rel, .count = amount });
}

fn collectGovernanceRelationCountsForNode(
    allocator: std.mem.Allocator,
    store: storage.Store,
    counts: *std.ArrayList(GovernanceRelationCount),
    node_id: core.NodeId,
) !void {
    var opened = try store.openPublishedEdgeSegmentsForQueryForNode(allocator, .forward, node_id);
    defer if (opened) |*segments| segments.deinit();

    const include_base = if (opened) |*segments| segments.coverage == .delta else true;
    if (include_base) {
        var edges = try store.edgeIndexRecordsByNodeIterator(.src, node_id);
        defer edges.deinit();
        while (try edges.next()) |record| {
            try recordGovernanceRelationCount(allocator, counts, try record.relKind());
        }
    }
    if (opened) |*segments| {
        const Context = struct {
            allocator: std.mem.Allocator,
            counts: *std.ArrayList(GovernanceRelationCount),

            fn visit(context: *@This(), edge: segment_mod.EdgeRecord) !bool {
                try recordGovernanceRelationCount(context.allocator, context.counts, edge.rel);
                return false;
            }
        };
        var context = Context{ .allocator = allocator, .counts = counts };
        _ = if (segments.coverage == .visible_full)
            try segments.segments.forEachNeighbor(.forward, node_id, null, std.math.maxInt(usize), &context, Context.visit)
        else
            try store.forEachOpenedPublishedEdgeSegmentNeighbor(&segments.segments, .forward, node_id, null, std.math.maxInt(usize), &context, Context.visit);
    }

    const deferred_path = try query.metaknowDeferredBasedOnPath(allocator, store);
    defer allocator.free(deferred_path);
    var deferred = try query.readMetaknowDeferredBasedOnTargets(allocator, store.io, deferred_path, node_id, 0, .forward);
    defer deferred.deinit(allocator);
    if (deferred.targets.len != 0) return error.InvalidRecord;
    if (deferred.total_count != 0) {
        try recordGovernanceRelationCountBy(allocator, counts, .based_on, @intCast(deferred.total_count));
    }
}

fn storedEdgeRefFromIndexRecord(record: storage.EdgeIndexRecord) storage.StoredEdgeRef {
    return .{
        .src = core.NodeId.fromInt(record.src),
        .dst = core.NodeId.fromInt(record.dst),
        .edge_id = core.EdgeId.fromInt(record.edge_id),
        .rel = @enumFromInt(record.rel),
    };
}

fn recordGovernanceEdgeStats(
    allocator: std.mem.Allocator,
    registry: ?schema.Registry,
    properties: *const GovernancePropertySnapshot,
    roles: *GovernanceRoleIndex,
    fanout_by_src: *std.AutoHashMap(u64, GovernanceFanoutStats),
    incoming_nodes: *std.AutoHashMap(u64, void),
    rel_kind_counts: []u64,
    edge: storage.StoredEdgeRef,
) !void {
    _ = allocator;
    rel_kind_counts[@as(usize, @intFromEnum(edge.rel))] += 1;
    const fanout_entry = try fanout_by_src.getOrPut(edge.src.toInt());
    if (!fanout_entry.found_existing) fanout_entry.value_ptr.* = .{};
    fanout_entry.value_ptr.outgoing_edges += 1;
    const src_role = roles.node_roles.get(edge.src.toInt()) orelse .unknown;
    if (src_role == .navigation and isGovernanceNavigationRelation(edge.rel, registry)) {
        fanout_entry.value_ptr.navigation_relation_edges += 1;
    }
    try incoming_nodes.put(edge.dst.toInt(), {});

    try roles.recordEdge(edge.src, edge.rel, edge.dst);
    const dst_role = roles.node_roles.get(edge.dst.toInt()) orelse .unknown;
    if (isGovernanceUnattachedFactCandidate(edge.rel, registry, src_role, dst_role) and
        properties.getString(.{ .edge = edge.edge_id }, "projection_edge_id") == null)
    {
        roles.unattached_fact_edges += 1;
        if (roles.unattached_fact_edges <= governance_sample_limit) {
            try roles.samples.print("unattached_fact_edge_sample edge={} src={} rel=", .{ edge.edge_id.toInt(), edge.src.toInt() });
            try writeGovernanceRelKindLabel(&roles.samples, registry, @intFromEnum(edge.rel));
            try roles.samples.print(" dst={}\n", .{edge.dst.toInt()});
        }
    }
}

fn writeGovernanceRelationCountSummary(writer: anytype, registry: ?schema.Registry, counts: []const GovernanceRelationCount) !void {
    try writer.writeAll(" relation_counts=");
    if (counts.len == 0) {
        try writer.writeAll("<none>");
        return;
    }
    for (counts, 0..) |entry, index| {
        if (index != 0) try writer.writeAll(",");
        try writeGovernanceRelKindLabel(writer, registry, @intFromEnum(entry.rel));
        try writer.print(":{}", .{entry.count});
    }
}

const GovernanceOutgoingContext = struct {
    allocator: std.mem.Allocator,
    store: storage.Store,
    rel_kind_counts: []u64,
    outgoing_relation_counts: ?*std.ArrayList(GovernanceRelationCount) = null,
    roles: ?*GovernanceRoleIndex = null,
    src_role: GovernanceNodeRole = .unknown,
    registry: ?schema.Registry = null,
    has_outgoing: bool = false,
    outgoing_edges: u64 = 0,
    navigation_relation_edges: u64 = 0,
};

fn governanceOutgoingEdgeCallback(context: *GovernanceOutgoingContext, edge: query_index.EdgeRef) !bool {
    context.has_outgoing = true;
    context.outgoing_edges += 1;
    context.rel_kind_counts[@as(usize, @intFromEnum(edge.rel))] += 1;
    if (context.outgoing_relation_counts) |counts| {
        try recordGovernanceRelationCount(context.allocator, counts, edge.rel);
    }
    if (context.src_role == .navigation and isGovernanceNavigationRelation(edge.rel, context.registry)) {
        context.navigation_relation_edges += 1;
    }
    if (context.roles) |roles| {
        try roles.recordEdge(edge.src, edge.rel, edge.dst);
        const dst_role = roles.node_roles.get(edge.dst.toInt()) orelse .unknown;
        if (isGovernanceUnattachedFactCandidate(edge.rel, context.registry, context.src_role, dst_role)) {
            const projection_edge_id = context.store.getStringProperty(context.allocator, .{ .edge = edge.edge_id }, "projection_edge_id") catch |err| switch (err) {
                error.InvalidId => null,
                else => |e| return e,
            };
            if (projection_edge_id) |value| {
                context.allocator.free(value);
            } else {
                roles.unattached_fact_edges += 1;
                if (roles.unattached_fact_edges <= governance_sample_limit) {
                    try roles.samples.print("unattached_fact_edge_sample edge={} src={} rel=", .{ edge.edge_id.toInt(), edge.src.toInt() });
                    try writeGovernanceRelKindLabel(&roles.samples, context.registry, @intFromEnum(edge.rel));
                    try roles.samples.print(" dst={}\n", .{edge.dst.toInt()});
                }
            }
        }
    }
    return false;
}

fn isGovernanceUnattachedFactCandidate(rel: core.RelKind, registry: ?schema.Registry, src_role: GovernanceNodeRole, dst_role: GovernanceNodeRole) bool {
    if (isMarkdownProjectionRel(rel)) return false;
    if (isGovernanceNavigationRelation(rel, registry)) return false;
    if (src_role == .navigation or dst_role == .navigation) return false;
    if (src_role == .unknown or dst_role == .unknown) return false;
    if (registry) |loaded| {
        const relation_class = loaded.relationClassById(@intFromEnum(rel)) orelse return false;
        if (relation_class != .domain) return false;
    }
    return true;
}

fn governanceRoleForNode(kind: core.NodeKind, schema_type: ?[]const u8) GovernanceNodeRole {
    if (schema_type) |type_label| {
        if (governanceSchemaTypeMatchesAny(type_label, &.{
            "navigation",
            "navigation_root",
            "root",
            "domain_root",
            "project",
            "project_root",
            "topic",
            "workstream",
            "phase",
            "cluster",
            "document_cluster",
            "task_group",
            "document",
        })) return .navigation;
        if (governanceSchemaTypeMatchesAny(type_label, &.{
            "decision",
            "evidence",
            "verification",
            "observation",
            "command",
            "error_event",
            "fix",
            "fragment",
            "memory",
            "content",
        })) return .content;
        if (governanceSchemaTypeMatchesAny(type_label, &.{
            "entity",
            "reference",
            "file",
            "symbol",
            "person",
            "system",
            "concept",
        })) return .entity;
    }
    return switch (kind) {
        .repo,
        .directory,
        .document,
        .document_section,
        .task,
        => .navigation,
        .decision,
        .evidence,
        .verification,
        .observation,
        .command,
        .error_event,
        .edit,
        .fix,
        => .content,
        .file,
        .symbol,
        .function,
        .type_decl,
        .image,
        .media,
        .concept,
        .user_preference,
        .relation_kind,
        .relation_policy,
        => .entity,
        else => .unknown,
    };
}

fn governanceSchemaTypeMatchesAny(schema_type: []const u8, candidates: []const []const u8) bool {
    for (candidates) |candidate| {
        if (std.ascii.eqlIgnoreCase(schema_type, candidate)) return true;
    }
    return false;
}

fn isGovernanceNavigationRelation(rel: core.RelKind, registry: ?schema.Registry) bool {
    switch (rel) {
        .contains => return true,
        else => {},
    }
    if (registry) |loaded| {
        if (loaded.relationTypeNameById(@intFromEnum(rel))) |name| {
            return governanceSchemaTypeMatchesAny(name, &.{
                "contains",
                "organizes",
                "has_child",
                "has_parent",
                "part_of",
            });
        }
    }
    return false;
}

const GovernanceSchemaStats = struct {
    endpoint_violations: u64 = 0,
    unknown_node_type_nodes: u64 = 0,
    unknown_relation_type_edges: u64 = 0,
    unknown_node_properties: u64 = 0,
    unknown_edge_properties: u64 = 0,
    missing_required_node_properties: u64 = 0,
    invalid_property_type: u64 = 0,
    composition_orphans: u64 = 0,
    composition_cardinality_violations: u64 = 0,
    ordered_composition_missing_ordered_by: u64 = 0,
    duplicate_order_key: u64 = 0,
    agent_fillable_missing_fields: u64 = 0,
    human_fillable_missing_fields: u64 = 0,
    relation_namespace_class_mismatches: u64 = 0,
    namespaced_relation_endpoint_gaps: u64 = 0,
    composition_owner_dst_types: schema.NodeTypeSet = schema.NodeTypeSet.empty(),
    composition_incoming_children: std.AutoHashMap(u64, void),
    composition_cardinality_counts: std.AutoHashMap(GovernanceCompositionCardinalityKey, u64),
    composition_order_keys_seen: std.AutoHashMap(GovernanceCompositionOrderKey, void),
    samples: QueryOutputWriter,

    fn init(allocator: std.mem.Allocator) GovernanceSchemaStats {
        return .{
            .composition_incoming_children = std.AutoHashMap(u64, void).init(allocator),
            .composition_cardinality_counts = std.AutoHashMap(GovernanceCompositionCardinalityKey, u64).init(allocator),
            .composition_order_keys_seen = std.AutoHashMap(GovernanceCompositionOrderKey, void).init(allocator),
            .samples = .{ .allocator = allocator },
        };
    }

    fn deinit(self: GovernanceSchemaStats, allocator: std.mem.Allocator) void {
        var samples = self.samples;
        samples.buffer.deinit(allocator);
        var incoming = self.composition_incoming_children;
        incoming.deinit();
        var counts = self.composition_cardinality_counts;
        counts.deinit();
        var order_keys = self.composition_order_keys_seen;
        order_keys.deinit();
    }
};

const GovernanceCompositionCardinalityKey = struct {
    src: u64,
    rel_id: u16,
};

const GovernanceCompositionOrderKey = struct {
    src: u64,
    rel_id: u16,
    order_key: u64,
};

const GovernanceSchemaEdgeContext = struct {
    registry: schema.Registry,
    store: storage.Store,
    node_view: *storage.Store.NodeRecordView,
    properties: *GovernancePropertySnapshot,
    stats: *GovernanceSchemaStats,
};

const GovernancePropertyLookupKey = struct {
    owner_kind: u8,
    owner_id: u64,
    key_hash: u64,
};

const GovernancePropertySnapshotValue = struct {
    value_kind: storage.PropertySnapshotValueKind,
    string_len: u32 = 0,
    string_value: []const u8 = &.{},
    uint_value: u64 = 0,
};

const GovernancePropertySnapshot = struct {
    backing: storage.PropertySnapshot,
    entries: std.AutoHashMap(GovernancePropertyLookupKey, GovernancePropertySnapshotValue),

    fn load(allocator: std.mem.Allocator, store: storage.Store) !GovernancePropertySnapshot {
        var snapshot = try store.loadPropertySnapshot(allocator);
        errdefer snapshot.deinit(allocator);

        var entries = std.AutoHashMap(GovernancePropertyLookupKey, GovernancePropertySnapshotValue).init(allocator);
        errdefer entries.deinit();
        try entries.ensureTotalCapacity(@intCast(snapshot.entries.len));
        for (snapshot.entries) |entry| {
            const key = governancePropertyLookupKey(entry.owner, entry.key_hash);
            try entries.put(key, .{
                .value_kind = entry.value_kind,
                .string_len = entry.string_len,
                .string_value = entry.string_value,
                .uint_value = entry.uint_value,
            });
        }
        return .{ .backing = snapshot, .entries = entries };
    }

    fn deinit(self: *GovernancePropertySnapshot, allocator: std.mem.Allocator) void {
        self.entries.deinit();
        self.backing.deinit(allocator);
    }

    fn get(self: *const GovernancePropertySnapshot, owner: storage.PropertyOwner, key: []const u8) ?GovernancePropertySnapshotValue {
        return self.entries.get(governancePropertyLookupKey(owner, storage.propertyKeyHashForLookup(key)));
    }

    fn getString(self: *const GovernancePropertySnapshot, owner: storage.PropertyOwner, key: []const u8) ?[]const u8 {
        const value = self.get(owner, key) orelse return null;
        if (value.value_kind != .string or value.string_len == 0) return null;
        return value.string_value;
    }
};

fn governancePropertyLookupKey(owner: storage.PropertyOwner, key_hash: u64) GovernancePropertyLookupKey {
    return switch (owner) {
        .node => |node_id| .{ .owner_kind = 1, .owner_id = node_id.toInt(), .key_hash = key_hash },
        .edge => |edge_id| .{ .owner_kind = 2, .owner_id = edge_id.toInt(), .key_hash = key_hash },
    };
}

const schema_governance_edge_string_properties = [_][]const u8{
    "markdown_attr",
    "render_flags",
    "source_span",
    "confidence",
    "created_by",
    "projection_edge_id",
    "fact_edge_id",
};

const schema_governance_edge_uint_properties = [_][]const u8{
    "order_key",
    "generation",
    "tombstone_generation",
};

fn governanceSchemaStats(
    allocator: std.mem.Allocator,
    store: storage.Store,
    registry: schema.Registry,
    property_snapshot: *GovernancePropertySnapshot,
    node_total: u64,
    edge_total: u64,
    writer: anytype,
    io: std.Io,
) !GovernanceSchemaStats {
    var stats = GovernanceSchemaStats.init(allocator);
    errdefer stats.deinit(allocator);

    var phase_start_ns = monotonicNs(io);
    try governanceProgress(writer, io, "schema_static", "begin", 0, 0, phase_start_ns, "checking schema relation classes and composition owner dst types");
    try governanceSchemaRelationClassStats(registry, &stats);
    try governanceSchemaCompositionDstTypes(registry, &stats);
    try governanceProgress(writer, io, "schema_static", "end", 1, 1, phase_start_ns, "schema static metadata scan complete");

    var node_view = try store.openNodeRecordView();
    defer node_view.deinit();
    var nodes = try store.nodeRecordsIterator(null);
    defer nodes.deinit();
    var context = GovernanceSchemaEdgeContext{
        .registry = registry,
        .store = store,
        .node_view = &node_view,
        .properties = property_snapshot,
        .stats = &stats,
    };

    phase_start_ns = monotonicNs(io);
    try governanceProgress(writer, io, "schema_nodes", "begin", 0, node_total, phase_start_ns, "checking node type ids and node property schema states");
    var scanned_nodes: u64 = 0;
    while (try nodes.next(allocator)) |stored_node| {
        var node = stored_node;
        defer node.deinit(allocator);
        if (!registry.hasNodeTypeId(@intFromEnum(node.kind))) stats.unknown_node_type_nodes += 1;
        try governanceSchemaNodePropertyStats(registry, node, property_snapshot, &stats);
        scanned_nodes += 1;
        try governanceProgressMaybe(writer, io, "schema_nodes", scanned_nodes, node_total, phase_start_ns, "checking node type ids and node property schema states");
    }
    try governanceProgress(writer, io, "schema_nodes", "end", scanned_nodes, node_total, phase_start_ns, "schema node scan complete");

    phase_start_ns = monotonicNs(io);
    try governanceProgress(writer, io, "schema_edges", "begin", 0, edge_total, phase_start_ns, "checking relation endpoint rules, edge properties, and composition edge metadata");
    var scanned_edges: u64 = 0;
    const GovernanceSchemaEdgeScanContext = struct {
        schema_context: *GovernanceSchemaEdgeContext,
        scanned_edges: *u64,
        writer: @TypeOf(writer),
        io: std.Io,
        total: u64,
        phase_start_ns: u128,

        fn visit(raw_context: *anyopaque, record: storage.EdgeIndexRecord) anyerror!void {
            const scan_context: *@This() = @ptrCast(@alignCast(raw_context));
            _ = try governanceSchemaEdgeCallback(scan_context.schema_context, storedEdgeRefFromIndexRecord(record));
            scan_context.scanned_edges.* = std.math.add(u64, scan_context.scanned_edges.*, 1) catch return error.RecordTooLarge;
            try governanceProgressMaybe(
                scan_context.writer,
                scan_context.io,
                "schema_edges",
                scan_context.scanned_edges.*,
                scan_context.total,
                scan_context.phase_start_ns,
                "checking relation endpoint rules, edge properties, and composition edge metadata",
            );
        }
    };
    var governance_schema_edge_scan_context = GovernanceSchemaEdgeScanContext{
        .schema_context = &context,
        .scanned_edges = &scanned_edges,
        .writer = writer,
        .io = io,
        .total = edge_total,
        .phase_start_ns = phase_start_ns,
    };
    const scanned_visible_edges = try store.scanVisibleEdgeIndexRecords(allocator, &governance_schema_edge_scan_context, GovernanceSchemaEdgeScanContext.visit);
    if (scanned_visible_edges != scanned_edges) return error.InvalidRecord;
    try governanceProgress(writer, io, "schema_edges", "end", scanned_edges, edge_total, phase_start_ns, "schema edge scan complete");

    phase_start_ns = monotonicNs(io);
    try governanceProgress(writer, io, "schema_orphans", "begin", 0, node_total, phase_start_ns, "checking composition owner destination nodes for missing incoming owner edges");
    var orphan_nodes = try store.nodeRecordsIterator(null);
    defer orphan_nodes.deinit();
    scanned_nodes = 0;
    while (try orphan_nodes.next(allocator)) |stored_node| {
        var node = stored_node;
        defer node.deinit(allocator);
        scanned_nodes += 1;
        try governanceProgressMaybe(writer, io, "schema_orphans", scanned_nodes, node_total, phase_start_ns, "checking composition owner destination nodes for missing incoming owner edges");
        if (!stats.composition_owner_dst_types.containsNodeKind(node.kind)) continue;
        if (stats.composition_incoming_children.contains(node.id.toInt())) continue;
        stats.composition_orphans += 1;
        if (stats.composition_orphans <= governance_sample_limit) {
            try stats.samples.print("schema_composition_orphan_sample node={} kind=", .{node.id.toInt()});
            try writeNodeKindName(&stats.samples, node.kind);
            try stats.samples.writeAll("\n");
        }
    }
    try governanceProgress(writer, io, "schema_orphans", "end", scanned_nodes, node_total, phase_start_ns, "schema orphan scan complete");

    return stats;
}

fn governanceSchemaCompositionDstTypes(registry: schema.Registry, stats: *GovernanceSchemaStats) !void {
    var index: usize = 0;
    while (index < registry.relationTypeCount()) : (index += 1) {
        const info = registry.relationTypeInfo(index).?;
        const composition = registry.relationCompositionById(info.id) orelse continue;
        if (!composition.enabled or !composition.owner) continue;
        const rule = registry.relationEndpointRuleById(info.id) orelse continue;
        if (rule.dst) |dst| stats.composition_owner_dst_types.merge(dst);
    }
}

fn governanceSchemaNodePropertyStats(registry: schema.Registry, node: storage.StoredNode, properties: *const GovernancePropertySnapshot, stats: *GovernanceSchemaStats) !void {
    var property_index: usize = 0;
    while (property_index < registry.nodePropertyCount(@intFromEnum(node.kind))) : (property_index += 1) {
        const property = registry.nodePropertyInfo(@intFromEnum(node.kind), property_index) orelse continue;
        const state = governanceNodeSchemaPropertyState(properties, node, property);
        if (property.required and !state.present) {
            stats.missing_required_node_properties += 1;
            if (stats.missing_required_node_properties <= governance_sample_limit) {
                try stats.samples.print("schema_missing_required_node_property_sample node={} key={s}\n", .{ node.id.toInt(), property.name });
            }
        }
        if (state.present and !state.valid_type) {
            stats.invalid_property_type += 1;
            if (stats.invalid_property_type <= governance_sample_limit) {
                try stats.samples.print("schema_invalid_node_property_type_sample node={} key={s} expected={s}\n", .{ node.id.toInt(), property.name, property.value_type.label() });
            }
        }
        if (property.agent_fillable and !state.present) {
            stats.agent_fillable_missing_fields += 1;
            if (stats.agent_fillable_missing_fields <= governance_sample_limit) {
                try stats.samples.print("schema_agent_fillable_missing_field_sample node={} key={s}\n", .{ node.id.toInt(), property.name });
            }
        }
        if (property.human_fillable and !state.present) {
            stats.human_fillable_missing_fields += 1;
            if (stats.human_fillable_missing_fields <= governance_sample_limit) {
                try stats.samples.print("schema_human_fillable_missing_field_sample node={} key={s}\n", .{ node.id.toInt(), property.name });
            }
        }
    }
}

const GovernancePropertyState = struct {
    present: bool = false,
    valid_type: bool = true,
};

fn governanceNodeSchemaPropertyState(properties: *const GovernancePropertySnapshot, node: storage.StoredNode, property: schema.PropertyMeta) GovernancePropertyState {
    if (std.mem.eql(u8, property.name, "text")) {
        return .{ .present = true, .valid_type = property.value_type == .string };
    }
    const value = properties.get(.{ .node = node.id }, property.name) orelse return .{};
    if (property.value_type == .@"enum") {
        return .{
            .present = value.value_kind == .string and value.string_len != 0,
            .valid_type = value.value_kind == .string and property.enumAllows(value.string_value),
        };
    }
    if (property.value_type == .string or property.value_type == .json) {
        return .{
            .present = value.value_kind == .string and value.string_len != 0,
            .valid_type = value.value_kind == .string,
        };
    }
    if (property.value_type == .uint or property.value_type == .int) {
        return .{
            .present = value.value_kind == .uint,
            .valid_type = value.value_kind == .uint,
        };
    }
    return .{};
}

fn schemaJsonPropertyIsEmpty(value: std.json.Value) bool {
    return switch (value) {
        .null => true,
        .string => |text| text.len == 0,
        else => false,
    };
}

fn schemaJsonPropertyMatchesType(value: std.json.Value, property_type: schema.PropertyType) bool {
    return switch (property_type) {
        .string, .@"enum" => value == .string,
        .uint => value == .integer and value.integer >= 0,
        .int => value == .integer,
        .bool => value == .bool,
        .json => true,
    };
}

fn governanceSchemaRelationClassStats(registry: schema.Registry, stats: *GovernanceSchemaStats) !void {
    var index: usize = 0;
    while (index < registry.relationTypeCount()) : (index += 1) {
        const info = registry.relationTypeInfo(index).?;
        const expected = schemaRelationClassNamespace(info.name) orelse continue;
        if (expected != info.class) {
            stats.relation_namespace_class_mismatches += 1;
            if (stats.relation_namespace_class_mismatches <= governance_sample_limit) {
                try stats.samples.print("schema_relation_namespace_class_mismatch_sample rel={s} expected_class={s} actual_class={s}\n", .{
                    info.name,
                    expected.label(),
                    info.class.label(),
                });
            }
        }
        const rule = registry.relationEndpointRuleById(info.id) orelse continue;
        if (rule.isEmpty()) {
            stats.namespaced_relation_endpoint_gaps += 1;
            if (stats.namespaced_relation_endpoint_gaps <= governance_sample_limit) {
                try stats.samples.print("schema_namespaced_relation_endpoint_gap_sample rel={s} class={s}\n", .{ info.name, info.class.label() });
            }
        }
    }
}

fn governanceSchemaEdgeCallback(context: *GovernanceSchemaEdgeContext, edge: storage.StoredEdgeRef) !bool {
    const rel_id: u16 = @intFromEnum(edge.rel);
    const rule = context.registry.relationEndpointRuleById(rel_id) orelse {
        context.stats.unknown_relation_type_edges += 1;
        if (context.stats.unknown_relation_type_edges <= governance_sample_limit) {
            try context.stats.samples.print("schema_unknown_relation_edge_sample edge={} rel#{} src={} dst={}\n", .{
                edge.edge_id.toInt(),
                rel_id,
                edge.src.toInt(),
                edge.dst.toInt(),
            });
        }
        return false;
    };
    try governanceSchemaEdgePropertyStats(context, edge);
    try governanceSchemaCompositionEdgeStats(context, edge);
    if (rule.isEmpty()) return false;

    // The node scan already reports types missing from the active schema.
    // Governance must keep scanning the remaining edges so it can produce a
    // complete debt report; UnknownNodeKind is only fatal on the write-time
    // validation path, where accepting an unregistered endpoint would make a
    // schema-constrained mutation ambiguous.
    const check = schemaEdgeEndpointCheck(context.node_view, context.registry, edge.src, edge.rel, edge.dst) catch |err| switch (err) {
        error.UnknownNodeKind => return false,
        else => |e| return e,
    };
    if (!check.violates) return false;

    context.stats.endpoint_violations += 1;
    if (context.stats.endpoint_violations <= governance_sample_limit) {
        try context.stats.samples.print("schema_edge_endpoint_violation_sample edge={} rel=", .{edge.edge_id.toInt()});
        try writeRelKindName(&context.stats.samples, edge.rel);
        try context.stats.samples.print(" src={} src_kind=", .{edge.src.toInt()});
        try writeNodeKindName(&context.stats.samples, check.src_kind);
        try context.stats.samples.print(" dst={} dst_kind=", .{edge.dst.toInt()});
        try writeNodeKindName(&context.stats.samples, check.dst_kind);
        try context.stats.samples.writeAll("\n");
    }
    return false;
}

fn governanceSchemaEdgePropertyStats(context: *GovernanceSchemaEdgeContext, edge: storage.StoredEdgeRef) !void {
    const rel_id: u16 = @intFromEnum(edge.rel);
    for (schema_governance_edge_string_properties) |key| {
        const value = context.properties.get(.{ .edge = edge.edge_id }, key) orelse continue;
        const property = context.registry.relationPropertyByTypeId(rel_id, key) orelse {
            try governanceSchemaUnknownEdgePropertySample(context, edge, key);
            continue;
        };
        if (value.value_kind != .string or
            (property.value_type != .string and property.value_type != .@"enum" and property.value_type != .json) or
            (property.value_type == .@"enum" and !property.enumAllows(value.string_value)))
        {
            try governanceSchemaInvalidEdgePropertyTypeSample(context, edge, key, property.value_type);
        }
    }
    for (schema_governance_edge_uint_properties) |key| {
        const value = context.properties.get(.{ .edge = edge.edge_id }, key) orelse continue;
        const property = context.registry.relationPropertyByTypeId(rel_id, key) orelse {
            try governanceSchemaUnknownEdgePropertySample(context, edge, key);
            continue;
        };
        if (value.value_kind != .uint or property.value_type != .uint) {
            try governanceSchemaInvalidEdgePropertyTypeSample(context, edge, key, property.value_type);
        }
    }
}

fn governanceSchemaUnknownEdgePropertySample(context: *GovernanceSchemaEdgeContext, edge: storage.StoredEdgeRef, key: []const u8) !void {
    context.stats.unknown_edge_properties += 1;
    if (context.stats.unknown_edge_properties <= governance_sample_limit) {
        try context.stats.samples.print("schema_unknown_edge_property_sample edge={} rel=", .{edge.edge_id.toInt()});
        try writeRelKindName(&context.stats.samples, edge.rel);
        try context.stats.samples.print(" key={s}\n", .{key});
    }
}

fn governanceSchemaInvalidEdgePropertyTypeSample(context: *GovernanceSchemaEdgeContext, edge: storage.StoredEdgeRef, key: []const u8, expected: schema.PropertyType) !void {
    context.stats.invalid_property_type += 1;
    if (context.stats.invalid_property_type <= governance_sample_limit) {
        try context.stats.samples.print("schema_invalid_edge_property_type_sample edge={} key={s} expected={s}\n", .{ edge.edge_id.toInt(), key, expected.label() });
    }
}

fn governanceSchemaCompositionEdgeStats(context: *GovernanceSchemaEdgeContext, edge: storage.StoredEdgeRef) !void {
    const rel_id: u16 = @intFromEnum(edge.rel);
    const composition = context.registry.relationCompositionById(rel_id) orelse return;
    if (!composition.enabled) return;
    if (composition.owner) try context.stats.composition_incoming_children.put(edge.dst.toInt(), {});

    switch (composition.cardinality) {
        .one, .optional_one => {
            const key = GovernanceCompositionCardinalityKey{ .src = edge.src.toInt(), .rel_id = rel_id };
            const entry = try context.stats.composition_cardinality_counts.getOrPut(key);
            if (entry.found_existing) {
                entry.value_ptr.* += 1;
                context.stats.composition_cardinality_violations += 1;
                if (context.stats.composition_cardinality_violations <= governance_sample_limit) {
                    try context.stats.samples.print("schema_composition_cardinality_violation_sample src={} rel=", .{edge.src.toInt()});
                    try writeRelKindName(&context.stats.samples, edge.rel);
                    try context.stats.samples.print(" count={}\n", .{entry.value_ptr.*});
                }
            } else {
                entry.value_ptr.* = 1;
            }
        },
        .many => {},
    }

    if (composition.ordered_by) |ordered_by| {
        const order_value = context.properties.get(.{ .edge = edge.edge_id }, ordered_by);
        if (order_value == null or order_value.?.value_kind != .uint) {
            context.stats.ordered_composition_missing_ordered_by += 1;
            if (context.stats.ordered_composition_missing_ordered_by <= governance_sample_limit) {
                try context.stats.samples.print("schema_ordered_composition_missing_ordered_by_sample edge={} rel=", .{edge.edge_id.toInt()});
                try writeRelKindName(&context.stats.samples, edge.rel);
                try context.stats.samples.print(" key={s}\n", .{ordered_by});
            }
            return;
        }
        const concrete = order_value.?.uint_value;
        const order_key = GovernanceCompositionOrderKey{ .src = edge.src.toInt(), .rel_id = rel_id, .order_key = concrete };
        const order_entry = try context.stats.composition_order_keys_seen.getOrPut(order_key);
        if (order_entry.found_existing) {
            context.stats.duplicate_order_key += 1;
            if (context.stats.duplicate_order_key <= governance_sample_limit) {
                try context.stats.samples.print("schema_duplicate_order_key_sample src={} rel=", .{edge.src.toInt()});
                try writeRelKindName(&context.stats.samples, edge.rel);
                try context.stats.samples.print(" key={s} value={}\n", .{ ordered_by, concrete });
            }
        }
    }
}

const SchemaEdgeEndpointCheck = struct {
    src_kind: core.NodeKind,
    dst_kind: core.NodeKind,
    violates: bool,
};

fn validateSchemaEdgeEndpoints(store: storage.Store, registry: schema.Registry, src: core.NodeId, rel: core.RelKind, dst: core.NodeId) !void {
    var node_view = try store.openNodeRecordView();
    defer node_view.deinit();
    const check = try schemaEdgeEndpointCheck(&node_view, registry, src, rel, dst);
    if (check.violates) return error.SchemaEndpointViolation;
}

fn schemaEdgeEndpointCheck(
    node_view: *storage.Store.NodeRecordView,
    registry: schema.Registry,
    src: core.NodeId,
    rel: core.RelKind,
    dst: core.NodeId,
) !SchemaEdgeEndpointCheck {
    const rule = registry.relationEndpointRuleById(@intFromEnum(rel)) orelse return error.UnknownRelationKind;
    const src_ref = (try node_view.readNodeRefById(src)) orelse return core.Error.NotFound;
    const dst_ref = (try node_view.readNodeRefById(dst)) orelse return core.Error.NotFound;
    if (!registry.hasNodeTypeId(@intFromEnum(src_ref.kind))) return error.UnknownNodeKind;
    if (!registry.hasNodeTypeId(@intFromEnum(dst_ref.kind))) return error.UnknownNodeKind;
    const bad_src = if (rule.src) |src_set| !src_set.containsNodeKind(src_ref.kind) else false;
    const bad_dst = if (rule.dst) |dst_set| !dst_set.containsNodeKind(dst_ref.kind) else false;
    return .{
        .src_kind = src_ref.kind,
        .dst_kind = dst_ref.kind,
        .violates = bad_src or bad_dst,
    };
}

fn nodeHasIncomingEdge(allocator: std.mem.Allocator, store: storage.Store, node_id: core.NodeId) !bool {
    var found = false;
    const cursor = query.EdgeCursor{ .persistent_store = .{
        .allocator = allocator,
        .store = store,
    } };
    if (try cursor.forEachIncoming(node_id, &found, markIncidentEdgeFound)) return true;
    return found;
}

fn markIncidentEdgeFound(found: *bool, edge: query_index.EdgeRef) !bool {
    _ = edge;
    found.* = true;
    return true;
}

const StoreContentIdentity = struct {
    bytes: u64 = 0,
    digest: ContentDigest,
};

fn hashLengthPrefixed(hasher: *std.crypto.hash.sha2.Sha256, bytes: []const u8) void {
    var len_bytes: [8]u8 = undefined;
    std.mem.writeInt(u64, &len_bytes, bytes.len, .little);
    hasher.update(&len_bytes);
    hasher.update(bytes);
}

fn hashStoreFile(
    io: std.Io,
    file_path: []const u8,
    relative_path: []const u8,
    size: u64,
    hasher: *std.crypto.hash.sha2.Sha256,
) !void {
    hasher.update("file\x00");
    hashLengthPrefixed(hasher, relative_path);
    var size_bytes: [8]u8 = undefined;
    std.mem.writeInt(u64, &size_bytes, size, .little);
    hasher.update(&size_bytes);
    var file = try std.Io.Dir.cwd().openFile(io, file_path, .{ .allow_directory = false });
    defer file.close(io);
    var buffer: [64 * 1024]u8 = undefined;
    var offset: u64 = 0;
    while (offset < size) {
        const remaining = size - offset;
        const take: usize = @intCast(@min(remaining, buffer.len));
        if (try file.readPositionalAll(io, buffer[0..take], offset) != take) return error.InvalidRecord;
        hasher.update(buffer[0..take]);
        offset += @intCast(take);
    }
}

const StoreContentIdentityView = enum {
    complete,
    backup_payload,
};

fn skipStoreContentIdentityEntry(view: StoreContentIdentityView, relative_path: []const u8, name: []const u8) bool {
    if (relative_path.len == 0 and isStoreControlEntry(name)) return true;
    return view == .backup_payload and relative_path.len == 0 and std.mem.eql(u8, name, backup_manifest_file);
}

fn hashStoreDirectory(
    allocator: std.mem.Allocator,
    io: std.Io,
    root_path: []const u8,
    relative_path: []const u8,
    hasher: *std.crypto.hash.sha2.Sha256,
    total_bytes: *u64,
    view: StoreContentIdentityView,
) !void {
    const dir_path = if (relative_path.len == 0)
        try allocator.dupe(u8, root_path)
    else
        try std.fs.path.join(allocator, &.{ root_path, relative_path });
    defer allocator.free(dir_path);
    var dir = try std.Io.Dir.cwd().openDir(io, dir_path, .{ .iterate = true, .follow_symlinks = false });
    defer dir.close(io);
    var names = std.ArrayList([]u8).empty;
    defer {
        for (names.items) |name| allocator.free(name);
        names.deinit(allocator);
    }
    var iter = dir.iterate();
    while (try iter.next(io)) |entry| {
        if (skipStoreContentIdentityEntry(view, relative_path, entry.name)) continue;
        const owned_name = try allocator.dupe(u8, entry.name);
        errdefer allocator.free(owned_name);
        try names.append(allocator, owned_name);
    }
    std.mem.sort([]u8, names.items, {}, markdownFileNameLessThan);
    for (names.items) |name| {
        const child_relative = if (relative_path.len == 0)
            try allocator.dupe(u8, name)
        else
            try std.fs.path.join(allocator, &.{ relative_path, name });
        defer allocator.free(child_relative);
        const child_path = try std.fs.path.join(allocator, &.{ root_path, child_relative });
        defer allocator.free(child_path);
        const stat = try std.Io.Dir.cwd().statFile(io, child_path, .{ .follow_symlinks = false });
        switch (stat.kind) {
            .file => {
                total_bytes.* = std.math.add(u64, total_bytes.*, stat.size) catch return error.RecordTooLarge;
                try hashStoreFile(io, child_path, child_relative, stat.size, hasher);
            },
            .directory => {
                hasher.update("dir\x00");
                hashLengthPrefixed(hasher, child_relative);
                try hashStoreDirectory(allocator, io, root_path, child_relative, hasher, total_bytes, view);
            },
            else => return core.Error.Unsupported,
        }
    }
}

fn storeContentIdentity(allocator: std.mem.Allocator, io: std.Io, db_path: []const u8) !StoreContentIdentity {
    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    var total_bytes: u64 = 0;
    try hashStoreDirectory(allocator, io, db_path, "", &hasher, &total_bytes, .complete);
    return .{ .bytes = total_bytes, .digest = finalizeContentDigest(&hasher) };
}

fn backupPayloadContentIdentity(allocator: std.mem.Allocator, io: std.Io, db_path: []const u8) !StoreContentIdentity {
    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    var total_bytes: u64 = 0;
    try hashStoreDirectory(allocator, io, db_path, "", &hasher, &total_bytes, .backup_payload);
    return .{ .bytes = total_bytes, .digest = finalizeContentDigest(&hasher) };
}

fn storeDirBytesAtDepth(allocator: std.mem.Allocator, io: std.Io, db_path: []const u8, is_root: bool) !u64 {
    var dir = try std.Io.Dir.cwd().openDir(io, db_path, .{ .iterate = true });
    defer dir.close(io);
    var iter = dir.iterate();
    var total: u64 = 0;
    while (try iter.next(io)) |entry| {
        if (is_root and isStoreControlEntry(entry.name)) continue;
        const full_path = try std.fs.path.join(allocator, &.{ db_path, entry.name });
        defer allocator.free(full_path);
        switch (entry.kind) {
            .file => {
                const stat = try std.Io.Dir.cwd().statFile(io, full_path, .{});
                total = std.math.add(u64, total, stat.size) catch return error.RecordTooLarge;
            },
            .directory => {
                const child_total = try storeDirBytesAtDepth(allocator, io, full_path, false);
                total = std.math.add(u64, total, child_total) catch return error.RecordTooLarge;
            },
            else => {},
        }
    }
    return total;
}

fn storeDirBytes(allocator: std.mem.Allocator, io: std.Io, db_path: []const u8) !u64 {
    return storeDirBytesAtDepth(allocator, io, db_path, true);
}

const BenchEdgeSegmentBytes = struct {
    total: u64 = 0,
    data: u64 = 0,
    sidecar: u64 = 0,
    other: u64 = 0,
    manifest: u64 = 0,
    current: u64 = 0,
    files: u64 = 0,
    dirs: u64 = 0,
    manifest_files: u64 = 0,
    current_files: u64 = 0,
    csr_header: u64 = 0,
    csr_vertex: u64 = 0,
    csr_relation: u64 = 0,
    csr_edge: u64 = 0,
    csr_edge_count: u64 = 0,
    csr_vertex_count: u64 = 0,
    csr_relation_count: u64 = 0,
    csr_files: u64 = 0,
    csr_derived_edge_id_files: u64 = 0,
    csr_split_derived_edge_id_files: u64 = 0,
    csr_derived_vertex_id_files: u64 = 0,
    csr_split_derived_vertex_id_files: u64 = 0,
    csr_derived_edge_other_node_files: u64 = 0,
    csr_split_derived_edge_other_node_files: u64 = 0,

    fn controlBytes(self: BenchEdgeSegmentBytes) !u64 {
        return std.math.add(u64, self.manifest, self.current) catch return error.RecordTooLarge;
    }

    fn physicalBytes(self: BenchEdgeSegmentBytes) !u64 {
        return std.math.add(u64, self.total, try self.controlBytes()) catch return error.RecordTooLarge;
    }

    fn addSegmentFile(self: *BenchEdgeSegmentBytes, leaf: []const u8, size: u64) !void {
        self.total = std.math.add(u64, self.total, size) catch return error.RecordTooLarge;
        self.files = std.math.add(u64, self.files, 1) catch return error.RecordTooLarge;
        if (std.mem.eql(u8, leaf, "edge_ids.idx")) {
            self.sidecar = std.math.add(u64, self.sidecar, size) catch return error.RecordTooLarge;
        } else if (std.mem.eql(u8, leaf, "edge_fwd.csr") or std.mem.eql(u8, leaf, "edge_rev.csr")) {
            self.data = std.math.add(u64, self.data, size) catch return error.RecordTooLarge;
        } else {
            self.other = std.math.add(u64, self.other, size) catch return error.RecordTooLarge;
        }
    }

    fn addCsrStats(self: *BenchEdgeSegmentBytes, stats: segment_mod.CsrFileByteStats) !void {
        self.csr_header = std.math.add(u64, self.csr_header, stats.header_bytes) catch return error.RecordTooLarge;
        self.csr_vertex = std.math.add(u64, self.csr_vertex, stats.vertex_bytes) catch return error.RecordTooLarge;
        self.csr_relation = std.math.add(u64, self.csr_relation, stats.relation_bytes) catch return error.RecordTooLarge;
        self.csr_edge = std.math.add(u64, self.csr_edge, stats.edge_bytes) catch return error.RecordTooLarge;
        self.csr_edge_count = std.math.add(u64, self.csr_edge_count, stats.edge_count) catch return error.RecordTooLarge;
        self.csr_vertex_count = std.math.add(u64, self.csr_vertex_count, stats.vertex_count) catch return error.RecordTooLarge;
        self.csr_relation_count = std.math.add(u64, self.csr_relation_count, stats.relation_count) catch return error.RecordTooLarge;
        self.csr_files = std.math.add(u64, self.csr_files, 1) catch return error.RecordTooLarge;
        if (stats.derived_edge_ids) {
            self.csr_derived_edge_id_files = std.math.add(u64, self.csr_derived_edge_id_files, 1) catch return error.RecordTooLarge;
        }
        if (stats.split_derived_edge_ids) {
            self.csr_split_derived_edge_id_files = std.math.add(u64, self.csr_split_derived_edge_id_files, 1) catch return error.RecordTooLarge;
        }
        if (stats.derived_vertex_ids) {
            self.csr_derived_vertex_id_files = std.math.add(u64, self.csr_derived_vertex_id_files, 1) catch return error.RecordTooLarge;
        }
        if (stats.split_derived_vertex_ids) {
            self.csr_split_derived_vertex_id_files = std.math.add(u64, self.csr_split_derived_vertex_id_files, 1) catch return error.RecordTooLarge;
        }
        if (stats.derived_edge_other_nodes) {
            self.csr_derived_edge_other_node_files = std.math.add(u64, self.csr_derived_edge_other_node_files, 1) catch return error.RecordTooLarge;
        }
        if (stats.split_derived_edge_other_nodes) {
            self.csr_split_derived_edge_other_node_files = std.math.add(u64, self.csr_split_derived_edge_other_node_files, 1) catch return error.RecordTooLarge;
        }
    }
};

fn benchEdgeSegmentBytes(allocator: std.mem.Allocator, io: std.Io, db_path: []const u8) !BenchEdgeSegmentBytes {
    var bytes = BenchEdgeSegmentBytes{};
    const edge_segments_path = try std.fs.path.join(allocator, &.{ db_path, "edge_segments" });
    defer allocator.free(edge_segments_path);
    try benchEdgeSegmentSubtreeBytes(allocator, io, edge_segments_path, &bytes);
    try benchEdgeSegmentControlBytes(allocator, io, db_path, &bytes);
    return bytes;
}

fn benchEdgeSegmentSubtreeBytes(allocator: std.mem.Allocator, io: std.Io, path: []const u8, bytes: *BenchEdgeSegmentBytes) !void {
    var dir = std.Io.Dir.cwd().openDir(io, path, .{ .iterate = true }) catch |err| switch (err) {
        error.FileNotFound => return,
        else => |e| return e,
    };
    defer dir.close(io);

    var iter = dir.iterate();
    while (try iter.next(io)) |entry| {
        const full_path = try std.fs.path.join(allocator, &.{ path, entry.name });
        defer allocator.free(full_path);
        switch (entry.kind) {
            .file => {
                const stat = try std.Io.Dir.cwd().statFile(io, full_path, .{});
                try bytes.addSegmentFile(entry.name, stat.size);
                if (std.mem.eql(u8, entry.name, "edge_fwd.csr") or std.mem.eql(u8, entry.name, "edge_rev.csr")) {
                    const stats = segment_mod.csrFileByteStats(io, full_path) catch |err| switch (err) {
                        error.InvalidRecord => null,
                        else => |e| return e,
                    };
                    if (stats) |csr_stats| try bytes.addCsrStats(csr_stats);
                }
            },
            .directory => {
                bytes.dirs = std.math.add(u64, bytes.dirs, 1) catch return error.RecordTooLarge;
                try benchEdgeSegmentSubtreeBytes(allocator, io, full_path, bytes);
            },
            else => {},
        }
    }
}

fn benchEdgeSegmentControlBytes(allocator: std.mem.Allocator, io: std.Io, db_path: []const u8, bytes: *BenchEdgeSegmentBytes) !void {
    var dir = std.Io.Dir.cwd().openDir(io, db_path, .{ .iterate = true }) catch |err| switch (err) {
        error.FileNotFound => return,
        else => |e| return e,
    };
    defer dir.close(io);

    var iter = dir.iterate();
    while (try iter.next(io)) |entry| {
        if (entry.kind != .file) continue;
        const full_path = try std.fs.path.join(allocator, &.{ db_path, entry.name });
        defer allocator.free(full_path);
        const stat = try std.Io.Dir.cwd().statFile(io, full_path, .{});
        if (std.mem.eql(u8, entry.name, "edge_segment_current")) {
            bytes.current = std.math.add(u64, bytes.current, stat.size) catch return error.RecordTooLarge;
            bytes.current_files = std.math.add(u64, bytes.current_files, 1) catch return error.RecordTooLarge;
        } else if (std.mem.eql(u8, entry.name, "edge_segment.manifest") or std.mem.startsWith(u8, entry.name, "edge_segment.manifest.")) {
            bytes.manifest = std.math.add(u64, bytes.manifest, stat.size) catch return error.RecordTooLarge;
            bytes.manifest_files = std.math.add(u64, bytes.manifest_files, 1) catch return error.RecordTooLarge;
        }
    }
}

test "store dir bytes recursively includes segment subdirectories" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const db_path = try std.fs.path.join(std.testing.allocator, &.{ path_buf[0..root_len], "kg" });
    defer std.testing.allocator.free(db_path);
    const segments_path = try std.fs.path.join(std.testing.allocator, &.{ db_path, "edge_segments", "0001" });
    defer std.testing.allocator.free(segments_path);
    const manifest_path = try std.fs.path.join(std.testing.allocator, &.{ db_path, "manifest.json" });
    defer std.testing.allocator.free(manifest_path);
    const csr_path = try std.fs.path.join(std.testing.allocator, &.{ segments_path, "edge_fwd.csr" });
    defer std.testing.allocator.free(csr_path);

    try std.Io.Dir.cwd().createDirPath(std.testing.io, segments_path);
    try std.Io.Dir.cwd().writeFile(std.testing.io, .{ .sub_path = manifest_path, .data = "12345" });
    try std.Io.Dir.cwd().writeFile(std.testing.io, .{ .sub_path = csr_path, .data = "1234567" });
    try std.testing.expectEqual(@as(u64, 12), try storeDirBytes(std.testing.allocator, std.testing.io, db_path));
}

test "bench edge segments bytes returns edge segment subtree only" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const db_path = try std.fs.path.join(std.testing.allocator, &.{ path_buf[0..root_len], "kg" });
    defer std.testing.allocator.free(db_path);
    const segments_path = try std.fs.path.join(std.testing.allocator, &.{ db_path, "edge_segments", "0001" });
    defer std.testing.allocator.free(segments_path);
    const segment_file_path = try std.fs.path.join(std.testing.allocator, &.{ segments_path, "edge_fwd.csr" });
    defer std.testing.allocator.free(segment_file_path);
    const outside_file_path = try std.fs.path.join(std.testing.allocator, &.{ db_path, "events.bin" });
    defer std.testing.allocator.free(outside_file_path);

    try std.Io.Dir.cwd().createDirPath(std.testing.io, segments_path);
    {
        var file = try std.Io.Dir.cwd().createFile(std.testing.io, segment_file_path, .{});
        defer file.close(std.testing.io);
        try file.writePositionalAll(std.testing.io, "segment-bytes", 0);
    }
    {
        var file = try std.Io.Dir.cwd().createFile(std.testing.io, outside_file_path, .{});
        defer file.close(std.testing.io);
        try file.writePositionalAll(std.testing.io, "outside", 0);
    }

    const bytes = try benchEdgeSegmentBytes(std.testing.allocator, std.testing.io, db_path);
    try std.testing.expectEqual(@as(u64, 13), bytes.total);
    try std.testing.expectEqual(@as(u64, 13), bytes.data);
    try std.testing.expectEqual(@as(u64, 0), bytes.sidecar);
    try std.testing.expectEqual(@as(u64, 1), bytes.files);
    try std.testing.expectEqual(@as(u64, 1), bytes.dirs);
}

test "bench edge segment bytes classify sidecar and control files" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    var path_buf: [std.Io.Dir.max_path_bytes]u8 = undefined;
    const root_len = try tmp.dir.realPath(std.testing.io, &path_buf);
    const db_path = try std.fs.path.join(std.testing.allocator, &.{ path_buf[0..root_len], "kg" });
    defer std.testing.allocator.free(db_path);
    const segments_path = try std.fs.path.join(std.testing.allocator, &.{ db_path, "edge_segments", "0001" });
    defer std.testing.allocator.free(segments_path);
    const fwd_path = try std.fs.path.join(std.testing.allocator, &.{ segments_path, "edge_fwd.csr" });
    defer std.testing.allocator.free(fwd_path);
    const rev_path = try std.fs.path.join(std.testing.allocator, &.{ segments_path, "edge_rev.csr" });
    defer std.testing.allocator.free(rev_path);
    const ids_path = try std.fs.path.join(std.testing.allocator, &.{ segments_path, "edge_ids.idx" });
    defer std.testing.allocator.free(ids_path);
    const other_path = try std.fs.path.join(std.testing.allocator, &.{ segments_path, "notes.bin" });
    defer std.testing.allocator.free(other_path);
    const manifest_path = try std.fs.path.join(std.testing.allocator, &.{ db_path, "edge_segment.manifest.4.abcd" });
    defer std.testing.allocator.free(manifest_path);
    const current_path = try std.fs.path.join(std.testing.allocator, &.{ db_path, "edge_segment_current" });
    defer std.testing.allocator.free(current_path);

    try std.Io.Dir.cwd().createDirPath(std.testing.io, segments_path);
    try std.Io.Dir.cwd().writeFile(std.testing.io, .{ .sub_path = fwd_path, .data = "ffff" });
    try std.Io.Dir.cwd().writeFile(std.testing.io, .{ .sub_path = rev_path, .data = "rrrrr" });
    try std.Io.Dir.cwd().writeFile(std.testing.io, .{ .sub_path = ids_path, .data = "ids" });
    try std.Io.Dir.cwd().writeFile(std.testing.io, .{ .sub_path = other_path, .data = "xx" });
    try std.Io.Dir.cwd().writeFile(std.testing.io, .{ .sub_path = manifest_path, .data = "manifest" });
    try std.Io.Dir.cwd().writeFile(std.testing.io, .{ .sub_path = current_path, .data = "current" });

    const bytes = try benchEdgeSegmentBytes(std.testing.allocator, std.testing.io, db_path);
    try std.testing.expectEqual(@as(u64, 14), bytes.total);
    try std.testing.expectEqual(@as(u64, 9), bytes.data);
    try std.testing.expectEqual(@as(u64, 3), bytes.sidecar);
    try std.testing.expectEqual(@as(u64, 2), bytes.other);
    try std.testing.expectEqual(@as(u64, 8), bytes.manifest);
    try std.testing.expectEqual(@as(u64, 7), bytes.current);
    try std.testing.expectEqual(@as(u64, 15), try bytes.controlBytes());
    try std.testing.expectEqual(@as(u64, 29), try bytes.physicalBytes());
}

