    out.buffer.clearRetainingCapacity();
    try run(&.{ "tinykg", "query", db_path, "MATCH (a:document)-[e:references]->(b:observation) WHERE e.created_by = \"agent\" RETURN b.text LIMIT 5" }, &out, std.testing.allocator, std.testing.io);
