    try std.testing.expect(!benchGeneratedNodeTextIsLong(96, diverse_source));
    try std.testing.expectEqual(@as(usize, 96), try benchExactTextLookupNodeId(97, diverse_source));

    var appended = std.ArrayList(u8).empty;
