    out.buffer.clearRetainingCapacity();
    try run(&.{ "tinykg", "schema-apply", old_db, "--schema", schema_path, "--profile", "agent-dag" }, &out, std.testing.allocator, std.testing.io);
    out.buffer.clearRetainingCapacity();
